(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,54575,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"开发者工具包：24 个替代付费应用程序的免费浏览器工具","description":"使用基于浏览器的免费开发工具格式化、转换、编码和调试数据的实用指南 - 无需安装，无需帐户，无需上传任何内容。","category":"开发者工具","blocks":[{"p":"您每周执行一百次的大多数小工作（重新格式化 API 响应、解码令牌、检查哈希值、缩进 SQL 段）不需要 IDE、付费订阅或团队许可证。他们需要打开一个标签九十秒。\\n\\n下面的集合是二十四个基于浏览器的实用程序，涵盖格式化、转换、编码、散列和调试。它们中的每一个都完全在您的页面中运行：您的数据永远不会发送到服务器，这比开发人员通常承认的更重要，因为您粘贴的有效负载通常是客户的。"},{"h":"基于浏览器的工具可以取代什么，不能取代什么"},{"p":"对边界要现实一些。这些工具取代了一次性、低风险、高频率的琐事。它们不会取代您的语言服务器、调试器、测试套​​件或在真实环境中重复运行所需的任何内容。"},{"l":["**适合：** 读取一次响应、调试单个值、转换文件以进行一次导入、在发货前检查格式。","**不适合：**在每次部署时运行相同的检查，转换数百个文件，任何在 CI 中都必须失败的东西。","**从不：**任何涉及您无法轮换的凭据的事情。粘贴已撤销的令牌，而不是活动令牌。"]},{"p":"话虽如此，保留这些书签的原因是吞吐量。在浏览器选项卡中花费 40 秒的任务永远不会被安排，永远不会被委派，也永远不会成为晚上八点打开 IDE 的理由。"},{"h":"格式化和转换数据"},{"p":"最常见的日常工作是使数据可读。 API 返回单行 blob，同事发送带有被聊天窗口破坏的选项卡的配置文件，或者您将电子表格导出为 JSON，但它返回为一大行。"},{"l":["[[json-formatter|JSON Formatter]] — 缩进、验证和读取有效负载。在调试之前使用它：一半的“API 已损坏”票证实际上是格式错误的 JSON，并带有尾随逗号。","[[json-validator|JSON Validator]] - 当您需要严格的通过/失败答案而不是漂亮的打印时。","[[xml-formatter|XML Formatter]] — 与 SOAP 响应、RSS 提要和 Maven POM 的工作相同，自 2014 年以来就没有人接触过。","[[json-to-yaml|JSON 到 YAML]] 和 [[json-to-csv|JSON 到 CSV]] — 在实际系统实际使用的格式之间移动数据。"]},{"p":"对于一个特定场景，请记住最后一组：客户向您提供电子表格，并希望在他们的 API 中提供该电子表格。直接将 CSV 转换为 JSON 只需两分钟的工作，而不是一下午的脚本编写。"},{"h":"编码和转义"},{"p":"编码错误非常令人烦恼，因为数据看起来不错。值“San José & Sons”以“San Jos%C3%A9 %26 Sons”形式到达，并且由于日志中不可见的原因，您与数据库的比较失败。"},{"l":["[[url-encoder|URL 编码器/解码器]] — 立即确定查询字符串是否是双重编码的。","[[base64-encoder|Base64 编码器/解码器]] — 解码证书片段，或编码小资产以内联在 CSS 中。","[[html-entity-encoder|HTML 实体编码器/解码器]] — 查明页面中的杂散“&”是否来自您的模板或数据。","[[unicode-converter|Unicode 转换器]] — 当“损坏的”字符被证明是以错误编码呈现的合法字符时很有用。","[[number-base-converter|数基转换器]] — 无需计算器应用程序即可检查颜色、权限位掩码或内存地址。"]},{"b":"一个实用的习惯：当一个值出现乱码时，一次解码一层并将每个结果粘贴到空白字段中。如果第一次解码产生可读文本，则问题是上游某处的额外编码。如果它产生 mojibake，那么您遇到的是编码问题而不是转义问题，并且这两个问题需要不同的修复。"},{"h":"标识符、哈希值和令牌"},{"p":"该组是开发人员花费最多时间寻找他们曾经编写并丢失的正确本地脚本的地方。"},{"l":["[[uuid-generator|UUID Generator]] — 为种子数据、固定装置或快速数据库行生成 v4 标识符。","[[md5-generator|MD5 / SHA 哈希生成器]] — 验证下载或确认两个文件实际上应该相同。","[[timestamp-converter|时间戳转换器]] — 整个列表中最常用的工具。当日志行显示 1761000000 时，这可以告诉您事件是在部署期间还是在部署之前发生。"]},{"p":"时间戳转换器之所以能得到它的青睐，有一个特定的原因：纪元号是明确的，同时也是无用的。您确切地知道事情发生的时间，但无法告诉同事。一次转变通常会解决比应有的更激烈的争论。"},{"h":"比较与调试"},{"l":["[[regex-tester|Regex Tester]] — 这里杠杆率最高的项目。看起来正确但安静地不匹配任何内容的正则表达式是开发中最昂贵的错误之一，因为它在没有人阅读的地方安静地失败。","[[html-preview|HTML Preview]] — 迭代标记片段以检查其实际呈现方式。"]},{"p":"根据您实际期望的输入测试您的正则表达式，包括空字符串、Unicode 名称和带有换行符的值。大多数模式在第三种情况下就会崩溃，直到生产数据到达之前没有人注意到。"},{"h":"一个可行的例子：三个工具，一个无聊的事件"},{"p":"这是说服我为所有这些添加书签的序列。一位客户报告说，他们周二提交的记录在周四的报告中丢失了。"},{"l":["**1.转换时间戳。** 报告作业将记录的创建时间记录为纪元值。 [[timestamp-converter|Timestamp Converter]] 显示记录是在当地时间星期二晚上 11 点创建的 - 作业的时区假设是问题所在，而不是记录。","**2.格式化有效负载。**通过 [[json-formatter|JSON Formatter]] 获取存储的 JSON，发现该记录是用空日期字段写入的，因为客户端两次调用同一端点（相隔 200 毫秒），并且第二次写入获胜。","**3.比较有效负载。** 两条记录都带有相同的 API 密钥和相同的客户端时间戳，这指向重试而不是两个单独的客户。"]},{"p":"总用时：四分钟。之前的调查尝试在一个日志平台中寻找相同的根本原因，花了一个下午的时间并得出了错误的结论。"},{"h":"隐私：为什么本地运行是实际功能"},{"p":"该库中的每个工具都会在您自己的浏览器中处理您的输入。没有上传任何内容，这意味着没有保留问题，没有处理器协议，也没有关于三分钟前粘贴的生产负载的令人不舒服的对话。\\n\\n这就是比起托管的“pastebin API”或要求您注册的在线服务更喜欢这些工具的原因。这也意味着他们可以在飞机上、地下室或公司 VPN 决定阻止另一个域时继续工作。"},{"p":"需要明确说明的一个警告是：只有当页面本身是您认为的代码时，具有离线功能的页面才是私有的。在共享计算机上，使用私有窗口并在完成后将其关闭，尤其是在您一直在解码令牌的情况下。"},{"h":"围绕它们构建工作流程"},{"p":"这些工具单独来看都是微不足道的。价值在于立即获取而不是“稍后再获取”的习惯，因为稍后是指当您编写一次性脚本，或打开 IDE，或决定根本不值得检查时。"},{"l":["为集合（而不是单个 URL）添加书签，并将其放入浏览器的工具栏中。","当出现问题时，请在形成理论之前进行检查。花费十五秒；消灭所有类型的错误结论。","当你对同一件事检查两次时，那就是自动化它的信号——但不要因为怀疑而自动化。","不要粘贴制作机密。旋转任何你不确定的东西。"]},{"h":"常见问题"},{"p":"**这些工具免费吗？** 是的，完全免费，没有帐户，也没有使用限制。没有任何付费等级会阻碍任何基本功能。\\n\\n**它们可以离线工作吗？** 页面加载后，是的 - 一切都在您的浏览器中运行。重新加载需要连接。\\n\\n**我可以将它们用于商业工作吗？** 可以。输出是您的，没有归属要求。\\n\\n**有API吗？** 没有，这是故意的——价值就是接口。导出输出并按照您喜欢的方式处理它。\\n\\n**为什么不直接安装一个 CLI 工具呢？** 当您需要 3 次时安装一个。前两个使用浏览器选项卡。"}]},"text-tools-for-writers":{"title":"17 个适合作家、学生和营销人员的免费文本工具","description":"使用从不上传文本的免费浏览器工具清理副本、准确计算字数、格式化列表并将粗略的草稿变成可发布的内容。","category":"文本工具","blocks":[{"p":"工作写作涉及大量与写作无关的机械苦差事：从粘贴的段落中去除多余的空格、检查字数限制、删除重复的名称列表、将某些内容转换为 URL slug。\\n\\n这十七个工具就是用于这部分工作的。它们都在浏览器本地运行，这不是一个小细节——您粘贴的草稿通常是未发布的，您正在排序的列表通常是某人的个人数据。"},{"h":"衡量你所写的内容"},{"p":"字数统计听起来已经解决了，直到客户要求正好 800 个字，而您的编辑器说 820，或者表单拒绝您的 1,995 个字符的文本，并且没有解释换行符的位置。"},{"l":["[[word-counter|字计数器]] — 标准度量。粘贴、阅读、调整。","[[letter-counter|Letter Counter]] — 计算字符和字母频率。当您调试为什么某个段落感觉不对时很有用：它通常是重复的字母模式，而不是梦想。"]},{"p":"关于“一个单词”含义的注释：不同的计数器在连字符、数字和 URL 方面存在分歧。如果确切的数字很重要，请使用检查您工作的人员使用的同一柜台，并提前达成一致。这是一个真正常见的小而无意义的争论的根源。"},{"h":"清理你没有写的副本"},{"p":"您收到的大多数文本都略有损坏：复制粘贴产生的双空格、杂散的制表符、匆忙打字造成的大小写不一致。手动修复它速度慢且容易出错。"},{"l":["[[text-trimmer|文本修剪器]] — 立即删除每一行的前导和尾随空格。这比此列表中的其他任何内容修复了更多的“格式看起来损坏”报告。","[[text-case-converter|文本大小写转换器]] — 在块中的句子大小写、标题大小写、大小写之间切换。也是撤消意外的大写锁定段落的最快方法。","[[text-to-slug|Text to Slug]] — 将标题变成干净的 URL slug。粘贴你的标题，得到标题，完成。"]},{"p":"slug 生成器除了 URL 之外还有一个用途：它是一种快速生成可读文件名或锚点的方法，人们一眼就能解析，这比“final_final_v3”要好。"},{"h":"使用列表"},{"p":"列表、库存、邮件合并、标签清理、调查回复、电子表格列——在某些时候，一切都变成了列表，每个列表都需要排序、去重或随机化。"},{"l":["[[duplicate-line-remover|重复行删除器]] — 比较两个列表，或清理一个列表。输出会告诉您删除了多少重复项，这在您报告结果时非常有用。","[[list-sorter|List Sorter]] — 与结构化列表输入相同的工作。","[[list-randomizer|List Randomizer]] — 随机排列抽签顺序、测验序列或围墙入围名单，这样就不会有人怀疑存在偏袒行为。","[[line-number-adder|行号添加器]] — 编号行，供在票证或代码审查评论中参考。"]},{"b":"这里的经典陷阱是一个看起来经过重复数据删除但实际上并非如此的列表：“Apple”、“apple”和“Apple.”对于计算机来说是三个不同的行。在重复数据删除之前，请修剪空格并去除尾随标点符号，否则您将不会合并任何内容并得出数据是干净的结论。"},{"h":"预览和格式化"},{"p":"Markdown 赢了，但情况并不统一。你的工具一半会渲染它，一半不会，而没有渲染的一半通常是高级人员必须粘贴到的工具。"},{"l":["[[markdown-preview|Markdown Preview]] — 实时渲染，因此您可以在表格或嵌套列表到达客户端之前检查其实际外观。","[[text-repeater|Text Repeater]] — 重复字符串 N 次。对于生成填充、测试数据或偶尔在文档中表达观点很有用。"]},{"p":"Markdown 预览是整个集合中安静地节省最多时间的工具，因为渲染文档中的损坏表格比原始文本中的损坏表格更明显，也更令人尴尬。"},{"h":"其余的，以及何时接触它们"},{"l":["[[random-string|随机字符串生成器]] — 生成可读的随机数、占位符 ID 或短代码。比手工发明一些东西更好，因为你不会意外地重复使用它。","[[摩尔斯电码|摩尔斯电码翻译器]] — 真正有趣，偶尔对主题项目或谜题有用。"]},{"p":"这些是频率较低的工具，但它们无需花费任何费用即可添加书签，并且它们解决了“我现在需要一个看起来随机的值，但我不相信自己能够编出一个值”的具体问题。"},{"h":"真实的编辑过程"},{"p":"当草稿从其他人处到达并需要以您的名义发出时，可以使用以下顺序。"},{"l":["**1.修剪。** 首先通过 [[text-trimmer|Text Trimmer]] 运行整个文档。空白损坏隐藏在您永远看不到的段落内。","**2.干净的大小写。** 仅对标题使用 [[text-case-converter|文本大小写转换器]]。切勿将大小写转换应用于完整的草稿 - 它会破坏专有名词。","**3.测量。** 在书​​写之前用 [[字计数器|字计数器]] 检查长度，这样您就知道该作品的形状。","**4.预览。** 如果包含 Markdown，则使用 [[markdown-preview|Markdown Preview]] 进行渲染。","**5. Slug.** 最后从最终标题生成 URL slug，使用 [[text-to-slug|Text to Slug]] — 之后更改标题会破坏该 slug。"]},{"p":"整个过程需要几分钟，并且消除了文档技术上正确但明显错误的错误类别。"},{"h":"作家关于隐私的问题"},{"p":"**我未发布的文本会离开我的计算机吗？** 不会。这些工具会在您的浏览器中处理文本，并且不会存储或传输任何内容。\\n\\n**有长度限制吗？** 没有服务器端限制，因为没有服务器调用。极大的输入受到您自己设备内存的限制。\\n\\n**我可以将输出用于商业用途吗？** 可以，自由使用，无需归属。\\n\\n**他们可以在电话上工作吗？** 是的。布局会调整，并且运行相同的代码。"},{"h":"这些工具不能为您做什么"},{"p":"值得直言其局限性，因为机械化错误事物的工具只会产生更快的错误。\\n\\n这些实用程序都无法告诉您句子是否清晰，主张是否有来源，或者语气是否适合听众。他们计算字符数；他们不评判散文。在该页面上的每个指标上得分都很高的文本仍然无法阅读。\\n\\n他们也不编辑。当您发现自己大规模地手动重写单个子句时，文本工具已经无法满足您的需求，您需要一个合适的编辑器、一个用正则表达式查找和替换的工具（[[regex-tester|Regex Tester]] 确实非常适合排练）或一个脚本。使用浏览器作为机械层，并对其之上的所有内容保留自己的判断。"},{"p":"他们不会做的另一件事是修复不良来源。如果您的电子表格充满了不一致的命名 - “Dr”、“DR”、“Dr.”全部集中在一列中 - 一个工具会对您忠实提供的内容进行排序和删除重复内容，并且您仍然会在应该有一个的地方保留三个条目。清理数据是一个决定，而不是一个机械步骤。首先确定规范形式，然后应用它，然后检查。"},{"h":"保持工作清单可用"},{"p":"如果你维护一个潜在客户、链接、参考文献或术语的列表，它就会悄然退化。失败模式总是相同的：看起来相同的条目实际上并不相同，并且一次合并不会删除任何内容。\\n\\n有效的维护过程很无聊：修剪空白、标准化大写、去掉尾随标点符号，然后消除重复。按照这个顺序——去重后的修剪会丢失条目。每月在活动列表上执行一次此操作会将两小时无法恢复的混乱变成十分钟的苦差事。\\n\\n当两个列表需要协调时（例如，登记列表与出勤列表）首先使用 [[list-sorter|List Sorter]] 对两个列表进行排序，使它们对齐，然后通过肉眼进行比较。在比较之前对双方进行排序是两分钟检查和二十分钟狩猎之间的区别。"},{"h":"外卖"},{"p":"这些工具都不聪明。这就是要点：他们删除了机械性的百分之五的非写作内容，因此剩下的百分之九十五实际上是关于句子的。为您每月使用的内容添加书签，忽略其余内容，并停止手动修复空白。"}]},"calculators-and-converters-guide":{"title":"18 个免费计算器和转换器，适合您实际处理的数字","description":"百分比、折扣、小费、贷款、日期、BMI 和单位换算 — 免费的浏览器计算器可以显示其推理并且从不保存您的输入。","category":"计算器","blocks":[{"p":"每个人都需要分摊账单，弄清楚折扣是否是真正的折扣，并且不假思索地转换温度或文件大小。每个人也至少有一次在公共场合犯过这样的错误。\\n\\n这是十八个计算器和转换器的集合，涵盖金钱、日期、健康以及工作和旅行中出现的单位转换。所有这些都在浏览器中运行：不会保存任何内容，因此您输入的数字与任何人无关，除了您自己。"},{"h":"金钱计算"},{"p":"现实世界中最常见的数学是某物的百分比。销售税、小费、折扣、佣金、增长率。公式很简单，但人们犯错的原因几乎总是相同的：他们将百分比应用于错误的基数。"},{"l":["[[discount-calculator|折扣计算器]] — 计算出最终价格，更重要的是，计算出您节省了多少钱。对于发现“50% 折扣”（实际上是提高标价后的 20%）非常有用。","[[小费计算器|小费计算器]] — 拆分账单，选择百分比，如果您愿意的话，可以按人四舍五入。","[[loan-calculator|贷款计算器]] — 每月还款额和总利息，这个数字实际上决定了贷款是否负担得起。"]},{"b":"关于折扣：先打 20% 折扣，再打 20% 折扣，这不是 40% 折扣，而是 36% 折扣。在减少的基数上按顺序百分比复合。此列表中的任何计算器都会在大约两秒钟内确认它，这是本文中最有用的算术事实。"},{"p":"贷款计算器值得特别说明。重要的数字不是每月还款额，而是贷款期限内支付的总利息，因为这是借款的实际成本。每月还款额相同但期限不同的两笔贷款的总利息可能相差数万。"},{"h":"日期和倒计时"},{"p":"日期算术是大多数人默默犯错的地方，因为人类的月份有不同的长度，并且答案会根据您的意思是“日历月”还是“30 天”而变化。"},{"l":["[[date-difference|日期差异计算器]] — 两个日期之间的天数（以及总月数、年数）。","[[days-until|Days Until Calculator]] — 特定日期的倒计时，工作日数通常是人们真正想要的。","[[年龄计算器|年龄计算器]] — 以年和日为单位的准确年龄，加上下一个生日。","[[timestamp-converter|时间戳转换器]] — 将 Unix 时间戳转换为真实日期，如果您接触日志、数据库或 API 响应，这一点很重要。"]},{"p":"令人困惑的区别是：3 月 1 日和 4 月 1 日之间的天数是 31，但“月”数是 1。如果您正在计算通知期或订阅期限，请以书面形式说明您所指的单位。"},{"h":"老实说，健康数字"},{"l":["[[bmi-计算器|BMI 计算器]] — 体重指数与标准类别，以及以下注意事项。"]},{"p":"BMI 是人口水平的筛查统计数据。它没有说明肌肉质量、身体成分或任何个人的健康状况，而且它并不能很好地代表运动员、老年人和不同种族群体的健康状况。将其用作多个数据点中的一个，或者作为跟踪随时间变化的一种方式，而不是作为结论。如果您正在做出影响您健康的决定，那么正确的工具是临床医生，而不是浏览器选项卡。"},{"h":"单位换算：日常单位换算"},{"p":"单位换算分为两种：必须精确的单位换算和粗略的单位换算。这些工具可以同时处理这两种情况，而工作就是记住哪个是哪个。"},{"l":["[[长度转换器|长度转换器]] — 公制到英制的转换：毫米、厘米、米、公里、英寸、英尺、码、英里。","[[重量转换器|重量转换器]] — 克、千克、盎司、磅、吨。在食谱或运输标签之前要检查的一个。","[[温度转换器|温度转换器]] — 摄氏度、华氏度、开尔文。因为 -10°C 不是 14°F，而且公式也不是乘法。","[[速度转换器|速度转换器]] — km/h、mph、m/s、knots。对于外国速度限制或工程规范很有用。","[[面积转换器|面积转换器]] — 平方米、平方英尺、英亩、公顷。这是人们在购买或租赁房产时最糟糕的估计。","[[volume-converter|体积转换器]] — 升、毫升、加仑、杯、立方米。","[[time-converter|时间转换器]] — 秒、分钟、小时、天、周。"]},{"b":"两个值得了解的转换陷阱：上面的数据存储（营销人员出售 10^3，操作系统报告 2^10）和燃油经济性 — 一辆报价为 40 英里/加仑（英制）的汽车比 40 英里/加仑更接近 33 英里/加仑（美国），因为英制加仑更大。如果第二个错误的话，租车的效率就会显得不切实际。"},{"h":"您不会期望需要的两个"},{"l":["[[随机数|随机数生成器]] — 在一定范围内抽奖，用于抽奖、分组或快速 A/B 分割。有用正是因为它消除了您操纵它的怀疑。","[[dice-roller|Dice Roller]] — 从硬币翻转到二十面骰子的任何骰子，适用于棋盘游戏或桌面游戏，其中真正的骰子最后一次从桌子上滚落。"]},{"h":"正确使用计算器"},{"p":"只有当您知道要询问的数字时，计算器才会有帮助。三个习惯会产生影响。"},{"l":["**第一轮，计算第二轮。**如果精确的数字不会改变您的决定，请使用第一轮。您可以在头脑中检查整数的百分比，从而捕获输入错误。","**健全性检查大小。** 在相信结果之前，询问它是否应该大于或小于输入，以及大致多少。除了这一次之外，大多数算术错误在每一次检查中都幸免于难。","**拍摄输入，而不是输出。** 当您稍后重新运行计算时，重要的是了解您的假设，而不是您的结论。"]},{"h":"人们实际问的问题"},{"p":"**我的号码是否存储在任何地方？** 不。计算在您的浏览器中进行，不会传输或保留任何内容。\\n\\n**这些可以在手机上使用吗？** 可以，并且计算器是专为单手使用而设计的。\\n\\n**您使用哪种转换标准进行数据存储？** 默认情况下为十进制（1 KB = 1000 字节），因为这就是存储的销售方式。操作系统报告二进制，这就是驱动器看起来缩小的原因 - 该工具解释了差异，而不是默默地选择一边。\\n\\n**我可以将它们嵌入到我自己的网站上吗？** 不可以。请为它们添加书签；其成本为零，并且准确性问题由您自己承担。"},{"h":"百分比：四个重要的错误"},{"p":"一个人在日常生活中所犯的几乎每一个百分比错误都是同样的四个错误之一。命名它们使它们可以避免。"},{"l":["**错误的基础。** “上涨 10%，然后下降 10%，让你回到起点”是错误的，因为两者适用于不同的基础。 100的百分之十是10； 90的百分之十是9。","**百分比的百分比。** 叠加两个折扣会将它们相乘（0.8 × 0.8 = 0.64，因此 36% 折扣），但不会将它们相加。","**百分比与百分点。** 从 4% 到 6% 的比率上升了 2 个百分点，但相对而言上升了 50%。政治和医学都充满了这种混乱，而且这并不总是偶然的。","**舍入太早。** 在应用百分比之前舍入中间步骤会增加误差。保持完全精确直到最终数字，并在计算器上而不是在头脑中完成最后一步。"]},{"p":"如果您只从整个部分中采取一个习惯，请采取这个习惯：在向任何人引用百分比之前，重申它是*的百分比。关于数字的争论有一半实际上是关于分母的争论。"},{"h":"知道何时停止计算"},{"p":"到了某个点，精度就不再有用了。每月还款额精确到小数点后两位是有意义的。将预计的总成本精确到小数点后八位是避免做出实际决定的一种方式，实际决定是贷款是否符合您在没有压力的情况下可以承受的范围。\\n\\n有用的测试是敏感性问题：如果输入变化 10%，决策是否会改变？如果不是，请停止完善它，并将额外的时间用于确实改变答案的变量 - 通常是术语而不是费率，或者标价而不是折扣。"},{"p":"有一个界限值得明确说明：这些计算器是算术，而不是建议。储蓄目标、退休日期和债务偿还计划都是关于风险、行为和时间的决定，浏览器选项卡无法权衡其中任何一个。只有当你决定了你的假设后，它才能告诉你这些数字意味着什么。这种区别就是计算器有用和负责任之间的区别。"},{"h":"单行版本"},{"p":"正确地为金钱和日期计算器添加书签，将体重指数视为一个信号而不是一项判决，记住堆叠百分比会相乘，并在数字进入任何合同时检查单位转换。这几乎涵盖了所有内容。"}]},"image-and-design-tools":{"title":"14 个可在浏览器中运行的免费图像和设计工具","description":"压缩、调整大小和准备图像，并生成 CSS 效果、调色板、对比度检查和网站图标，无需安装 Photoshop 或设计套件。","category":"设计工具","blocks":[{"p":"图像工作有一个特定的问题：工作通常很小，但提供的工具却非常多。您需要从英雄图像中删除 400 KB，或者获得设计师提到的十六进制值，或者生成一个尚未制作的图标。这不需要订阅。\\n\\n下面的 14 个工具涵盖了准备图像、处理颜色、生成 CSS 效果以及遗漏的小型制作资产。每个都在本地运行，这对于图像比对于文本更重要：您刚刚压缩的照片通常是您尚未发布的照片​​。"},{"h":"准备网络图像"},{"p":"大多数图像问题实际上都是重量问题。 A page that feels slow is usually carrying images that are larger than their display size, in the wrong format, at a quality setting nobody ever questioned."},{"l":["[[image-compressor|图像压缩器]] — 减小文件大小，同时保持图像视觉完整。在将任何内容上传到有大小限制的表单之前运行它。","[[image-resizer|Image Resizer]] — 设置您需要的实际像素尺寸。这是更大的胜利：以 800 像素显示的 4000 像素图像携带的数据是其所需数据的五倍。","[[image-to-base64|Image to Base64]] — 将小图像转换为数据 URI，以便内联到 CSS、HTML 或电子邮件模板中。"]},{"b":"顺序很重要。首先调整大小，其次压缩。 Compressing a 4000px image produces a much heavier file than resizing to 800px and then compressing at the same quality, because compressors spend their effort on pixels that were going to be thrown away anyway."},{"p":"你应该压缩多少？诚实的答案是：直到看起来不对劲，然后后退一步。对于摄影英雄图像，70% 到 80% 的质量通常与正常观看尺寸下的原始图像无法区分。对于徽标、屏幕截图或任何具有平坦颜色和硬边的内容，请使用 PNG 并进行更严格的压缩 - 这些增益更多，损失更少。"},{"p":"一个实用的经验法则：对于英雄图像来说，任何低于 200 KB 的内容都可以，对于缩略图来说，低于 80 KB 的内容都可以，如果不能低于 300 KB，则可能存在尺寸问题，而不是质量问题。"},{"h":"Base64：何时内联是正确的调用"},{"p":"将图像转换为 Base64 数据 URI 会删除 HTTP 请求，这听起来像是一个纯粹的胜利。通常情况并非如此。编码后的字符串大约比二进制文件大三分之一，它无法单独缓存，并且会使您的 CSS 或 HTML 膨胀。\\n\\n仅当图像很小（低于几千字节）且仅使用一次且至关重要时才内联。单个电子邮件模板中的小图标是典型的案例。对于跨页面重复或大于几千字节的任何内容，将其作为文件提供并让浏览器缓存它。"},{"h":"水印：什么是真正可去除的"},{"l":[]},{"p":"清楚这是做什么的。它消除或遮盖了可见标记。它无法重建底层像素——被覆盖的信息已经消失，并且没有过滤器将其重新发明出来。结果范围从当标记位于普通背景上时不可见到当标记位于细节上时出现明显的污点。\\n\\n还有一件事值得明确地说：删除别人的水印并发布结果在大多数司法管辖区都是版权问题，并且无论您是否会被抓住，都属于许可违规行为。此工具适用于从您自己的图像或您已许可的库存中删除标记。"},{"h":"颜色：转换、检查、选择"},{"p":"颜色是小错误变得非常明显的地方。无法访问的对比度、实际上是 HSL 三元组的十六进制值、在显示器上看起来连贯但在投影仪上看起来浑浊的调色板。"},{"l":["[[color-converter|颜色转换器]] — 在 HEX、RGB 和 HSL 之间移动。 HSL 值得学习阅读，因为色调 210、饱和度 40%、亮度 50% 比十六进制值更容易手动调整。","[[contrast-checker|对比度检查器]] — 根据 WCAG 阈值测试文本的背景。这是本文中最有用的工具，因为它捕获了真正的合规性问题，而不是品味问题。","[[color-palette|调色板生成器]] — 当您从品牌颜色开始并需要其余比例时，生成一个连贯的集合。"]},{"b":"相比之下：WCAG AA 要求普通正文文本为 4.5 比 1，大文本为 3 比 1。如果您在按钮的两种品牌颜色之间进行选择，则易于访问的颜色通常不是设计师喜欢的颜色。先检查，再用数据论证。"},{"p":"关于颜色工具的一个警告：它们都假设您的显示器已校准并且查看页面的人有眼睛。这两种假设都不安全。这就是比起主观组合更喜欢对比检查组合的原因。"},{"h":"无需打开设计工具的 CSS 效果"},{"p":"手动编写渐变或分层阴影确实是一项令人不快的任务。语法很繁琐，你看不到你正在生成什么，好阴影和坏阴影之间的区别就是几个像素的模糊。"},{"l":["[[gradient-generator|CSS 渐变生成器]] — 构建线性和径向渐变并直接复制 CSS。","[[box-shadow-generator|Box Shadow Generator]] — 分层多个阴影，这就是区分细微高程和大幅下降的原因。","[[border-radius-generator|边框半径生成器]] — 获取使形状看起来有意为之的不对称半径。","[[text-shadow-generator|文本阴影生成器]] — 很少用。大多数文本阴影太强；这可以让您调整偏移和模糊，直到它消失。"]},{"p":"解决这四个问题的秘诀就是克制。两个阴影——一个紧密的深色阴影和一个宽阔的柔和阴影——被解读为物理高度。一个影子读起来像是十五年前的网站。生成、复制、然后删除，直到您无法辨别它的存在。"},{"h":"每个人都忘记的生产资产"},{"l":["[[favicon-generator|Favicon Generator]] — 生成网站实际需要的小图标集。之所以将其列入列表，是因为网站图标是最有可能完全丢失的资产，而丢失的图标会显示通用的浏览器页面图标，使已完成的网站看起来未完成。","[[emoji-picker|表情符号选择器]] — 浏览、搜索和复制表情符号，无需通过操作系统选择器进行搜索。当您编写需要一个特定符号的副本时，它确实很有用。"]},{"h":"一个有效的例子：运送英雄部分"},{"p":"这是整个集群在做一项真正的工作。一个页面需要一个带有背景图像、标题和按钮的英雄，但目前还没有构建这些内容。"},{"l":["**1.保留空间。** 在布局中为图像槽指定固定高度，以便页面在第一次渲染时具有正确的形状，而不是在真实图像落地时跳跃。","**2.调整大小并压缩。** 当真实照片到达时，以 1600 像素宽运行 [[image-resizer|Image Resizer]]，然后以 75% 的宽度运行 [[image-compressor|Image Compressor]]。这是您可以发送的文件。","**3.对文本进行对比度检查。** 照片上的标题是典型的对比度失败。使用 [[contrast-checker|Contrast Checker]] 选择深色叠加强度或通过 AA 的浅色文本颜色。","**4.构建按钮。** [[box-shadow-generator|Box Shadow Generator]] 提供高度，[[color-converter|Color Converter]] 将品牌颜色转换为 CSS 所需的格式。","**5. Ship.** 从 [[favicon-generator|Favicon Generator]] 添加一个 favicon，这样该选项卡看起来就不会被遗弃，该部分就完成了。"]},{"p":"五种工具，没有设计套件，每个输出都是一个可以直接粘贴到代码中的值。"},{"h":"常见问题"},{"p":"**我的图像上传到任何地方了吗？** 没有。压缩、调整大小和 Base64 转换都在您的浏览器中进行，这就是没有文件大小限制和上传队列的原因。\\n\\n**压缩图像会降低质量吗？** 根据定义，总是如此。问题是它是否可见。在 70% 到 80% 的质量和正确的尺寸下，通常情况并非如此。\\n\\n**为什么调整大小后的图像看起来仍然很大？** 十有八九你在调整大小之前进行了压缩，或者当照片保存为 JPEG 更好时，你却保存为 PNG。\\n\\n**我可以将它们用于客户工作吗？** 可以，没有归属权，也没有商业限制。\\n\\n**它们可以在手机上使用吗？** 可以，但在手机上调整大照片的大小和压缩取决于设备的内存而不是服务器。"},{"h":"单行版本"},{"p":"在压缩之前调整大小，在争论颜色之前检查对比度，保持阴影微妙，并且永远不要忘记网站图标。无论如何，这就是设计套件为您做的大部分事情。"}]},"math-tools-for-real-numbers":{"title":"6 个免费的数学工具，用于处理不正常的数字","description":"科学记数法、小数转换为分数、质数检查、阶乘和 GCF/LCM — 免费的浏览器工具，用于处理容易出错的数字工作。","category":"数学工具","blocks":[{"p":"你在计算机上实际需要的数学并不是你考试时要考的数学。它是：这个数字是否采用系统期望的格式，这个分数是否简化，这个数字增长的速度有多快，以及为什么计算器和电子表格不一致。\\n\\n这六种工具涵盖了该领域。它们在本地运行，这对于算术来说意味着一个值得一提的具体好处：您输入的数字不会发送到任何地方，因此您可以毫不犹豫地检查涉及工资、余额或客户数据的计算。"},{"h":"将数字转化为机器接受的形式"},{"p":"计算机将十进制分数存储为二进制分数。 0.1 不能完全用二进制表示 - 最接近的双精度值是 0.1000000000000000055511151231257827。添加 0.1 + 0.2，您将得到 0.30000000000000004，默认情况下打印为 0.3，并悄悄地破坏了相等性检查。"},{"l":["[[科学记数法|科学记数法转换器]] — 在标准形式和科学形式之间转换，这是大多数日志、电子表格和 API 实际存储大小数字的方式。","[[decimal-fraction|小数转分数]] — 将小数转换为精确分数。这是上述问题的解决方案：精确分数算术中的 0.1 + 0.2 是 3/10，而不是近似值。"]},{"b":"如果您曾经见过总计错误 0.0000000000000004，这就是原因。在金融代码中，标准答案是使用整数美分或十进制库，而不是浮点数。如果您曾经见过电子表格与脚本的差异只有零头，那么这就是同一个错误，但戴着不同的帽子。"},{"p":"科学记数法值得熟练掌握，因为它是阅读日志行和眯着眼睛看它之间的区别。 6.022e23、1.6e-19 和 3e8 是阿伏伽德罗数、基本电荷和光速。如果这些看起来像噪音而不是数字，则通过该工具转换一些可以永久修复它。"},{"h":"素数以及为什么有人关心"},{"l":["[[prime-checker|素数检查器]] — 测试一个数是否是素数，如果不是，则查看它的因式分解。","[[gcf-calculator|GCF LCM 计算器]] — 最大公因数和最小公倍数。"]},{"p":"素数不是学校练习。您建立的每个 HTTPS 连接的安全性取决于这样一个事实：将两个大素数相乘很容易，而将结果因式分解却很困难。这种不对称性就是 RSA 的全部基础。\\n\\n对于日常用途，素数检查主要与分数有关。化简分数意味着将顶部和底部除以它们的最大公因数，如果不进行因式分解，你就无法找到它。这就是为什么这两个工具属于一起的原因：检查因素，然后一步获得 GCF 和 LCM。"},{"p":"LCM 一半是人们会忘记的一个，它解决了日程安排问题：每 18 天和每 12 天重复的两个事件每 36 天重合一次。相同的算术，不同的应用。"},{"h":"阶乘及其爆炸速度"},{"l":["[[阶乘计算器|阶乘计算器]] — n！对于答案仍然有意义的值。"]},{"p":"阶乘的增长速度几乎比你在办公桌上遇到的任何东西都快。 10！约为360万。 20！约为 2.4 千万亿——远远大于地球上沙粒的数量。 52！，洗牌方式的数量，大约是 8 后面跟着 67 个数字。\\n\\n实际结果是，枚举所有排列的程序在 5 项时表现良好，在 8 项时还可以接受，在 12 项时则永久卡住。如果一项任务感觉永远不会完成，而您正在循环排列，那么几乎可以肯定这就是原因。这也是反对大多数蛮力方法的论据，以算术而不是意见的形式表述。"},{"h":"罗马数字，以及它们的奇怪之处"},{"l":["[[roman-numerals|罗马数字转换器]] — 罗马数字之间的转换。"]},{"p":"罗马数字值得理解而不仅仅是转换，因为该系统揭示了一些有关位置表示法的信息。没有零，也没有位值：XI 表示十一，无论它代表十一根棍子还是一万一千。这就是为什么罗马数字的算术确实很困难，也是为什么这个系统存在了几个世纪主要是为了计数和约会而不是计算。\\n\\n减法规则是人们犯错的部分。 IV是四，不是VI； IX 是九。时钟是一个著名的例外——大本钟使用 IIII 而不是 IV，历史学家至今仍在争论的原因。在任何情况下，转换而不是派生都是正确的选择。"},{"h":"一个有效的例子：手动检查分数"},{"p":"一份食谱需要 0.375 杯和一个以克为单位的秤，一份报告引用的比率为 0.625，两者看起来都像是某人匆忙输入的数字。"},{"l":["**1.找到精确的分数。** 通过 [[decimal-fraction|小数化分数]] 工具运行 0.375：3/8。运行 0.625：5/8。两者都不需要你没有的计算器习惯。","**2.简化比率。** 要表达 3/8 与 5/8，您需要 3 和 5 的 GCF。 [[gcf-calculator|GCF LCM Calculator]] 给出 1，因此比率是 3:5，已经是最简单的了。","**3.检查阶乘声明。** 如果有人告诉您 9 个订单的队列有 362,880 个排列，[[阶乘计算器|阶乘计算器]] 会确认 9！正是如此。现在您知道构建时间估计是否合理。","**4.标准化任何大的东西。** 根据[[科学计数法|科学计数法转换器]]，报告 1.5e9 纳秒的服务器是 1.5 秒——这是延迟问题和舍入伪影之间的区别。"]},{"h":"这些工具故意不做什么"},{"p":"他们不表现出工作，也不教导。如果你需要理解为什么一个公式是正确的，那么计算器是错误的工具——它给出的答案没有原因，这就是人们最终只能计算而无法推理的原因。\\n\\n他们也不做任意精度。阶乘和大因式分解将失去准确性，超过答案仍然有用的程度，并且浏览器选项卡不是计算机代数系统。对于正确性真正重要的任何事情（工程、金融、密码学），请使用具有精确算术的适当库，而不是网页。"},{"h":"检查自己的算术"},{"p":"最有价值的数学习惯不是速度，而是估计。在相信任何结果之前，先问问它的数量级是否正确：比输入大还是小，以及大致是多少。除了这一次之外，大多数算术错误在其他所有检查中都幸免于难。\\n\\n首先四舍五入使得估算变得自由。将 0.375 舍入到 0.4，将 5/8 舍入到 0.6，比率显然约为 2:3 — 足够接近 3:5，足以确认您准确计算的分数。如果确切的答案和估计值不一致，那么您发现的是输入错误而不是舍入问题，而且您会在几秒钟内找到它。\\n\\n这也是为什么计算器不能代替思考你所问的问题的原因。工具会完美地计算出错误的数量，唯一的防御措施是知道答案应该是什么样的。"},{"h":"常见问题"},{"p":"**我的输入发送到任何地方了吗？** 不。所有这些都在您的浏览器本地运行。\\n\\n**为什么 0.1 加 0.2 不等于 0.3？** 因为 0.1 和 0.2 都不能用二进制浮点数精确表示。总和为 0.30000000000000004，这是最接近 0.3 的两倍。\\n\\n**这些可以处理多大的阶乘？** 在超出双精度范围之前最多可达 170。过了这个时间，答案就会以科学计数法显示，然后就不再有意义。\\n\\n**我可以在代码中使用输出吗？** 可以。特别是对于小数到分数的结果，请对分子和分母使用整数运算，而不是转换回小数。"},{"h":"单行版本"},{"p":"当涉及到金钱时，请使用精确的分数，请记住，阶乘的爆炸速度比您预期的要快，并且质因数分解既是安全基础，也是分数简化技巧。"}]},"everyday-utility-tools":{"title":"13 个免费的日常实用工具：密码、二维码、计时器和文本编码","description":"生成密码、构建二维码、运行计时器和时钟以及解码二进制、十六进制和密文——所有这些都可以使用不上传任何内容的免费浏览器工具完成。","category":"实用工具","blocks":[{"p":"最后一组是垃圾抽屉。密码、二维码、秒表、世界时钟、抛硬币以及四种将文本转换为自身其他表示形式的工具。单独来看是微不足道的，集合起来就是你在尴尬时刻需要的东西。\\n\\n总而言之，所有 13 个都在本地运行。对于一个密码生成器来说，这并不是一个很好的东西——这就是该工具值得信任的全部原因。"},{"h":"密码：真正重要的部分"},{"l":["[[password-generator|密码生成器]] — 生成任意长度和字符集的强随机密码。","[[password-strength|密码强度检查器]] — 估计密码在本地不易被猜测的程度。"]},{"b":"关于密码强度的一个最重要的事实是：**长度胜过复杂性，而重复使用则胜过危险。** 由不相关的单词组成的 16 个字符的密码比 10 个字符的乱七八糟的符号更强大且更容易输入。与此同时，在一次泄露中出现的一个重复使用的密码会立即删除它所触及的每个帐户。整个工作就是为每个站点生成一个独特的长密码。"},{"p":"如何估计力量也很重要。大多数检查器都会近似搜索空间的大小，这是一个合理的代理，但不是事实：“CorrectHorseBatteryStaple”在熵方面得分很高，而“P@ssw0rd1！”在字符多样性方面得分很高，但在实践中却很糟糕，因为它出现在地球上每个破解单词表中。\\n\\n使用生成器来处理您关心的任何事情，如果您必须记住密码，请使用由四个或五个不相关单词组成的密码。这就是记忆力和强度实际上重叠的具体情况。"},{"h":"QR 码：放入什么内容"},{"l":["[[qr-code-generator|QR 代码生成器]] — 生成 URL、文本、Wi-Fi 详细信息或联系信息的 QR 代码。"]},{"p":"QR 码是一种输出质量完全由一个决定决定的工具：您输入的数据量。短 URL 编码为易于扫描的小代码。一段带有标点符号的文本在小尺寸下编码成密集且不可靠的内容。\\n\\n两条实用规则。首先，在打印 200 条代码之前，始终按照实际打印的尺寸测试扫描代码。其次，Wi-Fi 和纯 URL 代码在不同手机上的行为有所不同 - 如果代码面向混合受众，则更喜欢纯 URL，而不是随后链接的登陆页面，因为它可以在任何地方使用，并且您可以更改它指向的位置。"},{"h":"时间：计时器、时钟和时区陷阱"},{"l":["[[秒表|在线秒表]] — 一个普通秒表，当您的手机在另一个房间时很有用。","[[pomodoro-timer|Pomodoro Timer]] — 25 分钟的带休息时间的专注块，适合那些发现该结构有效的人。","[[世界时钟|世界时钟]] — 同时显示多个城市的当前时间。"]},{"p":"世界时钟因其一个特定原因而赢得一席之地：夏令时。世界上一半的日程安排错误不是算术错误，而是两个城市上周相距四个小时，本周相距五个小时的时刻，却没有人检查。\\n\\n在跨时区安排任何事情之前，请将两个城市放入世界时钟中并查看 - 不要计算内存中的偏移量。这也是为什么会议邀请应该带有时区而不是仅仅一个小时。"},{"p":"关于番茄计时器：该技术适用于特定类型的任务——有限制的、专注的、不间断的。它不适用于调试，在调试中，卡住时正确的做法是走开，而不是开始另一个 25 分钟的区块。有帮助时就使用它。"},{"h":"随机性，诚实"},{"p":"[[random-number|Random Number Generator]] 和 [[list-randomizer|List Randomizer]] 涵盖了实际出现的情况：在一个范围内选择一个数字，并将一个列表按公平顺序排列。值得一句公平的话。两者都使用伪随机生成器，用于决定谁支付午餐费用与真正的硬币没有区别。对于任何重要的事情——有奖抽奖、附有资金的分配——你都需要一个可以审核的来源，而浏览器选项卡不是这样的。这里的价值在于剔除人类，因为人类在受到激励时会做出糟糕的选择。"},{"h":"编码垃圾抽屉"},{"p":"在表示之间移动文本的四种工具。它们都不是加密，其区别值得说明，因为它经常令人困惑：编码是任何人都可逆的，并且没有密钥。加密需要密钥。"},{"l":["[[binary-text|Binary to Text]] — 在文本及其二进制表示形式之间进行转换。","[[hex-text|十六进制到文本]] — 在文本和十六进制之间进行转换，这是您在网络工具和调试器中最常见的表示形式。","[[caesar-cipher|Caesar Cipher]] — 将字母移动固定数量，经典的课堂密码。","[[rot13-encoder|ROT13 Encoder]] — 将字母旋转 13，这是一种特殊情况，它本身就是逆的。"]},{"p":"这些对于两件事很有用。首先，理解文本如何变成字节，这是当任何东西看起来乱码时你需要的心理模型。其次，实际调试：当有效负载显示为十六进制时，[[hex-text|Hex to Text]] 转换器是您了解其内容的方式。\\n\\n它们对于隐藏任何东西没有用处。 ROT13 没有密钥——转变是公开的——所以它不会向任何知道 ROT13 是什么的人隐藏任何内容。凯撒密码有 25 种可能的变化，人类在一分钟内就能破解。"},{"h":"格式化事物的两个"},{"l":["[[phone-formatter|电话号码格式化程序]] — 将电话号码标准化为一致的格式。","[[file-size-converter|文件大小转换器]] — 在 KB、MB、GB 和 TB 之间进行转换，并解释了十进制和二进制的区别。"]},{"p":"文件大小转换器有一个真正有价值的输出：它告诉您为什么驱动器公布的数字比您的计算机报告的数字更大。供应商的销售量为 10 次方，操作系统的报告量为 2 次方，每种规模的差距约为 7%。这不是一个错误，这是两个约定。"},{"h":"一个有效的例子：乱码的 API 响应"},{"p":"Webhook 验证失败，日志中的有效负载类似于“\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f”。这是九十秒的诊断。"},{"l":["**1.转换。** 将 `48656c6c6f` 粘贴到 [[hex-text|Hex to Text]] 转换器中 — 结果是 `Hello`。它从来没有乱码，只是编码。","**2.检查形状。** 上游的某些东西在签名之前对有效负载进行十六进制编码。签名是根据原始文本计算的，并根据十六进制进行验证，因此比较失败。","**3.排除另一个方向。** 如果日志显示可读文本，则问题将相反：签署编码表格。","**4.确认大小声明。** 如果同一日志报告 1.2 MB 有效负载，[[file-size-converter|文件大小转换器]] 在任何人争论配额之前确定该负载是十进制还是二进制。"]},{"h":"常见问题"},{"p":"**如果一切都在浏览器中运行，密码生成器安全吗？** 是的，而且比基于服务器的密码生成器更安全：密码是在您的计算机上生成的并且从未传输，因此没有任何内容可以拦截、记录或泄露。代价是您无法恢复未保存的密码。\\n\\n**我可以相信虚拟硬币翻转吗？** 对于随意的决定，可以。对于任何带有金钱或奖品的东西，请使用您可以审核的来源。\\n\\n**密码安全吗？** 不。没有一个。 ROT13 和凯撒密码没有密钥，其存在是为了教授编码，而不是为了保护任何东西。\\n\\n**这些可以离线工作吗？** 一旦页面加载，是的 - 一切都是本地的。\\n\\n**转换器的文本长度有限制吗？** 只有您设备的内存，因为没有任何内容发送到任何地方。"},{"h":"单行版本"},{"p":"长而独特的密码胜过短而聪明的密码，二维码的好坏取决于其中的数据，检查时区偏移而不是计算它们，编码不是加密。"}]}}')},89642,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"開發者工具包：24 個替代付費應用程式的免費瀏覽器工具","description":"使用基於瀏覽器的免費開發工具格式化、轉換、編碼和除錯資料的實用指南 - 無需安裝，無需帳戶，無需上傳任何內容。","category":"開發者工具","blocks":[{"p":"您每週執行一百次的大多數小工作（重新格式化 API 響應、解碼令牌、檢查雜湊值、縮排 SQL 段）不需要 IDE、付費訂閱或團隊許可證。他們需要開啟一個標籤九十秒。\\n\\n下面的集合是二十四個基於瀏覽器的實用程式，涵蓋格式化、轉換、編碼、雜湊和除錯。它們中的每一個都完全在您的頁面中執行：您的資料永遠不會發送到伺服器，這比開發人員通常承認的更重要，因為您貼上的有效負載通常是客戶的。"},{"h":"基於瀏覽器的工具可以取代什麼，不能取代什麼"},{"p":"對邊界要現實一點。這些工具取代了一次性、低風險、高頻率的瑣事。它們不會取代您的語言伺服器、偵錯器、測試套件或在真實環境中重複執行所需的任何內容。"},{"l":["**適合：** 讀取一次回應、偵錯單一值、轉換檔案以進行一次匯入、在出貨前檢查格式。","**不適合：**在每次部署時執行相同的檢查，轉換數百個檔案，任何在 CI 中都必須失敗的東西。","**從不：**任何涉及您無法輪換的憑證的事情。貼上已撤銷的令牌，而不是活動令牌。"]},{"p":"話雖如此，保留這些書籤的原因是吞吐量。在瀏覽器標籤中花費 40 秒的任務永遠不會被安排，永遠不會被委派，也永遠不會成為晚上八點開啟 IDE 的理由。"},{"h":"格式化和轉換資料"},{"p":"最常見的日常工作是使資料可讀。 API 傳回單行 blob，同事傳送帶有被聊天視窗破壞的選項卡的設定檔案，或者您將電子表格匯出為 JSON，但它會傳回為一大行。"},{"l":["[[json-formatter|JSON Formatter]] — 縮排、驗證和讀取有效負載。在除錯之前使用它：一半的“API 已損壞”票證實際上是格式錯誤的 JSON，並帶有尾隨逗號。","[[json-validator|JSON Validator]] - 當您需要嚴格的通過/失敗答案而不是漂亮的列印。","[[xml-formatter|XML Formatter]] — 與 SOAP 回應、RSS 提要和 Maven POM 的工作相同，自 2014 年以來就沒有人接觸過。","[[json-to-yaml|JSON 到 YAML]] 和 [[json-to-csv|JSON 到 CSV]] — 在實際系統實際使用的格式之間移動資料。"]},{"p":"對於一個特定場景，請記住最後一組：客戶向您提供電子表格，並希望在他們的 API 中提供該電子表格。直接將 CSV 轉換為 JSON 只需兩分鐘的工作，而不是一下午的指令碼編寫。"},{"h":"編碼和轉義"},{"p":"編碼錯誤非常令人煩惱，因為資料看起來不錯。值“San José & Sons”以“San Jos%C3%A9 %26 Sons”形式到達，並且由於日誌中不可見的原因，您與資料庫的比較失敗。"},{"l":["[[url-encoder|URL 編碼器/解碼器]] — 立即確定查詢字串是否是雙重編碼的。","[[base64-encoder|Base64 編碼器/解碼器]] — 解碼憑證片段，或編碼小資產以內聯在 CSS 中。","[[html-entity-encoder|HTML 實體編碼器/解碼器]] — 找出頁面中的雜散「&」是否來自您的範本或資料。","[[unicode-converter|Unicode 轉換器]] — 當「損壞的」字元被證明是以錯誤編碼呈現的合法字元時很有用。","[[number-base-converter|數基轉換器]] — 無需計算器應用程式即可檢查顏色、許可權位元遮罩或記憶體位址。"]},{"b":"一個實用的習慣：當一個值出現亂碼時，一次解碼一層並將每個結果貼到空白欄位中。如果第一次解碼產生可讀文本，則問題是上游某處的額外編碼。如果它產生 mojibake，那麼您遇到的是編碼問題而不是轉義問題，而這兩個問題需要不同的修復。"},{"h":"識別符號、雜湊值和令牌"},{"p":"該群組是開發人員花費最多時間尋找他們曾經編寫並丟失的正確本地指令碼的地方。"},{"l":["[[uuid-generator|UUID Generator]] — 為種子資料、固定裝置或快速資料庫行產生 v4 識別碼。","[[md5-generator|MD5 / SHA 雜湊產生器]] — 驗證下載或確認兩個檔案實際上應該相同。","[[timestamp-converter|時間戳記轉換器]] — 整個清單中最常用的工具。當日誌行顯示 1761000000 時，這可以告訴您事件是在部署期間還是部署之前發生。"]},{"p":"時間戳轉換器之所以能得到它的青睞，有一個特定的原因：紀元號是明確的，同時也是無用的。您確切地知道事情發生的時間，但無法告訴同事。一次轉變通常會解決比應有的更激烈的爭論。"},{"h":"比較與除錯"},{"l":["[[regex-tester|Regex Tester]] — 這裡槓桿率最高的專案。看起來正確但安靜地不匹配任何內容的正規表示式是開發中最昂貴的錯誤之一，因為它在沒有人閱讀的地方安靜地失敗。","[[html-preview|HTML Preview]] — 迭代標記片段以檢查其實際呈現方式。"]},{"p":"根據您實際期望的輸入測試您的正規表示式，包括空字串、Unicode 名稱和帶有換行符的值。大多數模式在第三種情況下就會崩潰，直到生產資料到達之前沒有人注意到。"},{"h":"一個可行的例子：三個工具，一個無聊的事件"},{"p":"這是說服我為所有這些新增書籤的序列。一位客戶報告說，他們週二提交的記錄在週四的報告中丟失了。"},{"l":["**1.轉換時間戳。 ** 報表作業將記錄的建立時間記錄為紀元值。 [[timestamp-converter|Timestamp Converter]] 顯示記錄是在當地時間星期二晚上 11 點建立的 - 作業的時區假設是問題所在，而不是記錄。","**2.格式化有效負載。 **通過 [[json-formatter|JSON Formatter]] 獲取儲存的 JSON，發現該記錄是用空日期欄位寫入的，因為客戶端兩次呼叫同一端點（相隔 200 毫秒），並且第二次寫入獲勝。","**3.比較有效負載。 ** 兩筆記錄都帶有相同的 API 金鑰和相同的客戶端時間戳，這指向重試而不是兩個單獨的客戶。"]},{"p":"總用時：四分鐘。先前的調查嘗試在一個日誌平臺中尋找相同的根本原因，花了一個下午的時間並得出了錯誤的結論。"},{"h":"隱私：為什麼本地運作是實際功能"},{"p":"該庫中的每個工具都會在您自己的瀏覽器中處理您的輸入。沒有上傳任何內容，這意味著沒有保留問題，沒有處理器協議，也沒有關於三分鐘前貼上的生產負載的令人不舒服的對話。\\n\\n這就是為什麼比起託管的「pastebin API」或要求您註冊的線上服務更喜歡這些工具的原因。這也意味著他們可以在飛機上、地下室或公司 VPN 決定阻止另一個域時繼續工作。"},{"p":"需要明確說明的一個警告是：只有當頁面本身是您認為的程式碼時，具有離線功能的頁面才是私有的。在共享電腦上，使用私有視窗並在完成後將其關閉，尤其是在您一直在解碼令牌的情況下。"},{"h":"圍繞它們建立工作流程"},{"p":"這些工具單獨來看都是微不足道的。價值在於立即獲取而不是「稍後再獲取」的習慣，因為稍後是指當您編寫一次性指令碼，或開啟 IDE，或決定根本不值得檢查時。"},{"l":["為集合（而不是單一 URL）新增書籤，並將其放入瀏覽器的工具列中。","當出現問題時，請在形成理論之前進行檢查。花費十五秒；消滅所有型別的錯誤結論。","當你對同一件事檢查兩次時，那就是自動化它的訊號——但不要因為懷疑而自動化。","不要貼上製作機密。旋轉任何你不確定的東西。"]},{"h":"常見問題"},{"p":"**這些工具免費嗎？ ** 是的，完全免費，沒有帳戶，也沒有使用限制。沒有任何付費等級會阻礙任何基本功能。\\n\\n**它們可以離線工作嗎？ ** 頁面載入後，是的 - 一切都在您的瀏覽器中執行。重新載入需要連線。\\n\\n**我可以將它們用於商業工作嗎？ ** 可以。輸出是您的，沒有歸屬要求。\\n\\n**有API嗎？ ** 沒有，這是故意的－價值就是介面。匯出輸出並按照您喜歡的方式處理它。\\n\\n**為什麼不直接安裝一個 CLI 工具呢？ ** 當您需要 3 次時安裝一個。前兩個使用瀏覽器標籤。"}]},"text-tools-for-writers":{"title":"17 個適合作家、學生和營銷人員的免費文本工具","description":"使用從不上傳文本的免費瀏覽器工具清理副本、準確計算字數、格式化列表並將粗略的草稿變成可釋出的內容。","category":"文字工具","blocks":[{"p":"工作寫作涉及大量與寫作無關的機械苦差事：從貼上的段落中去除多餘的空格、檢查字數限制、刪除重複的名稱列表、將某些內容轉換為 URL slug。\\n\\n這十七個工具就是用在這部分的運作。它們都在瀏覽器本地執行，這不是一個小細節——您貼上的草稿通常是未發布的，您正在排序的清單通常是某人的個人資料。"},{"h":"衡量你所寫的內容"},{"p":"字數統計聽起來已經解決了，直到客戶要求正好 800 個字，而您的編輯器說 820，或者表單拒絕您的 1,995 個字元的文本，並且沒有解釋換行符的位置。"},{"l":["[[word-counter|字計數器]] — 標準量測。貼上、閱讀、調整。","[[letter-counter|Letter Counter]] — 計算字元和字母頻率。當您除錯為什麼某個段落感覺不對時很有用：它通常是重複的字母模式，而不是夢想。"]},{"p":"關於「一個單字」含義的註釋：不同的計數器在連字元、數字和 URL 方面存在分歧。如果確切的數字很重要，請使用檢查您工作的人員使用的相同櫃檯，並提前達成協議。這是一個真正常見的小而無意義的爭論的根源。"},{"h":"清理你沒有寫的副本"},{"p":"您收到的大多數文字都略有損壞：複製貼上產生的雙空格、雜散的製表符、匆忙打字造成的大小寫不一致。手動修復它速度慢且容易出錯。"},{"l":["[[text-trimmer|文字修剪器]] — 立即刪除每一行的前導和尾隨空格。這比此列表中的其他任何內容修復了更多的“格式看起來損壞”報告。","[[text-case-converter|文字大小寫轉換器]] — 在區塊中的句子大小寫、標題大小寫、大小寫之間切換。也是撤銷意外的大寫鎖定段落的最快方法。","[[text-to-slug|Text to Slug]] — 將標題變成乾淨的 URL slug。貼上你的標題，得到標題，完成。"]},{"p":"slug 生成器除了 URL 之外還有一個用途：它是一種快速產生可讀檔案名稱或錨點的方法，人們一眼就能解析，這比「final_final_v3」要好。"},{"h":"使用清單"},{"p":"列表、庫存、郵件合併、標籤清理、調查回復、電子表格列——在某些時候，一切都變成了列表，每個列表都需要排序、去重或隨機化。"},{"l":["[[duplicate-line-remover|重複行刪除器]] — 比較兩個列表，或清理一個列表。輸出會告訴您刪除了多少重複項，這在您報告結果時非常有用。","[[list-sorter|List Sorter]] — 與結構化清單輸入相同的工作。","[[list-randomizer|List Randomizer]] — 隨機排列抽籤順序、測驗序列或圍牆入圍名單，這樣就不會有人懷疑存在偏袒行為。","[[line-number-adder|行號新增器]] — 編號行，供在票證或程式碼審查評論中參考。"]},{"b":"這裡的經典陷阱是一個看起來經過重複資料刪除但實際上並非如此的清單：「Apple」、「apple」和「Apple.」對於電腦來說是三個不同的行。在重複資料刪除之前，請修剪空格並去除尾隨標點符號，否則您將不會合並任何內容並得出資料是乾淨的結論。"},{"h":"預覽和格式化"},{"p":"Markdown 贏了，但情況並不統一。你的工具一半會渲染它，一半不會，而沒有渲染的一半通常是高階人員必須貼上的工具。"},{"l":["[[markdown-preview|Markdown Preview]] — 即時渲染，因此您可以在表格或巢狀清單到達使用者端之前檢查其實際外觀。","[[text-repeater|Text Repeater]] — 重複字串 N 次。對於產生填充、測試資料或偶爾在檔案中表達觀點很有用。"]},{"p":"Markdown 預覽是整個集合中安靜地節省最多時間的工具，因為渲染文件中的損壞表格比原始文本中的損壞表格更明顯，也更令人尷尬。"},{"h":"其餘的，以及何時接觸它們"},{"l":["[[random-string|隨機字串產生器]] — 產生可讀取的隨機數、佔位符 ID 或短程式碼。比手工發明一些東西更好，因為你不會意外地重複使用它。","[[摩斯電碼|摩斯電碼翻譯者]] — 真正有趣，偶爾對主題專案或謎題有用。"]},{"p":"這些是頻率較低的工具，但它們無需花費任何費用即可新增書籤，並且它們解決了“我現在需要一個看起來隨機的值，但我不相信自己能夠編出一個值”的具體問題。"},{"h":"真實的編輯過程"},{"p":"當草稿從其他人到達並需要以您的名義發出時，可以使用以下順序。"},{"l":["**1.修剪。 ** 首先透過 [[text-trimmer|Text Trimmer]] 執行整個檔案。空白損壞隱藏在您永遠看不到的段落內。","**2.乾淨的大小寫。 ** 僅對標題使用 [[text-case-converter|文字大小寫轉換器]]。切勿將大小寫轉換應用於完整的草稿 - 它會破壞專有名詞。","**3.測量。 ** 在書寫之前用 [[字計數器|字計數器]] 檢查長度，這樣您就知道該作品的形狀。","**4.預覽。 ** 如果包含 Markdown，則使用 [[markdown-preview|Markdown Preview]] 來渲染。","**5. Slug.** 最後從最終標題產生 URL slug，使用 [[text-to-slug|Text to Slug]] — 之後更改標題會破壞該 slug。"]},{"p":"整個過程需要幾分鐘，並且消除了檔案技術上正確但明顯錯誤的錯誤類別。"},{"h":"作家關於隱私的問題"},{"p":"**我未釋出的文本會離開我的計算機嗎？ ** 不會。這些工具會在您的瀏覽器中處理文本，並且不會儲存或傳輸任何內容。\\n\\n**有長度限制嗎？ ** 沒有伺服器端限制，因為沒有伺服器呼叫。極大的輸入受到您自己裝置記憶體的限制。\\n\\n**我可以將輸出用於商業用途嗎？ ** 可以，自由使用，無需歸屬。\\n\\n**他們可以在電話上工作嗎？ ** 是的。佈局會調整，並且執行相同的程式碼。"},{"h":"這些工具不能為您做什麼"},{"p":"值得直言其侷限性，因為機械化錯誤事物的工具只會產生更快的錯誤。\\n\\n這些實用程式都無法告訴您句子是否清晰，主張是否有來源，或語氣是否適合聽眾。他們計算字元數；他們不評判散文。在該頁面上的每個指標上得分都很高的文字仍然無法閱讀。\\n\\n他們也不編輯。當您發現自己大規模地手動重寫單個子句時，文字工具已經無法滿足您的需求，您需要一個合適的編輯器、一個用正規表示式查詢和替換的工具（[[regex-tester|Regex Tester]] 確實非常適合排練）或一個指令碼。使用瀏覽器作為機械層，並對其之上的所有內容保留自己的判斷。"},{"p":"他們不會做的另一件事是修復不良來源。如果您的電子表格充滿了不一致的命名 - “Dr”、“DR”、“Dr.”全部集中在一列中 - 一個工具會對您忠實提供的內容進行排序和刪除重複內容，並且您仍然會在應該有一個的地方保留三個條目。清理資料是一個決定，而不是一個機械步驟。首先確定規範形式，然後應用它，然後檢查。"},{"h":"保持工作清單可用"},{"p":"如果你維護一個潛在客戶、連結、參考文獻或術語的列表，它就會悄悄退化。失敗模式總是相同的：看起來相同的條目實際上並不相同，並且一次合併不會刪除任何內容。\\n\\n有效的維護過程很無聊：修剪空白、標準化大寫、去掉尾隨標點符號，然後消除重複。依照這個順序－去重後的修剪會遺失條目。每月在活動清單上執行一次此操作會將兩小時無法恢復的混亂變成十分鐘的苦差事。\\n\\n當兩個清單需要協調時（例如，登記清單與出勤清單）首先使用 [[list-sorter|List Sorter]] 對兩個清單進行排序，使它們對齊，然後透過肉眼進行比較。在比較之前對雙方進行排序是兩分鐘檢查和二十分鐘狩獵之間的區別。"},{"h":"外賣"},{"p":"這些工具都不聰明。這就是要點：他們刪除了機械性​​的百分之五的非寫作內容，因此剩下的百分之九十五實際上是關於句子的。為您每月使用的內容新增書籤，忽略其餘內容，並停止手動修復空白。"}]},"calculators-and-converters-guide":{"title":"18 個免費計算器和轉換器，適合您實際處理的數字","description":"百分比、折扣、小費、貸款、日期、BMI 和單位換算 — 免費的瀏覽器計算器可以顯示其推理並且從不儲存您的輸入。","category":"計算機","blocks":[{"p":"每個人都需要分攤帳單，弄清楚折扣是否是真正的折扣，並且不假思索地轉換溫度或檔案大小。每個人也至少有一次在公共場合犯過這樣的錯誤。\\n\\n這是十八個計算器和轉換器的集合，涵蓋金錢、日期、健康以及工作和旅行中出現的單位轉換。所有這些都在瀏覽器中執行：不會儲存任何內容，因此您輸入的數字與任何人無關，除了您自己。"},{"h":"金錢計算"},{"p":"現實世界中最常見的數學是某物的百分比。銷售稅、小費、折扣、佣金、成長率。公式很簡單，但人們犯錯的原因幾乎總是相同的：他們將百分比應用於錯誤的基數。"},{"l":["[[discount-calculator|折扣計算器]] — 計算出最終價格，更重要的是，計算您省了多少錢。對於發現「50% 折扣」（實際上是提高標價後的 20%）非常有用。","[[小費計算器|小費計算器]] — 拆分賬單，選擇百分比，如果您願意的話，可以按人四捨五入。","[[loan-calculator|貸款計算器]] — 每月還款額和總利息，這個數字實際上決定了貸款是否負擔得起。"]},{"b":"關於折扣：先打 20% 折扣，再打 20% 折扣，這不是 40% 折扣，而是 36% 折扣。在減少的基數上按順序百分比複合。此列表中的任何計算器都會在大約兩秒鐘內確認它，這是本文中最有用的算術事實。"},{"p":"貸款計算器值得特別說明。重要的數字不是每月還款額，而是貸款期間支付的總利息，因為這是藉款的實際成本。每月還款額相同但期限不同的兩筆貸款的總利息可能相差數萬。"},{"h":"日期和倒計時"},{"p":"日期算術是大多數人默默犯錯的地方，因為人類的月份有不同的長度，並且答案會根據您的意思是“日曆月”還是“30 天”而變化。"},{"l":["[[date-difference|日期差異計算器]] — 兩個日期之間的天數（以及總月數、年數）。","[[days-until|Days Until Calculator]] — 特定日期的倒數計時，工作日數通常是人們真正想要的。","[[年齡計算器|年齡計算器]] — 以年和日為單位的準確年齡，加上下一個生日。","[[timestamp-converter|時間戳轉換器]] — 將 Unix 時間戳轉換為真實日期，如果您接觸日誌、資料庫或 API 回應，這一點很重要。"]},{"p":"令人困惑的差異是：3 月 1 日和 4 月 1 日之間的天數是 31，但「月」數是 1。如果您正在計算通知期或訂閱期限，請以書面說明您所指的單位。"},{"h":"老實說，健康數字"},{"l":["[[bmi-計算器|BMI 計算器]] — 體重指數與標準類別，以及以下注意事項。"]},{"p":"BMI 是人口層面的篩檢統計。它沒有說明肌肉質量、身體組成或任何個人的健康狀況，而且它並不能很好地代表運動員、老年人和不同種族群體的健康狀況。將其用作多個資料點中的一個，或作為追蹤隨時間變化的一種方式，而不是作為結論。如果您正在做出影響您健康的決定，那麼正確的工具是臨床醫生，而不是瀏覽器標籤。"},{"h":"單位換算：日常單位換算"},{"p":"單位換算分為兩種：必須精確的單位換算和粗略的單位換算。這些工具可以同時處理這兩種情況，而工作就是記住哪個是哪個。"},{"l":["[[長度轉換器|長度轉換器]] — 公製到英制的轉換：毫米、公分、公尺、公里、英吋、英尺、碼、英里。","[[重量轉換器|重量轉換器]] — 克、公斤、盎司、磅、噸。在食譜或運送標籤之前要檢查的一個。","[[溫度轉換器|溫度轉換器]] — 攝氏度、華氏、開爾文。因為 -10°C 不是 14°F，公式也不是乘法。","[[速度轉換器|速度轉換器]] — km/h、mph、m/s、knots。對於外國速度限製或工程規範很有用。","[[面積轉換器|面積轉換器]] — 平方公尺、平方英尺、英畝、公頃。這是人們在購買或租賃房產時最糟糕的估計。","[[volume-converter|體積轉換器]] — 升、毫升、加侖、杯、立方米。","[[time-converter|時間轉換器]] — 秒、分鐘、小時、天、週。"]},{"b":"兩個值得了解的轉換陷阱：上面的資料儲存（行銷人員出售 10^3，作業系統報告 2^10）和燃油經濟性 — 一輛報價為 40 英里/加侖（英制）的汽車比 40 英里/加侖更接近 33 英里/加侖（美國），因為英制加侖更大。如果第二個錯誤的話，租車的效率就會顯得不切實際。"},{"h":"您不會期望需要的兩個"},{"l":["[[隨機數|隨機數產生器]] — 在一定範圍內抽獎，用於抽獎、分組或快速 A/B 分割。有用正是因為它消除了您操縱它的懷疑。","[[dice-roller|Dice Roller]] — 從硬幣翻轉到二十面骰子的任何骰子，適用於棋盤遊戲或桌面遊戲，其中真正的骰子最後一次從桌子上滾落。"]},{"h":"正確使用計算器"},{"p":"只有當您知道要詢問的數字時，計算器才會有幫助。三個習慣會產生影響。"},{"l":["**第一輪，計算第二輪。 **如果精確的數字不會改變您的決定，請使用第一輪。您可以在腦中檢查整數的百分比，從而捕捉輸入錯誤。","**健全性檢查大小。 ** 在相信結果之前，請先詢問它是否應該大於或小於輸入，以及大致上多少。除了這次之外，大多數算術錯誤在每一次檢查中都倖免於難。","**拍攝輸入，而不是輸出。 ** 當您稍後重新執行計算時，重要的是瞭解您的假設，而不是您的結論。"]},{"h":"人們實際問的問題"},{"p":"**我的號碼是否儲存在任何地方？ ** 不。計算在您的瀏覽器中進行，不會傳輸或保留任何內容。\\n\\n**這些可以在手機上使用嗎？ ** 可以，並且計算器是專為單手使用而設計的。\\n\\n**您使用哪種轉換標準進行資料儲存？ ** 預設情況下為十進位制（1 KB = 1000 位元組），因為這就是儲存的銷售方式。作業系統報告二進位制，這就是驅動器看起來縮小的原因 - 該工具解釋了差異，而不是默默地選擇一邊。\\n\\n**我可以將它們嵌入到我自己的網站上嗎？ ** 不行。請為它們新增書籤；其成本為零，並且準確性問題由您自己承擔。"},{"h":"百分比：四個重要的錯誤"},{"p":"一個人在日常生活中所犯的幾乎每一個百分比錯誤都是同樣的四個錯誤之一。命名它們使它們可以避免。"},{"l":["**錯誤的基礎。 ** 「上漲 10%，然後下降 10%，讓你回到起點」是錯誤的，因為兩者適用於不同的基礎。 100的百分之十是10；90的百分之十是9。","**百分比的百分比。 ** 疊加兩個折扣會將它們相乘（0.8 × 0.8 = 0.64，因此 36% 折扣），但不會將它們相加。","**百分比與百分點。 ** 從 4% 到 6% 的比率上升了 2 個百分點，但相對而言上升了 50%。政治和醫學都充滿了這種混亂，而且這並不總是偶然的。","**舍入太早。 ** 在應用百分比之前捨入中間步驟會增加誤差。保持完全精確直到最終數字，並在計算器上而不是在頭腦中完成最後一步。"]},{"p":"如果您只從整個部分中採取一個習慣，請採取這個習慣：在向任何人引用百分比之前，重申它是*的百分比。關於數字的爭論有一半實際上是關於分母的爭論。"},{"h":"知道何時停止計算"},{"p":"到了某個點，精度就不再有用了。每月還款額精確到小數點後兩位是有意義的。將預期的總成本精確到小數點後八位是避免實際決定的一種方式，實際決定是貸款是否符合您在沒有壓力的情況下可以承受的範圍。\\n\\n有用的測試是敏感性問題：如果輸入變化 10%，決策是否會改變？如果不是，請停止完善它，並將額外的時間用於確實改變答案的變數 - 通常是術語而不是費率，或標價而不是折扣。"},{"p":"有一個界線值得明確說明：這些計算器是算術，而不是建議。儲蓄目標、退休日期和債務償還計劃都是關於風險、行為和時間的決定，瀏覽器標籤無法權衡其中任何一個。只有當你決定了你的假設後，它才能告訴你這些數字意味著什麼。這種區別就是計算器有用和負責任之間的區別。"},{"h":"單行版本"},{"p":"正確地為金錢和日期計算器新增書籤，將體重指數視為一個訊號而不是一項判決，記住堆疊百分比會相乘，並在數字進入任何合約時檢查單位轉換。這幾乎涵蓋了所有內容。"}]},"image-and-design-tools":{"title":"14 個可在瀏覽器中執行的免費影像和設計工具","description":"壓縮、調整大小和準備影像，並產生 CSS 效果、調色盤、對比度檢查和網站圖示，無需安裝 Photoshop 或設計套件。","category":"設計工具","blocks":[{"p":"影像工作有一個特定的問題：工作通常很小，但提供的工具卻非常多。您需要從英雄影像中刪除 400 KB，或獲得設計師提到的十六進位值，或產生一個尚未製作的圖示。這不需要訂閱。\\n\\n以下的 14 個工具涵蓋了準備圖片、處理顏色、產生 CSS 效果以及遺漏的小型製作資產。每個都在本地執行，這對於影像比對於文字更重要：您剛剛壓縮的照片通常是您尚未發布的照片​​。"},{"h":"準備網路影像"},{"p":"大多數影像問題實際上都是重量問題。感覺緩慢的頁面通常包含大於其顯示尺寸的影像，格式錯誤，品質設定無人質疑。"},{"l":["[[image-compressor|圖片壓縮器]] — 減少檔案大小，同時保持影像視覺完整。在將任何內容上傳到有大小限制的表單之前執行它。","[[image-resizer|Image Resizer]] — 設定您需要的實際畫素尺寸。這是更大的勝利：以 800 畫素顯示的 4000 畫素影像攜帶的資料是其所需資料的五倍。","[[image-to-base64|Image to Base64]] — 將小圖片轉換為資料 URI，以便內聯到 CSS、HTML 或電子郵件範本中。"]},{"b":"順序很重要。首先調整大小，其次壓縮。壓縮 4000 畫素的影像會產生比調整為 800 畫素然後以相同質量壓縮的檔案重得多的檔案，因為壓縮器將精力花費在無論如何都會被丟棄的畫素上。"},{"p":"你應該壓縮多少？誠實的答案是：直到看起來不對勁，然後退後一步。對於攝影英雄影像，70% 到 80% 的品質通常與正常觀看尺寸下的原始影像無法區分。對於標誌、螢幕截圖或任何具有平坦顏色和硬邊的內容，請使用 PNG 並進行更嚴格的壓縮 - 這些增益更多，損失更少。"},{"p":"一個實用的經驗法則：對於英雄影像來說，任何低於 200 KB 的內容都可以，對於縮圖來說，低於 80 KB 的內容都可以，如果不能低於 300 KB，則可能存在尺寸問題，而不是品質問題。"},{"h":"Base64：何時內聯是正確的呼叫"},{"p":"將影像轉換為 Base64 資料 URI 會刪除 HTTP 請求，這聽起來像是純粹的勝利。通常情況並非如此。編碼後的字串大約比二進位檔案大三分之一，它無法單獨快取，並且會使您的 CSS 或 HTML 膨脹。\\n\\n僅當影像很小（低於幾千位元組）且僅使用一次且至關重要時才內聯。單一電子郵件範本中的小圖示是典型的案例。對於跨頁面重複或大於幾千位元組的任何內容，將其作為檔案提供並讓瀏覽器快取它。"},{"h":"水印：什麼是真正可去除的"},{"l":[]},{"p":"清楚這是做什麼的。它消除或遮蓋了可見標記。它無法重建底層畫素——被覆蓋的資訊已經消失，並且沒有過濾器將其重新發明出來。結果範圍從當標記位於普通背景上時不可見到當標記位於細節上時出現明顯的汙點。\\n\\n還有一件事值得明確地說：刪除別人的浮水印並發布結果在大多數司法管轄區都是版權問題，並且無論您是否會被抓住，都屬於許可違規行為。此工具適用於從您自己的影像或您已許可的庫存中刪除標記。"},{"h":"顏色：轉換、檢查、選擇"},{"p":"顏色是小錯誤變得非常明顯的地方。無法存取的對比度、實際上是 HSL 三元組的十六進位值、在顯示器上看起來連貫但在投影機上看起來渾濁的調色盤。"},{"l":["[[color-converter|顏色轉換器]] — 在 HEX、RGB 和 HSL 之間移動。 HSL 值得學習閱讀，因為色調 210、飽和度 40%、亮度 50% 比十六進位值更容易手動調整。","[[contrast-checker|對比度檢查器]] — 根據 WCAG 閾值測試文本的背景。這是本文中最有用的工具，因為它捕捉了真正的合規性問題，而不是品味問題。","[[color-palette|調色盤產生器]] — 當您從品牌顏色開始並需要其餘比例時，產生一個連貫的集合。"]},{"b":"相較之下：WCAG AA 要求普通內文文本為 4.5 比 1，大文本為 3 比 1。如果您在按鈕的兩種品牌顏色之間進行選擇，則易於存取的顏色通常不是設計師喜歡的顏色。先檢查，再用資料論證。"},{"p":"關於顏色工具的一個警告：它們都假設您的顯示器已校準並且檢視頁面的人有眼睛。這兩種假設都不安全。這就是為什麼比起主觀組合更喜歡對比檢查組合的原因。"},{"h":"無需開啟設計工具的 CSS 效果"},{"p":"手動編寫漸層或分層陰影確實是一項令人不快的任務。語法很繁瑣，你看不到你正在生成什麼，好陰影和壞陰影之間的差異就是幾個畫素的模糊。"},{"l":["[[gradient-generator|CSS 漸變產生器]] — 建立線性和徑向漸層並直接複製 CSS。","[[box-shadow-generator|Box Shadow Generator]] — 分層多個陰影，這就是區分細微高程和大幅下降的原因。","[[border-radius-generator|邊框半徑產生器]] — 取得使形狀看起來有意為之的不對稱半徑。","[[text-shadow-generator|文字陰影產生器]] — 很少使用。大多數文字陰影太強；這可以讓您調整偏移和模糊，直到它消失。"]},{"p":"解決這四個問題的秘訣就是剋制。兩個陰影——一個緊密的深色陰影和一個寬闊的柔和陰影——被解讀為物理高度。一個影子讀起來像是十五年前的網站。產生、複製、然後刪除，直到您無法辨別它的存在。"},{"h":"每個人都忘記的生產資產"},{"l":["[[favicon-generator|Favicon Generator]] — 產生網站實際需要的小圖示集。之所以將其列入列表，是因為網站圖示是最有可能完全丟失的資產，而丟失的圖示會顯示通用的瀏覽器頁面圖示，使已完成的網站看起來未完成。","[[emoji-picker|表情符號選擇器]] — 瀏覽、搜尋和複製表情符號，無需透過作業系統選擇器進行搜尋。當您編寫需要一個特定符號的副本時，它確實很有用。"]},{"h":"一個有效的例子：運送英雄部分"},{"p":"這是整個叢集在做一項真正的工作。一個頁面需要一個帶有背景影像、標題和按鈕的英雄，但目前還沒有建構這些內容。"},{"l":["**1.保留空間。 ** 在佈局中為影像槽指定固定高度，以便頁面在第一次渲染時具有正確的形狀，而不是在真實影像落地時跳躍。","**2.調整大小並壓縮。 ** 當真實照片到達時，以 1600 畫素寬執行 [[image-resizer|Image Resizer]]，然後以 75% 的寬度執行 [[image-compressor|Image Compressor]]。這是您可以傳送的檔案。","**3.對文字進行對比檢查。 ** 照片上的標題是典型的對比失敗。使用 [[contrast-checker|Contrast Checker]] 選擇深色疊加強度或透過 AA 的淺色文字顏色。","**4.建構按鈕。 ** [[box-shadow-generator|Box Shadow Generator]] 提供高度，[[color-converter|Color Converter]] 將品牌顏色轉換為 CSS 所需的格式。","**5. Ship.** 從 [[favicon-generator|Favicon Generator]] 新增一個 favicon，這樣選項卡看起來就不會被遺棄，該部分就完成了。"]},{"p":"五種工具，沒有設計套件，每個輸出都是一個可以直接貼到程式碼中的值。"},{"h":"常見問題"},{"p":"**我的影像上傳到任何地方了嗎？ ** 沒有。壓縮、調整大小和 Base64 轉換都在您的瀏覽器中進行，這就是為什麼沒有檔案大小限制和上傳佇列的原因。\\n\\n**壓縮影像會降低品質嗎？ ** 根據定義，總是如此。問題是它是否可見。在 70% 到 80% 的品質和正確的尺寸下，通常並非如此。\\n\\n**為什麼調整大小後的影像看起來仍然很大？ ** 十有八九你在調整大小之前進行了壓縮，或者當照片儲存為 JPEG 更好時，你卻儲存為 PNG。\\n\\n**我可以將它們用於客戶工作嗎？ ** 可以，沒有歸屬權，也沒有商業限制。\\n\\n**它們可以在手機上使用嗎？ ** 可以，但在手機上調整大照片的大小和壓縮取決於裝置的記憶體而不是伺服器。"},{"h":"單行版本"},{"p":"在壓縮之前調整大小，在爭論顏色之前檢查對比度，保持陰影微妙，並且永遠不要忘記網站圖示。無論如何，這就是設計套件為您做的大部分事情。"}]},"math-tools-for-real-numbers":{"title":"6 個免費的數學工具，用於處理不正常的數字","description":"科學記數法、小數轉換為分數、質數檢查、階乘和 GCF/LCM — 免費的瀏覽器工具，用於處理容易出錯的數字工作。","category":"數學工具","blocks":[{"p":"你在計算機上實際需要的數學並不是考試時要考的數學。它是：這個數字是否採用系統期望的格式，這個分數是否簡化，這個數字增長的速度有多快，以及為什麼計算器和電子表格不一致。\\n\\n這六種工具涵蓋了這個領域。它們在本地執行，這對算術來說意味著一個值得一提的具體好處：您輸入的數字不會傳送到任何地方，因此您可以毫不猶豫地檢查涉及工資、餘額或客戶資料的計算。"},{"h":"將數字轉換為機器接受的形式"},{"p":"計算機將十進位制分數儲存為二進位制分數。 0.1 不能完全用二進位表示 - 最接近的雙精度值是 0.1000000000000000055511151231257827。加上 0.1 + 0.2，您將得到 0.30000000000000004，預設列印為 0.3，並悄悄地破壞了相等性檢查。"},{"l":["[[科學記數法|科學記數法轉換器]] — 在標準形式和科學形式之間轉換，這是大多數日誌、電子表格和 API 實際儲存大小數字的方式。","[[decimal-fraction|小數轉分數]] — 將小數轉換為精確分數。這是上述問題的解決方案：精確分數算術中的 0.1 + 0.2 是 3/10，而不是近似值。"]},{"b":"如果您曾經見過總計錯誤 0.0000000000000004，這就是原因。在金融程式碼中，標準答案是使用整數美分或十進位函式庫，而不是浮點數。如果您曾經見過電子表格與指令碼的差異只有零頭，那麼這就是同一個錯誤，但戴著不同的帽子。"},{"p":"科學記數法值得熟練，因為它是閱讀日誌行和瞇著眼睛看它之間的區別。 6.022e23、1.6e-19 和 3e8 是阿伏伽德羅數、基本電荷和光速。如果這些看起來像噪音而不是數字，則透過該工具轉換一些可以永久修復它。"},{"h":"素數以及為什麼有人關心"},{"l":["[[prime-checker|質數檢查器]] — 測試一個數是否為質數，如果不是，則檢視它的因式分解。","[[gcf-calculator|GCF LCM 計算器]] — 最大公因數和最小公倍數。"]},{"p":"素數不是學校練習。您建立的每個 HTTPS 連線的安全性取決於這樣一個事實：將兩個大素數相乘很容易，而將結果因式分解卻很困難。這種不對稱性就是 RSA 的全部基礎。\\n\\n對於日常用途，素數檢查主要與分數有關。化簡分數意味著將頂部和底部除以它們的最大公因數，如果不進行因式分解，你就無法找到它。這就是為什麼這兩個工具屬於一起的原因：檢查因素，然後一步獲得 GCF 和 LCM。"},{"p":"LCM 一半是人們會忘記的一個，它解決了日程安排問題：每 18 天和每 12 天重複的兩個事件每 36 天重合一次。相同的算術，不同的應用。"},{"h":"階乘及其爆炸速度"},{"l":["[[階乘計算機|階乘計算器]] — n！對於答案仍然有意義的值。"]},{"p":"階乘的成長速度幾乎比你在辦公桌上遇到的任何東西都快。 10！約360萬。 20！約 2.4 千萬億——遠大於地球上沙粒的數量。 52！ ，洗牌方式的數量，大約是 8 後面跟著 67 個數字。\\n\\n實際結果是，列舉所有排列的程式在 5 項時表現良好，在 8 項時還可以接受，在 12 項時則永久卡住。如果一項任務感覺永遠不會完成，而您正在迴圈排列，那麼幾乎可以肯定這就是原因。這也是反對大多數蠻力方法的論據，以算術而非意見的形式表達。"},{"h":"羅馬數字，以及它們的奇怪之處"},{"l":["[[roman-numerals|羅馬數位轉換器]] — 羅馬數字之間的轉換。"]},{"p":"羅馬數字值得理解而不僅僅是轉換，因為該系統揭示了一些有關位置表示法的資訊。沒有零，也沒有位值：XI 表示十一，無論它代表十一根棍子還是一萬一千。這就是為什麼羅馬數字的算術確實很困難，也是為什麼這個系統存在了幾個世紀主要是為了計數和約會而不是計算。\\n\\n減法規則是人們犯錯的部分。 IV是四，不是VI； IX 是九。時鐘是一個著名的例外——大笨鐘使用 IIII 而不是 IV，歷史學家至今仍在爭論的原因。在任何情況下，轉換而不是派生都是正確的選擇。"},{"h":"一個有效的例子：手動檢查分數"},{"p":"一份食譜需要 0.375 杯和一個以克為單位的秤，一份報告引用的比率為 0.625，兩者看起來都像是某人匆忙輸入的數字。"},{"l":["**1.找到精確的分數。 ** 透過 [[decimal-fraction|小數化分數]] 工具執行 0.375：3/8。執行 0.625：5/8。兩者都不需要你沒有的計算機習慣。","**2.簡化比率。 ** 要表達 3/8 與 5/8，您需要 3 和 5 的 GCF。 [[gcf-calculator|GCF LCM Calculator]] 給出 1，因此比率是 3:5，已經是最簡單的了。","**3.檢查階乘宣告。 ** 如果有人告訴您 9 個訂單的佇列有 362,880 個排列，[[階乘計算器|階乘計算器]] 會確認 9！正是如此。現在您知道建置時間估計是否合理。","**4.標準化任何大的東西。 ** 根據[[科學計數法|科學計數法轉換器]]，報告 1.5e9 奈秒的伺服器是 1.5 秒——這是延遲問題和舍入偽影之間的區別。"]},{"h":"這些工具故意不做什麼"},{"p":"他們不表現出工作，也不教導。如果你需要理解為什麼一個公式是正確的，那麼計算器是錯誤的工具——它給出的答案沒有原因，這就是人們最終只能計算而無法推理的原因。\\n\\n他們也不做任意精度。階乘和大因式分解將失去準確性，超過答案仍然有用的程度，瀏覽器標籤不是電腦代數系統。對於正確性真正重要的任何事情（工程、金融、密碼學），請使用具有精確算術的適當庫，而不是網頁。"},{"h":"檢查自己的算術"},{"p":"最有價值的數學習慣不是速度，而是估計。在相信任何結果之前，先問問它的數量級是否正確：比輸入大或小，以及大致上是多少。除了這次之外，大多數算術錯誤在其他所有檢查中都倖免於難。\\n\\n首先四捨五入使得估算變得自由。將 0.375 舍入到 0.4，將 5/8 舍入到 0.6，比率顯然約為 2:3 — 足夠接近 3:5，足以確認您準確計算的分數。如果確切的答案和估計值不一致，那麼您發現的是輸入錯誤而不是捨入問題，而且您會在幾秒鐘內找到它。\\n\\n這也是為什麼計算器不能取代思考你所問的問題的原因。工具會完美地計算出錯誤的數量，唯一的防禦措施是知道答案應該是什麼樣的。"},{"h":"常見問題"},{"p":"**我的輸入傳送到任何地方了嗎？ ** 不。所有這些都在您的瀏覽器本地執行。\\n\\n**為什麼 0.1 加 0.2 不等於 0.3？ ** 因為 0.1 和 0.2 都不能用二進位浮點數精確表示。總和為 0.30000000000000004，這是最接近 0.3 的兩倍。\\n\\n**這些可以處理多大的階乘？ ** 在超出雙精度範圍之前最多可達 170。過了這個時間，答案就會以科學計數法顯示，然後就不再有意義。\\n\\n**我可以在程式碼中使用輸出嗎？ ** 可以。特別是對於小數到分數的結果，請對分子和分母使用整數運算，而不是轉換回小數。"},{"h":"單行版本"},{"p":"當涉及到金錢時，請使用精確的分數，請記住，階乘的爆炸速度比您預期的要快，質因數分解既是安全基礎，也是分數簡化技巧。"}]},"everyday-utility-tools":{"title":"13 個免費的日常實用工具：密碼、二維碼、計時器和文字編碼","description":"生成密碼、構建二維碼、執行計時器和時鐘以及解碼二進位制、十六進位制和密文——所有這些都可以使用不上傳任何內容的免費瀏覽器工具完成。","category":"實用工具","blocks":[{"p":"最後一組是垃圾抽屜。密碼、二維碼、秒錶、世界時鐘、拋硬幣以及四種將文字轉換為自身其他表示形式的工具。單獨來看是微不足道的，集合起來就是你在尷尬時刻需要的。\\n\\n總而言之，所有 13 個都在本地執行。對於一個密碼產生器來說，這並不是一個很好的東西——這就是該工具值得信任的全部原因。"},{"h":"密碼：真正重要的部分"},{"l":["[[password-generator|密碼產生器]] — 產生任意長度和字元集的強隨機密碼。","[[password-strength|密碼強度檢查器]] — 估計密碼在本地不易被猜測的程度。"]},{"b":"關於密碼強度的一個最重要的事實是：**長度勝過複雜性，而重複使用則勝過危險。 ** 由不相關的單字組成的 16 個字元的密碼比 10 個字元的亂七八糟的符號更強大且更容易輸入。同時，在一次洩漏中出現的一個重複使用的密碼會立即刪除它所觸及的每個帳戶。整個工作就是為每個網站產生一個獨特的長密碼。"},{"p":"如何估計力量也很重要。大多數檢查器都會近似搜尋空間的大小，這是一個合理的代理，但不是事實：「CorrectHorseBatteryStaple」在熵方面得分很高，而「P@ssw0rd1！」在字元多樣性方面得分很高，但在實踐中卻很糟糕，因為它出現在地球上每個破解單字表中。\\n\\n使用生成器來處理您關心的任何事情，如果您必須記住密碼，請使用由四個或五個不相關單片語成的密碼。這就是記憶力和強度實際上重疊的具體情況。"},{"h":"QR 碼：放入什麼內容"},{"l":["[[qr-code-generator|QR 程式碼產生器]] — 產生 URL、文字、Wi-Fi 詳細資料或聯絡資訊的 QR 程式碼。"]},{"p":"QR 碼是輸出品質完全由一個決定決定的工具：您輸入的資料量。短 URL 編碼為易於掃描的小程式碼。一段帶有標點符號的文字在小尺寸下編碼成密集且不可靠的內容。\\n\\n兩條實用規則。首先，在列印 200 個程式碼之前，請務必按照實際列印的尺寸測試掃描程式碼。其次，Wi-Fi 和純 URL 程式碼在不同手機上的行為有所不同 - 如果程式碼面向混合受眾，則更喜歡純 URL，而不是隨後連結的登陸頁面，因為它可以在任何地方使用，並且您可以更改它指向的位置。"},{"h":"時間：計時器、時鐘和時區陷阱"},{"l":["[[秒錶|線上秒錶]] — 一個普通碼錶，當您的手機在另一個房間時很有用。","[[pomodoro-timer|Pomodoro Timer]] — 25 分鐘的帶休息時間的專注塊，適合那些發現該結構有效的人。","[[世界時鐘|世界時鐘]] — 同時顯示多個城市的當前時間。"]},{"p":"世界時鐘因其一個特定原因而贏得一席之地：夏令時。世界上一半的日程安排錯誤不是算術錯誤，而是兩個城市上週相距四個小時，本週相距五個小時的時刻，卻沒有人檢查。\\n\\n在跨時區安排任何事情之前，請將兩個城市放入世界時鐘中並檢視 - 不要計算記憶體中的偏移量。這也是為什麼會議邀請應該帶有時區而不是僅僅一個小時。"},{"p":"關於番茄計時器：此技術適用於特定型別的任務－有限制的、專注的、不間斷的。它不適用於除錯，在除錯中，卡住時正確的做法是走開，而不是開始另一個 25 分鐘的區塊。有幫助時就使用它。"},{"h":"隨機性，誠實"},{"p":"[[random-number|Random Number Generator]] 和 [[list-randomizer|List Randomizer]] 涵蓋了實際出現的情況：在一個範圍內選擇一個數字，並將一個列表按公平順序排列。值得一句公平的話。兩者都使用偽隨機產生器，用於決定誰支付午餐費用與真正的硬幣沒有區別。對於任何重要的事情——有獎抽獎、附有資金的分配——你都需要一個可以審核的來源，而瀏覽器選項卡不是這樣的。這裡的價值在於剔除人類，因為人類在受到激勵時會做出糟糕的選擇。"},{"h":"編碼垃圾抽屜"},{"p":"在表示之間移動文字的四種工具。它們都不是加密，其區別值得說明，因為它經常令人困惑：編碼是任何人都可逆的，並且沒有金鑰。加密需要金鑰。"},{"l":["[[binary-text|Binary to Text]] — 在文字及其二進位表示形式之間進行轉換。","[[hex-text|十六進位到文字]] — 在文字和十六進位之間進行轉換，這是您在網路工具和偵錯器中最常見的表示形式。","[[caesar-cipher|Caesar Cipher]] — 將字母移動固定數量，經典的課堂密碼。","[[rot13-encoder|ROT13 Encoder]] — 將字母旋轉 13，這是一種特殊情況，它本身就是逆的。"]},{"p":"這些對於兩件事很有用。首先，理解文字如何變成位元組，這是當任何東西看起來亂碼時你需要的心理模型。其次，實際偵錯：當有效負載顯示為十六進位時，[[hex-text|Hex to Text]] 轉換器是您瞭解其內容的方式。\\n\\n它們對於隱藏任何東西沒有用。 ROT13 沒有金鑰——轉變是公開的——所以它不會向任何知道 ROT13 是什麼的人隱藏任何內容。凱撒密碼有 25 種可能的變化，人類在一分鐘內就能破解。"},{"h":"格式化事物的兩個"},{"l":["[[phone-formatter|電話號碼格式化程式]] — 將電話號碼標準化為一致的格式。","[[file-size-converter|檔案大小轉換器]] — 在 KB、MB、GB 和 TB 之間進行轉換，並解釋了十進位和二進位的差異。"]},{"p":"檔案大小轉換器有一個真正有價值的輸出：它告訴您為什麼驅動器公佈的數字比您的電腦報告的數字更大。供應商的銷售量為 10 次方，作業系統的報告量為 2 次方，每個規模的差距約為 7%。這不是一個錯誤，這是兩個約定。"},{"h":"一個有效的例子：亂碼的 API 響應"},{"p":"Webhook 驗證失敗，日誌中的有效負載類似於「\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f」。這是九十秒的診斷。"},{"l":["**1.轉換。 ** 將 `48656c6c6f` 貼到 [[hex-text|Hex to Text]] 轉換器中 — 結果是 `Hello`。它從來沒有亂碼，只是編碼。","**2.檢查形狀。 ** 上游的某些東西在簽章之前對有效負載進行十六進位編碼。簽名是根據原始文字計算的，並根據十六進位制進行驗證，因此比較失敗。","**3.排除另一個方向。 ** 如果日誌顯示可讀文本，則問題將相反：簽署編碼表格。","**4.確認大小宣告。 ** 如果同一日誌報告 1.2 MB 有效負載，[[file-size-converter|檔案大小轉換器]] 在任何人爭論配額之前確定該負載是十進位制還是二進位制。"]},{"h":"常見問題"},{"p":"**如果一切都在瀏覽器中執行，密碼產生器安全嗎？ ** 是的，而且比基於伺服器的密碼產生器更安全：密碼是在您的電腦上產生的並且從未傳輸，因此沒有任何內容可以攔截、記錄或洩露。代價是您無法恢復未儲存的密碼。\\n\\n**我可以相信虛擬硬幣翻轉嗎？ ** 對於隨意的決定，可以。對於任何帶有金錢或獎品的東西，請使用您可以審核的來源。\\n\\n**密碼安全嗎？ ** 不。沒有一個。 ROT13 和凱撒密碼沒有金鑰，其存在是為了教導編碼，而不是為了保護任何東西。\\n\\n**這些可以離線工作嗎？ ** 一旦頁面載入，是的 - 一切都是本地的。\\n\\n**轉換器的文字長度有限制嗎？ ** 只有您裝置的記憶體，因為沒有任何內容傳送到任何地方。"},{"h":"單行版本"},{"p":"長而獨特的密碼勝過短而聰明的密碼，二維碼的好壞取決於其中的資料，檢查時區偏移而不是計算它們，編碼不是加密。"}]}}')},17622,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"開発者ツールキット: 有料アプリに代わる 24 の無料ブラウザ ツール","description":"無料のブラウザベースの開発者ツールを使用して、データのフォーマット、変換、エンコード、デバッグを行うための実用的なガイドです。インストールもアカウントも必要ありません。ほとんどのツールは入力をローカルで処理します。","category":"開発者ツール","blocks":[{"p":"API 応答の再フォーマット、トークンのデコード、ハッシュのチェック、SQL のスラッグのインデントなど、週に 100 回行う小さなジョブのほとんどには、IDE、有料サブスクリプション、チーム ライセンスは必要ありません。 1 つのタブを 90 秒間開いておく必要があります。\\n\\n以下のコレクションは、書式設定、変換、エンコード、ハッシュ、デバッグをカバーする 24 個のブラウザベースのユーティリティです。それらはすべてページ内で完全に実行されます。データはサーバーに送信されることはありません。貼り付けるペイロードは通常、顧客のものであるため、これは開発者が通常認めている以上に重要です。"},{"h":"ブラウザベースのツールで置き換えられるものと置き換えられないもの"},{"p":"境界については現実的になってください。これらのツールは、1 回限りの、リスクが低く、頻度の高い作業を置き換えます。これらは、言語サーバー、デバッガー、テスト スイート、または実際の環境に対して繰り返し実行する必要があるものを置き換えるものではありません。"},{"l":["**適合性:** 応答を 1 回読み取り、単一の値をデバッグし、1 回のインポートでファイルを変換し、出荷前に形式をチェックします。","**適合性が悪い:** すべてのデプロイで同じチェックを実行し、何百ものファイルを変換し、CI で大声で失敗する必要があるものはすべて変換します。","**決してしない:** ローテーションできない資格情報を含むも​​の。有効なトークンではなく、取り消されたトークンを貼り付けます。"]},{"p":"そうは言っても、これらをブックマークしておく理由はスループットです。ブラウザーのタブで 40 秒かかるタスクは、スケジュールされることも、委任されることも、夜の 8 時に IDE を開く理由にもなりません。"},{"h":"データのフォーマットと変換"},{"p":"最も一般的な日常業務は、データを読み取り可能にすることです。 API が単一行の BLOB を返したり、同僚がチャット ウィンドウでタブが分割された構成ファイルを送信したり、スプレッドシートを JSON にエクスポートすると、それが 1 つの巨大な行として返されたりします。"},{"l":["[[json-formatter|JSON Formatter]] — ペイロードをインデント、検証、読み取ります。デバッグする前に使用してください。すべての「API が壊れています」チケットの半分は、実際には末尾にカンマが付いている不正な形式の JSON です。","[[json-validator|JSON Validator]] — きれいに出力するのではなく、厳密な合否の回答が必要な場合。","[[xml-formatter|XML Formatter]] — 2014 年以来誰も触れていない、SOAP 応答、RSS フィード、Maven POM に対する同じジョブ。","[[json-to-yaml|JSON to YAML]] および [[json-to-csv|JSON to CSV]] — 実際のシステムが実際に使用する形式間でデータを移動します。"]},{"p":"最後のグループは、1 つの特定のシナリオについて念頭に置いてください。クライアントはスプレッドシートを渡し、それを API で期待します。 CSV を JSON に直接変換する作業は 2 分で済み、午後のスクリプト作成は不要です。"},{"h":"エンコードとエスケープ"},{"p":"データは正常に見えるため、エンコードのバグは不釣り合いに迷惑です。値「San José & Sons」は「San Jos%C3%A9 %26 Sons」として到着し、ログには表示されない理由でデータベースとの比較が失敗します。"},{"l":["[[url-encoder|URL Encoder / Decoder]] — クエリ文字列が二重エンコードされているかどうかを即座に決定します。","[[base64-encoder|Base64 Encoder / Decoder]] — 証明書フラグメントをデコードするか、CSS にインライン化する小さなアセットをエンコードします。","[[html-entity-encoder|HTML エンティティ エンコーダ / デコーダ]] — ページ内にある「&」がテンプレートから来たのかデータから来たのかを調べます。","[[unicode-converter|Unicode Converter]] — 「壊れた」文字が、間違ったエンコーディングでレンダリングされた正当な文字であることが判明した場合に便利です。","[[number-base-converter|Number Base Converter]] — 電卓アプリを使用せずに、色、許可ビットマスク、またはメモリ アドレスをチェックします。"]},{"b":"実際の習慣: 値が文字化けして届いた場合は、それを一度に 1 層ずつデコードし、各結果を空白のフィールドに貼り付けます。最初のデコードで読み取り可能なテキストが生成された場合、問題は上流のどこかで 1 つ余分にエンコードされることです。 mojibake が生成される場合は、エスケープの問題ではなくエンコードの問題があり、これら 2 つは異なる修正が必要です。"},{"h":"識別子、ハッシュ、トークン"},{"p":"このグループは、開発者が一度書いて紛失した適切なローカル スクリプトを探して最も時間を浪費する場所です。"},{"l":["[[uuid-generator|UUID Generator]] — シード データ、フィクスチャ、またはクイック データベース行の v4 識別子を生成します。","[[md5-generator|MD5 / SHA Hash Generator]] - ダウンロードを検証するか、同一であるはずの 2 つのファイルが実際に同一であることを確認します。","[[timestamp-converter|Timestamp Converter]] — このリスト全体の中で最もよく使用される単一のツールです。ログ行に 1761000000 と表示されている場合、これはインシデントがデプロイ中に発生したか、デプロイ前に発生したかを示します。"]},{"p":"タイムスタンプ コンバーターがその役割を果たしているのは、1 つの特別な理由があります。それは、エポック番号は明確であると同時に役に立たないということです。何かがいつ起こったかを正確に知っているのに、同僚に話すことはできません。通常、一度変換すると、必要以上に激しい議論が解決されます。"},{"h":"比較とデバッグ"},{"l":["[[regex-tester|Regex Tester]] — ここでは最も利用率の高い項目です。正しく見えて何も一致しない正規表現は、誰も読まない場所で静かに失敗するため、開発において最もコストがかかるバグの 1 つです。","[[html-preview|HTML プレビュー]] — マークアップのフラグメントを反復処理して、実際にどのようにレンダリングされるかを確認します。"]},{"p":"空の文字列、Unicode 名、改行を含む値など、実際に予期される入力に対して正規表現をテストします。ほとんどのパターンは 3 番目のケースで破綻し、運用データが到着するまで誰も気づきません。"},{"h":"うまくいった例: 3 つのツール、1 つの退屈な出来事"},{"p":"これが私がこれらすべてをブックマークすることを確信した一連のシーケンスです。顧客は、火曜日に提出した記録が木曜日のレポートに欠落していると報告しました。"},{"l":["**1.タイムスタンプを変換します。** レポート ジョブは、レコードの作成時間をエポック値として記録しました。 [[timestamp-converter|Timestamp Converter]] は、レコードが現地時間の午後 11 時 (火曜日) に作成されたことを示しています。問題はレコードではなく、ジョブのタイムゾーンの想定です。","**2.ペイロードをフォーマットします。** [[json-formatter|JSON Formatter]] を介して保存された JSON を取得すると、クライアントが同じエンドポイントを 200 ミリ秒間隔で 2 回呼び出し、2 回目の書き込みが成功したため、レコードが null の日付フィールドで書き込まれていることがわかりました。","**3.ペイロードを比較します。** 両方のレコードには同じ API キーと同じクライアント タイムスタンプが含まれており、2 人の別々の顧客ではなく再試行を示していました。"]},{"p":"合計経過時間: 4 分。この調査の以前の試みでは、ログ作成プラットフォームで同じ根本原因を探しましたが、午後にかかり、誤った結論が得られました。"},{"h":"プライバシー: ローカルで実行することが実際の機能である理由"},{"p":"このライブラリのすべてのツールは、独自のブラウザ内で入力を処理します。何もアップロードされません。つまり、保持に関する質問やプロセッサーに関する同意はなく、3 分前に貼り付けた運用ペイロードに関する不快な会話もありません。\\n\\nこれが、ホストされた「ペーストビン API」やサインアップを求めるオンライン サービスよりも、これらのツールを好む理由です。また、これは、飛行機の中でも、地下室でも、あるいは企業の VPN がさらに別のドメインをブロックすることを決定したときでも、作業を続けることを意味します。"},{"p":"明確に述べておくべき注意点が 1 つあります。オフライン対応ページは、ページ自体がユーザーが想定しているコードである場合にのみ非公開になります。共有マシンでは、特にトークンをデコードしている場合は、プライベート ウィンドウを使用し、完了したらウィンドウを閉じます。"},{"h":"それらを中心としたワークフローを構築する"},{"p":"ツールは個別には簡単なものです。値は、「後で取得する」のではなく、すぐに取得する習慣がついています。後で、使い捨てのスクリプトを書いたり、IDE を開いたり、まったくチェックする価値がないと判断したときだからです。"},{"l":["個々の URL ではなくコレクションをブックマークし、ブラウザのツールバーに置きます。","何かが間違っていると思われる場合は、理論を立てる前にそれを確認してください。所要時間は 15 秒です。間違った結論のクラス全体を殺します。","同じことを 2 回チェックした場合は、それを自動化する必要がありますが、疑いを持って自動化しないでください。","本番環境の秘密を貼り付けないでください。不明な点は回転させてください。"]},{"h":"よくある質問"},{"p":"**これらのツールは無料ですか?** はい、完全に無料です。アカウントや使用制限はありません。基本的なものを妨げる有料枠はありません。\\n\\n**オフラインでも動作しますか?** ページが読み込まれると、はい、すべてがブラウザ内で実行されます。リロードには接続が必要です。\\n\\n**商業作品に使用できますか?** はい。出力はあなたのものであり、帰属の要件はありません。\\n\\n**API はありますか?** いいえ、それは意図的なものです。値はインターフェイスです。出力をエクスポートし、必要に応じて処理します。\\n\\n**代わりに CLI ツールをインストールしてみてはいかがでしょうか?** 3 回必要になったらインストールしてください。最初の 2 つはブラウザのタブを使用します。"}]},"text-tools-for-writers":{"title":"ライター、学生、マーケティング担当者向けの 17 の無料テキスト ツール","description":"ブラウザ内でローカルに実行される無料のブラウザ ツールを使用して、コピーをクリーンアップし、単語を正確に数え、リストをフォーマットし、下書きを公開可能なものに変換します。","category":"テキストツール","blocks":[{"p":"仕事で文章を書くときには、文章を書くこととは関係のない、驚くほど多くの機械的な単調な作業が伴います。貼り付けられた段落から余分な空白を削除したり、文字数制限をチェックしたり、名前のリストの重複を排除したり、何かを URL スラッグに変換したりするなどです。\\n\\nこれら 17 のツールは、その部分の仕事に使用されます。これらはすべてブラウザ内でローカルに実行されますが、これは細かいことではありません。貼り付けた下書きは未公開であることが多く、並べ替えているリストは誰かの個人データであることがよくあります。"},{"h":"書いたものを測定する"},{"p":"クライアントがちょうど 800 語を要求して編集者が 820 文字と答えるか、フォームがテキストを 1,995 文字で拒否し、改行がどこにあるかの説明がないまでは、単語数は解決したように見えます。"},{"l":["[[word-counter|Word Counter]] — 標準の尺度。貼り付け、読み取り、調整。","[[letter-counter|Letter Counter]] — 文字と文​​字の頻度をカウントします。ある段落が間違っていると感じる理由をデバッグするときに役立ちます。通常、それは繰り返しの文字パターンであり、夢ではありません。"]},{"p":"「単語」の意味についてのメモ: ハイフネーション、数字、URL については、カウンターによって意見が異なります。正確な数が重要な場合は、作品をチェックする担当者が使用するのと同じカウンターを使用し、事前に合意してください。これは、小さくて無意味な議論の本当に一般的な原因です。"},{"h":"書いていないコピーをクリーンアップする"},{"p":"受け取ったテキストのほとんどは、コピー＆ペーストによる二重スペース、迷走したタブ、急いで入力したことによる一貫性のない大文字の使用など、わずかに破損しています。手動で修正すると時間がかかり、エラーが発生しやすくなります。"},{"l":["[[text-trimmer|テキスト トリマー]] — すべての行から先頭と末尾の空白を一度に削除します。これにより、このリストの他のレポートよりも多くの「書式が壊れているように見える」レポートが修正されます。","[[text-case-converter|Text Case Converter]] — ブロック全体で文の大文字、タイトルの大文字、上下を切り替えます。また、誤って CAPS LOCK を押した段落を元に戻す最も速い方法でもあります。","[[text-to-slug|Text to Slug]] — 見出しをクリーンな URL スラグに変換します。タイトルを貼り付けて、スラッグを取得して完了です。"]},{"p":"スラッグ ジェネレーターには、URL 以外にも用途が 1 つあります。これは、人間が一目で解析できる可読性の高いファイル名またはアンカーを作成する高速な方法であり、「final_final_v3」よりも優れています。"},{"h":"リストの操作"},{"p":"リスト、目録、差し込み印刷、タグのクリーンアップ、アンケートの回答、スプレッドシートの列など、ある時点ですべてがリストになり、すべてのリストの並べ替え、重複排除、またはランダム化が必要になります。"},{"l":["[[duplicate-line-remover|Duplicate Line Remover]] — 2 つのリストを比較するか、1 つをクリーンアップします。出力には、削除された重複の数が示されるため、結果をレポートするときに役立ちます。","[[list-sorter|List Sorter]] — 構造化リスト入力の同じジョブ。","[[list-randomizer|List Randomizer]] — 描画順、クイズシーケンス、または枠で囲まれた候補リストをシャッフルして、誰もえこひいきを疑わないようにします。","[[line-number-adder|行番号加算器]] — チケットまたはコードレビューコメントで参照するために行に番号を付けます。"]},{"b":"ここでの古典的な罠は、重複排除されているように見えて実際には重複排除されていないリストです。「Apple」、「apple」、および「Apple.」は、コンピューターにとっては 3 つの異なる行です。重複排除を行う前に空白をトリミングし、末尾の句読点を取り除いてください。そうしないと、何もマージせず、データがクリーンであると判断されます。"},{"h":"プレビューとフォーマット"},{"p":"Markdown が勝利しましたが、一律ではありません。あなたのツールの半分はレンダリングし、半分はレンダリングしません。そして、半分は通常、上級者が貼り付ける必要があります。"},{"l":["[[markdown-preview|Markdown Preview]] - ライブ レンダリング。テーブルまたはネストされたリストがクライアントに届く直前に実際にどのように見えるかを確認できます。","[[text-repeater|Text Replyer]] — 文字列を N 回繰り返します。パディングやテストデータを生成したり、場合によっては文書内で要点を示したりするのに役立ちます。"]},{"p":"Markdown プレビューは、このセット全体の中で最も時間を節約するツールです。レンダリングされたドキュメント内の壊れた表は、生のテキスト内の壊れた表よりもはるかに目立ち、はるかに恥ずかしいためです。"},{"h":"残りの部分と、いつそれらに手を伸ばすか"},{"l":["[[random-string|Random String Generator]] — 読み取り可能なナンス、プレースホルダー ID、またはショート コードを生成します。誤って再利用することがないため、手動で何かを発明するよりも優れています。","[[morse-code|モールス信号変換器]] — 本当に楽しく、テーマのあるプロジェクトやパズルに役立つこともあります。"]},{"p":"これらは頻度の低いツールですが、ブックマークしておくのに費用はかかりません。また、「今すぐランダムに見える値が必要だが、値を作成する自信がない」という特定の問題を解決します。"},{"h":"現実的な編集パス"},{"p":"他の人からドラフトが届き、自分の名前で送信する必要がある場合に機能する順序は次のとおりです。"},{"l":["**1. Trim.** まず、[[text-trimmer|Text Trimmer]] を通じてドキュメント全体を実行します。空白の損傷は段落内に隠れて見えなくなります。","**2.大文字をきれいにします。** [[text-case-converter|Text Case Converter]] は見出しにのみ使用してください。大文字小文字の変換を完全なドラフトに適用しないでください。固有名詞が破壊されます。","**3.測定します。** 書く前に [[word-counter|Word Counter]] で長さをチェックして、その作品がどのような形になるかを確認してください。","**4.プレビュー。** Markdown が含まれている場合は、[[markdown-preview|Markdown Preview]] を使用してレンダリングします。","**5. Slug.** [[text-to-slug|Text to Slug]] を使用して、最後の見出しから最後に URL スラグを生成します。後で見出しを変更すると、スラッグが壊れます。"]},{"p":"パス全体には数分かかり、文書が技術的に正しい場合と明らかに間違っている場合の間違いのカテゴリーが排除されます。"},{"h":"プライバシーに関する作家の質問"},{"p":"**未公開のテキストはコンピューターから送信されますか?** いいえ。これらのツールはブラウザーでテキストを処理し、何も保存または送信されません。\\n\\n**長さ制限はありますか?** サーバー呼び出しがないため、サーバー側の制限はありません。非常に大きな入力は、デバイスのメモリによって制限されます。\\n\\n**出力を商業的に使用できますか?** はい、出所表示なしで自由に使用できます。\\n\\n**電話では機能しますか?** はい。レイアウトが適応され、同じコードが実行されます。"},{"h":"これらのツールが役に立たないこと"},{"p":"間違ったことを機械化するツールは、より早い間違いを生み出すだけなので、限界について率直に言う価値はあります。\\n\\nこれらのユーティリティでは、文章が明確であるかどうか、主張の出典があるかどうか、または聴衆にとってトーンが適切であるかどうかを判断することはできません。彼らは文字を数えます。彼らは散文を判断しません。このページのすべての指標で見事なスコアを獲得したテキストでも、依然として判読できない可能性があります。\\n\\n彼らは編集することもありません。個々の句を手動で大規模に書き換えていることに気付いた瞬間、テキスト ツールでは限界を迎え、適切なエディタ、正規表現による検索と置換 ([[regex-tester|Regex Tester]] はリハーサルに最適です)、またはスクリプトのいずれかが必要になります。 Mechanical レイヤーにはブラウザを使用し、それより上のすべてについては独自の判断をしてください。"},{"p":"彼らがやらないもう 1 つのことは、悪いソースを修正することです。スプレッドシートに「Dr」、「DR」、「Dr」など、一貫性のない名前が付けられている場合は、すべてが 1 つの列に表示されます。ツールは、指定した内容を忠実に並べ替えて重複を排除します。また、エントリが 1 つあるはずの場所に 3 つのエントリが残ったままになります。データのクリーニングは機械的な手順ではなく、決定によるものです。最初に標準形式を決定し、それを適用してから確認します。"},{"h":"作業リストを使いやすい状態に保つ"},{"p":"リード、リンク、参考文献、または用語のリストを維持している場合、それは静かに劣化します。障害モードは常に同じです。同一に見えるエントリは同一ではなく、1 回のマージでは何も削除されません。\\n\\n機能するメンテナンス パスは退屈です。空白をトリミングし、大文字を標準化し、末尾の句読点を削除してから重複を排除します。この順序で、重複排除後にトリミングするとエントリが失われます。アクティブなリストでこれを月に 1 回実行すると、2 時間の回復不能な混乱が 10 分の雑事に変わります。\\n\\n2 つのリストを調整する必要がある場合 (たとえば、登録リストと出席者リストの場合)、まず [[list-sorter|List Sorter]] を使用して両方を並べ替えて並べ、次に目視で比較します。比較する前に両側を分類することは、2 分間のチェックと 20 分間の探索の違いです。"},{"h":"持ち帰り"},{"p":"これらのツールはどれも賢いものではありません。それが重要です。彼らは、文章以外の機械的な 5 パーセントを削除するので、残りの 95 パーセントは実際には文章に関するものになります。毎月使用するものをブックマークし、残りは無視し、手動で空白を修正するのはやめてください。"}]},"calculators-and-converters-guide":{"title":"実際に扱う数値用の無料の計算機とコンバーター 18 個","description":"パーセンテージ、割引、チップ、ローン、日付、BMI、単位換算 — アカウント不要で推論を表示する無料のブラウザー計算機。","category":"電卓","blocks":[{"p":"誰もが請求書を割り勘し、割引が本当に割引であるかどうかを判断し、何も考えずに温度やファイル サイズを変換する必要があります。誰もが少なくとも一度は、公の場でこの間違いを犯します。\\n\\nこれは、お金、日付、健康、仕事や旅行で使用される単位の変換をカバーする 18 個の計算機とコンバーターのコレクションです。これらはすべてブラウザ内で実行されます。何も保存されないため、入力した数字は他人の仕事ではありません。"},{"h":"お金の計算"},{"p":"現実世界で最も一般的な数学は、何かの割合です。消費税、チップ、割引スタック、手数料、成長率。計算式は単純ですが、人々が計算を間違える理由はほとんど同じです。間違った基数にパーセンテージを適用してしまうからです。"},{"l":["[[discount-calculator|Discount Calculator]] — 最終価格を計算し、さらに重要なことに、どれだけ節約できたかを計算します。定価の値上げ後に実際には 20% になる「50% オフ」を見つけるのに役立ちます。","[[tip-calculator|チップ計算機]] — 請求書を割り勘し、パーセンテージを選択し、必要に応じて 1 人あたり四捨五入します。","[[loan-calculator|Loan Calculator]] — 月々の支払額と合計利息。これは、ローンが手頃かどうかを実際に決定する数値です。"]},{"b":"割引について: 20% 割引に続いてさらに 20% 割引を行う場合は 40% 割引ではなく、36% 割引となります。連続したパーセンテージは換算されたベースに基づいて計算されます。このリストにある計算ツールを使用すると、約 2 秒でそれを確認できます。これは、この記事で最も有用な算術事実です。"},{"p":"ローン計算機は特に注目に値します。重要な数字は月々の支払額ではありません。それはローンの全期間にわたって支払われる利息の総額です。それが実際の借入コストだからです。毎月の支払いが同じで条件が異なる 2 つのローンでは、合計利息が数万単位異なる場合があります。"},{"h":"日付とカウントダウン"},{"p":"日付の計算は、ほとんどの人が黙って間違えているところです。人間の月の長さは異なり、「暦月」を意味するか「30 日」を意味するかによって答えが変わるためです。"},{"l":["[[date-difference|Date Difference Calculator]] — 2 つの日付間の日数 (および合計月、年)。","[[days-until|Days until Calculator]] — 特定の日付までのカウントダウン。通常、人々が実際に望む営業日数が表示されます。","[[age-calculator|Age Calculator]] — 正確な年齢と日数、および次の誕生日。","[[timestamp-converter|Timestamp Converter]] — Unix タイムスタンプを実際の日付に変換します。これは、ログ、データベース、または API 応答を扱う場合に重要になります。"]},{"p":"人々をつまずかせる違い: 3 月 1 日から 4 月 1 日までの日数は 31 ですが、*月* の数は 1 です。通知期間またはサブスクリプション期間を計算している場合は、どちらの単位を意味するかを書面で明記してください。"},{"h":"正直なところ、健康数値"},{"l":["[[bmi-calculator|BMI Calculator]] — 標準カテゴリと以下の注意事項を含む肥満指数。"]},{"p":"BMI は集団レベルのスクリーニング統計です。この指標は、筋肉量、体組成、個人の健康状態については何も述べておらず、アスリート、高齢者、およびさまざまな民族グループのフィットネスの代用としては不十分です。判定としてではなく、複数のデータ ポイントの中の 1 つのデータ ポイントとして、または経時的な変化を追跡する方法として使用します。自分の健康に影響を与える決定を下している場合、適切なツールはブラウザーのタブではなく臨床医です。"},{"h":"単位換算：日常のもの"},{"p":"単位換算には、正確に計算しなければならない単位と、ざっくりと計算しなければならない単位の2種類があります。これらのツールは両方を処理しますが、作業はどちらがどちらであるかを覚えておくことです。"},{"l":["[[length-converter|Length Converter]] — メートル法から帝国単位への変換とその逆: ミリメートル、センチメートル、メートル、キロメートル、インチ、フィート、ヤード、マイル。","[[weight-converter|Weight Converter]] — グラム、キログラム、オンス、ポンド、トン。レシピや配送ラベルの前に確認するもの。","[[温度コンバータ|温度コンバータ]] — 摂氏、華氏、ケルビン。なぜなら、-10°C は 14°F ではなく、式は掛け算ではないからです。","[[speed-converter|速度コンバータ]] — km/h、mph、m/s、ノット。外国の制限速度またはエンジニアリング仕様に役立ちます。","[[area-converter|面積コンバータ]] — 平方メートル、平方フィート、エーカー、ヘクタール。これは、不動産を購入または賃貸するときに人々が悪く評価するものです。","[[volume-converter|体積コンバータ]] — リットル、ミリリットル、ガロン、カップ、立方メートル。","[[time-converter|Time Converter]] — 秒、分、時間、日、週。"]},{"b":"知っておく価値のある 2 つの変換の罠: 上のデータ ストレージ (マーケティング担当者は 10^3 を販売し、オペレーティング システムは 2^10 を報告)、および燃費 — 40 mpg (帝国ガロン) で見積もられる車は、帝国ガロンの方が大きいため、40 mpg (英ガロン) よりも 33 mpg (米国) に近くなります。 2 番目の方法を間違えると、レンタカーが非現実的に効率的に見えてしまいます。"},{"h":"必要ないと思われる 2 つ"},{"l":["[[random-number|Random Number Generator]] — ラッフル、ブラケット、またはクイック A/B スプリットのために範囲内で描画します。不正操作の疑いを払拭できるからこそ、有用です。","[[dice-roller|Dice Roller]] — ボード ゲームまたはテーブルトップ セッションで、実際のサイコロが最後にテーブルから転がり落ちた場合の、コイン投げから 20 面のサイコロまでのあらゆるサイコロ。"]},{"h":"電卓を正しく使う"},{"p":"電卓は、どの数字について質問しているのかがわかっている場合にのみ役に立ちます。 3つの習慣が違いを生みます。"},{"l":["**最初に四捨五入し、次に計算します。** 正確な数値によって決定が変わらない場合は、四捨五入を使用してください。四捨五入のパーセンテージを頭の中で確認できるので、入力ミスをキャッチできます。","**大きさの健全性をチェックします。** 結果を信じる前に、その結​​果が入力値よりも大きいか小さいか、そしておおよそどれくらい小さいかを考えてください。ほとんどの算術ミスは、このミスを除くすべてのチェックで残ります。","**出力ではなく入力を撮影します。** 後で計算を再実行するときに重要なのは、結論ではなく、何を仮定したかを知ることです。"]},{"h":"人々が実際に尋ねる質問"},{"p":"**私の番号はどこかに保存されていますか?** いいえ、計算はブラウザ内で行われ、何も送信または保持されません。\\n\\n**これらは電話でも動作しますか?** はい、電卓は片手で使用できるように作られています。\\n\\n**データ ストレージにはどの変換標準を使用しますか?** デフォルトでは 10 進数 (1 KB = 1000 バイト) です。これはストレージの販売方法だからです。オペレーティング システムはバイナリを報告するため、ドライブが縮小しているように見えます。このツールは、どちらか一方を黙って選択するのではなく、違いを説明します。\\n\\n**これらを自分のサイトに埋め込むことはできますか?** いいえ。代わりにブックマークしてください。そのコストはゼロであり、精度の問題はあなたのものです。"},{"h":"パーセンテージ: 重要な 4 つの間違い"},{"p":"人が日常生活で犯すほぼすべての間違いは、同じ 4 つの間違いのうちの 1 つです。名前を付けると回避可能になります。"},{"l":["**根拠が間違っています。** 「10% 上昇し、その後 10% 下落すると、最初の状態から離れる」は、両方とも異なる基礎に適用されるため、誤りです。 100 の 10 パーセントは 10 です。 90 の 10 パーセントは 9 です。","**パーセンテージのパーセンテージ。** 2 つの割引を重ねると、割引が乗算されます (0.8 × 0.8 = 0.64、つまり 36% オフ)。加算されません。","**パーセントとパーセント ポイント。** 金利が 4% から 6% になると 2 パーセント ポイント上昇しますが、相対的には 50% 上昇します。政治と医学はこの混乱に満ちていますが、それは必ずしも偶然ではありません。","**丸めが早すぎます。** パーセンテージを適用する前に中間ステップを丸めると、エラーが悪化します。最終的な数値まで完全な精度を維持し、最後のステップは頭の中でではなく電卓を使用して実行します。"]},{"p":"このセクション全体から習慣を 1 つだけ取り上げる場合は、次の習慣を選んでください。誰かにパーセンテージを引用する前に、それが「何の」パーセンテージなのかをもう一度言い直してください。数値に関する議論の半分は、実際には分母に関する議論です。"},{"h":"いつ計算をやめるべきかを知る"},{"p":"精度が役に立たなくなる時点があります。小数点以下第 2 位までの毎月の支払いに意味があります。合計費用を小数点第 8 位まで予測することは、ローンがストレスなく支払える額の範囲内に収まるかどうかという実際の決定を回避する方法です。\\n\\n有用なテストは感度に関する質問です。この入力が 10% 変動した場合、決定は変わりますか?そうでない場合は、絞り込むのをやめて、答えを決定する変数 (通常はレートではなく用語、または割引ではなく定価) に余分な時間を費やします。"},{"p":"そして、明確に述べておくべき境界線が 1 つあります。これらの計算機は算術演算であり、アドバイスではありません。貯蓄目標、退職日、借金完済計画はすべて、リスク、行動、時間に関する決定であり、ブラウザーのタブではそれらのどれも考慮することはできません。何を想定しているかを決めた後でのみ、数字が何を意味するのかを知ることができます。この違いは、電卓が役に立つか、それとも責任があるかの違いです。"},{"h":"一行バージョン"},{"p":"お金と日付の計算ツールを適切にブックマークし、BMI を判定ではなく 1 つのシグナルとして扱い、積み上げパーセンテージが増加することを覚えておいて、数値が契約上の何かに使用される場合は常に単位変換を確認します。これでほぼすべてがカバーされます。"}]},"image-and-design-tools":{"title":"ブラウザで実行できる 14 の無料の画像およびデザイン ツール","description":"Photoshop やデザイン スイートをインストールせずに、画像の圧縮、サイズ変更、準備を行い、CSS 効果、パレット、コントラスト チェック、ファビコンを生成します。","category":"デザインツール","blocks":[{"p":"画像の仕事には特有の問題があります。通常、仕事は小規模ですが、提供されるツールは膨大です。ヒーロー画像から 400 KB を削減するか、デザイナーが言及した 16 進値を取得するか、まだ誰も作成していないファビコンを生成する必要があります。それにはサブスクリプションは必要ありません。\\n\\n以下の 14 のツールは、画像の準備、色の操作、CSS 効果の生成、および失敗した小さな制作資産をカバーしています。すべてローカルで実行されますが、これはテキストよりも画像の方が重要です。圧縮したばかりの写真は、まだ公開していない写真であることがよくあります。"},{"h":"ウェブ用の画像を準備する"},{"p":"ほとんどの画像の問題は実際には重さの問題です。速度が遅いと感じるページには、通常、表示サイズより大きい画像が、間違ったフォーマットで、誰も疑問に思ったことのない品質設定で掲載されています。"},{"l":["[[image-compressor|Image Compressor]] — 画像の見た目をそのままにしながら、ファイル サイズを削減します。サイズ制限のあるフォームに何かをアップロードする前に、これを実行します。","[[image-resizer|Image Resizer]] — 必要な実際のピクセル寸法を設定します。これはより大きなメリットです。800 ピクセルで表示された 4000 ピクセルの画像には、必要なデータの 5 倍のデータが含まれています。","[[image-to-base64|Image to Base64]] — CSS、HTML、または電子メール テンプレートでインライン化するために、小さな画像をデータ URI に変換します。"]},{"b":"順序が重要です。最初にサイズ変更し、次に圧縮します。 4000 ピクセルの画像を圧縮すると、800 ピクセルにサイズ変更して同じ品質で圧縮するよりもはるかに重いファイルが生成されます。これは、コンプレッサーが廃棄されるピクセルに労力を費やすためです。"},{"p":"どれくらい圧縮すればいいのでしょうか？正直な答えは、「間違っていると思われるまで、一歩下がってください」です。写真のヒーロー画像の場合、通常の表示サイズでは 70 ～ 80% の品質でオリジナルと区別がつきません。ロゴ、スクリーンショット、または単色でハードエッジのあるものについては、PNG を使用し、より強力に圧縮します。これらにより得られる効果は大きく、損失は少なくなります。"},{"p":"実際的な経験則: ヒーロー画像の場合は 200 KB 未満、サムネイルの場合は 80 KB 未満であれば問題ありません。300 KB 未満にできない場合は、品質の問題ではなくサイズの問題がある可能性があります。"},{"h":"Base64: インライン化が正しい呼び出しの場合"},{"p":"画像を Base64 データ URI に変換すると、HTTP リクエストが削除されます。これは純粋に効果があるように思えます。通常はそうではありません。エンコードされた文字列はバイナリ ファイルよりも約 3 分の 1 大きく、個別にキャッシュすることができず、CSS や HTML が肥大化します。\\n\\n画像が小さい場合 (数キロバイト未満)、一度使用され、重要な場合にのみインライン化します。単一の電子メール テンプレートに小さなアイコンが含まれるのは典型的なケースです。ページ間で繰り返されるもの、または数キロバイトを超えるものについては、ファイルとして提供し、ブラウザーにキャッシュさせます。"},{"h":"透かし: 正直に削除できるもの"},{"l":[]},{"p":"これが何をするのかを明確にしてください。目に見えるマークを削除または隠します。基礎となるピクセルを再構築することはできません。上にペイントされた情報は失われ、それを元に戻すフィルターはありません。結果は、マークが無地の背景の上にある場合には見えないものから、細部の上にある場合には明らかな汚れまで多岐にわたります。\\n\\nもう 1 つ、はっきり言っておきたいことは、他人の透かしを削除してその結果を公開することは、ほとんどの法域で著作権の問題であり、捕まるかどうかに関係なくライセンス違反です。このツールは、自分の画像、またはライセンスを取得したストックからマークを削除する場合に使用します。"},{"h":"色: 変換、確認、選択"},{"p":"色は小さな間違いが非常に目立つ場所です。アクセシビリティに欠けるコントラスト比、実際には HSL トリプルである 16 進値、モニターでは一貫して見えるが、プロジェクターでは濁って見えるパレット。"},{"l":["[[color-converter|Color Converter]] — HEX、RGB、HSL 間を移動します。色相 210、彩度 40 パーセント、明度 50 パーセントは、16 進数の値よりも手動で調整する方がはるかに簡単であるため、HSL の読み方を学ぶ価値があります。","[[contrast-checker|コントラスト チェッカー]] — WCAG のしきい値と比較して、背景に対するテキストをテストします。これは、好みの問題ではなく実際のコンプライアンス問題を捉えるため、この記事で唯一最も役立つツールです。","[[color-palette|カラー パレット ジェネレーター]] — ブランド カラーから開始し、残りのスケールが必要な場合に、一貫したセットを生成します。"]},{"b":"対照的に、WCAG AA は、通常の本文テキストの場合は 4.5 対 1、大きなテキストの場合は 3 対 1 を要求します。ボタンに 2 つのブランド カラーのいずれかを選択する場合、アクセスしやすい色は通常、デザイナーが好む色ではありません。まず確認してから、引数にデータを指定します。"},{"p":"カラー ツールに関する注意点が 1 つあります。これらのツールはすべて、モニターが調整されていて、ページを見ている人の目が正常に機能していることを前提としています。どちらの仮定も安全ではありません。これが、主観的な組み合わせよりもコントラストを確認した組み合わせを好む理由です。"},{"h":"デザインツールを開かずに CSS 効果を適用する"},{"p":"グラデーションやレイヤードシャドウを手で書くのは本当に面倒な作業です。構文は面倒で、何を作成しているのか見えず、良い影と悪い影の違いは数ピクセルのぼかしです。"},{"l":["[[gradient-generator|CSS Gradient Generator]] — 線形および放射状のグラデーションを構築し、CSS を直接コピーします。","[[box-shadow-generator|Box Shadow Generator]] — 複数のシャドウを重ねます。これが、微妙な標高と重い落下を区別します。","[[border-radius-generator|Border Radius Generator]] — 形状を意図的に見せる非対称の半径を取得します。","[[text-shadow-generator|テキスト シャドウ ジェネレーター]] — 控えめに有用です。ほとんどのテキストの影は強すぎます。これにより、オフセットとブラーが消えるまで調整できます。"]},{"p":"4つすべての秘訣は抑制です。 2 つの影 (きつい暗い影と広くて柔らかい影) は、物理的な高さを示します。 1 つの影には 15 年前の Web サイトが表示されます。生成、コピーし、その存在が分からなくなるまで削除します。"},{"h":"誰もが忘れている制作資産"},{"l":["[[favicon-generator|Favicon Generator]] — サイトが実際に必要とする小さなアイコン セットを生成します。これがリストに載っているのは、ファビコンが完全に欠落している可能性が最も高い資産であり、ファビコンが欠落していると、完成したサイトが未完成に見える一般的なブラウザー ページのアイコンが表示されるためです。","[[emoji-picker|絵文字ピッカー]] — オペレーティング システムのピッカーを使用せずに、絵文字を参照、検索、コピーします。特定の記号を必要とするコピーを作成する場合に非常に役立ちます。"]},{"h":"実用的な例: ヒーローセクションの出荷"},{"p":"ここでは、クラスター全体が 1 つの実際のジョブを実行しています。ページには背景画像、見出し、ボタンを備えたヒーローが必要ですが、まだどれも構築されていません。"},{"l":["**1.スペースを予約します。** レイアウト内で画像スロットに固定の高さを与えます。これにより、実際の画像が表示されたときにページがジャンプするのではなく、最初のレンダリングから正しい形状が得られます。","**2.サイズを変更して圧縮します。** 実際の写真が到着したら、幅 1600 ピクセルの [[image-resizer|Image Resizer]] を実行し、次に 75% の [[image-compressor|Image Compressor]] を実行します。それは発送できるファイルです。","**3.テキストのコントラストをチェックします。** 写真の上に見出しがあると、古典的なコントラストの失敗になります。 [[contrast-checker|コントラスト チェッカー]] を使用して、暗いオーバーレイの強さ、または AA に合格する明るいテキストの色のいずれかを選択します。","**4.ボタンを構築します。** [[box-shadow-generator|Box Shadow Generator]] は標高を与え、[[color-converter|Color Converter]] はブランドカラーを CSS が必要とする形式に変換します。","**5. Ship.** [[favicon-generator|Favicon Generator]] からファビコンを追加して、タブが放棄されたように見えないようにします。これでセクションは完了です。"]},{"p":"ツールが 5 つあり、デザイン スイートはなく、すべての出力はコードに直接貼り付けることができる値です。"},{"h":"よくある質問"},{"p":"**私の画像はどこかにアップロードされていますか?** いいえ、圧縮、サイズ変更、Base64 変換はすべてブラウザ内で行われるため、ファイル サイズの制限やアップロード キューはありません。\\n\\n**画像を圧縮すると品質は低下しますか?** 定義上、常に品質が低下します。問題はそれが見えるかどうかだ。 70 ～ 80% の品質と正確な寸法では、通常はそうではありません。\\n\\n**サイズ変更した画像が依然として大きく見えるのはなぜですか?** 10 回中 9 回は、サイズ変更する前に圧縮したか、JPEG の方が良い写真を PNG として保存しています。\\n\\n**これらをクライアントの仕事に使用できますか?** はい、帰属や商業上の制限はありません。\\n\\n**携帯電話でも機能しますか?** はい、ただし、携帯電話での大きな写真のサイズ変更と圧縮は、サーバーではなくデバイスのメモリに依存します。"},{"h":"一行バージョン"},{"p":"圧縮する前にサイズを変更し、色について議論する前にコントラストを確認し、影を控えめに保ち、ファビコンを決して忘れないでください。いずれにしても、デザイン スイートが行っていたことのほとんどはこれです。"}]},"math-tools-for-real-numbers":{"title":"動作しない数値を計算するための 6 つの無料数学ツール","description":"科学表記法、小数から分数への変換、素数チェック、階乗および GCF/LCM — 間違いやすい数値作業のための無料のブラウザ ツール。","category":"数学ツール","blocks":[{"p":"コンピュータで実際に必要な数学は、試験で問われた数学ではありません。それは、この数値はシステムが予期する形式であるか、この分数は簡略化されているか、これがどれくらいの速さで増加するか、なぜ計算機とスプレッドシートが一致しないのか、ということです。\\n\\nこれら 6 つのツールはその領域をカバーします。これらはローカルで実行されます。これは、算術演算の場合、名前を付ける価値のある特定の利点を意味します。入力した数値はどこにも送信されないため、給与、残高、顧客数などの計算を何も考えずに確認できます。"},{"h":"機械が受け入れる形式に数値を取り込む"},{"p":"コンピューターは、小数を 2 進数として保存します。 0.1 はバイナリでは正確に表現できません。最も近い倍精度値は 0.1000000000000000055511151231257827 です。 0.1 + 0.2 を加算すると 0.30000000000000004 が得られます。これはデフォルトでは 0.3 として出力され、等価性チェックは静かに中断されます。"},{"l":["[[scientific-notation|Scientific Notation Converter]] — 標準形式と科学表記の間を移動します。これは、ほとんどのログ、スプレッドシート、API が実際に大きい数値と小さい数値を格納する方法です。","[[decimal-fraction|Decimal to Fraction]] — 小数を正確な分数に変換します。これは上記の問題の修正です。正確な分数演算の 0.1 + 0.2 は 3/10 であり、近似ではありません。"]},{"b":"合計が 0.0000000000000004 間違っているのを見たことがあれば、これが理由です。金融コードにおける標準的な答えは、整数セントまたは 10 進数ライブラリで動作し、浮動小数点では決して動作しないことです。スプレッドシートがスクリプトとほんの少しでも一致しないのを見たことがあるなら、それは同じバグが別の帽子をかぶったものです。"},{"p":"科学的記法は流暢に理解する価値があります。それは、対数行を読むのと目を細めて見るのとは違います。 6.022e23、1.6e-19、3e8 はアボガドロ数、素電荷、光の速度です。これらが数値ではなくノイズのように見える場合は、ツールを使用していくつかを変換すると、永久に修正されます。"},{"h":"素数、そしてなぜ誰もが気にするのか"},{"l":["[[prime-checker|素数チェッカー]] — 数値が素数かどうかをテストし、素数でない場合はその因数分解を確認します。","[[gcf-calculator|GCF LCM Calculator]] — 最大公約数と最小公倍数。"]},{"p":"素数は学校の演習ではありません。確立するすべての HTTPS 接続のセキュリティは、2 つの大きな素数を掛けるのは簡単だが、結果を因数分解するのは難しいという事実に依存します。この非対称性が RSA の基礎全体です。\\n\\n日常的な目的では、プライムチェックは主に分数に関するものです。分数を単純化するとは、上下を最大公約数で割ることを意味しますが、因数分解をしないとそれを求めることができません。これが、これら 2 つのツールが一緒に使用される理由です。因子をチェックし、1 ステップで GCF と LCM を取得します。"},{"p":"LCM の半分は人々が忘れるものであり、スケジュールの問題を解決するものです。つまり、18 日ごとと 12 日ごとに繰り返される 2 つのイベントが 36 日ごとに同時に発生します。同じ算術、異なる応用。"},{"h":"階乗とその爆発速度"},{"l":["[[factorial-calculator|階乗計算機]] — ん!答えがまだ意味のある値の場合。"]},{"p":"階乗は、デスクで出会うほとんどすべてのものよりも速く成長します。 10！約360万です。 20！は約 2.4 京であり、地球上の砂粒の数よりもはるかに大きいです。 52! (トランプをシャッフルする方法の数) は、およそ 8 に 67 桁が続きます。\\n\\n実際の結果として、すべての順列を列挙するプログラムは 5 項目では問題なく、8 項目では許容範囲内ですが、12 項目では永久にスタックしてしまいます。タスクが決して完了しないように感じられ、順列をループしている場合は、ほぼ確実にこれが原因です。これは、ほとんどの強引なアプローチに対する反論でもあり、意見ではなく算術として述べられています。"},{"h":"ローマ数字とその奇妙な点"},{"l":["[[roman-numerals|ローマ数字コンバータ]] — ローマ数字との間の変換を行います。"]},{"p":"このシステムは位置表記について何かを明らかにするため、ローマ数字は単に変換するだけでなく理解する価値があります。ゼロも位の値もありません。XI は、11 スティックを表すか 11,000 を表すかを問わず、11 を意味します。これが、ローマ数字の算術が本当に難しい理由であり、この体系が計算ではなく数えたり年代測定をするために何世紀にもわたって生き残った理由です。\\n\\n引き算ルールは人々が間違えやすい部分です。 IV は VI ではなく 4 です。 IXは9です。時計は有名な例外です。ビッグ ベンは IV ではなく IIII を使用していますが、その理由については歴史家が今でも議論しています。どのような場合でも、導出ではなく変換することが正しい判断です。"},{"h":"実際の例: 分数を手動でチェックする"},{"p":"レシピには0.375カップとグラム単位で読み取るスケールが必要だが、レポートでは比率が0.625と引用されており、どちらも誰かが急いで入力した数字のように見える。"},{"l":["**1.正確な分数を見つけます。** [[小数-分数|小数から分数]] ツールで 0.375 を実行します: 3/8。ラン0.625：5/8。どちらも、あなたが持っていない計算の習慣を必要としませんでした。","**2.比率を単純化します。** 3/8 対 5/8 を表すには、3 と 5 の GCF が必要です。[[gcf-calculator|GCF LCM Calculator]] では 1 が得られるため、比率は 3:5 であり、すでに最も単純です。","**3.階乗の主張を確認してください。** 誰かが 9 個の注文のキューに 362,880 個の手配があると言った場合、[[factorial-calculator|Factorial Calculator]] は 9 であることを確認します。まさにそれです。これで、ビルド時間の見積もりが妥当かどうかがわかりました。","**4.大きいものはすべて正規化します。** 1.5e9 ナノ秒を報告するサーバーは、[[scientific-notation|Scientific Notation Converter]] によれば 1.5 秒です。これは、遅延の問題と丸めアーチファクトの違いです。"]},{"h":"これらのツールが意図的に行わないこと"},{"p":"彼らは働いているところを見せませんし、教えません。数式が正しい理由を理解する必要がある場合、電卓は間違った道具です。電卓は理由もなく答えを与えます。そのため、人々は計算できても推論できなくなります。\\n\\nまた、任意の精度も実行しません。階乗や大規模な因数分解は、答えがまだ役立つ時点を超えると精度が失われ、ブラウザーのタブはコンピューター代数システムではありません。エンジニアリング、金融、暗号化など、正確さが本当に重要な場合は、Web ページではなく、正確な演算を備えた適切なライブラリを使用してください。"},{"h":"自分の算術をチェックする"},{"p":"最も価値のある数学的習慣は速度ではなく、推定です。結果を信じる前に、それが正しい桁数であるかどうか、つまり入力よりも大きいか小さいか、そしておおよそどのくらいかを考えてください。ほとんどの算術ミスは、このチェックを除くすべてのチェックで生き残ります。\\n\\n最初に四捨五入すると見積もりが無料になります。 0.375 を 0.4 に丸め、5/8 を 0.6 に丸めると、比率は明らかに約 2:3 になります。正確に計算した分数を確認するには、3:5 に十分近い値です。正確な答えと推定値が一致しない場合は、丸めの問題ではなく入力エラーが見つかったことになります。それは数秒で見つかりました。\\n\\nこれは、電卓が、計算機に求められたことについて考える代わりにならない理由でもあります。ツールは間違った量を完璧に計算してしまいますが、唯一の防御策は、答えがどのようなものであるかを知ることです。"},{"h":"よくある質問"},{"p":"**私の入力はどこかに送信されますか?** いいえ。これらはすべてブラウザ内でローカルに実行されます。\\n\\n**0.1 プラス 0.2 が 0.3 に等しくないのはなぜですか?** 0.1 も 0.2 も 2 進浮動小数点では正確に表現できないためです。合計は 0.30000000000000004 で、0.3 に最も近い 2 倍になります。\\n\\n**これらはどれくらいの大きさの階乗を処理できますか?** double の範囲を超える前に最大 170 まで。それを過ぎると、答えは科学的表記法で表示され、意味を持たなくなります。\\n\\n**出力をコードで使用できますか?** はい。特に、小数から分数への結果の場合は、小数に変換し直すのではなく、分子と分母に整数演算を使用します。"},{"h":"一行バージョン"},{"p":"お金が関係する場合は正確な分数を使用し、階乗は予想よりも速く爆発することを覚えておいてください。素因数分解はセキュリティの基盤であると同時に分数を単純化するトリックでもあります。"}]},"everyday-utility-tools":{"title":"13 個の無料日常ユーティリティ: パスワード、QR コード、タイマー、テキスト エンコーディング","description":"パスワードの生成、QR コードの作成、タイマーと時計の実行、バイナリ、16 進数、および暗号テキストのデコードはすべて、アカウントを必要とせずにローカルで実行される無料のブラウザ ツールを使用して実行できます。","category":"ユーティリティツール","blocks":[{"p":"この最後のグループはジャンク引き出しです。パスワード、QR コード、ストップウォッチ、世界時計、コイン投げ、およびテキストをそれ自体の別の表現に変換する 4 つのツール。個々には些細なことですが、集合的には気まずいときに必要なものです。\\n\\n一貫して、13 台すべてがローカルで実行されます。パスワード生成ツールとしては、これはあまり良いことではありません。これこそが、このツールが信頼できる理由のすべてです。"},{"h":"パスワード: 実際に重要な部分"},{"l":["[[password-generator|Password Generator]] — 任意の長さと文字セットの強力なランダムパスワードを生成します。","[[password-strength|パスワード強度チェッカー]] — ローカルでのパスワードの推測に対する耐性を推定します。"]},{"b":"パスワードの強度に関する最も重要な事実は次のとおりです。**長さは複雑さよりも優れており、再利用は危険性よりも優れています。** 無関係な単語で構成された 16 文字のパスワードは、10 文字の記号の混乱よりも強力で、はるかに入力しやすいです。一方、再利用された 1 つのパスワードが侵害で判明し、接触したすべてのアカウントが一度に削除されます。サイトごとに異なる長いパスワードを生成することが仕事全体です。"},{"p":"強度をどのように見積もるかも重要です。ほとんどのチェッカーは、検索スペースのサイズを近似しますが、これは妥当な代用ですが、真実ではありません。「CorrectHorseBatteryStaple」はエントロピーで良いスコアを示しますが、「P@ssw0rd1!」は文字の多様性で良いスコアを示しますが、地球上のすべてのクラッキング単語リストに含まれるため、実際には悪いスコアを示します。\\n\\n関心のあるものにはジェネレーターを使用し、パスワードを覚えておく必要がある場合は、無関係な 4 ～ 5 つの単語からなるパスフレーズを使用します。これは、記憶力と強さが実際に重なっている特定のケースです。"},{"h":"QRコード：何を入れるか"},{"l":["[[qr-code-generator|QR コード ジェネレーター]] — URL、テキスト、Wi-Fi の詳細、または連絡先情報の QR コードを生成します。"]},{"p":"QR コードは、入力するデータの量という 1 つの決定によって出力品質が完全に決まるツールの 1 つです。短い URL は、小さくて簡単にスキャンできるコードにエンコードされます。句読点のあるテキストの段落は、小さいサイズでは高密度で信頼性の低いものにエンコードされます。\\n\\n2 つの実践的なルール。まず、コードを 200 個印刷する前に、実際に印刷されるサイズでコードを必ずテストスキャンしてください。第 2 に、Wi-Fi コードとプレーン URL コードは、携帯電話によって動作が異なります。コードがさまざまな視聴者に送信される場合は、その後にリンクするランディング ページよりもプレーン URL を優先します。これは、どこでも機能し、どこを指すかを変更できるためです。"},{"h":"時間: タイマー、時計、タイムゾーンの罠"},{"l":["[[stopwatch|Online Stopwatch]] — 携帯電話が他の部屋にあるときに便利な普通のストップウォッチです。","[[pomodoro-timer|Pomodoro Timer]] — 休憩を挟んだ 25 分間の集中ブロック。その構造がうまく機能していると感じる人向け。","[[world-時計|世界時計]] — 複数の都市の現在時刻を同時に表示します。"]},{"p":"世界時計がその役割を果たしているのには、サマータイムという特別な理由があります。世界のスケジュールミスの半分は算術ミスではなく、2つの都市の時差が先週は4時間、今週は5時間だったのに誰もチェックしなかった瞬間だ。\\n\\nタイムゾーンをまたいで何かをスケジュールする前に、両方の都市を世界時計に入れて確認してください。メモリからオフセットを計算するのではありません。これは、会議への招待状に時間ではなくタイムゾーンを記載する必要がある理由でもあります。"},{"p":"ポモドーロ タイマーについて: このテクニックは、制限があり、集中し、中断されない、特定の種類のタスクに有効です。デバッグでは機能しません。行き詰まったときの正しい行動は、別の 25 分のブロックを開始するのではなく、立ち去ることです。役立つときに使用してください。"},{"h":"正直言ってランダム"},{"p":"[[random-number|Random Number Generator]] と [[list-randomizer|List Randomizer]] は、範囲内の数値を選択し、リストを公正な順序に並べるなど、実際に発生するケースをカバーします。公平性に関しては一文の価値がある。どちらも疑似ランダム生成器を使用しており、誰が昼食代を支払うかを決定するために、本物のコインと区別がつきません。賞金付きの抽選や金銭を伴う割り当てなど、重要な事柄については、監査できるソースが必要ですが、ブラウザーのタブはそうではありません。ここでの価値は、動機付けられたときに間違った選択をする人間を排除することです。"},{"h":"エンコードジャンク引き出し"},{"p":"表現間でテキストを移動する 4 つのツール。それらはいずれも暗号化ではありません。エンコーディングは誰でも元に戻すことができ、キーがありません。エンコーディングは常に混同されているため、区別する価値があります。暗号化にはキーが必要です。"},{"l":["[[binary-text|バイナリからテキスト]] — テキストとそのバイナリ表現の間で変換します。","[[hex-text|16 進数からテキスト]] — テキストと 16 進数の間で変換します。これは、ネットワーク ツールやデバッガーで最もよく見られる表現です。","[[caesar-cipher|Caesar Cipher]] — 文字を一定量シフトする、古典的な教室暗号です。","[[rot13-encoder|ROT13 Encoder]] — 文字を 13 回転させます。これは、独自の逆である特殊なケースです。"]},{"p":"これらは正確に 2 つのことに役立ちます。まず、テキストがどのようにバイトになるかを理解します。これは、何かが文字化けしているように見えるときに必要なメンタル モデルです。次に、実際のデバッグです。ペイロードが 16 進数で表示される場合、[[hex-text|Hex to Text]] コンバーターを使用して、その内容を確認します。\\n\\n何かを隠すのには役に立ちません。 ROT13 にはキーがありません。シフトは公開されています。そのため、ROT13 が何であるかを知っている人に対して何も隠しません。シーザー暗号には 25 通りのシフトがあり、人間は 1 分で解読できます。"},{"h":"物事をフォーマットする 2 つ"},{"l":["[[phone-formatter|電話番号フォーマッタ]] — 電話番号を一貫した形式に正規化します。","[[file-size-converter|File Size Converter]] — 10 進数と 2 進数の区別を使用して、KB、MB、GB、TB の間で変換します。"]},{"p":"ファイル サイズ コンバーターには、本当に貴重な出力が 1 つあります。それは、ドライブがコンピューターのレポートよりも大きな数値をアドバタイズする理由を示します。ベンダーは 10 の累乗で販売し、オペレーティング システムは 2 の累乗で報告しており、その差はどの規模でも約 7% です。それは間違いではなく、2 つの慣例です。"},{"h":"うまくいった例: 文字化けした API レスポンス"},{"p":"Webhook が検証に失敗し、ログ内のペイロードは「\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f」のようになります。これは92番目の診断です。"},{"l":["**1. Convert.** `48656c6c6f` を [[hex-text|Hex to Text]] コンバータに貼り付けます。結果は `Hello` になります。文字化けしたことはなく、エンコードされただけです。","**2.形状を確認してください。** 上流の何かが署名前にペイロードを 16 進エンコードしています。署名は元のテキストに対して計算され、16 進数に対して検証されるため、比較は失敗します。","**3.他の方向は除外してください。** ログに読み取り可能なテキストが表示されていた場合、問題は逆に、エンコードされたフォームに署名することになるでしょう。","**4.サイズの主張を確認します。** 同じログが 1.2 MB のペイロードを報告する場合、[[file-size-converter|File Size Converter]] は、クォータについて議論する前に、それが 10 進数か 2 進数かを決定します。"]},{"h":"よくある質問"},{"p":"**すべてがブラウザで実行される場合、パスワード ジェネレータは安全ですか?** はい、サーバーベースのものよりも安全です。パスワードはマシン上で生成され、決して送信されないため、傍受、記録、侵害されるものは何もありません。その代償として、保存しなかったパスワードを回復することはできません。\\n\\n**仮想コイン投げを信頼できますか?** 偶然の決定については、信頼できます。金銭や賞品が添付されているものについては、監査できる情報源を使用してください。\\n\\n**暗号は安全ですか?** いいえ、どれも安全ではありません。 ROT13 暗号とシーザー暗号には秘密鍵がなく、何かを保護するためではなく、エンコードを教えるために存在します。\\n\\n**これらはオフラインでも機能しますか?** ページが読み込まれると、はい、すべてがローカルになります。\\n\\n**コンバーターのテキストの長さに制限はありますか?** どこにも何も送信されないため、デバイスのメモリのみです。"},{"h":"一行バージョン"},{"p":"長い固有のパスワードは短い巧妙なパスワードよりも優れており、QR コードの品質はその中のデータと同じであり、タイムゾーン オフセットを計算するのではなくチェックし、エンコードは暗号化ではありません。"}]}}')},94541,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"개발자 툴킷: 유료 앱을 대체하는 24가지 무료 브라우저 도구","description":"무료 브라우저 기반 개발자 도구를 사용하여 데이터 형식 지정, 변환, 인코딩 및 디버깅에 대한 실용적인 가이드입니다. 설치나 계정이 필요하지 않습니다. 대부분의 도구는 입력을 로컬로 처리합니다.","category":"개발자 도구","blocks":[{"p":"API 응답 형식 변경, 토큰 디코딩, 해시 확인, SQL 슬러그 들여쓰기 등 일주일에 수백 번 수행하는 대부분의 소규모 작업에는 IDE, 유료 구독 또는 팀 라이선스가 필요하지 않습니다. 90초 동안 하나의 탭을 열어야 합니다.\\n\\n아래 컬렉션은 서식 지정, 변환, 인코딩, 해싱 및 디버깅을 다루는 24개의 브라우저 기반 유틸리티입니다. 이들 모두는 전적으로 귀하의 페이지에서 실행됩니다. 귀하의 데이터는 결코 서버로 전송되지 않습니다. 이는 개발자가 일반적으로 인정하는 것보다 더 중요한데, 귀하가 붙여넣는 페이로드는 일반적으로 고객의 것이기 때문입니다."},{"h":"브라우저 기반 도구로 대체할 수 있는 것과 대체할 수 없는 것"},{"p":"경계에 대해 현실적으로 생각하십시오. 이러한 도구는 일회성, 저부담, 빈번한 집안일을 대체합니다. 언어 서버, 디버거, 테스트 스위트 또는 실제 환경에 대해 반복적으로 실행하는 데 필요한 모든 것을 대체하지 않습니다."},{"l":["**좋은 적합성:** 응답을 한 번 읽고, 단일 값을 디버깅하고, 한 번의 가져오기를 위해 파일을 변환하고, 배송 전에 형식을 확인합니다.","**잘못된 적합성:** 배포할 때마다 동일한 검사를 실행하여 수백 개의 파일을 변환하고 CI에서 크게 실패해야 하는 모든 파일을 변환합니다.","**절대 안 함:** 자격 증명과 관련된 항목은 교체할 수 없습니다. 실제 토큰이 아닌 취소된 토큰을 붙여넣으세요."]},{"p":"즉, 이러한 북마크를 유지하는 이유는 처리량입니다. 브라우저 탭에서 40초가 걸리는 작업은 결코 예약되거나 위임되지 않으며 저녁 8시에 IDE를 열 이유가 되지 않습니다."},{"h":"데이터 형식 지정 및 변환"},{"p":"가장 일반적인 일상 작업은 데이터를 읽을 수 있게 만드는 것입니다. API는 한 줄짜리 blob을 반환하고, 동료가 채팅 창에서 탭이 손상된 구성 파일을 보내거나, 스프레드시트를 JSON으로 내보냈는데 거대한 한 줄로 돌아왔습니다."},{"l":["[[json-formatter|JSON Formatter]] — 페이로드를 들여쓰기하고, 검증하고, 읽습니다. 디버깅하기 전에 이를 사용하십시오. 모든 \\"API가 손상되었습니다\\" 티켓 중 절반은 실제로 뒤에 쉼표가 있는 잘못된 JSON입니다.","[[json-validator|JSON Validator]] — 예쁜 글자보다는 엄격한 합격/실패 답변이 필요할 때.","[[xml-formatter|XML Formatter]] — 2014년 이후 누구도 건드리지 않은 SOAP 응답, RSS 피드 및 Maven POM에 대한 동일한 작업입니다.","[[json-to-yaml|JSON에서 YAML로]] 및 [[json-to-csv|JSON에서 CSV로]] — 실제 시스템이 실제로 사용하는 형식 간에 데이터를 이동합니다."]},{"p":"특정 시나리오의 경우 마지막 그룹을 염두에 두십시오. 클라이언트가 스프레드시트를 건네주고 API에서 이를 기대합니다. CSV를 JSON으로 직접 변환하는 작업은 오후의 스크립팅 작업이 아닌 2분이면 완료됩니다."},{"h":"인코딩 및 이스케이프"},{"p":"인코딩 버그는 데이터가 괜찮아 보이기 때문에 불균형적으로 짜증스럽습니다. \\"San José & Sons\\" 값은 \\"San Jos%C3%A9 %26 Sons\\"로 도착하며 로그에 표시되지 않는 이유로 데이터베이스와의 비교가 실패합니다."},{"l":["[[url-encoder|URL 인코더/디코더]] — 쿼리 문자열이 이중 인코딩되었는지 즉시 확인합니다.","[[base64-encoder|Base64 인코더/디코더]] — 인증서 조각을 디코딩하거나 CSS에서 인라인으로 작은 자산을 인코딩합니다.","[[html-entity-encoder|HTML Entity Encoder / Decoder]] — 페이지에 있는 \\"&\\"가 템플릿에서 나온 것인지 아니면 데이터에서 나온 것인지 알아보세요.","[[unicode-converter|유니코드 변환기]] — \\"깨진\\" 문자가 잘못된 인코딩으로 렌더링된 올바른 문자로 판명될 때 유용합니다.","[[number-base-converter|Number Base Converter]] — 계산기 앱 없이 색상, 권한 비트마스크 또는 메모리 주소를 확인하세요."]},{"b":"실용적인 습관: 값이 왜곡되어 도착하면 한 번에 한 레이어씩 디코딩하고 각 결과를 빈 필드에 붙여넣습니다. 첫 번째 디코드에서 읽을 수 있는 텍스트가 생성되면 문제는 업스트림 어딘가에 추가로 인코딩된 것입니다. mojibake가 생성되면 이스케이프 문제가 아닌 인코딩 문제가 있는 것이므로 이 두 가지 문제는 서로 다른 수정이 필요합니다."},{"h":"식별자, 해시 및 토큰"},{"p":"이 그룹은 개발자가 한 번 작성하고 잃어버린 올바른 로컬 스크립트를 찾는 데 가장 많은 시간을 낭비하는 곳입니다."},{"l":["[[uuid-generator|UUID 생성기]] — 시드 데이터, 고정 장치 또는 빠른 데이터베이스 행에 대한 v4 식별자를 생성합니다.","[[md5-generator|MD5 / SHA 해시 생성기]] — 다운로드를 확인하거나 동일해야 하는 두 파일이 실제로 있는지 확인합니다.","[[timestamp-converter|Timestamp Converter]] — 이 전체 목록에서 가장 많이 사용되는 단일 도구입니다. 로그 줄에 1761000000이라고 표시되면 이는 배포 중에 사건이 발생했는지 아니면 배포 전에 발생했는지 여부를 알려줍니다."]},{"p":"타임스탬프 변환기는 한 가지 특정한 이유 때문에 유지됩니다. 즉, 에포크 번호는 명확하고 동시에 쓸모가 없습니다. 언제 무슨 일이 일어났는지 정확히 알지만 동료에게 말할 수는 없습니다. 한 번 변환하면 일반적으로 필요한 것보다 더 큰 논쟁이 해결됩니다."},{"h":"비교 및 디버깅"},{"l":["[[regex-tester|Regex Tester]] — 여기서 가장 영향력이 높은 항목입니다. 정확해 보이고 아무것도 일치하지 않는 정규식은 개발에서 가장 비용이 많이 드는 버그 중 하나입니다. 아무도 읽지 않는 곳에서 조용히 실패하기 때문입니다.","[[html-preview|HTML 미리보기]] — 마크업 조각을 반복하여 실제로 렌더링되는 방식을 확인합니다."]},{"p":"빈 문자열, 유니코드 이름, 줄바꿈이 포함된 값을 포함하여 실제로 예상하는 입력에 대해 정규식을 테스트합니다. 대부분의 패턴은 세 번째 경우에 깨지며 생산 데이터가 도착할 때까지 아무도 이를 알아차리지 못합니다."},{"h":"실제 사례: 세 가지 도구, 하나의 지루한 사건"},{"p":"이 모든 것을 북마크에 추가하게 된 순서는 다음과 같습니다. 고객이 화요일에 제출한 기록이 목요일 보고서에서 누락되었다고 보고했습니다."},{"l":["**1. 타임스탬프를 변환합니다.** 보고 작업은 레코드 생성 시간을 에포크 값으로 기록했습니다. [[timestamp-converter|Timestamp Converter]]는 기록이 화요일인 현지 오후 11시에 생성되었음을 보여줍니다. 문제는 기록이 아니라 작업의 시간대 가정이었습니다.","**2. 페이로드 형식을 지정합니다.** [[json-formatter|JSON Formatter]]를 통해 저장된 JSON을 사용하면 클라이언트가 200ms 간격으로 동일한 끝점을 두 번 호출하고 두 번째 쓰기가 성공했기 때문에 레코드가 null 날짜 필드로 기록된 것으로 나타났습니다.","**3. 페이로드를 비교합니다.** 두 레코드 모두 동일한 API 키와 동일한 클라이언트 타임스탬프를 전달했으며, 이는 두 명의 개별 고객이 아닌 재시도를 나타냅니다."]},{"p":"총 경과 시간: 4분. 로깅 플랫폼에서 동일한 근본 원인을 찾은 이 조사의 이전 시도는 오후 시간이 걸렸고 잘못된 결론을 내렸습니다."},{"h":"개인 정보 보호: 로컬로 실행하는 것이 실제 기능인 이유"},{"p":"이 라이브러리의 모든 도구는 자체 브라우저 내에서 입력을 처리합니다. 아무 것도 업로드되지 않습니다. 즉, 보존 질문도 없고 프로세서 계약도 없으며 3분 전에 붙여넣은 프로덕션 페이로드에 대한 불편한 대화도 없습니다.\\n\\n이것이 호스팅된 \\"pastebin API\\"나 가입을 요청하는 온라인 서비스보다 이러한 도구를 선호하는 이유입니다. 이는 또한 비행기 안, 지하실에서 또는 회사 VPN이 또 다른 도메인을 차단하기로 결정한 경우에도 계속 작업한다는 것을 의미합니다."},{"p":"명확하게 언급할 가치가 있는 한 가지 주의 사항: 오프라인 가능 페이지는 페이지 자체가 사용자가 생각하는 코드인 경우에만 비공개입니다. 공유 컴퓨터에서는 개인 창을 사용하고 작업이 끝나면 닫으십시오. 특히 토큰을 디코딩한 경우에는 더욱 그렇습니다."},{"h":"이를 중심으로 워크플로우 구축"},{"p":"도구는 개별적으로 사소합니다. 값은 \\"나중에 확인\\"하는 대신 즉시 확인하는 습관에 있습니다. 나중에는 일회용 스크립트를 작성하거나 IDE를 열거나 전혀 확인할 가치가 없다고 결정할 때이기 때문입니다."},{"l":["개별 URL이 아닌 컬렉션을 북마크하고 브라우저 도구 모음에 넣으세요.","뭔가 잘못된 것 같으면 이론을 세우기 전에 먼저 확인하세요. 15초가 소요됩니다. 잘못된 결론의 전체 클래스를 죽입니다.","동일한 항목을 두 번 확인했다면 자동화하라는 신호입니다. 그러나 의심스러운 경우에는 자동화하지 마세요.","생산 비밀을 붙여 넣지 마십시오. 확실하지 않은 것은 무엇이든 회전하세요."]},{"h":"자주 묻는 질문"},{"p":"**이 도구는 무료입니까?** 예, 전적으로 계정이나 사용 제한이 없습니다. 기본적인 것을 방해하는 유료 계층은 없습니다.\\n\\n**오프라인에서도 작동하나요?** 일단 페이지가 로드되면 그렇습니다. 모든 것이 브라우저에서 실행됩니다. 새로고침하려면 연결이 필요합니다.\\n\\n**상업적 작업에 사용할 수 있나요?** 예. 출력은 귀속 요구 사항 없이 귀하의 것입니다.\\n\\n**API가 있나요?** 아니요, 의도적인 것입니다. 가치는 인터페이스입니다. 출력을 내보내고 원하는 대로 처리하세요.\\n\\n**그냥 CLI 도구를 설치하면 어떨까요?** 세 번 필요할 때마다 설치하세요. 처음 두 개에는 브라우저 탭을 사용하세요."}]},"text-tools-for-writers":{"title":"작가, 학생, 마케팅 담당자를 위한 17가지 무료 텍스트 도구","description":"브라우저에서 로컬로 실행되는 무료 브라우저 도구를 사용하여 사본을 정리하고, 단어를 정확하게 계산하고, 목록 형식을 지정하고, 초안을 게시 가능한 것으로 변환하세요.","category":"텍스트 도구","blocks":[{"p":"업무용 글쓰기에는 붙여넣은 단락에서 길 잃은 공백 제거, 단어 제한 확인, 이름 목록 중복 제거, URL 슬러그로 변환 등 놀랍도록 기계적 고된 일이 수반됩니다.\\n\\n이 17개의 도구는 작업의 해당 부분을 위한 것입니다. 그것들은 모두 브라우저에서 로컬로 실행되는데 이는 작은 세부 사항이 아닙니다. 붙여넣은 초안은 게시되지 않은 경우가 많으며 정렬 중인 목록은 누군가의 개인 데이터인 경우가 많습니다."},{"h":"당신이 쓴 내용을 측정"},{"p":"클라이언트가 정확히 800단어를 요구하고 편집자가 820단어라고 말하거나 양식에서 개행 문자가 어디로 갔는지에 대한 설명 없이 1,995자에서 텍스트를 거부할 때까지 단어 수는 해결된 것처럼 들립니다."},{"l":["[[word-counter|단어 카운터]] — 표준 측정값입니다. 붙여넣고, 읽고, 조정하세요.","[[letter-counter|Letter Counter]] — 문자와 문자 빈도를 계산합니다. 한 단락이 잘못된 것 같은 이유를 디버깅할 때 유용합니다. 일반적으로 꿈이 아니라 반복되는 문자 패턴입니다."]},{"p":"\\"단어\\"의 의미에 대한 참고 사항: 서로 다른 카운터는 하이픈 넣기, 숫자 및 URL에 동의하지 않습니다. 정확한 숫자가 중요한 경우에는 작업을 확인하는 사람이 사용하는 것과 동일한 카운터를 사용하고 사전에 동의하세요. 이것은 사소하고 무의미한 논쟁의 진정한 공통 소스입니다."},{"h":"작성하지 않은 사본 정리"},{"p":"수신하는 대부분의 텍스트는 약간 손상되었습니다. 복사하여 붙여넣을 때 공백이 두 개, 탭이 흩어지고, 급하게 입력하여 대문자가 일관되지 않습니다. 손으로 수정하는 것은 느리고 오류가 발생하기 쉽습니다."},{"l":["[[text-trimmer|Text Trimmer]] — 모든 줄의 앞뒤 공백을 한 번에 제거합니다. 이는 이 목록의 다른 어떤 것보다 더 많은 \\"서식이 깨져 보이는\\" 보고서를 수정합니다.","[[text-case-converter|텍스트 케이스 변환기]] — 블록 전체에서 문장 케이스, 제목 케이스, 대문자와 소문자 사이를 전환합니다. 또한 실수로 CAPS LOCK 문단을 실행 취소하는 가장 빠른 방법입니다.","[[text-to-slug|Text to Slug]] — 헤드라인을 깨끗한 URL 슬러그로 바꿉니다. 제목을 붙여넣고 슬러그를 완성하세요."]},{"p":"슬러그 생성기는 URL 외에도 한 가지 용도가 있습니다. 사람이 한 눈에 파싱할 수 있는 읽기 쉬운 파일 이름이나 앵커를 만드는 빠른 방법이며, 이는 `final_final_v3`보다 뛰어납니다."},{"h":"목록 작업"},{"p":"목록, 인벤토리, 메일 병합, 태그 정리, 설문 조사 응답, 스프레드시트 열 등 모든 것이 목록이 되고 모든 목록에는 정렬, 중복 제거 또는 무작위화가 필요합니다."},{"l":["[[duplicate-line-remover|중복 줄 제거]] — 두 목록을 비교하거나 하나를 정리합니다. 출력에서는 제거된 중복 항목 수를 알려주므로 결과를 보고할 때 유용합니다.","[[list-sorter|List Sorter]] — 구조화된 목록 입력에 대한 동일한 작업입니다.","[[list-randomizer|List Randomizer]] — 추첨 순서, 퀴즈 시퀀스 또는 경계가 막힌 최종 후보 목록을 섞어 아무도 편애를 의심하지 않도록 합니다.","[[line-number-adder|줄 번호 추가]] — 티켓 또는 코드 검토 주석에서 참조할 줄 번호입니다."]},{"b":"여기서 고전적인 함정은 중복이 제거된 것처럼 보이지만 그렇지 않은 목록입니다. \'Apple\', \'apple\' 및 \'Apple\'은 컴퓨터에 대한 세 가지 다른 라인입니다. 중복을 제거하기 전에 공백을 자르고 후행 구두점을 제거하십시오. 그렇지 않으면 아무것도 병합하지 않고 데이터가 깨끗하다는 결론을 내릴 것입니다."},{"h":"미리보기 및 서식 지정"},{"p":"Markdown이(가) 이겼지만 균일하지는 않았습니다. 도구의 절반은 렌더링하고 절반은 렌더링하지 않으며, 그렇지 않은 절반은 일반적으로 선배가 붙여넣어야 하는 도구입니다."},{"l":["[[markdown-preview|Markdown 미리보기]] — 라이브 렌더링을 통해 클라이언트에 도달하기 직전에 테이블이나 중첩 목록이 실제로 보이는지 확인할 수 있습니다.","[[text-repeater|텍스트 반복기]] — 문자열을 N번 반복합니다. 패딩을 생성하거나 데이터를 테스트하거나 때로는 문서에서 요점을 만드는 데 유용합니다."]},{"p":"Markdown 미리보기는 렌더링된 문서의 깨진 표가 원시 텍스트의 깨진 표보다 훨씬 더 눈에 띄고 훨씬 더 당혹스럽기 때문에 이 전체 세트에서 가장 많은 시간을 조용히 절약하는 도구입니다."},{"h":"나머지, 그리고 언제 도달해야 하는가"},{"l":["[[random-string|Random String Generator]] — 읽을 수 있는 nonce, 자리 표시자 ID 또는 단축 코드를 생성합니다. 실수로 재사용할 일이 없기 때문에 손으로 무언가를 발명하는 것보다 낫습니다.","[[morse-code|모스 부호 번역기]] — 정말 재미있고 때로는 테마 프로젝트나 퍼즐에 유용합니다."]},{"p":"이러한 도구는 빈도가 낮은 도구이지만 북마크를 유지하는 데 비용이 들지 않으며 \\"지금 당장 무작위로 보이는 값이 필요하고 이를 만드는 데 자신이 없습니다\\"라는 특정 문제를 해결합니다."},{"h":"현실적인 편집 패스"},{"p":"다음은 다른 사람으로부터 초안이 도착하여 귀하의 이름으로 발송되어야 할 때 적용되는 순서입니다."},{"l":["**1. Trim.** 먼저 [[text-trimmer|Text Trimmer]]를 통해 전체 문서를 실행합니다. 공백 손상은 결코 볼 수 없는 단락 내부에 숨겨져 있습니다.","**2. 케이스를 청소하세요.** 헤드라인에만 [[text-case-converter|텍스트 케이스 변환기]]를 사용하세요. 전체 초안에 대소문자 변환을 적용하지 마십시오. 고유 명사가 삭제됩니다.","**3. 측정하세요.** 글을 쓰기 전에 [[단어 카운터|단어 카운터]]로 길이를 확인하면 작품의 모양이 어떤 것인지 알 수 있습니다.","**4. 미리보기.** Markdown이 포함된 경우 [[markdown-preview|Markdown 미리보기]]로 렌더링하세요.","**5. Slug.** [[text-to-slug|Text to Slug]]를 사용하여 최종 헤드라인에서 마지막으로 URL 슬러그를 생성합니다. 나중에 헤드라인을 변경하면 슬러그가 중단됩니다."]},{"p":"전체 통과에는 몇 분이 걸리며 문서가 기술적으로 정확하고 눈에 띄게 잘못된 실수 범주를 제거합니다."},{"h":"개인 정보 보호에 대한 작가의 질문"},{"p":"**게시되지 않은 내 텍스트가 내 컴퓨터 밖으로 나가나요?** 아니요. 이러한 도구는 브라우저에서 텍스트를 처리하며 아무 것도 저장되거나 전송되지 않습니다.\\n\\n**길이 제한이 있나요?** 서버 호출이 없기 때문에 서버 측 제한이 없습니다. 매우 큰 입력은 장치의 메모리에 의해 제한됩니다.\\n\\n**출력물을 상업적으로 사용할 수 있습니까?** 예, 저작자 표시 없이 자유롭게 사용할 수 있습니다.\\n\\n**전화로도 작동하나요?** 예. 레이아웃이 조정되고 동일한 코드가 실행됩니다."},{"h":"이 도구가 제공하지 않는 작업"},{"p":"잘못된 것을 기계화하는 도구는 더 빠른 실수를 낳기 때문에 한계에 대해 직설적으로 말할 가치가 있습니다.\\n\\n이러한 유틸리티 중 어느 것도 문장이 명확한지, 주장의 근거가 있는지 또는 어조가 청중에게 적합한지 여부를 알려줄 수 없습니다. 그들은 문자를 센다; 그들은 산문을 판단하지 않습니다. 이 페이지의 모든 지표에서 좋은 점수를 받은 텍스트라도 여전히 읽을 수 없습니다.\\n\\n편집도 하지 않습니다. 대규모로 개별 절을 직접 다시 작성하는 순간, 텍스트 도구는 더 이상 성장하지 않으며 적절한 편집기, 정규식을 사용한 찾기 및 바꾸기([[regex-tester|Regex Tester]]가 리허설에 정말 좋습니다) 또는 스크립트가 필요합니다. Mechanical 레이어에는 브라우저를 사용하고 그 위의 모든 항목에 대해서는 스스로 판단하세요."},{"p":"그들이 하지 않을 또 하나의 일은 잘못된 소스를 수정하는 것입니다. 스프레드시트에 \\"Dr\\", \\"DR\\", \\"Dr.\\" 등 일관성 없는 이름이 가득한 경우 모두 하나의 열에 표시됩니다. 도구는 사용자가 제공한 내용을 충실하게 정렬하고 중복을 제거하며, 하나가 있어야 할 항목은 여전히 ​​3개입니다. 데이터 정리는 기계적인 단계가 아닌 결정입니다. 먼저 표준 형식을 결정한 후 적용하고 확인합니다."},{"h":"작업 목록을 사용 가능한 상태로 유지"},{"p":"리드, 링크, 참조 또는 용어 목록을 유지 관리하면 조용히 성능이 저하됩니다. 실패 모드는 항상 동일합니다. 동일해 보이는 항목은 동일하지 않으며 한 번의 병합으로 아무것도 제거되지 않습니다.\\n\\n작동하는 유지 관리 패스는 지루합니다. 공백을 다듬고, 대문자를 표준화하고, 후행 구두점을 제거한 다음 중복을 제거합니다. 해당 순서대로 - 중복 제거 후 트리밍하면 항목이 손실됩니다. 활성 목록에서 한 달에 한 번 이 작업을 수행하면 복구할 수 없는 2시간의 혼란스러운 일이 10분의 자질구레한 일로 변합니다.\\n\\n두 개의 목록을 조정해야 하는 경우(예: 출석 목록에 대한 등록 목록) 먼저 [[list-sorter|List Sorter]]를 사용하여 두 목록을 정렬하여 정렬한 다음 눈으로 비교합니다. 비교하기 전에 양쪽을 분류하는 것이 2분 확인과 20분 사냥의 차이입니다."},{"h":"테이크아웃"},{"p":"이러한 도구 중 어느 것도 영리하지 않습니다. 그것이 요점입니다. 쓰기가 아닌 쓰기의 기계적인 5%를 제거하므로 나머지 95%는 실제로 문장에 관한 것입니다. 매달 사용하는 항목을 북마크에 추가하고 나머지는 무시하고 공백을 수동으로 수정하지 마세요."}]},"calculators-and-converters-guide":{"title":"실제로 다루는 숫자를 위한 18가지 무료 계산기 및 변환기","description":"백분율, 할인, 팁, 대출, 날짜, BMI 및 단위 변환 — 계정이 필요 없이 추론을 보여주는 무료 브라우저 계산기입니다.","category":"계산기","blocks":[{"p":"모두가 청구서를 분할하고, 할인이 진짜 할인인지 확인하고, 온도나 파일 크기를 고려하지 않고 변환해야 합니다. 모든 사람들도 적어도 한 번은 공개적으로 이 말을 잘못 이해합니다.\\n\\n이것은 돈, 날짜, 건강, 직장과 여행에 나타나는 단위 변환을 다루는 18개의 계산기와 변환기 모음입니다. 모두 브라우저에서 실행됩니다. 아무 것도 저장되지 않으므로 귀하가 입력하는 숫자는 귀하 외에는 누구의 것도 아닙니다."},{"h":"돈 계산"},{"p":"가장 일반적인 실제 수학은 어떤 것의 백분율입니다. 판매세, 팁, 할인 스택, 수수료, 성장률. 공식은 간단하지만 사람들이 틀리는 이유는 거의 항상 동일합니다. 즉, 잘못된 밑수에 백분율을 적용합니다."},{"l":["[[discount-calculator|할인 계산기]] — 최종 가격을 계산하고, 더 중요하게는 얼마나 절약했는지 계산하세요. 정가를 인상한 후 실제로 20% 할인된 \\"50% 할인\\"을 찾는 데 유용합니다.","[[tip-calculator|팁 계산기]] — 청구서를 분할하고, 백분율을 선택하고, 원할 경우 1인당 반올림합니다.","[[loan-calculator|대출 계산기]] — 월별 지불금 및 총 이자. 이는 실제로 대출이 합리적인지 여부를 결정하는 수치입니다."]},{"b":"할인: 20% 할인에 이어 또 다른 20% 할인은 40% 할인이 아니라 36% 할인입니다. 감소된 염기에 순차적인 백분율이 합성됩니다. 이 목록에 있는 모든 계산기는 약 2초 안에 이를 확인하며, 이는 이 기사에서 가장 유용한 단일 산술 사실입니다."},{"p":"대출 계산기에는 특별한 메모가 필요합니다. 중요한 숫자는 월별 지불액이 아니라 대출 기간 동안 지불한 총 이자입니다. 왜냐하면 그것이 실제 대출 비용이기 때문입니다. 동일한 월 납입금과 다른 조건의 두 대출은 총 이자가 수만 차이가 날 수 있습니다."},{"h":"날짜 및 카운트다운"},{"p":"날짜 산술은 대부분의 사람들이 조용히 틀리는 부분입니다. 인간의 달은 길이가 다르고 \\"달력 달\\"을 의미하는지 \\"30일\\"을 의미하는지에 따라 답이 달라지기 때문입니다."},{"l":["[[date-difference|날짜 차이 계산기]] — 두 날짜 사이의 일수(및 총 월, 연도)입니다.","[[days-until|계산기까지 남은 일수]] — 특정 날짜까지의 카운트다운이며 일반적으로 사람들이 실제로 원하는 근무일 수입니다.","[[age-calculator|나이 계산기]] — 정확한 나이(연도, 일수)에 다음 생일을 더합니다.","[[timestamp-converter|타임스탬프 변환기]] — 실제 날짜로의 Unix 타임스탬프이며 로그, 데이터베이스 또는 API 응답을 터치하는 경우 중요합니다."]},{"p":"사람들을 혼란스럽게 만드는 차이점: 3월 1일과 4월 1일 사이의 일수는 31일이지만 *개월* 수는 1입니다. 통지 기간이나 구독 기간을 계산하는 경우, 어떤 단위를 의미하는지 서면으로 명시하십시오."},{"h":"솔직히 말해서 건강 수치"},{"l":["[[bmi-calculator|BMI 계산기]] — 표준 범주가 포함된 체질량 지수와 아래의 주의 사항."]},{"p":"BMI는 인구 수준의 선별 통계입니다. 이는 근육량, 신체 구성 또는 개인의 건강에 대해 아무 말도 하지 않으며, 운동선수, 노인 및 다양한 인종 그룹의 체력을 제대로 나타내지 않습니다. 이를 여러 데이터 포인트 중 하나의 데이터 포인트로 사용하거나 판정이 아닌 시간에 따른 변화를 추적하는 방법으로 사용하세요. 건강에 영향을 미치는 결정을 내리는 경우 올바른 도구는 브라우저 탭이 아닌 임상의입니다."},{"h":"단위 변환: 일상적인 것"},{"p":"단위 변환은 정확히 맞아야 하는 변환과 대략적으로 필요한 변환의 두 가지 종류로 나뉩니다. 이러한 도구는 두 가지를 모두 처리하며 작업은 어느 것이 어느 것인지 기억하는 것입니다."},{"l":["[[length-converter|길이 변환기]] — 미터법에서 영국식 단위로, 그 뒤로: 밀리미터, 센티미터, 미터, 킬로미터, 인치, 피트, 야드, 마일.","[[weight-converter|무게 변환기]] — 그램, 킬로그램, 온스, 파운드, 톤. 레시피나 배송 라벨을 확인하기 전에 확인해야 할 것입니다.","[[온도 변환기|온도 변환기]] — 섭씨, 화씨, 켈빈. -10°C는 14°F가 아니고 공식은 곱셈이 아니기 때문입니다.","[[속도 변환기|속도 변환기]] — km/h, mph, m/s, 노트. 외국의 속도 제한이나 엔지니어링 사양에 유용합니다.","[[area-converter|면적 변환기]] — 평방 미터, 평방 피트, 에이커, 헥타르. 이것은 부동산을 구입하거나 임대할 때 사람들이 나쁘게 평가하는 것입니다.","[[volume-converter|볼륨 변환기]] — 리터, 밀리리터, 갤런, 컵, 입방미터.","[[time-converter|시간 변환기]] — 초, 분, 시간, 일, 주."]},{"b":"알아야 할 두 가지 전환 함정: 위의 데이터 저장(마케터는 10^3을 판매하고 운영 체제는 2^10을 보고함)과 연비 — 영국식 갤런이 더 크기 때문에 40mpg(영국식)로 표시된 자동차는 40mpg보다 33mpg(미국)에 더 가깝습니다. 두 번째 것을 잘못하면 렌터카가 비현실적으로 효율적으로 보입니다."},{"h":"필요하지 않을 것으로 예상되는 두 가지"},{"l":["[[random-number|난수 생성기]] — 추첨, 브래킷 또는 빠른 A/B 분할을 위해 범위 내에서 추첨합니다. 당신이 조작했다는 의혹을 없애주기 때문에 유용합니다.","[[dice-roller|Dice Roller]] — 실제 주사위가 마지막으로 테이블에서 굴러 떨어진 보드 게임이나 테이블탑 세션의 경우 동전 던지기부터 20면체 주사위까지 모든 주사위."]},{"h":"계산기를 올바르게 사용하기"},{"p":"계산기는 질문하려는 숫자가 무엇인지 아는 경우에만 도움이 됩니다. 세 가지 습관이 차이를 만든다."},{"l":["**먼저 반올림하고 두 번째로 계산합니다.** 정확한 숫자가 결정에 영향을 미치지 않으면 반올림을 사용하십시오. 둥근 숫자의 백분율을 머릿속으로 확인할 수 있어 입력 오류를 잡아냅니다.","**크기를 제대로 확인하세요.** 결과를 믿기 전에 입력보다 더 커야 하는지, 작아야 하는지, 그리고 대략 얼마만큼 커야 하는지 물어보세요. 대부분의 산술 실수는 이것을 제외한 모든 수표에서 살아남습니다.","**출력이 아닌 입력을 사진에 담으세요.** 나중에 계산을 다시 실행할 때 중요한 것은 결론이 아니라 가정한 내용을 아는 것입니다."]},{"h":"사람들이 실제로 묻는 질문"},{"p":"**내 전화번호는 어디에 저장되나요?** 아니요. 계산은 브라우저에서 이루어지며 아무 것도 전송되거나 보관되지 않습니다.\\n\\n**휴대폰에서도 작동하나요?** 예, 계산기는 한 손으로 사용할 수 있도록 제작되었습니다.\\n\\n**데이터 스토리지에 어떤 변환 표준을 사용합니까?** 스토리지가 판매되는 방식이므로 기본적으로 십진수(1KB = 1000바이트)입니다. 운영 체제는 바이너리를 보고하므로 드라이브가 축소된 것처럼 보입니다. 도구는 조용히 한쪽을 선택하는 대신 차이점을 설명합니다.\\n\\n**이를 내 사이트에 삽입할 수 있나요?** 아니요. 대신 북마크에 추가하세요. 그 비용은 0이고 정확성 문제는 귀하가 소유해야 합니다."},{"h":"백분율: 중요한 네 가지 실수"},{"p":"사람이 일상 생활에서 범하는 거의 모든 백분율 오류는 동일한 네 가지 실수 중 하나입니다. 이름을 지정하면 피할 수 있습니다."},{"l":["**잘못된 기준.** \\"10% 상승한 다음 10% 하락하면 시작했던 위치에 있게 됩니다.\\"는 둘 다 서로 다른 기준에 적용되기 때문에 거짓입니다. 100의 10%는 10입니다. 90의 10%는 9입니다.","**백분율의 백분율.** 2개의 할인을 누적하면 두 할인이 곱해지며(0.8 × 0.8 = 0.64, 즉 36% 할인) 추가되지는 않습니다.","**퍼센트 대 백분율 포인트.** 4%에서 6%로 가는 비율은 2% 포인트 증가했지만 상대적인 측면에서는 50% 증가했습니다. 정치와 의학은 이러한 혼란으로 가득 차 있으며, 이것이 항상 우연은 아닙니다.","**너무 일찍 반올림되었습니다.** 백분율을 적용하기 전에 중간 단계를 반올림하면 오류가 발생합니다. 최종 숫자가 나올 때까지 완전한 정확성을 유지하고 머리 속이 아닌 계산기로 마지막 단계를 수행하십시오."]},{"p":"이 전체 섹션에서 단 하나의 습관만 취한다면 다음 습관을 취하십시오. 누구에게나 백분율을 인용하기 전에 그것이 *의* 백분율이 무엇인지 다시 말하십시오. 숫자에 관해 여러분이 갖게 될 논쟁의 절반은 실제로 분모에 관한 논쟁입니다."},{"h":"계산을 멈춰야 할 때를 아는 것"},{"p":"정밀도가 유용하지 않게 되는 지점이 있습니다. 소수점 이하 두 자리까지 월별 지불이 의미가 있습니다. 예상 총 비용을 소수점 8자리까지 표시하는 것은 대출금이 스트레스 없이 감당할 수 있는 수준에 맞는지 여부를 결정하는 실제 결정을 피하는 방법입니다.\\n\\n유용한 테스트는 민감도 질문입니다. 이 입력이 10%만큼 이동하면 결정이 변경됩니까? 그렇지 않은 경우에는 수정을 중단하고 답을 이동하는 변수(일반적으로 요율보다는 용어, 할인보다는 정가)에 추가 시간을 사용하십시오."},{"p":"그리고 분명히 말할 가치가 있는 한 가지 경계는 이 계산기는 산술이지 조언이 아니라는 것입니다. 저축 목표, 은퇴 날짜 및 부채 상환 계획은 모두 위험, 행동 및 시간에 대한 결정이며 브라우저 탭은 이러한 사항을 평가할 수 없습니다. 가정하고 있는 것을 결정한 후에만 숫자가 의미하는 바를 알려줄 수 있습니다. 이러한 차이는 계산기가 유용하다는 것과 책임감이 있다는 것의 차이입니다."},{"h":"한 줄 버전"},{"p":"돈과 날짜 계산기를 적절하게 북마크에 표시하고, BMI를 평결이 아닌 하나의 신호로 취급하고, 누적 백분율이 곱해진다는 것을 기억하고, 숫자가 계약상 어떤 것에 들어갈 때마다 단위 변환을 확인하십시오. 그것은 거의 모든 것을 다룹니다."}]},"image-and-design-tools":{"title":"브라우저에서 실행되는 14가지 무료 이미지 및 디자인 도구","description":"Photoshop이나 디자인 제품군을 설치하지 않고도 이미지를 압축, 크기 조정 및 준비하고 CSS 효과, 팔레트, 대비 검사 및 파비콘을 생성할 수 있습니다.","category":"디자인 도구","blocks":[{"p":"이미지 작업에는 특정한 문제가 있습니다. 작업은 일반적으로 규모가 작고 제공되는 도구는 엄청납니다. 히어로 이미지에서 400KB를 줄이거나, 디자이너가 언급한 16진수 값을 얻거나, 아직 아무도 만들지 않은 파비콘을 생성해야 합니다. 구독이 필요하지 않습니다.\\n\\n아래의 14개 도구는 이미지 준비, 색상 작업, CSS 효과 생성 및 문제가 있는 소규모 제작 자산을 다룹니다. 모든 것이 로컬에서 실행되는데 이는 텍스트보다 이미지에 더 중요합니다. 방금 압축한 사진은 아직 게시하지 않은 사진인 경우가 많습니다."},{"h":"웹용 이미지 준비"},{"p":"대부분의 이미지 문제는 실제로 체중 문제입니다. 느리게 느껴지는 페이지에는 일반적으로 디스플레이 크기보다 큰 이미지가 잘못된 형식으로, 아무도 의심하지 않는 품질 설정으로 포함되어 있습니다."},{"l":["[[image-compressor|이미지 압축기]] — 이미지를 시각적으로 그대로 유지하면서 파일 크기를 줄입니다. 크기 제한이 있는 양식에 무엇이든 업로드하기 전에 실행하십시오.","[[image-resizer|이미지 크기 조정기]] — 필요한 실제 픽셀 크기를 설정합니다. 이것이 더 큰 승리입니다. 800px로 표시되는 4000px 이미지는 필요한 데이터의 5배를 전달합니다.","[[image-to-base64|이미지를 Base64로]] — CSS, HTML 또는 이메일 템플릿의 인라인 처리를 위해 작은 이미지를 데이터 URI로 변환합니다."]},{"b":"순서가 중요합니다. 먼저 크기를 조정하고 두 번째로 압축합니다. 4000px 이미지를 압축하면 800px로 크기를 조정한 다음 동일한 품질로 압축하는 것보다 훨씬 더 무거운 파일이 생성됩니다. 왜냐하면 압축기는 어쨌든 버려질 픽셀에 노력을 기울이기 때문입니다."},{"p":"얼마나 압축해야합니까? 정직한 대답은 잘못된 것처럼 보일 때까지 한 단계 뒤로 물러나는 것입니다. 사진 영웅 이미지의 경우 70~80% 품질은 일반적으로 일반 보기 크기에서 원본과 구별할 수 없습니다. 로고, 스크린샷 또는 단조로운 색상과 딱딱한 가장자리가 있는 모든 것의 경우 PNG를 사용하고 더 세게 압축하십시오. 이렇게 하면 더 많은 것을 얻고 더 적은 손실을 얻을 수 있습니다."},{"p":"경험상 실용적인 규칙: 히어로 이미지의 경우 200KB 미만이면 괜찮고, 썸네일의 경우 80KB 미만이면 괜찮습니다. 300KB 미만으로 줄일 수 없다면 품질 문제보다는 크기 문제가 있을 가능성이 높습니다."},{"h":"Base64: 인라인이 올바른 호출인 경우"},{"p":"이미지를 Base64 데이터 URI로 변환하면 HTTP 요청이 제거되는데, 이는 순전히 승리처럼 들립니다. 일반적으로 그렇지 않습니다. 인코딩된 문자열은 바이너리 파일보다 약 1/3 더 크고 별도로 캐시할 수 없으며 CSS 또는 HTML을 부풀립니다.\\n\\n인라인은 이미지가 작은 경우에만(몇 킬로바이트 미만) 한 번만 사용되며 중요합니다. 단일 이메일 템플릿에 있는 작은 아이콘이 전형적인 경우입니다. 여러 페이지에 걸쳐 반복되거나 몇 킬로바이트보다 큰 내용의 경우 파일로 제공하고 브라우저에서 캐시하도록 합니다."},{"h":"워터마크: 정직하게 제거 가능한 것"},{"l":[]},{"p":"이것이 무엇을 하는지 명확히 하세요. 눈에 보이는 표시를 제거하거나 모호하게 만듭니다. 기본 픽셀을 재구성할 수 없습니다. 위에 칠해진 정보는 사라지고 어떤 필터도 이를 다시 생성하지 않습니다. 결과는 표시가 일반 배경 위에 있을 때 보이지 않는 것부터 세부적인 부분 위에 있을 때 눈에 띄게 번지는 것까지 다양합니다.\\n\\n분명히 말할 가치가 있는 한 가지 더: 다른 사람의 워터마크를 제거하고 결과를 게시하는 것은 대부분의 관할권에서 저작권 문제이며 적발 여부에 관계없이 라이선스 위반입니다. 자신의 이미지나 라이센스가 있는 재고에서 표시를 제거하는 것이 이 도구의 목적입니다."},{"h":"색상: 변환, 확인, 선택"},{"p":"색상은 작은 실수가 눈에 띄게 나타나는 곳입니다. 접근성이 떨어지는 명암비, 실제로 HSL 트리플인 16진수 값, 모니터에서는 일관되게 보이지만 프로젝터에서는 흐릿하게 보이는 팔레트입니다."},{"l":["[[color-converter|색상 변환기]] — HEX, RGB 및 HSL 사이를 이동합니다. HSL은 읽는 법을 배울 가치가 있습니다. 왜냐하면 색조 210, 채도 40%, 밝기 50%가 16진수 값보다 손으로 조정하기가 훨씬 쉽기 때문입니다.","[[contrast-checker|Contrast Checker]] — WCAG 임계값을 기준으로 배경과 텍스트를 테스트합니다. 이는 취향 문제가 아닌 실제 규정 준수 문제를 포착하기 때문에 이 기사에서 가장 유용한 단일 도구입니다.","[[color-palette|색상 팔레트 생성기]] — 브랜드 색상에서 시작하고 나머지 규모가 필요할 때 일관된 세트를 생성합니다."]},{"b":"이와 대조적으로 WCAG AA는 일반 본문 텍스트의 경우 4.5:1, 큰 텍스트의 경우 3:1을 요구합니다. 버튼에 대해 두 가지 브랜드 색상 중 하나를 선택하는 경우 일반적으로 접근 가능한 색상은 디자이너가 좋아하는 색상이 아닙니다. 먼저 확인한 다음 데이터로 논쟁을 벌이세요."},{"p":"색상 도구에 대한 한 가지 주의 사항: 이 도구는 모두 모니터가 보정되어 있고 페이지를 보는 사람의 눈이 제대로 작동하고 있다고 가정합니다. 어느 가정도 안전하지 않습니다. 이것이 주관적인 조합보다 대조 확인된 조합을 선호하는 이유입니다."},{"h":"디자인 도구를 열지 않고도 CSS 효과"},{"p":"그라데이션이나 레이어드 섀도우를 손으로 그리는 것은 정말 불쾌한 작업입니다. 구문은 까다롭고, 생성되는 내용을 볼 수 없으며, 좋은 그림자와 나쁜 그림자의 차이는 몇 픽셀의 흐림 정도입니다."},{"l":["[[gradient-generator|CSS 그라디언트 생성기]] — 선형 및 방사형 그라디언트를 만들고 CSS를 직접 복사합니다.","[[box-shadow-generator|박스 그림자 생성기]] — 여러 개의 그림자를 겹쳐서 미묘한 고도와 무거운 낙하를 구분합니다.","[[border-radius-generator|테두리 반경 생성기]] — 모양을 의도적으로 보이게 만드는 비대칭 반경을 가져옵니다.","[[text-shadow-generator|텍스트 그림자 생성기]] — 드물게 유용합니다. 대부분의 텍스트 그림자가 너무 강합니다. 이렇게 하면 오프셋과 흐림이 사라질 때까지 조정할 수 있습니다."]},{"p":"네 가지 모두의 비결은 구속입니다. 두 개의 그림자(단단히 어두운 그림자와 넓고 부드러운 그림자)는 물리적 높이로 읽혀집니다. 하나의 그림자는 15년 전의 웹사이트로 읽힌다. 생성하고, 복사하고, 존재하는지 알 수 없을 때까지 삭제하세요."},{"h":"모두가 잊어버린 생산 자산"},{"l":["[[favicon-generator|Favicon Generator]] — 사이트에 실제로 필요한 작은 아이콘 세트를 생성합니다. 파비콘은 완전히 누락될 가능성이 가장 높은 자산이고 누락된 파비콘은 완성된 사이트를 미완성으로 보이게 만드는 일반 브라우저 페이지 아이콘을 표시하기 때문에 목록에 있습니다.","[[emoji-picker|Emoji Picker]] — 운영 체제 선택기를 통해 검색하지 않고도 이모티콘을 탐색, 검색 및 복사할 수 있습니다. 하나의 특정 기호가 필요한 사본을 작성할 때 정말 유용합니다."]},{"h":"실제 사례: 히어로 섹션 배송"},{"p":"다음은 하나의 실제 작업을 수행하는 전체 클러스터입니다. 페이지에는 배경 이미지, 제목, 버튼이 있는 히어로가 필요하지만 아직 아무것도 구축되지 않았습니다."},{"l":["**1. 공간을 확보하세요.** 레이아웃에서 이미지 슬롯에 고정 높이를 지정하면 페이지가 실제 이미지가 도착할 때 점프하는 대신 첫 번째 렌더링부터 올바른 모양을 갖게 됩니다.","**2. 크기를 조정하고 압축합니다.** 실제 사진이 도착하면 [[image-resizer|이미지 크기 조정기]]를 통해 1600px 너비로 실행한 다음 [[image-compressor|이미지 압축기]]를 75%로 실행합니다. 보낼 수 있는 파일입니다.","**3. 대비를 확인하여 텍스트를 확인하세요.** 사진 위의 제목은 전형적인 대비 실패입니다. [[contrast-checker|Contrast Checker]]를 사용하여 어두운 오버레이 강도나 AA를 통과하는 밝은 텍스트 색상을 선택하세요.","**4. 버튼을 만듭니다.** [[box-shadow-generator|Box Shadow Generator]]는 높이를 제공하고 [[color-converter|Color Converter]]는 브랜드 색상을 CSS에 필요한 형식으로 가져옵니다.","**5. Ship.** 탭이 버려진 것처럼 보이지 않도록 [[favicon-generator|Favicon Generator]]에서 파비콘을 추가하면 섹션이 완료됩니다."]},{"p":"다섯 가지 도구, 디자인 제품군 없음, 모든 출력은 코드에 바로 붙여넣을 수 있는 값입니다."},{"h":"자주 묻는 질문"},{"p":"**내 이미지가 어디에 업로드되나요?** 아니요. 압축, 크기 조정 및 Base64 변환은 모두 브라우저에서 이루어지므로 파일 크기 제한이나 업로드 대기열이 없습니다.\\n\\n**이미지를 압축하면 품질이 떨어지나요?** 정의에 따르면 항상 그렇습니다. 문제는 그것이 눈에 보이느냐 하는 것이다. 70~80%의 품질과 정확한 치수에서는 일반적으로 그렇지 않습니다.\\n\\n**크기가 조정된 이미지가 여전히 크게 보이는 이유는 무엇입니까?** 10번 중 9번은 크기를 조정하기 전에 압축했거나 사진이 JPEG보다 나은데 PNG로 저장하고 있습니다.\\n\\n**클라이언트 작업에 사용할 수 있나요?** 예, 저작자 표시나 상업적 제한이 없습니다.\\n\\n**휴대폰에서도 작동하나요?** 예, 하지만 휴대폰에서 큰 사진의 크기를 조정하고 압축하는 것은 서버가 아닌 기기의 메모리에 따라 다릅니다."},{"h":"한 줄 버전"},{"p":"압축하기 전에 크기를 조정하고, 색상에 대해 논쟁하기 전에 대비를 확인하고, 그림자를 미묘하게 유지하고, 파비콘을 잊지 마세요. 어쨌든 그것은 디자인 제품군이 당신을 위해 했던 일의 대부분입니다."}]},"math-tools-for-real-numbers":{"title":"작동하지 않는 숫자를 위한 6가지 무료 수학 도구","description":"과학적 표기법, 소수를 분수로, 소수 확인, 계승 및 GCF/LCM — 틀리기 쉬운 숫자 작업을 위한 무료 브라우저 도구입니다.","category":"수학 도구","blocks":[{"p":"컴퓨터에서 실제로 필요한 수학은 시험했던 수학이 아닙니다. 이 숫자는 시스템이 예상하는 형식인지, 이 분수가 단순화되었는지, 얼마나 빨리 증가하는지, 계산기와 스프레드시트가 일치하지 않는 이유는 무엇입니까?\\n\\n이 6가지 도구는 해당 영역을 다룹니다. 로컬에서 실행되는데, 이는 산술적으로 이름을 붙일 가치가 있는 하나의 특정 혜택을 의미합니다. 입력한 숫자는 어디에도 전송되지 않으므로 급여, 잔액 또는 고객 수치와 관련된 계산을 다시 생각할 필요 없이 확인할 수 있습니다."},{"h":"기계가 받아들이는 형식으로 숫자 가져오기"},{"p":"컴퓨터는 소수를 이진 분수로 저장합니다. 0.1은 이진수로 정확히 표현할 수 없습니다. 가장 가까운 배정밀도 값은 0.1000000000000000055511151231257827입니다. 0.1 + 0.2를 더하면 0.30000000000000004가 됩니다. 이는 기본적으로 0.3으로 인쇄되고 조용히 동등 검사를 중단합니다."},{"l":["[[scientific-notation|과학적 표기법 변환기]] — 표준 형식과 과학 형식 사이를 이동합니다. 이는 대부분의 로그, 스프레드시트 및 API가 실제로 큰 숫자와 작은 숫자를 저장하는 방식입니다.","[[decimal-fraction|소수를 분수로]] — 소수를 정확한 분수로 변환합니다. 이것은 위의 문제에 대한 수정 사항입니다. 정확한 분수 산술에서 0.1 + 0.2는 근사치가 아닌 3/10입니다."]},{"b":"합계가 0.0000000000000004만큼 틀린 것을 본 적이 있다면, 이것이 바로 그 이유입니다. 금융 코드에서 표준적인 대답은 정수 센트 또는 십진수 라이브러리에서 작업하는 것이며 부동 소수점에서는 작업하지 않는 것입니다. 스프레드시트가 스크립트와 조금도 일치하지 않는 것을 본 적이 있다면 그것은 다른 모자를 쓰고 있는 동일한 버그입니다."},{"p":"과학적 표기법은 로그 라인을 읽는 것과 눈을 가늘게 뜨고 보는 것의 차이이기 때문에 능숙하게 다룰 가치가 있습니다. 6.022e23, 1.6e-19 및 3e8은 아보가드로 수, 기본 전하 및 빛의 속도입니다. 숫자가 아닌 노이즈처럼 보이는 경우 도구를 통해 몇 가지를 변환하면 영구적으로 수정됩니다."},{"h":"소수, 그리고 누군가가 관심을 갖는 이유"},{"l":["[[prime-checker|소수 검사기]] — 숫자가 소수인지 테스트하고, 소수가 아닌 경우 인수분해를 확인합니다.","[[gcf-calculator|GCF LCM 계산기]] — 최대 공배수 및 최소 공배수."]},{"p":"소수는 학교에서 배우는 것이 아닙니다. 모든 HTTPS 연결의 보안은 두 개의 큰 소수를 곱하는 것은 쉽고 그 결과를 다시 인수분해하는 것은 어렵다는 사실에 달려 있습니다. 이러한 비대칭성은 RSA의 전체 기반입니다.\\n\\n일상적인 목적을 위해 소수 확인은 주로 분수에 관한 것입니다. 분수를 단순화한다는 것은 위쪽과 아래쪽을 최대공약수로 나누는 것을 의미하며 인수분해 없이는 이를 찾을 수 없습니다. 이것이 바로 이 두 도구가 함께 속하는 이유입니다. 요소를 확인한 다음 한 단계로 GCF와 LCM을 가져옵니다."},{"p":"LCM 절반은 사람들이 잊어버리는 부분이자 일정 문제를 해결하는 부분입니다. 18일마다 반복되는 두 이벤트와 12일마다 반복되는 두 이벤트는 36일마다 일치합니다. 동일한 산술, 다른 적용."},{"h":"팩토리얼과 폭발 속도"},{"l":["[[factorial-calculator|계수 계산기]] — n! 대답이 여전히 의미 있는 값의 경우."]},{"p":"팩토리얼은 책상에서 만나는 거의 모든 것보다 빠르게 성장합니다. 10! 3억 6천만 정도입니다. 20! 이는 약 2.4경개로 지구상의 모래알 수보다 훨씬 많습니다. 52!는 카드 한 벌을 섞는 방법의 수로, 대략 8자리 뒤에 67자리 숫자가 옵니다.\\n\\n실질적인 결과는 모든 순열을 열거하는 프로그램이 5개 항목에서는 괜찮고 8개에서는 허용 가능하며 12개에서는 영구적으로 멈춘다는 것입니다. 작업이 절대 끝나지 않을 것 같고 순열을 반복하는 경우 이것이 바로 그 이유임이 거의 확실합니다. 이는 또한 의견이 아닌 산술적 접근 방식으로 표현되는 대부분의 무차별 접근 방식에 대한 반대 주장이기도 합니다."},{"h":"로마 숫자, 그리고 그 이상한 점"},{"l":["[[roman-numerals|로마 숫자 변환기]] — 로마 숫자로 변환하거나 로마 숫자에서 변환합니다."]},{"p":"로마 숫자는 단순히 변환하는 것보다 이해할 가치가 있습니다. 왜냐하면 시스템이 위치 표기법에 대해 뭔가를 보여주기 때문입니다. 0도 없고 자릿값도 없습니다. XI는 11개의 막대를 나타내든 11,000개를 나타내든 11을 의미합니다. 이것이 바로 로마 숫자의 산술이 정말 어려운 이유이며, 이 시스템이 주로 계산보다는 계산과 연대 측정을 위해 수세기 동안 살아남은 이유입니다.\\n\\n빼기 법칙은 사람들이 잘못 이해하는 부분입니다. IV는 VI가 아니라 4입니다. IX는 9입니다. 시계는 유명한 예외입니다. Big Ben은 역사가들이 여전히 논쟁을 벌이는 이유로 IV 대신 IIII을 사용합니다. 파생보다는 변환이 모든 경우에 올바른 호출입니다."},{"h":"실제 사례: 손으로 분수 확인하기"},{"p":"레시피에는 0.375컵과 그램 단위로 읽는 저울이 필요하고, 보고서에서는 비율을 0.625로 인용하는데, 둘 다 누군가 급히 입력한 숫자처럼 보입니다."},{"l":["**1. 정확한 분수를 찾으세요.** [[decimal-fraction|Decimal to Fraction]] 도구를 통해 0.375를 실행하세요: 3/8. 0.625: 5/8을 실행합니다. 당신이 가지고 있지 않은 계산기 습관도 필요하지 않았습니다.","**2. 비율을 단순화합니다.** 5/8에 대해 3/8을 표현하려면 3과 5의 GCF가 필요합니다. [[gcf-calculator|GCF LCM 계산기]]는 1을 제공하므로 비율은 3:5이며 이미 가장 간단합니다.","**3. 팩토리얼 주장을 확인하세요.** 누군가 9개의 주문으로 구성된 대기열에 362,880개의 배열이 있다고 말하면 [[factorial-calculator|Factorial-calculator]]는 9를 확인합니다! 바로 그것이다. 이제 빌드 시간 추정치가 타당한지 여부를 알 수 있습니다.","**4. 큰 것은 무엇이든 정규화하세요.** 1.5e9나노초를 보고하는 서버는 [[scientific-notation|과학 표기법 변환기]]에 따라 1.5초입니다. 이는 대기 시간 문제와 반올림 아티팩트 간의 차이입니다."]},{"h":"이러한 도구가 의도적으로 수행하지 않는 작업"},{"p":"그들은 일하는 모습을 보여주지도 않고 가르치지도 않습니다. 공식이 참인 이유를 이해해야 한다면 계산기는 잘못된 도구입니다. 계산기는 이유 없이 답을 제공하므로 결국 사람들은 계산할 수는 있지만 추론할 수는 없습니다.\\n\\n또한 임의의 정밀도를 수행하지 않습니다. 계승 및 대규모 인수분해는 답변이 여전히 유용한 지점을 지나면 정확도가 떨어지며 브라우저 탭은 컴퓨터 대수학 시스템이 아닙니다. 엔지니어링, 금융, 암호화 등 정확성이 정말로 중요한 모든 경우에는 웹페이지가 아닌 정확한 산술 기능을 갖춘 적절한 라이브러리를 사용하세요."},{"h":"자신의 연산 확인하기"},{"p":"가장 가치 있는 수학적 습관은 속도가 아니라 추정이다. 결과를 믿기 전에 그것이 올바른 크기 순서인지, 즉 입력보다 크거나 작은지, 그리고 대략 얼마인지 물어보십시오. 대부분의 산술 실수는 이 실수를 제외한 다른 모든 수표에서 살아남습니다.\\n\\n먼저 반올림하면 추정이 무료가 됩니다. 0.375를 0.4로 반올림하고, 5/8을 0.6으로 반올림하면 비율은 분명히 약 2:3입니다. 정확히 계산한 분수를 확인할 수 있을 만큼 3:5에 가깝습니다. 정확한 답과 추정치가 일치하지 않으면 반올림 문제가 아닌 입력 오류를 발견했으며 몇 초 만에 발견했습니다.\\n\\n이것이 바로 계산기가 질문한 내용을 생각하는 것을 대체할 수 없는 이유이기도 합니다. 도구는 잘못된 수량을 완벽하게 계산하므로 유일한 방어 수단은 답이 어떤 느낌일지 아는 것입니다."},{"h":"자주 묻는 질문"},{"p":"**내 입력이 어디로 전송되나요?** 아니요. 이 모든 것은 브라우저에서 로컬로 실행됩니다.\\n\\n**0.1 더하기 0.2가 0.3이 아닌 이유는 무엇입니까?** 0.1도 0.2도 이진 부동 소수점으로 정확히 표현할 수 없기 때문입니다. 합은 0.30000000000000004이며, 이는 0.3에 가장 가까운 두 배입니다.\\n\\n**이들은 얼마나 큰 계승을 처리할 수 있습니까?** double의 범위를 초과하기 전 최대 170입니다. 과거에는 답이 과학적 표기법으로 표시되고 의미가 없어집니다.\\n\\n**코드에서 출력을 사용할 수 있습니까?** 예. 특히 소수를 분수로 변환하는 결과의 경우 소수로 다시 변환하는 대신 분자와 분모에 정수 연산을 사용합니다."},{"h":"한 줄 버전"},{"p":"돈이 관련된 경우 정확한 분수를 사용하고, 계승은 예상보다 빠르게 폭발하며, 소인수분해는 보안 기반이자 분수 단순화 트릭이라는 점을 기억하세요."}]},"everyday-utility-tools":{"title":"13가지 무료 일상 유틸리티: 비밀번호, QR 코드, 타이머 및 텍스트 인코딩","description":"비밀번호를 생성하고, QR 코드를 작성하고, 타이머와 시계를 실행하고, 바이너리, 16진수, 암호 텍스트를 디코딩하세요. 이 모든 작업은 계정이 필요 없이 로컬에서 실행되는 무료 브라우저 도구를 사용하여 수행할 수 있습니다.","category":"유틸리티 도구","blocks":[{"p":"이 마지막 그룹은 정크 서랍입니다. 비밀번호, QR 코드, 스톱워치, 세계 시계, 동전 뒤집기 및 텍스트를 다른 표현으로 변환하는 네 가지 도구입니다. 개별적으로는 사소한 것, 집합적으로는 어색한 순간에 필요한 것들입니다.\\n\\n요점은 13개 모두 로컬에서 실행된다는 것입니다. 훌륭하지 않은 비밀번호 생성기의 경우 이는 도구를 전혀 신뢰할 수 있는 전체 이유입니다."},{"h":"비밀번호: 실제로 중요한 부분"},{"l":["[[password-generator|비밀번호 생성기]] — 모든 길이와 문자 집합의 강력한 무작위 비밀번호를 생성합니다.","[[password-strength|비밀번호 강도 검사기]] — 비밀번호가 로컬에서 추측되기 어려운 정도를 추정합니다."]},{"b":"비밀번호 강도에 대한 가장 중요한 사실은 **길이가 복잡함을 이기고 재사용이 두 가지 모두보다 위험하다는 점입니다.** 관련 없는 단어로 구성된 16자 비밀번호는 10자로 뒤죽박죽된 기호보다 훨씬 더 강력하고 입력하기 쉽습니다. 한편, 위반으로 인해 재사용된 비밀번호 중 하나가 노출되면 해당 비밀번호가 접촉하는 모든 계정이 동시에 삭제됩니다. 사이트별로 고유한 긴 비밀번호를 생성하는 것이 전체 작업입니다."},{"p":"강도를 추정하는 방법도 중요합니다. 대부분의 체커는 검색 공간의 크기를 대략적으로 추정하는데, 이는 합리적인 프록시이지만 사실은 아닙니다. \'CorretHorseBatteryStaple\'은 엔트로피에서 좋은 점수를 받는 반면, \'P@ssw0rd1!\'은 문자 다양성에서 좋은 점수를 얻었지만 지구상의 모든 크래킹 단어 목록에 나타나기 때문에 실제로는 좋지 않습니다.\\n\\n관심 있는 모든 것에 생성기를 사용하고, 비밀번호를 기억해야 하는 경우 관련 없는 4~5개의 단어로 구성된 비밀번호 문구를 사용하세요. 기억력과 강인함이 실제로 겹치는 경우가 바로 그것이다."},{"h":"QR 코드: 무엇을 넣을 것인가?"},{"l":["[[qr-code-generator|QR 코드 생성기]] — URL, 텍스트, Wi-Fi 세부 정보 또는 연락처 정보에 대한 QR 코드를 생성합니다."]},{"p":"QR 코드는 입력한 데이터의 양이라는 하나의 결정에 의해 출력 품질이 전적으로 결정되는 도구 중 하나입니다. 짧은 URL은 작고 쉽게 스캔할 수 있는 코드로 인코딩됩니다. 구두점이 있는 텍스트 단락은 작은 크기에서는 조밀하고 신뢰할 수 없는 내용으로 인코딩됩니다.\\n\\n두 가지 실제 규칙. 먼저, 200개를 인쇄하기 전에 항상 실제로 인쇄될 크기로 코드를 테스트 스캔하세요. 둘째, Wi-Fi와 일반 URL 코드는 휴대폰마다 다르게 작동합니다. 코드가 혼합된 청중에게 전달되는 경우 계속 연결되는 방문 페이지보다 일반 URL을 선호합니다. 왜냐하면 어디에서나 작동하고 가리키는 위치를 변경할 수 있기 때문입니다."},{"h":"시간: 타이머, 시계 및 시간대의 트랩"},{"l":["[[스톱워치|온라인 스톱워치]] — 일반 스톱워치로, 휴대폰이 다른 방에 있을 때 유용합니다.","[[pomodoro-timer|Pomodoro Timer]] — 해당 구조가 효과가 있다고 생각하는 사람들을 위한 휴식 시간이 포함된 25분 집중 블록입니다.","[[world-clock|세계 시계]] — 동시에 여러 도시의 현재 시간."]},{"p":"세계시계가 그 자리를 차지한 이유는 바로 일광 절약 시간제입니다. 세계의 일정 실수 중 절반은 산술 오류가 아닙니다. 두 도시가 지난주에 4시간, 이번 주에 5시간 떨어져 있었는데 아무도 확인하지 않은 순간입니다.\\n\\n시간대에 걸쳐 일정을 계획하기 전에 두 도시를 세계 시계에 넣고 살펴보십시오. 메모리에서 오프셋을 계산하지 마십시오. 이는 또한 회의 초대장에 기본 시간이 아닌 시간대를 포함해야 하는 이유이기도 합니다."},{"p":"Pomodoro 타이머에서 이 기술은 제한된 작업, 집중된 작업, 중단 없는 작업 등 특정 종류의 작업에 작동합니다. 디버깅에는 작동하지 않습니다. 막혔을 때 올바른 조치는 다른 25분 블록을 시작하는 것이 아니라 떠나는 것입니다. 도움이 될 때 사용하세요."},{"h":"솔직히 무작위성"},{"p":"[[random-number|Random Number Generator]] 및 [[list-randomizer|List Randomizer]]는 실제로 발생하는 경우를 다룹니다. 즉, 범위에서 숫자를 선택하고 목록을 공정한 순서로 배치합니다. 공정성에 대한 선고를 받을 가치가 있습니다. 둘 다 의사 난수 생성기를 사용하는데, 이는 누가 점심 비용을 지불하는지 결정하는 데 실제 동전과 구별할 수 없습니다. 상품이 포함된 추첨, 돈이 첨부된 할당 등 결과적인 모든 경우 감사할 수 있는 소스를 원하지만 브라우저 탭은 그렇지 않습니다. 여기서 중요한 점은 동기 부여 시 잘못 선택하는 인간을 제거하는 것입니다."},{"h":"인코딩 정크 서랍"},{"p":"표현 간에 텍스트를 이동하는 네 가지 도구입니다. 그 중 어느 것도 암호화가 아니며 끊임없이 혼동되기 때문에 구별을 언급할 가치가 있습니다. 인코딩은 누구나 되돌릴 수 있으며 키가 없습니다. 암호화에는 키가 필요합니다."},{"l":["[[binary-text|이진을 텍스트로]] — 텍스트와 이진 표현 간을 변환합니다.","[[hex-text|16진수를 텍스트로]] — 네트워크 도구 및 디버거에서 가장 자주 볼 수 있는 표현인 텍스트와 16진수 간을 변환합니다.","[[caesar-cipher|Caesar Cipher]] — 문자를 고정된 양만큼 이동하는 고전 교실 암호입니다.","[[rot13-encoder|ROT13 Encoder]] — 글자를 13만큼 회전합니다. 이는 그 자체가 반대인 특별한 경우입니다."]},{"p":"이는 정확히 두 가지에 유용합니다. 첫째, 텍스트가 바이트가 되는 방식을 이해합니다. 이는 무엇이든 깨져 보일 때마다 필요한 정신적 모델입니다. 둘째, 실제로 디버깅합니다. 페이로드가 16진수로 표시되면 [[hex-text|Hex to Text]] 변환기를 사용하여 내용을 알아낼 수 있습니다.\\n\\n아무것도 숨기는 데는 유용하지 않습니다. ROT13에는 키가 없습니다. 교대는 공개됩니다. 따라서 ROT13이 무엇인지 아는 사람에게는 아무 것도 숨기지 않습니다. 카이사르 암호에는 25개의 가능한 교대조가 있으며, 인간은 1분 만에 이를 해독합니다."},{"h":"사물을 포맷하는 두 가지"},{"l":["[[phone-formatter|전화번호 포맷터]] — 전화번호를 일관된 형식으로 정규화합니다.","[[file-size-converter|파일 크기 변환기]] — 10진수와 2진수의 구분을 설명하면서 KB, MB, GB, TB 간을 변환합니다."]},{"p":"파일 크기 변환기에는 진정으로 귀중한 출력이 하나 있습니다. 이는 드라이브가 컴퓨터가 보고하는 것보다 더 큰 숫자를 광고하는 이유를 알려줍니다. 공급업체는 10의 거듭제곱으로 판매하고 운영 체제는 2의 거듭제곱을 보고하며 그 차이는 모든 규모에서 약 7%입니다. 그것은 잘못이 아니며 두 가지 관례입니다."},{"h":"실제 사례: 잘못된 API 응답"},{"p":"웹후크가 검증에 실패하고 로그의 페이로드는 `\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f`와 같습니다. 이것은 90초의 진단이다."},{"l":["**1. 변환.** `48656c6c6f`를 [[hex-text|Hex to Text]] 변환기에 붙여넣습니다. 결과는 `Hello`입니다. 결코 왜곡되지 않았고 단지 인코딩되었을 뿐입니다.","**2. 모양을 확인하세요.** 업스트림에서 서명하기 전에 페이로드를 16진수로 인코딩하고 있습니다. 서명은 원본 텍스트에 대해 계산되고 16진수에 대해 유효성이 검사되었으므로 비교가 실패합니다.","**3. 다른 방향은 배제하세요.** 로그에 읽을 수 있는 텍스트가 표시되어 있었다면 문제는 그 반대였을 것입니다. 즉, 인코딩된 양식에 서명하는 것입니다.","**4. 크기 요구를 확인하십시오.** 동일한 로그가 1.2MB 페이로드를 보고하는 경우, [[file-size-converter|파일 크기 변환기]]는 누군가가 할당량에 대해 논쟁하기 전에 그것이 십진수인지 이진수인지를 결정합니다."]},{"h":"자주 묻는 질문"},{"p":"**모든 것이 브라우저에서 실행되는 경우 비밀번호 생성기는 안전한가요?** 그렇습니다. 서버 기반 비밀번호보다 더 그렇습니다. 비밀번호는 컴퓨터에서 생성되고 전송되지 않으므로 가로채거나 기록하거나 위반할 일이 없습니다. 단점은 저장하지 않은 비밀번호를 복구할 수 없다는 것입니다.\\n\\n**가상 동전 뒤집기를 신뢰할 수 있나요?** 일상적인 결정의 경우 그렇습니다. 금품이나 상품이 첨부된 모든 것에 대해서는 감사할 수 있는 출처를 사용하십시오.\\n\\n**암호는 안전합니까?** 아니요. 아무것도 아닙니다. ROT13 및 Caesar 암호에는 비밀 키가 없으며 암호화를 가르치기 위해 존재하며 아무것도 보호하기 위해 존재하지 않습니다.\\n\\n**오프라인에서 작동합니까?** 페이지가 로드되면 그렇습니다. 모든 것이 로컬입니다.\\n\\n**변환기의 텍스트 길이에 제한이 있나요?** 아무데도 전송되지 않으므로 기기의 메모리만 필요합니다."},{"h":"한 줄 버전"},{"p":"긴 고유 비밀번호는 짧고 영리한 비밀번호를 능가하며, QR 코드는 내부 데이터만큼만 우수하고, 시간대 오프셋을 계산하는 대신 확인하며, 인코딩은 암호화가 아닙니다."}]}}')},64591,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"El kit de herramientas para desarrolladores: 24 herramientas de navegador gratuitas que reemplazan las aplicaciones pagas","description":"Una guía práctica para formatear, convertir, codificar y depurar datos utilizando herramientas de desarrollo gratuitas basadas en navegador: sin instalaciones, sin cuentas, sin carga.","category":"Herramientas para desarrolladores","blocks":[{"p":"La mayoría de los pequeños trabajos que se realizan cien veces por semana (reformatear una respuesta API, decodificar un token, verificar un hash, sangrar un fragmento de SQL) no necesitan un IDE, una suscripción paga o una licencia de equipo. Necesitan una pestaña abierta durante noventa segundos.\\n\\nLa siguiente colección consta de veinticuatro utilidades basadas en navegador que cubren formato, conversión, codificación, hash y depuración. Cada uno de ellos se ejecuta completamente en su página: sus datos nunca se envían a un servidor, lo cual es más importante de lo que los desarrolladores suelen admitir, porque la carga útil que pega suele ser la de un cliente."},{"h":"Qué herramientas basadas en navegador pueden y no pueden reemplazar"},{"p":"Sea realista acerca de los límites. Estas herramientas reemplazan tareas únicas, de bajo riesgo y de alta frecuencia. No reemplazan su servidor de idiomas, su depurador, su conjunto de pruebas ni cualquier cosa que necesite ejecutar en un entorno real repetidamente."},{"l":["**Buen ajuste:** leer una respuesta una vez, depurar un valor único, convertir un archivo para una importación, verificar un formato antes de enviarlo.","**Mal ajuste:** ejecutar la misma verificación en cada implementación, transformar cientos de archivos, cualquier cosa que deba fallar estrepitosamente en CI.","**Nunca:** cualquier cosa que involucre credenciales que no puedas rotar. Pegue un token revocado, no uno activo."]},{"p":"Dicho esto, la razón para mantenerlos marcados es el rendimiento. Una tarea que tarda cuarenta segundos en una pestaña del navegador nunca se programa, nunca se delega y nunca se convierte en un motivo para abrir un IDE a las ocho de la tarde."},{"h":"Formatear y convertir datos"},{"p":"El trabajo diario más común es hacer que los datos sean legibles. Una API devuelve un blob de una sola línea, un colega envía un archivo de configuración con pestañas destrozadas por una ventana de chat, o usted exportó una hoja de cálculo a JSON y regresó como una línea enorme."},{"l":["[[json-formatter|JSON Formatter]] — sangría, valida y lee una carga útil. Úselo antes de depurar: la mitad de todos los tickets de \\"la API no funciona\\" en realidad son JSON con formato incorrecto con una coma al final.","[[json-validator|Validador JSON]] — cuando necesitas una respuesta estricta de pasa/falla en lugar de una letra bonita.","[[xml-formatter|Formateador XML]]: el mismo trabajo para respuestas SOAP, feeds RSS y POM Maven que nadie ha tocado desde 2014.","[[json-to-yaml|JSON a YAML]] y [[json-to-csv|JSON a CSV]]: mover datos entre los formatos que realmente utilizan los sistemas reales."]},{"p":"Tenga en cuenta el último grupo para un escenario específico: un cliente le entrega una hoja de cálculo y la espera en su API. Pasar de CSV a JSON directamente es un trabajo de dos minutos en lugar de una tarde de secuencias de comandos."},{"h":"Codificar y escapar"},{"p":"Los errores de codificación son desproporcionadamente molestos porque los datos se ven bien. El valor \\"San José & Sons\\" llega como \\"San José%C3%A9 %26 Sons\\" y su comparación con la base de datos falla por razones que son invisibles en los registros."},{"l":["[[url-encoder|Codificador/Decodificador de URL]] — determina inmediatamente si una cadena de consulta tiene doble codificación.","[[base64-encoder|Codificador/Decodificador Base64]]: decodifica un fragmento de certificado o codifica un pequeño recurso para integrarlo en CSS.","[[html-entity-encoder|Codificador/Decodificador de entidades HTML]]: descubre si ese \\"&\\" perdido en tu página proviene de tu plantilla o de tus datos.","[[unicode-converter|Convertidor Unicode]] — útil cuando un carácter \\"roto\\" resulta ser legítimo y se representa con una codificación incorrecta.","[[number-base-converter|Convertidor de bases numéricas]] — comprueba un color, una máscara de bits de permiso o una dirección de memoria sin una aplicación de calculadora."]},{"b":"Un hábito práctico: cuando un valor llega confuso, decodificarlo capa por capa y pega cada resultado en un campo en blanco. Si la primera decodificación produce texto legible, el problema es una codificación adicional en algún lugar anterior. Si produce mojibake, tiene un problema de codificación en lugar de un problema de escape, y esos dos necesitan soluciones diferentes."},{"h":"Identificadores, hashes y tokens"},{"p":"Este grupo es donde los desarrolladores pierden la mayor parte del tiempo buscando el script local correcto que escribieron una vez y perdieron."},{"l":["[[uuid-generator|Generador UUID]] — genera identificadores v4 para datos iniciales, accesorios o una fila rápida de la base de datos.","[[md5-generator|MD5 / SHA Hash Generator]] — verifica una descarga o confirma que dos archivos que deberían ser idénticos realmente lo son.","[[timestamp-converter|Timestamp Converter]] — la herramienta más utilizada en toda esta lista. Cuando una línea de registro dice 1761000000, esto es lo que le indica si el incidente ocurrió durante la implementación o antes."]},{"p":"El conversor de marcas de tiempo se gana la vida por una razón específica: un número de época es inequívoco y al mismo tiempo inútil. Sabes exactamente cuándo sucedió algo y no puedes decírselo a un colega. La conversión una vez suele resolver una discusión más ruidosa de lo que debería."},{"h":"Comparar y depurar"},{"l":["[[regex-tester|Regex Tester]] — el elemento de mayor apalancamiento aquí. Una expresión regular que parece correcta y silenciosamente no coincide con nada es uno de los errores más costosos en desarrollo, porque falla silenciosamente en un lugar que nadie lee.","[[html-preview|Vista previa HTML]] — itera sobre un fragmento de marcado para comprobar cómo se representa realmente."]},{"p":"Pruebe sus expresiones regulares con la entrada que realmente espera, incluida la cadena vacía, un nombre Unicode y un valor con una nueva línea. La mayoría de los patrones se rompen en el tercer caso y nadie se da cuenta hasta que llegan los datos de producción."},{"h":"Un ejemplo práctico: tres herramientas, un incidente aburrido"},{"p":"Aquí está la secuencia que me convenció de marcar todo esto como favorito. Un cliente informó que un registro que envió el martes faltaba en un informe del jueves."},{"l":["**1. Convierta la marca de tiempo.** El trabajo de informe registró la hora de creación del registro como un valor de época. El [[timestamp-converter|Timestamp Converter]] mostró que el registro se creó a las 11 p.m. local, que es el martes; la suposición de zona horaria del trabajo fue el problema, no el registro.","**2. Formatee la carga útil.** Al tomar el JSON almacenado a través del [[json-formatter|JSON Formatter]] se reveló que el registro se escribió con un campo de fecha nulo, porque el cliente llamó dos veces al mismo punto final con 200 ms de diferencia y ganó la segunda escritura.","**3. Compare las cargas útiles.** Ambos registros llevaban la misma clave API y la misma marca de tiempo del cliente, lo que apuntaba a un reintento en lugar de dos clientes separados."]},{"p":"Tiempo total transcurrido: cuatro minutos. El intento anterior de esta investigación, que buscaba la misma causa raíz en una plataforma maderera, tomó una tarde y arrojó una conclusión equivocada."},{"h":"Privacidad: por qué ejecutar localmente es la característica real"},{"p":"Cada herramienta de esta biblioteca procesa su entrada dentro de su propio navegador. No se carga nada, lo que significa que no hay preguntas sobre retención, ni acuerdos con el procesador ni conversaciones incómodas sobre la carga útil de producción que pegaste hace tres minutos.\\n\\nEsta es la razón para preferir estas herramientas a una \\"API de Pastebin\\" alojada o un servicio en línea que le solicita que se registre. También significa que siguen trabajando en un vuelo, en un sótano o cuando la VPN corporativa ha decidido bloquear otro dominio."},{"p":"Una advertencia que vale la pena señalar claramente: una página con capacidad sin conexión solo es privada si la página en sí es el código que usted cree que es. En una máquina compartida, use una ventana privada y ciérrela cuando haya terminado, especialmente si ha estado decodificando tokens."},{"h":"Construyendo un flujo de trabajo alrededor de ellos"},{"p":"Las herramientas son individualmente triviales. El valor es el hábito de buscar uno inmediatamente en lugar de \\"llegar a él más tarde\\", porque más tarde es cuando escribes un script desechable, abres un IDE o decides que no vale la pena verificarlo en absoluto."},{"l":["Añade la colección a favoritos, no las URL individuales, y colócala en la barra de herramientas de tu navegador.","Cuando algo parezca mal, verifíquelo antes de formular una teoría. Cuesta quince segundos; mata clases enteras de conclusiones erróneas.","Cuando hayas verificado lo mismo dos veces, esa es la señal para automatizarlo, pero no lo automatices por sospecha.","No pegue secretos de producción. Gire cualquier cosa de la que no esté seguro."]},{"h":"Preguntas frecuentes"},{"p":"**¿Estas herramientas son gratuitas?** Sí, completamente, sin cuenta y sin límite de uso. No existe ningún nivel pago que retenga nada básico.\\n\\n**¿Funcionan sin conexión?** Una vez que se ha cargado una página, sí, todo se ejecuta en su navegador. La recarga requiere una conexión.\\n\\n**¿Puedo usarlos para trabajos comerciales?** Sí. El resultado es suyo sin requisito de atribución.\\n\\n**¿Existe una API?** No, y eso es deliberado: el valor es la interfaz. Exporta el resultado y procésalo como quieras.\\n\\n**¿Por qué no simplemente instalar una herramienta CLI?** Instale una cuando la necesite tres veces. Utilice una pestaña del navegador para los dos primeros."}]},"text-tools-for-writers":{"title":"17 herramientas de texto gratuitas para escritores, estudiantes y especialistas en marketing","description":"Limpie el texto, cuente palabras con precisión, dé formato a listas y convierta borradores en algo publicable, con herramientas de navegador gratuitas que nunca cargan su texto.","category":"Herramientas de texto","blocks":[{"p":"Escribir para el trabajo implica una sorprendente cantidad de trabajo mecánico que no tiene nada que ver con la escritura: eliminar espacios en blanco perdidos de un párrafo pegado, verificar un límite de palabras, eliminar duplicados de una lista de nombres, convertir algo en una URL.\\n\\nEstas diecisiete herramientas son para esa parte del trabajo. Todos se ejecutan localmente en el navegador, lo cual no es un detalle menor: el borrador que pegas a menudo no está publicado y la lista que estás ordenando suele contener datos personales de alguien."},{"h":"Midiendo lo que has escrito"},{"p":"El recuento de palabras parece resuelto hasta que un cliente solicita exactamente 800 palabras y su editor dice 820, o un formulario rechaza su texto con 1995 caracteres sin explicación de dónde fue la nueva línea."},{"l":["[[word-counter|Contador de palabras]] — la medida estándar. Pegar, leer, ajustar.","[[letter-counter|Contador de letras]] — cuenta los caracteres y la frecuencia de las letras. Útil cuando estás depurando por qué un párrafo parece incorrecto: generalmente es un patrón de letras repetido, no un sueño."]},{"p":"Una nota sobre lo que significa \\"una palabra\\": diferentes contadores no están de acuerdo con la separación de palabras, los números y las URL. Si un número exacto es importante, use el mismo contador que usa la persona que revisa su trabajo y acuerdelo de antemano. Esta es una fuente genuinamente común de pequeñas discusiones sin sentido."},{"h":"Limpiar la copia que no escribiste"},{"p":"La mayor parte del texto que recibe está levemente dañado: espacios dobles debido a copiar y pegar, una pestaña perdida, mayúsculas inconsistentes debido a que alguien escribe con prisa. Arreglarlo a mano es lento y propenso a errores."},{"l":["[[text-trimmer|Recortador de texto]] — elimina los espacios en blanco iniciales y finales de cada línea a la vez. Esto corrige más informes de \\"el formato parece roto\\" que cualquier otra cosa en esta lista.","[[text-case-converter|Convertidor de casos de texto]] — cambia entre mayúsculas y minúsculas de oración, mayúsculas y minúsculas en un bloque. También es la forma más rápida de deshacer un párrafo BLOQ MAYÚS accidental.","[[text-to-slug|Text to Slug]]: convierte un título en un slug de URL limpio. Pega tu título, consigue el slug y listo."]},{"p":"El generador de slug tiene un uso más allá de las URL: es una forma rápida de crear un nombre de archivo o un ancla legible que un humano puede analizar de un vistazo, lo que supera a `final_final_v3`."},{"h":"Trabajar con listas"},{"p":"Listas, inventarios, combinación de correspondencia, limpieza de etiquetas, respuestas a encuestas, columnas de hojas de cálculo: en algún momento, todo se convierte en una lista y cada lista necesita ordenarse, eliminar duplicaciones o aleatorizarse."},{"l":["[[duplicate-line-remover|Eliminador de líneas duplicadas]] — compara dos listas o limpia una. El resultado le indica cuántos duplicados se eliminaron, lo cual resulta útil cuando informa el resultado.","[[list-sorter|Clasificador de listas]] — el mismo trabajo para la entrada de listas estructuradas.","[[list-randomizer|List Randomizer]]: mezcla un orden de sorteo, una secuencia de prueba o una lista corta delimitada para que nadie sospeche de favoritismo.","[[line-number-adder|Sumador de números de línea]] — líneas numéricas para referencia en un ticket o comentario de revisión de código."]},{"b":"La trampa clásica aquí es una lista que parece deduplicada pero no lo es: `Apple`, `apple ` y `Apple.` son tres líneas diferentes para una computadora. Recorte los espacios en blanco y elimine la puntuación final antes de deduplicar, o no fusionará nada y concluirá que los datos están limpios."},{"h":"Vista previa y formato"},{"p":"Markdown ha ganado, pero no de manera uniforme. La mitad de sus herramientas lo renderizan, la otra mitad no, y la mitad que no lo hace suele ser en la que alguien superior tiene que pegar."},{"l":["[[markdown-preview|Markdown Preview]] — renderizado en vivo, para que puedas comprobar que una tabla o una lista anidada realmente se ve bien antes de llegar a un cliente.","[[text-repeater|Repetidor de texto]] — repite una cadena N veces. Útil para generar relleno, datos de prueba o, ocasionalmente, resaltar un punto en un documento."]},{"p":"La vista previa Markdown es la herramienta que silenciosamente ahorra más tiempo en todo este conjunto, porque una tabla rota en un documento renderizado es mucho más visible (y mucho más vergonzosa) que una tabla rota en texto sin formato."},{"h":"El resto y cuándo alcanzarlos"},{"l":["[[random-string|Generador de cadenas aleatorias]] — genera nonces legibles, ID de marcador de posición o códigos cortos. Mejor que inventar algo a mano, porque no lo reutilizarás accidentalmente.","[[morse-code|Traductor de código Morse]]: realmente divertido, en ocasiones útil para un proyecto temático o un rompecabezas."]},{"p":"Estas son herramientas de menor frecuencia, pero mantenerlas marcadas no cuesta nada y resuelven el problema específico de \\"Necesito un valor de apariencia aleatoria en este momento y no confío en mí mismo para inventar uno\\"."},{"h":"Un pase de edición realista"},{"p":"Este es el orden que funciona cuando llega un borrador de otra persona y debe enviarse a su nombre."},{"l":["**1. Recortar.** Ejecute todo el documento a través del [[text-trimmer|Text Trimmer]] primero. El daño de los espacios en blanco se esconde dentro de los párrafos donde nunca lo verás.","**2. Mayúsculas y minúsculas limpias.** Utilice el [[text-case-converter|Text Case Converter]] solo para el título. Nunca apliques la conversión de mayúsculas y minúsculas a un borrador completo: destruye los nombres propios.","**3. Mide.** Comprueba la longitud con el [[contador de palabras|Contador de palabras]] antes de escribir, para saber qué forma debe tener la pieza.","**4. Vista previa.** Si contiene Markdown, renderícelo con la [[markdown-preview|Markdown Preview]].","**5. Slug.** Genere el slug de URL al final, desde el título final, con [[text-to-slug|Text to Slug]]; cambiar el título después rompe el slug."]},{"p":"Todo el pase dura unos minutos y elimina la categoría de error en el que un documento es técnicamente correcto y visiblemente incorrecto."},{"h":"Preguntas de los escritores sobre la privacidad"},{"p":"**¿Mi texto no publicado sale de mi computadora?** No. Estas herramientas procesan el texto en su navegador y no se almacena ni transmite nada.\\n\\n**¿Existe un límite de longitud?** No hay límite del lado del servidor porque no hay ninguna llamada al servidor. Las entradas extremadamente grandes están limitadas por la memoria de su propio dispositivo.\\n\\n**¿Puedo utilizar el resultado comercialmente?** Sí, libremente, sin atribución.\\n\\n**¿Funcionan en un teléfono?** Sí. El diseño se adapta y se ejecuta el mismo código."},{"h":"Lo que estas herramientas no harán por ti"},{"p":"Vale la pena ser franco acerca de los límites, porque una herramienta que mecaniza algo incorrecto sólo produce un error más rápido.\\n\\nNinguna de estas utilidades puede indicarle si una frase es clara, si la afirmación tiene su origen o si el tono es adecuado para la audiencia. Cuentan personajes; no juzgan la prosa. Un texto que obtiene una excelente puntuación en todas las métricas de esta página aún puede resultar ilegible.\\n\\nTampoco editan. En el momento en que te encuentras reescribiendo cláusulas individuales a mano a escala, se te ha quedado pequeña una herramienta de texto y necesitas un editor adecuado, un buscador y reemplazo con expresiones regulares (que el [[regex-tester|Regex Tester]] es realmente bueno para ensayar) o un guión. Utilice el navegador para la capa mecánica y mantenga su propio criterio para todo lo que está encima de ella."},{"p":"Una cosa más que no harán es arreglar una fuente defectuosa. Si su hoja de cálculo está llena de nombres inconsistentes: \\"Dr\\", \\"DR\\", \\"Dr.\\" todo en una columna: una herramienta ordenará y eliminará duplicados fielmente de lo que le proporcionó, y aún tendrá tres entradas donde debería haber una. Limpiar los datos es una decisión, no un paso mecánico. Primero decida la forma canónica, luego aplíquela y luego verifique."},{"h":"Mantener una lista de trabajo utilizable"},{"p":"Si mantiene una lista de clientes potenciales, enlaces, referencias o términos, se degrada silenciosamente. El modo de falla es siempre el mismo: las entradas que parecen idénticas no lo son y una combinación no elimina nada.\\n\\nUna pasada de mantenimiento que funciona es aburrida: recortar espacios en blanco, estandarizar las mayúsculas, eliminar la puntuación final y luego eliminar duplicados. En ese orden, al recortar después de eliminar duplicados se pierden las entradas. Hacer esto una vez al mes en una lista activa convierte un desastre irrecuperable de dos horas en una tarea de diez minutos.\\n\\nCuando es necesario conciliar dos listas (por ejemplo, una lista de registro con una lista de asistencia), ordene ambas con el [[list-sorter|List Sorter]] primero, para que se alineen y luego comparen a ojo. Clasificar ambos lados antes de comparar es la diferencia entre una verificación de dos minutos y una búsqueda de veinte minutos."},{"h":"la comida para llevar"},{"p":"Ninguna de estas herramientas es inteligente. Ésa es la cuestión: eliminan el cinco por ciento mecánico de la escritura que no es escritura, de modo que el noventa y cinco por ciento restante se trata en realidad de oraciones. Añade a favoritos los que usas mensualmente, ignora el resto y deja de arreglar los espacios en blanco a mano."}]},"calculators-and-converters-guide":{"title":"18 calculadoras y convertidores gratuitos para los números con los que realmente trabajas","description":"Porcentajes, descuentos, propinas, préstamos, fechas, IMC y conversiones de unidades: calculadoras de navegador gratuitas que muestran su razonamiento y nunca guardan sus datos.","category":"Calculadoras","blocks":[{"p":"Todo el mundo necesita dividir una factura, determinar si un descuento es realmente un descuento y convertir una temperatura o un tamaño de archivo sin pensar en ello. Todo el mundo también, al menos una vez, se equivoca en público.\\n\\nEsta es una colección de dieciocho calculadoras y convertidores que cubren dinero, fechas, salud y las conversiones de unidades que aparecen en el trabajo y los viajes. Todos se ejecutan en el navegador: no se guarda nada, por lo que los números que escribas no son asunto de nadie más que tuyo."},{"h":"Cálculos de dinero"},{"p":"La matemática más común en el mundo real es un porcentaje de algo. Impuesto sobre las ventas, una propina, un descuento, una comisión, una tasa de crecimiento. La fórmula es simple y, sin embargo, la razón por la que la gente se equivoca es casi siempre la misma: aplican un porcentaje a la base equivocada."},{"l":["[[discount-calculator|Calculadora de descuentos]] — calcula el precio final y, más importante aún, cuánto ahorraste. Útil para detectar un \\"50% de descuento\\" que en realidad es un 20% después de un precio de lista elevado.","[[tip-calculator|Calculadora de propinas]] — divide una factura, elige un porcentaje, redondea por persona si así lo deseas.","[[calculadora de préstamos|Calculadora de préstamos]] — pago mensual e interés total, que es el número que realmente decide si un préstamo es asequible."]},{"b":"Sobre descuentos: un descuento del 20% seguido de otro descuento del 20% no es un 40% de descuento, sino un 36%. Compuesto de porcentajes secuenciales sobre la base reducida. Cualquier calculadora de esta lista lo confirmará en unos dos segundos y es el dato aritmético más útil de este artículo."},{"p":"La calculadora de préstamos merece una nota específica. La cifra que importa no es el pago mensual, sino el interés total pagado durante la vigencia del préstamo, porque ese es el costo real del préstamo. Dos préstamos con pagos mensuales idénticos y términos diferentes pueden diferir en decenas de miles en el interés total."},{"h":"Fechas y cuentas atrás"},{"p":"La aritmética de fechas es donde la mayoría de la gente se equivoca silenciosamente, porque los meses humanos tienen diferentes duraciones y la respuesta cambia dependiendo de si te refieres a \\"meses calendario\\" o \\"30 días\\"."},{"l":["[[date-difference|Calculadora de diferencia de fechas]] — días (y total de meses, años) entre dos fechas.","[[days-until|Calculadora de días hasta]]: una cuenta regresiva hasta una fecha específica, donde la cantidad de días hábiles generalmente es lo que la gente realmente quiere.","[[calculadora de edad|Calculadora de edad]] — edad exacta en años y días, más el próximo cumpleaños.","[[timestamp-converter|Convertidor de marcas de tiempo]] — una marca de tiempo de Unix en una fecha real, lo cual importa si tocas registros, bases de datos o respuestas de API."]},{"p":"La distinción que hace tropezar a la gente: el número de días entre el 1 de marzo y el 1 de abril es 31, pero el número de *meses* es uno. Si está calculando un período de notificación o un período de suscripción, indique por escrito a qué unidad se refiere."},{"h":"Cifras de salud, sinceramente"},{"l":["[[bmi-calculator|Calculadora de IMC]] — índice de masa corporal con las categorías estándar y las advertencias a continuación."]},{"p":"El IMC es una estadística de detección a nivel poblacional. No dice nada sobre la masa muscular, la composición corporal o la salud de ningún individuo, y es un indicador deficiente del estado físico en atletas, adultos mayores y en diferentes grupos étnicos. Úselo como un punto de datos entre varios, o como una forma de rastrear un cambio a lo largo del tiempo, no como un veredicto. Si está tomando decisiones que afectan su salud, la herramienta adecuada es un médico, no una pestaña del navegador."},{"h":"Conversión de unidades: las de todos los días"},{"p":"La conversión de unidades se divide en dos tipos: conversiones que debes realizar exactamente correctamente y conversiones que necesitas de forma aproximada. Estas herramientas manejan ambos, y el trabajo consiste en recordar cuál es cuál."},{"l":["[[convertidor de longitud|Convertidor de longitud]] — métrico a imperial y viceversa: milímetros, centímetros, metros, kilómetros, pulgadas, pies, yardas, millas.","[[convertidor de peso|Convertidor de peso]] — gramos, kilogramos, onzas, libras, toneladas. El de consultar antes de una receta o de una etiqueta de envío.","[[convertidor de temperatura|Convertidor de temperatura]] — Celsius, Fahrenheit, Kelvin. Porque -10°C no es 14°F y la fórmula no es una multiplicación.","[[speed-converter|Convertidor de velocidad]] — km/h, mph, m/s, nudos. Útil para un límite de velocidad extranjero o una especificación de ingeniería.","[[area-converter|Convertidor de área]] — metros cuadrados, pies cuadrados, acres, hectáreas. Este es el que la gente valora mal a la hora de comprar o alquilar una propiedad.","[[volume-converter|Convertidor de volumen]] — litros, mililitros, galones, tazas, metros cúbicos.","[[time-converter|Convertidor de tiempo]] — segundos, minutos, horas, días, semanas."]},{"b":"Dos trampas de conversión que vale la pena conocer: la del almacenamiento de datos mencionada anteriormente (los especialistas en marketing venden 10 ^ 3, los sistemas operativos informan 2 ^ 10) y la economía de combustible: un automóvil cotizado a 40 mpg (imperial) está más cerca de 33 mpg (EE. UU.) que 40, porque el galón imperial es más grande. Equivocarse en el segundo hace que un coche de alquiler parezca irrealmente eficiente."},{"h":"Los dos que no esperarás necesitar"},{"l":["[[random-number|Generador de números aleatorios]] — sorteos dentro de un rango, para una rifa, un grupo o una división rápida A/B. Útil precisamente porque elimina la sospecha de que lo has manipulado.","[[dice-roller|Rodillo de dados]] — cualquier dado, desde un lanzamiento de moneda hasta un dado de veinte caras, para un juego de mesa o una sesión de mesa en la que el dado real ha salido de la mesa por última vez."]},{"h":"Usar una calculadora correctamente"},{"p":"Una calculadora sólo ayuda si sabes sobre qué número estás preguntando. Tres hábitos marcan la diferencia."},{"l":["**Redondea primero, calcula el segundo.** Si el número exacto no cambia tu decisión, redondea uno. Los porcentajes de números redondos se pueden comprobar mentalmente, lo que detecta errores de entrada.","**Verifique la cordura de la magnitud.** Antes de creer en un resultado, pregunte si debería ser mayor o menor que la entrada, y aproximadamente en cuánto. La mayoría de los errores aritméticos sobreviven a todas las comprobaciones excepto a ésta.","**Fotografíe las entradas, no las salidas.** Cuando vuelva a ejecutar el cálculo más tarde, lo que importa es saber lo que supuso, no lo que concluyó."]},{"h":"Preguntas que la gente realmente hace"},{"p":"**¿Mis números se almacenan en algún lugar?** No. Los cálculos se realizan en su navegador y no se transmite ni retiene nada.\\n\\n**¿Funcionan en un teléfono?** Sí, y las calculadoras están diseñadas para usarse con una sola mano.\\n\\n**¿Qué estándar de conversión utiliza para el almacenamiento de datos?** Decimal (1 KB = 1000 bytes) de forma predeterminada, porque así es como se vende el almacenamiento. Los sistemas operativos informan binario, razón por la cual una unidad parece reducirse: la herramienta explica la diferencia en lugar de elegir silenciosamente un lado.\\n\\n**¿Puedo insertarlos en mi propio sitio?** No. En su lugar, márquelos como favoritos; el costo de esto es cero y el problema de precisión es suyo."},{"h":"Porcentajes: los cuatro errores que importan"},{"p":"Casi cada porcentaje de error que comete una persona en la vida diaria es uno de los mismos cuatro errores. Nombrarlos los hace evitables."},{"l":["**Base incorrecta.** \\"Un aumento del 10% y luego una caída del 10% te deja donde empezaste\\" es falso, porque ambos se aplican a bases diferentes. El diez por ciento de 100 es 10; el diez por ciento de 90 es 9.","**Porcentaje de un porcentaje.** Acumular dos descuentos los multiplica (0,8 × 0,8 = 0,64, es decir, 36 % de descuento), no los suma.","**Porcentaje versus puntos porcentuales.** Una tasa que va del 4% al 6% ha aumentado 2 puntos porcentuales, pero un 50% en términos relativos. La política y la medicina están llenas de esta confusión y no siempre es accidental.","**Redondear demasiado pronto.** Redondear un paso intermedio antes de aplicar un porcentaje agrava el error. Mantenga la precisión total hasta la cifra final y realice el último paso en una calculadora en lugar de hacerlo mentalmente."]},{"p":"Si solo tomas un hábito de toda esta sección, toma este: antes de citar un porcentaje a alguien, repite qué es un porcentaje *de*. La mitad de los argumentos que tendrás sobre un número son en realidad argumentos sobre el denominador."},{"h":"Saber cuándo dejar de calcular"},{"p":"Llega un punto en el que la precisión deja de ser útil. Un pago mensual con dos decimales es significativo. Un coste total proyectado con ocho decimales es una forma de evitar la decisión real, que es si el préstamo se ajusta a lo que puedes permitirte sin estrés.\\n\\nLa prueba útil es la pregunta de sensibilidad: ¿cambia la decisión si este insumo se mueve un 10%? De lo contrario, deje de refinarlo y use el tiempo adicional en la variable que sí mueve la respuesta (generalmente el plazo en lugar de la tasa, o el precio de lista en lugar del descuento)."},{"p":"Y hay un límite que vale la pena señalar claramente: estas calculadoras son aritméticas, no consejos. Un objetivo de ahorro, una fecha de jubilación y un plan de pago de deudas son decisiones sobre riesgo, comportamiento y tiempo, y una pestaña del navegador no puede sopesar ninguna de ellas. Sólo puede decirle lo que implican los números una vez que haya decidido lo que está suponiendo. Esa distinción es la diferencia entre que una calculadora sea útil y responsable."},{"h":"La versión de una sola línea"},{"p":"Marque correctamente las calculadoras de dinero y fecha, trate el IMC como una señal en lugar de un veredicto, recuerde que los porcentajes acumulados se multiplican y verifique la conversión de unidades cada vez que un número entre en algo contractual. Eso cubre casi todo."}]},"image-and-design-tools":{"title":"14 herramientas gratuitas de imagen y diseño que se ejecutan en tu navegador","description":"Comprima, cambie el tamaño y prepare imágenes, y genere efectos CSS, paletas, controles de contraste y favicons sin instalar Photoshop o un paquete de diseño.","category":"Herramientas de diseño","blocks":[{"p":"El trabajo con imágenes tiene un problema específico: el trabajo suele ser pequeño y las herramientas que se ofrecen son enormes. Necesita eliminar 400 KB de una imagen principal, obtener un valor hexadecimal que mencionó su diseñador o generar un favicon que nadie ha creado todavía. Eso no requiere suscripción.\\n\\nLas catorce herramientas siguientes cubren la preparación de imágenes, el trabajo con color, la generación de efectos CSS y los pequeños recursos de producción que pasan desapercibidos. Cada uno se ejecuta localmente, lo que es más importante para las imágenes que para el texto: la foto que acabas de comprimir suele ser una foto que aún no has publicado."},{"h":"Preparando imágenes para la web."},{"p":"La mayoría de los problemas de imagen son en realidad problemas de peso. Una página que se siente lenta generalmente contiene imágenes que son más grandes que su tamaño de visualización, en el formato incorrecto y con una configuración de calidad que nadie jamás cuestionó."},{"l":["[[image-compressor|Compresor de imágenes]] — reduce el tamaño del archivo manteniendo la imagen visualmente intacta. Ejecútelo antes de cargar algo en un formulario con un límite de tamaño.","[[image-resizer|Image Resizer]] — establece las dimensiones reales en píxeles que necesitas. Esta es la mayor ganancia: una imagen de 4000 px mostrada a 800 px contiene cinco veces los datos que necesita.","[[image-to-base64|Imagen a Base64]]: convierte una imagen pequeña en un URI de datos para insertarla en CSS, HTML o una plantilla de correo electrónico."]},{"b":"El orden importa. Cambie el tamaño primero, comprima segundo. Comprimir una imagen de 4000 px produce un archivo mucho más pesado que cambiar el tamaño a 800 px y luego comprimirlo con la misma calidad, porque los compresores dedican su esfuerzo a píxeles que de todos modos se desecharían."},{"p":"¿Cuánto debes comprimir? La respuesta honesta es: hasta que parezca mal, retroceda un paso. Para una imagen fotográfica destacada, la calidad entre el 70 y el 80 por ciento suele ser indistinguible del original en un tamaño de visualización normal. Para un logotipo, una captura de pantalla o cualquier cosa con color plano y bordes duros, use PNG y comprima más fuerte; estos ganan más y pierden menos."},{"p":"Una regla práctica: cualquier valor inferior a 200 KB está bien para una imagen principal, menos de 80 KB para una miniatura, y si no puede obtener menos de 300 KB, probablemente tenga un problema de dimensión en lugar de un problema de calidad."},{"h":"Base64: cuando insertar es la decisión correcta"},{"p":"Convertir una imagen a un URI de datos Base64 elimina una solicitud HTTP, lo que suena como una pura victoria. Generalmente no lo es. La cadena codificada es aproximadamente un tercio más grande que el archivo binario, no se puede almacenar en caché por separado y sobrecarga su CSS o HTML.\\n\\nEn línea solo cuando la imagen es pequeña (menos de unos pocos kilobytes), se usa una vez y es crítica. Un pequeño icono en una única plantilla de correo electrónico es el caso clásico. Para cualquier cosa que se repita en varias páginas o que supere unos pocos kilobytes, sírvala como un archivo y deje que el navegador lo almacene en caché."},{"h":"Marcas de agua: lo que es honestamente removible"},{"l":[]},{"p":"Sea claro sobre lo que esto hace. Elimina u oscurece la marca visible. No puede reconstruir los píxeles subyacentes: la información sobre la que se pintó desaparece y ningún filtro la recupera. Los resultados varían desde invisible, cuando la marca se asienta sobre un fondo liso, hasta una mancha obvia cuando se asienta sobre detalles.\\n\\nUna cosa más que vale la pena decir claramente: eliminar la marca de agua de otra persona y publicar el resultado es un problema de derechos de autor en la mayoría de las jurisdicciones y una violación de la licencia, independientemente de si lo atraparán. El objetivo de esta herramienta es eliminar marcas de sus propias imágenes o de las que tiene bajo licencia."},{"h":"Color: convertir, comprobar, elegir."},{"p":"El color es donde los pequeños errores se vuelven muy visibles. Una relación de contraste que no es accesible, un valor hexadecimal que en realidad es un triple HSL, una paleta que parece coherente en el monitor y turbia en un proyector."},{"l":["[[color-converter|Convertidor de colores]] — muévete entre HEX, RGB y HSL. Vale la pena aprender a leer HSL, porque el tono 210, la saturación del 40 por ciento y la luminosidad del 50 por ciento son mucho más fáciles de ajustar a mano que un valor hexadecimal.","[[contrast-checker|Contrast Checker]] — prueba el texto en su contexto según los umbrales WCAG. Esta es la herramienta más útil de este artículo, porque detecta un problema de cumplimiento real en lugar de un problema de sabor.","[[color-palette|Generador de paleta de colores]] — genera un conjunto coherente cuando comienzas con un color de marca y necesitas el resto de la escala."]},{"b":"Por el contrario: WCAG AA solicita 4,5 a 1 para texto de cuerpo normal y 3 a 1 para texto grande. Si elige entre dos colores de marca para un botón, el disponible no suele ser el que le gusta al diseñador. Verifique primero, luego discuta con los datos."},{"p":"Una advertencia sobre las herramientas de color: todas asumen que su monitor está calibrado y que la persona que ve su página tiene ojos que funcionan. Ninguna suposición es segura. Ésa es una razón para preferir las combinaciones contrastadas a las subjetivas."},{"h":"Efectos CSS sin abrir una herramienta de diseño"},{"p":"Escribir a mano un degradado o una sombra en capas es una tarea realmente desagradable. La sintaxis es complicada, no puedes ver lo que estás produciendo y la diferencia entre una buena sombra y una mala son unos pocos píxeles de desenfoque."},{"l":["[[gradient-generator|Generador de gradiente CSS]] — crea gradientes lineales y radiales y copia el CSS directamente.","[[box-shadow-generator|Box Shadow Generator]] — superpone múltiples sombras, que es lo que separa una elevación sutil de una caída pronunciada.","[[border-radius-generator|Generador de radio de borde]] — obtiene los radios asimétricos que hacen que una forma parezca intencional.","[[text-shadow-generator|Generador de sombras de texto]] — útil con moderación. La mayoría de las sombras del texto son demasiado fuertes; esto le permite ajustar el desplazamiento y desenfocar hasta que desaparezca."]},{"p":"El truco para los cuatro es la moderación. Dos sombras, una oscura y estrecha y otra amplia y suave, se leen como elevación física. Una sombra parece un sitio web de hace quince años. Genere, copie y luego elimine hasta que no sepa que está allí."},{"h":"Los activos de producción que todos olvidan"},{"l":["[[favicon-generator|Favicon Generator]]: genera el conjunto de iconos pequeños que un sitio realmente necesita. Esto está en la lista porque los favicons son el activo con mayor probabilidad de faltar por completo, y uno que falta muestra un ícono de página de navegador genérico que hace que un sitio terminado parezca inacabado.","[[emoji-picker|Selector de emoji]]: navega, busca y copia emoji sin tener que buscar en el selector del sistema operativo. Realmente útil cuando escribes un texto que necesita un símbolo específico."]},{"h":"Un ejemplo práctico: enviar una sección de héroe"},{"p":"Aquí está todo el grupo haciendo un trabajo real. Una página necesita un héroe con una imagen de fondo, un título y un botón, y nada de eso se ha creado todavía."},{"l":["**1. Reserva el espacio.** Dale a la ranura de la imagen una altura fija en el diseño, para que la página tenga la forma correcta desde el primer renderizado en lugar de saltar cuando aparece la imagen real.","**2. Cambia el tamaño y comprime.** Cuando llegue la foto real, pásala por el [[image-resizer|Image Resizer]] a 1600 px de ancho, luego el [[image-compressor|Image Compressor]] al 75 por ciento. Ese es un archivo que puedes enviar.","**3. Comprueba el contraste del texto.** Un título sobre una foto es el clásico error de contraste. Utilice el [[contrast-checker|Contrast Checker]] para elegir una intensidad de superposición oscura o un color de texto claro que pase AA.","**4. Construya el botón.** El [[box-shadow-generator|Box Shadow Generator]] proporciona la elevación y el [[color-converter|Color Converter]] obtiene el color de la marca en el formato que necesita el CSS.","**5. Enviar.** Agrega un favicon del [[favicon-generator|Favicon Generator]] para que la pestaña no parezca abandonada y la sección esté lista."]},{"p":"Cinco herramientas, ningún paquete de diseño y cada resultado es un valor que puede pegar directamente en el código."},{"h":"Preguntas frecuentes"},{"p":"**¿Se cargan mis imágenes en algún lugar?** No. La compresión, el cambio de tamaño y la conversión Base64 se realizan en su navegador, razón por la cual no hay límite de tamaño de archivo ni cola de carga.\\n\\n**¿Comprimir una imagen perderá calidad?** Siempre, por definición. La pregunta es si es visible. Con una calidad del 70 al 80 por ciento y dimensiones correctas, normalmente no lo es.\\n\\n**¿Por qué mi imagen redimensionada todavía parece grande?** Nueve de cada diez veces la comprimiste antes de cambiar el tamaño, o la guardas como PNG cuando una foto es mejor como JPEG.\\n\\n**¿Puedo usarlos para el trabajo del cliente?** Sí, sin atribución ni restricción comercial.\\n\\n**¿Funcionan en un teléfono?** Sí, aunque cambiar el tamaño y comprimir fotos grandes en un teléfono depende de la memoria de su dispositivo y no de un servidor."},{"h":"La versión de una sola línea"},{"p":"Cambie el tamaño antes de comprimir, verifique el contraste antes de discutir sobre el color, mantenga las sombras sutiles y nunca olvide el favicon. De todos modos, eso es la mayor parte de lo que una suite de diseño estaba haciendo por usted."}]},"math-tools-for-real-numbers":{"title":"6 herramientas matemáticas gratuitas para números que no se comportan bien","description":"Notación científica, decimales a fracciones, verificación de números primos, factoriales y MCD/MCM: herramientas de navegación gratuitas para el trabajo con números en las que es fácil equivocarse.","category":"Herramientas matemáticas","blocks":[{"p":"Las matemáticas que realmente necesitas en una computadora no son las matemáticas que te examinaron. Es: ¿está este número en el formato que espera el sistema?, ¿está simplificada esta fracción?, ¿a qué velocidad crece? y ¿por qué la calculadora y la hoja de cálculo no están de acuerdo?\\n\\nEstas seis herramientas cubren ese territorio. Se ejecutan localmente, lo que para la aritmética significa un beneficio específico que vale la pena mencionar: el número que ingresas no se envía a ninguna parte, por lo que puedes verificar un cálculo que involucra un salario, un saldo o una cifra de cliente sin pensarlo dos veces."},{"h":"Obtener números en una forma que una máquina acepte"},{"p":"Las computadoras almacenan fracciones decimales como fracciones binarias. 0,1 no es exactamente representable en binario: el valor de doble precisión más cercano es 0,1000000000000000055511151231257827. Agregue 0,1 + 0,2 y obtendrá 0,30000000000000004, que se imprime como 0,3 de forma predeterminada y rompe silenciosamente una verificación de igualdad."},{"l":["[[scientific-notation|Convertidor de notación científica]]: pasa de la forma estándar a la científica, que es la forma en que la mayoría de los registros, hojas de cálculo y API almacenan números grandes y pequeños.","[[decimal-fraction|Decimal a fracción]] — convierte un decimal en una fracción exacta. Esta es la solución al problema anterior: 0,1 + 0,2 en aritmética de fracciones exactas es 3/10, no una aproximación."]},{"b":"Si alguna vez ha visto un total incorrecto en 0,0000000000000004, este es el motivo. En código financiero la respuesta estándar es trabajar en centavos enteros, o en una biblioteca decimal, y nunca en punto flotante. Si alguna vez ha visto una hoja de cálculo que no coincide con un guión por una fracción de centavo, es el mismo error con un sombrero diferente."},{"p":"Vale la pena dominar la notación científica, porque es la diferencia entre leer una línea de registro y entrecerrar los ojos. 6.022e23, 1.6e-19 y 3e8 son el número de Avogadro, la carga elemental y la velocidad de la luz. Si parecen ruido en lugar de números, convertir algunos a través de la herramienta lo soluciona permanentemente."},{"h":"Primos, y por qué a alguien le importa"},{"l":["[[prime-checker|Comprobador de números primos]] — prueba si un número es primo y observa su factorización cuando no lo es.","[[gcf-calculator|Calculadora MCD MCM]] — máximo común divisor y mínimo común múltiplo."]},{"p":"Los números primos no son un ejercicio escolar. La seguridad de cada conexión HTTPS que realice depende del hecho de que multiplicar dos números primos grandes es fácil y factorizar el resultado es difícil. Esa asimetría es la base entera de RSA.\\n\\nPara fines cotidianos, la verificación prima se trata principalmente de fracciones. Simplificar una fracción significa dividir la parte superior e inferior por su máximo común divisor, y no puedes encontrar eso sin factorizar. Es por eso que estas dos herramientas van juntas: verifique los factores y luego obtenga el MCD y el LCM en un solo paso."},{"p":"La mitad LCM es la que la gente olvida, y es la que soluciona los problemas de programación: dos eventos que se repiten cada 18 días y cada 12 días coinciden cada 36 días. Misma aritmética, diferente aplicación."},{"h":"Los factoriales y la velocidad a la que explotan"},{"l":["[[calculadora-factorial|Calculadora factorial]] — n! para valores donde la respuesta todavía es significativa."]},{"p":"Los factoriales crecen más rápido que casi cualquier cosa que encuentres en un escritorio. 10! es de unos 3,6 millones. 20! es aproximadamente 2,4 quintillones, mayor que el número de granos de arena de la Tierra por un amplio margen. ¡52!, el número de formas de barajar una baraja de cartas, es aproximadamente 8 seguido de 67 dígitos.\\n\\nLa consecuencia práctica es que un programa que enumera todas las permutaciones está bien en 5 elementos, tolerable en 8 y permanentemente bloqueado en 12. Si parece que una tarea nunca terminará y estás recorriendo permutaciones, es casi seguro que ese sea el motivo. También es el argumento en contra de la mayoría de los enfoques de fuerza bruta, expresado como aritmética más que como opinión."},{"h":"Números romanos y lo curioso de ellos"},{"l":["[[números romanos|Convertidor de números romanos]] — convierte hacia y desde números romanos."]},{"p":"Vale la pena entender los números romanos en lugar de simplemente convertirlos, porque el sistema revela algo sobre la notación posicional. No hay cero ni valor posicional: XI significa once, ya sea que represente once palos o once mil. Por eso la aritmética en números romanos es realmente difícil, y por eso el sistema sobrevivió durante siglos principalmente para contar y fechar, más que para calcular.\\n\\nLa regla sustractiva es la parte en la que la gente se equivoca. IV es cuatro, no VI; IX es nueve. Los relojes son una famosa excepción: el Big Ben usa IIII en lugar de IV, por razones sobre las que los historiadores aún discuten. Convertir en lugar de derivar es la decisión correcta en todos los casos."},{"h":"Un ejemplo resuelto: comprobar una fracción a mano"},{"p":"Una receta necesita 0,375 tazas y una báscula que lea en gramos, un informe cita una proporción de 0,625 y ambos parecen números que alguien escribió apresuradamente."},{"l":["**1. Encuentra la fracción exacta.** Ejecuta 0.375 a través de la herramienta [[decimal-fraction|Decimal a fracción]]: 3/8. Ejecute 0,625: 5/8. Tampoco hace falta un hábito de calculadora que no tienes.","**2. Simplifica la razón.** Para expresar 3/8 contra 5/8, necesitas el MCD de 3 y 5. La [[calculadora de mcd|Calculadora MCM del MCD]] da 1, por lo que la razón es 3:5 y ya es la más simple.","**3. Verifique la afirmación de los factoriales.** Si alguien le dice que una cola de 9 pedidos tiene 362,880 arreglos, la [[factorial-calculator|Calculadora factorial]] confirma 9. es exactamente eso. Ahora ya sabes si la estimación del tiempo de construcción era plausible.","**4. Normalice cualquier cosa grande.** Un servidor que informa 1,5e9 nanosegundos es 1,5 segundos, según el [[scientific-notation|Scientific Notation Converter]], que es la diferencia entre un problema de latencia y un artefacto de redondeo."]},{"h":"Lo que estas herramientas deliberadamente no hacen"},{"p":"No se muestran trabajando y no enseñan. Si necesita comprender por qué una fórmula es verdadera, una calculadora es el instrumento equivocado: da la respuesta sin la razón, que es la razón por la que las personas terminan siendo capaces de calcular e incapaces de razonar.\\n\\nTampoco hacen precisión arbitraria. Los factoriales y las factorizaciones grandes perderán precisión más allá del punto en que la respuesta siga siendo útil, y una pestaña del navegador no es un sistema de álgebra informática. Para cualquier cosa donde la corrección realmente importe (ingeniería, finanzas, criptografía), utilice una biblioteca adecuada con aritmética exacta, no una página web."},{"h":"Comprobando tu propia aritmética"},{"p":"El hábito matemático más valioso no es la velocidad, sino la estimación. Antes de creer en cualquier resultado, pregúntese si es el orden de magnitud correcto: mayor o menor que la entrada, y aproximadamente en qué medida. La mayoría de los errores aritméticos sobreviven a todas las demás comprobaciones excepto a ésta.\\n\\nRedondear primero hace que la estimación sea gratuita. Redondea 0,375 a 0,4, redondea 5/8 a 0,6 y la proporción es obviamente de aproximadamente 2:3, lo suficientemente cerca de 3:5 para confirmar la fracción que calculaste exactamente. Si la respuesta exacta y la estimación no coinciden, habrá encontrado un error de entrada en lugar de un problema de redondeo, y lo encontró en segundos.\\n\\nEsta es también la razón por la que una calculadora no sustituye a pensar en lo que le preguntaste. Una herramienta calculará perfectamente la cantidad incorrecta y la única defensa es saber cómo debería ser la respuesta."},{"h":"Preguntas frecuentes"},{"p":"**¿Mi entrada se envía a algún lugar?** No. Todos estos se ejecutan localmente en su navegador.\\n\\n**¿Por qué 0,1 más 0,2 no es igual a 0,3?** Porque ni 0,1 ni 0,2 son exactamente representables en coma flotante binaria. La suma es 0,30000000000000004, que es el doble más cercano a 0,3.\\n\\n**¿Qué tamaño de factorial pueden manejar?** Hasta 170 antes de exceder el rango de un doble. Más allá de eso, la respuesta se muestra en notación científica y luego deja de ser significativa.\\n\\n**¿Puedo usar la salida en código?** Sí. En particular, para los resultados de conversión de decimal a fracción, utilice la aritmética de números enteros en el numerador y el denominador en lugar de volver a convertir a decimal."},{"h":"La versión de una sola línea"},{"p":"Utilice fracciones exactas cuando se trate de dinero, recuerde que los factoriales explotan más rápido de lo esperado y que la factorización prima es a la vez una base de seguridad y un truco para simplificar fracciones."}]},"everyday-utility-tools":{"title":"13 utilidades diarias gratuitas: contraseñas, códigos QR, temporizadores y codificación de texto","description":"Genere contraseñas, cree códigos QR, ejecute temporizadores y relojes, y decodifique texto binario, hexadecimal y cifrado, todo con herramientas de navegador gratuitas que no cargan nada.","category":"Herramientas de utilidad","blocks":[{"p":"Este último grupo es el cajón de trastos. Contraseñas, códigos QR, un cronómetro, un reloj mundial, un lanzamiento de moneda y cuatro herramientas que convierten el texto en otras representaciones de sí mismo. Individualmente triviales, colectivamente lo que necesitas en momentos incómodos.\\n\\nLa línea directa es que los trece se ejecutan localmente. Para un generador de contraseñas, eso no es una sutileza: es la única razón por la que se puede confiar en la herramienta."},{"h":"Contraseñas: la parte que realmente importa"},{"l":["[[password-generator|Generador de contraseñas]] — genera contraseñas aleatorias seguras de cualquier longitud y conjunto de caracteres.","[[password-strength|Comprobador de seguridad de la contraseña]]: estima qué tan resistente es una contraseña a ser adivinada, localmente."]},{"b":"El hecho más importante sobre la seguridad de la contraseña: **la longitud supera a la complejidad, y la reutilización supera a ambas como peligro.** Una contraseña de 16 caracteres formada por palabras no relacionadas es más segura y mucho más fácil de escribir que un conjunto de símbolos de 10 caracteres. Mientras tanto, una contraseña reutilizada que aparece en una infracción elimina todas las cuentas que toca a la vez. Generar una contraseña larga y distinta por sitio es todo el trabajo."},{"p":"También importa cómo se estima la fuerza. La mayoría de los verificadores se aproximan al tamaño del espacio de búsqueda, lo cual es un indicador razonable pero no la verdad: `CorrectHorseBatteryStaple` obtiene buenos resultados en entropía, mientras que `P@ssw0rd1!` obtiene buenos resultados en variedad de caracteres y malos en la práctica porque aparece en todas las listas de palabras del mundo.\\n\\nUtilice el generador para cualquier cosa que le interese y, si tiene que recordar una contraseña, utilice una frase de contraseña de cuatro o cinco palabras no relacionadas. Ése es el caso específico en el que la memorabilidad y la fuerza en realidad se superponen."},{"h":"Códigos QR: que poner en ellos"},{"l":["[[qr-code-generator|Generador de códigos QR]] — genera un código QR para una URL, texto, detalles de Wi-Fi o información de contacto."]},{"p":"Los códigos QR son una de esas herramientas en las que la calidad del resultado está completamente determinada por una decisión: la cantidad de datos que ingresa. Una URL corta se codifica en un código pequeño y fácil de escanear. Un párrafo de texto con puntuación se codifica en algo denso y poco confiable en tamaños pequeños.\\n\\nDos reglas prácticas. En primer lugar, siempre escanee el código en el tamaño en el que realmente se imprimirá antes de imprimir doscientos. En segundo lugar, los códigos Wi-Fi y URL simples se comportan de manera diferente en diferentes teléfonos: si un código está dirigido a una audiencia mixta, prefiera una URL simple a una página de destino que luego enlace hacia adelante, porque funciona en todas partes y puede cambiar hacia dónde apunta."},{"h":"Hora: cronómetros, relojes y la trampa en las zonas horarias"},{"l":["[[cronómetro|Cronómetro en línea]] — un cronómetro simple, útil cuando tu teléfono está en la otra habitación.","[[pomodoro-timer|Pomodoro Timer]] — Bloques de concentración de 25 minutos con descansos, para personas que encuentran que esa estructura funciona.","[[world-clock|Reloj mundial]] — hora actual en varias ciudades a la vez."]},{"p":"El reloj mundial se gana su lugar por una razón específica: el horario de verano. La mitad de los errores de programación del mundo no son errores aritméticos; son un momento en el que dos ciudades estaban separadas por cuatro horas la semana pasada y cinco horas esta semana, y nadie comprobó.\\n\\nAntes de programar algo en una zona horaria, coloque ambas ciudades en el reloj mundial y observe: no calcule el desplazamiento desde la memoria. Esta es también la razón por la que las invitaciones a reuniones deben incluir una zona horaria en lugar de una hora simple."},{"p":"En el temporizador Pomodoro: la técnica funciona para un tipo específico de tarea: limitada, enfocada e ininterrumpida. No funciona para la depuración, donde el movimiento correcto cuando se está atascado es alejarse, no comenzar otro bloque de 25 minutos. Úselo cuando le ayude."},{"h":"Aleatoriedad, honestamente"},{"p":"El [[random-number|Generador de números aleatorios]] y el [[list-randomizer|List Randomizer]] cubren los casos que realmente surgen: elegir un número en un rango y poner una lista en un orden justo. Vale la pena una sentencia sobre la equidad. Ambos utilizan un generador pseudoaleatorio, que para decidir quién paga el almuerzo es indistinguible de una moneda real. Para cualquier cosa importante (un sorteo con premios, una asignación con dinero adjunto), desea una fuente que pueda auditar, y una pestaña del navegador no es eso. El valor aquí es eliminar al ser humano, que elige mal cuando está motivado."},{"h":"El cajón de la basura de codificación"},{"p":"Cuatro herramientas que mueven texto entre representaciones. Ninguno de ellos es cifrado, y vale la pena señalar la distinción porque constantemente se confunde: una codificación es reversible por cualquiera y no tiene clave. El cifrado requiere una clave."},{"l":["[[binary-text|Binario a texto]] — convierte entre texto y su representación binaria.","[[hex-text|Hex a Texto]] — convierte entre texto y hexadecimal, la representación que ves con más frecuencia en herramientas de red y depuradores.","[[caesar-cipher|Cifrado César]]: cambia las letras en una cantidad fija, el cifrado clásico del aula.","[[rot13-encoder|Codificador ROT13]] — rota las letras en 13, un caso especial que es su propio inverso."]},{"p":"Estos son útiles para exactamente dos cosas. Primero, comprender cómo el texto se convierte en bytes, que es el modelo mental que necesita cuando algo parece confuso. En segundo lugar, depurar realmente: cuando una carga útil aparece como hexadecimal, el convertidor [[hex-text|Hex to Text]] es la forma de descubrir lo que dice.\\n\\nNo sirven para ocultar nada. ROT13 no tiene clave (el cambio es público), por lo que no oculta nada a nadie que sepa qué es ROT13. El cifrado César tiene 25 cambios posibles, que un humano descifra en un minuto."},{"h":"Los dos que dan formato a las cosas."},{"l":["[[phone-formatter|Formateador de números de teléfono]]: normaliza los números de teléfono en un formato coherente.","[[file-size-converter|Convertidor de tamaño de archivo]] — convierte entre KB, MB, GB y TB, explicando la distinción decimal y binaria."]},{"p":"El conversor de tamaño de archivo tiene un resultado realmente valioso: le indica por qué una unidad anuncia un número mayor que el que informa su computadora. Los proveedores venden en potencias de diez, los sistemas operativos informan potencias de dos y la brecha es de alrededor del 7 por ciento en todas las escalas. Eso no es un defecto, son dos convenciones."},{"h":"Un ejemplo resuelto: la respuesta API confusa"},{"p":"Un webhook no supera la validación y la carga útil en el registro parece `\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f`. Este es un diagnóstico de noventa segundos."},{"l":["**1. Convertir.** Pegue `48656c6c6f` en el convertidor [[hex-text|Hex to Text]]; el resultado es `Hello`. Nunca fue confuso, sólo codificado.","**2. Verifique la forma.** Algo ascendente está codificando hexadecimalmente la carga útil antes de firmar. La firma se calculó sobre el texto original y se validó con el hexadecimal, por lo que la comparación falla.","**3. Descarta la otra dirección.** Si el registro hubiera mostrado texto legible, el problema habría sido el inverso: firmar el formulario codificado.","**4. Confirme la afirmación de tamaño.** Si el mismo registro informa una carga útil de 1,2 MB, el [[file-size-converter|Convertidor de tamaño de archivo]] determina si es decimal o binario antes de que alguien discuta sobre una cuota."]},{"h":"Preguntas frecuentes"},{"p":"**¿Es seguro el generador de contraseñas si todo se ejecuta en el navegador?** Sí, y más que uno basado en servidor: la contraseña se genera en su máquina y nunca se transmite, por lo que no hay nada que interceptar, registrar o violar. La desventaja es que no puede recuperar una contraseña que no guardó.\\n\\n**¿Puedo confiar en el lanzamiento de moneda virtual?** Para decisiones casuales, sí. Para cualquier cosa que tenga dinero o premios adjuntos, utilice una fuente que pueda auditar.\\n\\n**¿Son seguros los cifrados?** No. Ninguno de ellos. Los cifrados ROT13 y César no tienen clave secreta y existen para enseñar codificación, no para proteger nada.\\n\\n**¿Funcionan sin conexión?** Una vez que se ha cargado una página, sí, todo es local.\\n\\n**¿Existe un límite en la longitud del texto para los convertidores?** Solo la memoria de su dispositivo, ya que no se envía nada a ninguna parte."},{"h":"La versión de una sola línea"},{"p":"Las contraseñas largas y únicas superan a las cortas e inteligentes, un código QR es tan bueno como los datos que contiene, verifica las diferencias de zona horaria en lugar de calcularlas, y la codificación no es encriptación."}]}}')},31823,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"La boîte à outils du développeur : 24 outils de navigateur gratuits qui remplacent les applications payantes","description":"Un guide pratique pour formater, convertir, encoder et déboguer des données à l\'aide d\'outils de développement gratuits basés sur un navigateur : pas d\'installation, pas de compte, rien de téléchargé.","category":"Outils de développement","blocks":[{"p":"La plupart des petits travaux que vous effectuez cent fois par semaine (reformatage d\'une réponse API, décodage d\'un jeton, vérification d\'un hachage, indentation d\'un slug SQL) n\'ont pas besoin d\'un IDE, d\'un abonnement payant ou d\'une licence d\'équipe. Ils ont besoin d’un onglet ouvert pendant quatre-vingt-dix secondes.\\n\\nLa collection ci-dessous comprend vingt-quatre utilitaires basés sur un navigateur couvrant le formatage, la conversion, l\'encodage, le hachage et le débogage. Chacun d\'entre eux s\'exécute entièrement sur votre page : vos données ne sont jamais envoyées à un serveur, ce qui est plus important que les développeurs ne l\'admettent habituellement, car la charge utile que vous collez appartient généralement à un client."},{"h":"Quels outils basés sur un navigateur peuvent et ne peuvent pas remplacer"},{"p":"Soyez réaliste quant aux limites. Ces outils remplacent les tâches ponctuelles, à faibles enjeux et à haute fréquence. Ils ne remplacent pas votre serveur de langage, votre débogueur, votre suite de tests ou tout ce dont vous avez besoin pour exécuter de manière répétée dans un environnement réel."},{"l":["**Bon ajustement :** lire une réponse une fois, déboguer une seule valeur, convertir un fichier pour une importation, vérifier un format avant l\'expédition.","**Mauvais ajustement :** exécuter la même vérification à chaque déploiement, transformer des centaines de fichiers, tout ce qui doit échouer bruyamment dans CI.","**Jamais :** tout ce qui implique des informations d\'identification que vous ne pouvez pas alterner. Collez un jeton révoqué, pas un jeton actif."]},{"p":"Cela dit, la raison pour laquelle il faut les conserver dans vos favoris est le débit. Une tâche qui prend quarante secondes dans un onglet de navigateur n\'est jamais planifiée, n\'est jamais déléguée et ne devient jamais une raison pour ouvrir un IDE à huit heures du soir."},{"h":"Formatage et conversion de données"},{"p":"Le travail quotidien le plus courant consiste à rendre les données lisibles. Une API renvoie un blob sur une seule ligne, un collègue envoie un fichier de configuration avec des onglets mutilés par une fenêtre de discussion, ou vous avez exporté une feuille de calcul au format JSON et elle est revenue sous la forme d\'une énorme ligne."},{"l":["[[json-formatter|JSON Formatter]] — indente, valide et lit une charge utile. Utilisez-le avant de déboguer : la moitié de tous les tickets « l\'API est cassée » sont en fait du JSON mal formé avec une virgule finale.","[[json-validator|JSON Validator]] — lorsque vous avez besoin d\'une réponse stricte réussite/échec plutôt qu\'une jolie impression.","[[xml-formatter|XML Formatter]] — le même travail pour les réponses SOAP, les flux RSS et les POM Maven que personne n\'a touchés depuis 2014.","[[json-to-yaml|JSON to YAML]] et [[json-to-csv|JSON to CSV]] — déplacement des données entre les formats que les systèmes réels utilisent réellement."]},{"p":"Gardez le dernier groupe à l\'esprit pour un scénario spécifique : un client vous remet une feuille de calcul et l\'attend dans son API. Passer directement de CSV à JSON est un travail de deux minutes plutôt qu\'un après-midi de script."},{"h":"Encodage et échappement"},{"p":"Les bugs d’encodage sont disproportionnellement ennuyeux car les données semblent correctes. La valeur « San José & Sons » arrive sous la forme « San Jos%C3%A9 %26 Sons » et votre comparaison avec la base de données échoue pour des raisons invisibles dans les journaux."},{"l":["[[url-encoder|URL Encoder / Decoder]] — détermine immédiatement si une chaîne de requête est doublement codée.","[[base64-encoder|Base64 Encoder/Decoder]] — décode un fragment de certificat ou encode un petit actif à intégrer dans CSS.","[[html-entity-encoder|HTML Entity Encoder / Decoder]] — découvrez si ce \\"&\\" parasite dans votre page provient de votre modèle ou de vos données.","[[unicode-converter|Unicode Converter]] — utile lorsqu\'un caractère \\"cassé\\" s\'avère être un caractère légitime rendu avec un mauvais encodage.","[[number-base-converter|Number Base Converter]] — vérifie une couleur, un masque de bits d\'autorisation ou une adresse mémoire sans application de calculatrice."]},{"b":"Une habitude pratique : lorsqu\'une valeur arrive tronquée, décodez-la couche par couche et collez chaque résultat dans un champ vide. Si le premier décodage produit un texte lisible, le problème est un encodage supplémentaire quelque part en amont. S\'il produit du mojibake, vous avez un problème d\'encodage plutôt qu\'un problème d\'échappement, et ces deux-là nécessitent des correctifs différents."},{"h":"Identifiants, hachages et jetons"},{"p":"C\'est dans ce groupe que les développeurs perdent le plus de temps à rechercher le bon script local qu\'ils ont écrit une fois et qu\'ils ont perdu."},{"l":["[[uuid-generator|UUID Generator]] — génère des identifiants v4 pour les données de départ, les appareils ou une ligne de base de données rapide.","[[md5-generator|MD5 / SHA Hash Generator]] — vérifiez un téléchargement ou confirmez que deux fichiers qui devraient être identiques le sont réellement.","[[timestamp-converter|Timestamp Converter]] — l\'outil le plus utilisé de toute cette liste. Lorsqu\'une ligne de journal indique 1761000000, c\'est ce qui vous indique si l\'incident s\'est produit pendant le déploiement ou avant celui-ci."]},{"p":"Le convertisseur d’horodatage mérite sa place pour une raison spécifique : un numéro d’époque est à la fois sans ambiguïté et inutile. Vous savez exactement quand quelque chose s\'est produit et vous ne pouvez pas le dire à un collègue. Une conversion unique règle généralement un argument plus fort qu\'elle ne le devrait."},{"h":"Comparaison et débogage"},{"l":["[[regex-tester|Regex Tester]] — l\'élément le plus efficace ici. Une expression régulière qui semble correcte et qui ne correspond à rien est l\'un des bogues les plus coûteux en développement, car elle échoue silencieusement au seul endroit où personne ne la lit.","[[html-preview|HTML Preview]] — parcourez un fragment de balisage pour vérifier son rendu réel."]},{"p":"Testez vos expressions régulières par rapport à l\'entrée que vous attendez réellement, y compris la chaîne vide, un nom Unicode et une valeur avec une nouvelle ligne. La plupart des modèles se brisent au troisième cas et personne ne le remarque jusqu\'à ce que les données de production arrivent."},{"h":"Un exemple concret : trois outils, un incident ennuyeux"},{"p":"Voici la séquence qui m’a convaincu de mettre tout cela dans mes favoris. Un client a signalé qu\'un enregistrement qu\'il avait soumis mardi manquait dans un rapport de jeudi."},{"l":["**1. Convertissez l\'horodatage.** La tâche de rapport a enregistré l\'heure de création de l\'enregistrement en tant que valeur d\'époque. Le [[timestamp-converter|Timestamp Converter]] a montré que l\'enregistrement avait été créé à 23 heures locales, soit mardi - l\'hypothèse de fuseau horaire du travail était le problème, pas l\'enregistrement.","**2. Formatez la charge utile.** Le passage du JSON stocké via le [[json-formatter|JSON Formatter]] a révélé que l\'enregistrement avait été écrit avec un champ de date nul, car le client a appelé deux fois le même point de terminaison à 200 ms d\'intervalle et la deuxième écriture a gagné.","**3. Comparez les charges utiles.** Les deux enregistrements contenaient la même clé API et le même horodatage client, ce qui indiquait une nouvelle tentative plutôt que deux clients distincts."]},{"p":"Temps total écoulé : quatre minutes. La précédente tentative d\'enquête, qui cherchait la même cause fondamentale dans une plate-forme d\'exploitation forestière, avait duré un après-midi et avait abouti à une conclusion erronée."},{"h":"Confidentialité : pourquoi l\'exécution locale est la véritable fonctionnalité"},{"p":"Chaque outil de cette bibliothèque traite votre saisie dans votre propre navigateur. Rien n\'est téléchargé, ce qui signifie aucune question de rétention, aucun accord de processeur et aucune conversation inconfortable sur la charge utile de production que vous avez collée il y a trois minutes.\\n\\nC\'est la raison pour laquelle il est préférable de préférer ces outils à une « API Pastebin » hébergée ou à un service en ligne qui vous demande de vous inscrire. Cela signifie également qu’ils continuent de travailler sur un vol, dans un sous-sol ou lorsque le VPN de l’entreprise a décidé de bloquer un autre domaine."},{"p":"Une mise en garde mérite d\'être clairement formulée : une page compatible hors ligne n\'est privée que si la page elle-même correspond au code que vous pensez. Sur une machine partagée, utilisez une fenêtre privée et fermez-la lorsque vous avez terminé, surtout si vous avez décodé des jetons."},{"h":"Construire un flux de travail autour d\'eux"},{"p":"Les outils sont individuellement triviaux. La valeur a l\'habitude d\'en atteindre une immédiatement au lieu de \\"y accéder plus tard\\", car plus tard, c\'est lorsque vous écrivez un script jetable, ou ouvrez un IDE, ou décidez que cela ne vaut pas la peine d\'être vérifié du tout."},{"l":["Ajoutez la collection à vos favoris, et non les URL individuelles, et placez-la dans la barre d\'outils de votre navigateur.","Lorsque quelque chose ne va pas, vérifiez-le avant de formuler une théorie. Coûte quinze secondes ; tue des classes entières de conclusions erronées.","Lorsque vous avez vérifié deux fois la même chose, c’est le signal pour l’automatiser – mais n’automatisez pas sur suspicion.","Ne collez pas les secrets de production. Faites pivoter tout ce dont vous n\'êtes pas sûr."]},{"h":"Questions fréquemment posées"},{"p":"**Ces outils sont-ils gratuits ?** Oui, entièrement, sans compte ni limite d\'utilisation. Aucun niveau payant ne retient quoi que ce soit de base.\\n\\n**Fonctionnent-ils hors ligne ?** Une fois qu\'une page est chargée, oui, tout s\'exécute dans votre navigateur. Le rechargement nécessite une connexion.\\n\\n**Puis-je les utiliser à des fins commerciales ?** Oui. Le résultat vous appartient sans aucune exigence d’attribution.\\n\\n**Existe-t-il une API ?** Non, et c\'est délibéré : la valeur est l\'interface. Exportez le résultat et traitez-le comme vous le souhaitez.\\n\\n**Pourquoi ne pas simplement installer un outil CLI à la place ?** Installez-en un lorsque vous en avez besoin trois fois. Utilisez un onglet de navigateur pour les deux premiers."}]},"text-tools-for-writers":{"title":"17 outils de texte gratuits pour les écrivains, les étudiants et les spécialistes du marketing","description":"Nettoyez la copie, comptez les mots avec précision, formatez les listes et transformez les brouillons en quelque chose de publiable - avec des outils de navigation gratuits qui ne téléchargent jamais votre texte.","category":"Outils de texte","blocks":[{"p":"Écrire pour le travail implique une quantité surprenante de corvées mécaniques qui n\'ont rien à voir avec l\'écriture : supprimer les espaces parasites d\'un paragraphe collé, vérifier une limite de mots, dédupliquer une liste de noms, convertir quelque chose en un slug d\'URL.\\n\\nCes dix-sept outils sont destinés à cette partie du travail. Ils s\'exécutent tous localement dans le navigateur, ce qui n\'est pas un détail : le brouillon que vous collez est souvent inédit et la liste que vous triez contient souvent les données personnelles de quelqu\'un."},{"h":"Mesurer ce que vous avez écrit"},{"p":"Le nombre de mots semble résolu jusqu\'à ce qu\'un client demande exactement 800 mots et que votre éditeur en dise 820, ou qu\'un formulaire rejette votre texte à 1 995 caractères sans aucune explication sur l\'endroit où est passée la nouvelle ligne."},{"l":["[[word-counter|Word Counter]] — la mesure standard. Collez, lisez, ajustez.","[[letter-counter|Letter Counter]] — compte les caractères et la fréquence des lettres. Utile lorsque vous déboguez pourquoi un paragraphe ne semble pas correct : il s\'agit généralement d\'un motif de lettres répété, pas d\'un rêve."]},{"p":"Une note sur ce que signifie « un mot » : différents compteurs ne sont pas d\'accord sur la césure, les nombres et les URL. Si un nombre exact est important, utilisez le même compteur que celui utilisé par la personne qui vérifie votre travail et convenez-en à l\'avance. Il s’agit là d’une source véritablement courante de petits arguments inutiles."},{"h":"Nettoyer la copie que vous n\'avez pas écrite"},{"p":"La plupart du texte que vous recevez est légèrement endommagé : des espaces doubles provenant d\'un copier-coller, une tabulation parasite, des majuscules incohérentes provenant d\'une personne tapant à la hâte. Le réparer à la main est lent et sujet aux erreurs."},{"l":["[[text-trimmer|Text Trimmer]] — supprime les espaces de début et de fin de chaque ligne à la fois. Cela corrige plus de rapports « le formatage semble défectueux » que tout autre élément de cette liste.","[[text-case-converter|Text Case Converter]] — basculer entre la casse de la phrase, la casse du titre, les majuscules et les minuscules dans un bloc. C\'est également le moyen le plus rapide d\'annuler un paragraphe accidentel de CAPS LOCK.","[[text-to-slug|Text to Slug]] — transformez un titre en un slug d\'URL propre. Collez votre titre, récupérez le slug, c\'est fait."]},{"p":"Le générateur de slug a une utilité au-delà des URL : c\'est un moyen rapide de créer un nom de fichier ou une ancre lisible qu\'un humain peut analyser d\'un seul coup d\'œil, ce qui surpasse \\"final_final_v3\\"."},{"h":"Travailler avec des listes"},{"p":"Listes, inventaires, publipostages, nettoyages de balises, réponses à des enquêtes, colonnes de feuilles de calcul : à un moment donné, tout devient une liste et chaque liste doit être triée, dédoublonnée ou randomisée."},{"l":["[[duplicate-line-remover|Duplicate Line Remover]] — comparez deux listes ou nettoyez-en une. La sortie vous indique combien de doublons ont été supprimés, ce qui est utile lorsque vous rapportez le résultat.","[[list-sorter|List Sorter]] — le même travail pour la saisie de liste structurée.","[[list-randomizer|List Randomizer]] — mélangez un ordre de tirage au sort, une séquence de quiz ou une liste restreinte afin que personne ne soupçonne de favoritisme.","[[line-number-adder|Line Number Adder]] — numérote les lignes pour référence dans un ticket ou un commentaire de révision de code."]},{"b":"Le piège classique ici est une liste qui semble dédoublonnée mais qui ne l\'est pas : « Apple », « apple » et « Apple ». sont trois lignes différentes sur un ordinateur. Coupez les espaces et supprimez la ponctuation de fin avant de dédupliquer, sinon vous ne fusionnerez rien et conclurez que les données sont propres."},{"h":"Aperçu et formatage"},{"p":"Markdown a gagné, mais pas de manière uniforme. La moitié de vos outils le rendent, l\'autre moitié ne le fait pas, et la moitié qui ne le fait pas est généralement celle dans laquelle une personne senior doit la coller."},{"l":["[[markdown-preview|Markdown Preview]] — rendu en direct, afin que vous puissiez vérifier qu\'un tableau ou une liste imbriquée a réellement l\'air juste avant qu\'il n\'atteigne un client.","[[text-repeater|Text Repeater]] — répétez une chaîne N fois. Utile pour générer du remplissage, tester des données ou, occasionnellement, faire valoir un point dans un document."]},{"p":"L\'aperçu Markdown est l\'outil qui permet de gagner le plus de temps dans tout cet ensemble, car un tableau brisé dans un document rendu est beaucoup plus visible - et bien plus embarrassant - qu\'un tableau brisé dans un texte brut."},{"h":"Le reste, et quand les atteindre"},{"l":["[[random-string|Random String Generator]] — génère des noms occasionnels lisibles, des identifiants d\'espace réservé ou des codes courts. Mieux que d’inventer quelque chose à la main, car vous ne le réutiliserez pas accidentellement.","[[morse-code|Morse Code Translator]] — vraiment amusant, parfois utile pour un projet thématique ou un puzzle."]},{"p":"Ce sont des outils à faible fréquence, mais ils ne coûtent rien à conserver dans vos favoris et ils résolvent le problème spécifique de \\"J\'ai besoin d\'une valeur aléatoire en ce moment et je ne me fais pas confiance pour en inventer une\\"."},{"h":"Une passe de montage réaliste"},{"p":"Voici l\'ordre qui fonctionne lorsqu\'un brouillon arrive de quelqu\'un d\'autre et doit être publié sous votre nom."},{"l":["**1. Trim.** Exécutez d\'abord l\'intégralité du document via le [[text-trimmer|Text Trim]]. Les dommages causés par les espaces se cachent dans les paragraphes où vous ne les verrez jamais.","**2. Nettoyer la casse.** Utilisez le [[text-case-converter|Text Case Converter]] pour le titre uniquement. N’appliquez jamais la conversion de casse à un brouillon complet – cela détruit les noms propres.","**3. Mesurez.** Vérifiez la longueur avec le [[compteur de mots|Compteur de mots]] avant d\'écrire, afin de savoir quelle forme la pièce est censée avoir.","**4. Aperçu.** S\'il contient du Markdown, rendez-le avec le [[markdown-preview|Markdown Preview]].","**5. Slug.** Générez le slug d\'URL en dernier, à partir du titre final, avec [[text-to-slug|Text to Slug]] — changer le titre ensuite brise le slug."]},{"p":"L\'ensemble du processus prend quelques minutes et élimine la catégorie d\'erreur dans laquelle un document est techniquement correct et visiblement erroné."},{"h":"Questions des écrivains sur la vie privée"},{"p":"**Mon texte non publié quitte-t-il mon ordinateur ?** Non. Ces outils traitent le texte dans votre navigateur et rien n\'est stocké ou transmis.\\n\\n**Y a-t-il une limite de longueur ?** Il n\'y a pas de limite côté serveur car il n\'y a pas d\'appel serveur. Les entrées extrêmement volumineuses sont limitées par la mémoire de votre propre appareil.\\n\\n**Puis-je utiliser le résultat à des fins commerciales ?** Oui, librement, sans attribution.\\n\\n**Est-ce qu\'ils fonctionnent sur un téléphone ?** Oui. La mise en page s\'adapte et le même code s\'exécute."},{"h":"Ce que ces outils ne feront pas pour vous"},{"p":"Cela vaut la peine d\'être franc sur les limites, car un outil qui mécanise la mauvaise chose ne fait que produire une erreur plus rapide.\\n\\nAucun de ces utilitaires ne peut vous dire si une phrase est claire, si une affirmation est fondée ou si un ton convient au public. Ils comptent les caractères ; ils ne jugent pas la prose. Un texte qui obtient de superbes résultats sur chaque métrique de cette page peut toujours être illisible.\\n\\nIls ne modifient pas non plus. Au moment où vous vous retrouvez à réécrire des clauses individuelles à la main à grande échelle, vous êtes devenu trop grand pour un outil de texte et vous voulez soit un éditeur approprié, un outil de recherche et de remplacement avec regex - que le [[regex-tester|Regex Tester]] est vraiment bon pour répéter - ou un script. Utilisez le navigateur pour la couche mécanique et gardez votre propre jugement pour tout ce qui se trouve au-dessus."},{"p":"Une autre chose qu’ils ne feront pas est de réparer une mauvaise source. Si votre feuille de calcul est remplie de noms incohérents : \\"Dr\\", \\"DR\\", \\"Dr\\". le tout dans une seule colonne — un outil triera et dédupliquera fidèlement ce que vous lui avez donné, et vous aurez toujours trois entrées là où il devrait y en avoir une. Le nettoyage des données est une décision et non une étape mécanique. Décidez d’abord de la forme canonique, puis appliquez-la, puis vérifiez."},{"h":"Garder une liste de travail utilisable"},{"p":"Si vous maintenez une liste de pistes, de liens, de références ou de termes, elle se dégrade tranquillement. Le mode d\'échec est toujours le même : les entrées qui semblent identiques ne le sont pas et une seule fusion ne supprime rien.\\n\\nUne passe de maintenance qui fonctionne est ennuyeuse : coupez les espaces, normalisez les majuscules, supprimez la ponctuation de fin, puis dupliquez. Dans cet ordre, le découpage après la déduplication fait perdre des entrées. Faire cela une fois par mois sur une liste active transforme un gâchis irrécupérable de deux heures en une corvée de dix minutes.\\n\\nLorsque deux listes doivent être rapprochées (par exemple, une liste d\'inscription avec une liste de présence), triez d\'abord les deux avec le [[list-sorter|List Sorter]], afin qu\'elles s\'alignent, puis comparez à l\'œil nu. Trier les deux côtés avant de comparer fait la différence entre un contrôle de deux minutes et une chasse de vingt minutes."},{"h":"Les plats à emporter"},{"p":"Aucun de ces outils n’est intelligent. C’est là le point : ils suppriment les cinq pour cent mécaniques de l’écriture qui n’est pas de l’écriture, donc les quatre-vingt-quinze pour cent restants concernent en réalité des phrases. Ajoutez ceux que vous utilisez mensuellement à vos favoris, ignorez le reste et arrêtez de corriger les espaces à la main."}]},"calculators-and-converters-guide":{"title":"18 calculatrices et convertisseurs gratuits pour les nombres que vous traitez réellement","description":"Pourcentages, remises, pourboires, prêts, dates, IMC et conversions d\'unités — des calculateurs de navigateur gratuits qui affichent leur raisonnement et n\'enregistrent jamais vos saisies.","category":"Calculatrices","blocks":[{"p":"Tout le monde doit diviser une facture, déterminer si une remise est réellement une remise et convertir une température ou une taille de fichier sans y penser. Tout le monde aussi, au moins une fois, se trompe en public.\\n\\nIl s\'agit d\'une collection de dix-huit calculatrices et convertisseurs couvrant l\'argent, les dates, la santé et les conversions d\'unités qui apparaissent dans le travail et les voyages. Tous s\'exécutent dans le navigateur : rien n\'est enregistré, donc les chiffres que vous tapez ne regardent personne d\'autre que vous."},{"h":"Calculs d\'argent"},{"p":"Les mathématiques du monde réel les plus courantes sont un pourcentage de quelque chose. Taxe de vente, un pourboire, une pile de remises, une commission, un taux de croissance. La formule est simple, et pourtant la raison pour laquelle les gens se trompent est presque toujours la même : ils appliquent un pourcentage à la mauvaise base."},{"l":["[[discount-calculator|Discount Calculator]] — calculez le prix final et, plus important encore, combien vous avez économisé. Utile pour repérer un « 50 % de réduction » qui correspond en réalité à 20 % après un prix catalogue augmenté.","[[tip-calculator|Tip Calculator]] - divisez une facture, choisissez un pourcentage, arrondissez par personne si vous le souhaitez.","[[loan-calculator|Loan Calculator]] — paiement mensuel et intérêts totaux, qui sont le nombre qui décide réellement si un prêt est abordable."]},{"b":"Sur les remises : une remise de 20 % suivie d\'une autre remise de 20 % n\'est pas une réduction de 40 %, mais bien une réduction de 36 %. Pourcentages séquentiels composés sur la base réduite. N\'importe quelle calculatrice de cette liste le confirmera en deux secondes environ, et c\'est le fait arithmétique le plus utile de cet article."},{"p":"Le calculateur de prêt mérite une note spécifique. Le chiffre qui compte n’est pas le paiement mensuel, mais le total des intérêts payés sur la durée du prêt, car c’est le coût réel de l’emprunt. Deux prêts avec des mensualités identiques et des conditions différentes peuvent différer de plusieurs dizaines de milliers en termes d\'intérêt total."},{"h":"Dates et comptes à rebours"},{"p":"C\'est dans l\'arithmétique des dates que la plupart des gens se trompent silencieusement, car les mois humains ont des durées différentes et la réponse change selon que vous parlez de « mois civils » ou de « 30 jours »."},{"l":["[[date-difference|Date Difference Calculator]] — jours (et total des mois, années) entre deux dates.","[[days-until|Days Until Calculator]] — un compte à rebours jusqu\'à une date spécifique, le nombre de jours ouvrables étant généralement ce que les gens souhaitent réellement.","[[age-calculator|Age Calculator]] — âge exact en années et en jours, plus le prochain anniversaire.","[[timestamp-converter|Timestamp Converter]] — un horodatage Unix en une date réelle, ce qui est important si vous touchez aux journaux, aux bases de données ou aux réponses API."]},{"p":"La distinction qui fait trébucher les gens : le nombre de jours entre le 1er mars et le 1er avril est de 31, mais le nombre de *mois* est d\'un. Si vous calculez un délai de préavis ou une durée d\'abonnement, indiquez par écrit de quelle part vous parlez."},{"h":"Honnêtement, les chiffres de la santé"},{"l":["[[bmi-calculator|BMI Calculator]] — indice de masse corporelle avec les catégories standard et les mises en garde ci-dessous."]},{"p":"L\'IMC est une statistique de dépistage à l\'échelle de la population. Cela ne dit rien sur la masse musculaire, la composition corporelle ou la santé d\'un individu, et c\'est un mauvais indicateur de la condition physique des athlètes, des personnes âgées et des différents groupes ethniques. Utilisez-le comme un point de données parmi plusieurs, ou comme moyen de suivre un changement au fil du temps, et non comme un verdict. Si vous prenez des décisions qui affectent votre santé, le bon outil est un clinicien et non un onglet de navigateur."},{"h":"Conversion d\'unités : celles du quotidien"},{"p":"La conversion d\'unités est divisée en deux types : les conversions que vous devez obtenir exactement et les conversions dont vous avez besoin approximativement. Ces outils gèrent les deux, et le travail consiste à se rappeler lequel est lequel."},{"l":["[[convertisseur de longueur|Convertisseur de longueur]] — système métrique vers impérial et inversement : millimètres, centimètres, mètres, kilomètres, pouces, pieds, yards, miles.","[[convertisseur de poids|Convertisseur de poids]] — grammes, kilogrammes, onces, livres, tonnes. Celui à vérifier avant une recette ou une étiquette d’expédition.","[[convertisseur de température|Convertisseur de température]] — Celsius, Fahrenheit, Kelvin. Parce que -10°C n\'est pas 14°F et que la formule n\'est pas une multiplication.","[[convertisseur de vitesse|Convertisseur de vitesse]] — km/h, mph, m/s, nœuds. Utile pour une limite de vitesse étrangère ou une spécification technique.","[[area-converter|Area Converter]] — mètres carrés, pieds carrés, acres, hectares. C’est celui que les gens estiment mal lorsqu’ils achètent ou louent un bien immobilier.","[[convertisseur de volume|Convertisseur de volume]] — litres, millilitres, gallons, tasses, mètres cubes.","[[time-converter|Time Converter]] — secondes, minutes, heures, jours, semaines."]},{"b":"Two conversion traps worth knowing: the data-storage one above (marketers sell 10^3, operating systems report 2^10), and fuel economy — a car quoted at 40 mpg (imperial) is closer to 33 mpg (US) than 40, because the imperial gallon is larger. Se tromper sur la seconde donne à une voiture de location une apparence irréaliste et efficace."},{"h":"Les deux dont vous n\'aurez pas besoin"},{"l":["[[random-number|Random Number Generator]] — tire dans une plage, pour un tirage au sort, un parenthèse ou un partage A/B rapide. Utile précisément parce que cela élimine les soupçons selon lesquels vous l’avez truqué.","[[dice-roller|Dice Roller]] — n\'importe quel dé, du tirage au sort au dé à vingt faces, pour un jeu de société ou une session sur table où le vrai dé est sorti de la table pour la dernière fois."]},{"h":"Utiliser correctement une calculatrice"},{"p":"Une calculatrice n’est utile que si vous savez sur quel numéro vous lui posez la question. Trois habitudes font la différence."},{"l":["**Arrondissez d\'abord, calculez ensuite.** Si le nombre précis ne change pas votre décision, utilisez un tour. Les pourcentages de nombres ronds sont vérifiables dans votre tête, ce qui détecte les erreurs de saisie.","**Vérifiez l\'ampleur.** Avant de croire un résultat, demandez s\'il doit être plus grand ou plus petit que l\'entrée, et de combien environ. La plupart des erreurs arithmétiques survivent à tous les contrôles, sauf celui-ci.","**Photographiez les entrées, pas la sortie.** Lorsque vous relancerez le calcul plus tard, ce qui compte est de savoir ce que vous avez supposé, pas ce que vous avez conclu."]},{"h":"Questions que les gens posent réellement"},{"p":"**Mes numéros sont-ils stockés quelque part ?** Non. Les calculs s\'effectuent dans votre navigateur et rien n\'est transmis ou conservé.\\n\\n**Est-ce que cela fonctionne sur un téléphone ?** Oui, et les calculatrices sont conçues pour une utilisation à une main.\\n\\n**Quelle norme de conversion utilisez-vous pour le stockage des données ?** Décimal (1 Ko = 1 000 octets) par défaut, car c\'est ainsi que le stockage est vendu. Les systèmes d\'exploitation signalent le binaire, c\'est pourquoi un disque semble rétrécir - l\'outil explique la différence plutôt que de choisir silencieusement un côté.\\n\\n**Puis-je les intégrer sur mon propre site ?** Non. Ajoutez-les plutôt à vos favoris ; le coût est nul et le problème de précision vous appartient."},{"h":"Pourcentages : les quatre erreurs qui comptent"},{"p":"Presque chaque pourcentage d’erreur qu’une personne commet dans la vie quotidienne est l’une des quatre mêmes erreurs. Les nommer les rend évitables."},{"l":["**Mauvaise base.** « Une hausse de 10 % puis une baisse de 10 % vous ramènent là où vous avez commencé » est faux, car les deux s\'appliquent à des bases différentes. Dix pour cent de 100 font 10 ; dix pour cent de 90 font 9.","**Pourcentage d\'un pourcentage.** Le cumul de deux remises les multiplie (0,8 × 0,8 = 0,64, donc 36 % de réduction), mais ne les additionne pas.","**Pourcentage contre points de pourcentage.** Un taux passant de 4 % à 6 % a augmenté de 2 points de pourcentage, mais de 50 % en termes relatifs. La politique et la médecine sont pleines de cette confusion, et ce n’est pas toujours accidentel.","**Arrondir trop tôt.** Arrondir une étape intermédiaire avant d\'appliquer un pourcentage aggrave l\'erreur. Gardez une précision totale jusqu\'au chiffre final, et effectuez la dernière étape sur une calculatrice plutôt que dans votre tête."]},{"p":"Si vous ne prenez qu\'une seule habitude de toute cette section, prenez celle-ci : avant de citer un pourcentage à qui que ce soit, reformulez de quoi il s\'agit *de*. La moitié des arguments que vous aurez à propos d’un nombre sont en réalité des arguments sur le dénominateur."},{"h":"Savoir quand arrêter de calculer"},{"p":"Il y a un point où la précision cesse d’être utile. Un paiement mensuel à deux décimales est significatif. A projected total cost to eight decimal places is a way of avoiding the actual decision, which is whether the loan fits inside what you can afford without stress.\\n\\nLe test utile est la question de sensibilité : la décision change-t-elle si cette entrée évolue de 10 % ? If not, stop refining it and use the extra time on the variable that does move the answer — usually the term rather than the rate, or the list price rather than the discount."},{"p":"Et une limite mérite d’être clairement indiquée : ces calculatrices sont de l’arithmétique, pas des conseils. Un objectif d’épargne, une date de retraite et un plan de remboursement de la dette sont autant de décisions concernant le risque, le comportement et le temps, et un onglet de navigateur ne peut peser sur aucun de ces éléments. Il ne peut vous dire ce que les chiffres impliquent qu’une fois que vous avez décidé de vos hypothèses. Cette distinction est la différence entre une calculatrice utile et responsable."},{"h":"La version en une ligne"},{"p":"Ajoutez correctement les calculateurs d\'argent et de date à vos favoris, traitez l\'IMC comme un signal plutôt que comme un verdict, rappelez-vous que les pourcentages empilés se multiplient et vérifiez une conversion d\'unité chaque fois qu\'un nombre entre dans quelque chose de contractuel. Cela couvre presque tout."}]},"image-and-design-tools":{"title":"14 outils d\'image et de conception gratuits qui s\'exécutent dans votre navigateur","description":"Compressez, redimensionnez et préparez des images, et générez des effets CSS, des palettes, des contrôles de contraste et des favicons sans installer Photoshop ou une suite de conception.","category":"Outils de conception","blocks":[{"p":"Le travail de l’image pose un problème spécifique : le travail est généralement petit et les outils proposés sont énormes. Vous devez supprimer 400 Ko d\'une image de héros, ou obtenir une valeur hexadécimale mentionnée par votre concepteur, ou générer un favicon que personne n\'a encore créé. Cela ne nécessite pas d\'abonnement.\\n\\nLes quatorze outils ci-dessous couvrent la préparation des images, le travail avec la couleur, la génération d\'effets CSS et les petits actifs de production qui passent entre les mailles du filet. Chacun fonctionne localement, ce qui compte plus pour les images que pour le texte : la photo que vous venez de compresser est souvent une photo que vous n\'avez pas encore publiée."},{"h":"Préparer des images pour le Web"},{"p":"La plupart des problèmes d’image sont en réalité des problèmes de poids. Une page qui semble lente contient généralement des images plus grandes que leur taille d\'affichage, dans le mauvais format, avec un paramètre de qualité que personne n\'a jamais remis en question."},{"l":["[[image-compressor|Image Compressor]] — réduisez la taille du fichier tout en gardant l\'image visuellement intacte. Exécutez-le avant de télécharger quoi que ce soit dans un formulaire avec une limite de taille.","[[image-resizer|Image Resizer]] — définissez les dimensions réelles en pixels dont vous avez besoin. C’est la plus grande victoire : une image de 4 000 px affichée à 800 px contient cinq fois les données dont elle a besoin.","[[image-to-base64|Image to Base64]] — convertissez une petite image en URI de données pour l\'intégrer dans CSS, HTML ou un modèle d\'e-mail."]},{"b":"L’ordre compte. Redimensionnez d\'abord, compressez ensuite. La compression d\'une image de 4 000 px produit un fichier beaucoup plus lourd que le redimensionnement à 800 px puis la compression avec la même qualité, car les compresseurs consacrent leurs efforts à des pixels qui allaient de toute façon être jetés."},{"p":"Combien faut-il compresser ? La réponse honnête est la suivante : jusqu’à ce que cela semble faux, reculez d’un pas. Pour une image de héros photographique, une qualité de 70 à 80 pour cent est généralement impossible à distinguer de l\'original à une taille de visualisation normale. Pour un logo, une capture d\'écran ou tout autre objet avec des couleurs plates et des bords nets, utilisez PNG et compressez plus fort : ils gagnent plus et perdent moins."},{"p":"Une règle empirique pratique : tout ce qui est inférieur à 200 Ko convient pour une image de héros, moins de 80 Ko pour une vignette, et si vous ne pouvez pas descendre en dessous de 300 Ko, vous avez probablement un problème de dimension plutôt qu\'un problème de qualité."},{"h":"Base64 : quand l\'inline est la bonne solution"},{"p":"La conversion d\'une image en URI de données Base64 supprime une requête HTTP, ce qui ressemble à une pure victoire. Ce n’est généralement pas le cas. La chaîne codée est environ un tiers plus grande que le fichier binaire, elle ne peut pas être mise en cache séparément et elle gonfle votre CSS ou HTML.\\n\\nEn ligne uniquement lorsque l\'image est petite (moins de quelques kilo-octets) et est utilisée une seule fois et est critique. Une petite icône dans un seul modèle d’e-mail est le cas classique. Pour tout ce qui se répète sur plusieurs pages ou dépasse quelques kilo-octets, servez-le comme fichier et laissez le navigateur le mettre en cache."},{"h":"Filigranes : ce qui est honnêtement amovible"},{"l":[]},{"p":"Soyez clair sur ce que cela fait. Il supprime ou obscurcit la marque visible. Il ne peut pas reconstruire les pixels sous-jacents : les informations qui ont été peintes ont disparu et aucun filtre ne les réinvente. Les résultats vont d\'invisible, lorsque la marque se trouve sur un fond uni, à une tache évidente lorsqu\'elle se trouve sur des détails.\\n\\nUne dernière chose qui mérite d\'être dite clairement : supprimer le filigrane de quelqu\'un d\'autre et publier le résultat est un problème de droit d\'auteur dans la plupart des juridictions et une violation de licence, que vous soyez ou non pris. Supprimer les marques de vos propres images ou du stock sous licence pour lequel vous disposez est le cas pour lequel cet outil est destiné."},{"h":"Couleur : convertir, vérifier, choisir"},{"p":"La couleur est l’endroit où les petites erreurs deviennent très visibles. Un rapport de contraste qui manque d\'accessibilité, une valeur hexadécimale qui est en fait un triple HSL, une palette qui semble cohérente sur votre moniteur et trouble sur un projecteur."},{"l":["[[color-converter|Color Converter]] — déplacez-vous entre HEX, RVB et HSL. HSL vaut la peine d\'apprendre à lire, car la teinte 210, la saturation 40 pour cent, la luminosité 50 pour cent sont beaucoup plus faciles à ajuster à la main qu\'une valeur hexadécimale.","[[contrast-checker|Contrast Checker]] — teste le texte sur son arrière-plan par rapport aux seuils WCAG. Il s’agit de l’outil le plus utile de cet article, car il détecte un véritable problème de conformité plutôt qu’un problème de goût.","[[color-palette|Color Palette Generator]] — générez un ensemble cohérent lorsque vous partez d\'une couleur de marque et que vous avez besoin du reste de l\'échelle."]},{"b":"En revanche : les WCAG AA demandent 4,5 contre 1 pour le corps du texte normal et 3 contre 1 pour le texte volumineux. Si vous choisissez entre deux couleurs de marque pour un bouton, celle qui est accessible n\'est généralement pas celle que le concepteur aime. Vérifiez d\'abord, puis discutez avec les données."},{"p":"Une mise en garde concernant les outils couleur : ils supposent tous que votre moniteur est calibré et que la personne qui consulte votre page a des yeux fonctionnels. Aucune des deux hypothèses n’est sûre. C’est une raison pour préférer les combinaisons contrastées aux combinaisons subjectives."},{"h":"Effets CSS sans ouvrir un outil de conception"},{"p":"Écrire à la main un dégradé ou une ombre superposée est une tâche véritablement désagréable. La syntaxe est délicate, vous ne pouvez pas voir ce que vous produisez et la différence entre une bonne et une mauvaise ombre réside dans quelques pixels de flou."},{"l":["[[gradient-generator|CSS Gradient Generator]] — créez des dégradés linéaires et radiaux et copiez directement le CSS.","[[box-shadow-generator|Box Shadow Generator]] — superposez plusieurs ombres, ce qui sépare une élévation subtile d\'une forte chute.","[[border-radius-generator|Border Radius Generator]] — obtient les rayons asymétriques qui donnent à une forme un aspect intentionnel.","[[text-shadow-generator|Text Shadow Generator]] — utile avec parcimonie. La plupart des ombres de texte sont trop fortes ; cela vous permet d\'ajuster le décalage et le flou jusqu\'à ce qu\'il disparaisse."]},{"p":"L’astuce pour tous les quatre est la retenue. Deux ombres – une sombre et étroite et une large et douce – se lisent comme une élévation physique. Une ombre se lit comme un site Web datant d’il y a quinze ans. Générez, copiez, puis supprimez jusqu\'à ce que vous ne puissiez pas savoir qu\'il est là."},{"h":"Les moyens de production que tout le monde oublie"},{"l":["[[favicon-generator|Favicon Generator]] — produit le petit jeu d\'icônes dont un site a réellement besoin. Ceci est sur la liste car les favicons sont l\'actif le plus susceptible de manquer complètement, et un élément manquant affiche une icône de page de navigateur générique qui donne l\'impression qu\'un site terminé est inachevé.","[[emoji-picker|Emoji Picker]] — parcourez, recherchez et copiez des emoji sans passer par un sélecteur de système d\'exploitation. Vraiment utile lorsque vous rédigez une copie nécessitant un symbole spécifique."]},{"h":"Un exemple concret : expédier une section de héros"},{"p":"Voici l\'ensemble du cluster effectuant un vrai travail. Une page a besoin d\'un héros avec une image d\'arrière-plan, un en-tête et un bouton, et rien n\'a encore été construit."},{"l":["**1. Réservez l\'espace.** Donnez à l\'emplacement de l\'image une hauteur fixe dans la mise en page, afin que la page ait la bonne forme dès le premier rendu au lieu de sauter lorsque l\'image réelle atterrit.","**2. Redimensionnez et compressez.** Lorsque la vraie photo arrive, exécutez-la via le [[image-resizer|Image Resizer]] à 1 600 px de large, puis le [[image-compressor|Image Compressor]] à 75 %. C\'est un fichier que vous pouvez envoyer.","**3. Vérifiez le contraste du texte.** Un en-tête sur une photo est l\'échec classique du contraste. Utilisez le [[contrast-checker|Contrast Checker]] pour choisir soit une force de superposition sombre, soit une couleur de texte claire qui passe AA.","**4. Construisez le bouton.** Le [[box-shadow-generator|Box Shadow Generator]] donne l\'élévation, et le [[color-converter|Color Converter]] obtient la couleur de la marque dans le format dont le CSS a besoin.","**5. Ship.** Ajoutez une favicon à partir du [[favicon-generator|Favicon Generator]] pour que l\'onglet ne semble pas abandonné et que la section soit terminée."]},{"p":"Cinq outils, pas de suite de conception et chaque sortie est une valeur que vous pouvez coller directement dans le code."},{"h":"Questions fréquemment posées"},{"p":"**Mes images sont-elles téléchargées n\'importe où ?** Non. La compression, le redimensionnement et la conversion Base64 se produisent tous dans votre navigateur, c\'est la raison pour laquelle il n\'y a pas de limite de taille de fichier ni de file d\'attente de téléchargement.\\n\\n**La compression d\'une image va-t-elle perdre en qualité ?** Toujours, par définition. La question est de savoir si cela est visible. Avec une qualité de 70 à 80 pour cent et des dimensions correctes, ce n\'est généralement pas le cas.\\n\\n**Pourquoi mon image redimensionnée semble-t-elle toujours grande ?** Neuf fois sur dix, vous la compressez avant de la redimensionner, ou vous l\'enregistrez au format PNG alors qu\'une photo est meilleure au format JPEG.\\n\\n**Puis-je les utiliser pour le travail d\'un client ?** Oui, sans attribution ni restriction commerciale.\\n\\n**Fonctionnent-ils sur un téléphone ?** Oui, bien que le redimensionnement et la compression de grandes photos sur un téléphone dépendent de la mémoire de votre appareil plutôt que d\'un serveur."},{"h":"La version en une ligne"},{"p":"Redimensionnez avant de compresser, vérifiez le contraste avant de discuter de couleur, gardez les ombres subtiles et n\'oubliez jamais le favicon. De toute façon, c’est l’essentiel de ce qu’une suite de design faisait pour vous."}]},"math-tools-for-real-numbers":{"title":"6 outils mathématiques gratuits pour les nombres qui ne se comporteront pas","description":"Notation scientifique, décimales en fractions, vérification des nombres premiers, factorielles et GCF/LCM — des outils de navigation gratuits pour le travail sur les nombres dans lequel il est facile de se tromper.","category":"Outils mathématiques","blocks":[{"p":"Les mathématiques dont vous avez réellement besoin sur un ordinateur ne sont pas celles sur lesquelles vous avez été examiné. La question est la suivante : ce nombre est-il dans le format attendu par le système, cette fraction est-elle simplifiée, à quelle vitesse augmente-t-elle et pourquoi la calculatrice et la feuille de calcul sont-elles en désaccord.\\n\\nCes six outils couvrent ce territoire. Ils fonctionnent localement, ce qui, du point de vue arithmétique, signifie un avantage spécifique qui mérite d\'être mentionné : le numéro que vous avez tapé n\'est envoyé nulle part, vous pouvez donc vérifier un calcul impliquant un salaire, un solde ou le chiffre d\'un client sans hésiter."},{"h":"Mettre des nombres sous une forme acceptée par une machine"},{"p":"Les ordinateurs stockent les fractions décimales sous forme de fractions binaires. 0,1 n\'est pas exactement représentable en binaire — la valeur double précision la plus proche est 0,1000000000000000055511151231257827. Ajoutez 0,1 + 0,2 et vous obtenez 0,30000000000000004, qui s\'imprime sous la forme 0,3 par défaut et interrompt discrètement un contrôle d\'égalité."},{"l":["[[scientific-notation|Scientific Notation Converter]] — passez de la forme standard à la forme scientifique, c\'est ainsi que la plupart des journaux, feuilles de calcul et API stockent réellement des nombres grands et petits.","[[decimal-fraction|Decimal to Fraction]] — convertit une décimale en fraction exacte. C\'est la solution au problème ci-dessus : 0,1 + 0,2 en arithmétique de fraction exacte est 3/10, pas une approximation."]},{"b":"Si vous avez déjà vu un total erroné de 0,0000000000000004, voici pourquoi. Dans le code financier, la réponse standard est de travailler en cents entiers ou dans une bibliothèque décimale, et jamais en virgule flottante. Si vous avez déjà vu une feuille de calcul en désaccord avec un script d\'une fraction de centime, il s\'agit du même bug portant un chapeau différent."},{"p":"La notation scientifique vaut la peine d\'être maîtrisée, car c\'est la différence entre lire une ligne de journal et plisser les yeux. 6.022e23, 1.6e-19 et 3e8 sont le nombre d\'Avogadro, la charge élémentaire et la vitesse de la lumière. Si ceux-ci ressemblent à du bruit plutôt qu\'à des chiffres, la conversion de quelques-uns via l\'outil le corrige de manière permanente."},{"h":"Primes, et pourquoi tout le monde s\'en soucie"},{"l":["[[prime-checker|Prime Number Checker]] — teste si un nombre est premier et voit sa factorisation lorsqu\'il ne l\'est pas.","[[gcf-calculator|GCF LCM Calculator]] — le plus grand facteur commun et le plus petit commun multiple."]},{"p":"Les nombres premiers ne sont pas un exercice scolaire. La sécurité de chaque connexion HTTPS que vous établissez dépend du fait qu\'il est facile de multiplier deux grands nombres premiers et qu\'il est difficile de prendre en compte le résultat. Cette asymétrie est la base même du RSA.\\n\\nAu quotidien, la vérification des nombres premiers concerne principalement les fractions. Simplifier une fraction signifie diviser le haut et le bas par leur plus grand facteur commun, et vous ne pouvez pas le trouver sans factorisation. C\'est pourquoi ces deux outils vont de pair : vérifiez les facteurs, puis obtenez le GCF et le LCM en une seule étape."},{"p":"La moitié du LCM est celle que les gens oublient, et c\'est celle qui résout les problèmes de planification : deux événements qui se répètent tous les 18 jours et tous les 12 jours coïncident tous les 36 jours. Même arithmétique, application différente."},{"h":"Les factorielles et la vitesse à laquelle elles explosent"},{"l":["[[calculateur factoriel|Calculateur factoriel]] — n ! pour les valeurs où la réponse est encore significative."]},{"p":"Les factorielles croissent plus rapidement que presque tout ce que vous rencontrez à un bureau. 10 ! est d\'environ 3,6 millions. 20 ! est d’environ 2,4 quintillions – soit largement plus grand que le nombre de grains de sable sur Terre. 52 !, le nombre de façons de mélanger un jeu de cartes, est d\'environ 8 suivis de 67 chiffres.\\n\\nLa conséquence pratique est qu\'un programme qui énumère toutes les permutations est correct à 5 éléments, tolérable à 8 et bloqué en permanence à 12. Si une tâche donne l\'impression qu\'elle ne se terminera jamais et que vous parcourez les permutations, c\'est presque certainement pourquoi. C’est aussi l’argument contre la plupart des approches par force brute, présenté comme de l’arithmétique plutôt que comme une opinion."},{"h":"Les chiffres romains et ce qui est étrange à leur sujet"},{"l":["[[roman-numerals|Roman Numeral Converter]] — convertit vers et depuis des chiffres romains."]},{"p":"Les chiffres romains méritent d\'être compris plutôt que simplement convertis, car le système révèle quelque chose sur la notation positionnelle. Il n\'y a pas de zéro, ni de valeur de position : XI signifie onze, qu\'il représente onze bâtons ou onze mille. C’est pourquoi l’arithmétique en chiffres romains est véritablement difficile et pourquoi le système a survécu pendant des siècles principalement pour le comptage et la datation plutôt que pour le calcul.\\n\\nLa règle soustractive est la partie où les gens se trompent. IV vaut quatre, pas VI ; IX est neuf. Les horloges sont une exception célèbre : Big Ben utilise IIII plutôt que IV, pour des raisons sur lesquelles les historiens débattent encore. Convertir plutôt que dériver est la bonne décision dans tous les cas."},{"h":"Un exemple concret : vérifier une fraction à la main"},{"p":"Une recette nécessite 0,375 tasse et une balance qui indique en grammes, un rapport cite un ratio de 0,625, et les deux ressemblent à des chiffres que quelqu\'un a tapés à la hâte."},{"l":["**1. Trouvez la fraction exacte.** Exécutez 0,375 via l\'outil [[decimal-fraction|Decimal to Fraction]] : 3/8. Exécutez 0,625 : 5/8. Ni l’un ni l’autre n’avait besoin d’une habitude de calculatrice que vous n’avez pas.","**2. Simplifiez le rapport.** Pour exprimer 3/8 contre 5/8, vous avez besoin du GCF de 3 et 5. Le [[gcf-calculator|GCF LCM Calculator]] donne 1, donc le rapport est de 3:5 et déjà le plus simple.","**3. Vérifiez les affirmations factorielles.** Si quelqu\'un vous dit qu\'une file d\'attente de 9 commandes contient 362 880 arrangements, le [[factorial-calculator|Factorial Calculator]] confirme 9 ! c\'est exactement ça. Vous savez maintenant si l\'estimation du temps de construction était plausible.","**4. Normalisez tout ce qui est volumineux.** Un serveur signalant 1,5e9 nanosecondes équivaut à 1,5 secondes, selon le [[scientific-notation|Scientific Notation Converter]] — ce qui est la différence entre un problème de latence et un artefact d\'arrondi."]},{"h":"Ce que ces outils ne font délibérément pas"},{"p":"Ils ne montrent pas leur travail et n\'enseignent pas. Si vous avez besoin de comprendre pourquoi une formule est vraie, une calculatrice n’est pas le bon instrument : elle donne la réponse sans raison, c’est ainsi que les gens finissent par être capables de calculer et incapables de raisonner.\\n\\nIls ne font pas non plus preuve de précision arbitraire. Les factorielles et les grandes factorisations perdront en précision au-delà du point où la réponse est encore utile, et un onglet de navigateur n\'est pas un système de calcul formel. Pour tout ce qui importe vraiment – ​​ingénierie, finance, cryptographie – utilisez une bibliothèque appropriée avec une arithmétique exacte, pas une page Web."},{"h":"Vérifier votre propre arithmétique"},{"p":"L’habitude mathématique la plus précieuse n’est pas la vitesse, c’est l’estimation. Avant de croire un résultat, demandez-vous s\'il s\'agit du bon ordre de grandeur : plus grand ou plus petit que l\'entrée, et de combien environ. La plupart des erreurs arithmétiques survivent à tous les autres contrôles, sauf celui-ci.\\n\\nL’arrondi rend d’abord l’estimation gratuite. Arrondissez 0,375 à 0,4, arrondissez 5/8 à 0,6, et le rapport est évidemment d\'environ 2:3 – suffisamment proche de 3:5 pour confirmer exactement la fraction que vous avez calculée. Si la réponse exacte et l\'estimation ne sont pas d\'accord, vous avez trouvé une erreur de saisie plutôt qu\'un problème d\'arrondi, et vous l\'avez trouvé en quelques secondes.\\n\\nC’est aussi pourquoi une calculatrice ne remplace pas la réflexion sur ce que vous lui avez demandé. Un outil calculera parfaitement la mauvaise quantité, et la seule défense est de savoir à quoi devrait ressembler la réponse."},{"h":"Questions fréquemment posées"},{"p":"**Ma contribution est-elle envoyée n\'importe où ?** Non. Tous ces éléments s\'exécutent localement dans votre navigateur.\\n\\n**Pourquoi 0,1 plus 0,2 n\'est-il pas égal à 0,3 ?** Parce que ni 0,1 ni 0,2 ne sont exactement représentables en virgule flottante binaire. La somme est de 0,30000000000000004, ce qui est le double le plus proche de 0,3.\\n\\n**Quelle taille de factorielle peuvent-ils gérer ?** Jusqu\'à 170 avant de dépasser la plage d\'un double. Au-delà de cela, la réponse est affichée en notation scientifique et cesse alors d\'avoir du sens.\\n\\n**Puis-je utiliser la sortie dans le code ?** Oui. Pour les résultats décimaux en fractions en particulier, utilisez l\'arithmétique entière sur le numérateur et le dénominateur plutôt que de reconvertir en nombre décimal."},{"h":"La version en une ligne"},{"p":"Utilisez des fractions exactes lorsque de l\'argent est en jeu, rappelez-vous que les factorielles explosent plus rapidement que prévu et que la factorisation première est à la fois un fondement de sécurité et une astuce de simplification des fractions."}]},"everyday-utility-tools":{"title":"13 utilitaires quotidiens gratuits : mots de passe, codes QR, minuteries et encodage de texte","description":"Générez des mots de passe, créez des codes QR, exécutez des minuteries et des horloges et décodez du texte binaire, hexadécimal et chiffré, le tout avec des outils de navigation gratuits qui ne téléchargent rien.","category":"Outils utilitaires","blocks":[{"p":"Ce dernier groupe est le tiroir à déchets. Des mots de passe, des codes QR, un chronomètre, une horloge mondiale, un tirage au sort et quatre outils qui convertissent le texte en d\'autres représentations de lui-même. Individuellement trivial, collectivement, ce dont vous avez besoin dans les moments difficiles.\\n\\nL\'essentiel est que les treize fonctionnent localement. Pour un générateur de mots de passe, ce n’est pas une subtilité – c’est la seule raison pour laquelle on peut faire confiance à l’outil."},{"h":"Mots de passe : la partie qui compte vraiment"},{"l":["[[password-generator|Password Generator]] — génère des mots de passe aléatoires forts de n\'importe quelle longueur et jeu de caractères.","[[password-strength|Password Strength Checker]] — estimez la résistance d\'un mot de passe à être deviné, localement."]},{"b":"Le fait le plus important concernant la force des mots de passe : **la longueur l\'emporte sur la complexité, et la réutilisation l\'emporte sur les deux en tant que danger.** Un mot de passe de 16 caractères composé de mots sans rapport est plus fort et bien plus facile à saisir qu\'un fouillis de symboles de 10 caractères. Pendant ce temps, un mot de passe réutilisé qui apparaît lors d’une violation supprime simultanément tous les comptes qu’il touche. Générer un mot de passe long distinct par site constitue tout le travail."},{"p":"La façon dont la force est estimée est également importante. La plupart des vérificateurs se rapprochent de la taille de l\'espace de recherche, ce qui est une approximation raisonnable mais pas la vérité : « CorrectHorseBatteryStaple » obtient de bons résultats en termes d\'entropie, tandis que « P@ssw0rd1 ! » obtient de bons résultats en termes de variété de caractères et mauvais en pratique car il apparaît dans toutes les listes de mots géniales sur terre.\\n\\nUtilisez le générateur pour tout ce qui vous intéresse, et si vous devez vous souvenir d\'un mot de passe, utilisez une phrase secrète de quatre ou cinq mots sans rapport. C’est le cas spécifique où la mémorisation et la force se chevauchent."},{"h":"Codes QR : que mettre dedans"},{"l":["[[qr-code-generator|QR Code Generator]] — générez un code QR pour une URL, un texte, des détails Wi-Fi ou des informations de contact."]},{"p":"Les codes QR font partie de ces outils où la qualité de sortie est entièrement déterminée par une seule décision : la quantité de données que vous entrez. Une URL courte est codée en un petit code facilement lisible. Un paragraphe de texte avec ponctuation est codé en quelque chose de dense et peu fiable dans de petites tailles.\\n\\nDeux règles pratiques. Tout d’abord, testez toujours le code à la taille dans laquelle il sera réellement imprimé avant d’en imprimer deux cents. Deuxièmement, les codes Wi-Fi et les codes URL simples se comportent différemment selon les téléphones : si un code s\'adresse à un public mixte, préférez une URL simple à une page de destination qui renvoie ensuite vers l\'autre, car elle fonctionne partout et vous pouvez modifier l\'endroit où elle pointe."},{"h":"Heure : minuteries, horloges et piège dans les fuseaux horaires"},{"l":["[[chronomètre|Chronomètre en ligne]] — un chronomètre simple, utile lorsque votre téléphone est dans l\'autre pièce.","[[pomodoro-timer|Pomodoro Timer]] — Blocs de concentration de 25 minutes avec pauses, pour les personnes qui trouvent que la structure fonctionne.","[[world-clock|World Clock]] — heure actuelle de plusieurs villes à la fois."]},{"p":"L’horloge mondiale mérite sa place pour une raison précise : l’heure d’été. La moitié des erreurs d\'horaire dans le monde ne sont pas des erreurs arithmétiques, il s\'agit d\'un moment où deux villes étaient espacées de quatre heures la semaine dernière et de cinq heures cette semaine, et personne n\'a vérifié.\\n\\nAvant de planifier quoi que ce soit sur un fuseau horaire, placez les deux villes dans l’horloge mondiale et regardez – ne calculez pas le décalage à partir de la mémoire. C\'est également pourquoi les invitations aux réunions doivent comporter un fuseau horaire plutôt qu\'une simple heure."},{"p":"Sur la minuterie Pomodoro : la technique fonctionne pour un type spécifique de tâche : délimitée, ciblée, ininterrompue. Cela ne fonctionne pas pour le débogage, où le bon mouvement en cas de blocage est de s\'éloigner, et non de démarrer un autre bloc de 25 minutes. Utilisez-le quand cela peut vous aider."},{"h":"Le hasard, honnêtement"},{"p":"Le [[random-number|Random Number Generator]] et le [[list-randomizer|List Randomizer]] couvrent les cas qui se présentent réellement : choisir un nombre dans une plage et mettre une liste dans un ordre équitable. Ça vaut le coup d\'être honnête. Les deux utilisent un générateur pseudo-aléatoire qui, pour décider qui paie le déjeuner, ne se distingue pas d\'une vraie pièce de monnaie. Pour tout ce qui est conséquent – ​​un tirage au sort avec des prix, une allocation avec de l\'argent attaché – vous voulez une source que vous pouvez vérifier, et un onglet de navigateur n\'est pas cela. La valeur ici est de supprimer l’humain, qui choisit mal lorsqu’il est motivé."},{"h":"Le tiroir à déchets d’encodage"},{"p":"Quatre outils qui déplacent le texte entre les représentations. Aucun d\'entre eux n\'est chiffré, et la distinction mérite d\'être soulignée car elle est constamment confuse : un cryptage est réversible par n\'importe qui et n\'a pas de clé. Le cryptage nécessite une clé."},{"l":["[[binary-text|Binary to Text]] — convertit entre le texte et sa représentation binaire.","[[hex-text|Hex to Text]] — convertit entre texte et hexadécimal, la représentation que vous voyez le plus souvent dans les outils réseau et les débogueurs.","[[cesar-cipher|Caesar Cipher]] — décale les lettres d\'un montant fixe, le chiffre classique de la classe.","[[rot13-encoder|ROT13 Encoder]] — fait pivoter les lettres de 13, un cas particulier qui est son propre inverse."]},{"p":"Ceux-ci sont utiles pour exactement deux choses. Tout d’abord, comprendre comment le texte devient des octets, qui est le modèle mental dont vous avez besoin chaque fois que quelque chose semble tronqué. Deuxièmement, le débogage réel : lorsqu\'une charge utile apparaît au format hexadécimal, le convertisseur [[hex-text|Hex to Text]] vous permet de découvrir ce qu\'il dit.\\n\\nIls ne servent à rien pour cacher quoi que ce soit. ROT13 n’a pas de clé – le changement est public – donc il ne cache rien à quiconque sait ce qu’est ROT13. Le chiffre de César comporte 25 décalages possibles, qu\'un humain brise dès la première minute."},{"h":"Les deux qui formatent les choses"},{"l":["[[phone-formatter|Phone Number Formatter]] — normalise les numéros de téléphone dans un format cohérent.","[[file-size-converter|File Size Converter]] — convertit entre Ko, Mo, Go et To, avec la distinction décimale et binaire expliquée."]},{"p":"Le convertisseur de taille de fichier a un résultat vraiment précieux : il vous indique pourquoi un lecteur annonce un nombre plus grand que celui indiqué par votre ordinateur. Les fournisseurs vendent par puissance de dix, les systèmes d\'exploitation déclarent des puissances de deux, et l\'écart est d\'environ 7 % à chaque échelle. Ce n\'est pas une faute, ce sont deux conventions."},{"h":"Un exemple concret : la réponse API tronquée"},{"p":"Un webhook échoue à la validation et la charge utile dans le journal ressemble à `\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f`. Il s’agit d’un quatre-vingt-douzième diagnostic."},{"l":["**1. Convertir.** Collez « 48656c6c6f » dans le convertisseur [[hex-text|Hex to Text]] — le résultat est « Bonjour ». Il n’a jamais été tronqué, juste codé.","**2. Vérifiez la forme.** Quelque chose en amont code en hexadécimal la charge utile avant de signer. La signature a été calculée sur le texte original et validée par rapport à l\'hexadécimal, donc la comparaison échoue.","**3. Éliminez l’autre sens.** Si le journal avait affiché un texte lisible, le problème aurait été l’inverse : signer le formulaire codé.","**4. Confirmez la demande de taille.** Si le même journal signale une charge utile de 1,2 Mo, le [[file-size-converter|File Size Converter]] détermine si celle-ci est décimale ou binaire avant que quiconque ne discute d\'un quota."]},{"h":"Questions fréquemment posées"},{"p":"**Le générateur de mot de passe est-il sûr si tout s\'exécute dans le navigateur ?** Oui, et plus encore qu\'un générateur de mot de passe basé sur un serveur : le mot de passe est généré sur votre machine et n\'est jamais transmis, il n\'y a donc rien à intercepter, à enregistrer ou à violer. Le compromis est que vous ne pouvez pas récupérer un mot de passe que vous n\'avez pas enregistré.\\n\\n**Puis-je faire confiance au tirage au sort virtuel ?** Pour des décisions occasionnelles, oui. Pour tout ce qui implique de l\'argent ou des prix, utilisez une source que vous pouvez vérifier.\\n\\n**Les chiffrements sont-ils sécurisés ?** Non. Aucun d\'entre eux. Les chiffres ROT13 et César n’ont pas de clé secrète et existent pour enseigner le codage, et non pour protéger quoi que ce soit.\\n\\n**Est-ce que cela fonctionne hors ligne ?** Une fois qu\'une page est chargée, oui, tout est local.\\n\\n**Y a-t-il une limite sur la longueur du texte pour les convertisseurs ?** Uniquement la mémoire de votre appareil, puisque rien n\'est envoyé nulle part."},{"h":"La version en une ligne"},{"p":"Les mots de passe longs et uniques surpassent les mots de passe courts et intelligents, un code QR est aussi bon que les données qu\'il contient, vérifie les décalages horaires plutôt que de les calculer, et l\'encodage n\'est pas un cryptage."}]}}')},78831,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"Das Entwickler-Toolkit: 24 kostenlose Browser-Tools, die kostenpflichtige Apps ersetzen","description":"Eine praktische Anleitung zum Formatieren, Konvertieren, Kodieren und Debuggen von Daten mit kostenlosen browserbasierten Entwicklertools – keine Installationen, keine Konten, nichts Hochladen.","category":"Entwicklertools","blocks":[{"p":"Für die meisten kleinen Aufgaben, die Sie hundertmal pro Woche erledigen – eine API-Antwort neu formatieren, ein Token dekodieren, einen Hash überprüfen, einen SQL-Slug einrücken – ist keine IDE, kein kostenpflichtiges Abonnement oder eine Teamlizenz erforderlich. Sie müssen einen Tab neunzig Sekunden lang geöffnet haben.\\n\\nDie folgende Sammlung umfasst vierundzwanzig browserbasierte Dienstprogramme für Formatierung, Konvertierung, Kodierung, Hashing und Debugging. Jeder von ihnen läuft vollständig auf Ihrer Seite: Ihre Daten werden niemals an einen Server gesendet, was wichtiger ist, als Entwickler normalerweise zugeben, da die von Ihnen eingefügten Nutzdaten normalerweise die eines Kunden sind."},{"h":"Was browserbasierte Tools ersetzen können und was nicht"},{"p":"Seien Sie realistisch, was die Grenze angeht. Diese Tools ersetzen einmalige, hochfrequente Aufgaben mit geringem Einsatz. Sie ersetzen nicht Ihren Sprachserver, Ihren Debugger, Ihre Testsuite oder alles, was Sie für die wiederholte Ausführung in einer realen Umgebung benötigen."},{"l":["**Gut geeignet:** Eine Antwort einmal lesen, einen einzelnen Wert debuggen, eine Datei für einen Import konvertieren, ein Format vor dem Versand prüfen.","**Schlechte Passform:** Bei jeder Bereitstellung wird die gleiche Prüfung durchgeführt, Hunderte von Dateien werden transformiert, alles, was in CI lautstark fehlschlagen muss.","**Niemals:** alles, was Anmeldeinformationen betrifft, die Sie nicht rotieren können. Fügen Sie ein widerrufenes Token ein, kein aktives."]},{"p":"Der Grund, diese Lesezeichen zu behalten, ist jedoch der Durchsatz. Eine Aufgabe, die in einem Browser-Tab vierzig Sekunden dauert, wird nie geplant, nie delegiert und wird nie zu einem Grund, um acht Uhr abends eine IDE zu öffnen."},{"h":"Formatieren und Konvertieren von Daten"},{"p":"Die häufigste tägliche Aufgabe besteht darin, Daten lesbar zu machen. Eine API gibt einen einzeiligen Blob zurück, ein Kollege sendet eine Konfigurationsdatei mit durch ein Chat-Fenster verstümmelten Tabs, oder Sie haben eine Tabelle nach JSON exportiert und es kam als eine riesige Zeile zurück."},{"l":["[[json-formatter|JSON Formatter]] – eine Nutzlast einrücken, validieren und lesen. Verwenden Sie es vor dem Debuggen: Die Hälfte aller Tickets mit der Meldung „Die API ist defekt“ sind in Wirklichkeit fehlerhaftes JSON mit einem abschließenden Komma.","[[json-validator|JSON Validator]] – wenn Sie eine strikte Pass/Fail-Antwort statt eines hübschen Ausdrucks benötigen.","[[xml-formatter|XML Formatter]] – derselbe Job für SOAP-Antworten, RSS-Feeds und Maven-POMs, den seit 2014 niemand mehr angerührt hat.","[[json-to-yaml|JSON zu YAML]] und [[json-to-csv|JSON zu CSV]] – Verschieben von Daten zwischen den Formaten, die echte Systeme tatsächlich verwenden."]},{"p":"Denken Sie an die letzte Gruppe für ein bestimmtes Szenario: Ein Kunde überreicht Ihnen eine Tabelle und erwartet sie in seiner API. Die direkte Umwandlung von CSV in JSON dauert nur zwei Minuten und erfordert nicht einen Nachmittag mit Skripten."},{"h":"Kodierung und Flucht"},{"p":"Codierungsfehler sind unverhältnismäßig ärgerlich, da die Daten gut aussehen. Der Wert „San José & Sons“ wird als „San Jos%C3%A9 %26 Sons“ angezeigt und Ihr Vergleich mit der Datenbank schlägt aus Gründen fehl, die in den Protokollen nicht sichtbar sind."},{"l":["[[url-encoder|URL-Encoder/Decoder]] – stellt sofort fest, ob eine Abfragezeichenfolge doppelt codiert ist.","[[base64-encoder|Base64-Encoder/Decoder]] – dekodieren Sie ein Zertifikatfragment oder kodieren Sie ein kleines Asset, um es in CSS zu integrieren.","[[html-entity-encoder|HTML-Entity-Encoder/Decoder]] – Finden Sie heraus, ob das verirrte „&“ auf Ihrer Seite von Ihrer Vorlage oder Ihren Daten stammt.","[[unicode-converter|Unicode Converter]] – nützlich, wenn sich herausstellt, dass ein „kaputtes“ Zeichen ein legitimes Zeichen ist, das in der falschen Codierung gerendert wurde.","[[number-base-converter|Number Base Converter]] – Überprüfen Sie eine Farbe, eine Berechtigungsbitmaske oder eine Speicheradresse ohne eine Taschenrechner-App."]},{"b":"Eine praktische Angewohnheit: Wenn ein Wert verstümmelt ankommt, dekodieren Sie ihn Schicht für Schicht und fügen Sie jedes Ergebnis in ein leeres Feld ein. Wenn die erste Dekodierung lesbaren Text erzeugt, liegt das Problem in einer zusätzlichen Kodierung irgendwo weiter oben. Wenn es Mojibake erzeugt, liegt eher ein Codierungsproblem als ein Escape-Problem vor, und diese beiden erfordern unterschiedliche Korrekturen."},{"h":"Identifikatoren, Hashes und Token"},{"p":"In dieser Gruppe verschwenden Entwickler die meiste Zeit mit der Suche nach dem richtigen lokalen Skript, das sie einmal geschrieben und verloren haben."},{"l":["[[uuid-generator|UUID-Generator]] – Generieren Sie v4-Identifikatoren für Seed-Daten, Fixtures oder eine schnelle Datenbankzeile.","[[md5-generator|MD5 / SHA Hash Generator]] – Überprüfen Sie einen Download oder bestätigen Sie, dass zwei Dateien, die identisch sein sollten, tatsächlich identisch sind.","[[timestamp-converter|Timestamp Converter]] – das am häufigsten verwendete Tool in dieser ganzen Liste. Wenn in einer Protokollzeile 1761000000 steht, erfahren Sie hieraus, ob der Vorfall während der Bereitstellung oder davor aufgetreten ist."]},{"p":"Der Zeitstempelkonverter verdient seinen Unterhalt aus einem bestimmten Grund: Eine Epochennummer ist eindeutig und nutzlos zugleich. Sie wissen genau, wann etwas passiert ist und können es keinem Kollegen sagen. Durch einmaliges Konvertieren wird normalerweise ein lauterer Streit geklärt, als er sollte."},{"h":"Vergleichen und Debuggen"},{"l":["[[regex-tester|Regex Tester]] – das Element mit der höchsten Hebelwirkung hier. Ein regulärer Ausdruck, der korrekt aussieht und stillschweigend mit nichts übereinstimmt, ist einer der teuersten Fehler in der Entwicklung, da er stillschweigend an der einen Stelle scheitert, die niemand liest.","[[html-preview|HTML Preview]] – Iterieren Sie ein Markup-Fragment, um zu überprüfen, wie es tatsächlich gerendert wird."]},{"p":"Testen Sie Ihre regulären Ausdrücke anhand der Eingabe, die Sie tatsächlich erwarten, einschließlich der leeren Zeichenfolge, eines Unicode-Namens und eines Werts mit einer neuen Zeile. Die meisten Muster brechen im dritten Fall und niemand bemerkt es, bis die Produktionsdaten eintreffen."},{"h":"Ein praktisches Beispiel: drei Werkzeuge, ein langweiliger Vorfall"},{"p":"Hier ist die Sequenz, die mich überzeugt hat, das alles in meinen Lesezeichen zu speichern. Ein Kunde berichtete, dass ein Datensatz, den er am Dienstag eingereicht hatte, in einem Bericht vom Donnerstag fehlte."},{"l":["**1. Konvertieren Sie den Zeitstempel.** Der Berichtsjob protokollierte die Erstellungszeit des Datensatzes als Epochenwert. Der [[timestamp-converter|Timestamp Converter]] zeigte, dass der Datensatz um 23:00 Uhr Ortszeit, also am Dienstag, erstellt wurde – die Zeitzonenannahme des Jobs war das Problem, nicht der Datensatz.","**2. Formatieren Sie die Nutzlast.** Beim Durchlaufen des gespeicherten JSON-Codes durch den [[json-formatter|JSON Formatter]] stellte sich heraus, dass der Datensatz mit einem Null-Datumsfeld geschrieben wurde, da der Client denselben Endpunkt zweimal im Abstand von 200 ms aufrief und der zweite Schreibvorgang gewann.","**3. Vergleichen Sie die Nutzlasten.** Beide Datensätze enthielten denselben API-Schlüssel und denselben Client-Zeitstempel, was auf einen Wiederholungsversuch und nicht auf zwei separate Kunden hinwies."]},{"p":"Gesamtzeit: vier Minuten. Der vorherige Versuch dieser Untersuchung, bei dem nach der gleichen Grundursache in einer Protokollierungsplattform gesucht wurde, dauerte einen Nachmittag und kam zu einer falschen Schlussfolgerung."},{"h":"Datenschutz: Warum die lokale Ausführung die eigentliche Funktion ist"},{"p":"Jedes Tool in dieser Bibliothek verarbeitet Ihre Eingaben in Ihrem eigenen Browser. Es wird nichts hochgeladen, was bedeutet, dass es keine Frage zur Aufbewahrung gibt, keine Prozessorvereinbarung besteht und keine unangenehme Unterhaltung über die Produktionsnutzlast besteht, die Sie vor drei Minuten eingefügt haben.\\n\\nAus diesem Grund bevorzugen Sie diese Tools gegenüber einer gehosteten „Pastebin-API“ oder einem Onlinedienst, der Sie zur Anmeldung auffordert. Es bedeutet auch, dass sie während eines Fluges, in einem Keller weiterarbeiten oder wenn das Unternehmens-VPN beschlossen hat, eine weitere Domäne zu blockieren."},{"p":"Eine Einschränkung, die es deutlich zu sagen gilt: Eine offlinefähige Seite ist nur dann privat, wenn es sich bei der Seite selbst um den Code handelt, für den Sie sie halten. Verwenden Sie auf einem gemeinsam genutzten Computer ein privates Fenster und schließen Sie es, wenn Sie fertig sind, insbesondere wenn Sie Token dekodiert haben."},{"h":"Erstellen Sie einen Workflow um sie herum"},{"p":"Die Werkzeuge sind einzeln trivial. Der Wert liegt in der Angewohnheit, sofort danach zu greifen, anstatt „später danach zu greifen“, denn später schreiben Sie ein Wegwerfskript, öffnen eine IDE oder entscheiden, dass es sich überhaupt nicht lohnt, es zu überprüfen."},{"l":["Setzen Sie ein Lesezeichen für die Sammlung, nicht für einzelne URLs, und fügen Sie sie in die Symbolleiste Ihres Browsers ein.","Wenn etwas falsch aussieht, überprüfen Sie es, bevor Sie eine Theorie aufstellen. Kostet fünfzehn Sekunden; tötet ganze Klassen falscher Schlussfolgerungen.","Wenn Sie dasselbe zweimal überprüft haben, ist das das Signal, es zu automatisieren – aber automatisieren Sie nicht bei Verdacht.","Fügen Sie keine Produktionsgeheimnisse ein. Drehen Sie alles, worüber Sie sich nicht sicher sind."]},{"h":"Häufig gestellte Fragen"},{"p":"**Sind diese Tools kostenlos?** Ja, vollständig, ohne Konto und ohne Nutzungsbeschränkung. Es gibt keine kostenpflichtige Stufe, die etwas Grundlegendes zurückhält.\\n\\n**Funktionieren sie offline?** Sobald eine Seite geladen ist, ja – alles läuft in Ihrem Browser. Zum Nachladen ist eine Verbindung erforderlich.\\n\\n**Kann ich sie für kommerzielle Arbeiten verwenden?** Ja. Die Ausgabe gehört Ihnen, ohne Angabe einer Quellenangabe.\\n\\n**Gibt es eine API?** Nein, und das ist Absicht – der Wert ist die Schnittstelle. Exportieren Sie die Ausgabe und verarbeiten Sie sie nach Ihren Wünschen.\\n\\n**Warum installieren Sie nicht stattdessen einfach ein CLI-Tool?** Installieren Sie eines, wenn Sie es dreimal benötigen. Verwenden Sie für die ersten beiden einen Browser-Tab."}]},"text-tools-for-writers":{"title":"17 kostenlose Texttools für Autoren, Studenten und Vermarkter","description":"Bereinigen Sie Texte, zählen Sie Wörter genau, formatieren Sie Listen und verwandeln Sie grobe Entwürfe in etwas, das veröffentlicht werden kann – mit kostenlosen Browser-Tools, die Ihren Text nie hochladen.","category":"Textwerkzeuge","blocks":[{"p":"Das Schreiben für die Arbeit ist mit überraschend viel mechanischer Plackerei verbunden, die nichts mit dem Schreiben zu tun hat: Verirrte Leerzeichen aus einem eingefügten Absatz entfernen, eine Wortbeschränkung überprüfen, eine Namensliste deduplizieren, etwas in einen URL-Slug umwandeln.\\n\\nDiese siebzehn Werkzeuge sind für diesen Teil der Arbeit gedacht. Sie werden alle lokal im Browser ausgeführt, was kein kleines Detail ist – der Entwurf, den Sie einfügen, ist oft unveröffentlicht und die Liste, die Sie sortieren, enthält oft die persönlichen Daten einer anderen Person."},{"h":"Messen Sie, was Sie geschrieben haben"},{"p":"Die Wortzählung scheint gelöst, bis ein Kunde nach genau 800 Wörtern fragt und Ihr Redakteur 820 sagt oder ein Formular Ihren Text mit 1.995 Zeichen ablehnt, ohne zu erklären, wo die neue Zeile hingehört."},{"l":["[[word-counter|Word Counter]] – das Standardmaß. Einfügen, lesen, anpassen.","[[letter-counter|Letter Counter]] – zählt Zeichen und Buchstabenhäufigkeit. Nützlich, wenn Sie herausfinden, warum sich ein Absatz falsch anfühlt: Normalerweise handelt es sich um ein wiederholtes Buchstabenmuster und nicht um einen Traum."]},{"p":"Ein Hinweis zur Bedeutung eines Wortes: Verschiedene Zähler sind sich über Silbentrennung, Zahlen und URLs nicht einig. Wenn es auf eine genaue Anzahl ankommt, verwenden Sie denselben Schalter, den auch die Person verwendet, die Ihre Arbeit überprüft, und vereinbaren Sie dies im Voraus. Dies ist eine wirklich häufige Quelle für kleine, sinnlose Argumente."},{"h":"Bereinigen Sie die Kopie, die Sie nicht geschrieben haben"},{"p":"Der meiste Text, den Sie erhalten, ist leicht beschädigt: doppelte Leerzeichen durch Kopieren und Einfügen, ein verirrter Tabulator, inkonsistente Groß- und Kleinschreibung durch jemanden, der in Eile tippt. Das manuelle Reparieren ist langsam und fehleranfällig."},{"l":["[[text-trimmer|Text Trimmer]] – Entfernen Sie führende und nachfolgende Leerzeichen aus jeder Zeile auf einmal. Dies behebt mehr Berichte über die Meldung „Formatierung sieht fehlerhaft aus“ als alles andere auf dieser Liste.","[[text-case-converter|Text Case Converter]] – Wechseln Sie zwischen Satz-, Titel-, Groß- und Kleinschreibung in einem Block. Auch der schnellste Weg, einen versehentlichen Absatz mit der Feststelltaste rückgängig zu machen.","[[text-to-slug|Text to Slug]] – Verwandeln Sie eine Überschrift in einen sauberen URL-Slug. Fügen Sie Ihren Titel ein, holen Sie sich den Slug, fertig."]},{"p":"Der Slug-Generator hat über URLs hinaus einen weiteren Nutzen: Er ist eine schnelle Möglichkeit, einen lesbaren Dateinamen oder Anker zu erstellen, den ein Mensch auf einen Blick analysieren kann, was „final_final_v3“ übertrifft."},{"h":"Arbeiten mit Listen"},{"p":"Listicles, Inventare, Serienbriefe, Tag-Bereinigungen, Umfrageantworten, Tabellenspalten – irgendwann wird alles zu einer Liste und jede Liste muss sortiert, dedupliziert oder randomisiert werden."},{"l":["[[duplicate-line-remover|Duplicate Line Remover]] – Vergleichen Sie zwei Listen oder bereinigen Sie eine. In der Ausgabe erfahren Sie, wie viele Duplikate entfernt wurden. Dies ist hilfreich, wenn Sie das Ergebnis melden.","[[list-sorter|List Sorter]] – die gleiche Aufgabe für die strukturierte Listeneingabe.","[[list-randomizer|List Randomizer]] – Mischen Sie eine Ziehungsreihenfolge, eine Quizsequenz oder eine abgegrenzte Auswahlliste, damit niemand den Verdacht einer Bevorzugung hegt.","[[line-number-adder|Line Number Adder]] – Nummerierungszeilen als Referenz in einem Ticket oder einem Kommentar zur Codeüberprüfung."]},{"b":"Die klassische Falle hier ist eine Liste, die dedupliziert aussieht, es aber nicht ist: „Apple“, „apple“ und „Apple“. sind drei verschiedene Zeilen für einen Computer. Entfernen Sie vor der Deduplizierung Leerzeichen und nachfolgende Satzzeichen. Andernfalls führen Sie nichts zusammen und kommen zu dem Schluss, dass die Daten sauber sind."},{"h":"Vorschau und Formatierung"},{"p":"Markdown hat gewonnen, aber nicht einheitlich. Die Hälfte Ihrer Werkzeuge rendert es, die andere Hälfte nicht, und die Hälfte, bei der dies nicht der Fall ist, muss normalerweise ein Vorgesetzter einfügen."},{"l":["[[markdown-preview|Markdown Preview]] – Live-Rendering, sodass Sie überprüfen können, ob eine Tabelle oder eine verschachtelte Liste tatsächlich aussieht, bevor sie einen Client erreicht.","[[text-repeater|Text Repeater]] – eine Zeichenfolge N-mal wiederholen. Nützlich zum Generieren von Auffüllungen, zum Testen von Daten oder gelegentlich zum Hervorheben einer Aussage in einem Dokument."]},{"p":"Die Markdown-Vorschau ist in aller Stille das Tool, das am meisten Zeit spart, da eine kaputte Tabelle in einem gerenderten Dokument weitaus sichtbarer – und weitaus peinlicher – ist als eine kaputte Tabelle im Rohtext."},{"h":"Der Rest und wann man danach greifen sollte"},{"l":["[[random-string|Random String Generator]] – Generieren Sie lesbare Nonces, Platzhalter-IDs oder Funktionscodes. Besser, als etwas von Hand zu erfinden, weil Sie es nicht versehentlich wiederverwenden.","[[Morse-Code|Morsecode-Übersetzer]] – wirklich lustig, gelegentlich nützlich für ein Themenprojekt oder ein Puzzle."]},{"p":"Dabei handelt es sich um Tools mit geringerer Frequenz, aber es kostet nichts, sie in den Lesezeichen zu behalten, und sie lösen das spezifische Problem: „Ich brauche gerade einen zufällig aussehenden Wert und traue mir nicht, mir einen auszudenken.“"},{"h":"Ein realistischer Bearbeitungsdurchgang"},{"p":"Hier ist die Reihenfolge, die funktioniert, wenn ein Entwurf von einer anderen Person eintrifft und unter Ihrem Namen ausgegeben werden muss."},{"l":["**1. Trimmen.** Lassen Sie das gesamte Dokument zunächst durch den [[Texttrimmer|Texttrimmer]] laufen. Schäden durch Leerzeichen verstecken sich in Absätzen, wo Sie sie nie sehen werden.","**2. Klare Groß-/Kleinschreibung.** Verwenden Sie den [[text-case-converter|Text Case Converter]] nur für die Überschrift. Wenden Sie niemals die Fallumwandlung auf einen vollständigen Entwurf an – dadurch werden Eigennamen zerstört.","**3. Messen.** Überprüfen Sie vor dem Schreiben die Länge mit dem [[word-counter|Word Counter]], damit Sie wissen, welche Form das Stück haben soll.","**4. Vorschau.** Wenn es Markdown enthält, rendern Sie es mit der [[markdown-preview|Markdown-Vorschau]].","**5. Slug.** Generieren Sie den URL-Slug zuletzt aus der letzten Überschrift mit [[text-to-slug|Text to Slug]] – wenn Sie die Überschrift danach ändern, wird der Slug unterbrochen."]},{"p":"Der gesamte Durchgang dauert nur wenige Minuten und eliminiert die Fehlerkategorie, bei der ein Dokument technisch korrekt und sichtbar falsch ist."},{"h":"Fragen von Autoren zum Thema Privatsphäre"},{"p":"**Verlässt mein unveröffentlichter Text meinen Computer?** Nein. Diese Tools verarbeiten Text in Ihrem Browser und es wird nichts gespeichert oder übertragen.\\n\\n**Gibt es eine Längenbeschränkung?** Es gibt keine serverseitige Beschränkung, da kein Serveraufruf erfolgt. Extrem große Eingaben werden durch den Speicher Ihres eigenen Geräts begrenzt.\\n\\n**Kann ich die Ausgabe kommerziell nutzen?** Ja, frei, ohne Quellenangabe.\\n\\n**Funktionieren sie mit einem Telefon?** Ja. Das Layout passt sich an und derselbe Code wird ausgeführt."},{"h":"Was diese Tools nicht für Sie tun werden"},{"p":"Es lohnt sich, offen über die Grenzen zu sprechen, denn ein Werkzeug, das das Falsche mechanisiert, produziert nur einen schnelleren Fehler.\\n\\nKeines dieser Dienstprogramme kann Ihnen sagen, ob ein Satz klar ist, ob eine Behauptung aus einer Quelle stammt oder ob der Ton für das Publikum richtig ist. Sie zählen Zeichen; Sie beurteilen Prosa nicht. Ein Text, der bei jeder Kennzahl auf dieser Seite hervorragend abschneidet, kann dennoch unlesbar sein.\\n\\nSie bearbeiten auch nicht. In dem Moment, in dem Sie feststellen, dass Sie einzelne Klauseln in großem Maßstab von Hand umschreiben, sind Sie einem Textwerkzeug entwachsen und benötigen entweder einen richtigen Editor, ein Suchen-und-Ersetzen-System mit Regex – das sich mit dem [[Regex-Tester|Regex-Tester]] wirklich gut zum Üben eignet – oder ein Skript. Verwenden Sie den Browser für die mechanische Ebene und behalten Sie Ihr eigenes Urteilsvermögen für alles darüber."},{"p":"Eine weitere Sache, die sie nicht tun werden, ist, eine fehlerhafte Quelle zu reparieren. Wenn Ihre Tabelle voller inkonsistenter Namen ist – „Dr“, „DR“, „Dr.“ Alles in einer Spalte – ein Tool sortiert und dedupliziert das, was Sie ihm gegeben haben, originalgetreu, und Sie haben immer noch drei Einträge, wo eigentlich einer sein sollte. Das Bereinigen der Daten ist eine Entscheidung, kein mechanischer Schritt. Entscheiden Sie sich zuerst für die kanonische Form, wenden Sie sie dann an und überprüfen Sie sie."},{"h":"Eine Arbeitsliste nutzbar halten"},{"p":"Wenn Sie eine Liste mit Leads, Links, Referenzen oder Begriffen führen, verfällt diese geräuschlos. Der Fehlermodus ist immer derselbe: Einträge, die identisch aussehen, sind es nicht, und eine Zusammenführung entfernt nichts.\\n\\nEin Wartungsdurchgang, der funktioniert, ist langweilig: Leerzeichen kürzen, Groß- und Kleinschreibung standardisieren, nachgestellte Satzzeichen entfernen und dann die Duplikate entfernen. In dieser Reihenfolge gehen beim Beschneiden nach dem Deduplizieren Einträge verloren. Wenn Sie dies einmal im Monat auf einer aktiven Liste tun, wird aus einem zweistündigen, nicht behebbaren Durcheinander eine zehnminütige Aufgabe.\\n\\nWenn zwei Listen abgeglichen werden müssen – beispielsweise eine Registrierungsliste mit einer Anwesenheitsliste – sortieren Sie beide zuerst mit dem [[list-sorter|List Sorter]], sodass sie ausgerichtet sind, und vergleichen Sie sie dann nach Augenmaß. Das Sortieren beider Seiten vor dem Vergleich macht den Unterschied zwischen einer zweiminütigen Überprüfung und einer zwanzigminütigen Jagd aus."},{"h":"Das Essen zum Mitnehmen"},{"p":"Keines dieser Tools ist clever. Das ist der Punkt: Sie entfernen die mechanischen fünf Prozent des Schreibens, die kein Schreiben sind, sodass es bei den restlichen fünfundneunzig Prozent tatsächlich um Sätze geht. Setzen Sie ein Lesezeichen für diejenigen, die Sie monatlich verwenden, ignorieren Sie den Rest und hören Sie auf, Leerzeichen manuell zu korrigieren."}]},"calculators-and-converters-guide":{"title":"18 kostenlose Rechner und Umrechner für die Zahlen, mit denen Sie tatsächlich zu tun haben","description":"Prozentsätze, Rabatte, Trinkgelder, Kredite, Daten, BMI und Einheitenumrechnungen – kostenlose Browser-Rechner, die ihre Argumentation zeigen und Ihre Eingaben nie speichern.","category":"Taschenrechner","blocks":[{"p":"Jeder muss eine Rechnung aufteilen, herausfinden, ob es sich bei einem Rabatt tatsächlich um einen Rabatt handelt, und eine Temperatur oder eine Dateigröße umrechnen, ohne darüber nachzudenken. Jeder versteht das auch mindestens einmal in der Öffentlichkeit falsch.\\n\\nDies ist eine Sammlung von achtzehn Taschenrechnern und Umrechnern für Geld, Daten, Gesundheit und die Einheitenumrechnungen, die bei der Arbeit und auf Reisen anfallen. Sie laufen alle im Browser: Es wird nichts gespeichert, sodass die von Ihnen eingegebenen Zahlen niemanden außer Ihnen etwas angehen."},{"h":"Geldberechnungen"},{"p":"Die gebräuchlichste Mathematik in der realen Welt ist ein Prozentsatz von etwas. Umsatzsteuer, ein Trinkgeld, ein Rabattstapel, eine Provision, eine Wachstumsrate. Die Formel ist einfach, und doch ist der Grund, warum Menschen etwas falsch machen, fast immer derselbe: Sie wenden einen Prozentsatz auf die falsche Basis an."},{"l":["[[Rabattrechner|Rabattrechner]] – Berechnen Sie den Endpreis und, was noch wichtiger ist, wie viel Sie gespart haben. Nützlich, um einen „50 % Rabatt“ zu erkennen, der in Wirklichkeit 20 % nach einem erhöhten Listenpreis entspricht.","[[tip-calculator|Tip Calculator]] – Teilen Sie eine Rechnung auf, wählen Sie einen Prozentsatz aus und runden Sie pro Person, wenn Sie möchten.","[[Kreditrechner|Kreditrechner]] – monatliche Zahlung und Gesamtzins, also die Zahl, die tatsächlich darüber entscheidet, ob ein Kredit bezahlbar ist."]},{"b":"Zu Rabatten: Ein Rabatt von 20 %, gefolgt von einem weiteren Rabatt von 20 %, bedeutet nicht 40 %, sondern 36 %. Aufeinanderfolgende Prozentsätze werden auf der reduzierten Basis zusammengesetzt. Jeder Taschenrechner in dieser Liste wird dies in etwa zwei Sekunden bestätigen und es ist die nützlichste arithmetische Tatsache in diesem Artikel."},{"p":"Eine besondere Erwähnung verdient der Kreditrechner. Entscheidend ist nicht die monatliche Rate, sondern der Gesamtzins, der über die Laufzeit des Kredits gezahlt wird, denn das sind die tatsächlichen Kosten der Kreditaufnahme. Zwei Kredite mit identischen monatlichen Raten und unterschiedlichen Laufzeiten können sich im Gesamtzins um mehrere Zehntausend unterscheiden."},{"h":"Termine und Countdowns"},{"p":"Bei der Datumsarithmetik machen die meisten Leute stillschweigend einen Fehler, da menschliche Monate unterschiedlich lang sind und die Antwort unterschiedlich ist, je nachdem, ob Sie „Kalendermonate“ oder „30 Tage“ meinen."},{"l":["[[Datumsdifferenz|Datumsdifferenzrechner]] – Tage (und Gesamtmonate, Jahre) zwischen zwei Daten.","[[days-until|Days Until Calculator]] – ein Countdown bis zu einem bestimmten Datum, wobei die Anzahl der Arbeitstage normalerweise dem entspricht, was die Leute tatsächlich wollen.","[[age-calculator|Age Calculator]] – genaues Alter in Jahren und Tagen, plus der nächste Geburtstag.","[[timestamp-converter|Timestamp Converter]] – ein Unix-Zeitstempel in ein echtes Datum, das wichtig ist, wenn Sie Protokolle, Datenbanken oder API-Antworten berühren."]},{"p":"Der Unterschied, der die Leute stutzig macht: Die Anzahl der Tage zwischen dem 1. März und dem 1. April beträgt 31, aber die Anzahl der *Monate* ist eins. Wenn Sie eine Kündigungsfrist oder eine Abonnementlaufzeit berechnen, geben Sie schriftlich an, welche Einheit Sie meinen."},{"h":"Gesundheitszahlen, ehrlich"},{"l":["[[bmi-calculator|BMI-Rechner]] – Body-Mass-Index mit den Standardkategorien und den folgenden Einschränkungen."]},{"p":"Der BMI ist eine Screening-Statistik auf Bevölkerungsebene. Es sagt nichts über Muskelmasse, Körperzusammensetzung oder die Gesundheit einer Person aus und ist ein schlechter Indikator für die Fitness von Sportlern, älteren Erwachsenen und über verschiedene ethnische Gruppen hinweg. Verwenden Sie es als einen Datenpunkt unter mehreren oder als Möglichkeit, eine Änderung im Laufe der Zeit zu verfolgen – nicht als Urteil. Wenn Sie Entscheidungen treffen, die sich auf Ihre Gesundheit auswirken, ist ein Arzt das richtige Werkzeug, nicht ein Browser-Tab."},{"h":"Einheitenumrechnung: die Alltäglichen"},{"p":"Die Einheitenumrechnung wird in zwei Arten unterteilt: Umrechnungen, die Sie genau richtig machen müssen, und Umrechnungen, die Sie grob benötigen. Diese Tools beherrschen beides, und die Arbeit besteht darin, sich zu merken, welches welches ist."},{"l":["[[length-converter|Length Converter]] – metrisch in imperial und zurück: Millimeter, Zentimeter, Meter, Kilometer, Zoll, Fuß, Yards, Meilen.","[[Gewichtsumrechner|Gewichtsumrechner]] – Gramm, Kilogramm, Unzen, Pfund, Tonnen. Diejenige, die vor einem Rezept oder einem Versandetikett überprüft werden muss.","[[temperaturkonverter|Temperaturkonverter]] – Celsius, Fahrenheit, Kelvin. Weil -10 °C nicht 14 °F sind und die Formel keine Multiplikation ist.","[[speed-converter|Speed ​​Converter]] – km/h, mph, m/s, Knoten. Nützlich für eine ausländische Geschwindigkeitsbegrenzung oder eine technische Spezifikation.","[[area-converter|Area Converter]] – Quadratmeter, Quadratfuß, Acres, Hektar. Dies ist der Punkt, den Menschen beim Kauf oder der Miete einer Immobilie schlecht einschätzen.","[[Volumenkonverter|Volumenkonverter]] – Liter, Milliliter, Gallonen, Tassen, Kubikmeter.","[[time-converter|Time Converter]] – Sekunden, Minuten, Stunden, Tage, Wochen."]},{"b":"Zwei Umrechnungsfallen, die man kennen sollte: die Datenspeicherfalle oben (Vermarkter verkaufen 10^3, Betriebssysteme melden 2^10) und der Kraftstoffverbrauch – ein Auto, das mit 40 mpg (imperial) angegeben wird, liegt näher bei 33 mpg (US) als 40, weil die britische Gallone größer ist. Wenn Sie den zweiten Fehler falsch machen, sieht ein Mietwagen unrealistisch effizient aus."},{"h":"Die beiden werden Sie voraussichtlich nicht brauchen"},{"l":["[[random-number|Random Number Generator]] – Zieht innerhalb eines Bereichs, für eine Verlosung, eine Klammer oder eine schnelle A/B-Aufteilung. Nützlich, gerade weil es den Verdacht beseitigt, dass Sie es manipuliert haben.","[[Würfelroller|Würfelroller]] – jeder Würfel vom Münzwurf bis zum zwanzigseitigen Würfel, für ein Brettspiel oder eine Tabletop-Sitzung, bei der der echte Würfel zum letzten Mal vom Tisch gefallen ist."]},{"h":"Einen Taschenrechner richtig nutzen"},{"p":"Ein Taschenrechner hilft nur, wenn man weiß, um welche Zahl es sich handelt. Drei Gewohnheiten machen den Unterschied."},{"l":["**Zuerst runden, dann berechnen.** Wenn die genaue Zahl Ihre Entscheidung nicht ändert, verwenden Sie eine Eins-Runde. Prozentsätze runder Zahlen können im Kopf überprüft werden, wodurch Eingabefehler aufgedeckt werden.","**Überprüfen Sie die Größe.** Bevor Sie einem Ergebnis Glauben schenken, fragen Sie, ob es größer oder kleiner als die Eingabe sein sollte und um wie viel ungefähr. Die meisten Rechenfehler überleben jede Prüfung außer dieser.","**Fotografieren Sie die Eingaben, nicht die Ausgabe.** Wenn Sie die Berechnung später erneut ausführen, kommt es darauf an, zu wissen, was Sie angenommen haben, und nicht, was Sie daraus geschlossen haben."]},{"h":"Fragen, die Menschen tatsächlich stellen"},{"p":"**Werden meine Zahlen irgendwo gespeichert?** Nein. Die Berechnungen erfolgen in Ihrem Browser und es wird nichts übertragen oder gespeichert.\\n\\n**Funktionieren diese auf einem Telefon?** Ja, und die Taschenrechner sind für die einhändige Bedienung konzipiert.\\n\\n**Welchen Konvertierungsstandard verwenden Sie für die Datenspeicherung?** Standardmäßig Dezimal (1 KB = 1000 Bytes), da Speicher so verkauft wird. Betriebssysteme melden binär, weshalb ein Laufwerk scheinbar schrumpft – das Tool erklärt den Unterschied, anstatt sich stillschweigend für eine Seite zu entscheiden.\\n\\n**Kann ich diese auf meiner eigenen Website einbetten?** Nein. Setzen Sie stattdessen ein Lesezeichen für sie. Die Kosten dafür betragen Null und das Genauigkeitsproblem liegt bei Ihnen."},{"h":"Prozentsätze: die vier Fehler, auf die es ankommt"},{"p":"Fast jeder prozentuale Fehler, den ein Mensch im täglichen Leben macht, ist einer dieser vier Fehler. Sie zu benennen, macht sie vermeidbar."},{"l":["**Falsche Basis.** „Ein Anstieg um 10 %, dann ein Rückgang um 10 % lässt Sie dort zurück, wo Sie angefangen haben“ ist falsch, da beides für unterschiedliche Basen gilt. Zehn Prozent von 100 sind 10; zehn Prozent von 90 sind 9.","**Prozentsatz eines Prozentsatzes.** Durch das Stapeln zweier Rabatte werden diese multipliziert (0,8 × 0,8 = 0,64, also 36 % Rabatt), nicht addiert.","**Prozent vs. Prozentpunkte.** Ein Anstieg von 4 % auf 6 % ist um 2 Prozentpunkte gestiegen, relativ gesehen jedoch um 50 %. Politik und Medizin sind voll von dieser Verwirrung, und sie ist nicht immer zufällig.","**Zu frühes Runden.** Das Runden eines Zwischenschritts vor der Anwendung eines Prozentsatzes verschlimmert den Fehler. Behalten Sie bis zur endgültigen Zahl Ihre volle Präzision bei und erledigen Sie den letzten Schritt auf einem Taschenrechner und nicht im Kopf."]},{"p":"Wenn Sie nur eine Angewohnheit aus diesem ganzen Abschnitt übernehmen, nehmen Sie diese: Bevor Sie jemandem einen Prozentsatz nennen, wiederholen Sie, um welchen Prozentsatz es sich handelt. Die Hälfte der Argumente, die Sie jemals über eine Zahl haben werden, sind tatsächlich Argumente über den Nenner."},{"h":"Wissen, wann man mit dem Rechnen aufhören muss"},{"p":"Es gibt einen Punkt, an dem Präzision nicht mehr nützlich ist. Sinnvoll ist eine monatliche Zahlung mit zwei Nachkommastellen. Eine Prognose der Gesamtkosten auf acht Dezimalstellen ist eine Möglichkeit, die eigentliche Entscheidung zu vermeiden, nämlich ob der Kredit zu dem passt, was Sie sich ohne Stress leisten können.\\n\\nDer nützliche Test ist die Sensitivitätsfrage: Ändert sich die Entscheidung, wenn sich diese Eingabe um 10 % verschiebt? Wenn nicht, hören Sie auf, es zu verfeinern, und verwenden Sie die zusätzliche Zeit für die Variable, die die Antwort verschiebt – normalerweise eher die Laufzeit als den Preis oder den Listenpreis statt des Rabatts."},{"p":"Und eine Grenze, die es klar zu sagen gilt: Bei diesen Taschenrechnern handelt es sich um Arithmetik, nicht um Ratschläge. Ein Sparziel, ein Ruhestandstermin und ein Schuldentilgungsplan sind alles Entscheidungen über Risiko, Verhalten und Zeit, und ein Browser-Tab kann keine dieser Entscheidungen abwägen. Was die Zahlen bedeuten, kann es Ihnen erst dann sagen, wenn Sie entschieden haben, was Sie annehmen. Dieser Unterschied macht den Unterschied zwischen der Nützlichkeit und der Verantwortung eines Taschenrechners aus."},{"h":"Die einzeilige Version"},{"p":"Fügen Sie den Geld- und Datumsrechnern die richtigen Lesezeichen hinzu, behandeln Sie den BMI als ein Signal und nicht als Urteil, denken Sie daran, dass sich gestapelte Prozentsätze multiplizieren, und überprüfen Sie eine Einheitenumrechnung, wenn eine Zahl in etwas Vertragliches einfließt. Das deckt fast alles ab."}]},"image-and-design-tools":{"title":"14 kostenlose Bild- und Design-Tools, die in Ihrem Browser ausgeführt werden","description":"Komprimieren Sie Bilder, ändern Sie ihre Größe und bereiten Sie sie vor. Erstellen Sie CSS-Effekte, Paletten, Kontrastprüfungen und Favoriten, ohne Photoshop oder eine Design-Suite zu installieren.","category":"Design-Tools","blocks":[{"p":"Bei der Bildbearbeitung gibt es ein spezifisches Problem: Die Arbeit ist meist klein und die angebotenen Werkzeuge riesig. Sie müssen 400 KB von einem Heldenbild einsparen, einen Hex-Wert erhalten, den Ihr Designer erwähnt hat, oder ein Favicon generieren, das noch niemand erstellt hat. Dafür ist kein Abonnement erforderlich.\\n\\nDie folgenden vierzehn Tools behandeln das Vorbereiten von Bildern, das Arbeiten mit Farben, das Erzeugen von CSS-Effekten und die kleinen Produktionsressourcen, die durch das Raster fallen. Alle laufen lokal, was für Bilder wichtiger ist als für Texte: Das Foto, das Sie gerade komprimiert haben, ist oft ein Foto, das Sie noch nicht veröffentlicht haben."},{"h":"Aufbereitung von Bildern für das Web"},{"p":"Bei den meisten Bildproblemen handelt es sich in Wirklichkeit um Gewichtsprobleme. Eine Seite, die sich langsam anfühlt, enthält normalerweise Bilder, die größer als ihre Anzeigegröße sind, im falschen Format und in einer Qualitätseinstellung, die niemand jemals in Frage gestellt hat."},{"l":["[[image-compressor|Image Compressor]] – Reduzieren Sie die Dateigröße, während das Bild optisch intakt bleibt. Führen Sie es aus, bevor Sie etwas in ein Formular mit einer Größenbeschränkung hochladen.","[[image-resizer|Image Resizer]] – Legen Sie die tatsächlichen Pixelabmessungen fest, die Sie benötigen. Das ist der größere Gewinn: Ein 4000-Pixel-Bild, das mit 800 Pixel angezeigt wird, enthält das Fünffache der benötigten Daten.","[[image-to-base64|Image to Base64]] – Konvertieren Sie ein kleines Bild in einen Daten-URI zum Inlining in CSS, HTML oder einer E-Mail-Vorlage."]},{"b":"Die Reihenfolge ist wichtig. Zuerst die Größe ändern, dann komprimieren. Das Komprimieren eines 4000-Pixel-Bildes erzeugt eine viel schwerere Datei als die Größenänderung auf 800 Pixel und das anschließende Komprimieren in derselben Qualität, da Komprimierer ihre Mühe auf Pixel verwenden, die ohnehin weggeworfen würden."},{"p":"Wie stark sollte man komprimieren? Die ehrliche Antwort lautet: Bis es falsch aussieht, dann einen Schritt zurücktreten. Bei einem fotografischen Heldenbild ist die Qualität bei 70 bis 80 Prozent in der Regel nicht vom Original bei normaler Betrachtungsgröße zu unterscheiden. Verwenden Sie für ein Logo, einen Screenshot oder alles mit flachen Farben und harten Kanten PNG und komprimieren Sie stärker – diese gewinnen mehr und verlieren weniger."},{"p":"Eine praktische Faustregel: Alles unter 200 KB ist für ein Heldenbild in Ordnung, unter 80 KB für ein Miniaturbild, und wenn Sie nicht unter 300 KB kommen, liegt wahrscheinlich eher ein Dimensionsproblem als ein Qualitätsproblem vor."},{"h":"Base64: Wenn Inlining der richtige Aufruf ist"},{"p":"Durch die Konvertierung eines Bildes in einen Base64-Daten-URI wird eine HTTP-Anfrage entfernt, was wie ein reiner Gewinn klingt. Normalerweise ist das nicht der Fall. Der codierte String ist etwa ein Drittel größer als die Binärdatei, kann nicht separat zwischengespeichert werden und bläht Ihr CSS oder HTML auf.\\n\\nInline nur, wenn das Bild klein ist – unter ein paar Kilobyte –, einmal verwendet wird und kritisch ist. Ein kleines Symbol in einer einzelnen E-Mail-Vorlage ist der klassische Fall. Stellen Sie alles, was seitenübergreifend wiederholt wird oder größer als ein paar Kilobyte ist, als Datei bereit und lassen Sie es vom Browser zwischenspeichern."},{"h":"Wasserzeichen: Was ist ehrlich gesagt entfernbar?"},{"l":[]},{"p":"Machen Sie sich klar, was dies bewirkt. Es entfernt oder verdeckt die sichtbare Markierung. Die zugrunde liegenden Pixel können nicht rekonstruiert werden – übermalte Informationen sind verloren und kein Filter erfindet sie wieder. Die Ergebnisse reichen von unsichtbar, wenn die Markierung auf einem einfachen Hintergrund sitzt, bis hin zu einem deutlichen Verschmieren, wenn sie sich über Details befindet.\\n\\nNoch eine Sache, die es klar und deutlich zu sagen gilt: Das Entfernen des Wasserzeichens einer anderen Person und die Veröffentlichung des Ergebnisses stellt in den meisten Rechtsordnungen ein Urheberrechtsproblem und eine Lizenzverletzung dar, unabhängig davon, ob Sie dabei erwischt werden. Das Entfernen von Markierungen aus Ihren eigenen Bildern oder aus von Ihnen lizenzierten Bildern ist der Fall, für den dieses Tool gedacht ist."},{"h":"Farbe: Konvertieren, Prüfen, Auswählen"},{"p":"Durch die Farbe werden kleine Fehler deutlich sichtbar. Ein Kontrastverhältnis, das nicht zugänglich ist, ein Hex-Wert, der eigentlich ein HSL-Triple ist, eine Palette, die auf Ihrem Monitor kohärent und auf einem Projektor matschig aussieht."},{"l":["[[color-converter|Color Converter]] – Wechseln Sie zwischen HEX, RGB und HSL. Es lohnt sich, HSL lesen zu lernen, denn Farbton 210, Sättigung 40 Prozent, Helligkeit 50 Prozent lassen sich viel einfacher per Hand anpassen als ein Hexadezimalwert.","[[contrast-checker|Contrast Checker]] – Testen Sie Text vor seinem Hintergrund anhand von WCAG-Schwellenwerten. Dies ist das nützlichste Tool in diesem Artikel, da es eher ein echtes Compliance-Problem als ein Geschmacksproblem aufdeckt.","[[color-palette|Farbpalettengenerator]] – Generieren Sie einen kohärenten Satz, wenn Sie von einer Markenfarbe ausgehen und den Rest der Skala benötigen."]},{"b":"Im Gegensatz dazu: WCAG AA verlangt 4,5 zu 1 für normalen Fließtext und 3 zu 1 für großen Text. Wenn Sie für einen Knopf zwischen zwei Markenfarben wählen, ist die zugängliche Farbe normalerweise nicht die, die dem Designer gefällt. Zuerst prüfen, dann mit Daten argumentieren."},{"p":"Eine Einschränkung bei Farbtools: Sie gehen alle davon aus, dass Ihr Monitor kalibriert ist und dass die Person, die Ihre Seite betrachtet, funktionierende Augen hat. Keine der beiden Annahmen ist sicher. Das ist ein Grund, kontrastgeprüfte Kombinationen den subjektiven vorzuziehen."},{"h":"CSS-Effekte, ohne ein Design-Tool zu öffnen"},{"p":"Einen Farbverlauf oder einen geschichteten Schatten von Hand zu schreiben ist eine wirklich unangenehme Aufgabe. Die Syntax ist fummelig, man sieht nicht, was man erzeugt, und der Unterschied zwischen einem guten und einem schlechten Schatten beträgt ein paar Pixel Unschärfe."},{"l":["[[gradient-generator|CSS Gradient Generator]] – Erstellen Sie lineare und radiale Verläufe und kopieren Sie das CSS direkt.","[[Box-Shadow-Generator|Box-Shadow-Generator]] – mehrere Schatten überlagern, was eine subtile Erhebung von einem starken Tropfen unterscheidet.","[[border-radius-generator|Randradius-Generator]] – erhalten Sie die asymmetrischen Radien, die eine Form gewollt aussehen lassen.","[[text-shadow-generator|Text Shadow Generator]] – sparsam nützlich. Die meisten Textschatten sind zu stark; Auf diese Weise können Sie den Versatz und die Unschärfe anpassen, bis sie verschwindet."]},{"p":"Der Trick bei allen vieren ist Zurückhaltung. Zwei Schatten – ein enger dunkler und ein breiter, weicher – lesen sich als physische Erhebung. One Shadow liest sich wie eine Website von vor fünfzehn Jahren. Generieren, kopieren und dann löschen, bis Sie nicht mehr erkennen können, dass es vorhanden ist."},{"h":"Die Produktionsanlagen, die jeder vergisst"},{"l":["[[Favicon-Generator|Favicon-Generator]] – Erstellt den kleinen Icon-Satz, den eine Website tatsächlich benötigt. Dies steht auf der Liste, da Favicons am wahrscheinlichsten völlig fehlen und ein fehlendes Symbol ein allgemeines Browserseitensymbol anzeigt, das eine fertige Website unvollendet aussehen lässt.","[[emoji-picker|Emoji-Picker]] – Durchsuchen, suchen und kopieren Sie Emojis, ohne einen Betriebssystem-Picker durchsuchen zu müssen. Wirklich nützlich, wenn Sie Texte schreiben, die ein bestimmtes Symbol benötigen."]},{"h":"Ein praktisches Beispiel: Versand eines Heldenabschnitts"},{"p":"Hier leistet der gesamte Cluster einen echten Job. Eine Seite braucht einen Helden mit einem Hintergrundbild, einer Überschrift und einem Button, und noch ist nichts davon erstellt."},{"l":["**1. Reservieren Sie den Platz.** Geben Sie dem Bildfeld im Layout eine feste Höhe, damit die Seite vom ersten Rendern an die richtige Form hat, anstatt zu springen, wenn das echte Bild landet.","**2. Größe ändern und komprimieren.** Wenn das echte Foto eintrifft, führen Sie es durch den [[image-resizer|Image Resizer]] mit einer Breite von 1600 Pixeln und dann durch den [[image-compressor|Image Compressor]] mit 75 Prozent. Das ist eine Datei, die Sie versenden können.","**3. Überprüfen Sie den Text auf Kontrast.** Eine Überschrift über einem Foto ist der klassische Kontrastfehler. Verwenden Sie den [[contrast-checker|Contrast Checker]], um entweder eine dunkle Überlagerungsstärke oder eine helle Textfarbe auszuwählen, die AA erfüllt.","**4. Erstellen Sie die Schaltfläche.** Der [[box-shadow-generator|Box Shadow Generator]] gibt die Höhe an, und der [[color-converter|Color Converter]] bringt die Markenfarbe in das Format, das das CSS benötigt.","**5. Versenden.** Fügen Sie ein Favicon aus dem [[Favicon-Generator|Favicon-Generator]] hinzu, damit die Registerkarte nicht verlassen aussieht, und der Abschnitt ist fertig."]},{"p":"Fünf Tools, keine Design-Suite und jede Ausgabe ist ein Wert, den Sie direkt in den Code einfügen können."},{"h":"Häufig gestellte Fragen"},{"p":"**Werden meine Bilder irgendwo hochgeladen?** Nein. Komprimierung, Größenänderung und Base64-Konvertierung erfolgen alle in Ihrem Browser, weshalb es keine Dateigrößenbeschränkung und keine Upload-Warteschlange gibt.\\n\\n**Führt das Komprimieren eines Bildes zu einem Qualitätsverlust?** Per Definition immer. Die Frage ist, ob es sichtbar ist. Bei 70 bis 80 Prozent Qualität und korrekten Maßen ist dies meist nicht der Fall.\\n\\n**Warum sieht mein in der Größe geändertes Bild immer noch groß aus?** In neun von zehn Fällen haben Sie es vor der Größenänderung komprimiert, oder Sie speichern es als PNG, obwohl ein Foto besser als JPEG ist.\\n\\n**Kann ich diese für Kundenarbeiten verwenden?** Ja, ohne Namensnennung und ohne kommerzielle Einschränkung.\\n\\n**Funktionieren sie auf einem Telefon?** Ja, allerdings hängt die Größenänderung und Komprimierung großer Fotos auf einem Telefon vom Speicher Ihres Geräts und nicht von einem Server ab."},{"h":"Die einzeilige Version"},{"p":"Ändern Sie die Größe, bevor Sie komprimieren, überprüfen Sie den Kontrast, bevor Sie über die Farbe streiten, halten Sie die Schatten dezent und vergessen Sie nie das Favicon. Das ist sowieso das meiste, was eine Design-Suite für Sie erledigt hat."}]},"math-tools-for-real-numbers":{"title":"6 kostenlose Mathe-Tools für Zahlen, die sich nicht verhalten","description":"Wissenschaftliche Notation, Dezimalzahlen in Brüche umrechnen, Primzahlprüfung, Fakultäten und GCF/LCM – kostenlose Browser-Tools für die Zahlenarbeit, bei der man leicht Fehler machen kann.","category":"Mathe-Tools","blocks":[{"p":"Die Mathematik, die Sie tatsächlich am Computer benötigen, ist nicht die Mathematik, die Sie geprüft haben. Es geht darum: Hat diese Zahl das vom System erwartete Format, ist dieser Bruch vereinfacht, wie schnell wächst er und warum stimmen der Rechner und die Tabelle nicht überein.\\n\\nDiese sechs Tools decken dieses Gebiet ab. Sie laufen lokal, was für die Arithmetik einen besonderen Vorteil bedeutet, der erwähnt werden sollte: Die von Ihnen eingegebene Zahl wird nirgendwohin gesendet, sodass Sie eine Berechnung, die ein Gehalt, einen Kontostand oder eine Kundenzahl betrifft, bedenkenlos überprüfen können."},{"h":"Zahlen in eine Form bringen, die eine Maschine akzeptiert"},{"p":"Computer speichern Dezimalbrüche als Binärbrüche. 0,1 ist im Binärformat nicht genau darstellbar – der nächste Wert mit doppelter Genauigkeit ist 0,1000000000000000055511151231257827. Addieren Sie 0,1 + 0,2 und Sie erhalten 0,30000000000000004, was standardmäßig als 0,3 ausgegeben wird und eine Gleichheitsprüfung stillschweigend unterbricht."},{"l":["[[scientific-notation|Scientific Notation Converter]] – Wechseln Sie zwischen Standard- und wissenschaftlicher Form, in der die meisten Protokolle, Tabellenkalkulationen und APIs tatsächlich große und kleine Zahlen speichern.","[[decimal-fraction|Decimal to Fraction]] – wandelt eine Dezimalzahl in einen exakten Bruch um. Dies ist die Lösung für das obige Problem: 0,1 + 0,2 in der Arithmetik mit exakten Brüchen ist 3/10, keine Näherung."]},{"b":"Wenn Sie jemals eine Summe gesehen haben, die um 0,0000000000000004 falsch ist, dann ist dies der Grund. Im Finanzcode lautet die Standardlösung, in ganzzahligen Cent oder in einer Dezimalbibliothek und niemals in Gleitkommazahlen zu arbeiten. Wenn Sie schon einmal gesehen haben, dass eine Tabellenkalkulation nur um den Bruchteil eines Cents mit einem Skript übereinstimmt, handelt es sich um denselben Fehler mit einer anderen Rolle."},{"p":"Es lohnt sich, die wissenschaftliche Notation fließend zu beherrschen, denn sie macht den Unterschied zwischen dem Lesen einer Protokollzeile und dem Hinsehen darauf aus. 6,022e23, 1,6e-19 und 3e8 sind Avogadros Zahl, die Elementarladung und die Lichtgeschwindigkeit. Wenn diese eher wie Rauschen als wie Zahlen aussehen, lässt sich das Problem durch die Konvertierung einiger weniger mit dem Tool dauerhaft beheben."},{"h":"Primzahlen und warum es irgendjemanden interessiert"},{"l":["[[prime-checker|Prime Number Checker]] – Testen Sie, ob eine Zahl eine Primzahl ist, und sehen Sie sich ihre Faktorisierung an, wenn dies nicht der Fall ist.","[[gcf-calculator|GCF LCM Calculator]] – größter gemeinsamer Faktor und kleinstes gemeinsames Vielfaches."]},{"p":"Primzahlen sind keine Schulaufgabe. Die Sicherheit jeder HTTPS-Verbindung, die Sie herstellen, hängt von der Tatsache ab, dass die Multiplikation zweier großer Primzahlen einfach ist und das Zurückrechnen des Ergebnisses schwierig ist. Diese Asymmetrie ist die gesamte Grundlage von RSA.\\n\\nFür alltägliche Zwecke geht es bei der Primzahlprüfung hauptsächlich um Brüche. Einen Bruch zu vereinfachen bedeutet, den oberen und unteren Teil durch ihren größten gemeinsamen Teiler zu dividieren, und das lässt sich ohne Faktorisierung nicht finden. Deshalb gehören diese beiden Tools zusammen: Faktoren prüfen, dann GCF und LCM in einem Schritt ermitteln."},{"p":"Die LCM-Hälfte vergessen die Leute und sie löst Planungsprobleme: Zwei Ereignisse, die sich alle 18 Tage und alle 12 Tage wiederholen, fallen alle 36 Tage zusammen. Gleiche Arithmetik, andere Anwendung."},{"h":"Fakultäten und die Geschwindigkeit, mit der sie explodieren"},{"l":["[[Fakultätsrechner|Fakultätsrechner]] – n! für Werte, bei denen die Antwort noch aussagekräftig ist."]},{"p":"Fakultäten wachsen schneller als fast alles, was Sie an einem Schreibtisch treffen. 10! beträgt etwa 3,6 Millionen. 20! beträgt etwa 2,4 Trillionen – bei weitem mehr als die Anzahl der Sandkörner auf der Erde. 52!, die Anzahl der Möglichkeiten, ein Kartenspiel zu mischen, beträgt ungefähr 8, gefolgt von 67 Ziffern.\\n\\nDie praktische Konsequenz ist, dass ein Programm, das alle Permutationen auflistet, bei 5 Elementen in Ordnung ist, bei 8 tolerierbar ist und bei 12 dauerhaft hängen bleibt. Wenn eine Aufgabe das Gefühl hat, dass sie niemals beendet wird und Sie Permutationen in einer Schleife durchlaufen, ist dies mit ziemlicher Sicherheit der Grund. Es ist auch das Argument gegen die meisten Brute-Force-Ansätze, das eher als Arithmetik denn als Meinung formuliert wird."},{"h":"Römische Ziffern und das Seltsame daran"},{"l":["[[roman-numerals|Römische Ziffernkonverter]] – Konvertieren in und aus römischen Ziffern."]},{"p":"Es lohnt sich, römische Ziffern zu verstehen und nicht nur umzuwandeln, da das System etwas über die Positionsschreibweise verrät. Es gibt keine Null und keinen Stellenwert: XI bedeutet elf, egal ob es elf Stöcke oder elftausend darstellt. Aus diesem Grund ist das Rechnen mit römischen Zahlen wirklich schwierig und das System überlebte Jahrhunderte lang hauptsächlich zum Zählen und Datieren und nicht zum Rechnen.\\n\\nDie Subtraktionsregel ist der Teil, den Menschen falsch machen. IV ist vier, nicht VI; IX ist neun. Uhren sind eine berühmte Ausnahme – Big Ben verwendet IIII anstelle von IV, aus Gründen, über die Historiker immer noch streiten. Konvertieren statt Ableiten ist in jedem Fall die richtige Entscheidung."},{"h":"Ein praktisches Beispiel: Überprüfen eines Bruchs von Hand"},{"p":"Ein Rezept benötigt 0,375 Tassen und eine Skala, die in Gramm anzeigt, ein Bericht gibt ein Verhältnis von 0,625 an und beide sehen aus wie Zahlen, die jemand in Eile getippt hat."},{"l":["**1. Finden Sie den genauen Bruch.** Führen Sie 0,375 durch das Tool [[decimal-fraction|Decimal to Fraction]] aus: 3/8. Lauf 0,625: 5/8. Weder brauchte noch eine Rechengewohnheit, die Sie nicht haben.","**2. Vereinfachen Sie das Verhältnis.** Um 3/8 gegenüber 5/8 auszudrücken, benötigen Sie den GCF von 3 und 5. Der [[gcf-calculator|GCF LCM Calculator]] ergibt 1, also ist das Verhältnis 3:5 und bereits am einfachsten.","**3. Überprüfen Sie die Fakultätsbehauptung.** Wenn Ihnen jemand sagt, dass eine Warteschlange mit 9 Bestellungen 362.880 Vereinbarungen hat, bestätigt der [[Fakultätsrechner|Fakultätsrechner]] 9! ist genau das. Jetzt wissen Sie, ob die Bauzeitschätzung plausibel war.","**4. Normalisieren Sie alles, was groß ist.** Ein Server, der 1,5e9 Nanosekunden meldet, beträgt laut [[scientific-notation|Scientific Notation Converter]] 1,5 Sekunden – was den Unterschied zwischen einem Latenzproblem und einem Rundungsartefakt darstellt."]},{"h":"Was diese Tools bewusst nicht tun"},{"p":"Sie zeigen nicht, dass sie arbeiten, und sie unterrichten nicht. Wenn Sie verstehen möchten, warum eine Formel wahr ist, ist ein Taschenrechner das falsche Instrument – ​​er gibt die Antwort ohne Angabe des Grundes, was dazu führt, dass Menschen am Ende rechnen können, aber nicht in der Lage sind, vernünftig zu argumentieren.\\n\\nSie erreichen auch keine willkürliche Präzision. Fakultäten und große Faktorisierungen verlieren an Genauigkeit, wenn die Antwort noch nützlich ist und ein Browser-Tab kein Computeralgebrasystem ist. Für alles, wo es wirklich auf Korrektheit ankommt – Technik, Finanzen, Kryptographie – verwenden Sie eine richtige Bibliothek mit exakter Arithmetik und keine Webseite."},{"h":"Überprüfen Sie Ihre eigene Arithmetik"},{"p":"Die wertvollste mathematische Gewohnheit ist nicht die Geschwindigkeit, sondern das Schätzen. Bevor Sie einem Ergebnis glauben, fragen Sie, ob es in der richtigen Größenordnung liegt: größer oder kleiner als die Eingabe und um ungefähr den Betrag. Die meisten Rechenfehler überleben jede zweite Prüfung außer dieser.\\n\\nDurch vorheriges Runden ist die Schätzung kostenlos. Runden Sie 0,375 auf 0,4, runden Sie 5/8 auf 0,6, und das Verhältnis beträgt offensichtlich etwa 2:3 – nahe genug an 3:5, um den Bruch zu bestätigen, den Sie genau berechnet haben. Wenn die genaue Antwort und die Schätzung nicht übereinstimmen, liegt eher ein Eingabefehler als ein Rundungsproblem vor, und zwar innerhalb von Sekunden.\\n\\nAus diesem Grund ist ein Taschenrechner auch kein Ersatz dafür, darüber nachzudenken, was Sie von ihm verlangt haben. Ein Tool berechnet die falsche Menge perfekt, und die einzige Verteidigung besteht darin, zu wissen, wie sich die Antwort anfühlen sollte."},{"h":"Häufig gestellte Fragen"},{"p":"**Wird meine Eingabe irgendwohin gesendet?** Nein. Alle diese werden lokal in Ihrem Browser ausgeführt.\\n\\n**Warum ist 0,1 plus 0,2 nicht gleich 0,3?** Weil weder 0,1 noch 0,2 im binären Gleitkomma exakt darstellbar sind. Die Summe beträgt 0,30000000000000004, was dem Doppelten von 0,3 am nächsten kommt.\\n\\n**Wie groß kann eine Fakultät sein?** Bis zu 170, bevor der Bereich eines Doubles überschritten wird. Danach wird die Antwort in wissenschaftlicher Notation angezeigt und ist dann nicht mehr aussagekräftig.\\n\\n**Kann ich die Ausgabe im Code verwenden?** Ja. Verwenden Sie insbesondere für die Dezimal-Bruch-Ergebnisse die Ganzzahlarithmetik für Zähler und Nenner, anstatt sie zurück in eine Dezimalzahl umzuwandeln."},{"h":"Die einzeilige Version"},{"p":"Verwenden Sie exakte Brüche, wenn es um Geld geht. Denken Sie daran, dass Fakultäten schneller explodieren als erwartet, und dass die Primfaktorzerlegung sowohl eine Sicherheitsgrundlage als auch ein Trick zur Vereinfachung von Brüchen ist."}]},"everyday-utility-tools":{"title":"13 kostenlose Alltagsdienstprogramme: Passwörter, QR-Codes, Timer und Textkodierung","description":"Generieren Sie Passwörter, erstellen Sie QR-Codes, lassen Sie Timer und Uhren laufen und dekodieren Sie binäre, hexadezimale und verschlüsselte Texte – alles mit kostenlosen Browser-Tools, die nichts hochladen.","category":"Hilfsprogramme","blocks":[{"p":"Diese letzte Gruppe ist die Müllschublade. Passwörter, QR-Codes, eine Stoppuhr, eine Weltzeituhr, ein Münzwurf und vier Tools, die Text in andere Darstellungen seiner selbst umwandeln. Einzeln trivial, gemeinsam das Zeug, das man in schwierigen Momenten braucht.\\n\\nDie durchgehende Linie besteht darin, dass alle dreizehn lokal verlaufen. Für einen Passwortgenerator ist das keine nette Sache – es ist der einzige Grund, warum man dem Tool überhaupt vertrauen kann."},{"h":"Passwörter: der Teil, der wirklich zählt"},{"l":["[[password-generator|Password Generator]] – generiert sichere zufällige Passwörter beliebiger Länge und Zeichensatz.","[[password-strength|Password Strength Checker]] – Schätzen Sie lokal, wie resistent ein Passwort gegen Erraten ist."]},{"b":"Die wichtigste Tatsache zur Passwortstärke: **Länge ist wichtiger als Komplexität, und Wiederverwendung ist gefährlicher als beides.** Ein 16-stelliges Passwort aus nicht zusammenhängenden Wörtern ist sicherer und viel besser schreibbar als ein 10-stelliges Durcheinander von Symbolen. In der Zwischenzeit löscht ein wiederverwendetes Passwort, das bei einer Sicherheitsverletzung auftaucht, alle Konten, die es berührt, auf einmal. Die gesamte Aufgabe besteht darin, für jede Site ein eindeutiges langes Passwort zu generieren."},{"p":"Es spielt auch eine Rolle, wie die Stärke geschätzt wird. Die meisten Prüfer schätzen die Größe des Suchraums ein, was ein vernünftiger Indikator, aber nicht die Wahrheit ist: „CorrectHorseBatteryStaple“ schneidet bei der Entropie gut ab, während „P@ssw0rd1!“ bei der Zeichenvielfalt gut abschneidet, in der Praxis aber schlecht, weil es in jeder Cracking-Wortliste der Welt vorkommt.\\n\\nVerwenden Sie den Generator für alles, was Ihnen wichtig ist, und wenn Sie sich ein Passwort merken müssen, verwenden Sie eine Passphrase aus vier oder fünf nicht zusammenhängenden Wörtern. Das ist der spezielle Fall, in dem sich Einprägsamkeit und Stärke tatsächlich überschneiden."},{"h":"QR-Codes: Was man in sie einfügt"},{"l":["[[qr-code-generator|QR-Code-Generator]] – Generieren Sie einen QR-Code für eine URL, einen Text, WLAN-Details oder Kontaktinformationen."]},{"p":"QR-Codes gehören zu den Tools, bei denen die Ausgabequalität vollständig von einer Entscheidung abhängt: der Menge der eingegebenen Daten. Eine kurze URL wird in einen kleinen, leicht scannbaren Code kodiert. Ein Textabschnitt mit Satzzeichen wird bei kleinen Größen zu etwas Dichtem und Unzuverlässigem.\\n\\nZwei praktische Regeln. Scannen Sie zunächst immer den Code in der Größe, in der er tatsächlich gedruckt wird, probeweise ein, bevor Sie zweihundert davon drucken. Zweitens verhalten sich WLAN- und einfache URL-Codes auf verschiedenen Telefonen unterschiedlich. Wenn ein Code an eine gemischte Zielgruppe gerichtet ist, bevorzugen Sie eine einfache URL gegenüber einer Zielseite, die dann weiterleitet, da sie überall funktioniert und Sie ändern können, wohin sie verweist."},{"h":"Zeit: Timer, Uhren und die Falle in Zeitzonen"},{"l":["[[Stoppuhr|Online-Stoppuhr]] – eine einfache Stoppuhr, nützlich, wenn sich Ihr Telefon im anderen Raum befindet.","[[pomodoro-timer|Pomodoro Timer]] – 25-minütige Fokusblöcke mit Pausen, für Leute, die finden, dass diese Struktur funktioniert.","[[world-clock|World Clock]] – aktuelle Zeit in mehreren Städten gleichzeitig."]},{"p":"Die Weltzeituhr verdient ihren Platz aus einem bestimmten Grund: der Sommerzeit. Bei der Hälfte der Planungsfehler auf der Welt handelt es sich nicht um Rechenfehler, sondern um einen Moment, in dem zwei Städte letzte Woche vier Stunden und diese Woche fünf Stunden voneinander entfernt waren und niemand nachgesehen hat.\\n\\nBevor Sie etwas über eine Zeitzone hinweg planen, stellen Sie beide Städte auf die Weltzeituhr und schauen Sie nach – berechnen Sie den Versatz nicht aus dem Speicher. Aus diesem Grund sollten Besprechungseinladungen auch eine Zeitzone und nicht nur eine bloße Uhrzeit enthalten."},{"p":"Zum Pomodoro-Timer: Die Technik funktioniert für eine bestimmte Art von Aufgabe – begrenzt, konzentriert, ununterbrochen. Es funktioniert nicht beim Debuggen, wo der richtige Schritt, wenn man feststeckt, darin besteht, wegzugehen und nicht einen weiteren 25-Minuten-Block zu starten. Benutzen Sie es, wenn es hilft."},{"h":"Zufälligkeit, ehrlich"},{"p":"Der [[random-number|Random Number Generator]] und der [[list-randomizer|List Randomizer]] decken die Fälle ab, die tatsächlich auftreten: eine Zahl aus einem Bereich auswählen und eine Liste in eine faire Reihenfolge bringen. Einen Satz zum Thema Fairness wert. Beide verwenden einen Pseudozufallsgenerator, der sich bei der Entscheidung, wer das Mittagessen bezahlt, nicht von einer echten Münze unterscheiden lässt. Für alles, was von Bedeutung ist – eine Verlosung mit Preisen, eine Zuteilung mit angehängtem Geld – benötigen Sie eine Quelle, die Sie überprüfen können, und ein Browser-Tab ist das nicht. Der Wert liegt hier darin, den Menschen zu entfernen, der bei Motivation schlecht auswählt."},{"h":"Die Kodierungsmüllschublade"},{"p":"Vier Werkzeuge, die Text zwischen Darstellungen verschieben. Bei keiner davon handelt es sich um eine Verschlüsselung, und die Unterscheidung ist erwähnenswert, da sie ständig verwechselt wird: Eine Verschlüsselung kann von jedem rückgängig gemacht werden und hat keinen Schlüssel. Für die Verschlüsselung ist ein Schlüssel erforderlich."},{"l":["[[binary-text|Binär zu Text]] – Konvertieren zwischen Text und seiner binären Darstellung.","[[hex-text|Hex zu Text]] – Konvertieren zwischen Text und Hex, der Darstellung, die Sie am häufigsten in Netzwerk-Tools und Debuggern sehen.","[[caesar-cipher|Caesar-Chiffre]] – Buchstaben um einen festen Betrag verschieben, die klassische Klassenzimmer-Chiffre.","[[rot13-encoder|ROT13 Encoder]] – Buchstaben um 13 drehen, ein Sonderfall, der seine eigene Umkehrung darstellt."]},{"p":"Diese sind für genau zwei Dinge nützlich. Erstens müssen Sie verstehen, wie Text zu Bytes wird. Dies ist das mentale Modell, das Sie benötigen, wenn etwas verstümmelt aussieht. Zweitens, eigentliches Debuggen: Wenn eine Nutzlast als Hexadezimalwert angezeigt wird, können Sie mit dem [[hex-text|Hex to Text]]-Konverter herausfinden, was darin steht.\\n\\nSie sind nicht dazu geeignet, etwas zu verbergen. ROT13 hat keinen Schlüssel – die Verschiebung ist öffentlich – und verbirgt daher nichts vor jemandem, der weiß, was ROT13 ist. Die Caesar-Chiffre hat 25 mögliche Verschiebungen, die ein Mensch in der ersten Minute durchbricht."},{"h":"Die beiden, die Dinge formatieren"},{"l":["[[phone-formatter|Phone Number Formatter]] – Telefonnummern in ein einheitliches Format normalisieren.","[[file-size-converter|File Size Converter]] – Konvertieren Sie zwischen KB, MB, GB und TB, mit Erklärung der dezimalen und binären Unterscheidung."]},{"p":"Der Dateigrößenkonverter hat eine wirklich wertvolle Ausgabe: Er sagt Ihnen, warum ein Laufwerk eine größere Zahl anzeigt, als Ihr Computer meldet. Anbieter verkaufen in Zehnerpotenzen, Betriebssysteme melden Zweierpotenzen und der Abstand beträgt bei jeder Skala etwa 7 Prozent. Das ist kein Fehler, es sind zwei Konventionen."},{"h":"Ein funktionierendes Beispiel: die verstümmelte API-Antwort"},{"p":"Die Validierung eines Webhooks schlägt fehl und die Nutzlast im Protokoll sieht aus wie „\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f“. Dies ist eine zweiundneunzigste Diagnose."},{"l":["**1. Konvertieren.** Fügen Sie „48656c6c6f“ in den [[hex-text|Hex to Text]]-Konverter ein – das Ergebnis ist „Hallo“. Es wurde nie verstümmelt, sondern nur verschlüsselt.","**2. Überprüfen Sie die Form.** Etwas Upstream codiert die Nutzdaten vor dem Signieren hexadezimal. Die Signatur wurde über den Originaltext berechnet und anhand des Hexadezimalwerts validiert, sodass der Vergleich fehlschlägt.","**3. Schließen Sie die andere Richtung aus.** Wenn das Protokoll lesbaren Text angezeigt hätte, wäre das Problem umgekehrt gewesen: das Signieren des verschlüsselten Formulars.","**4. Bestätigen Sie die Größenangabe.** Wenn dasselbe Protokoll eine Nutzlast von 1,2 MB meldet, legt der [[Dateigrößenkonverter|Dateigrößenkonverter]] fest, ob es sich um eine Dezimal- oder Binärdatei handelt, bevor jemand über ein Kontingent streitet."]},{"h":"Häufig gestellte Fragen"},{"p":"**Ist der Passwortgenerator sicher, wenn alles im Browser läuft?** Ja, und das sogar noch sicherer als ein serverbasierter: Das Passwort wird auf Ihrem Computer generiert und niemals übertragen, sodass nichts abgefangen, protokolliert oder gehackt werden kann. Der Nachteil besteht darin, dass Sie ein Passwort, das Sie nicht gespeichert haben, nicht wiederherstellen können.\\n\\n**Kann ich dem virtuellen Münzwurf vertrauen?** Für gelegentliche Entscheidungen, ja. Verwenden Sie für alles, was mit Geld oder Preisen verbunden ist, eine Quelle, die Sie prüfen können.\\n\\n**Sind die Chiffren sicher?** Nein. Keine davon. ROT13- und Caesar-Chiffren haben keinen geheimen Schlüssel und dienen dazu, die Codierung zu lehren, nicht um etwas zu schützen.\\n\\n**Funktionieren diese offline?** Sobald eine Seite geladen ist, ja – alles ist lokal.\\n\\n**Gibt es eine Begrenzung der Textlänge für die Konverter?** Nur der Speicher Ihres Geräts, da nichts irgendwohin gesendet wird."},{"h":"Die einzeilige Version"},{"p":"Lange, einzigartige Passwörter schlagen kurze, clevere Passwörter, ein QR-Code ist nur so gut wie die darin enthaltenen Daten, prüfen Sie Zeitzonenversätze, anstatt sie zu berechnen, und Codierung ist keine Verschlüsselung."}]}}')},8280,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"O kit de ferramentas do desenvolvedor: 24 ferramentas de navegador gratuitas que substituem aplicativos pagos","description":"Um guia prático para formatar, converter, codificar e depurar dados usando ferramentas gratuitas para desenvolvedores baseadas em navegador — sem instalações, sem contas; a maioria das ferramentas processa a entrada localmente.","category":"Ferramentas para desenvolvedores","blocks":[{"p":"A maioria dos pequenos trabalhos que você faz cem vezes por semana – reformatar uma resposta de API, decodificar um token, verificar um hash, recuar um slug de SQL – não precisa de um IDE, uma assinatura paga ou uma licença de equipe. Eles precisam de uma guia aberta por noventa segundos.\\n\\nA coleção abaixo é composta por vinte e quatro utilitários baseados em navegador que cobrem formatação, conversão, codificação, hash e depuração. Cada um deles é executado inteiramente em sua página: seus dados nunca são enviados para um servidor, o que é mais importante do que os desenvolvedores costumam admitir, porque a carga útil que você cola geralmente é de um cliente."},{"h":"O que as ferramentas baseadas em navegador podem ou não substituir"},{"p":"Seja realista quanto ao limite. Essas ferramentas substituem tarefas pontuais, de baixo risco e de alta frequência. Eles não substituem seu servidor de linguagem, seu depurador, seu conjunto de testes ou qualquer coisa que você precise executar repetidamente em um ambiente real."},{"l":["**Bom ajuste:** ler uma resposta uma vez, depurar um único valor, converter um arquivo para uma importação, verificar um formato antes do envio.","**Ajuste incorreto:** executar a mesma verificação em cada implantação, transformando centenas de arquivos, qualquer coisa que deva falhar ruidosamente na CI.","**Nunca:** nada que envolva credenciais que você não possa alternar. Cole um token revogado, não um ativo."]},{"p":"Dito isso, o motivo para mantê-los marcados é o rendimento. Uma tarefa que leva quarenta segundos em uma guia do navegador nunca é agendada, nunca é delegada e nunca se torna um motivo para abrir um IDE às oito da noite."},{"h":"Formatando e convertendo dados"},{"p":"A tarefa diária mais comum é tornar os dados legíveis. Uma API retorna um blob de linha única, um colega envia um arquivo de configuração com abas distorcidas por uma janela de bate-papo ou você exportou uma planilha para JSON e ela voltou como uma linha enorme."},{"l":["[[json-formatter|JSON Formatter]] — recuar, validar e ler uma carga útil. Use-o antes de depurar: metade de todos os tickets \\"a API está quebrada\\" são, na verdade, JSON malformado com uma vírgula final.","[[json-validator|JSON Validator]] — quando você precisa de uma resposta estrita de aprovação/reprovação em vez de uma impressão bonita.","[[xml-formatter|XML Formatter]] — o mesmo trabalho para respostas SOAP, feeds RSS e POMs Maven que ninguém mexeu desde 2014.","[[json-to-yaml|JSON to YAML]] e [[json-to-csv|JSON to CSV]] — movendo dados entre os formatos que os sistemas reais realmente usam."]},{"p":"Lembre-se do último grupo para um cenário específico: um cliente lhe entrega uma planilha e a espera em sua API. Transformar CSV em JSON diretamente é um trabalho de dois minutos, em vez de uma tarde de scripts."},{"h":"Codificação e escape"},{"p":"Erros de codificação são desproporcionalmente irritantes porque os dados parecem bons. O valor \\"San José & Sons\\" chega como \\"San Jos%C3%A9 %26 Sons\\" e sua comparação com o banco de dados falha por motivos invisíveis nos logs."},{"l":["[[url-encoder|URL Encoder / Decoder]] — decide imediatamente se uma string de consulta é codificada duas vezes.","[[base64-encoder|Base64 Encoder / Decoder]] — decodifica um fragmento de certificado ou codifica um pequeno ativo para in-line em CSS.","[[html-entity-encoder|Codificador/Decodificador de entidade HTML]] — descubra se aquele \\"&\\" perdido em sua página veio de seu modelo ou de seus dados.","[[unicode-converter|Conversor Unicode]] — útil quando um caractere \\"quebrado\\" acaba sendo legítimo e renderizado na codificação errada.","[[number-base-converter|Number Base Converter]] — verifique uma cor, uma máscara de bits de permissão ou um endereço de memória sem um aplicativo de calculadora."]},{"b":"Um hábito prático: quando um valor chega distorcido, decodifique-o uma camada por vez e cole cada resultado em um campo em branco. Se a primeira decodificação produzir texto legível, o problema será uma codificação extra em algum lugar upstream. Se produzir mojibake, você terá um problema de codificação em vez de um problema de escape, e esses dois precisam de soluções diferentes."},{"h":"Identificadores, hashes e tokens"},{"p":"Este grupo é onde os desenvolvedores perdem mais tempo procurando o script local correto que escreveram uma vez e perderam."},{"l":["[[uuid-generator|UUID Generator]] — gera identificadores v4 para dados iniciais, fixtures ou uma linha rápida do banco de dados.","[[md5-generator|MD5 / SHA Hash Generator]] — verifica um download ou confirma se dois arquivos que deveriam ser idênticos realmente o são.","[[timestamp-converter|Timestamp Converter]] — a ferramenta mais usada em toda a lista. Quando uma linha de log diz 1761000000, é isso que informa se o incidente aconteceu durante a implantação ou antes dela."]},{"p":"O conversor de carimbo de data/hora ganha seu sustento por um motivo específico: um número de época é inequívoco e inútil ao mesmo tempo. Você sabe exatamente quando algo aconteceu e não pode contar a um colega. A conversão uma vez geralmente resolve uma discussão mais alta do que deveria."},{"h":"Comparando e depurando"},{"l":["[[regex-tester|Regex Tester]] — o item de maior alavancagem aqui. Uma expressão regular que parece correta e silenciosamente não corresponde a nada é um dos bugs mais caros no desenvolvimento, porque falha silenciosamente no único lugar onde ninguém lê.","[[html-preview|HTML Preview]] — itere em um fragmento de marcação para verificar como ele realmente é renderizado."]},{"p":"Teste suas expressões regulares em relação à entrada que você realmente espera, incluindo a string vazia, um nome Unicode e um valor com uma nova linha. A maioria dos padrões quebra no terceiro caso e ninguém percebe até que os dados de produção cheguem."},{"h":"Um exemplo prático: três ferramentas, um incidente chato"},{"p":"Aqui está a sequência que me convenceu a marcar tudo isso. Um cliente relatou que um registro enviado na terça-feira estava faltando em um relatório na quinta-feira."},{"l":["**1. Converta o carimbo de data/hora.** O trabalho de relatório registrou o horário de criação do registro como um valor de época. O [[timestamp-converter|Timestamp Converter]] mostrou que o registro foi criado às 23h local, que é terça-feira — a suposição de fuso horário do trabalho era o problema, não o registro.","**2. Formate a carga útil.** Levar o JSON armazenado por meio do [[json-formatter|JSON Formatter]] revelou que o registro foi gravado com um campo de data nulo, porque o cliente chamou duas vezes o mesmo endpoint com 200 ms de intervalo e a segunda gravação venceu.","**3. Compare as cargas.** Ambos os registros carregavam a mesma chave de API e o mesmo carimbo de data/hora do cliente, o que apontava para uma nova tentativa em vez de dois clientes separados."]},{"p":"Tempo total decorrido: quatro minutos. A tentativa anterior desta investigação, que procurou a mesma causa raiz numa plataforma de registo, demorou uma tarde e produziu uma conclusão errada."},{"h":"Privacidade: por que a execução local é o recurso real"},{"p":"Cada ferramenta nesta biblioteca processa sua entrada dentro de seu próprio navegador. Nada é carregado, o que significa que não há perguntas sobre retenção, nenhum acordo de processador e nenhuma conversa desconfortável sobre a carga útil de produção que você colou há três minutos.\\n\\nEsta é a razão para preferir essas ferramentas a uma “API pastebin” hospedada ou a um serviço online que solicita que você se inscreva. Isso também significa que eles continuarão trabalhando durante um voo, em um porão ou quando a VPN corporativa decidir bloquear outro domínio."},{"p":"Uma ressalva que vale a pena deixar clara: uma página com capacidade offline só é privada se a página em si for o código que você pensa que é. Em uma máquina compartilhada, use uma janela privada e feche-a quando terminar, especialmente se estiver decodificando tokens."},{"h":"Construindo um fluxo de trabalho em torno deles"},{"p":"As ferramentas são individualmente triviais. O valor tem o hábito de buscar um imediatamente em vez de \\"fazer isso mais tarde\\", porque mais tarde é quando você escreve um script descartável, ou abre um IDE, ou decide que não vale a pena verificar."},{"l":["Marque a coleção, não URLs individuais, e coloque-a na barra de ferramentas do seu navegador.","Quando algo parece errado, verifique antes de formar uma teoria. Custa quinze segundos; mata classes inteiras de conclusões erradas.","Quando você verifica a mesma coisa duas vezes, esse é o sinal para automatizá-la – mas não automatize por suspeita.","Não cole segredos de produção. Gire qualquer coisa sobre a qual você não tenha certeza."]},{"h":"Perguntas frequentes"},{"p":"**Essas ferramentas são gratuitas?** Sim, totalmente, sem conta e sem limite de uso. Não existe um nível pago que retenha algo básico.\\n\\n**Eles funcionam off-line?** Depois que a página é carregada, sim, tudo é executado no seu navegador. Recarregar requer uma conexão.\\n\\n**Posso usá-los para trabalhos comerciais?** Sim. A saída é sua, sem necessidade de atribuição.\\n\\n**Existe uma API?** Não, e isso é deliberado — o valor é a interface. Exporte a saída e processe-a como quiser.\\n\\n**Por que não instalar apenas uma ferramenta CLI?** Instale uma quando precisar dela três vezes. Use uma guia do navegador para os dois primeiros."}]},"text-tools-for-writers":{"title":"17 ferramentas de texto gratuitas para escritores, estudantes e profissionais de marketing","description":"Limpe textos, conte palavras com precisão, formate listas e transforme rascunhos em algo publicável - com ferramentas de navegador gratuitas que são executadas localmente em seu navegador.","category":"Ferramentas de texto","blocks":[{"p":"Escrever para o trabalho envolve uma quantidade surpreendente de trabalho penoso e mecânico que não tem nada a ver com a escrita: remover espaços em branco perdidos de um parágrafo colado, verificar um limite de palavras, desduplicar uma lista de nomes, converter algo em um slug de URL.\\n\\nEssas dezessete ferramentas são para essa parte do trabalho. Todos eles são executados localmente no navegador, o que não é um pequeno detalhe – o rascunho que você cola geralmente não é publicado e a lista que você está classificando geralmente contém dados pessoais de alguém."},{"h":"Medindo o que você escreveu"},{"p":"A contagem de palavras parece resolvida até que um cliente solicite exatamente 800 palavras e seu editor diga 820, ou um formulário rejeite seu texto com 1.995 caracteres sem nenhuma explicação de onde foi a nova linha."},{"l":["[[word-counter|Word Counter]] — a medida padrão. Cole, leia, ajuste.","[[letter-counter|Letter Counter]] — conta caracteres e frequência de letras. Útil quando você está depurando por que um parágrafo parece errado: geralmente é um padrão de letras repetidas, não um sonho."]},{"p":"Uma observação sobre o que significa \\"uma palavra\\": contadores diferentes discordam quanto à hifenização, números e URLs. Se um número exato for importante, use o mesmo contador usado pela pessoa que verifica seu trabalho e combine-o com antecedência. Esta é uma fonte genuinamente comum de argumentos pequenos e inúteis."},{"h":"Limpando a cópia que você não escreveu"},{"p":"A maior parte do texto que você recebe está ligeiramente danificada: espaços duplos de copiar e colar, uma tabulação perdida, letras maiúsculas inconsistentes de alguém digitando com pressa. Consertá-lo manualmente é lento e sujeito a erros."},{"l":["[[text-trimmer|Text Trimmer]] — remove espaços em branco iniciais e finais de cada linha de uma vez. Isso corrige mais relatórios de “formatação parece quebrada” do que qualquer outra coisa nesta lista.","[[text-case-converter|Conversor de maiúsculas e minúsculas de texto]] — alterna entre maiúsculas e minúsculas da frase, maiúsculas e minúsculas do título, superior e inferior em um bloco. Também é a maneira mais rápida de desfazer um parágrafo acidental de CAPS LOCK.","[[text-to-slug|Text to Slug]] — transforme um título em um slug de URL limpo. Cole seu título, pegue o slug e pronto."]},{"p":"O gerador de slug tem um uso além dos URLs: é uma maneira rápida de criar um nome de arquivo legível ou uma âncora que um ser humano possa analisar rapidamente, o que supera `final_final_v3`."},{"h":"Trabalhando com listas"},{"p":"Listas, inventários, malas diretas, limpeza de tags, respostas de pesquisas, colunas de planilhas — em algum momento, tudo se torna uma lista e cada lista precisa ser classificada, desduplicada ou randomizada."},{"l":["[[duplicate-line-remover|Removedor de linha duplicada]] — compare duas listas ou limpe uma. A saída informa quantas duplicatas foram removidas, o que é útil quando você relata o resultado.","[[list-sorter|List Sorter]] — o mesmo trabalho para entrada de lista estruturada.","[[list-randomizer|List Randomizer]] — embaralhe uma ordem de sorteio, uma sequência de quiz ou uma lista restrita para que ninguém suspeite de favoritismo.","[[line-number-adder|Line Number Adder]] — numera linhas para referência em um ticket ou comentário de revisão de código."]},{"b":"A armadilha clássica aqui é uma lista que parece desduplicada, mas não é: `Apple`, `apple ` e `Apple.` são três linhas diferentes para um computador. Corte os espaços em branco e remova a pontuação final antes de desduplicar, ou você não mesclará nada e concluirá que os dados estão limpos."},{"h":"Pré-visualização e formatação"},{"p":"Markdown venceu, mas não de maneira uniforme. Metade de suas ferramentas renderiza, metade não, e a metade que não o faz geralmente é aquela em que alguém sênior deve colar."},{"l":["[[markdown-preview|Markdown Preview]] — renderização ao vivo, para que você possa verificar se uma tabela ou lista aninhada realmente parece correta antes de chegar ao cliente.","[[text-repeater|Text Repeater]] — repete uma string N vezes. Útil para gerar preenchimento, dados de teste ou, ocasionalmente, destacar um documento."]},{"p":"A visualização Markdown é a ferramenta que silenciosamente economiza mais tempo em todo esse conjunto, porque uma tabela quebrada em um documento renderizado é muito mais visível — e muito mais embaraçosa — do que uma tabela quebrada em texto bruto."},{"h":"O resto e quando alcançá-los"},{"l":["[[random-string|Random String Generator]] — gera nonces legíveis, IDs de espaço reservado ou códigos curtos. Melhor do que inventar algo à mão, porque você não vai reutilizar acidentalmente.","[[morse-code|Morse Code Translator]] — genuinamente divertido, ocasionalmente útil para um projeto temático ou um quebra-cabeça."]},{"p":"Estas são ferramentas de baixa frequência, mas não custa nada mantê-las marcadas e resolvem o problema específico de \\"Preciso de um valor aleatório agora e não confio em mim mesmo para inventá-lo\\"."},{"h":"Um passe de edição realista"},{"p":"Esta é a ordem que funciona quando um rascunho chega de outra pessoa e precisa ser enviado em seu nome."},{"l":["**1. Cortar.** Execute todo o documento através do [[text-trimmer|Text Trimmer]] primeiro. Os danos de espaço em branco ficam ocultos dentro de parágrafos onde você nunca os verá.","**2. Caixa limpa.** Use o [[text-case-converter|Text Case Converter]] apenas para o título. Nunca aplique a conversão de caso a um rascunho completo – isso destrói nomes próprios.","**3. Meça.** Verifique o comprimento com o [[word-counter|Word Counter]] antes de escrever, para saber qual formato a peça deve ter.","**4. Preview.** Se contiver Markdown, renderize-o com o [[markdown-preview|Markdown Preview]].","**5. Slug.** Gere o slug de URL por último, a partir do título final, com [[text-to-slug|Text to Slug]] — alterar o título depois quebra o slug."]},{"p":"Toda a passagem leva alguns minutos e elimina a categoria de erro em que um documento está tecnicamente correto e visivelmente errado."},{"h":"Perguntas dos escritores sobre privacidade"},{"p":"**Meu texto não publicado sai do meu computador?** Não. Essas ferramentas processam texto no seu navegador e nada é armazenado ou transmitido.\\n\\n**Existe um limite de comprimento?** Não há limite no lado do servidor porque não há chamada de servidor. Entradas extremamente grandes são limitadas pela memória do seu próprio dispositivo.\\n\\n**Posso usar o resultado comercialmente?** Sim, gratuitamente, sem atribuição.\\n\\n**Eles funcionam por telefone?** Sim. O layout se adapta e o mesmo código é executado."},{"h":"O que essas ferramentas não farão por você"},{"p":"Vale a pena ser franco quanto aos limites, porque uma ferramenta que mecaniza a coisa errada apenas produz um erro mais rápido.\\n\\nNenhum desses utilitários pode dizer se uma frase é clara, se uma afirmação tem origem ou se o tom é adequado para o público. Eles contam caracteres; eles não julgam a prosa. Um texto com ótima pontuação em todas as métricas desta página ainda pode ser ilegível.\\n\\nNem editam. No momento em que você se encontra reescrevendo cláusulas individuais manualmente em escala, você superou uma ferramenta de texto e deseja um editor adequado, um localize e substitua com regex - que o [[regex-tester|Regex Tester]] é genuinamente bom para ensaiar - ou um script. Use o navegador para a camada mecânica e mantenha seu próprio julgamento para tudo acima dela."},{"p":"Mais uma coisa que eles não farão é consertar uma fonte ruim. Se sua planilha estiver cheia de nomes inconsistentes - \\"Dr\\", \\"DR\\", \\"Dr.\\" tudo em uma coluna - uma ferramenta classificará e desduplicará o que você forneceu fielmente, e você ainda terá três entradas onde deveria haver uma. Limpar os dados é uma decisão, não uma etapa mecânica. Decida primeiro a forma canônica, depois aplique-a e verifique."},{"h":"Manter uma lista de trabalho utilizável"},{"p":"Se você mantiver uma lista de leads, links, referências ou termos, ela se degradará silenciosamente. O modo de falha é sempre o mesmo: entradas que parecem idênticas não o são, e uma mesclagem não remove nada.\\n\\nUma passagem de manutenção que funciona é enfadonha: cortar espaços em branco, padronizar letras maiúsculas, remover a pontuação final e, em seguida, desduplicar. Nessa ordem - o corte após a desduplicação perde entradas. Fazer isso uma vez por mês em uma lista ativa transforma uma bagunça irrecuperável de duas horas em uma tarefa de dez minutos.\\n\\nQuando duas listas precisam ser reconciliadas - digamos, uma lista de registro versus uma lista de presença - classifique ambas primeiro com o [[classificador de listas|Classificador de listas]], para que elas se alinhem e depois comparem a olho nu. Classificar os dois lados antes de comparar é a diferença entre uma verificação de dois minutos e uma caçada de vinte minutos."},{"h":"A lição"},{"p":"Nenhuma dessas ferramentas é inteligente. Esse é o ponto: eles removem os cinco por cento mecânicos da escrita que não é escrita, de modo que os noventa e cinco por cento restantes são, na verdade, sobre sentenças. Marque aqueles que você usa mensalmente, ignore o resto e pare de corrigir os espaços em branco manualmente."}]},"calculators-and-converters-guide":{"title":"18 calculadoras e conversores gratuitos para os números com os quais você realmente lida","description":"Porcentagens, descontos, gorjetas, empréstimos, datas, IMC e conversões de unidades — calculadoras de navegador gratuitas que mostram seu raciocínio, sem necessidade de conta.","category":"Calculadoras","blocks":[{"p":"Todo mundo precisa dividir uma conta, descobrir se um desconto é realmente um desconto e converter uma temperatura ou tamanho de arquivo sem pensar nisso. Todo mundo também, pelo menos uma vez, erra isso em público.\\n\\nEsta é uma coleção de dezoito calculadoras e conversores que cobrem dinheiro, datas, saúde e conversões de unidades que aparecem no trabalho e nas viagens. Todos eles rodam no navegador: nada é salvo, então os números que você digita não são da conta de ninguém, apenas seus."},{"h":"Cálculos de dinheiro"},{"p":"A matemática mais comum do mundo real é uma porcentagem de alguma coisa. Imposto sobre vendas, gorjeta, desconto, comissão, taxa de crescimento. A fórmula é simples, mas a razão pela qual as pessoas erram é quase sempre a mesma: aplicam uma percentagem à base errada."},{"l":["[[discount-calculator|Calculadora de descontos]] — calcule o preço final e, mais importante, quanto você economizou. Útil para identificar um \\"desconto de 50%\\" que é, na verdade, 20% após um preço de tabela aumentado.","[[tip-calculator|Tip Calculator]] — divida uma conta, escolha uma porcentagem e arredonde por pessoa, se desejar.","[[loan-calculator|Loan Calculator]] — pagamento mensal e juros totais, que é o número que realmente decide se um empréstimo é acessível."]},{"b":"Sobre descontos: um desconto de 20% seguido de outro desconto de 20% não é 40% de desconto – é 36%. Porcentagens sequenciais compostas na base reduzida. Qualquer calculadora nesta lista confirmará isso em cerca de dois segundos, e é o fato aritmético mais útil neste artigo."},{"p":"A calculadora de empréstimos merece uma observação específica. O número que importa não é o pagamento mensal – é o total de juros pagos ao longo da vida do empréstimo, porque esse é o custo real do empréstimo. Dois empréstimos com pagamentos mensais idênticos e prazos diferentes podem diferir em dezenas de milhares nos juros totais."},{"h":"Datas e contagens regressivas"},{"p":"A aritmética de datas é onde a maioria das pessoas erram silenciosamente, porque os meses humanos têm durações diferentes e a resposta muda dependendo se você quer dizer \\"meses corridos\\" ou \\"30 dias\\"."},{"l":["[[date-difference|Calculadora de diferença de data]] — dias (e total de meses, anos) entre duas datas.","[[days-until|Days Until Calculator]] — uma contagem regressiva para uma data específica, com o número de dias úteis geralmente sendo o que as pessoas realmente desejam.","[[age-calculator|Age Calculator]] — idade exata em anos e dias, mais o próximo aniversário.","[[timestamp-converter|Timestamp Converter]] — um carimbo de data/hora Unix em uma data real, o que é importante se você tocar em logs, bancos de dados ou respostas de API."]},{"p":"A distinção que confunde as pessoas: o número de dias entre 1º de março e 1º de abril é 31, mas o número de *meses* é um. Se você estiver calculando um período de aviso prévio ou um prazo de assinatura, indique por escrito a qual unidade você se refere."},{"h":"Números de saúde, honestamente"},{"l":["[[bmi-calculator|Calculadora de IMC]] — índice de massa corporal com as categorias padrão e as advertências abaixo."]},{"p":"O IMC é uma estatística de triagem em nível populacional. Não diz nada sobre a massa muscular, a composição corporal ou a saúde de qualquer indivíduo, e é um indicador fraco da aptidão física em atletas, em adultos mais velhos e em diferentes grupos étnicos. Use-o como um ponto de dados entre vários ou como uma forma de acompanhar uma mudança ao longo do tempo – não como um veredicto. Se você estiver tomando decisões que afetam sua saúde, a ferramenta certa é um médico, não uma guia do navegador."},{"h":"Conversão de unidades: as do dia a dia"},{"p":"A conversão de unidades é dividida em dois tipos: conversões que você precisa acertar e conversões que você precisa aproximadamente. Essas ferramentas lidam com ambos, e o trabalho consiste em lembrar qual é qual."},{"l":["[[conversor de comprimento|Conversor de comprimento]] — métrico para imperial e vice-versa: milímetros, centímetros, metros, quilômetros, polegadas, pés, jardas, milhas.","[[conversor de peso|Conversor de peso]] — gramas, quilogramas, onças, libras, toneladas. Aquele a verificar antes de uma receita ou etiqueta de envio.","[[conversor de temperatura|Conversor de temperatura]] — Celsius, Fahrenheit, Kelvin. Porque -10°C não é 14°F e a fórmula não é uma multiplicação.","[[conversor de velocidade|Conversor de velocidade]] — km/h, mph, m/s, nós. Útil para um limite de velocidade estrangeiro ou especificações de engenharia.","[[area-converter|Conversor de área]] — metros quadrados, pés quadrados, acres, hectares. É esse que as pessoas estimam mal na hora de comprar ou alugar um imóvel.","[[conversor de volume|Conversor de volume]] — litros, mililitros, galões, xícaras, metros cúbicos.","[[time-converter|Time Converter]] — segundos, minutos, horas, dias, semanas."]},{"b":"Duas armadilhas de conversão que vale a pena conhecer: a de armazenamento de dados acima (os profissionais de marketing vendem 10 ^ 3, os sistemas operacionais relatam 2 ^ 10) e a economia de combustível - um carro cotado a 40 mpg (imperial) está mais próximo de 33 mpg (EUA) do que 40, porque o galão imperial é maior. Errar no segundo faz com que um carro alugado pareça excessivamente eficiente."},{"h":"Os dois que você não espera precisar"},{"l":["[[random-number|Random Number Generator]] — sorteios dentro de um intervalo, para um sorteio, uma chave ou uma rápida divisão A/B. Útil precisamente porque elimina a suspeita de que você o fraudou.","[[dice-roller|Dice Roller]] — qualquer dado, desde um cara ou coroa até um dado de vinte faces, para um jogo de tabuleiro ou uma sessão de mesa onde o dado real rolou para fora da mesa pela última vez."]},{"h":"Usando uma calculadora corretamente"},{"p":"Uma calculadora só ajuda se você souber qual número está perguntando. Três hábitos fazem a diferença."},{"l":["**Primeiro arredondar, calcular depois.** Se o número exato não mudar sua decisão, use um arredondamento. As porcentagens de números redondos podem ser verificadas em sua cabeça, o que detecta erros de entrada.","**Verifique a magnitude.** Antes de acreditar em um resultado, pergunte se ele deve ser maior ou menor que a entrada e aproximadamente em quanto. A maioria dos erros aritméticos sobrevive a todas as verificações, exceto esta.","**Fotografe as entradas, não a saída.** Quando você executar novamente o cálculo posteriormente, o que importa é saber o que você presumiu, não o que concluiu."]},{"h":"Perguntas que as pessoas realmente fazem"},{"p":"**Meus números ficam armazenados em algum lugar?** Não. Os cálculos acontecem no seu navegador e nada é transmitido ou retido.\\n\\n**Funcionam em um telefone?** Sim, e as calculadoras são projetadas para uso com uma mão.\\n\\n**Qual padrão de conversão você usa para armazenamento de dados?** Decimal (1 KB = 1.000 bytes) por padrão, porque é assim que o armazenamento é vendido. Os sistemas operacionais relatam binário, e é por isso que uma unidade parece encolher – a ferramenta explica a diferença em vez de escolher um lado silenciosamente.\\n\\n**Posso incorporá-los em meu próprio site?** Não. Em vez disso, marque-os como favoritos; o custo disso é zero e o problema de precisão é seu."},{"h":"Porcentagens: os quatro erros que importam"},{"p":"Quase todo erro percentual que uma pessoa comete na vida diária é um dos mesmos quatro erros. Nomeá-los os torna evitáveis."},{"l":["**Base errada.** \\"Um aumento de 10% e depois uma queda de 10% deixa você onde você começou\\" é falso, porque ambos se aplicam a bases diferentes. Dez por cento de 100 é 10; dez por cento de 90 é 9.","**Porcentagem de uma porcentagem.** Acumular dois descontos os multiplica (0,8 × 0,8 = 0,64, ou seja, 36% de desconto), mas não os soma.","**Porcentagens versus pontos percentuais.** Uma taxa que vai de 4% para 6% aumentou 2 pontos percentuais, mas 50% em termos relativos. A política e a medicina estão cheias desta confusão, e nem sempre é acidental.","**Arredondamento muito cedo.** Arredondar uma etapa intermediária antes de aplicar uma porcentagem agrava o erro. Mantenha a precisão total até o valor final e execute a última etapa em uma calculadora, e não de cabeça."]},{"p":"Se você pegar apenas um hábito de toda esta seção, escolha este: antes de citar uma porcentagem para alguém, reafirme o que é uma porcentagem *de*. Metade dos argumentos que você terá sobre um número são, na verdade, argumentos sobre o denominador."},{"h":"Saber quando parar de calcular"},{"p":"Chega um ponto em que a precisão deixa de ser útil. Um pagamento mensal com duas casas decimais é significativo. Um custo total projetado com oito casas decimais é uma forma de evitar a decisão real, que é se o empréstimo cabe dentro do que você pode pagar sem estresse.\\n\\nO teste útil é a questão da sensibilidade: a decisão muda se esta entrada se mover 10%? Caso contrário, pare de refiná-lo e use o tempo extra na variável que move a resposta – geralmente o prazo em vez da taxa, ou o preço de tabela em vez do desconto."},{"p":"E vale a pena declarar claramente um limite: essas calculadoras são aritméticas, não conselhos. Uma meta de poupança, uma data de aposentadoria e um plano de pagamento de dívidas são decisões sobre risco, comportamento e tempo, e uma guia do navegador não pode pesar nada disso. Ele só pode dizer o que os números implicam depois de você decidir o que está assumindo. Essa distinção é a diferença entre uma calculadora ser útil e ser responsável."},{"h":"A versão de uma linha"},{"p":"Marque as calculadoras de dinheiro e data corretamente, trate o IMC como um sinal em vez de um veredicto, lembre-se de que as porcentagens empilhadas se multiplicam e verifique a conversão de unidades sempre que um número estiver entrando em algo contratual. Isso cobre quase tudo."}]},"image-and-design-tools":{"title":"14 ferramentas gratuitas de imagem e design que rodam em seu navegador","description":"Comprima, redimensione e prepare imagens e gere efeitos CSS, paletas, verificações de contraste e favicons sem instalar o Photoshop ou um conjunto de design.","category":"Ferramentas de projeto","blocks":[{"p":"O trabalho de imagem tem um problema específico: o trabalho geralmente é pequeno e as ferramentas oferecidas são enormes. Você precisa eliminar 400 KB de uma imagem principal, obter um valor hexadecimal mencionado pelo designer ou gerar um favicon que ninguém criou ainda. Isso não requer uma assinatura.\\n\\nAs quatorze ferramentas abaixo cobrem a preparação de imagens, o trabalho com cores, a geração de efeitos CSS e os pequenos ativos de produção que passam despercebidos. Cada um é executado localmente, o que é mais importante para imagens do que para texto: a foto que você acabou de compactar geralmente é uma foto que você ainda não publicou."},{"h":"Preparando imagens para a web"},{"p":"A maioria dos problemas de imagem são, na verdade, problemas de peso. Uma página que parece lenta geralmente contém imagens maiores que o tamanho de exibição, no formato errado e com uma configuração de qualidade que ninguém jamais questionou."},{"l":["[[image-compressor|Compressor de imagem]] — reduza o tamanho do arquivo enquanto mantém a imagem visualmente intacta. Execute-o antes de enviar qualquer coisa para um formulário com limite de tamanho.","[[image-resizer|Image Resizer]] — defina as dimensões reais em pixels que você precisa. Esta é a maior vitória: uma imagem de 4.000 pixels exibida em 800 pixels carrega cinco vezes mais dados de que precisa.","[[image-to-base64|Image to Base64]] — converte uma pequena imagem em um URI de dados para inlining em CSS, HTML ou um modelo de email."]},{"b":"A ordem é importante. Redimensione primeiro e depois comprima. Compactar uma imagem de 4000px produz um arquivo muito mais pesado do que redimensionar para 800px e depois compactar com a mesma qualidade, porque os compressores gastam seu esforço em pixels que seriam jogados fora de qualquer maneira."},{"p":"Quanto você deve comprimir? A resposta honesta é: até que pareça errado, recue um passo. Para uma imagem fotográfica principal, a qualidade de 70 a 80 por cento geralmente é indistinguível do original em tamanho de visualização normal. Para um logotipo, uma captura de tela ou qualquer coisa com cores planas e bordas rígidas, use PNG e comprima com mais força – eles ganham mais e perdem menos."},{"p":"Uma regra prática: qualquer coisa abaixo de 200 KB é adequada para uma imagem principal, menos de 80 KB para uma miniatura, e se você não conseguir menos de 300 KB, provavelmente terá um problema de dimensão em vez de um problema de qualidade."},{"h":"Base64: quando inlining é a decisão certa"},{"p":"A conversão de uma imagem em um URI de dados Base64 remove uma solicitação HTTP, o que parece uma vitória pura. Geralmente não é. A string codificada é aproximadamente um terço maior que o arquivo binário, não pode ser armazenada em cache separadamente e sobrecarrega seu CSS ou HTML.\\n\\nInline somente quando a imagem for pequena — menos de alguns kilobytes — usada uma vez e crítica. Um pequeno ícone em um único modelo de email é o caso clássico. Para qualquer coisa repetida nas páginas ou maior que alguns kilobytes, sirva-a como um arquivo e deixe o navegador armazená-la em cache."},{"h":"Marcas d\'água: o que é honestamente removível"},{"l":[]},{"p":"Seja claro sobre o que isso faz. Remove ou obscurece a marca visível. Ele não pode reconstruir os pixels subjacentes – as informações que foram pintadas desaparecem e nenhum filtro as inventa de volta. Os resultados variam de invisível, quando a marca fica sobre um fundo liso, até uma mancha óbvia quando fica sobre detalhes.\\n\\nMais uma coisa que vale a pena dizer claramente: remover a marca d\'água de outra pessoa e publicar o resultado é um problema de direitos autorais na maioria das jurisdições e uma violação de licenciamento, independentemente de você ser pego. Remover marcas de suas próprias imagens ou de estoque licenciado é o caso desta ferramenta."},{"h":"Cor: convertendo, verificando, escolhendo"},{"p":"A cor é onde os pequenos erros se tornam muito visíveis. Uma taxa de contraste que falha na acessibilidade, um valor hexadecimal que na verdade é um triplo HSL, uma paleta que parece coerente em seu monitor e turva em um projetor."},{"l":["[[color-converter|Color Converter]] — alternar entre HEX, RGB e HSL. Vale a pena aprender a ler HSL, porque matiz 210, saturação 40 por cento, luminosidade 50 por cento é muito mais fácil de ajustar manualmente do que um valor hexadecimal.","[[contrast-checker|Contrast Checker]] — testa o texto em relação ao seu plano de fundo em relação aos limites WCAG. Esta é a ferramenta mais útil neste artigo, porque detecta um problema real de conformidade, e não um problema de sabor.","[[color-palette|Color Palette Generator]] — gera um conjunto coerente quando você está partindo de uma cor de marca e precisa do restante da escala."]},{"b":"Em contraste: WCAG AA pede 4,5 para 1 para texto normal e 3 para 1 para texto grande. Se você estiver escolhendo entre duas cores de marca para um botão, a cor acessível geralmente não é aquela que o designer gosta. Verifique primeiro e depois argumente com os dados."},{"p":"Uma advertência sobre as ferramentas de cores: todas elas presumem que seu monitor está calibrado e que a pessoa que visualiza sua página tem olhos funcionais. Nenhuma das suposições é segura. Essa é uma razão para preferir combinações verificadas por contraste às subjetivas."},{"h":"Efeitos CSS sem abrir uma ferramenta de design"},{"p":"Escrever um gradiente ou uma sombra em camadas à mão é uma tarefa genuinamente desagradável. A sintaxe é complicada, você não consegue ver o que está produzindo e a diferença entre uma sombra boa e uma ruim são alguns pixels de desfoque."},{"l":["[[gradient-generator|CSS Gradient Generator]] — cria gradientes lineares e radiais e copia o CSS diretamente.","[[box-shadow-generator|Box Shadow Generator]] — camada de múltiplas sombras, que é o que separa uma elevação sutil de uma queda pesada.","[[border-radius-generator|Border Radius Generator]] — obtém os raios assimétricos que fazem uma forma parecer intencional.","[[text-shadow-generator|Text Shadow Generator]] — útil com moderação. A maioria das sombras do texto são muito fortes; isso permite ajustar o deslocamento e o desfoque até que desapareça."]},{"p":"O truque para todos os quatro é a contenção. Duas sombras - uma escura e densa e uma ampla e suave - são interpretadas como elevação física. Uma sombra parece um site de quinze anos atrás. Gere, copie e exclua até que você não saiba que ele está lá."},{"h":"Os ativos de produção que todos esquecem"},{"l":["[[favicon-generator|Favicon Generator]] — produz o pequeno conjunto de ícones que um site realmente precisa. Isso está na lista porque os favicons são o ativo com maior probabilidade de estar totalmente ausente, e um que está faltando mostra um ícone genérico de página do navegador que faz com que um site finalizado pareça inacabado.","[[emoji-picker|Emoji Picker]] — navegue, pesquise e copie emojis sem procurar por um seletor de sistema operacional. Genuinamente útil quando você está escrevendo um texto que precisa de um símbolo específico."]},{"h":"Um exemplo prático: enviar uma seção de herói"},{"p":"Aqui está todo o cluster fazendo um trabalho real. Uma página precisa de um herói com imagem de fundo, título e botão, e nada disso foi construído ainda."},{"l":["**1. Reserve o espaço.** Dê ao slot da imagem uma altura fixa no layout, para que a página tenha o formato correto desde a primeira renderização, em vez de pular quando a imagem real chegar.","**2. Redimensione e comprima.** Quando a foto real chegar, passe-a pelo [[image-resizer|Image Resizer]] com 1600px de largura e depois pelo [[image-compressor|Image Compressor]] com 75 por cento. Esse é um arquivo que você pode enviar.","**3. Verifique o contraste do texto.** Um título sobre uma foto é a clássica falha de contraste. Use o [[contrast-checker|Contrast Checker]] para escolher uma intensidade de sobreposição escura ou uma cor de texto clara que passe por AA.","**4. Construa o botão.** O [[box-shadow-generator|Box Shadow Generator]] fornece a elevação, e o [[color-converter|Color Converter]] coloca a cor da marca no formato que o CSS precisa.","**5. Enviar.** Adicione um favicon do [[favicon-generator|Favicon Generator]] para que a aba não pareça abandonada e a seção esteja pronta."]},{"p":"Cinco ferramentas, nenhum conjunto de design e cada saída é um valor que você pode colar diretamente no código."},{"h":"Perguntas frequentes"},{"p":"**Minhas imagens são carregadas em algum lugar?** Não. A compactação, o redimensionamento e a conversão em Base64 acontecem no seu navegador, e é por isso que não há limite de tamanho de arquivo nem fila de upload.\\n\\n**A compactação de uma imagem perderá qualidade?** Sempre, por definição. A questão é se é visível. Com qualidade de 70 a 80 por cento e dimensões corretas, geralmente não é.\\n\\n**Por que minha imagem redimensionada ainda parece grande?** Nove em cada dez vezes você comprimiu antes de redimensionar ou está salvando como PNG quando uma foto é melhor como JPEG.\\n\\n**Posso usá-los para trabalho do cliente?** Sim, sem atribuição e sem restrição comercial.\\n\\n**Eles funcionam em um telefone?** Sim, embora o redimensionamento e a compactação de fotos grandes em um telefone dependam da memória do seu dispositivo e não de um servidor."},{"h":"A versão de uma linha"},{"p":"Redimensione antes de compactar, verifique o contraste antes de discutir sobre cores, mantenha as sombras sutis e nunca se esqueça do favicon. De qualquer forma, isso é muito do que uma suíte de design estava fazendo por você."}]},"math-tools-for-real-numbers":{"title":"6 ferramentas matemáticas gratuitas para números que não se comportam","description":"Notação científica, decimais em frações, verificação de números primos, fatoriais e GCF/LCM — ferramentas de navegador gratuitas para o trabalho numérico que é fácil de errar.","category":"Ferramentas matemáticas","blocks":[{"p":"A matemática que você realmente precisa em um computador não é a matemática na qual você foi examinado. É: esse número está no formato que o sistema espera, essa fração está simplificada, com que rapidez isso cresce e por que a calculadora e a planilha discordam.\\n\\nEstas seis ferramentas cobrem esse território. Eles funcionam localmente, o que para aritmética significa um benefício específico que vale a pena citar: o número que você digitou não é enviado para lugar nenhum, então você pode verificar um cálculo envolvendo salário, saldo ou valor do cliente sem pensar duas vezes."},{"h":"Colocar números em um formato que uma máquina aceita"},{"p":"Os computadores armazenam frações decimais como frações binárias. 0,1 não é exatamente representável em binário - o valor de precisão dupla mais próximo é 0,10000000000000055511151231257827. Adicione 0,1 + 0,2 e você obterá 0,30000000000000004, que é impresso como 0,3 por padrão e quebra silenciosamente uma verificação de igualdade."},{"l":["[[notação científica|Conversor de notação científica]] — alterna entre a forma padrão e a científica, que é como a maioria dos logs, planilhas e APIs realmente armazenam números grandes e pequenos.","[[decimal-fraction|Decimal to Fraction]] — converte um decimal em uma fração exata. Esta é a solução para o problema acima: 0,1 + 0,2 na fração exata aritmética é 3/10, não uma aproximação."]},{"b":"Se você já viu um total errado em 0,0000000000000004, é por isso. No código financeiro a resposta padrão é trabalhar em centavos inteiros, ou em uma biblioteca decimal, e nunca em ponto flutuante. Se você já viu uma planilha discordar de um script por uma fração de centavo, é o mesmo bug com um chapéu diferente."},{"p":"Vale a pena ser fluente em notação científica, porque é a diferença entre ler uma linha de registro e semicerrá-la. 6.022e23, 1.6e-19 e 3e8 são o número de Avogadro, a carga elementar e a velocidade da luz. Se parecerem ruído em vez de números, converter alguns por meio da ferramenta corrige o problema permanentemente."},{"h":"Primes, e por que alguém se importa"},{"l":["[[prime-checker|Prime Number Checker]] — testa se um número é primo e vê sua fatoração quando não é.","[[gcf-calculator|GCF LCM Calculator]] — maior fator comum e mínimo múltiplo comum."]},{"p":"Os números primos não são um exercício escolar. A segurança de cada conexão HTTPS que você faz depende do fato de que multiplicar dois números primos grandes é fácil e fatorar o resultado é difícil. Essa assimetria é toda a base da RSA.\\n\\nPara fins cotidianos, a verificação principal trata principalmente de frações. Simplificar uma fração significa dividir o topo e a base pelo seu maior fator comum, e você não pode descobrir isso sem fatorar. É por isso que essas duas ferramentas estão juntas: verifique os fatores e, em seguida, obtenha o GCF e o LCM em uma única etapa."},{"p":"A metade LCM é aquela que as pessoas esquecem e é a que resolve os problemas de agendamento: dois eventos que se repetem a cada 18 dias e a cada 12 dias coincidem a cada 36 dias. Mesma aritmética, aplicação diferente."},{"h":"Fatoriais e a velocidade com que eles explodem"},{"l":["[[calculadora fatorial|Calculadora fatorial]] — n! para valores onde a resposta ainda é significativa."]},{"p":"Os fatoriais crescem mais rápido do que quase tudo que você encontra em uma mesa. 10! é de cerca de 3,6 milhões. 20! é cerca de 2,4 quintilhões – maior que o número de grãos de areia na Terra por uma ampla margem. 52!, o número de maneiras de embaralhar um baralho de cartas, é aproximadamente 8 seguido por 67 dígitos.\\n\\nA consequência prática é que um programa que enumera todas as permutações é bom em 5 itens, tolerável em 8 e permanentemente preso em 12. Se uma tarefa parece que nunca terminará e você está repetindo permutações, é quase certamente por isso. É também o argumento contra a maioria das abordagens de força bruta, apresentadas como aritmética e não como opinião."},{"h":"Algarismos romanos e o que há de estranho neles"},{"l":["[[algarismos romanos|Conversor de algarismos romanos]] — converte de e para algarismos romanos."]},{"p":"Vale a pena entender os algarismos romanos, em vez de apenas convertê-los, porque o sistema revela algo sobre a notação posicional. Não há zero nem valor posicional: XI significa onze, quer represente onze paus ou onze mil. É por isso que a aritmética em algarismos romanos é genuinamente difícil, e é por isso que o sistema sobreviveu durante séculos principalmente para contagem e datação, em vez de cálculo.\\n\\nA regra subtrativa é a parte que as pessoas erram. IV é quatro, não VI; IX é nove. Os relógios são uma exceção famosa – o Big Ben usa IIII em vez de IV, por razões que os historiadores ainda discutem. Converter em vez de derivar é a decisão certa em todos os casos."},{"h":"Um exemplo prático: verificar uma fração manualmente"},{"p":"Uma receita precisa de 0,375 xícaras e uma balança que lê em gramas, um relatório cita uma proporção de 0,625, e ambos parecem números que alguém digitou com pressa."},{"l":["**1. Encontre a fração exata.** Execute 0,375 através da ferramenta [[decimal-fraction|Decimal to Fraction]]: 3/8. Execute 0,625: 5/8. Nem precisava de um hábito de calculadora que você não possui.","**2. Simplifique a proporção.** Para expressar 3/8 contra 5/8, você precisa do MDC de 3 e 5. A [[gcf-calculator|GCF LCM Calculator]] fornece 1, então a proporção é 3:5 e já é a mais simples.","**3. Verifique a afirmação dos fatoriais.** Se alguém lhe disser que uma fila de 9 pedidos tem 362.880 arranjos, a [[factorial-calculator|Calculadora Fatorial]] confirma 9! é exatamente isso. Agora você sabe se a estimativa do tempo de construção era plausível.","**4. Normalize qualquer coisa grande.** Um servidor que relata 1,5e9 nanossegundos equivale a 1,5 segundos, de acordo com o [[scientific-notation|Scientific Notation Converter]] — que é a diferença entre um problema de latência e um artefato de arredondamento."]},{"h":"O que essas ferramentas deliberadamente não fazem"},{"p":"Não mostram trabalho e não ensinam. Se você precisa entender por que uma fórmula é verdadeira, uma calculadora é o instrumento errado – ela dá a resposta sem a razão, e é assim que as pessoas acabam sendo capazes de calcular e incapazes de raciocinar.\\n\\nEles também não fazem precisão arbitrária. Fatoriais e grandes fatorações perderão a precisão além do ponto em que a resposta ainda seja útil e uma guia do navegador não seja um sistema de álgebra computacional. Para qualquer coisa onde a correção realmente importe – engenharia, finanças, criptografia – use uma biblioteca adequada com aritmética exata, não uma página da web."},{"h":"Verificando sua própria aritmética"},{"p":"O hábito matemático mais valioso não é a velocidade, é a estimativa. Antes de acreditar em qualquer resultado, pergunte se é a ordem de grandeza correta: maior ou menor que a entrada, e aproximadamente em quanto. A maioria dos erros aritméticos sobrevive a todas as outras verificações, exceto esta.\\n\\nO arredondamento primeiro torna a estimativa gratuita. Arredonde 0,375 para 0,4, arredonde 5/8 para 0,6, e a proporção é obviamente de cerca de 2:3 – perto o suficiente de 3:5 para confirmar a fração que você calculou com exatidão. Se a resposta exata e a estimativa discordarem, você encontrou um erro de entrada em vez de um problema de arredondamento e o encontrou em segundos.\\n\\nÉ também por isso que uma calculadora não substitui pensar sobre o que você perguntou. Uma ferramenta calculará a quantidade errada perfeitamente, e a única defesa é saber como deve ser a resposta."},{"h":"Perguntas frequentes"},{"p":"**Minha entrada é enviada para algum lugar?** Não. Tudo isso é executado localmente no seu navegador.\\n\\n**Por que 0,1 mais 0,2 não é igual a 0,3?** Porque nem 0,1 nem 0,2 são exatamente representáveis ​​em ponto flutuante binário. A soma é 0,30000000000000004, que é o dobro mais próximo de 0,3.\\n\\n**Qual o tamanho de um fatorial que eles podem suportar?** Até 170 antes de exceder o intervalo de um duplo. Depois disso, a resposta é exibida em notação científica e deixa de ter sentido.\\n\\n**Posso usar a saída em código?** Sim. Para os resultados decimais para frações em particular, use aritmética inteira no numerador e denominador em vez de converter novamente para decimal."},{"h":"A versão de uma linha"},{"p":"Use frações exatas quando houver dinheiro envolvido, lembre-se de que os fatoriais explodem mais rápido do que o esperado e que a fatoração primária é tanto uma base de segurança quanto um truque para simplificar frações."}]},"everyday-utility-tools":{"title":"13 utilitários diários gratuitos: senhas, códigos QR, temporizadores e codificação de texto","description":"Gere senhas, crie códigos QR, execute cronômetros e relógios e decodifique textos binários, hexadecimais e cifrados — tudo isso com ferramentas de navegador gratuitas que são executadas localmente, sem necessidade de conta.","category":"Ferramentas utilitárias","blocks":[{"p":"Este último grupo é a gaveta de lixo. Senhas, códigos QR, cronômetro, relógio mundial, lançamento de moeda e quatro ferramentas que convertem texto em outras representações de si mesmo. Individualmente triviais, coletivamente o que você precisa em momentos difíceis.\\n\\nO segredo é que todos os treze sejam executados localmente. Para um gerador de senha, isso não é uma delicadeza - é a razão pela qual a ferramenta pode ser confiável."},{"h":"Senhas: a parte que realmente importa"},{"l":["[[password-generator|Password Generator]] — gera senhas aleatórias fortes de qualquer tamanho e conjunto de caracteres.","[[password-strength|Verificador de força de senha]] — estima a resistência de uma senha a ser adivinhada, localmente."]},{"b":"O fato mais importante sobre a força da senha: **o comprimento supera a complexidade e a reutilização supera ambos como um perigo.** Uma senha de 16 caracteres feita de palavras não relacionadas é mais forte e muito mais digitável do que uma confusão de símbolos de 10 caracteres. Enquanto isso, uma senha reutilizada que aparece em uma violação destrói todas as contas que toca de uma só vez. Gerar uma senha longa distinta por site é o trabalho completo."},{"p":"A forma como a força é estimada também é importante. A maioria dos verificadores se aproxima do tamanho do espaço de pesquisa, o que é um proxy razoável, mas não é a verdade: `CorrectHorseBatteryStaple` pontua bem em entropia, enquanto `P@ssw0rd1!` pontua bem em variedade de caracteres e mal na prática porque aparece em todas as listas de palavras do mundo.\\n\\nUse o gerador para qualquer coisa de seu interesse e, se precisar lembrar uma senha, use uma senha longa de quatro ou cinco palavras não relacionadas. Esse é o caso específico em que a memorabilidade e a força realmente se sobrepõem."},{"h":"Códigos QR: o que colocar neles"},{"l":["[[qr-code-generator|QR Code Generator]] — gera um código QR para uma URL, texto, detalhes de Wi-Fi ou informações de contato."]},{"p":"Os códigos QR são uma daquelas ferramentas em que a qualidade da saída é inteiramente determinada por uma decisão: a quantidade de dados que você insere. Um URL curto é codificado em um código pequeno e facilmente escaneável. Um parágrafo de texto com pontuação é codificado em algo denso e não confiável em tamanhos pequenos.\\n\\nDuas regras práticas. Primeiro, sempre teste o código no tamanho que ele realmente será impresso antes de imprimir duzentos deles. Em segundo lugar, os códigos Wi-Fi e URL simples se comportam de maneira diferente em telefones diferentes – se um código for direcionado a um público misto, prefira um URL simples a uma página de destino com links para frente, porque funciona em qualquer lugar e você pode alterar para onde ele aponta."},{"h":"Tempo: temporizadores, relógios e a armadilha nos fusos horários"},{"l":["[[cronômetro|Cronômetro Online]] — um cronômetro simples, útil quando seu telefone está na outra sala.","[[pomodoro-timer|Pomodoro Timer]] — Blocos de foco de 25 minutos com intervalos, para pessoas que acham que essa estrutura funciona.","[[relógio mundial|Relógio mundial]] — hora atual em várias cidades ao mesmo tempo."]},{"p":"O relógio mundial ganha seu lugar por um motivo específico: o horário de verão. Metade dos erros de programação do mundo não são erros aritméticos, são um momento em que duas cidades estavam separadas por quatro horas na semana passada e por cinco horas nesta semana, e ninguém verificou.\\n\\nAntes de programar qualquer coisa em um fuso horário, coloque ambas as cidades no relógio mundial e veja – não calcule o deslocamento da memória. É também por isso que os convites para reuniões devem conter um fuso horário em vez de uma hora."},{"p":"No cronômetro Pomodoro: a técnica funciona para um tipo específico de tarefa – limitada, focada, ininterrupta. Não funciona para depuração, onde o movimento correto quando travado é ir embora, e não iniciar outro bloco de 25 minutos. Use-o quando ajudar."},{"h":"Aleatoriedade, honestamente"},{"p":"O [[random-number|Random Number Generator]] e o [[list-randomizer|List Randomizer]] cobrem os casos que realmente surgem: escolher um número em um intervalo e colocar uma lista em uma ordem justa. Vale uma frase sobre justiça. Ambos usam um gerador pseudo-aleatório, que para decidir quem paga o almoço é indistinguível de uma moeda real. Para qualquer coisa importante – um sorteio com prêmios, uma alocação com dinheiro anexado – você quer uma fonte que possa auditar, e uma guia do navegador não é isso. O valor aqui é afastar o ser humano, que escolhe mal quando motivado."},{"h":"A gaveta de lixo eletrônico de codificação"},{"p":"Quatro ferramentas que movem texto entre representações. Nenhum deles é criptografado, e vale a pena afirmar a distinção porque é constantemente confundida: uma codificação é reversível por qualquer pessoa e não possui chave. A criptografia requer uma chave."},{"l":["[[binary-text|Binary to Text]] — converte entre texto e sua representação binária.","[[hex-text|Hex to Text]] — converte entre texto e hexadecimal, a representação que você vê com mais frequência em ferramentas de rede e depuradores.","[[cifra de césar|Cifra de césar]] — muda as letras em um valor fixo, a cifra clássica da sala de aula.","[[rot13-encoder|ROT13 Encoder]] — gira as letras em 13, um caso especial que é seu próprio inverso."]},{"p":"Eles são úteis exatamente para duas coisas. Primeiro, entender como o texto se transforma em bytes, que é o modelo mental necessário sempre que algo parecer distorcido. Em segundo lugar, realmente depurando: quando uma carga útil aparece como hexadecimal, o conversor [[hex-text|Hex to Text]] é como você descobre o que ela diz.\\n\\nEles não são úteis para esconder nada. ROT13 não tem chave – a mudança é pública – então não esconde nada de quem sabe o que é ROT13. A cifra de César tem 25 mudanças possíveis, que um humano quebra no primeiro minuto."},{"h":"Os dois que formatam as coisas"},{"l":["[[phone-formatter|Phone Number Formatter]] — normaliza os números de telefone em um formato consistente.","[[file-size-converter|Conversor de tamanho de arquivo]] — converte entre KB, MB, GB e TB, com a distinção decimal e binária explicada."]},{"p":"O conversor de tamanho de arquivo tem uma saída genuinamente valiosa: ele informa por que uma unidade anuncia um número maior do que o relatado pelo seu computador. Os fornecedores vendem em potências de dez, os sistemas operacionais relatam potências de dois e a diferença é de cerca de 7% em todas as escalas. Isso não é uma falha, são duas convenções."},{"h":"Um exemplo prático: a resposta distorcida da API"},{"p":"Um webhook está falhando na validação e a carga no log se parece com `\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f`. Este é um diagnóstico de noventa segundos."},{"l":["**1. Convert.** Cole `48656c6c6f` no conversor [[hex-text|Hex to Text]] — o resultado é `Hello`. Nunca foi distorcido, apenas codificado.","**2. Verifique a forma.** Algo upstream está codificando hexadecimal a carga útil antes de assinar. A assinatura foi calculada sobre o texto original e validada em relação ao hexadecimal, portanto a comparação falha.","**3. Exclua a outra direção.** Se o log tivesse mostrado texto legível, o problema teria sido o inverso: assinar o formulário codificado.","**4. Confirme a declaração de tamanho.** Se o mesmo log reportar uma carga útil de 1,2 MB, o [[file-size-converter|Conversor de tamanho de arquivo]] decide se é decimal ou binário antes que alguém discuta sobre uma cota."]},{"h":"Perguntas frequentes"},{"p":"**O gerador de senha é seguro se tudo rodar no navegador?** Sim, e mais do que um gerador baseado em servidor: a senha é gerada em sua máquina e nunca transmitida, portanto não há nada para interceptar, registrar ou violar. A desvantagem é que você não pode recuperar uma senha que não salvou.\\n\\n**Posso confiar no cara ou coroa virtual?** Para decisões casuais, sim. Para qualquer coisa que envolva dinheiro ou prêmios, use uma fonte que você possa auditar.\\n\\n**As cifras são seguras?** Não. Nenhuma delas. As cifras ROT13 e César não têm chave secreta e existem para ensinar codificação, não para proteger nada.\\n\\n**Isso funciona off-line?** Depois que a página é carregada, sim — tudo é local.\\n\\n**Existe limite de comprimento de texto para os conversores?** Apenas a memória do seu dispositivo, já que nada é enviado para lugar nenhum."},{"h":"A versão de uma linha"},{"p":"Senhas longas e exclusivas superam as curtas e inteligentes, um código QR é tão bom quanto os dados dentro dele, verifica as diferenças de fuso horário em vez de calculá-las, e codificação não é criptografia."}]}}')},5852,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"Инструментарий разработчика: 24 бесплатных браузерных инструмента, которые заменяют платные приложения","description":"Практическое руководство по форматированию, преобразованию, кодированию и отладке данных с использованием бесплатных инструментов разработчика на основе браузера — без установок и без учетных записей; большинство инструментов обрабатывают ввод локально.","category":"Инструменты разработчика","blocks":[{"p":"Большинство небольших задач, которые вы выполняете сто раз в неделю — переформатирование ответа API, декодирование токена, проверка хеша, изменение фрагмента SQL — не требуют IDE, платной подписки или командной лицензии. Им нужно, чтобы одна вкладка была открыта в течение девяноста секунд.\\n\\nВ приведенной ниже коллекции представлены двадцать четыре утилиты для браузера, предназначенные для форматирования, преобразования, кодирования, хеширования и отладки. Каждый из них полностью работает на вашей странице: ваши данные никогда не отправляются на сервер, что имеет большее значение, чем обычно признают разработчики, поскольку вставляемая вами полезная нагрузка обычно принадлежит клиенту."},{"h":"Какие браузерные инструменты могут и не могут заменить"},{"p":"Будьте реалистичны в отношении границ. Эти инструменты заменяют одноразовые, не требующие больших затрат и часто выполняемые работы. Они не заменяют ваш языковой сервер, отладчик, набор тестов или что-либо еще, что вам нужно для многократного запуска в реальной среде."},{"l":["**Подходит**: чтение ответа один раз, отладка одного значения, преобразование файла для одного импорта, проверка формата перед отправкой.","**Плохое соответствие**: выполнение одной и той же проверки при каждом развертывании, преобразование сотен файлов — все, что в CI должно привести к громкому сбою.","**Никогда:** все, что связано с учетными данными, которые нельзя менять. Вставьте отозванный токен, а не действующий."]},{"p":"С учетом вышесказанного, причина сохранить их в закладках — это пропускная способность. Задача, которая занимает сорок секунд во вкладке браузера, никогда не запланируется, никогда не делегируется и никогда не станет поводом открыть IDE в восемь вечера."},{"h":"Форматирование и преобразование данных"},{"p":"Самая распространенная ежедневная работа — сделать данные читаемыми. API возвращает однострочный объект, коллега отправляет файл конфигурации с вкладками, искаженными окном чата, или вы экспортировали электронную таблицу в JSON, и она вернулась в виде одной огромной строки."},{"l":["[[json-formatter|JSON Formatter]] — выравнивание, проверка и чтение полезных данных. Используйте его перед отладкой: половина всех заявок «API сломан» на самом деле представляет собой неверный формат JSON с завершающей запятой.","[[json-validator|JSON Validator]] — когда вам нужен строгий ответ «прошел/не прошел», а не красивая распечатка.","[[xml-formatter|XML Formatter]] — та же работа для ответов SOAP, RSS-каналов и POM Maven, которую никто не трогал с 2014 года.","[[json-to-yaml|JSON в YAML]] и [[json-to-csv|JSON в CSV]] — перемещение данных между форматами, которые фактически используют реальные системы."]},{"p":"Помните о последней группе для одного конкретного сценария: клиент передает вам электронную таблицу и ожидает ее в своем API. Преобразование CSV в JSON напрямую — это двухминутная работа, а не полдня написания сценариев."},{"h":"Кодирование и экранирование"},{"p":"Ошибки кодирования непропорционально раздражают, потому что данные выглядят нормально. Значение «San José & Sons» поступает как «San Jos%C3%A9 %26 Sons», и сравнение с базой данных завершается неудачно по причинам, невидимым в журналах."},{"l":["[[url-encoder|URL Encoder/Decoder]] — немедленно определить, является ли строка запроса двойной кодировкой.","[[base64-encoder|Base64 Encoder/Decoder]] — декодируйте фрагмент сертификата или закодируйте небольшой ресурс для встраивания в CSS.","[[html-entity-encoder|HTML Entity Encoder/Decoder]] — выясните, откуда взялся этот случайный знак «&» на вашей странице — из вашего шаблона или из ваших данных.","[[unicode-converter|Конвертер Юникода]] — полезно, когда «битый» символ оказывается допустимым, отображаемым в неправильной кодировке.","[[number-base-converter|Конвертер оснований чисел]] — проверьте цвет, битовую маску разрешения или адрес памяти без приложения-калькулятора."]},{"b":"Практическая привычка: когда значение приходит искаженным, декодируйте его послойно и вставляйте каждый результат в пустое поле. Если первое декодирование создает читаемый текст, проблема в одном дополнительном кодировании где-то выше. Если он создает моджибаке, у вас проблема с кодированием, а не с экранированием, и эти две проблемы требуют разных исправлений."},{"h":"Идентификаторы, хеши и токены"},{"p":"В этой группе разработчики тратят больше всего времени на поиск нужного локального скрипта, который они однажды написали и потеряли."},{"l":["[[uuid-generator|UUID Generator]] — генерирует идентификаторы v4 для начальных данных, фикстур или быстрой строки базы данных.","[[md5-generator|MD5/SHA Hash Generator]] — проверьте загрузку или подтвердите, что два файла, которые должны быть идентичны, на самом деле таковы.","[[timestamp-converter|Конвертер временных меток]] — единственный наиболее часто используемый инструмент во всем этом списке. Когда в строке журнала указано 1761000000, это указывает на то, произошел ли инцидент во время развертывания или до него."]},{"p":"Преобразователь временных меток заслужил свое существование по одной конкретной причине: номер эпохи однозначен и в то же время бесполезен. Вы точно знаете, когда что-то произошло, и не можете сказать об этом коллеге. Однократное обращение обычно разрешает более громкий спор, чем следовало бы."},{"h":"Сравнение и отладка"},{"l":["[[regex-tester|Тестер регулярных выражений]] — элемент с самым высоким кредитным плечом здесь. Регулярное выражение, которое выглядит корректно и ничего не соответствует ничему, является одной из самых дорогостоящих ошибок в разработке, поскольку оно молча дает сбой в одном месте, которое никто не читает.","[[html-preview|Предварительный просмотр HTML]] — перебирайте фрагмент разметки, чтобы проверить, как он на самом деле отображается."]},{"p":"Проверьте свои регулярные выражения на соответствие ожидаемым входным данным, включая пустую строку, имя в Юникоде и значение с новой строкой. Большинство закономерностей нарушаются в третьем случае, и никто этого не замечает, пока не поступят производственные данные."},{"h":"Проработанный пример: три инструмента, один скучный инцидент"},{"p":"Вот последовательность, которая убедила меня добавить все это в закладки. Клиент сообщил, что запись, отправленная им во вторник, отсутствовала в отчете в четверг."},{"l":["**1. Преобразуйте временную метку.** Задание отчета регистрировало время создания записи как значение эпохи. [[timestamp-converter|Timestamp Converter]] показал, что запись была создана в 23:00 по местному времени, то есть во вторник — проблема заключалась в предположении о часовом поясе задания, а не в записи.","**2. Отформатируйте полезную нагрузку.** Проведение сохраненного JSON через [[json-formatter|JSON Formatter]] показало, что запись была записана с нулевым полем даты, поскольку клиент дважды вызывал одну и ту же конечную точку с интервалом в 200 мс, и вторая запись выиграла.","**3. Сравните полезные данные.** Обе записи содержали один и тот же ключ API и одну и ту же метку времени клиента, что указывало на повторную попытку, а не на двух отдельных клиентов."]},{"p":"Общее затраченное время: четыре минуты. Предыдущая попытка этого расследования, направленная на поиск той же основной причины на платформе регистрации, заняла целый день и привела к неправильному выводу."},{"h":"Конфиденциальность: почему локальный запуск является актуальной функцией"},{"p":"Каждый инструмент в этой библиотеке обрабатывает вводимые вами данные внутри вашего браузера. Ничего не загружается, а это означает отсутствие вопросов об хранении, отсутствие соглашения об использовании процессора и отсутствие неприятных разговоров о производственной полезной нагрузке, которую вы вставили три минуты назад.\\n\\nИменно по этой причине эти инструменты предпочтительнее размещенного «pastebin API» или онлайн-сервиса, который просит вас зарегистрироваться. Это также означает, что они продолжают работать в полете, в подвале или когда корпоративная VPN решила заблокировать еще один домен."},{"p":"Одно предостережение, о котором стоит сказать прямо: страница, поддерживающая офлайн-режим, является частной только в том случае, если сама страница представляет собой код, который, как вы думаете, это так. На общей машине используйте личное окно и закройте его, когда закончите, особенно если вы декодировали токены."},{"h":"Построение рабочего процесса вокруг них"},{"p":"Инструменты по отдельности тривиальны. Ценность заключается в привычке немедленно обращаться к одному из них, а не «обращаться к нему позже», потому что позже вы пишете одноразовый сценарий, открываете IDE или решаете, что проверять вообще не стоит."},{"l":["Добавьте в закладки коллекцию, а не отдельные URL-адреса, и поместите ее на панель инструментов браузера.","Если что-то кажется неправильным, проверьте это, прежде чем строить теорию. Стоит пятнадцать секунд; убивает целые классы неправильных выводов.","Если вы дважды проверили одно и то же, это сигнал к автоматизации, но не автоматизируйте по подозрению.","Не выкладывайте секреты производства. Поверните все, в чем вы не уверены."]},{"h":"Часто задаваемые вопросы"},{"p":"**Эти инструменты бесплатны?** Да, полностью, без учетной записи и без ограничений на использование. Нет никакого платного уровня, сдерживающего что-то базовое.\\n\\n**Работают ли они офлайн?** Да, после загрузки страницы все работает в вашем браузере. Для перезагрузки требуется соединение.\\n\\n**Могу ли я использовать их в коммерческих целях?** Да. Результат принадлежит вам без каких-либо требований об указании авторства.\\n\\n**Есть ли API?** Нет, и это сделано намеренно: ценностью является интерфейс. Экспортируйте выходные данные и обрабатывайте их по своему усмотрению.\\n\\n**Почему бы просто не установить вместо этого инструмент CLI?** Установите его, когда он вам понадобится три раза. Используйте вкладку браузера для первых двух."}]},"text-tools-for-writers":{"title":"17 бесплатных текстовых инструментов для писателей, студентов и маркетологов","description":"Наводите порядок в текстах, точно подсчитывайте слова, форматируйте списки и превращайте черновики в нечто пригодное для публикации — с помощью бесплатных инструментов для браузера, которые запускаются локально в вашем браузере.","category":"Текстовые инструменты","blocks":[{"p":"Написание текста для работы включает в себя удивительное количество рутинной механической работы, не имеющей ничего общего с письмом: удаление случайных пробелов из вставленного абзаца, проверка ограничения на количество слов, дедупликация списка имен, преобразование чего-либо в URL-адрес.\\n\\nЭти семнадцать инструментов предназначены для этой части работы. Все они запускаются локально в браузере, что немаловажно: вставляемый вами черновик часто не публикуется, а список, который вы сортируете, часто представляет собой чьи-то личные данные."},{"h":"Измеряю то, что вы написали"},{"p":"Подсчет слов кажется решенным до тех пор, пока клиент не запросит ровно 800 слов, а ваш редактор не скажет 820, или пока форма не отклонит ваш текст длиной 1995 символов без объяснения того, где находится перевод строки."},{"l":["[[word-counter|Счетчик слов]] — стандартная мера. Вставьте, прочтите, настройте.","[[letter-counter|Счетчик букв]] — подсчитывает символы и частоту букв. Полезно, когда вы выясняете, почему один абзац кажется неправильным: обычно это повторяющийся шаблон букв, а не сон."]},{"p":"Примечание о том, что означает «слово»: разные счетчики расходятся во мнениях относительно расстановки переносов, цифр и URL-адресов. Если точное число имеет значение, используйте тот же счетчик, который использует человек, проверяющий вашу работу, и договоритесь об этом заранее. Это действительно распространенный источник мелких и бессмысленных споров."},{"h":"Очистка текста, который вы не писали"},{"p":"Большая часть текста, который вы получаете, слегка повреждена: двойные пробелы из-за копирования и вставки, случайная табуляция, неправильная заглавная буква из-за того, что кто-то печатает в спешке. Исправлять это вручную — медленно и чревато ошибками."},{"l":["[[text-trimmer|Триммер текста]] — удалить начальные и конечные пробелы из каждой строки одновременно. Это исправляет больше отчетов «форматирование выглядит нарушенным», чем что-либо еще в этом списке.","[[text-case-converter|Конвертер регистра текста]] — переключение между регистром предложений, регистром заголовка, верхним и нижним регистром по всему блоку. Также это самый быстрый способ отменить случайный абзац, набранный CAPS LOCK.","[[text-to-slug|Отправьте текст в Slug]] — превратите заголовок в чистый фрагмент URL-адреса. Вставьте заголовок, получите ссылку, готово."]},{"p":"У генератора слагов есть еще одно применение, помимо URL-адресов: это быстрый способ создать читаемое имя файла или привязку, которую человек может проанализировать с первого взгляда, что превосходит `final_final_v3`."},{"h":"Работа со списками"},{"p":"Списки, инвентаризации, слияния писем, очистка тегов, ответы на опросы, столбцы электронных таблиц — в какой-то момент все становится списком, и каждый список требует сортировки, дедупликации или рандомизации."},{"l":["[[duulate-line-remover|Удаление повторяющихся строк]] — сравнить два списка или очистить один. В выводе указано, сколько дубликатов было удалено, что полезно при сообщении о результате.","[[list-sorter|Сортировщик списков]] — то же задание для ввода структурированного списка.","[[list-randomizer|List Randomizer]] — перетасуйте порядок жеребьевки, последовательность викторин или изолированный короткий список, чтобы никто не заподозрил фаворитизма.","[[line-number-adder|Сумматор номера строки]] — количество строк для ссылки в заявке или комментарии к обзору кода."]},{"b":"Классическая ловушка здесь — это список, который выглядит дедуплицированным, но на самом деле таковым не является: «Apple», «apple» и «Apple.» — это три разные строки для компьютера. Перед дедупликацией обрезайте пробелы и конечные знаки препинания, иначе вы ничего не объедините и придете к выводу, что данные чисты."},{"h":"Предварительный просмотр и форматирование"},{"p":"Markdown победил, но не всегда. Половина ваших инструментов отображает его, половина — нет, а половину, которая не делает, обычно вставляет кто-то из старших."},{"l":["[[markdown-preview|Markdown Preview]] — рендеринг в реальном времени, поэтому вы можете проверить, действительно ли таблица или вложенный список выглядят непосредственно перед тем, как они достигнут клиента.","[[text-repeater|Повторитель текста]] — повторить строку N раз. Полезно для создания заполнения, тестовых данных или, иногда, для выделения точки в документе."]},{"p":"Предварительный просмотр Markdown — это инструмент, который незаметно экономит больше всего времени во всем этом наборе, потому что сломанная таблица в визуализированном документе гораздо более заметна — и гораздо более смущает — чем сломанная таблица в необработанном тексте."},{"h":"Остальное и когда к ним обращаться"},{"l":["[[random-string|Генератор случайных строк]] — генерирует читаемые одноразовые номера, идентификаторы-заполнители или короткие коды. Лучше, чем изобретать что-то вручную, потому что вы случайно не будете использовать это повторно.","[[morse-code|Переводчик азбуки Морзе]] — действительно весело, иногда полезно для тематического проекта или головоломки."]},{"p":"Это низкочастотные инструменты, но их добавление в закладки ничего не стоит и они решают конкретную проблему: «Мне нужно случайно выглядящее значение прямо сейчас, и я не уверен, что смогу его придумать»."},{"h":"Реалистичный проход редактирования"},{"p":"Вот порядок, который работает, когда черновик приходит от кого-то другого и должен быть опубликован под вашим именем."},{"l":["**1. Обрезать.** Сначала пропустите весь документ через [[text-trimmer|Text Trimmer]]. Ущерб от пробелов скрывается внутри абзацев, где вы его никогда не увидите.","**2. Чистый регистр.** Используйте [[text-case-converter|Конвертер регистра текста]] только для заголовка. Никогда не применяйте преобразование падежа к полному черновику — оно уничтожает имена собственные.","**3. Измерьте.** Перед тем, как писать, проверьте длину с помощью [[word-counter|Word Counter]], чтобы знать, какой формы должен быть фрагмент.","**4. Предварительный просмотр.** Если он содержит Markdown, отобразите его с помощью [[markdown-preview|Markdown Preview]].","**5. Slug.** Создайте фрагмент URL-адреса последним, из окончательного заголовка, с помощью [[text-to-slug|Text to Slug]] — изменение заголовка после этого приводит к разрыву фрагмента."]},{"p":"Весь процесс занимает несколько минут и исключает ту категорию ошибок, когда документ является технически правильным и явно ошибочным."},{"h":"Вопросы писателей о конфиденциальности"},{"p":"**Покидает ли мой неопубликованный текст мой компьютер?** Нет. Эти инструменты обрабатывают текст в вашем браузере, и ничего не сохраняется и не передается.\\n\\n**Существует ли ограничение на длину?** Ограничений на стороне сервера нет, поскольку нет вызова сервера. Чрезвычайно большие входы ограничены памятью вашего устройства.\\n\\n**Могу ли я использовать результаты в коммерческих целях?** Да, бесплатно, без указания авторства.\\n\\n**Они работают на телефоне?** Да. Макет адаптируется, и запускается тот же код."},{"h":"Чего эти инструменты вам не сделают"},{"p":"Стоит прямо сказать об ограничениях, потому что инструмент, который механизирует неправильные вещи, приводит к более быстрой ошибке.\\n\\nНи одна из этих утилит не может сказать вам, ясно ли предложение, есть ли источник утверждения или подходит ли тон аудитории. Они считают персонажей; они не судят прозу. Текст, который имеет хорошие оценки по всем показателям на этой странице, все равно может оказаться нечитаемым.\\n\\nИ они не редактируют. В тот момент, когда вы обнаружите, что переписываете отдельные предложения вручную в большом масштабе, вы переросли текстовый инструмент и вам нужен либо правильный редактор, программа поиска и замены с регулярным выражением — для которой действительно хорош [[regex-tester|Regex Tester]] — либо скрипт. Используйте браузер для механического уровня и сохраняйте собственное суждение обо всем, что находится над ним."},{"p":"Еще одна вещь, которую они не сделают, — это исправить плохой источник. Если ваша таблица полна противоречивых имен — «Доктор», «ДР», «Доктор». все в одном столбце — инструмент добросовестно отсортирует и дедуплицирует то, что вы ему предоставили, и у вас все равно останется три записи там, где должна быть одна. Очистка данных — это решение, а не механический шаг. Сначала определите каноническую форму, затем примените ее, затем проверьте."},{"h":"Поддержание рабочего списка в рабочем состоянии"},{"p":"Если вы ведете список потенциальных клиентов, ссылок, ссылок или терминов, он постепенно ухудшается. Режим сбоя всегда один и тот же: записи, которые выглядят одинаково, не являются таковыми, и одно слияние ничего не удаляет.\\n\\nРаботающий проход обслуживания скучен: обрежьте пробелы, стандартизируйте заглавные буквы, удалите конечные знаки препинания, а затем удалите дубликаты. В таком порядке — обрезка после дедупликации приводит к потере записей. Если делать это раз в месяц в активном списке, двухчасовой неисправимый беспорядок превращается в десятиминутную рутинную работу.\\n\\nКогда необходимо согласовать два списка — скажем, список регистрации со списком посещаемости — сначала отсортируйте оба с помощью [[list-sorter|List Sorter]], чтобы они выстроились в линию, а затем сравните их на глаз. Сортировка обеих сторон перед сравнением — это разница между двухминутной проверкой и двадцатиминутным поиском."},{"h":"Вывод"},{"p":"Ни один из этих инструментов не является умным. В том-то и дело: они удаляют механические пять процентов письма, которое не является письмом, так что оставшиеся девяносто пять процентов фактически составляют предложения. Добавьте в закладки те, которые используете ежемесячно, игнорируйте остальные и перестаньте исправлять пробелы вручную."}]},"calculators-and-converters-guide":{"title":"18 бесплатных калькуляторов и конвертеров чисел, с которыми вы действительно имеете дело","description":"Проценты, скидки, чаевые, кредиты, даты, ИМТ и конвертация единиц — бесплатные браузерные калькуляторы, которые показывают обоснование без необходимости учетной записи.","category":"Калькуляторы","blocks":[{"p":"Каждому нужно разделить счет, выяснить, действительно ли скидка является скидкой, и преобразовать температуру или размер файла, не задумываясь об этом. Каждый, по крайней мере, однажды ошибается на публике.\\n\\nЭто коллекция из восемнадцати калькуляторов и конвертеров, охватывающих деньги, даты, здоровье и преобразования единиц измерения, которые проявляются в работе и путешествиях. Все они запускаются в браузере: ничего не сохраняется, поэтому вводимые вами цифры никого не касаются, кроме вас."},{"h":"Денежные расчеты"},{"p":"Самая распространенная реальная математика — это процент от чего-то. Налог с продаж, чаевые, стек скидок, комиссия, темп роста. Формула проста, но причина, по которой люди ошибаются, почти всегда одна и та же: они применяют процент к неправильной базе."},{"l":["[[discount-calculator|Калькулятор скидок]] — рассчитайте окончательную цену и, что более важно, сколько вы сэкономили. Полезно для определения «скидки 50%», которая на самом деле составляет 20% после повышения прейскурантной цены.","[[tip-calculator|Калькулятор чаевых]] — разделите счет, выберите процент, округленный на человека, если хотите.","[[loan-calculator|Кредитный калькулятор]] — ежемесячный платеж и общая сумма процентов, то есть число, которое фактически определяет, является ли кредит доступным."]},{"b":"О скидках: скидка 20 %, за которой следует еще скидка 20 %, — это не скидка 40 %, а 36 %. Последовательные проценты начисляются по уменьшенной базе. Любой калькулятор из этого списка подтвердит это примерно за две секунды, и это самый полезный арифметический факт в этой статье."},{"p":"Кредитный калькулятор заслуживает отдельного упоминания. Значение имеет не ежемесячный платеж, а общая сумма процентов, выплачиваемых в течение срока действия кредита, потому что это реальная стоимость займа. Два кредита с одинаковыми ежемесячными платежами и разными условиями могут отличаться по общей сумме процентов на десятки тысяч."},{"h":"Даты и обратный отсчет"},{"p":"Большинство людей молча ошибаются в арифметике дат, потому что человеческие месяцы имеют разную длину, и ответ меняется в зависимости от того, имеете ли вы в виду «календарные месяцы» или «30 дней»."},{"l":["[[date-difference|Калькулятор разницы дат]] — количество дней (и всего месяцев, лет) между двумя датами.","[[days-until|Калькулятор дней до]] — обратный отсчет до определенной даты, при этом количество рабочих дней обычно соответствует тому, что люди действительно хотят.","[[age-calculator|Калькулятор возраста]] — точный возраст в годах и днях, плюс ближайший день рождения.","[[timestamp-converter|Конвертер временных меток]] — временная метка Unix в реальную дату, которая имеет значение, если вы касаетесь журналов, баз данных или ответов API."]},{"p":"Разница, которая сбивает людей с толку: количество дней между 1 марта и 1 апреля равно 31, а количество *месяцев* — один. Если вы рассчитываете период уведомления или срок подписки, укажите в письменном виде, какую единицу вы имеете в виду."},{"h":"Цифры здоровья, честно говоря"},{"l":["[[bmi-calculator|Калькулятор ИМТ]] — индекс массы тела со стандартными категориями и оговорками ниже."]},{"p":"ИМТ — это статистика скрининга на уровне населения. Он ничего не говорит о мышечной массе, составе тела или здоровье человека и является плохим показателем физической подготовки спортсменов, пожилых людей и представителей разных этнических групп. Используйте его как одну из нескольких точек данных или как способ отслеживать изменения с течением времени, а не как приговор. Если вы принимаете решения, влияющие на ваше здоровье, правильный инструмент — это врач, а не вкладка браузера."},{"h":"Преобразование единиц измерения: повседневные"},{"p":"Преобразование единиц измерения делится на два вида: преобразования, которые вы должны выполнить точно правильно, и преобразования, которые вам нужны примерно. Эти инструменты справляются с обоими задачами, и работа заключается в запоминании того, что есть что."},{"l":["[[length-converter|Конвертер длины]] — метрическая система в британскую и обратно: миллиметры, сантиметры, метры, километры, дюймы, футы, ярды, мили.","[[weight-converter|Конвертер веса]] — граммы, килограммы, унции, фунты, тонны. Тот, который нужно проверить перед рецептом или транспортной этикеткой.","[[temperature-converter|Конвертер температуры]] — Цельсий, Фаренгейт, Кельвин. Потому что -10°C — это не 14°F, и формула не является умножением.","[[speed-converter|Конвертер скорости]] — км/ч, мили в час, м/с, узлы. Полезно для иностранного ограничения скорости или технических требований.","[[area-converter|Конвертер площадей]] — квадратные метры, квадратные футы, акры, гектары. Это то, что люди плохо оценивают при покупке или аренде недвижимости.","[[volume-converter|Конвертер объёма]] — литры, миллилитры, галлоны, чашки, кубические метры.","[[time-converter|Конвертер времени]] — секунды, минуты, часы, дни, недели."]},{"b":"Две ловушки конверсии, о которых стоит знать: упомянутая выше, связанная с хранением данных (маркетологи продают 10^3, операционные системы сообщают 2^10) и экономия топлива — автомобиль, указанный за 40 миль на галлон (британские стандарты), ближе к 33 милям на галлон (США), чем к 40, потому что британский галлон больше. Ошибка во втором случае делает арендованный автомобиль нереально эффективным."},{"h":"Два, которые вам не понадобятся"},{"l":["[[random-number|Генератор случайных чисел]] — розыгрыш в пределах диапазона для лотереи, сетки или быстрого разделения A/B. Полезно именно потому, что устраняет подозрения, что вы его подстроили.","[[dice-roller|Dice Roller]] — любой кубик от подбрасывания монеты до двадцатигранного кубика, для настольной игры или настольной игры, когда настоящий кубик укатился со стола в последний раз."]},{"h":"Правильно пользуемся калькулятором"},{"p":"Калькулятор помогает только в том случае, если вы знаете, о каком числе спрашиваете. Три привычки имеют значение."},{"l":["**Сначала округлите, потом вычислите.** Если точное число не повлияет на ваше решение, используйте округление. Проценты круглых чисел можно проверить в голове, которая выявляет ошибки ввода.","**Проверьте величину.** Прежде чем поверить в результат, спросите, должен ли он быть больше или меньше входных данных и примерно на сколько. Большинство арифметических ошибок выдерживают любую проверку, кроме этой.","**Фотографируйте входные данные, а не выходные данные.** Когда вы позже повторите расчет, важно знать, что вы предполагали, а не какой вывод сделали."]},{"h":"Вопросы, которые люди на самом деле задают"},{"p":"**Мои номера хранятся где-нибудь?** Нет. Расчеты происходят в вашем браузере, и ничего не передается и не сохраняется.\\n\\n**Работают ли они на телефоне?** Да, калькуляторы созданы для использования одной рукой.\\n\\n**Какой стандарт преобразования вы используете для хранения данных?** Десятичный размер (1 КБ = 1000 байт) по умолчанию, поскольку именно так продается хранилище. Операционные системы сообщают о двоичном формате, поэтому кажется, что диск сжимается — инструмент объясняет разницу, а не молча выбирает сторону.\\n\\n**Могу ли я встроить их на свой сайт?** Нет. Вместо этого добавьте их в закладки; стоимость этого равна нулю, а проблема с точностью остается только за вами."},{"h":"Проценты: четыре ошибки, которые имеют значение"},{"p":"Почти каждая процентная ошибка, которую человек допускает в повседневной жизни, — это одна из тех же четырех ошибок. Если дать им название, их можно избежать."},{"l":["**Неправильная база.** «Подъем на 10%, а затем падение на 10% оставляет вас там, где вы начали» неверно, поскольку оба варианта применимы к разным базам. Десять процентов от 100 — это 10; десять процентов от 90 — это 9.","**Процент от процента.** Суммирование двух скидок умножает их (0,8 × 0,8 = 0,64, то есть скидка 36%), а не суммирует.","**Проценты в сравнении с процентными пунктами.** Ставка с 4% до 6% выросла на 2 процентных пункта, но в относительном выражении на 50%. Политика и медицина полны этой путаницы, и она не всегда случайна.","**Слишком раннее округление.** Округление промежуточного шага перед применением процентного значения приводит к увеличению ошибки. Сохраняйте полную точность до окончательного результата и делайте последний шаг на калькуляторе, а не в уме."]},{"p":"Если вы возьмете только одну привычку из всего этого раздела, возьмите вот эту: прежде чем называть кому-либо процент, еще раз сформулируйте, что это за процент *от*. Половина аргументов, которые у вас когда-либо возникнут по поводу числа, на самом деле являются аргументами о знаменателе."},{"h":"Знать, когда прекратить расчеты"},{"p":"Есть момент, когда точность перестает быть полезной. Ежемесячный платеж с точностью до двух знаков после запятой имеет смысл. Прогнозируемая общая стоимость с точностью до восьми знаков после запятой — это способ избежать фактического решения, а именно, соответствует ли кредит тому, что вы можете себе позволить без стресса.\\n\\nПолезным тестом является вопрос о чувствительности: изменится ли решение, если этот входной сигнал изменится на 10%? Если нет, прекратите уточнять его и используйте дополнительное время для переменной, которая действительно меняет ответ — обычно это срок, а не ставка, или прейскурантная цена, а не скидка."},{"p":"И одну границу стоит обозначить прямо: эти калькуляторы предназначены для арифметики, а не для советов. Цель сбережений, дата выхода на пенсию и план погашения долга — все это решения, связанные с риском, поведением и временем, и вкладка браузера не может оценить ни одно из них. Он сможет сказать вам, что означают цифры, только после того, как вы решите, что предполагаете. В этом различии заключается разница между полезностью калькулятора и ответственностью."},{"h":"Однострочная версия"},{"p":"Правильно добавьте в закладки калькуляторы денег и дат, относитесь к ИМТ как к одному сигналу, а не как к приговору, помните, что сложенные проценты умножаются, и проверяйте преобразование единиц всякий раз, когда число переходит в какое-либо договорное значение. Это охватывает почти все."}]},"image-and-design-tools":{"title":"14 бесплатных инструментов для работы с изображениями и дизайном, которые работают в вашем браузере","description":"Сжимайте, изменяйте размер и подготавливайте изображения, а также создавайте эффекты CSS, палитры, проверки контрастности и значки без установки Photoshop или пакета дизайна.","category":"Инструменты проектирования","blocks":[{"p":"У имиджевой работы есть специфическая проблема: работа обычно небольшая, а предлагаемые инструменты огромны. Вам нужно убрать 400 КБ с главного изображения, или получить шестнадцатеричное значение, упомянутое вашим дизайнером, или создать значок, который еще никто не создал. Для этого не требуется подписка.\\n\\nЧетырнадцать инструментов, представленных ниже, охватывают подготовку изображений, работу с цветом, создание CSS-эффектов и небольшие производственные ресурсы, которые остаются незамеченными. Каждый из них запускается локально, что важнее для изображений, чем для текста: фотография, которую вы только что сжали, часто является фотографией, которую вы еще не опубликовали."},{"h":"Подготовка изображений для Интернета."},{"p":"Большинство проблем с имиджем на самом деле связаны с весом. Страница, которая кажется медленной, обычно содержит изображения, размер которых превышает размер дисплея, в неправильном формате и с настройками качества, которые никто никогда не подвергал сомнению."},{"l":["[[image-compressor|Image Compressor]] — уменьшить размер файла, сохраняя при этом визуальное изображение. Запустите его, прежде чем загружать что-либо в форму с ограничением размера.","[[image-resizer|Image Resizer]] — установите нужные вам фактические размеры в пикселях. Это большая победа: изображение размером 4000 пикселей, отображаемое с разрешением 800 пикселей, несет в пять раз больше необходимых данных.","[[image-to-base64|Изображение в Base64]] — преобразуйте небольшое изображение в URI данных для встраивания в CSS, HTML или шаблон электронной почты."]},{"b":"Порядок имеет значение. Сначала измените размер, затем сожмите. Сжатие изображения размером 4000 пикселей создает гораздо более тяжелый файл, чем изменение размера до 800 пикселей и последующее сжатие с тем же качеством, поскольку компрессоры тратят свои усилия на пиксели, которые в любом случае будут выброшены."},{"p":"Насколько сильно следует сжимать? Честный ответ: пока что-то не выглядит неправильным, тогда отступите на шаг. Для главного фотографического изображения качество от 70 до 80 процентов обычно неотличимо от оригинала при нормальном размере просмотра. Для логотипа, скриншота или чего-либо еще с плоским цветом и четкими краями используйте PNG и сжимайте сильнее — они выигрывают больше и теряют меньше."},{"p":"Практическое правило: для главного изображения подойдет все, что меньше 200 КБ, для миниатюры — меньше 80 КБ, а если вы не можете получить размер менее 300 КБ, то, вероятно, у вас проблема с размером, а не с качеством."},{"h":"Base64: когда встраивание — правильный вызов"},{"p":"Преобразование изображения в URI данных Base64 удаляет HTTP-запрос, что звучит как чистая победа. Обычно это не так. Закодированная строка примерно на треть больше, чем двоичный файл, ее нельзя кэшировать отдельно, и она раздувает ваш CSS или HTML.\\n\\nВстроенное только тогда, когда изображение небольшое (менее нескольких килобайт) используется один раз и является критическим. Крошечный значок в одном шаблоне электронного письма — классический случай. Если что-либо повторяется на страницах или превышает несколько килобайт, сохраните это как файл и позвольте браузеру кэшировать его."},{"h":"Водяные знаки: что можно честно удалить"},{"l":[]},{"p":"Четко объясните, что это делает. Он удаляет или скрывает видимую отметку. Он не может восстановить основные пиксели — закрашенная информация исчезает, и никакой фильтр не создает ее обратно. Результаты варьируются от невидимых, когда метка находится на простом фоне, до явного размазывания, когда она находится на деталях.\\n\\nЕще одна вещь, о которой стоит сказать прямо: удаление чужого водяного знака и публикация результата — это проблема авторских прав в большинстве юрисдикций и нарушение лицензии, независимо от того, попадетесь ли вы. Этот инструмент предназначен для удаления пометок с ваших собственных изображений или изображений, на которые вы лицензировали."},{"h":"Цвет: преобразование, проверка, выбор"},{"p":"Цвет — это то место, где небольшие ошибки становятся очень заметными. Коэффициент контрастности, который не доступен, шестнадцатеричное значение, которое на самом деле является тройкой HSL, палитра, которая выглядит связной на вашем мониторе и мутной на проекторе."},{"l":["[[color-converter|Конвертер цветов]] — перемещение между HEX, RGB и HSL. HSL стоит научиться читать, потому что оттенок 210, насыщенность 40 процентов, яркость 50 процентов гораздо проще настроить вручную, чем шестнадцатеричное значение.","[[contrast-checker|Проверка контрастности]] — проверка текста на фоне на соответствие порогам WCAG. Это единственный наиболее полезный инструмент в этой статье, поскольку он решает реальную проблему соответствия, а не проблему вкуса.","[[color-palette|Генератор цветовой палитры]] — сгенерируйте согласованный набор, если вы начинаете с фирменного цвета и вам нужна остальная часть шкалы."]},{"b":"Напротив, WCAG AA требует 4,5 к 1 для обычного основного текста и 3 к 1 для крупного текста. Если вы выбираете для кнопки один из двух фирменных цветов, доступный обычно не тот, который нравится дизайнеру. Сначала проверьте, а затем аргументируйте данные."},{"p":"Одно предостережение относительно инструментов цвета: все они предполагают, что ваш монитор откалиброван и что у человека, просматривающего вашу страницу, работают глаза. Ни одно из предположений не является безопасным. Это причина предпочитать проверенные по контрасту комбинации субъективным."},{"h":"Эффекты CSS без открытия инструмента дизайна"},{"p":"Написание градиента или многослойной тени вручную — действительно неприятная задача. Синтаксис сложен, вы не можете видеть, что создаете, а разница между хорошей тенью и плохой — несколько пикселей размытия."},{"l":["[[gradient-generator|Генератор градиентов CSS]] — создавайте линейные и радиальные градиенты и напрямую копируйте CSS.","[[box-shadow-generator|Box Shadow Generator]] — наложение нескольких теней, которые отделяют небольшую возвышенность от сильного падения.","[[border-radius-generator|Генератор радиуса границы]] — получите асимметричные радиусы, которые придадут форме преднамеренный вид.","[[text-shadow-generator|Генератор текстовых теней]] — полезен в редких случаях. Большинство теней текста слишком сильные; это позволяет вам настраивать смещение и размытие до тех пор, пока оно не исчезнет."]},{"p":"Уловка для всех четырех — сдержанность. Две тени — плотная темная и широкая мягкая — воспринимаются как физическое возвышение. Одна тень читается как веб-сайт пятнадцатилетней давности. Создавайте, копируйте, затем удаляйте до тех пор, пока вы не сможете определить его наличие."},{"h":"Производственные активы, о которых все забывают"},{"l":["[[favicon-generator|Favicon Generator]] — создайте небольшой набор значков, который действительно нужен сайту. Он находится в списке, потому что значки — это актив, который, скорее всего, полностью отсутствует, а отсутствующий значок отображает общий значок страницы браузера, из-за которого готовый сайт выглядит незавершенным.","[[emoji-picker|Emoji Picker]] — просматривайте, ищите и копируйте смайлы без поиска в средстве выбора операционной системы. Действительно полезно, когда вы пишете текст, для которого нужен один конкретный символ."]},{"h":"Проработанный пример: доставка главного раздела"},{"p":"Вот весь кластер делает одну настоящую работу. На странице нужен герой с фоновым изображением, заголовком и кнопкой, но ничего из этого еще не создано."},{"l":["**1. Зарезервируйте место.** Присвойте слоту изображения фиксированную высоту в макете, чтобы страница имела правильную форму с первого рендеринга, а не прыгала при приземлении реального изображения.","**2. Измените размер и сожмите.** Когда появится настоящая фотография, пропустите ее через [[image-resizer|Image Resizer]] шириной 1600 пикселей, а затем через [[image-compressor|Image Compressor]] с шириной 75 процентов. Это файл, который вы можете отправить.","**3. Проверьте контрастность текста.** Заголовок над фотографией — классический провал контраста. Используйте [[contrast-checker|Проверка контрастности]], чтобы выбрать либо темную интенсивность наложения, либо светлый цвет текста, соответствующий AA.","**4. Создайте кнопку.** [[box-shadow-generator|Box Shadow Generator]] задает высоту, а [[color-converter|Color Converter]] преобразует цвет бренда в формат, необходимый CSS.","**5. Ship.** Добавьте значок из [[favicon-generator|Favicon Generator]], чтобы вкладка не выглядела заброшенной, и раздел готов."]},{"p":"Пять инструментов, никакого пакета проектирования, и каждый результат — это значение, которое можно вставить прямо в код."},{"h":"Часто задаваемые вопросы"},{"p":"**Мои изображения загружаются куда-нибудь?** Нет. Сжатие, изменение размера и преобразование Base64 выполняются в вашем браузере, поэтому здесь нет ограничений на размер файла и очереди на загрузку.\\n\\n**Потеряет ли качество сжатие изображения?** Всегда, по определению. Вопрос в том, видно ли это. При качестве от 70 до 80 процентов и правильных размерах это обычно не так.\\n\\n**Почему мое изображение с измененным размером по-прежнему выглядит большим?** В девяти случаях из десяти вы сжимаете изображение перед изменением размера или сохраняете его в формате PNG, если фотография лучше в формате JPEG.\\n\\n**Могу ли я использовать их для работы с клиентами?** Да, без указания авторства и коммерческих ограничений.\\n\\n**Работают ли они на телефоне?** Да, хотя изменение размера и сжатие больших фотографий на телефоне зависит от памяти вашего устройства, а не от сервера."},{"h":"Однострочная версия"},{"p":"Изменяйте размер перед сжатием, проверяйте контрастность, прежде чем спорить о цвете, сохраняйте тени тонкими и никогда не забывайте о значке. В любом случае это большая часть того, что пакет дизайна сделал для вас."}]},"math-tools-for-real-numbers":{"title":"6 бесплатных математических инструментов для чисел, которые не работают","description":"Научное представление, десятичные дроби, проверка простых чисел, факториалы и GCF/LCM — бесплатные инструменты браузера для работы с числами, в которых легко ошибиться.","category":"Математические инструменты","blocks":[{"p":"Математика, которая вам действительно нужна на компьютере, — это не та математика, по которой вас экзаменовали. Это: находится ли это число в том формате, который ожидает система, упрощена ли эта дробь, как быстро она растет и почему калькулятор и электронная таблица расходятся во мнениях.\\n\\nЭти шесть инструментов охватывают эту территорию. Они работают локально, что с точки зрения арифметики означает одно конкретное преимущество, о котором стоит упомянуть: введенный вами номер никуда не отправляется, поэтому вы можете, не задумываясь, проверить расчет, включающий зарплату, баланс или количество клиентов."},{"h":"Приведение чисел в форму, которую принимает машина"},{"p":"Компьютеры хранят десятичные дроби как двоичные. 0,1 не совсем представимо в двоичном виде — ближайшее значение двойной точности — 0,1000000000000000055511151231257827. Добавьте 0,1 + 0,2, и вы получите 0,30000000000000004, что по умолчанию печатается как 0,3 и незаметно нарушает проверку равенства."},{"l":["[[scientific-notation|Конвертер научной нотации]] — переход от стандартной к научной форме, именно так большинство журналов, электронных таблиц и API фактически хранят большие и малые числа.","[[decimal-fraction|Десятичная дробь в дробь]] — преобразовать десятичную дробь в точную дробь. Это решение описанной выше проблемы: 0,1 + 0,2 в точной арифметике дробей равно 3/10, а не приближению."]},{"b":"Если вы когда-либо видели сумму, которая ошибочна на 0,0000000000000004, то вот почему. В финансовом коде стандартный ответ — работать с целыми центами или с десятичной библиотекой, а не с плавающей запятой. Если вы когда-нибудь видели, чтобы электронная таблица расходилась со сценарием на долю копейки, то это та же самая ошибка, но в другой шляпе."},{"p":"Научными обозначениями стоит владеть свободно, потому что это разница между чтением строки журнала и щурящимся взглядом. 6.022e23, 1.6e-19 и 3e8 — число Авогадро, элементарный заряд и скорость света. Если они выглядят как шум, а не как числа, преобразование некоторых из них с помощью инструмента исправляет ситуацию навсегда."},{"h":"Простые числа и почему это кого-то волнует"},{"l":["[[prime-checker|Проверка простых чисел]] — проверьте, является ли число простым, и посмотрите его факторизацию, если это не так.","[[gcf-calculator|GCF LCM Calculator]] — наибольший общий делитель и наименьшее общее кратное."]},{"p":"Простые числа — это не школьное упражнение. Безопасность каждого HTTPS-соединения, которое вы устанавливаете, зависит от того, что умножить два больших простых числа легко, а разложить результат обратно на множители сложно. Эта асимметрия является основой RSA.\\n\\nВ повседневных целях проверка простых чисел в основном касается дробей. Упрощение дроби означает деление верхней и нижней части на их наибольший общий делитель, и вы не сможете найти это без факторизации. Вот почему эти два инструмента подходят друг другу: проверьте факторы, затем получите GCF и LCM за один шаг."},{"p":"Половину LCM люди забывают, и именно она решает проблемы планирования: два события, которые повторяются каждые 18 дней и каждые 12 дней, совпадают каждые 36 дней. Та же арифметика, другое применение."},{"h":"Факториалы и скорость, с которой они взрываются"},{"l":["[[factorial-calculator|Калькулятор факториалов]] — n! для значений, ответ на которые все еще имеет смысл."]},{"p":"Факториалы растут быстрее, чем все, что вы встречаете за столом. 10! составляет около 3,6 млн. 20! составляет около 2,4 квинтиллиона — значительно больше, чем количество песчинок на Земле. 52!, количество способов перетасовать колоду карт, составляет примерно 8, за которыми следуют 67 цифр.\\n\\nПрактическим следствием является то, что программа, которая перечисляет все перестановки, работает нормально при 5 элементах, терпима при 8 и навсегда застревает при 12. Если кажется, что задача никогда не завершится, и вы перебираете перестановки в цикле, то почти наверняка причина в этом. Это также аргумент против большинства подходов грубой силы, которые выражаются скорее как арифметика, а не как мнение."},{"h":"Римские цифры и их странности"},{"l":["[[roman-numerals|Конвертер римских цифр]] — преобразование в римские цифры и обратно."]},{"p":"Римские цифры стоит понять, а не просто преобразовать, потому что система раскрывает кое-что о позиционных обозначениях. Здесь нет нуля и нет значения места: XI означает одиннадцать, независимо от того, представляет оно одиннадцать палочек или одиннадцать тысяч. Вот почему арифметика римскими цифрами действительно сложна и почему эта система существовала на протяжении веков в основном для подсчета и датировки, а не для вычислений.\\n\\nПравило вычитания — это то, в чем люди ошибаются. IV — четыре, а не VI; IX — девять. Часы являются известным исключением: Биг-Бен использует IIII, а не IV, по причинам, о которых историки до сих пор спорят. Преобразование, а не вывод, является правильным решением в каждом случае."},{"h":"Проработанный пример: проверка дроби вручную"},{"p":"Для рецепта требуется 0,375 чашки и шкала, которая показывает граммы, в отчете указано соотношение 0,625, и оба выглядят как цифры, которые кто-то напечатал в спешке."},{"l":["**1. Найдите точную дробь.** Введите 0,375 с помощью инструмента [[decimal-fraction|Десятичная дробь]]: 3/8. Пробег 0,625:5/8. Также не нужна привычка калькулятора, которой у вас нет.","**2. Упростите соотношение.** Чтобы выразить 3/8 в сравнении с 5/8, вам нужен GCF 3 и 5. [[gcf-calculator|GCF LCM Calculator]] дает 1, поэтому соотношение составляет 3:5 и это уже самое простое соотношение.","**3. Проверьте утверждение факториалов.** Если кто-то скажет вам, что очередь из 9 заказов имеет 362 880 упорядочений, [[factorial-calculator|Калькулятор факториалов]] подтвердит 9! именно это. Теперь вы знаете, была ли оценка времени сборки правдоподобной.","**4. Нормализуйте что-нибудь большое.** Сервер, сообщающий о 1,5e9 наносекундах, равен 1,5 секунды согласно [[scientific-notation|Scientific Notation Converter]] — в этом разница между проблемой задержки и артефактом округления."]},{"h":"Чего эти инструменты намеренно не делают"},{"p":"Они не показывают работу и не учат. Если вам нужно понять, почему формула верна, калькулятор — неправильный инструмент: он дает ответ без причины, и именно поэтому люди в конечном итоге могут вычислять, но не могут рассуждать.\\n\\nОни также не имеют произвольной точности. Факториалы и большие факторизации потеряют точность после того момента, когда ответ все еще будет полезен, а вкладка браузера не является системой компьютерной алгебры. Для всего, где правильность действительно имеет значение — инженерия, финансы, криптография — используйте подходящую библиотеку с точной арифметикой, а не веб-страницу."},{"h":"Проверка собственной арифметики"},{"p":"Самый ценный математический навык — это не скорость, а оценка. Прежде чем поверить в какой-либо результат, спросите, правильный ли он порядок величины: больше или меньше входных данных и примерно на сколько. Большинство арифметических ошибок выдерживают любую другую проверку, кроме этой.\\n\\nОкругление сначала делает оценку бесплатной. Округлите 0,375 до 0,4, округлите 5/8 до 0,6, и соотношение, очевидно, будет примерно 2:3 — достаточно близко к 3:5, чтобы подтвердить точно вычисленную вами дробь. Если точный ответ и оценка не совпадают, вы обнаружили ошибку ввода, а не проблему округления, и нашли ее за секунды.\\n\\nИменно поэтому калькулятор не заменяет размышлений о том, о чем вы его спросили. Инструмент идеально вычислит неправильную величину, и единственная защита — знать, каким должен быть ответ."},{"h":"Часто задаваемые вопросы"},{"p":"**Отправляются ли куда-нибудь мои данные?** Нет. Все они выполняются локально в вашем браузере.\\n\\n**Почему 0,1 плюс 0,2 не равно 0,3?** Потому что ни 0,1, ни 0,2 невозможно точно представить в двоичном формате с плавающей запятой. Сумма равна 0,30000000000000004, что является ближайшим к 0,3 удвоением.\\n\\n**Насколько большой факториал они могут обрабатывать?** До 170, прежде чем выйти за пределы диапазона двойного значения. После этого ответ отображается в научной записи и затем перестает иметь смысл.\\n\\n**Могу ли я использовать выходные данные в коде?** Да. В частности, для результатов преобразования десятичной дроби в числитель и знаменатель используйте целочисленную арифметику, а не конвертируйте обратно в десятичную дробь."},{"h":"Однострочная версия"},{"p":"Используйте точные дроби, когда речь идет о деньгах, помните, что факториалы взрываются быстрее, чем вы ожидаете, а простая факторизация — это одновременно основа безопасности и трюк, упрощающий дроби."}]},"everyday-utility-tools":{"title":"13 бесплатных повседневных утилит: пароли, QR-коды, таймеры и кодирование текста","description":"Создавайте пароли, создавайте QR-коды, запускайте таймеры и часы, а также декодируйте двоичный, шестнадцатеричный и зашифрованный текст — и все это с помощью бесплатных инструментов браузера, которые запускаются локально и не требуют учетной записи.","category":"Служебные инструменты","blocks":[{"p":"Эта последняя группа — ящик для мусора. Пароли, QR-коды, секундомер, мировые часы, подбрасывание монеты и четыре инструмента, которые преобразуют текст в другие его представления. По отдельности тривиально, а в совокупности то, что нужно в неловкие моменты.\\n\\nСуть в том, что все тринадцать работают локально. Для генератора паролей это не изящество, а единственная причина, по которой этому инструменту вообще можно доверять."},{"h":"Пароли: то, что действительно важно"},{"l":["[[password-generator|Генератор паролей]] — генерирует надежные случайные пароли любой длины и набора символов.","[[password-strength|Проверка надежности пароля]] — локально оценивает, насколько устойчив пароль к угадыванию."]},{"b":"Самый важный факт о надежности пароля: **длина превосходит сложность, а повторное использование превосходит обе опасности.** 16-значный пароль, составленный из несвязанных между собой слов, надежнее и гораздо легче набирается, чем 10-значный набор символов. Между тем, один повторно используемый пароль, обнаруженный при взломе, уничтожает все учетные записи, которых он касается, одновременно. Создание отдельного длинного пароля для каждого сайта — это вся работа."},{"p":"То, как оценивается сила, тоже имеет значение. Большинство чекеров приблизительно соответствуют размеру пространства поиска, что является разумным показателем, но не соответствует действительности: «CorrectHorseBatteryStaple» имеет хорошие показатели по энтропии, а «P@ssw0rd1!» — по разнообразию символов и плох на практике, поскольку встречается в каждом важном списке слов на земле.\\n\\nИспользуйте генератор для всего, что вам нужно, а если вам нужно запомнить пароль, используйте парольную фразу из четырех или пяти несвязанных слов. Это тот конкретный случай, когда запоминаемость и сила фактически совпадают."},{"h":"QR-коды: что в них вставлять"},{"l":["[[qr-code-generator|Генератор QR-кода]] — сгенерируйте QR-код для URL-адреса, текста, сведений о Wi-Fi или контактной информации."]},{"p":"QR-коды — это один из тех инструментов, качество вывода которых полностью определяется одним решением: сколько данных вы вводите. Короткий URL-адрес кодируется в небольшой, легко сканируемый код. Абзац текста со знаками препинания при небольших размерах кодируется во что-то плотное и ненадежное.\\n\\nДва практических правила. Во-первых, всегда тестируйте код в том размере, в котором он будет напечатан, прежде чем распечатывать двести таких кодов. Во-вторых, Wi-Fi и простые URL-коды ведут себя по-разному на разных телефонах — если код предназначен для смешанной аудитории, предпочтите простой URL-адрес целевой странице, которая затем ссылается дальше, потому что он работает везде, и вы можете изменить, куда он указывает."},{"h":"Время: таймеры, часы и ловушка часовых поясов"},{"l":["[[секундомер|Онлайн-секундомер]] — простой секундомер, полезный, когда ваш телефон находится в другой комнате.","[[pomodoro-timer|Таймер Pomodoro]] — 25-минутные блоки фокусировки с перерывами для людей, которые считают, что такая структура работает.","[[world-lock|Мировое время]] — текущее время сразу в нескольких городах."]},{"p":"Мировые часы заслужили свое место по одной конкретной причине: переход на летнее время. Половина мировых ошибок в планировании — это не арифметические ошибки, это момент, когда два города находились на расстоянии четырех часов друг от друга на прошлой неделе и на пять часов на этой неделе, и никто не проверил.\\n\\nПрежде чем планировать что-либо в часовом поясе, поместите оба города на мировые часы и посмотрите — не вычисляйте смещение по памяти. Именно поэтому в приглашениях на встречи должен быть указан часовой пояс, а не просто час."},{"p":"О таймере Помидора: этот метод работает для задач определенного типа — ограниченных, целенаправленных и непрерывных. Это не работает для отладки, где правильный ход при застревании — уйти, а не начинать еще один 25-минутный блок. Используйте его, когда это помогает."},{"h":"Случайность, честное слово"},{"p":"[[random-number|Генератор случайных чисел]] и [[list-randomizer|Landomizer]] охватывают фактически возникающие случаи: выбор числа в диапазоне и размещение списка в справедливом порядке. Стоит вынести приговор по справедливости. Оба используют псевдослучайный генератор, который для принятия решения о том, кто платит за обед, неотличим от реальной монеты. Для чего-либо значимого — розыгрыша призов, распределения денежных средств — вам нужен источник, который можно проверить, а вкладка браузера — это не то. Ценность здесь заключается в устранении человека, который делает плохой выбор, когда у него есть мотивация."},{"h":"Ящик для ненужного кодирования"},{"p":"Четыре инструмента, которые перемещают текст между представлениями. Ни один из них не является шифрованием, и об этом различии стоит упомянуть, потому что его постоянно путают: кодирование обратимо кем угодно и не имеет ключа. Для шифрования требуется ключ."},{"l":["[[binary-text|Двоичный текст в текст]] — конвертирует текст в его двоичное представление.","[[hex-text|Hex в текст]] — преобразование текста в шестнадцатеричное представление, которое вы чаще всего видите в сетевых инструментах и ​​отладчиках.","[[caesar-cipher|Цезарь Шифр]] — сдвиг букв на фиксированную величину, классический классный шифр.","[[rot13-encoder|ROT13 Encoder]] — поворот букв на 13, особый случай, который является обратным."]},{"p":"Они полезны ровно для двух вещей. Во-первых, понимание того, как текст становится байтами, и это мысленная модель, которая вам нужна, когда что-то выглядит искаженным. Во-вторых, собственно отладка: когда полезная нагрузка отображается в шестнадцатеричном виде, конвертер [[hex-text|Hex в текст]] позволяет узнать, что там написано.\\n\\nОни бесполезны для сокрытия чего-либо. У ROT13 нет ключа — сдвиг общедоступен, поэтому он ничего не скрывает от тех, кто знает, что такое ROT13. Шифр Цезаря имеет 25 возможных сдвигов, которые человек взламывает за первую минуту."},{"h":"Двое, которые форматируют вещи"},{"l":["[[phone-formatter|Форматтер телефонных номеров]] — нормализует номера телефонов в согласованный формат.","[[file-size-converter|Конвертер размеров файлов]] — конвертирует КБ, МБ, ГБ и ТБ с объяснением различия между десятичными и двоичными числами."]},{"p":"Конвертер размера файлов имеет один действительно ценный результат: он сообщает вам, почему диск объявляет большее число, чем сообщает ваш компьютер. Поставщики продают степени десяти, операционные системы сообщают о степени двойки, и разрыв составляет около 7 процентов в каждом масштабе. Это не ошибка, это две условности."},{"h":"Проработанный пример: искаженный ответ API"},{"p":"Веб-перехватчик не проходит проверку, и полезные данные в журнале выглядят как `\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f`. Это девяносто второй диагноз."},{"l":["**1. Convert.** Вставьте `48656c6c6f` в конвертер [[hex-text|Hex to Text]] — результатом будет `Hello`. Оно никогда не было искажено, а просто закодировано.","**2. Проверьте форму.** Перед подписанием что-то вышестоящее кодирует полезную нагрузку в шестнадцатеричном формате. Подпись была вычислена по исходному тексту и проверена на соответствие шестнадцатеричному коду, поэтому сравнение не удалось.","**3. Исключите другое направление.** Если бы в журнале был читаемый текст, проблема была бы в обратной: подписание закодированной формы.","**4. Подтвердите заявление о размере.** Если в том же журнале сообщается о полезной нагрузке размером 1,2 МБ, [[file-size-converter|Конвертер размера файла]] определяет, является ли она десятичной или двоичной, прежде чем кто-либо станет спорить о квоте."]},{"h":"Часто задаваемые вопросы"},{"p":"**Безопасен ли генератор паролей, если все работает в браузере?** Да, и в большей степени, чем серверный: пароль генерируется на вашем компьютере и никогда не передается, поэтому нечего перехватывать, регистрировать или взламывать. Компромисс заключается в том, что вы не сможете восстановить пароль, который не сохранили.\\n\\n**Могу ли я доверять виртуальному подбрасыванию монеты?** Для случайных решений — да. Для всего, что связано с деньгами или призами, используйте источник, который вы можете проверить.\\n\\n**Надежны ли шифры?** Нет. Ни один из них. Шифры ROT13 и Цезарь не имеют секретного ключа и существуют для обучения кодированию, а не для защиты чего-либо.\\n\\n**Работают ли они в автономном режиме?** Да, после загрузки страницы все становится локальным.\\n\\n**Есть ли ограничение на длину текста для конвертеров?** Только память вашего устройства, так как ничего никуда не отправляется."},{"h":"Однострочная версия"},{"p":"Длинные уникальные пароли превосходят короткие умные, QR-код хорош только настолько, насколько хороши данные внутри него, проверяйте смещения часовых поясов, а не вычисляйте их, а кодирование не является шифрованием."}]}}')},31884,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"مجموعة أدوات المطور: 24 أداة متصفح مجانية تحل محل التطبيقات المدفوعة","description":"دليل عملي لتنسيق البيانات وتحويلها وترميزها وتصحيح أخطائها باستخدام أدوات المطورين المجانية المستندة إلى المتصفح - بدون عمليات تثبيت أو حسابات؛ تقوم معظم الأدوات بمعالجة الإدخال محليًا.","category":"أدوات المطور","blocks":[{"p":"معظم المهام الصغيرة التي تقوم بها مائة مرة في الأسبوع - مثل إعادة تنسيق استجابة واجهة برمجة التطبيقات (API)، وفك تشفير رمز مميز، والتحقق من التجزئة، ووضع مسافة بادئة لجزء من SQL - لا تحتاج إلى بيئة تطوير متكاملة (IDE)، أو اشتراك مدفوع، أو ترخيص فريق. إنهم بحاجة إلى فتح علامة تبويب واحدة لمدة تسعين ثانية.\\n\\nالمجموعة أدناه عبارة عن أربعة وعشرون أداة مساعدة تعتمد على المستعرض وتغطي التنسيق والتحويل والتشفير والتجزئة وتصحيح الأخطاء. يتم تشغيل كل واحدة منها بالكامل في صفحتك: لا يتم إرسال بياناتك أبدًا إلى الخادم، وهو أمر أكثر أهمية مما يعترف به المطورون عادةً، لأن الحمولة التي تلصقها عادة ما تكون خاصة بالعميل."},{"h":"ما هي الأدوات المستندة إلى المتصفح التي يمكن أن تحل محلها والتي لا يمكن أن تحل محلها"},{"p":"كن واقعيًا بشأن الحدود. تحل هذه الأدوات محل الأعمال الروتينية التي تتم لمرة واحدة ومنخفضة المخاطر وعالية التردد. فهي لا تحل محل خادم اللغة الخاص بك، أو مصحح الأخطاء، أو مجموعة الاختبار الخاصة بك، أو أي شيء تحتاجه للتشغيل في بيئة حقيقية بشكل متكرر."},{"l":["**ملاءمة جيدة:** قراءة الرد مرة واحدة، وتصحيح أخطاء قيمة واحدة، وتحويل ملف لاستيراد واحد، والتحقق من التنسيق قبل الشحن.","**ملاءمة سيئة:** إجراء نفس الفحص عند كل عملية نشر، وتحويل مئات الملفات، وأي شيء يجب أن يفشل بشكل كبير في CI.","**مطلقًا:** أي شيء يتضمن بيانات اعتماد لا يمكنك تدويرها. الصق رمزًا مميزًا تم إبطاله، وليس رمزًا مباشرًا."]},{"p":"ومع ذلك، فإن سبب الاحتفاظ بهذه الإشارات المرجعية هو الإنتاجية. المهمة التي تستغرق أربعين ثانية في علامة تبويب المتصفح لا تتم جدولتها أبدًا، ولا يتم تفويضها أبدًا، ولا تصبح أبدًا سببًا لفتح IDE في الساعة الثامنة مساءً."},{"h":"تنسيق البيانات وتحويلها"},{"p":"الوظيفة اليومية الأكثر شيوعًا هي جعل البيانات قابلة للقراءة. تقوم واجهة برمجة التطبيقات (API) بإرجاع كائن ثنائي كبير الحجم من سطر واحد، أو يرسل أحد الزملاء ملف تكوين يحتوي على علامات تبويب مشوهة بواسطة نافذة دردشة، أو قمت بتصدير جدول بيانات إلى JSON وعادت كسطر واحد ضخم."},{"l":["[[json-formatter|JSON Formatter]] — مسافة بادئة للحمولة والتحقق من صحتها وقراءتها. استخدمه قبل تصحيح الأخطاء: نصف جميع تذاكر \\"واجهة برمجة التطبيقات المعطلة\\" هي في الواقع JSON مشوهة بفاصلة زائدة.","[[json-validator|JSON Validator]] - عندما تحتاج إلى إجابة نجاح/رسوب صارمة بدلاً من طباعة جميلة.","[[xml-formatter|XML Formatter]] - نفس الوظيفة لاستجابات SOAP وخلاصات RSS وMaven POMs التي لم يتطرق إليها أحد منذ عام 2014.","[[json-to-yaml|JSON to YAML]] و [[json-to-csv|JSON إلى CSV]] — نقل البيانات بين التنسيقات التي تستخدمها الأنظمة الحقيقية بالفعل."]},{"p":"ضع المجموعة الأخيرة في الاعتبار لسيناريو واحد محدد: يقدم لك العميل جدول بيانات ويتوقعه في واجهة برمجة التطبيقات الخاصة به. يستغرق الانتقال من ملف CSV إلى JSON مباشرةً مهمة تستغرق دقيقتين بدلاً من قضاء فترة ما بعد الظهيرة في البرمجة النصية."},{"h":"الترميز والهروب"},{"p":"تعد أخطاء التشفير مزعجة بشكل غير متناسب لأن البيانات تبدو جيدة. تصل القيمة \\"San José & Sons\\" كـ \\"San Jos%C3%A9 %26 Sons\\" وتفشل المقارنة مع قاعدة البيانات لأسباب غير مرئية في السجلات."},{"l":["[[url-encoder|URL Encoder / Decoder]] - حدد على الفور ما إذا كانت سلسلة الاستعلام مشفرة بشكل مزدوج.","[[base64-encoder|Base64 Encoder / Decoder]] — فك تشفير جزء من الشهادة، أو تشفير أصل صغير لتضمينه في CSS.","[[html-entity-encoder|HTML Entity Encoder / Decoder]] - اكتشف ما إذا كانت علامة \\"&\\" الضالة في صفحتك جاءت من القالب الخاص بك أو من بياناتك.","[[unicode-converter|Unicode Converter]] — مفيد عندما يتبين أن الحرف \\"المكسور\\" هو حرف شرعي تم تقديمه بتشفير خاطئ.","[[number-base-converter|Number Base Converter]] — التحقق من اللون أو قناع البت للإذن أو عنوان الذاكرة بدون تطبيق الآلة الحاسبة."]},{"b":"عادة عملية: عندما تصل قيمة مشوهة، فك تشفيرها طبقة واحدة في كل مرة والصق كل نتيجة في حقل فارغ. إذا أدى فك التشفير الأول إلى إنتاج نص قابل للقراءة، فستكون المشكلة هي ترميز إضافي واحد في مكان ما في المنبع. إذا كان ينتج mojibake، فستكون لديك مشكلة في التشفير بدلاً من مشكلة الهروب، وهاتان المشكلتان تحتاجان إلى إصلاحات مختلفة."},{"h":"المعرفات والتجزئة والرموز"},{"p":"هذه المجموعة هي المكان الذي يضيع فيه المطورون معظم وقتهم في البحث عن النص المحلي الصحيح الذي كتبوه مرة واحدة ثم فقدوه."},{"l":["[[uuid-generator|UUID Generator]] — إنشاء معرفات v4 للبيانات الأولية أو التركيبات أو صف قاعدة بيانات سريع.","[[md5-generator|MD5 / SHA Hash Generator]] — تحقق من التنزيل أو تأكد من وجود ملفين يجب أن يكونا متطابقين بالفعل.","[[timestamp-converter|Timestamp Converter]] — الأداة الوحيدة الأكثر استخدامًا في هذه القائمة بأكملها. عندما يشير سطر السجل إلى 1761000000، فهذا هو ما يخبرك بما إذا كان الحادث قد وقع أثناء النشر أو قبله."]},{"p":"يحتفظ محول الطابع الزمني لسبب واحد محدد: رقم العصر لا لبس فيه وغير مفيد في نفس الوقت. أنت تعرف بالضبط متى حدث شيء ما ولا يمكنك إخبار زميلك. عادةً ما يؤدي التحويل مرة واحدة إلى حل حجة أعلى مما ينبغي."},{"h":"المقارنة والتصحيح"},{"l":["[[اختبار regex|اختبار Regex]] — العنصر ذو الرافعة المالية الأعلى هنا. التعبير العادي الذي يبدو صحيحًا ولا يتطابق مع أي شيء بهدوء هو أحد أغلى الأخطاء في التطوير، لأنه يفشل بصمت في المكان الوحيد الذي لا يقرأه أحد.","[[html-preview|HTML Preview]] — قم بالتكرار على جزء من العلامات للتحقق من كيفية عرضه فعليًا."]},{"p":"اختبر تعبيراتك العادية مقابل المدخلات التي تتوقعها بالفعل، بما في ذلك السلسلة الفارغة واسم Unicode والقيمة ذات السطر الجديد. تنكسر معظم الأنماط في الحالة الثالثة ولا يلاحظ أحد حتى وصول بيانات الإنتاج."},{"h":"مثال عملي: ثلاث أدوات، حادثة واحدة مملة"},{"p":"هذا هو التسلسل الذي أقنعني بوضع إشارة مرجعية على كل هذا. أبلغ أحد العملاء أن السجل الذي أرسله يوم الثلاثاء كان مفقودًا من تقرير يوم الخميس."},{"l":["**1. تحويل الطابع الزمني.** سجلت مهمة التقرير وقت إنشاء السجل كقيمة زمنية. أظهر [[timestamp-converter|Timestamp Converter]] أن السجل تم إنشاؤه في الساعة 11 مساءً بالتوقيت المحلي، وهو يوم الثلاثاء - كان افتراض المنطقة الزمنية للمهمة هو المشكلة، وليس السجل.","**2. قم بتنسيق الحمولة. ** كشف أخذ JSON المخزن من خلال [[json-formatter|JSON Formatter]] أن السجل مكتوب بحقل تاريخ فارغ، لأن العميل اتصل مرتين بنفس نقطة النهاية بفارق 200 مللي ثانية وفازت عملية الكتابة الثانية.","**3. قارن الحمولات.** يحمل كلا السجلين نفس مفتاح واجهة برمجة التطبيقات (API) ونفس الطابع الزمني للعميل، مما يشير إلى إعادة المحاولة بدلاً من عميلين منفصلين."]},{"p":"إجمالي الوقت المنقضي: أربع دقائق. استغرقت المحاولة السابقة لهذا التحقيق، والتي بحثت عن نفس السبب الجذري في منصة التسجيل، فترة ما بعد الظهر وتوصلت إلى نتيجة خاطئة."},{"h":"الخصوصية: لماذا يعد التشغيل محليًا هو الميزة الفعلية"},{"p":"تقوم كل أداة في هذه المكتبة بمعالجة مدخلاتك داخل المتصفح الخاص بك. لم يتم تحميل أي شيء، مما يعني عدم وجود سؤال للاحتفاظ، ولا اتفاقية معالج، ولا توجد محادثة غير مريحة حول حمولة الإنتاج التي قمت بلصقها قبل ثلاث دقائق.\\n\\nهذا هو السبب وراء تفضيل هذه الأدوات على \\"pastebin API\\" المستضافة أو الخدمة عبر الإنترنت التي تطلب منك التسجيل. ويعني ذلك أيضًا أنهم يستمرون في العمل على متن الطائرة، أو في الطابق السفلي، أو عندما تقرر شبكة VPN الخاصة بالشركة حظر نطاق آخر."},{"p":"هناك تحذير واحد يستحق الذكر بوضوح: الصفحة التي لا يمكن الاتصال بها في وضع عدم الاتصال تكون خاصة فقط إذا كانت الصفحة نفسها هي الرمز الذي تعتقد أنه كذلك. على جهاز مشترك، استخدم نافذة خاصة وأغلقها عند الانتهاء، خاصة إذا كنت قد قمت بفك تشفير الرموز المميزة."},{"h":"بناء سير العمل من حولهم"},{"p":"الأدوات تافهة بشكل فردي. القيمة هي عادة الوصول إلى واحد على الفور بدلاً من \\"الوصول إليه لاحقًا\\"، لأنه يحدث لاحقًا عندما تكتب نصًا سريعًا، أو تفتح IDE، أو تقرر أنه لا يستحق التحقق على الإطلاق."},{"l":["قم بوضع إشارة مرجعية على المجموعة، وليس عناوين URL الفردية، ثم ضعها في شريط أدوات المتصفح الخاص بك.","عندما يبدو شيء ما خاطئًا، تحقق منه قبل تكوين نظرية. تكاليف خمسة عشر ثانية؛ يقتل فئات كاملة من الاستنتاجات الخاطئة.","عندما تتحقق من نفس الشيء مرتين، فهذه إشارة لتشغيله تلقائيًا، لكن لا تقم بتشغيله تلقائيًا عند الشك.","لا تلصق أسرار الإنتاج. قم بتدوير أي شيء لست متأكدًا منه."]},{"h":"الأسئلة المتداولة"},{"p":"**هل هذه الأدوات مجانية؟** نعم، تمامًا، بدون حساب ولا حدود للاستخدام. لا يوجد مستوى مدفوع يعيق أي شيء أساسي.\\n\\n**هل تعمل دون اتصال بالإنترنت؟** بمجرد تحميل الصفحة، نعم — يتم تشغيل كل شيء في متصفحك. إعادة التحميل تتطلب اتصالاً.\\n\\n**هل يمكنني استخدامها في الأعمال التجارية؟** نعم. الإخراج لك دون أي شرط الإسناد.\\n\\n**هل هناك API؟** لا، وهذا أمر متعمد — القيمة هي الواجهة. قم بتصدير الإخراج ومعالجته كيفما تشاء.\\n\\n** لماذا لا تقوم فقط بتثبيت أداة CLI بدلاً من ذلك؟ ** قم بتثبيت واحدة عندما تحتاج إليها ثلاث مرات. استخدم علامة تبويب المتصفح لأول اثنين."}]},"text-tools-for-writers":{"title":"17 أداة نصية مجانية للكتاب والطلاب والمسوقين","description":"قم بتنظيف النسخة، وعد الكلمات بدقة، وتنسيق القوائم، وتحويل المسودات الأولية إلى شيء قابل للنشر - باستخدام أدوات المتصفح المجانية التي تعمل محليًا في متصفحك.","category":"أدوات النص","blocks":[{"p":"تتضمن الكتابة للعمل قدرًا مدهشًا من العمل الميكانيكي الذي لا علاقة له بالكتابة: إزالة المسافات البيضاء الضالة من فقرة تم لصقها، والتحقق من الحد الأقصى للكلمات، وإلغاء تكرار قائمة الأسماء، وتحويل شيء ما إلى عنوان URL ثابت.\\n\\nهذه الأدوات السبعة عشر مخصصة لهذا الجزء من العمل. يتم تشغيلها جميعًا محليًا في المتصفح، وهذا ليس بالتفاصيل الصغيرة - فالمسودة التي تلصقها غالبًا ما تكون غير منشورة، والقائمة التي تقوم بفرزها غالبًا ما تكون بيانات شخصية لشخص ما."},{"h":"قياس ما كتبته"},{"p":"يبدو أن عدد الكلمات قد تم حله حتى يطلب العميل 800 كلمة بالضبط ويقول محررك 820، أو يرفض النموذج النص الذي يتكون من 1995 حرفًا دون توضيح أين ذهب السطر الجديد."},{"l":["[[عداد الكلمات|عداد الكلمات]] — المقياس القياسي. لصق، قراءة، ضبط.","[[letter-counter|عداد الحروف]] — يقوم بحساب عدد الأحرف وتكرارها. يكون ذلك مفيدًا عند تصحيح الأخطاء التي تجعل فقرة واحدة تبدو خاطئة: فهي عادةً ما تكون نمطًا متكررًا للأحرف، وليست حلمًا."]},{"p":"ملاحظة حول معنى \\"الكلمة\\": تختلف العدادات المختلفة حول الواصلة والأرقام وعناوين URL. إذا كان الرقم الدقيق مهمًا، فاستخدم نفس العداد الذي يستخدمه الشخص الذي يتحقق من عملك، ووافق عليه مسبقًا. هذا مصدر شائع حقًا للحجج الصغيرة التي لا معنى لها."},{"h":"تنظيف نسخة لم تكتبها"},{"p":"معظم النصوص التي تتلقاها تكون تالفة قليلاً: مسافات مزدوجة من عملية النسخ واللصق، وعلامة التبويب الضالة، والأحرف الكبيرة غير المتناسقة من شخص يكتب على عجل. إصلاحه باليد بطيء وعرضة للخطأ."},{"l":["[[text-trimmer|Text Trimmer]] — إزالة المسافات البيضاء البادئة واللاحقة من كل سطر مرة واحدة. يؤدي هذا إلى إصلاح تقارير \\"يبدو التنسيق معطلاً\\" أكثر من أي شيء آخر في هذه القائمة.","[[text-case-converter|محول حالة النص]] - التبديل بين حالة الجملة وحالة العنوان والعلوية والسفلى عبر الكتلة. وهي أيضًا أسرع طريقة للتراجع عن فقرة CAPS LOCK غير المقصودة.","[[text-to-slug|Text to Slug]] — حوّل العنوان إلى عنوان URL ثابت نظيف. الصق عنوانك، وانجز المهمة."]},{"p":"يستخدم منشئ الارتباط الثابت استخدامًا واحدًا يتجاوز عناوين URL: فهو طريقة سريعة لإنشاء اسم ملف قابل للقراءة أو نقطة ربط يمكن للإنسان تحليلها بنظرة واحدة، وهو ما يتفوق على \\"final_final_v3\\"."},{"h":"العمل مع القوائم"},{"p":"القوائم، وقوائم الجرد، ودمج البريد، وتنظيف العلامات، واستجابات الاستطلاع، وأعمدة جدول البيانات - في مرحلة ما يصبح كل شيء قائمة وتحتاج كل قائمة إلى الفرز أو إلغاء التكرار أو التوزيع العشوائي."},{"l":["[[مزيل الخط المكرر|مزيل الخط المكرر]] — قارن بين قائمتين، أو قم بتنظيف واحدة. يخبرك الإخراج بعدد التكرارات التي تمت إزالتها، وهو أمر مفيد عند الإبلاغ عن النتيجة.","[[list-sorter|فارز القائمة]] — نفس الوظيفة لإدخال القائمة المنظمة.","[[list-randomizer|List Randomizer]] - قم بتبديل ترتيب السحب أو تسلسل الاختبار أو القائمة المختصرة المحاطة بسياج دائري حتى لا يشك أحد في المحسوبية.","[[line-number-adder|Line Number Adder]] — سطور الأرقام للرجوع إليها في التذكرة أو تعليق مراجعة الكود."]},{"b":"المصيدة الكلاسيكية هنا هي القائمة التي تبدو غير مكررة ولكنها ليست كذلك: \\"Apple\\"، و\\"apple\\"، و\\"Apple\\". هي ثلاثة أسطر مختلفة لجهاز الكمبيوتر. قم بقص المسافات البيضاء وإزالة علامات الترقيم قبل حذف البيانات المكررة، وإلا فلن تقوم بدمج أي شيء وتستنتج أن البيانات نظيفة."},{"h":"المعاينة والتنسيق"},{"p":"لقد فاز Markdown، ولكن ليس بشكل موحد. نصف أدواتك تجعلها، والنصف الآخر لا تفعل ذلك، والنصف الذي لا يفعل ذلك هو عادةً ما يجب على أحد كبار الموظفين لصقه فيه."},{"l":["[[markdown-preview|Markdown Preview]] — عرض مباشر، حتى تتمكن من التحقق من أن الجدول أو القائمة المتداخلة تبدو صحيحة قبل أن تصل إلى العميل.","[[مكرر النص|مكرر النص]] — كرر سلسلة N مرات. مفيد لإنشاء الحشو أو بيانات الاختبار أو في بعض الأحيان لتوضيح نقطة في المستند."]},{"p":"معاينة Markdown هي الأداة التي توفر بهدوء معظم الوقت في هذه المجموعة بأكملها، لأن الجدول المكسور في المستند المعروض يكون أكثر وضوحًا - وأكثر إحراجًا بكثير - من الجدول المكسور في النص الخام."},{"h":"الباقي ومتى تصل إليهم"},{"l":["[[سلسلة عشوائية|مولد سلسلة عشوائية]] — إنشاء حروف غير قابلة للقراءة أو معرفات العناصر النائبة أو الرموز القصيرة. أفضل من اختراع شيء ما باليد، لأنك لن تعيد استخدامه عن طريق الخطأ.","[[morse-code|Morse Code Translator]] — ممتع حقًا، ومفيد أحيانًا لمشروع ذي موضوع معين أو لغز."]},{"p":"هذه أدوات ذات تردد منخفض، لكن الاحتفاظ بها كإشارة مرجعية لا يكلف شيئًا كما أنها تحل المشكلة المحددة المتمثلة في \\"أحتاج إلى قيمة ذات مظهر عشوائي الآن ولا أثق بنفسي في إنشاء واحدة\\"."},{"h":"تمريرة تحرير واقعية"},{"p":"هذا هو الترتيب الذي يعمل عندما تصل مسودة من شخص آخر وتحتاج إلى الخروج باسمك."},{"l":["**1. القطع.** قم بتشغيل المستند بأكمله من خلال [[أداة تشذيب النص|أداة تشذيب النص]] أولاً. يختفي ضرر المسافات البيضاء داخل الفقرات حيث لن تتمكن من رؤيتها أبدًا.","**2. حالة نظيفة.** استخدم [[text-case-converter|محول حالة النص]] للعنوان الرئيسي فقط. لا تطبق أبدًا تحويل الحالة إلى مسودة كاملة، فهذا يدمر أسماء العلم.","**3. قم بالقياس. ** تحقق من الطول باستخدام [[عداد الكلمات|عداد الكلمات]] قبل الكتابة، حتى تعرف الشكل المقصود للقطعة.","**4. معاينة.** إذا كانت تحتوي على Markdown، فقم بعرضها باستخدام [[markdown-preview|Markdown Preview]].","**5. Slug.** أنشئ عنوان URL الثابت أخيرًا، من العنوان النهائي، باستخدام [[text-to-slug|Text to Slug]] — يؤدي تغيير العنوان بعد ذلك إلى كسر الارتباط الثابت."]},{"p":"يستغرق التمرير بأكمله بضع دقائق ويزيل فئة الخطأ حيث يكون المستند صحيحًا من الناحية الفنية وخاطئًا بشكل واضح."},{"h":"أسئلة الكتاب حول الخصوصية"},{"p":"**هل يغادر النص غير المنشور جهاز الكمبيوتر الخاص بي؟** لا. تقوم هذه الأدوات بمعالجة النص في متصفحك ولا يتم تخزين أي شيء أو نقله.\\n\\n**هل هناك حد للطول؟** لا يوجد حد من جانب الخادم لأنه لا يوجد اتصال بالخادم. المدخلات الكبيرة للغاية محدودة بذاكرة جهازك.\\n\\n**هل يمكنني استخدام المخرجات تجاريًا؟** نعم، بحرية، دون إسناد.\\n\\n**هل يعملون على الهاتف؟** نعم. يتكيف التخطيط، ويتم تشغيل نفس الكود."},{"h":"ما لن تفعله هذه الأدوات لك"},{"p":"من المفيد أن نكون صريحين بشأن الحدود، لأن الأداة التي تجعل الشيء الخطأ آليًا تنتج خطأً أسرع.\\n\\nلا يمكن لأي من هذه الأدوات أن تخبرك ما إذا كانت الجملة واضحة، أو ما إذا كان مصدر المطالبة، أو ما إذا كانت النغمة مناسبة للجمهور. يحسبون الشخصيات. لا يحكمون على النثر. قد يظل النص الذي يسجل نتائج رائعة في كل مقياس في هذه الصفحة غير قابل للقراءة.\\n\\nولا يقومون بالتحرير. في اللحظة التي تجد فيها نفسك تعيد كتابة الجمل الفردية يدويًا على نطاق واسع، تكون قد تجاوزت أداة النص وتريد إما محررًا مناسبًا، أو البحث والاستبدال باستخدام التعبير العادي - وهو [[اختبار regex|اختبار Regex]] جيد حقًا للتدرب عليه - أو نصًا. استخدم المتصفح للطبقة الميكانيكية، واحتفظ بحكمك الخاص على كل شيء فوقها."},{"p":"هناك شيء آخر لن يفعلوه وهو إصلاح مصدر سيئ. إذا كان جدول البيانات الخاص بك مليئًا بأسماء غير متناسقة - \\"Dr\\"، \\"DR\\"، \\"Dr.\\" كل ذلك في عمود واحد - ستقوم الأداة بفرز ما قدمته لها بأمانة وإلغاء تكراره، وسيظل لديك ثلاثة إدخالات حيث يجب أن يكون هناك إدخال واحد. يعد تنظيف البيانات قرارًا وليس خطوة ميكانيكية. حدد النموذج الأساسي أولاً، ثم قم بتطبيقه، ثم تحقق منه."},{"h":"الاحتفاظ بقائمة عمل قابلة للاستخدام"},{"p":"إذا احتفظت بقائمة من العملاء المتوقعين أو الروابط أو المراجع أو المصطلحات، فإنها تتدهور بهدوء. وضع الفشل هو نفسه دائمًا: الإدخالات التي تبدو متطابقة ليست كذلك، ولا يؤدي الدمج الواحد إلى إزالة أي شيء.\\n\\nيعتبر تصريح الصيانة الذي يعمل أمرًا مملًا: قم بقص المسافات البيضاء، وتوحيد الكتابة بالأحرف الكبيرة، وإزالة علامات الترقيم، ثم إلغاء التكرار. وبهذا الترتيب، يؤدي التشذيب بعد إلغاء التكرار إلى فقدان الإدخالات. إن القيام بذلك مرة واحدة في الشهر على قائمة نشطة يحول الفوضى غير القابلة للاسترداد لمدة ساعتين إلى عمل روتيني مدته عشر دقائق.\\n\\nعندما تحتاج قائمتان إلى التوفيق بين قائمتين - على سبيل المثال، قائمة تسجيل مقابل قائمة الحضور - قم بفرزهما باستخدام [[list-sorter|List Sorter]] أولاً، بحيث تصطفان، ثم قارنهما بالعين المجردة. فرز كلا الجانبين قبل المقارنة هو الفرق بين الفحص لمدة دقيقتين والمطاردة لمدة عشرين دقيقة."},{"h":"الوجبات الجاهزة"},{"p":"لا شيء من هذه الأدوات ذكي. هذه هي النقطة: إنهم يزيلون نسبة الخمسة بالمائة الميكانيكية من الكتابة التي ليست كتابة، وبالتالي فإن الخمسة والتسعين بالمائة المتبقية تتعلق في الواقع بالجمل. قم بوضع إشارة مرجعية على تلك التي تستخدمها شهريًا، وتجاهل الباقي، وتوقف عن إصلاح المسافات البيضاء يدويًا."}]},"calculators-and-converters-guide":{"title":"18 آلة حاسبة ومحولات مجانية للأرقام التي تتعامل معها فعليًا","description":"النسب المئوية، والخصومات، والنصائح، والقروض، والتواريخ، ومؤشر كتلة الجسم وتحويلات الوحدات - حاسبات متصفح مجانية توضح أسبابها، دون الحاجة إلى حساب.","category":"الآلات الحاسبة","blocks":[{"p":"يحتاج الجميع إلى تقسيم الفاتورة، ومعرفة ما إذا كان الخصم يمثل خصمًا حقيقيًا، وتحويل درجة الحرارة أو حجم الملف دون التفكير في الأمر. الجميع أيضًا، مرة واحدة على الأقل، يخطئون في هذا الأمر علنًا.\\n\\nهذه مجموعة من ثمانية عشر آلة حاسبة ومحولات تغطي الأموال والتواريخ والصحة وتحويلات الوحدات التي تظهر في العمل والسفر. يتم تشغيلها جميعًا في المتصفح: لا يتم حفظ أي شيء، لذا فإن الأرقام التي تكتبها ليست من اختصاص أحد غيرك."},{"h":"حسابات المال"},{"p":"الرياضيات الأكثر شيوعًا في العالم الحقيقي هي النسبة المئوية لشيء ما. ضريبة المبيعات، الإكرامية، كومة الخصم، العمولة، معدل النمو. المعادلة بسيطة، ومع ذلك فإن السبب الذي يجعل الناس يخطئون في فهمها هو نفسه دائمًا تقريبًا: فهم يطبقون نسبة مئوية على الأساس الخاطئ."},{"l":["[[حاسبة الخصم|حاسبة الخصم]] — احسب السعر النهائي، والأهم من ذلك، المبلغ الذي قمت بتوفيره. من المفيد اكتشاف \\"خصم 50%\\" الذي يمثل في الحقيقة 20% بعد قائمة الأسعار المرتفعة.","[[حاسبة النصيحة|حاسبة النصيحة]] — قم بتقسيم الفاتورة، واختر نسبة مئوية، وجولة لكل شخص إذا كنت ترغب في ذلك.","[[loan-calculator|حاسبة القرض]] — الدفعة الشهرية وإجمالي الفائدة، وهو الرقم الذي يحدد فعليًا ما إذا كان القرض ميسور التكلفة أم لا."]},{"b":"بالنسبة للخصومات: خصم 20% يتبعه خصم آخر 20% لا يعتبر خصم 40%، بل 36%. النسب المئوية المتسلسلة تتراكم على القاعدة المخفضة. أي آلة حاسبة في هذه القائمة سوف تؤكد ذلك في حوالي ثانيتين، وهي الحقيقة الحسابية الأكثر فائدة في هذه المقالة."},{"p":"حاسبة القروض تستحق ملاحظة محددة. الرقم المهم ليس الدفعة الشهرية - بل هو إجمالي الفائدة المدفوعة على مدى عمر القرض، لأن هذه هي التكلفة الحقيقية للاقتراض. يمكن أن يختلف قرضان بدفعات شهرية متطابقة وشروط مختلفة بعشرات الآلاف في إجمالي الفائدة."},{"h":"التواريخ والعد التنازلي"},{"p":"حساب التاريخ هو المكان الذي يخطئ فيه معظم الناس بصمت، لأن الأشهر البشرية لها أطوال مختلفة وتتغير الإجابة اعتمادًا على ما إذا كنت تقصد \\"الأشهر التقويمية\\" أو \\"30 يومًا\\"."},{"l":["[[فارق التاريخ|حاسبة فرق التاريخ]] — الأيام (وإجمالي الأشهر والسنوات) بين تاريخين.","[[days-until|الأيام المتبقية على الحاسبة]] — عد تنازلي لتاريخ محدد، وعادةً ما يكون عدد أيام العمل هو ما يريده الأشخاص فعليًا.","[[حاسبة العمر|حاسبة العمر]] — العمر المحدد بالسنوات والأيام، بالإضافة إلى تاريخ الميلاد التالي.","[[timestamp-converter|Timestamp Converter]] — طابع زمني لنظام Unix لتحويل التاريخ الحقيقي، وهو أمر مهم إذا لمست السجلات أو قواعد البيانات أو استجابات واجهة برمجة التطبيقات."]},{"p":"الفرق الذي يزعج الناس: عدد الأيام بين 1 مارس و1 أبريل هو 31، ولكن عدد *الأشهر* واحد. إذا كنت تحسب فترة إشعار أو مدة اشتراك، فاذكر الوحدة التي تقصدها كتابيًا."},{"h":"أرقام صحية بصراحة"},{"l":["[[bmi-calculator|BMI Calculator]] — مؤشر كتلة الجسم مع الفئات القياسية، والمحاذير أدناه."]},{"p":"مؤشر كتلة الجسم هو إحصائية فحص على مستوى السكان. فهو لا يذكر شيئًا عن كتلة العضلات، أو تكوين الجسم، أو صحة أي فرد، وهو مؤشر ضعيف للياقة البدنية لدى الرياضيين، وكبار السن، وعبر المجموعات العرقية المختلفة. استخدمها كنقطة بيانات واحدة من بين عدة نقاط، أو كوسيلة لتتبع التغيير بمرور الوقت - وليس كحكم. إذا كنت تتخذ قرارات تؤثر على صحتك، فإن الأداة الصحيحة هي الطبيب، وليس علامة تبويب المتصفح."},{"h":"تحويل الوحدات: تلك اليومية"},{"p":"ينقسم تحويل الوحدات إلى نوعين: التحويلات التي يجب أن تحصل عليها بشكل صحيح تمامًا، والتحويلات التي تحتاجها بشكل تقريبي. تتعامل هذه الأدوات مع كليهما، ويتمثل العمل في تذكر أيهما."},{"l":["[[تحويل الطول|تحويل الطول]] — المتري إلى الإمبراطوري والعودة: ملليمتر، سنتيمتر، متر، كيلومتر، بوصة، قدم، ياردة، ميل.","[[تحويل الوزن|تحويل الوزن]] — جرام، كيلوجرام، أوقية، رطل، طن. الشيء الذي يجب التحقق منه قبل الوصفة أو ملصق الشحن.","[[محول درجة الحرارة|محول درجة الحرارة]] — مئوية، فهرنهايت، كلفن. لأن -10 درجة مئوية ليست 14 درجة فهرنهايت، والصيغة ليست ضربًا.","[[محول السرعة|محول السرعة]] — كم/ساعة، ميل في الساعة، م/ث، عقدة. مفيد للحد الأقصى للسرعة الأجنبية أو المواصفات الهندسية.","[[area-converter|محول المساحة]] — متر مربع، قدم مربع، فدان، هكتار. هذا هو الشيء الذي يقدره الناس بشكل سيء عند شراء أو استئجار العقارات.","[[محول الحجم|محول الحجم]] — لتر، ملليلتر، جالون، كوب، متر مكعب.","[[time-converter|تحويل الوقت]] — الثواني، الدقائق، الساعات، الأيام، الأسابيع."]},{"b":"هناك فخان للتحويل يستحقان المعرفة: الأول هو تخزين البيانات أعلاه (المسوقون يبيعون 10^3، وتقارير أنظمة التشغيل 2^10)، والاقتصاد في استهلاك الوقود - السيارة التي يبلغ سعرها 40 ميلا في الغالون (الإمبراطوري) أقرب إلى 33 ميلا في الغالون (الولايات المتحدة) من 40، لأن الجالون الإمبراطوري أكبر. إن الخطأ في الخطأ الثاني يجعل السيارة المستأجرة تبدو فعالة بشكل غير واقعي."},{"h":"الاثنان اللذان لن تتوقع أنهما في حاجة إليهما"},{"l":["[[رقم عشوائي|مولد الأرقام العشوائية]] — يتم السحب ضمن نطاق لإجراء سحب أو شريحة أو تقسيم A/B سريع. مفيد على وجه التحديد لأنه يزيل الشك في أنك قمت بتزويره.","[[dice-roller|Dice Roller]] — أي حجر نرد من رمي عملة معدنية إلى حجر نرد ذي عشرين جانبًا، في لعبة لوحية أو جلسة على الطاولة حيث يتم رمي حجر النرد الحقيقي من على الطاولة للمرة الأخيرة."]},{"h":"استخدام الآلة الحاسبة بشكل صحيح"},{"p":"الآلة الحاسبة تساعدك فقط إذا كنت تعرف الرقم الذي تسأل عنه. ثلاث عادات تصنع الفارق."},{"l":["**التقريب أولاً، والحساب ثانيًا.** إذا لم يغير الرقم الدقيق قرارك، فاستخدم رقمًا مستديرًا. يمكن التحقق من النسب المئوية للأرقام المستديرة في رأسك، مما يؤدي إلى اكتشاف أخطاء الإدخال.","**السلامة-تحقق من الحجم.** قبل تصديق النتيجة، اسأل ما إذا كان يجب أن تكون أكبر أم أصغر من المدخلات، وبأي حجم تقريبًا. معظم الأخطاء الحسابية تنجو من كل شيك باستثناء هذا الشيك.","**قم بتصوير المدخلات، وليس المخرجات.** عند إعادة إجراء العملية الحسابية لاحقًا، ما يهم هو معرفة ما افترضته، وليس ما خلصت إليه."]},{"h":"الأسئلة التي يطرحها الناس في الواقع"},{"p":"**هل يتم تخزين أرقامي في أي مكان؟** لا. تتم الحسابات في متصفحك ولا يتم نقل أي شيء أو الاحتفاظ به.\\n\\n**هل تعمل هذه الأشياء على الهاتف؟** نعم، والآلات الحاسبة مصممة للاستخدام بيد واحدة.\\n\\n**ما هو معيار التحويل الذي تستخدمه لتخزين البيانات؟** الرقم العشري (1 كيلو بايت = 1000 بايت) بشكل افتراضي، لأن هذه هي الطريقة التي يتم بها بيع التخزين. تُبلغ أنظمة التشغيل عن الملفات الثنائية، وهذا هو سبب انكماش محرك الأقراص - حيث تشرح الأداة الفرق بدلاً من اختيار جانب بصمت.\\n\\n**هل يمكنني تضمينها في موقعي الخاص؟** لا. قم بوضع إشارة مرجعية عليها بدلاً من ذلك؛ تكلفة ذلك صفر ومشكلة الدقة ملك لك."},{"h":"النسب المئوية: الأخطاء الأربعة التي تهم"},{"p":"تقريبًا كل نسبة خطأ يرتكبها الشخص في حياته اليومية هي واحدة من نفس الأخطاء الأربعة. تسميتها تجعل تجنبها."},{"l":["**قاعدة خاطئة.** \\"ارتفاع بنسبة 10% ثم انخفاض بنسبة 10% يتركك من حيث بدأت\\" غير صحيح، لأن كلاهما ينطبق على أساسين مختلفين. عشرة في المائة من 100 هي 10؛ عشرة في المائة من 90 هي 9.","**النسبة المئوية.** يؤدي تجميع خصمين إلى ضربهما (0.8 × 0.8 = 0.64، أي خصم 36%)، ولا يضيفهما.","**النسبة المئوية مقابل النقاط المئوية.** ارتفع المعدل الذي يتراوح من 4% إلى 6% بنقطتين مئويتين، ولكن بنسبة 50% بالقيمة النسبية. إن السياسة والطب مليء بهذا الالتباس، وهو ليس مصادفة دائما.","**التقريب مبكر جدًا.** يؤدي تقريب خطوة متوسطة قبل تطبيق النسبة المئوية إلى تفاقم الخطأ. حافظ على الدقة الكاملة حتى الرقم النهائي، وقم بالخطوة الأخيرة على الآلة الحاسبة وليس في رأسك."]},{"p":"إذا كنت تأخذ عادة واحدة فقط من هذا القسم بأكمله، فخذ هذه العادة: قبل أن تقتبس نسبة مئوية لأي شخص، أعد ذكر النسبة المئوية *من*. نصف الحجج التي ستكون لديك حول رقم ما هي في الواقع حجج حول المقام."},{"h":"معرفة متى تتوقف عن الحساب"},{"p":"هناك نقطة تتوقف فيها الدقة عن كونها مفيدة. إن الدفع شهريًا إلى منزلتين عشريتين له معنى. التكلفة الإجمالية المتوقعة إلى ثمانية منازل عشرية هي وسيلة لتجنب القرار الفعلي، وهو ما إذا كان القرض يتناسب مع ما يمكنك تحمله دون ضغوط.\\n\\nوالاختبار المفيد هو سؤال الحساسية: هل يتغير القرار إذا تحرك هذا المدخل بنسبة 10%؟ إذا لم يكن الأمر كذلك، توقف عن تحسينه واستخدم الوقت الإضافي على المتغير الذي يحرك الإجابة - عادةً ما يكون المصطلح بدلاً من السعر، أو قائمة الأسعار بدلاً من الخصم."},{"p":"وأحد الحدود الجديرة بالذكر بوضوح: هذه الآلات الحاسبة هي عمليات حسابية، وليست نصيحة. إن هدف الادخار وتاريخ التقاعد وخطة سداد الديون كلها قرارات تتعلق بالمخاطر والسلوك والوقت، ولا يمكن لعلامة تبويب المتصفح أن تزن أيًا من هذه القرارات. يمكن أن يخبرك بما تعنيه الأرقام فقط بمجرد أن تقرر ما تفترضه. هذا التمييز هو الفرق بين كون الآلة الحاسبة مفيدة وبين كونها مسؤولة."},{"h":"النسخة ذات السطر الواحد"},{"p":"قم بوضع إشارة مرجعية على حاسبات المال والتاريخ بشكل صحيح، وتعامل مع مؤشر كتلة الجسم كإشارة واحدة بدلاً من حكم، وتذكر أن النسب المئوية المكدسة تتضاعف، وتحقق من تحويل الوحدة كلما كان الرقم يدخل في أي شيء تعاقدي. وهذا يغطي كل شيء تقريبًا."}]},"image-and-design-tools":{"title":"14 أداة مجانية للصور والتصميم تعمل في متصفحك","description":"يمكنك ضغط الصور وتغيير حجمها وإعدادها وإنشاء تأثيرات CSS ولوحات الألوان وفحوصات التباين والأيقونات المفضلة دون تثبيت Photoshop أو مجموعة التصميم.","category":"أدوات التصميم","blocks":[{"p":"يواجه العمل الصوري مشكلة محددة: العمل عادةً ما يكون صغيرًا، والأدوات المعروضة هائلة. أنت بحاجة إلى حذف 400 كيلو بايت من الصورة الرئيسية، أو الحصول على قيمة سداسية عشرية ذكرها المصمم الخاص بك، أو إنشاء رمز مفضل لم يقم أحد بإنشائه بعد. وهذا لا يتطلب الاشتراك.\\n\\nتغطي الأدوات الأربعة عشر أدناه إعداد الصور، والعمل بالألوان، وإنشاء تأثيرات CSS، وأصول الإنتاج الصغيرة التي تفشل. يتم تشغيل كل واحدة منها محليًا، وهو ما يهم الصور أكثر من النص: الصورة التي قمت بضغطها للتو غالبًا ما تكون صورة لم تنشرها بعد."},{"h":"تحضير الصور للويب"},{"p":"معظم مشاكل الصورة هي في الواقع مشاكل في الوزن. الصفحة التي تبدو بطيئة عادةً ما تحمل صورًا أكبر من حجم العرض الخاص بها، بتنسيق خاطئ، وبإعدادات جودة لم يشكك فيها أحد على الإطلاق."},{"l":["[[image-compressor|Image Compressor]] — تقليل حجم الملف مع الحفاظ على الصورة سليمة بصريًا. قم بتشغيله قبل تحميل أي شيء إلى نموذج به حد للحجم.","[[image-resizer|Image Resizer]] — اضبط أبعاد البكسل الفعلية التي تحتاجها. هذا هو الفوز الأكبر: صورة بحجم 4000 بكسل معروضة بحجم 800 بكسل تحمل خمسة أضعاف البيانات التي تحتاجها.","[[image-to-base64|Image to Base64]] — تحويل صورة صغيرة إلى عنوان URI للبيانات لتضمينها في CSS أو HTML أو قالب بريد إلكتروني."]},{"b":"الترتيب مهم. تغيير الحجم أولا، والضغط ثانيا. يؤدي ضغط صورة بحجم 4000 بكسل إلى إنتاج ملف أثقل بكثير من تغيير الحجم إلى 800 بكسل ثم الضغط بنفس الجودة، لأن الضاغطات تنفق جهدها على وحدات البكسل التي سيتم التخلص منها على أي حال."},{"p":"كم يجب أن تضغط؟ الجواب الصادق هو: حتى يبدو الأمر خاطئاً، ثم تراجع خطوة واحدة. بالنسبة لصورة البطل الفوتوغرافية، عادةً ما لا يمكن تمييز الجودة بنسبة 70 إلى 80 بالمائة عن الصورة الأصلية بحجم العرض العادي. للحصول على شعار أو لقطة شاشة أو أي شيء ذي لون مسطح وحواف صلبة، استخدم PNG واضغط بقوة أكبر - فهذه تكسب المزيد وتخسر ​​أقل."},{"p":"قاعدة عملية: أي شيء يقل حجمه عن 200 كيلو بايت يعد مناسبًا للصورة الرئيسية، وأقل من 80 كيلو بايت للصورة المصغرة، وإذا لم تتمكن من الحصول على أقل من 300 كيلو بايت، فمن المحتمل أن تكون لديك مشكلة في البعد وليس مشكلة في الجودة."},{"h":"Base64: عندما يكون التضمين هو الاتصال الصحيح"},{"p":"يؤدي تحويل صورة إلى URI لبيانات Base64 إلى إزالة طلب HTTP، والذي يبدو وكأنه فوز خالص. عادة لا يكون كذلك. السلسلة المشفرة أكبر بمقدار الثلث تقريبًا من الملف الثنائي، ولا يمكن تخزينها مؤقتًا بشكل منفصل، كما أنها تؤدي إلى تضخم CSS أو HTML.\\n\\nمضمنة فقط عندما تكون الصورة صغيرة - أقل من بضعة كيلو بايت - تُستخدم مرة واحدة وحرجة. رمز صغير في قالب بريد إلكتروني واحد هو الحالة الكلاسيكية. بالنسبة لأي شيء يتكرر عبر الصفحات أو أكبر من بضعة كيلو بايت، قم بتقديمه كملف واترك المتصفح يخزنه مؤقتًا."},{"h":"العلامات المائية: ما هو قابل للإزالة بأمانة"},{"l":[]},{"p":"كن واضحًا بشأن ما يفعله هذا. يزيل أو يحجب العلامة المرئية. لا يمكنها إعادة بناء وحدات البكسل الأساسية، فالمعلومات التي تم رسمها قد اختفت، ولا يوجد مرشح يخترعها مرة أخرى. تتراوح النتائج من غير مرئية، عندما تكون العلامة فوق خلفية عادية، إلى مسحة واضحة عندما توضع فوق التفاصيل.\\n\\nهناك شيء آخر يستحق أن نقوله بوضوح: إن إزالة العلامة المائية لشخص آخر ونشر النتيجة يمثل مشكلة حقوق الطبع والنشر في معظم الولايات القضائية، وانتهاكًا للترخيص بغض النظر عما إذا كان سيتم القبض عليك أم لا. إن إزالة العلامات من صورك الخاصة، أو من المخزون الذي قمت بترخيصه، هو ما يناسب هذه الأداة."},{"h":"اللون: تحويل، فحص، اختيار"},{"p":"اللون هو المكان الذي تصبح فيه الأخطاء الصغيرة واضحة جدًا. نسبة تباين تفشل في الوصول إليها، وهي قيمة سداسية عشرية هي في الواقع ثلاثية HSL، وهي لوحة تبدو متماسكة على شاشتك وموحلة على جهاز العرض."},{"l":["[[color-converter|محول الألوان]] — التنقل بين HEX وRGB وHSL. يستحق HSL تعلم القراءة، لأن ضبط اللون 210، والتشبع 40 بالمائة، والخفة 50 بالمائة أسهل بكثير من ضبط القيمة السداسية.","[[مدقق التباين|مدقق التباين]] — اختبار النص على خلفيته مقابل حدود WCAG. هذه هي الأداة الوحيدة الأكثر فائدة في هذه المقالة، لأنها تكتشف مشكلة الامتثال الحقيقية بدلاً من مشكلة الذوق.","[[color-palette|Color Palette Generator]] — قم بإنشاء مجموعة متماسكة عندما تبدأ من لون العلامة التجارية وتحتاج إلى بقية المقياس."]},{"b":"على النقيض من ذلك: تطلب WCAG AA نسبة 4.5 إلى 1 للنص الأساسي العادي و3 إلى 1 للنص الكبير. إذا كنت تختار بين لونين للعلامة التجارية لزر ما، فإن اللون الذي يمكن الوصول إليه عادةً ليس هو اللون الذي يحبه المصمم. تحقق أولاً، ثم قم بإجراء الوسيطة مع البيانات."},{"p":"تحذير واحد بشأن أدوات الألوان: جميعها تفترض أن شاشتك تمت معايرتها وأن الشخص الذي يشاهد صفحتك لديه عيون عاملة. ولا يعد أي من الافتراضين آمنًا. وهذا هو السبب وراء تفضيل التركيبات المفحوصة على النقيض من التركيبات الذاتية."},{"h":"تأثيرات CSS دون فتح أداة التصميم"},{"p":"تعد كتابة التدرج أو الظل متعدد الطبقات يدويًا مهمة غير سارة حقًا. بناء الجملة غير واضح، ولا يمكنك رؤية ما تنتجه، والفرق بين الظل الجيد والظل السيئ هو بضع وحدات بكسل من التمويه."},{"l":["[[gradient-generator|CSS Gradient Generator]] — أنشئ تدرجات خطية وشعاعية وانسخ CSS مباشرة.","[[box-shadow-generator|Box Shadow Generator]] — طبقة من الظلال المتعددة، وهو ما يفصل الارتفاع الدقيق عن الانخفاض الثقيل.","[[border-radius-generator|Border-radius Generator]] - احصل على نصف القطر غير المتماثل الذي يجعل الشكل يبدو مقصودًا.","[[text-shadow-generator|مولد ظل النص]] — مفيد بشكل مقتصد. معظم ظلال النص قوية جدًا؛ يتيح لك هذا ضبط الإزاحة والتمويه حتى يختفي."]},{"p":"الحيلة بالنسبة للأربعة هي ضبط النفس. يُقرأ الظلان - ظل داكن ضيق وآخر ناعم واسع - على أنه ارتفاع مادي. يقرأ One Shadow كموقع ويب منذ خمسة عشر عامًا. أنشئ، انسخ، ثم احذف حتى لا تتمكن من معرفة وجوده."},{"h":"أصول الإنتاج التي ينساها الجميع"},{"l":["[[favicon-generator|Favicon Generator]] — قم بإنتاج مجموعة الأيقونات الصغيرة التي يحتاجها الموقع بالفعل. هذا موجود في القائمة لأن الرموز المفضلة هي الأصل الذي من المرجح أن يكون مفقودًا تمامًا، والرمز المفقود يعرض رمز صفحة متصفح عام يجعل الموقع النهائي يبدو غير مكتمل.","[[emoji-picker|Emoji Picker]] — تصفح الرموز التعبيرية وابحث عنها وانسخها دون الحاجة إلى البحث في منتقي نظام التشغيل. مفيد حقًا عندما تكتب نسخة تحتاج إلى رمز واحد محدد."]},{"h":"مثال عملي: شحن قسم البطل"},{"p":"هنا المجموعة بأكملها تقوم بعمل حقيقي واحد. تحتاج الصفحة إلى بطل مع صورة خلفية وعنوان وزر، ولم يتم إنشاء أي منها بعد."},{"l":["**1. احجز المساحة. ** امنح فتحة الصورة ارتفاعًا ثابتًا في التخطيط، بحيث يكون للصفحة الشكل الصحيح من العرض الأول بدلاً من القفز عندما تصل الصورة الحقيقية.","**2. قم بتغيير الحجم والضغط.** عندما تصل الصورة الحقيقية، قم بتشغيلها من خلال [[image-resizer|Image Resizer]] بعرض 1600 بكسل، ثم [[image-compressor|Image Compressor]] بنسبة 75 بالمائة. هذا هو الملف الذي يمكنك إرساله.","**3. تحقق من التباين في النص. ** العنوان فوق الصورة هو فشل التباين الكلاسيكي. استخدم [[مدقق التباين|مدقق التباين]] لاختيار قوة تراكب داكنة أو لون نص فاتح يمر بـ AA.","**4. أنشئ الزر.** يعطي [[box-shadow-generator|Box Shadow Generator]] الارتفاع، ويحصل [[color-converter|Color Converter]] على لون العلامة التجارية بالتنسيق الذي يحتاجه CSS.","**5. السفينة.** أضف رمزًا مفضلاً من [[favicon-generator|Favicon Generator]] حتى لا تبدو علامة التبويب مهجورة، ويتم الانتهاء من القسم."]},{"p":"خمس أدوات، لا توجد مجموعة تصميم، وكل مخرجات عبارة عن قيمة يمكنك لصقها مباشرة في التعليمات البرمجية."},{"h":"الأسئلة المتداولة"},{"p":"**هل تم تحميل صوري في أي مكان؟** لا. يحدث الضغط وتغيير الحجم والتحويل Base64 في متصفحك، وهذا هو السبب في عدم وجود حد لحجم الملف وعدم وجود قائمة انتظار للتحميل.\\n\\n**هل يؤدي ضغط الصورة إلى فقدان الجودة؟** دائمًا، حسب التعريف. والسؤال هو ما إذا كان مرئيا. عندما تصل الجودة والأبعاد الصحيحة إلى 70 إلى 80 بالمائة، عادةً لا يكون الأمر كذلك.\\n\\n**لماذا لا تزال الصورة التي تم تغيير حجمها تبدو كبيرة؟** قمت بضغطها تسع مرات من أصل عشر قبل تغيير حجمها، أو تقوم بحفظها بتنسيق PNG عندما تكون الصورة أفضل بتنسيق JPEG.\\n\\n**هل يمكنني استخدامها لعمل العميل؟** نعم، بدون إسناد أو قيود تجارية.\\n\\n**هل تعمل على الهاتف؟** نعم، على الرغم من أن تغيير حجم الصور الكبيرة وضغطها على الهاتف يعتمد على ذاكرة جهازك وليس على الخادم."},{"h":"النسخة ذات السطر الواحد"},{"p":"قم بتغيير الحجم قبل الضغط، وتحقق من التباين قبل أن تتجادل حول اللون، وحافظ على الظلال خفية، ولا تنس أبدًا الرمز المفضل. هذا هو معظم ما كانت تفعله لك مجموعة التصميم على أي حال."}]},"math-tools-for-real-numbers":{"title":"6 أدوات رياضية مجانية للأرقام التي لن تتصرف","description":"التدوين العلمي، والكسور العشرية للكسور، والتحقق من الأعداد الأولية، والمضروبات، وGCF/LCM - أدوات متصفح مجانية للعمل على الأرقام التي يسهل الخطأ فيها.","category":"أدوات الرياضيات","blocks":[{"p":"إن الرياضيات التي تحتاجها بالفعل على الكمبيوتر ليست هي الرياضيات التي تم اختبارك عليها. وهي: هل هذا الرقم بالتنسيق الذي يتوقعه النظام، وهل تم تبسيط هذا الكسر، وما مدى سرعة نموه، ولماذا تختلف الآلة الحاسبة وجدول البيانات.\\n\\nتغطي هذه الأدوات الستة تلك المنطقة. يتم تشغيلها محليًا، وهو ما يعني بالنسبة للحساب فائدة واحدة محددة تستحق التسمية: الرقم الذي كتبته لا يتم إرساله إلى أي مكان، لذا يمكنك التحقق من الحساب الذي يتضمن راتبًا أو رصيدًا أو رقم العميل دون تفكير ثانٍ."},{"h":"إدخال الأرقام في شكل تقبله الآلة"},{"p":"تقوم أجهزة الكمبيوتر بتخزين الكسور العشرية ككسور ثنائية. 0.1 لا يمكن تمثيله تمامًا في النظام الثنائي — أقرب قيمة مزدوجة الدقة هي 0.1000000000000000055511151231257827. أضف 0.1 + 0.2 وستحصل على 0.30000000000000004، والتي تطبع كـ 0.3 افتراضيًا وتكسر التحقق من المساواة بهدوء."},{"l":["[[scientific-notation|Scientific Notation Converter]] — التنقل بين الشكل القياسي والشكل العلمي، وهي الطريقة التي تخزن بها معظم السجلات وجداول البيانات وواجهات برمجة التطبيقات الأرقام الكبيرة والصغيرة.","[[كسر عشري|من عشري إلى كسر]] — تحويل كسر عشري إلى كسر صحيح. هذا هو حل المشكلة أعلاه: 0.1 + 0.2 في حساب الكسور الدقيقة هو 3/10، وليس تقريبيًا."]},{"b":"إذا سبق لك أن رأيت إجماليًا خاطئًا بمقدار 0.0000000000000004، فهذا هو السبب. في الكود المالي، الإجابة القياسية هي العمل بالسنتات الصحيحة، أو في مكتبة عشرية، وليس بالفاصلة العائمة أبدًا. إذا سبق لك أن رأيت جدول بيانات لا يتفق مع النص بنسبة ضئيلة، فهذا هو نفس الخطأ الذي يرتدي قبعة مختلفة."},{"p":"يستحق التدوين العلمي أن تتقنه بطلاقة، لأنه يمثل الفرق بين قراءة سطر السجل والتحديق فيه. 6.022e23 و1.6e-19 و3e8 هي عدد أفوجادرو والشحنة الأولية وسرعة الضوء. إذا كانت تبدو وكأنها ضوضاء وليست أرقامًا، فإن تحويل القليل منها من خلال الأداة يؤدي إلى إصلاحها بشكل دائم."},{"h":"الأعداد الأولية، ولماذا يهتم أي شخص"},{"l":["[[Prime-checker|مدقق الرقم الأولي]] — اختبر ما إذا كان الرقم أوليًا، وشاهد تحليله عندما لا يكون كذلك.","[[gcf-calculator|GCF LCM Calculator]] — العامل المشترك الأكبر والمضاعف المشترك الأصغر."]},{"p":"الأعداد الأولية ليست تمرينًا مدرسيًا. يعتمد أمان كل اتصال HTTPS تقوم به على حقيقة أن ضرب عددين أوليين كبيرين أمر سهل، بينما يعد تحليل النتيجة أمرًا صعبًا. عدم التماثل هذا هو الأساس الكامل لـ RSA.\\n\\nللأغراض اليومية، يتم فحص الأعداد الأولية في الغالب حول الكسور. تبسيط الكسر يعني قسمة الأعلى والأسفل على العامل المشترك الأكبر لهما، ولا يمكنك العثور على ذلك بدون التحليل. ولهذا السبب تنتمي هاتان الأداتان معًا: تحقق من العوامل، ثم احصل على GCF وLCM في خطوة واحدة."},{"p":"نصف LCM هو الذي ينساه الناس، وهو الذي يحل مشاكل الجدولة: حدثان يتكرران كل 18 يومًا وكل 12 يومًا يتزامنان كل 36 يومًا. نفس الحساب، وتطبيق مختلف."},{"h":"العوامل، وسرعة انفجارها"},{"l":["[[آلة حاسبة العوامل|آلة حاسبة العوامل]] — ن! للقيم حيث لا تزال الإجابة ذات معنى."]},{"p":"تنمو العوامل بشكل أسرع من أي شيء تقريبًا تقابله على المكتب. 10! حوالي 3.6 مليون. 20! يبلغ حوالي 2.4 كوينتيليون، وهو أكبر من عدد حبات الرمل الموجودة على الأرض بفارق كبير. 52!، عدد طرق خلط مجموعة أوراق اللعب، هو تقريبًا 8 متبوعة بـ 67 رقمًا.\\n\\nوالنتيجة العملية هي أن البرنامج الذي يعدد جميع التباديل يكون جيدًا عند 5 عناصر، ويمكن قبوله عند 8، ويتوقف بشكل دائم عند 12. إذا شعرت أن المهمة لن تنتهي أبدًا وكنت تتكرر فوق التباديل، فمن المؤكد تقريبًا أن هذا هو السبب. إنها أيضًا الحجة ضد معظم أساليب القوة الغاشمة، والتي يتم ذكرها على أنها حسابية وليست رأيًا."},{"h":"الأرقام الرومانية والشيء الغريب فيها"},{"l":["[[roman-numerals|محول الأرقام الرومانية]] — تحويل من وإلى الأرقام الرومانية."]},{"p":"الأرقام الرومانية تستحق الفهم بدلاً من مجرد التحويل، لأن النظام يكشف شيئاً عن التدوين الموضعي. لا يوجد صفر، ولا قيمة مكانية: XI تعني أحد عشر سواء كانت تمثل إحدى عشرة عصا أو أحد عشر ألفًا. ولهذا السبب فإن العمليات الحسابية بالأرقام الرومانية صعبة للغاية، ولهذا السبب استمر النظام لعدة قرون في الغالب في العد والتأريخ بدلاً من الحساب.\\n\\nالقاعدة الطرحية هي الجزء الذي يخطئ فيه الناس. الرابع هو أربعة، وليس السادس؛ التاسع هو تسعة. تعتبر الساعات استثناءً مشهورًا، حيث تستخدم ساعة بيج بن الرقم IIII بدلاً من IV، لأسباب لا يزال المؤرخون يتجادلون حولها. التحويل بدلاً من الاشتقاق هو القرار الصحيح في كل حالة."},{"h":"مثال عملي: التحقق من الكسر باليد"},{"p":"تحتاج الوصفة إلى 0.375 كوبًا ومقياسًا يُقرأ بالجرامات، ويقتبس التقرير نسبة 0.625، وكلاهما يبدو كأرقام كتبها شخص ما على عجل."},{"l":["**1. ابحث عن الكسر الدقيق.** قم بتشغيل 0.375 من خلال أداة [[الكسر العشري|من العشري إلى الكسر]]: 3/8. تشغيل 0.625: 5/8. لا حاجة إلى عادة الآلة الحاسبة التي لا تمتلكها.","**2. بسّط النسبة.** للتعبير عن 3/8 مقابل 5/8، تحتاج إلى العامل المشترك الأكبر 3 و5. تعطي [[gcf-calculator|GCF LCM Calculator]] 1، وبالتالي تكون النسبة 3:5 وهي الأبسط بالفعل.","**3. تحقق من مطالبة المعامل.** إذا أخبرك شخص ما أن قائمة الانتظار المكونة من 9 أوامر تحتوي على 362,880 ترتيبًا، فإن [[حاسبة المعامل|حاسبة المعامل]] تؤكد الرقم 9! هذا هو بالضبط. الآن أنت تعرف ما إذا كان تقدير وقت البناء معقولاً أم لا.","**4. تطبيع أي شيء كبير.** الخادم الذي يبلغ عن 1.5e9 نانو ثانية هو 1.5 ثانية، وفقًا لـ [[scientific-notation|Scientific Notation Converter]] — وهو الفرق بين مشكلة زمن الوصول وحرف التقريب."]},{"h":"ما لا تفعله هذه الأدوات عمدا"},{"p":"إنهم لا يظهرون العمل، ولا يعلمون. إذا كنت بحاجة إلى فهم سبب صحة الصيغة، فإن الآلة الحاسبة هي الأداة الخاطئة - فهي تعطي الإجابة دون سبب، وهذا هو السبب الذي يجعل الناس في نهاية المطاف قادرين على الحساب وغير قادرين على التفكير.\\n\\nكما أنها لا تفعل الدقة التعسفية. ستفقد العوامل والعوامل الكبيرة دقتها بعد النقطة التي تظل فيها الإجابة مفيدة، وعلامة تبويب المتصفح ليست نظامًا جبريًا حاسوبيًا. بالنسبة لأي شيء تكون فيه الصحة ذات أهمية حقيقية - الهندسة، والتمويل، والتشفير - استخدم مكتبة مناسبة ذات حسابات حسابية دقيقة، وليس صفحة ويب."},{"h":"التحقق من العمليات الحسابية الخاصة بك"},{"p":"إن العادة الرياضية الأكثر قيمة ليست السرعة، بل التقدير. قبل تصديق أي نتيجة، اسأل ما إذا كانت بالترتيب الصحيح من حيث الحجم: أكبر أم أصغر من المدخلات، وبأي حجم تقريبًا. معظم الأخطاء الحسابية تنجو من كل عملية فحص أخرى باستثناء هذا الاختبار.\\n\\nالتقريب أولاً يجعل التقدير مجانيًا. تقريب 0.375 إلى 0.4، وتقريب 5/8 إلى 0.6، ومن الواضح أن النسبة تبلغ حوالي 2:3 — قريبة بما يكفي من 3:5 لتأكيد الكسر الذي حسبته بالضبط. إذا اختلفت الإجابة الدقيقة والتقدير، فقد وجدت خطأ في الإدخال بدلاً من مشكلة تقريب، وعثرت عليه في ثوانٍ.\\n\\nوهذا أيضًا هو السبب في أن الآلة الحاسبة ليست بديلاً عن التفكير فيما طلبته منها. ستقوم الأداة بحساب الكمية الخاطئة بشكل مثالي، والدفاع الوحيد هو معرفة كيف يجب أن تكون الإجابة."},{"h":"الأسئلة المتداولة"},{"p":"**هل يتم إرسال مدخلاتي إلى أي مكان؟** لا. يتم تشغيل كل هذه العناصر محليًا في متصفحك.\\n\\n** لماذا 0.1 زائد 0.2 لا يساوي 0.3؟ ** لأنه لا يمكن تمثيل 0.1 أو 0.2 تمامًا في الفاصلة العائمة الثنائية. المجموع هو 0.3000000000000004، وهو أقرب ضعف إلى 0.3.\\n\\n** ما هو حجم المضروب الذي يمكن أن يتعامل معه؟ ** ما يصل إلى 170 قبل تجاوز نطاق المضاعف. بعد ذلك يتم عرض الإجابة بالتدوين العلمي ثم يتوقف عن كونها ذات معنى.\\n\\n**هل يمكنني استخدام المخرجات في الكود؟** نعم. بالنسبة للنتائج العشرية إلى الكسر على وجه الخصوص، استخدم الحساب الصحيح على البسط والمقام بدلاً من التحويل مرة أخرى إلى عدد عشري."},{"h":"النسخة ذات السطر الواحد"},{"p":"استخدم الكسور الدقيقة عندما يتعلق الأمر بالمال، وتذكر أن المضروب ينفجر بشكل أسرع مما تتوقع، والتحليل الأولي هو أساس أمني وخدعة لتبسيط الكسور."}]},"everyday-utility-tools":{"title":"13 أداة مساعدة يومية مجانية: كلمات المرور، ورموز QR، والمؤقتات، وترميز النص","description":"يمكنك إنشاء كلمات مرور، وإنشاء رموز QR، وتشغيل المؤقتات والساعات، وفك تشفير النصوص الثنائية والسداسي عشرية والمشفرة - كل ذلك باستخدام أدوات متصفح مجانية تعمل محليًا، دون الحاجة إلى حساب.","category":"أدوات المساعدة","blocks":[{"p":"هذه المجموعة الأخيرة هي درج النفايات. كلمات المرور، ورموز الاستجابة السريعة، وساعة التوقف، والساعة العالمية، وقلب العملة، وأربع أدوات تقوم بتحويل النص إلى تمثيلات أخرى لنفسه. تافهة بشكل فردي، وبشكل جماعي الأشياء التي تحتاجها في اللحظات الحرجة.\\n\\nالخط الفاصل هو أن جميع الثلاثة عشر تعمل محليًا. بالنسبة لمولد كلمات المرور الذي لا يعد أمرًا رائعًا، فهذا هو السبب وراء إمكانية الوثوق بالأداة على الإطلاق."},{"h":"كلمات المرور: الجزء المهم بالفعل"},{"l":["[[password-generator|Password Generator]] — إنشاء كلمات مرور عشوائية قوية بأي طول وأي مجموعة أحرف.","[[قوة كلمة المرور|مدقق قوة كلمة المرور]] — تقدير مدى مقاومة كلمة المرور للتخمين محليًا."]},{"b":"الحقيقة الوحيدة الأكثر أهمية حول قوة كلمة المرور: **الطول يتفوق على التعقيد، وإعادة الاستخدام تتفوق على كليهما كخطر.** كلمة المرور المكونة من 16 حرفًا والمكونة من كلمات غير مرتبطة هي أقوى وأكثر قابلية للكتابة من مجموعة من الرموز المكونة من 10 أحرف. وفي الوقت نفسه، تؤدي كلمة المرور المعاد استخدامها التي تظهر في عملية اختراق إلى إزالة كل حساب تلمسه مرة واحدة. إن إنشاء كلمة مرور طويلة مميزة لكل موقع هو المهمة بأكملها."},{"p":"إن كيفية تقدير القوة أمر مهم أيضًا. معظم أدوات التحقق تقريبية لحجم مساحة البحث، وهو بديل معقول ولكنه ليس الحقيقة: `CorrectHorseBatteryStaple` يسجل نتائج جيدة في الإنتروبيا، في حين أن `P@ssw0rd1!` يسجل نتائج جيدة في تنوع الأحرف وسيئًا في الممارسة لأنه يظهر في كل قائمة كلمات متصدعة على وجه الأرض.\\n\\nاستخدم المولد لأي شيء يهمك، وإذا كان عليك أن تتذكر كلمة مرور، فاستخدم عبارة مرور مكونة من أربع أو خمس كلمات غير مرتبطة. هذه هي الحالة المحددة التي تتداخل فيها قوة التذكر والقوة."},{"h":"رموز QR: ما يجب وضعه فيها"},{"l":["[[qr-code-generator|QR Code Generator]] - قم بإنشاء رمز QR لعنوان URL أو نص أو تفاصيل Wi-Fi أو معلومات الاتصال."]},{"p":"تعد رموز QR إحدى تلك الأدوات التي يتم فيها تحديد جودة المخرجات بالكامل من خلال قرار واحد: مقدار البيانات التي تدخلها. يتم تشفير عنوان URL القصير في رمز صغير يمكن مسحه بسهولة. يتم تحويل فقرة من النص مع علامات الترقيم إلى شيء كثيف وغير موثوق به بأحجام صغيرة.\\n\\nقاعدتان عمليتان. أولاً، قم دائمًا باختبار الرمز ضوئيًا بالحجم الذي سيتم طباعته فعليًا قبل طباعة مائتين منه. ثانيًا، تتصرف رموز Wi-Fi ورموز URL العادية بشكل مختلف على الهواتف المختلفة - إذا كان الرمز متوجهًا إلى جمهور مختلط، ففضل عنوان URL العادي على الصفحة المقصودة التي ترتبط بعد ذلك، لأنها تعمل في كل مكان ويمكنك تغيير المكان الذي تشير إليه."},{"h":"الوقت: الموقتات والساعات والفخ في المناطق الزمنية"},{"l":["[[stopwatch|Online Stopwatch]] — ساعة توقيت عادية، مفيدة عندما يكون هاتفك في الغرفة الأخرى.","[[pomodoro-timer|مؤقت بومودورو]] — مجموعات تركيز مدتها 25 دقيقة مع فترات راحة، للأشخاص الذين يجدون أن هذا الهيكل يعمل.","[[world-clock|الساعة العالمية]] — التوقيت الحالي في عدة مدن في وقت واحد."]},{"p":"تكتسب الساعة العالمية مكانتها لسبب واحد محدد: وهو التوقيت الصيفي. نصف أخطاء الجدولة في العالم ليست أخطاء حسابية، بل هي لحظة كانت فيها مدينتان تفصل بينهما أربع ساعات في الأسبوع الماضي وخمس ساعات هذا الأسبوع، ولم يقم أحد بالتحقق منها.\\n\\nقبل جدولة أي شيء عبر منطقة زمنية، ضع كلتا المدينتين في الساعة العالمية وانظر - لا تحسب الإزاحة من الذاكرة. وهذا هو السبب أيضًا في أن دعوات الاجتماع يجب أن تحمل منطقة زمنية بدلاً من ساعة مجردة."},{"p":"في مؤقت بومودورو: تعمل التقنية مع نوع معين من المهام - محددة، مركزة، دون انقطاع. إنه لا يعمل من أجل تصحيح الأخطاء، حيث تكون الخطوة الصحيحة عندما تكون عالقة هي الابتعاد، وليس بدء كتلة أخرى مدتها 25 دقيقة. استخدامه عندما يساعد."},{"h":"العشوائية بصراحة"},{"p":"يغطي [[الرقم العشوائي|مولد الأرقام العشوائية]] و[[list-randomizer|List Randomizer]] الحالات التي تظهر بالفعل: اختيار رقم في نطاق، ووضع القائمة في ترتيب عادل. يستحق الجملة على العدالة. كلاهما يستخدم مولدًا عشوائيًا زائفًا، والذي لا يمكن تمييزه عن العملة الحقيقية لتحديد من يدفع ثمن الغداء. بالنسبة لأي شيء ذي أهمية - مثل السحب على الجوائز، أو التخصيص مع الأموال المرفقة - فأنت تريد مصدرًا يمكنك تدقيقه، وعلامة تبويب المتصفح ليست كذلك. القيمة هنا هي إزالة الإنسان، الذي يختار بشكل سيء عندما يكون لديه الدافع."},{"h":"درج الترميز غير المرغوب فيه"},{"p":"أربع أدوات تنقل النص بين التمثيلات. لا يعتبر أي منها تشفيرًا، والتمييز يستحق الذكر لأنه يتم الخلط باستمرار: يمكن لأي شخص عكس التشفير وليس له مفتاح. يتطلب التشفير مفتاحًا."},{"l":["[[binary-text|Binary to Text]] — التحويل بين النص وتمثيله الثنائي.","[[hex-text|Hex to Text]] — التحويل بين النص والست عشري، وهو التمثيل الذي تراه غالبًا في أدوات الشبكة ومصححات الأخطاء.","[[caesar-cipher|Caesar Cipher]] — تحويل الحروف بمقدار ثابت، وهو التشفير الكلاسيكي للفصول الدراسية.","[[rot13-encoder|ROT13 Encoder]] — تدوير الحروف بمقدار 13، وهي حالة خاصة تمثل معكوسها."]},{"p":"هذه مفيدة لشيئين بالضبط. أولاً، فهم كيف يتحول النص إلى بايتات، وهو النموذج العقلي الذي تحتاجه عندما يبدو أي شيء مشوهًا. ثانيًا، تصحيح الأخطاء فعليًا: عندما تظهر الحمولة على شكل سداسي عشري، فإن محول [[hex-text|Hex to Text]] هو الطريقة التي تكتشف بها ما تقوله.\\n\\nفهي ليست مفيدة لإخفاء أي شيء. لا يوجد مفتاح لـ ROT13 - التحول علني - لذا فهو لا يخفي شيئًا عن أي شخص يعرف ما هو ROT13. تحتوي شفرة قيصر على 25 تحولًا محتملاً، والتي يمكن للإنسان كسرها في الدقيقة الأولى."},{"h":"الاثنان اللذان ينسقان الأشياء"},{"l":["[[phone-formatter|Phone Number Formatter]] — لتطبيع أرقام الهواتف إلى تنسيق ثابت.","[[file-size-converter|File Size Converter]] — التحويل بين KB وMB وGB وTB، مع شرح التمييز بين العلامة العشرية والثنائية."]},{"p":"يحتوي محول حجم الملف على نتيجة واحدة ذات قيمة حقيقية: فهو يخبرك لماذا يعلن محرك الأقراص عن عدد أكبر من تقارير جهاز الكمبيوتر الخاص بك. يبيع البائعون قوة تبلغ عشرة، وتبلغ أنظمة التشغيل عن قوة تبلغ اثنين، وتبلغ الفجوة حوالي 7 بالمائة على كل نطاق. وهذا ليس خطأ، بل هو اتفاقيتين."},{"h":"مثال عملي: استجابة واجهة برمجة التطبيقات المشوهة"},{"p":"فشل خطاف الويب في التحقق من الصحة وتبدو الحمولة في السجل مثل `\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f`. هذا هو التشخيص الثاني والتسعون."},{"l":["**1. تحويل.** الصق `48656c6c6f` في محول [[hex-text|Hex to Text]] — والنتيجة هي `Hello`. لم يتم تشويهه أبدًا، بل تم تشفيره فقط.","**2. تحقق من الشكل.** هناك شيء ما في المنبع وهو الترميز السداسي للحمولة قبل التوقيع. تم حساب التوقيع على النص الأصلي وتم التحقق من صحته مقابل الرقم السداسي، لذلك فشلت المقارنة.","**3. استبعد الاتجاه الآخر. ** إذا أظهر السجل نصًا قابلاً للقراءة، لكانت المشكلة هي العكس: التوقيع على النموذج المشفر.","**4. قم بتأكيد المطالبة بالحجم. ** إذا أبلغ نفس السجل عن حمولة تبلغ 1.2 ميجابايت، فإن [[file-size-converter|محول حجم الملف]] يحدد ما إذا كان ذلك رقمًا عشريًا أو ثنائيًا قبل أن يجادل أي شخص حول الحصة النسبية."]},{"h":"الأسئلة المتداولة"},{"p":"**هل منشئ كلمة المرور آمن إذا كان كل شيء يعمل في المتصفح؟** نعم، وأكثر من مولد كلمة المرور المستند إلى الخادم: يتم إنشاء كلمة المرور على جهازك ولا يتم نقلها مطلقًا، لذلك لا يوجد شيء يمكن اعتراضه أو تسجيله أو اختراقه. والمقايضة هي أنه لا يمكنك استعادة كلمة المرور التي لم تقم بحفظها.\\n\\n**هل يمكنني الوثوق في عملية قلب العملة الافتراضية؟** بالنسبة للقرارات غير الرسمية، نعم. بالنسبة لأي شيء مرتبط بأموال أو جوائز، استخدم مصدرًا يمكنك تدقيقه.\\n\\n**هل الأصفار آمنة؟** لا، لا أحد منهم. لا تحتوي شفرات ROT13 وقيصر على مفتاح سري وهي موجودة لتعليم التشفير، وليس لحماية أي شيء.\\n\\n**هل تعمل هذه العناصر دون الاتصال بالإنترنت؟** بمجرد تحميل الصفحة، نعم — كل شيء محلي.\\n\\n**هل هناك حد لطول النص للمحولات؟** ذاكرة جهازك فقط، حيث لا يتم إرسال أي شيء إلى أي مكان."},{"h":"النسخة ذات السطر الواحد"},{"p":"تتفوق كلمات المرور الفريدة الطويلة على الكلمات الذكية القصيرة، ورمز الاستجابة السريعة يكون جيدًا مثل البيانات الموجودة بداخله، وتحقق من إزاحات المنطقة الزمنية بدلاً من حسابها، والتشفير ليس تشفيرًا."}]}}')},76442,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"Il toolkit dello sviluppatore: 24 strumenti browser gratuiti che sostituiscono le app a pagamento","description":"Una guida pratica alla formattazione, conversione, codifica e debug dei dati utilizzando strumenti di sviluppo gratuiti basati su browser: nessuna installazione, nessun account, niente caricato.","category":"Strumenti per sviluppatori","blocks":[{"p":"La maggior parte dei piccoli lavori che svolgi cento volte a settimana (riformattare una risposta API, decodificare un token, controllare un hash, indentare uno slug di SQL) non necessitano di un IDE, di un abbonamento a pagamento o di una licenza di gruppo. Hanno bisogno di una scheda aperta per novanta secondi.\\n\\nLa raccolta seguente comprende ventiquattro utilità basate su browser che coprono formattazione, conversione, codifica, hashing e debug. Ognuno di essi viene eseguito interamente nella tua pagina: i tuoi dati non vengono mai inviati a un server, il che è più importante di quanto ammettono solitamente gli sviluppatori, perché il payload che incolli è solitamente quello di un cliente."},{"h":"Quali strumenti basati su browser possono e non possono sostituire"},{"p":"Sii realistico riguardo al confine. Questi strumenti sostituiscono i compiti una tantum, a bassa posta in gioco e ad alta frequenza. Non sostituiscono il tuo server linguistico, il tuo debugger, la tua suite di test o qualsiasi cosa tu debba eseguire ripetutamente su un ambiente reale."},{"l":["**Buona compatibilità:** leggere una risposta una volta, eseguire il debug di un singolo valore, convertire un file per un\'importazione, controllare un formato prima della spedizione.","**Cattivo adattamento:** eseguendo lo stesso controllo a ogni distribuzione, trasformando centinaia di file, tutto ciò che deve fallire rumorosamente in CI.","**Mai:** tutto ciò che riguarda credenziali che non è possibile ruotare. Incolla un token revocato, non uno attivo."]},{"p":"Detto questo, il motivo per mantenerli nei segnalibri è la produttività. Un\'attività che richiede quaranta secondi in una scheda del browser non viene mai pianificata, non viene mai delegata e non diventa mai un motivo per aprire un IDE alle otto di sera."},{"h":"Formattazione e conversione dei dati"},{"p":"Il lavoro quotidiano più comune è rendere leggibili i dati. Un\'API restituisce un BLOB a riga singola, un collega invia un file di configurazione con schede alterate da una finestra di chat oppure hai esportato un foglio di calcolo in JSON ed è tornato come un\'unica riga enorme."},{"l":["[[json-formatter|JSON Formatter]]: rientra, convalida e legge un payload. Usalo prima di eseguire il debug: metà di tutti i ticket \\"l\'API è danneggiata\\" sono in realtà JSON non validi con una virgola finale.","[[json-validator|JSON Validator]] — quando hai bisogno di una risposta pass/fail rigorosa piuttosto che di una bella stampa.","[[xml-formatter|XML Formatter]]: lo stesso lavoro per risposte SOAP, feed RSS e Maven POM che nessuno ha più toccato dal 2014.","[[json-to-yaml|JSON to YAML]] e [[json-to-csv|JSON to CSV]]: spostamento dei dati tra i formati effettivamente utilizzati dai sistemi reali."]},{"p":"Tieni a mente l\'ultimo gruppo per uno scenario specifico: un cliente ti consegna un foglio di calcolo e lo aspetta nella sua API. Passare direttamente da CSV a JSON è un lavoro di due minuti anziché un pomeriggio di scripting."},{"h":"Codifica e fuga"},{"p":"I bug di codifica sono sproporzionatamente fastidiosi perché i dati sembrano a posto. Il valore \\"San José & Sons\\" arriva come \\"San Jos%C3%A9 %26 Sons\\" e il confronto con il database non riesce per ragioni invisibili nei log."},{"l":["[[url-encoder|Codificatore/decodificatore URL]]: determina immediatamente se una stringa di query è doppia codificata.","[[base64-encoder|Codificatore/decodificatore Base64]]: decodifica un frammento di certificato o codifica una piccola risorsa da incorporare nel CSS.","[[html-entity-encoder|Codificatore/decodificatore di entità HTML]]: scopri se quel \\"&\\" nella tua pagina proviene dal tuo modello o dai tuoi dati.","[[unicode-converter|Unicode Converter]] — utile quando un carattere \\"rotto\\" risulta essere legittimo reso nella codifica sbagliata.","[[number-base-converter|Number Base Converter]]: controlla un colore, una maschera di bit di autorizzazione o un indirizzo di memoria senza un\'app calcolatrice."]},{"b":"Un\'abitudine pratica: quando un valore arriva confuso, decodificalo uno strato alla volta e incolla ogni risultato in un campo vuoto. Se la prima decodifica produce testo leggibile, il problema è una codifica aggiuntiva da qualche parte a monte. Se produce mojibake, hai un problema di codifica piuttosto che un problema di fuga, e questi due problemi necessitano di soluzioni diverse."},{"h":"Identificatori, hash e token"},{"p":"Questo gruppo è il luogo in cui gli sviluppatori perdono la maggior parte del tempo alla ricerca dello script locale corretto che hanno scritto una volta e poi hanno perso."},{"l":["[[uuid-generator|UUID Generator]]: genera identificatori v4 per dati seed, partite o una riga rapida del database.","[[md5-generator|MD5 / SHA Hash Generator]]: verifica un download o conferma che due file che dovrebbero essere identici lo siano effettivamente.","[[timestamp-converter|Timestamp Converter]]: lo strumento più utilizzato nell\'intero elenco. Quando una riga di registro riporta 1761000000, questo è ciò che indica se l\'incidente si è verificato durante o prima della distribuzione."]},{"p":"Il convertitore di timestamp si guadagna da vivere per un motivo specifico: un numero di epoca è inequivocabile e inutile allo stesso tempo. Sai esattamente quando è successo qualcosa e non puoi dirlo a un collega. La conversione una volta di solito risolve una questione più forte di quanto dovrebbe."},{"h":"Confronto e debug"},{"l":["[[regex-tester|Regex Tester]]: l\'elemento con la leva più alta qui. Un\'espressione regolare che sembra corretta e non corrisponde a nulla è uno dei bug più costosi in fase di sviluppo, perché fallisce silenziosamente nell\'unico posto in cui nessuno la legge.","[[html-preview|Anteprima HTML]]: esegue l\'iterazione su un frammento di markup per verificare come viene effettivamente visualizzato."]},{"p":"Metti alla prova le tue espressioni regolari rispetto all\'input che effettivamente ti aspetti, inclusa la stringa vuota, un nome Unicode e un valore con una nuova riga. La maggior parte dei modelli si interrompe nel terzo caso e nessuno se ne accorge finché non arrivano i dati di produzione."},{"h":"Un esempio pratico: tre strumenti, un incidente noioso"},{"p":"Ecco la sequenza che mi ha convinto a segnare tutto questo tra i preferiti. Un cliente ha segnalato che un record inviato martedì mancava dal report di giovedì."},{"l":["**1. Converti il ​​timestamp.** Il processo di report ha registrato l\'ora di creazione del record come valore epoch. Il [[timestamp-converter|Timestamp Converter]] ha mostrato che il record è stato creato alle 23:00 locali, ovvero martedì: il problema era il fuso orario del lavoro, non il record.","**2. Formatta il payload.** Prendendo il JSON archiviato attraverso il [[json-formatter|JSON Formatter]] è stato rivelato che il record è stato scritto con un campo data nullo, perché il client ha chiamato due volte lo stesso endpoint a 200 ms di distanza e la seconda scrittura ha vinto.","**3. Confronta i payload.** Entrambi i record contenevano la stessa chiave API e lo stesso timestamp del client, il che indicava un nuovo tentativo anziché due clienti separati."]},{"p":"Tempo trascorso totale: quattro minuti. Il precedente tentativo di indagine, che cercava la stessa causa principale in una piattaforma di disboscamento, ha richiesto un pomeriggio e ha prodotto una conclusione sbagliata."},{"h":"Privacy: perché l\'esecuzione locale è la vera caratteristica"},{"p":"Ogni strumento in questa libreria elabora il tuo input all\'interno del tuo browser. Non viene caricato nulla, il che significa nessuna domanda sulla conservazione, nessun accordo con il processore e nessuna conversazione scomoda sul payload di produzione che hai incollato tre minuti fa.\\n\\nQuesto è il motivo per preferire questi strumenti rispetto a una \\"API pastebin\\" ospitata o a un servizio online che ti chiede di registrarti. Significa anche che continuano a lavorare su un volo, in un seminterrato o quando la VPN aziendale ha deciso di bloccare un altro dominio."},{"p":"Un avvertimento vale la pena dirlo chiaramente: una pagina con funzionalità offline è privata solo se la pagina stessa è il codice che pensi che sia. Su una macchina condivisa, usa una finestra privata e chiudila quando hai finito, soprattutto se hai decodificato i token."},{"h":"Costruire un flusso di lavoro attorno a loro"},{"p":"Gli strumenti sono individualmente banali. Il valore sta nell\'abitudine di raggiungerne uno immediatamente invece di \\"arrivarci più tardi\\", perché più tardi è quando scrivi uno script usa e getta, o apri un IDE, o decidi che non vale la pena controllarlo affatto."},{"l":["Aggiungi la raccolta ai segnalibri, non i singoli URL, e inseriscila nella barra degli strumenti del browser.","Quando qualcosa sembra sbagliato, controllalo prima di formulare una teoria. Costa quindici secondi; uccide intere classi di conclusioni errate.","Quando hai controllato la stessa cosa due volte, questo è il segnale per automatizzarla, ma non automatizzare in caso di sospetto.","Non incollare segreti di produzione. Ruota tutto ciò di cui non sei sicuro."]},{"h":"Domande frequenti"},{"p":"**Questi strumenti sono gratuiti?** Sì, completamente, senza account e senza limiti di utilizzo. Non esiste un livello a pagamento che trattenga qualcosa di base.\\n\\n**Funzionano offline?** Una volta caricata la pagina, sì, tutto viene eseguito nel tuo browser. Il ricaricamento richiede una connessione.\\n\\n**Posso usarli per lavori commerciali?** Sì. L\'output è tuo senza requisiti di attribuzione.\\n\\n**Esiste un\'API?** No, e questo è intenzionale: il valore è l\'interfaccia. Esporta l\'output ed elaboralo come preferisci.\\n\\n**Perché invece non installare semplicemente uno strumento CLI?** Installane uno quando ne hai bisogno tre volte. Utilizza una scheda del browser per i primi due."}]},"text-tools-for-writers":{"title":"17 strumenti di testo gratuiti per scrittori, studenti ed esperti di marketing","description":"Pulisci il testo, conta le parole con precisione, formatta elenchi e trasforma le bozze in qualcosa di pubblicabile, con strumenti browser gratuiti che non caricano mai il tuo testo.","category":"Strumenti di testo","blocks":[{"p":"Scrivere per lavoro comporta una quantità sorprendente di lavoro noioso meccanico che non ha nulla a che fare con la scrittura: eliminare gli spazi bianchi vaganti da un paragrafo incollato, controllare un limite di parole, deduplicare un elenco di nomi, convertire qualcosa in uno slug URL.\\n\\nQuesti diciassette strumenti sono per quella parte del lavoro. Funzionano tutti localmente nel browser, il che non è un dettaglio da poco: la bozza che incolli spesso non è pubblicata e l\'elenco che stai ordinando contiene spesso i dati personali di qualcuno."},{"h":"Misurare ciò che hai scritto"},{"p":"Il conteggio delle parole sembra risolto finché un cliente non chiede esattamente 800 parole e il tuo editor ne dice 820, oppure un modulo rifiuta il tuo testo a 1.995 caratteri senza alcuna spiegazione di dove sia andato il ritorno a capo."},{"l":["[[contatore-parole|Contatore-parole]] — la misura standard. Incolla, leggi, aggiusta.","[[letter-counter|Contatore lettere]]: conta i caratteri e la frequenza delle lettere. Utile quando si esegue il debug del motivo per cui un paragrafo sembra sbagliato: di solito si tratta di uno schema di lettere ripetuto, non di un sogno."]},{"p":"Una nota su cosa significa \\"una parola\\": diversi contatori non sono d\'accordo su sillabazione, numeri e URL. Se un numero esatto è importante, utilizza lo stesso contatore utilizzato dalla persona che controlla il tuo lavoro e concordalo in anticipo. Questa è una fonte veramente comune di argomenti piccoli e inutili."},{"h":"Ripulire la copia che non hai scritto"},{"p":"La maggior parte del testo che ricevi è leggermente danneggiato: doppi spazi da un copia-incolla, una tabulazione vagante, maiuscole incoerenti da qualcuno che digita in fretta. Ripararlo manualmente è lento e soggetto a errori."},{"l":["[[text-trimmer|Text Trimmer]]: rimuove gli spazi bianchi iniziali e finali da ogni riga contemporaneamente. Ciò risolve più report \\"la formattazione sembra interrotta\\" rispetto a qualsiasi altra cosa in questo elenco.","[[text-case-converter|Text Case Converter]]: cambia tra maiuscole e minuscole della frase, maiuscole e minuscole del titolo, superiore e inferiore in un blocco. È anche il modo più veloce per annullare un paragrafo BLOC MAIUSC accidentale.","[[text-to-slug|Text to Slug]]: trasforma un titolo in uno slug URL pulito. Incolla il tuo titolo, fai lo slug, fatto."]},{"p":"Il generatore di slug ha un altro utilizzo oltre agli URL: è un modo veloce per creare un nome file o un\'ancora leggibile che un essere umano possa analizzare a colpo d\'occhio, il che batte `final_final_v3`."},{"h":"Lavorare con gli elenchi"},{"p":"Elenchi, inventari, fusioni di posta, pulizia dei tag, risposte ai sondaggi, colonne dei fogli di calcolo: a un certo punto tutto diventa un elenco e ogni elenco deve essere ordinato, deduplicato o randomizzato."},{"l":["[[duplicate-line-remover|Duplicate Line Remover]]: confronta due elenchi o puliscine uno. L\'output indica quanti duplicati sono stati rimossi, il che è utile quando riporti il ​​risultato.","[[list-sorter|List Sorter]] — lo stesso lavoro per l\'input di elenchi strutturati.","[[list-randomizer|List Randomizer]]: mescola l\'ordine di estrazione, una sequenza di quiz o una lista delimitata in modo che nessuno sospetti favoritismi.","[[line-number-adder|Line Number Adder]]: numero di righe per riferimento in un ticket o in un commento di revisione del codice."]},{"b":"La classica trappola qui è un elenco che sembra deduplicato ma non lo è: `Apple`, `apple ` e `Apple.` sono tre righe diverse di un computer. Taglia gli spazi bianchi ed elimina la punteggiatura finale prima di eseguire la deduplica, altrimenti non unirai nulla e concluderai che i dati sono puliti."},{"h":"Anteprima e formattazione"},{"p":"Markdown ha vinto, ma non in modo uniforme. Metà dei tuoi strumenti lo rendono, metà no, e la metà che non lo fa è solitamente quella in cui deve incollarsi qualcuno più anziano."},{"l":["[[markdown-preview|Anteprima Markdown]]: rendering dal vivo, così puoi verificare che una tabella o un elenco nidificato appaia effettivamente prima che raggiunga un client.","[[text-repeater|Text Repeater]] — ripete una stringa N volte. Utile per generare riempimento, dati di test o, occasionalmente, per evidenziare un punto in un documento."]},{"p":"L\'anteprima Markdown è lo strumento che fa risparmiare più tempo in tutta questa serie, perché una tabella rotta in un documento renderizzato è molto più visibile - e molto più imbarazzante - di una tabella rotta in testo non elaborato."},{"h":"Il resto e quando raggiungerli"},{"l":["[[random-string|Generatore di stringhe casuali]]: genera nonce leggibili, ID segnaposto o codici funzione. Meglio che inventare qualcosa a mano, perché non lo riutilizzerai accidentalmente.","[[codice-morse|Traduttore di codice Morse]]: davvero divertente, occasionalmente utile per un progetto a tema o un puzzle."]},{"p":"Si tratta di strumenti a frequenza più bassa, ma non costa nulla mantenerli nei segnalibri e risolvono il problema specifico di \\"Ho bisogno di un valore dall\'aspetto casuale in questo momento e non mi fido di me stesso per crearne uno\\"."},{"h":"Un passaggio di editing realistico"},{"p":"Ecco l\'ordine che funziona quando arriva una bozza da qualcun altro e deve uscire a tuo nome."},{"l":["**1. Ritaglia.** Esegui prima l\'intero documento attraverso il [[text-trimmer|Text Trimmer]]. Il danno da spazi bianchi si nasconde all\'interno dei paragrafi dove non lo vedrai mai.","**2. Pulisci maiuscole/minuscole.** Utilizza il [[text-case-converter|Text Case Converter]] solo per il titolo. Non applicare mai la conversione dei casi a una bozza completa: distrugge i nomi propri.","**3. Misura.** Controlla la lunghezza con il [[contatore di parole|Contatore di parole]] prima di scrivere, in modo da sapere quale forma dovrà avere il pezzo.","**4. Anteprima.** Se contiene Markdown, esegui il rendering con [[markdown-preview|Anteprima Markdown]].","**5. Slug.** Genera lo slug dell\'URL per ultimo, dal titolo finale, con [[text-to-slug|Text to Slug]]: la modifica successiva del titolo interrompe lo slug."]},{"p":"L\'intero passaggio richiede pochi minuti ed elimina la categoria di errore in cui un documento è tecnicamente corretto e visibilmente sbagliato."},{"h":"Le domande degli scrittori sulla privacy"},{"p":"**Il mio testo non pubblicato lascia il mio computer?** No. Questi strumenti elaborano il testo nel tuo browser e nulla viene memorizzato o trasmesso.\\n\\n**Esiste un limite di lunghezza?** Non esiste alcun limite lato server perché non è prevista alcuna chiamata al server. Gli input estremamente grandi sono limitati dalla memoria del tuo dispositivo.\\n\\n**Posso utilizzare l\'output a fini commerciali?** Sì, liberamente, senza attribuzione.\\n\\n**Funzionano su un telefono?** Sì. Il layout si adatta e viene eseguito lo stesso codice."},{"h":"Cosa questi strumenti non faranno per te"},{"p":"Vale la pena essere schietti riguardo ai limiti, perché uno strumento che meccanizza la cosa sbagliata produce solo un errore più veloce.\\n\\nNessuna di queste utilità può dirti se una frase è chiara, se la fonte di un\'affermazione o se un tono è giusto per il pubblico. Contano i caratteri; non giudicano la prosa. Un testo che ottiene un ottimo punteggio in ogni metrica di questa pagina può ancora essere illeggibile.\\n\\nNé modificano. Nel momento in cui ti ritrovi a riscrivere singole clausole a mano su larga scala, sei diventato troppo grande per uno strumento di testo e desideri un editor adeguato, un trova e sostituisci con regex (che il [[regex-tester|Regex Tester]] è veramente utile per provare) o uno script. Utilizza il browser per il livello meccanico e mantieni il tuo giudizio per tutto ciò che è al di sopra di esso."},{"p":"Un\'altra cosa che non faranno è riparare una cattiva fonte. Se il tuo foglio di calcolo è pieno di nomi incoerenti: \\"Dr\\", \\"DR\\", \\"Dr.\\" tutto in una colonna: uno strumento ordinerà e deduplicherà ciò che hai fornito fedelmente e avrai ancora tre voci dove dovrebbe essercene una. La pulizia dei dati è una decisione, non un passaggio meccanico. Decidi prima la forma canonica, poi applicala, quindi controlla."},{"h":"Mantenere una lista di lavoro utilizzabile"},{"p":"Se mantieni un elenco di lead, collegamenti, riferimenti o termini, questo si degrada silenziosamente. La modalità di errore è sempre la stessa: le voci che sembrano identiche non lo sono e un\'unione non rimuove nulla.\\n\\nUn passaggio di manutenzione che funziona è noioso: ritaglia gli spazi bianchi, standardizza le maiuscole, elimina la punteggiatura finale, quindi deduplica. In questo ordine, il taglio dopo la deduplicazione fa perdere le voci. Farlo una volta al mese su un elenco attivo trasforma un pasticcio irrecuperabile di due ore in un lavoro di dieci minuti.\\n\\nQuando è necessario riconciliare due elenchi, ad esempio un elenco di registrazione rispetto a un elenco di presenze, ordinali prima entrambi con [[list-sorter|List Sorter]], in modo che si allineino, quindi confrontali a occhio. Ordinare entrambe le parti prima del confronto è la differenza tra un controllo di due minuti e una caccia di venti minuti."},{"h":"L\'asporto"},{"p":"Nessuno di questi strumenti è intelligente. Questo è il punto: rimuovono il cinque per cento meccanico della scrittura che non è scrittura, quindi il restante novantacinque per cento riguarda in realtà le frasi. Aggiungi ai segnalibri quelli che usi mensilmente, ignora il resto e smetti di correggere gli spazi bianchi manualmente."}]},"calculators-and-converters-guide":{"title":"18 calcolatori e convertitori gratuiti per i numeri con cui hai effettivamente a che fare","description":"Percentuali, sconti, mance, prestiti, date, BMI e conversioni di unità: calcolatori browser gratuiti che mostrano il loro ragionamento e non salvano mai i tuoi input.","category":"Calcolatrici","blocks":[{"p":"Tutti hanno bisogno di dividere una fattura, capire se uno sconto è davvero uno sconto e convertire una temperatura o una dimensione di file senza pensarci. Anche tutti, almeno una volta, sbagliano in pubblico.\\n\\nQuesta è una raccolta di diciotto calcolatori e convertitori che coprono denaro, date, salute e conversioni di unità che compaiono nel lavoro e nei viaggi. Funzionano tutti nel browser: nulla viene salvato, quindi i numeri che digiti non sono affari di nessuno se non tuoi."},{"h":"Calcoli del denaro"},{"p":"La matematica più comune nel mondo reale è una percentuale di qualcosa. L\'imposta sulle vendite, una mancia, uno sconto, una commissione, un tasso di crescita. La formula è semplice, eppure il motivo per cui le persone sbagliano è quasi sempre lo stesso: applicano una percentuale alla base sbagliata."},{"l":["[[calcolatore-sconto|Calcolatore sconto]]: calcola il prezzo finale e, soprattutto, quanto hai risparmiato. Utile per individuare uno \\"sconto del 50%\\" che in realtà è il 20% dopo un prezzo di listino aumentato.","[[tip-calculator|Tip Calculator]]: dividi un conto, scegli una percentuale, arrotonda per persona se lo desideri.","[[calcolatore-prestito|Calcolatore prestito]]: rata mensile e interesse totale, ovvero il numero che decide effettivamente se un prestito è conveniente."]},{"b":"Sugli sconti: uno sconto del 20% seguito da un altro sconto del 20% non equivale a uno sconto del 40%, bensì del 36%. Percentuali sequenziali composte sulla base ridotta. Qualsiasi calcolatrice presente in questo elenco lo confermerà in circa due secondi ed è il singolo fatto aritmetico più utile in questo articolo."},{"p":"Una nota a parte merita il calcolatore del prestito. La cifra che conta non è la rata mensile, ma l’interesse totale pagato per tutta la durata del prestito, perché quello è il costo reale del prestito. Due prestiti con pagamenti mensili identici e termini diversi possono differire di decine di migliaia di interessi totali."},{"h":"Date e conti alla rovescia"},{"p":"L\'aritmetica delle date è il punto in cui la maggior parte delle persone sbaglia silenziosamente, perché i mesi umani hanno lunghezze diverse e la risposta cambia a seconda che si intenda \\"mesi di calendario\\" o \\"30 giorni\\"."},{"l":["[[Differenza-data|Calcolatore della differenza data]] — giorni (e totale mesi, anni) tra due date.","[[days-until|Calcolatore dei giorni mancanti]]: un conto alla rovescia fino a una data specifica, in cui il numero di giorni lavorativi di solito corrisponde a quello che le persone effettivamente desiderano.","[[age-calculator|Calcolatore età]]: età esatta in anni e giorni, più il compleanno successivo.","[[timestamp-converter|Timestamp Converter]] — un timestamp Unix in una data reale, che è importante se si toccano log, database o risposte API."]},{"p":"La distinzione che fa inciampare le persone: il numero di giorni tra il 1 marzo e il 1 aprile è 31, ma il numero di *mesi* è uno. Se stai calcolando un periodo di preavviso o una durata di abbonamento, indica per iscritto quale unità intendi."},{"h":"Numeri sanitari, onestamente"},{"l":["[[bmi-calculator|Calcolatore BMI]]: indice di massa corporea con le categorie standard e le avvertenze seguenti."]},{"p":"Il BMI è una statistica di screening a livello di popolazione. Non dice nulla sulla massa muscolare, sulla composizione corporea o sulla salute di un individuo, ed è un indicatore inadeguato della forma fisica negli atleti, negli anziani e nei diversi gruppi etnici. Usalo come un punto dati tra tanti o come un modo per tenere traccia di un cambiamento nel tempo, non come un verdetto. Se stai prendendo decisioni che incidono sulla tua salute, lo strumento giusto è un medico, non una scheda del browser."},{"h":"Conversione di unità: quelle di tutti i giorni"},{"p":"La conversione delle unità è divisa in due tipi: conversioni che devi ottenere esattamente nel modo giusto e conversioni di cui hai bisogno in modo approssimativo. Questi strumenti gestiscono entrambi e il lavoro sta nel ricordare quale è quale."},{"l":["[[length-converter|Length Converter]] — da metrico a imperiale e viceversa: millimetri, centimetri, metri, chilometri, pollici, piedi, iarde, miglia.","[[weight-converter|Convertitore di peso]] — grammi, chilogrammi, once, libbre, tonnellate. Quella da controllare prima di una ricetta o di un\'etichetta di spedizione.","[[convertitore-di-temperatura|Convertitore di temperatura]] — Celsius, Fahrenheit, Kelvin. Perché -10°C non è 14°F e la formula non è una moltiplicazione.","[[speed-converter|Speed ​​Converter]] — km/h, mph, m/s, nodi. Utile per un limite di velocità straniero o una specifica tecnica.","[[area-converter|Convertitore di area]] — metri quadrati, piedi quadrati, acri, ettari. Questo è quello che le persone valutano male quando acquistano o affittano un immobile.","[[volume-converter|Convertitore di volume]] — litri, millilitri, galloni, tazze, metri cubi.","[[time-converter|Time Converter]]: secondi, minuti, ore, giorni, settimane."]},{"b":"Due trappole di conversione che vale la pena conoscere: quella dell\'archiviazione dei dati sopra (gli esperti di marketing vendono 10^3, i sistemi operativi riportano 2^10) e il risparmio di carburante: un\'auto quotata a 40 mpg (imperiale) è più vicina a 33 mpg (USA) che a 40, perché il gallone imperiale è più grande. Sbagliare la seconda fa sembrare un’auto a noleggio irrealisticamente efficiente."},{"h":"I due di cui non ti aspetteresti di aver bisogno"},{"l":["[[random-number|Generatore di numeri casuali]]: estrazioni all\'interno di un intervallo, per una lotteria, una parentesi o una rapida divisione A/B. Utile proprio perché toglie il sospetto che tu l\'abbia truccata.","[[dice-roller|Dice Roller]]: qualsiasi dado, dal lancio di una moneta a un dado a venti facce, per un gioco da tavolo o una sessione da tavolo in cui il vero dado è rotolato fuori dal tavolo per l\'ultima volta."]},{"h":"Usare correttamente la calcolatrice"},{"p":"Una calcolatrice aiuta solo se sai per quale numero lo stai chiedendo. Tre abitudini fanno la differenza."},{"l":["**Prima il round, poi calcola.** Se il numero preciso non cambia la tua decisione, usa un round. Le percentuali dei numeri tondi sono controllabili nella tua testa, il che rileva gli errori di input.","**Controlla l\'entità.** Prima di credere a un risultato, chiedi se dovrebbe essere più grande o più piccolo dell\'input e approssimativamente di quanto. La maggior parte degli errori aritmetici sopravvivono a ogni controllo tranne questo.","**Fotografa gli input, non l\'output.** Quando riesegui il calcolo in un secondo momento, ciò che conta è sapere cosa hai ipotizzato, non cosa hai concluso."]},{"h":"Domande che le persone effettivamente pongono"},{"p":"**I miei numeri sono memorizzati da qualche parte?** No. I calcoli avvengono nel tuo browser e nulla viene trasmesso o conservato.\\n\\n**Funzionano su un telefono?** Sì, e le calcolatrici sono progettate per essere utilizzate con una sola mano.\\n\\n**Quale standard di conversione utilizzi per l\'archiviazione dei dati?** Decimale (1 KB = 1000 byte) per impostazione predefinita, perché è così che viene venduto lo spazio di archiviazione. I sistemi operativi riportano il codice binario, motivo per cui un\'unità sembra rimpicciolirsi: lo strumento spiega la differenza anziché scegliere silenziosamente un lato.\\n\\n**Posso incorporarli nel mio sito?** No. Aggiungili invece ai segnalibri; il costo è zero e il problema della precisione è tuo."},{"h":"Percentuali: i quattro errori che contano"},{"p":"Quasi ogni percentuale di errore che una persona commette nella vita quotidiana è uno degli stessi quattro errori. Nominarli li rende evitabili."},{"l":["**Base sbagliata.** \\"Un aumento del 10% e poi un calo del 10% ti lasciano al punto di partenza\\" è falso, perché entrambi si applicano a basi diverse. Il dieci per cento di 100 è 10; il dieci per cento di 90 è 9.","**Percentuale di una percentuale.** La somma di due sconti li moltiplica (0,8 × 0,8 = 0,64, quindi 36% di sconto), non li somma.","**Percentuale rispetto a punti percentuali.** Un tasso che passa dal 4% al 6% è aumentato di 2 punti percentuali, ma del 50% in termini relativi. La politica e la medicina sono piene di questa confusione, e non sempre è casuale.","**Arrotondamento troppo anticipato.** Arrotondare un passaggio intermedio prima di applicare una percentuale aggrava l\'errore. Mantieni la massima precisione fino alla cifra finale e fai l\'ultimo passaggio su una calcolatrice anziché nella tua testa."]},{"p":"Se prendi solo un\'abitudine da tutta questa sezione, prendi questa: prima di citare una percentuale a qualcuno, ribadisci di cosa si tratta una percentuale *di*. La metà delle argomentazioni che avrai riguardo a un numero sono in realtà argomentazioni sul denominatore."},{"h":"Sapere quando smettere di calcolare"},{"p":"C\'è un punto in cui la precisione smette di essere utile. Un pagamento mensile fino a due cifre decimali è significativo. Una proiezione del costo totale fino a otto cifre decimali è un modo per evitare la decisione effettiva, ovvero se il prestito rientra in ciò che puoi permetterti senza stress.\\n\\nIl test utile è la domanda di sensibilità: la decisione cambia se questo input si sposta del 10%? In caso contrario, smetti di perfezionarlo e utilizza il tempo extra sulla variabile che muove la risposta: di solito il termine anziché la tariffa, o il prezzo di listino anziché lo sconto."},{"p":"E c’è un limite che vale la pena affermare chiaramente: questi calcolatori sono operazioni aritmetiche, non consigli. Un obiettivo di risparmio, una data di pensionamento e un piano di rimborso del debito sono tutte decisioni relative al rischio, al comportamento e al tempo, e una scheda del browser non può pesare nessuna di queste. Può dirti cosa implicano i numeri solo una volta che hai deciso cosa stai assumendo. Questa distinzione è la differenza tra l’essere utile e l’essere responsabile."},{"h":"La versione a una riga"},{"p":"Aggiungi correttamente i calcolatori di denaro e data ai segnalibri, tratta il BMI come un segnale piuttosto che un verdetto, ricorda che le percentuali impilate si moltiplicano e controlla una conversione di unità ogni volta che un numero entra in qualcosa di contrattuale. Questo copre quasi tutto."}]},"image-and-design-tools":{"title":"14 strumenti gratuiti per immagini e progettazione eseguibili nel tuo browser","description":"Comprimi, ridimensiona e prepara immagini e genera effetti CSS, tavolozze, controlli di contrasto e favicon senza installare Photoshop o una suite di progettazione.","category":"Strumenti di progettazione","blocks":[{"p":"Il lavoro sull\'immagine ha un problema specifico: il lavoro è solitamente piccolo e gli strumenti offerti sono enormi. Devi eliminare 400 KB da un\'immagine hero, o ottenere un valore esadecimale menzionato dal tuo designer, o generare una favicon che nessuno ha ancora creato. Ciò non richiede un abbonamento.\\n\\nI quattordici strumenti seguenti riguardano la preparazione delle immagini, il lavoro con il colore, la generazione di effetti CSS e le piccole risorse di produzione che passano inosservate. Tutti vengono eseguiti localmente, il che conta più per le immagini che per il testo: la foto che hai appena compresso è spesso una foto che non hai ancora pubblicato."},{"h":"Preparazione delle immagini per il web"},{"p":"La maggior parte dei problemi di immagine sono in realtà problemi di peso. Una pagina che sembra lenta di solito contiene immagini più grandi delle dimensioni di visualizzazione, nel formato sbagliato e con un\'impostazione di qualità che nessuno ha mai messo in discussione."},{"l":["[[image-compressor|Image Compressor]]: riduce le dimensioni del file mantenendo l\'immagine visivamente intatta. Eseguilo prima di caricare qualsiasi cosa in un modulo con un limite di dimensione.","[[image-resizer|Image Resizer]]: imposta le dimensioni in pixel effettive di cui hai bisogno. Questa è la vittoria più grande: un\'immagine da 4000px visualizzata a 800px trasporta cinque volte i dati di cui ha bisogno.","[[image-to-base64|Image to Base64]]: converte una piccola immagine in un URI di dati per l\'incorporamento in CSS, HTML o in un modello di posta elettronica."]},{"b":"L\'ordine conta. Prima ridimensiona, poi comprimi. La compressione di un\'immagine da 4000 px produce un file molto più pesante rispetto al ridimensionamento a 800 px e alla successiva compressione con la stessa qualità, perché i compressori dedicano il loro sforzo ai pixel che verrebbero comunque eliminati."},{"p":"Quanto dovresti comprimere? La risposta onesta è: finché non sembra sbagliato, poi fai un passo indietro. Per un\'immagine fotografica eccezionale, la qualità compresa tra il 70 e l\'80% è solitamente indistinguibile dall\'originale a dimensioni di visualizzazione normali. Per un logo, uno screenshot o qualsiasi cosa con colori uniformi e bordi netti, usa PNG e comprimi di più: guadagni di più e perdi di meno."},{"p":"Una regola pratica: qualsiasi cosa sotto i 200 KB va bene per un\'immagine hero, sotto gli 80 KB per una miniatura, e se non riesci a scendere sotto i 300 KB probabilmente hai un problema di dimensione piuttosto che di qualità."},{"h":"Base64: quando l\'inlining è la chiamata giusta"},{"p":"La conversione di un\'immagine in un URI di dati Base64 rimuove una richiesta HTTP, il che sembra una pura vittoria. Di solito non lo è. La stringa codificata è circa un terzo più grande del file binario, non può essere memorizzata nella cache separatamente e gonfia il tuo CSS o HTML.\\n\\nIn linea solo quando l\'immagine è piccola, inferiore a pochi kilobyte, utilizzata una volta e critica. Una piccola icona in un singolo modello di email è il caso classico. Per qualsiasi cosa ripetuta su più pagine o più grande di pochi kilobyte, servila come file e lascia che il browser lo memorizzi nella cache."},{"h":"Filigrane: ciò che è onestamente rimovibile"},{"l":[]},{"p":"Sii chiaro su cosa fa. Rimuove o oscura il segno visibile. Non è in grado di ricostruire i pixel sottostanti: le informazioni su cui è stata dipinta scompaiono e nessun filtro le inventa nuovamente. I risultati vanno da quelli invisibili, quando il segno si trova su uno sfondo semplice, a una sbavatura evidente quando si trova sui dettagli.\\n\\nUn\'altra cosa che vale la pena dire chiaramente: rimuovere la filigrana di qualcun altro e pubblicare il risultato è un problema di copyright nella maggior parte delle giurisdizioni e una violazione della licenza indipendentemente dal fatto che tu possa essere scoperto o meno. Rimuovere i segni dalle tue immagini o da stock di cui hai ottenuto la licenza è il caso a cui è rivolto questo strumento."},{"h":"Colore: convertire, verificare, scegliere"},{"p":"Il colore è il luogo in cui i piccoli errori diventano molto visibili. Un rapporto di contrasto che non riesce a raggiungere l\'accessibilità, un valore esadecimale che in realtà è una tripla HSL, una tavolozza che appare coerente sul monitor e confusa su un proiettore."},{"l":["[[color-converter|Color Converter]]: spostati tra HEX, RGB e HSL. Vale la pena imparare a leggere HSL, perché tonalità 210, saturazione 40%, luminosità 50% sono molto più facili da regolare manualmente rispetto a un valore esadecimale.","[[contrast-checker|Contrast Checker]]: testa il testo rispetto al suo sfondo rispetto alle soglie WCAG. Questo è lo strumento più utile in questo articolo, perché rileva un vero problema di conformità piuttosto che un problema di gusto.","[[color-palette|Generatore tavolozza colori]]: genera un set coerente quando inizi da un colore di marca e hai bisogno del resto della scala."]},{"b":"Al contrario: le WCAG AA richiedono 4,5 a 1 per il corpo del testo normale e 3 a 1 per il testo grande. Se devi scegliere tra due colori del marchio per un pulsante, quello accessibile di solito non è quello che piace al designer. Prima controlla, poi discuti con i dati."},{"p":"Un avvertimento sugli strumenti per il colore: presuppongono tutti che il tuo monitor sia calibrato e che la persona che visualizza la tua pagina abbia gli occhi funzionanti. Nessuna delle due ipotesi è sicura. Questo è un motivo per preferire le combinazioni controllate dal contrasto rispetto a quelle soggettive."},{"h":"Effetti CSS senza aprire uno strumento di progettazione"},{"p":"Scrivere a mano una sfumatura o un\'ombra a strati è un compito davvero spiacevole. La sintassi è complicata, non puoi vedere cosa stai producendo e la differenza tra un\'ombra buona e una cattiva sono pochi pixel di sfocatura."},{"l":["[[gradient-generator|CSS Gradient Generator]]: crea gradienti lineari e radiali e copia direttamente il CSS.","[[box-shadow-generator|Box Shadow Generator]]: sovrapponi più ombre, che è ciò che separa un\'elevazione sottile da una caduta pesante.","[[border-radius-generator|Border Radius Generator]]: ottieni i raggi asimmetrici che fanno sembrare intenzionale una forma.","[[text-shadow-generator|Text Shadow Generator]] — utile con parsimonia. La maggior parte delle ombre del testo sono troppo forti; questo ti consente di regolare l\'offset e la sfocatura finché non scompare."]},{"p":"Il trucco per tutti e quattro è la moderazione. Due ombre, una stretta e scura e una ampia e morbida, vengono interpretate come elevazione fisica. Un\'ombra sembra un sito web di quindici anni fa. Genera, copia, quindi elimina finché non puoi più dire che è lì."},{"h":"Gli asset produttivi che tutti dimenticano"},{"l":["[[favicon-generator|Favicon Generator]]: produce il piccolo set di icone di cui un sito ha effettivamente bisogno. Questo è nell\'elenco perché le favicon sono la risorsa che molto probabilmente mancherà del tutto e una mancante mostra un\'icona generica della pagina del browser che fa sembrare incompiuto un sito finito.","[[emoji-picker|Selettore emoji]]: sfoglia, cerca e copia emoji senza cercare attraverso un selettore del sistema operativo. Veramente utile quando scrivi un testo che necessita di un simbolo specifico."]},{"h":"Un esempio funzionante: spedire una sezione eroe"},{"p":"Ecco l\'intero cluster che svolge un vero lavoro. Una pagina ha bisogno di un eroe con un\'immagine di sfondo, un\'intestazione e un pulsante e nessuno di questi è stato ancora creato."},{"l":["**1. Prenota lo spazio.** Assegna allo slot dell\'immagine un\'altezza fissa nel layout, in modo che la pagina abbia la forma giusta fin dal primo rendering invece di saltare quando arriva l\'immagine reale.","**2. Ridimensiona e comprimi.** Quando arriva la foto reale, eseguila attraverso il [[image-resizer|Image Resizer]] a 1600px di larghezza, quindi il [[image-compressor|Image Compressor]] al 75%. Questo è un file che puoi spedire.","**3. Controlla il contrasto del testo.** Un\'intestazione sopra una foto è il classico errore di contrasto. Utilizza il [[contrasto-checker|Contrast Checker]] per scegliere un\'intensità di sovrapposizione scura o un colore di testo chiaro che superi AA.","**4. Costruisci il pulsante.** Il [[box-shadow-generator|Box Shadow Generator]] fornisce l\'elevazione e il [[color-converter|Color Converter]] ottiene il colore del marchio nel formato richiesto dal CSS.","**5. Spedisci.** Aggiungi una favicon dal [[favicon-generator|Favicon Generator]] in modo che la scheda non sembri abbandonata e la sezione sia completata."]},{"p":"Cinque strumenti, nessuna suite di progettazione e ogni output è un valore che puoi incollare direttamente nel codice."},{"h":"Domande frequenti"},{"p":"**Le mie immagini vengono caricate ovunque?** No. La compressione, il ridimensionamento e la conversione Base64 avvengono tutti nel tuo browser, motivo per cui non esiste alcun limite di dimensione del file né coda di caricamento.\\n\\n**La compressione di un\'immagine perde qualità?** Sempre, per definizione. La domanda è se è visibile. Con una qualità del 70-80% e dimensioni corrette, di solito non lo è.\\n\\n**Perché l\'immagine ridimensionata appare ancora grande?** Nove volte su dieci hai compresso prima di ridimensionarla o hai salvato come PNG quando una foto è migliore come JPEG.\\n\\n**Posso utilizzarli per il lavoro dei clienti?** Sì, senza attribuzione e senza restrizioni commerciali.\\n\\n**Funzionano su un telefono?** Sì, anche se il ridimensionamento e la compressione di foto di grandi dimensioni su un telefono dipendono dalla memoria del dispositivo e non da un server."},{"h":"La versione a una riga"},{"p":"Ridimensiona prima di comprimere, controlla il contrasto prima di discutere sul colore, mantieni le ombre sottili e non dimenticare mai la favicon. Questo è comunque la maggior parte di ciò che una suite di design faceva per te."}]},"math-tools-for-real-numbers":{"title":"6 strumenti matematici gratuiti per numeri che non si comportano bene","description":"Notazione scientifica, decimali e frazioni, controllo dei numeri primi, fattoriali e GCF/LCM: strumenti browser gratuiti per lavorare sui numeri in cui è facile sbagliare.","category":"Strumenti matematici","blocks":[{"p":"I calcoli di cui hai effettivamente bisogno al computer non sono i calcoli su cui sei stato esaminato. È: questo numero è nel formato previsto dal sistema, questa frazione è semplificata, quanto velocemente cresce e perché la calcolatrice e il foglio di calcolo non sono d\'accordo.\\n\\nQuesti sei strumenti coprono quel territorio. Funzionano localmente, il che per l\'aritmetica significa un vantaggio specifico che vale la pena menzionare: il numero digitato non viene inviato da nessuna parte, quindi puoi controllare senza pensarci due volte un calcolo riguardante uno stipendio, un saldo o la cifra di un cliente."},{"h":"Ottenere numeri in una forma accettata da una macchina"},{"p":"I computer memorizzano le frazioni decimali come frazioni binarie. 0,1 non è esattamente rappresentabile in formato binario: il valore a doppia precisione più vicino è 0,1000000000000000055511151231257827. Aggiungi 0,1 + 0,2 e ottieni 0,30000000000000004, che viene stampato come 0,3 per impostazione predefinita e interrompe silenziosamente un controllo di uguaglianza."},{"l":["[[scientific-notation|Convertitore di notazione scientifica]]: passa dalla forma standard a quella scientifica, che è il modo in cui la maggior parte dei log, dei fogli di calcolo e delle API memorizza effettivamente numeri grandi e piccoli.","[[decimal-fraction|Decimal to Fraction]] — converte un decimale in una frazione esatta. Questa è la soluzione al problema di cui sopra: 0,1 + 0,2 nell\'aritmetica delle frazioni esatte è 3/10, non un\'approssimazione."]},{"b":"Se hai mai visto un totale sbagliato di 0,0000000000000004, ecco perché. Nel codice finanziario la risposta standard è lavorare in centesimi interi, o in una libreria decimale, e mai in virgola mobile. Se hai mai visto un foglio di calcolo in disaccordo con uno script per una frazione di centesimo, si tratta dello stesso insetto che indossa un cappello diverso."},{"p":"Vale la pena padroneggiare la notazione scientifica, perché è la differenza tra leggere una riga di registro e strizzare gli occhi. 6.022e23, 1.6e-19 e 3e8 sono il numero di Avogadro, la carica elementare e la velocità della luce. Se questi sembrano rumore piuttosto che numeri, convertirne alcuni tramite lo strumento risolve il problema in modo permanente."},{"h":"I numeri primi e perché a qualcuno importa"},{"l":["[[prime-checker|Verifica numeri primi]] — verifica se un numero è primo e osserva la sua fattorizzazione quando non lo è.","[[gcf-calculator|GCF LCM Calculator]] — massimo comune divisore e minimo comune multiplo."]},{"p":"I numeri primi non sono un esercizio scolastico. La sicurezza di ogni connessione HTTPS che stabilisci dipende dal fatto che moltiplicare due grandi numeri primi è facile e fattorizzare il risultato è difficile. Questa asimmetria è l’intera base della RSA.\\n\\nPer gli scopi quotidiani, il controllo principale riguarda principalmente le frazioni. Semplificare una frazione significa dividere il massimo e il minimo per il loro massimo comun divisore, e non è possibile trovarlo senza fattorizzare. Ecco perché questi due strumenti vanno insieme: controlla i fattori, quindi ottieni GCF e LCM in un unico passaggio."},{"p":"La metà LCM è quella che le persone dimenticano, ed è quella che risolve i problemi di programmazione: due eventi che si ripetono ogni 18 giorni e ogni 12 giorni coincidono ogni 36 giorni. Stessa aritmetica, diversa applicazione."},{"h":"Fattoriali e velocità con cui esplodono"},{"l":["[[calcolatore-fattoriale|Calcolatore fattoriale]] — n! per valori in cui la risposta è ancora significativa."]},{"p":"I fattoriali crescono più velocemente di quasi tutto ciò che incontri alla scrivania. 10! è di circa 3,6 milioni. 20! è di circa 2,4 quintilioni – di gran lunga maggiore del numero di granelli di sabbia sulla Terra. 52!, il numero di modi per mescolare un mazzo di carte, è circa 8 seguito da 67 cifre.\\n\\nLa conseguenza pratica è che un programma che enumera tutte le permutazioni va bene con 5 elementi, tollerabile con 8 e permanentemente bloccato con 12. Se un\'attività sembra non finire mai e stai ripetendo le permutazioni, questo è quasi certamente il motivo. È anche l’argomentazione contro la maggior parte degli approcci basati sulla forza bruta, dichiarati come aritmetici piuttosto che come opinioni."},{"h":"Numeri romani e la cosa strana che li riguarda"},{"l":["[[numeri-romani|Convertitore di numeri romani]] — converte da e verso numeri romani."]},{"p":"Vale la pena comprendere i numeri romani anziché limitarsi a convertirli, perché il sistema rivela qualcosa sulla notazione posizionale. Non c\'è zero e nessun valore posizionale: XI significa undici sia che rappresenti undici bastoncini o undicimila. Questo è il motivo per cui l’aritmetica con i numeri romani è davvero difficile, e perché il sistema è sopravvissuto per secoli principalmente per il conteggio e la datazione piuttosto che per il calcolo.\\n\\nLa regola sottrattiva è la parte che le persone sbagliano. IV è quattro, non VI; IX è nove. Gli orologi sono una famosa eccezione: il Big Ben usa IIII anziché IV, per ragioni su cui gli storici discutono ancora. Convertire piuttosto che derivare è la scelta giusta in ogni caso."},{"h":"Un esempio pratico: controllare una frazione a mano"},{"p":"Una ricetta richiede 0,375 tazze e una scala che legga in grammi, un rapporto riporta un rapporto pari a 0,625 ed entrambi sembrano numeri digitati in fretta."},{"l":["**1. Trova la frazione esatta.** Esegui 0,375 con lo strumento [[decimal-fraction|Decimal to Fraction]]: 3/8. Corri 0,625: 5/8. Né era necessaria un\'abitudine alla calcolatrice che non hai.","**2. Semplifica il rapporto.** Per esprimere 3/8 contro 5/8, è necessario il GCF di 3 e 5. Il [[gcf-calculator|GCF LCM Calculator]] dà 1, quindi il rapporto è 3:5 ed è già il più semplice.","**3. Controlla l\'affermazione dei fattoriali.** Se qualcuno ti dice che una coda di 9 ordini ha 362.880 disposizioni, il [[fattoriale-calculator|Calcolatore fattoriale]] conferma 9! è esattamente questo. Ora sai se la stima del tempo di compilazione era plausibile.","**4. Normalizza qualsiasi cosa di grandi dimensioni.** Un server che riporta 1,5e9 nanosecondi è 1,5 secondi, secondo il [[scientific-notation|Scientific Notation Converter]], che è la differenza tra un problema di latenza e un artefatto di arrotondamento."]},{"h":"Ciò che questi strumenti deliberatamente non fanno"},{"p":"Non mostrano di lavorare e non insegnano. Se hai bisogno di capire perché una formula è vera, una calcolatrice è lo strumento sbagliato: dà la risposta senza la ragione, ed è così che le persone finiscono per essere in grado di calcolare e incapaci di ragionare.\\n\\nInoltre non eseguono una precisione arbitraria. Fattoriali e fattorizzazioni di grandi dimensioni perderanno precisione oltre il punto in cui la risposta è ancora utile e una scheda del browser non è un sistema di algebra informatica. Per qualsiasi cosa in cui la correttezza sia veramente importante (ingegneria, finanza, crittografia) usa una libreria adeguata con l\'aritmetica esatta, non una pagina web."},{"h":"Controllare la tua aritmetica"},{"p":"L’abitudine matematica più preziosa non è la velocità, è la stima. Prima di credere a qualsiasi risultato, chiediti se è il giusto ordine di grandezza: più grande o più piccolo dell\'input e all\'incirca di quanto. La maggior parte degli errori aritmetici sopravvivono a ogni altro controllo tranne questo.\\n\\nIl primo arrotondamento rende la stima gratuita. Arrotonda 0,375 a 0,4, arrotonda 5/8 a 0,6 e il rapporto è ovviamente di circa 2:3, abbastanza vicino a 3:5 per confermare esattamente la frazione che hai calcolato. Se la risposta esatta e la stima non sono d\'accordo, hai trovato un errore di input anziché un problema di arrotondamento e lo hai trovato in pochi secondi.\\n\\nQuesto è anche il motivo per cui una calcolatrice non sostituisce il pensare a ciò che le è stato chiesto. Uno strumento calcolerà perfettamente la quantità sbagliata e l\'unica difesa è sapere come dovrebbe essere la risposta."},{"h":"Domande frequenti"},{"p":"**Il mio contributo viene inviato ovunque?** No. Tutti questi vengono eseguiti localmente nel tuo browser.\\n\\n**Perché 0,1 più 0,2 non è uguale a 0,3?** Perché né 0,1 né 0,2 sono esattamente rappresentabili in virgola mobile binaria. La somma è 0,30000000000000004, che è il doppio più vicino a 0,3.\\n\\n**Quanto è grande il fattoriale che possono gestire?** Fino a 170 prima di superare l\'intervallo di un doppio. Dopodiché la risposta viene visualizzata in notazione scientifica e quindi smette di essere significativa.\\n\\n**Posso utilizzare l\'output nel codice?** Sì. In particolare, per i risultati da decimale a frazione, utilizzare l\'aritmetica dei numeri interi sul numeratore e sul denominatore anziché riconvertire in un decimale."},{"h":"La versione a una riga"},{"p":"Usa le frazioni esatte quando è coinvolto il denaro, ricorda che i fattoriali esplodono più velocemente di quanto ti aspetti e la fattorizzazione in fattori primi è sia una base di sicurezza che un trucco per semplificare le frazioni."}]},"everyday-utility-tools":{"title":"13 utilità quotidiane gratuite: password, codici QR, timer e codifica di testo","description":"Genera password, crea codici QR, esegui timer e orologi e decodifica testo binario, esadecimale e cifrato, il tutto con strumenti browser gratuiti che non caricano nulla.","category":"Strumenti di utilità","blocks":[{"p":"Quest\'ultimo gruppo è il cassetto della spazzatura. Password, codici QR, un cronometro, un orologio mondiale, il lancio di una moneta e quattro strumenti che convertono il testo in altre rappresentazioni di se stesso. Individualmente banali, collettivamente le cose di cui hai bisogno nei momenti imbarazzanti.\\n\\nLa verità è che tutti e tredici funzionano localmente. Per un generatore di password questo non è un vantaggio: è l\'unico motivo per cui ci si può fidare dello strumento."},{"h":"Password: la parte che conta davvero"},{"l":["[[password-generator|Generatore di password]]: genera password casuali complesse di qualsiasi lunghezza e set di caratteri.","[[password-strength|Password Strength Checker]]: stima la resistenza di una password a essere indovinata, a livello locale."]},{"b":"Il fatto più importante sulla robustezza della password: **la lunghezza batte la complessità e il riutilizzo batte entrambi i pericoli.** Una password di 16 caratteri composta da parole non correlate è più forte e molto più digitabile di un insieme di simboli di 10 caratteri. Nel frattempo, una password riutilizzata che viene rilevata in una violazione elimina contemporaneamente tutti gli account che tocca. Generare una password lunga e distinta per sito è l\'intero lavoro."},{"p":"Anche il modo in cui viene stimata la forza è importante. La maggior parte dei controllori si avvicina alla dimensione dello spazio di ricerca, il che è un proxy ragionevole ma non la verità: `CorrectHorseBatteryStaple` ha un buon punteggio in termini di entropia, mentre \\"P@ssw0rd1!\\" ha un buon punteggio in termini di varietà di caratteri e male in pratica perché appare in ogni eccellente elenco di parole sulla terra.\\n\\nUsa il generatore per tutto ciò che ti interessa e, se devi ricordare una password, usa una passphrase di quattro o cinque parole non correlate. Questo è il caso specifico in cui memorabilità e forza effettivamente si sovrappongono."},{"h":"Codici QR: cosa inserirvi"},{"l":["[[qr-code-generator|QR Code Generator]]: genera un codice QR per un URL, testo, dettagli Wi-Fi o informazioni di contatto."]},{"p":"I codici QR sono uno di quegli strumenti in cui la qualità dell\'output è interamente determinata da una decisione: quanti dati inserire. Un breve URL viene codificato in un codice piccolo e facilmente scansionabile. Un paragrafo di testo con punteggiatura si codifica in qualcosa di denso e inaffidabile a piccole dimensioni.\\n\\nDue regole pratiche. Innanzitutto, esegui sempre la scansione di prova del codice nella dimensione in cui verrà effettivamente stampato prima di stamparne duecento. In secondo luogo, i codici Wi-Fi e URL semplici si comportano in modo diverso su telefoni diversi: se un codice è destinato a un pubblico misto, preferisci un URL semplice a una pagina di destinazione che poi si collega in seguito, perché funziona ovunque e puoi cambiare dove punta."},{"h":"Tempo: timer, orologi e la trappola dei fusi orari"},{"l":["[[cronometro|Cronometro online]]: un semplice cronometro, utile quando il telefono è nell\'altra stanza.","[[pomodoro-timer|Pomodoro Timer]] — Blocchi di focus da 25 minuti con pause, per le persone che trovano che la struttura funzioni.","[[world-clock|World Clock]]: ora corrente di più città contemporaneamente."]},{"p":"L\'orologio mondiale guadagna il suo posto per un motivo specifico: l\'ora legale. La metà degli errori di programmazione del mondo non sono errori aritmetici, sono dovuti al momento in cui due città erano a quattro ore di distanza la settimana scorsa e a cinque ore questa settimana, e nessuno ha controllato.\\n\\nPrima di programmare qualsiasi cosa attraverso un fuso orario, metti entrambe le città nell\'orologio mondiale e guarda: non calcolare l\'offset dalla memoria. Questo è anche il motivo per cui gli inviti alle riunioni dovrebbero riportare un fuso orario anziché un\'ora nuda."},{"p":"Sul timer Pomodoro: la tecnica funziona per un tipo specifico di compito: limitato, mirato, ininterrotto. Non funziona per il debug, dove la mossa corretta quando si è bloccati è allontanarsi, non iniziare un altro blocco di 25 minuti. Usalo quando aiuta."},{"h":"Casualità, onestamente"},{"p":"Il [[random-number|Generatore di numeri casuali]] e il [[list-randomizer|List Randomizer]] coprono i casi che effettivamente si presentano: scegliere un numero in un intervallo e mettere un elenco in un ordine corretto. Merita una frase sull\'equità. Entrambi utilizzano un generatore pseudo-casuale, che per decidere chi paga il pranzo è indistinguibile da una moneta reale. Per qualsiasi cosa consequenziale - un\'estrazione con premi, un\'allocazione con denaro allegato - vuoi una fonte che puoi controllare, e una scheda del browser non è quella. Il valore qui è eliminare l’umano, che sceglie male quando è motivato."},{"h":"Il cassetto della spazzatura di codifica"},{"p":"Quattro strumenti che spostano il testo tra le rappresentazioni. Nessuna di esse è crittografia, e vale la pena di distinguerla perché è costantemente confusa: una codifica è reversibile da chiunque e non ha chiave. La crittografia richiede una chiave."},{"l":["[[binary-text|Da binario a testo]]: converte tra il testo e la sua rappresentazione binaria.","[[hex-text|Hex to Text]] — converte tra testo ed esadecimale, la rappresentazione che vedi più spesso negli strumenti di rete e nei debugger.","[[caesar-cipher|Caesar Cipher]] — sposta le lettere di un importo fisso, il classico cifrario scolastico.","[[rot13-encoder|ROT13 Encoder]] — ruota le lettere di 13, un caso speciale che è il suo stesso inverso."]},{"p":"Questi sono utili esattamente per due cose. Innanzitutto, capire come il testo diventa byte, che è il modello mentale di cui hai bisogno ogni volta che qualcosa sembra confuso. In secondo luogo, il debug vero e proprio: quando un carico utile viene visualizzato come esadecimale, il convertitore [[hex-text|Hex to Text]] è il modo per scoprire cosa dice.\\n\\nNon servono a nascondere nulla. ROT13 non ha chiave – il turno è pubblico – quindi non nasconde nulla a chiunque sappia cosa sia ROT13. Il codice di Cesare ha 25 possibili spostamenti, che un essere umano riesce a decifrare in un minuto."},{"h":"I due che formattano le cose"},{"l":["[[phone-formatter|Phone Number Formatter]]: normalizza i numeri di telefono in un formato coerente.","[[file-size-converter|Convertitore di dimensioni file]]: converte tra KB, MB, GB e TB, spiegando la distinzione decimale e binaria."]},{"p":"Il convertitore delle dimensioni del file ha un risultato davvero prezioso: ti dice perché un\'unità pubblicizza un numero maggiore di quanto riportato dal tuo computer. I fornitori vendono con potenze di dieci, i sistemi operativi riportano potenze di due e il divario è di circa il 7% su ogni scala. Non è una colpa, sono due convenzioni."},{"h":"Un esempio funzionante: la risposta API confusa"},{"p":"Un webhook non supera la convalida e il payload nel log è simile a \\"\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f\\". Questa è una diagnosi di novantaduesimo."},{"l":["**1. Converti.** Incolla `48656c6c6f` nel convertitore [[testo-esadecimale|Testo da esadecimale]]: il risultato è `Ciao`. Non è mai stato confuso, solo codificato.","**2. Controlla la forma.** Qualcosa a monte sta codificando esadecimale il payload prima della firma. La firma è stata calcolata sul testo originale e convalidata rispetto all\'esadecimale, quindi il confronto fallisce.","**3. Escludere l\'altra direzione.** Se il registro avesse mostrato testo leggibile, il problema sarebbe stato il contrario: firmare il modulo codificato.","**4. Conferma la richiesta di dimensione.** Se lo stesso log riporta un payload di 1,2 MB, il [[file-size-converter|File Size Converter]] stabilisce se è decimale o binario prima che qualcuno discuta su una quota."]},{"h":"Domande frequenti"},{"p":"**Il generatore di password è sicuro se tutto viene eseguito nel browser?** Sì, e molto più di un generatore di password basato su server: la password viene generata sul tuo computer e non viene mai trasmessa, quindi non c\'è nulla da intercettare, registrare o violare. Il compromesso è che non puoi recuperare una password che non hai salvato.\\n\\n**Posso fidarmi del lancio della moneta virtuale?** Per decisioni casuali, sì. Per qualsiasi cosa con denaro o premi allegati, utilizza una fonte che puoi controllare.\\n\\n**I codici sono sicuri?** No. Nessuno di loro. I codici ROT13 e Caesar non hanno una chiave segreta ed esistono per insegnare la codifica, non per proteggere nulla.\\n\\n**Funzionano offline?** Una volta caricata la pagina, sì, tutto è locale.\\n\\n**Esiste un limite alla lunghezza del testo per i convertitori?** Solo la memoria del tuo dispositivo, poiché nulla viene inviato da nessuna parte."},{"h":"La versione a una riga"},{"p":"Le password lunghe e univoche battono quelle corte e intelligenti, un codice QR è valido quanto i dati al suo interno, controlla gli offset del fuso orario anziché calcolarli e la codifica non è crittografia."}]}}')},52903,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"De Developer\'s Toolkit: 24 gratis browsertools die betaalde apps vervangen","description":"Een praktische gids voor het formatteren, converteren, coderen en debuggen van gegevens met behulp van gratis browsergebaseerde ontwikkelaarstools - geen installaties, geen accounts, niets geüpload.","category":"Ontwikkelaarstools","blocks":[{"p":"Voor de meeste kleine klusjes die je honderd keer per week doet – het opnieuw formatteren van een API-antwoord, het decoderen van een token, het controleren van een hash, het inspringen van een stukje SQL – heb je geen IDE, een betaald abonnement of een teamlicentie nodig. Ze hebben één tabblad negentig seconden geopend nodig.\\n\\nDe onderstaande verzameling bestaat uit vierentwintig browsergebaseerde hulpprogramma\'s die betrekking hebben op opmaak, conversie, codering, hashing en foutopsporing. Ze draaien allemaal volledig op uw pagina: uw gegevens worden nooit naar een server verzonden, wat belangrijker is dan ontwikkelaars gewoonlijk toegeven, omdat de payload die u plakt meestal van een klant is."},{"h":"Welke browsergebaseerde tools wel en niet kunnen vervangen"},{"p":"Wees realistisch over de grens. Deze hulpmiddelen vervangen eenmalige, hoogfrequente klusjes met een lage inzet. Ze vervangen niet uw taalserver, uw debugger, uw testsuite of iets anders dat u herhaaldelijk in een echte omgeving moet uitvoeren."},{"l":["**Goede pasvorm:** een reactie één keer lezen, fouten opsporen in een enkele waarde, een bestand converteren voor één import, een formaat controleren voordat het wordt verzonden.","**Slechte pasvorm:** het uitvoeren van dezelfde controle bij elke implementatie, waarbij honderden bestanden worden getransformeerd, alles wat luid moet mislukken in CI.","**Nooit:** alles waarbij inloggegevens betrokken zijn, kunt u niet rouleren. Plak een ingetrokken token, geen live token."]},{"p":"Dat gezegd hebbende, de reden om deze als bladwijzer te bewaren is de doorvoer. Een taak die op een browsertabblad veertig seconden in beslag neemt, wordt nooit gepland, wordt nooit gedelegeerd en wordt nooit een reden om om acht uur \'s avonds een IDE te openen."},{"h":"Gegevens formatteren en converteren"},{"p":"De meest voorkomende dagelijkse klus is het leesbaar maken van data. Een API retourneert een blob van één regel, een collega stuurt een configuratiebestand met tabbladen die worden verminkt door een chatvenster, of je exporteert een spreadsheet naar JSON en deze komt terug als één enorme regel."},{"l":["[[json-formatter|JSON Formatter]] — laat een payload inspringen, valideren en lezen. Gebruik het voordat u fouten gaat opsporen: de helft van alle \\"de API is kapot\\"-tickets zijn feitelijk verkeerd ingedeelde JSON met een komma erachter.","[[json-validator|JSON Validator]] — wanneer u een strikt geslaagd/mislukt antwoord nodig heeft in plaats van een mooie afdruk.","[[xml-formatter|XML Formatter]] — dezelfde taak voor SOAP-reacties, RSS-feeds en Maven POM\'s die niemand sinds 2014 heeft aangeraakt.","[[json-to-yaml|JSON to YAML]] en [[json-to-csv|JSON to CSV]] — het verplaatsen van gegevens tussen de formaten die echte systemen daadwerkelijk gebruiken."]},{"p":"Houd de laatste groep in gedachten voor één specifiek scenario: een klant overhandigt u een spreadsheet en verwacht deze in zijn API. CSV rechtstreeks naar JSON brengen is twee minuten werk in plaats van een middagje scripten."},{"h":"Coderen en ontsnappen"},{"p":"Coderingsfouten zijn onevenredig vervelend omdat de gegevens er goed uitzien. De waarde \\"San José & Sons\\" komt binnen als \\"San Jos%C3%A9 %26 Sons\\" en uw vergelijking met de database mislukt om redenen die onzichtbaar zijn in de logbestanden."},{"l":["[[url-encoder|URL Encoder / Decoder]] — bepaal onmiddellijk of een queryreeks dubbel gecodeerd is.","[[base64-encoder|Base64 Encoder / Decoder]] — decodeer een certificaatfragment of codeer een klein item voor inline in CSS.","[[html-entity-encoder|HTML Entity Encoder / Decoder]] — ontdek of die verdwaalde \\"&\\" op uw pagina afkomstig is van uw sjabloon of uw gegevens.","[[unicode-converter|Unicode Converter]] — handig wanneer een \\"gebroken\\" teken een legitiem teken blijkt te zijn, weergegeven in de verkeerde codering.","[[number-base-converter|Number Base Converter]] — controleer een kleur, een toestemmingsbitmasker of een geheugenadres zonder een rekenmachine-app."]},{"b":"Een praktische gewoonte: wanneer een waarde onleesbaar aankomt, decodeert u deze laag voor laag en plakt u elk resultaat in een leeg veld. Als de eerste decodering leesbare tekst oplevert, is het probleem één extra codering ergens stroomopwaarts. Als het mojibake produceert, heb je eerder een coderingsprobleem dan een ontsnappingsprobleem, en deze twee hebben verschillende oplossingen nodig."},{"h":"Identificatoren, hashes en tokens"},{"p":"In deze groep verspillen ontwikkelaars de meeste tijd met het zoeken naar het juiste lokale script dat ze ooit hebben geschreven en verloren."},{"l":["[[uuid-generator|UUID Generator]] — genereer v4-identifiers voor zaadgegevens, wedstrijden of een snelle databaserij.","[[md5-generator|MD5 / SHA Hash Generator]] — verifieer een download of bevestig dat twee bestanden die identiek zouden moeten zijn, dat ook daadwerkelijk zijn.","[[timestamp-converter|Timestamp Converter]] — de meest gebruikte tool in deze hele lijst. Als op een logboekregel 1761000000 staat, kunt u hieruit zien of het incident plaatsvond tijdens de implementatie of ervoor."]},{"p":"De tijdstempelconverter verdient zijn geld om één specifieke reden: een tijdperknummer is tegelijkertijd ondubbelzinnig en nutteloos. Je weet precies wanneer iets is gebeurd en je kunt het niet aan een collega vertellen. Eén keer converteren lost meestal een luider argument op dan zou moeten."},{"h":"Vergelijken en debuggen"},{"l":["[[regex-tester|Regex Tester]] — het item met de hoogste hefboomwerking hier. Een reguliere expressie die er correct uitziet en stilletjes met niets overeenkomt, is een van de duurste bugs in de ontwikkeling, omdat deze stilletjes faalt op de enige plek waar niemand leest.","[[html-preview|HTML Preview]] — herhaal een fragment van de markup om te controleren hoe het daadwerkelijk wordt weergegeven."]},{"p":"Test uw reguliere expressies met de invoer die u daadwerkelijk verwacht, inclusief de lege tekenreeks, een Unicode-naam en een waarde met een nieuwe regel. De meeste patronen breken in het derde geval en niemand merkt het totdat de productiegegevens binnenkomen."},{"h":"Een uitgewerkt voorbeeld: drie tools, één saai incident"},{"p":"Hier is de reeks die mij ervan overtuigde om dit allemaal te bookmarken. Een klant meldde dat een record dat ze dinsdag hadden ingediend, ontbrak in een rapport van donderdag."},{"l":["**1. Converteer de tijdstempel.** De rapporttaak registreerde de aanmaaktijd van de record als een tijdperkwaarde. De [[timestamp-converter|Timestamp Converter]] liet zien dat het record om 23.00 uur lokaal was aangemaakt, wat dinsdag is. De aanname van de tijdzone van de taak was het probleem, niet het record.","**2. Formatteer de payload.** Door de opgeslagen JSON door de [[json-formatter|JSON Formatter]] te halen, bleek dat de record was geschreven met een nuldatumveld, omdat de client tweemaal hetzelfde eindpunt had aangeroepen met een tussenpoos van 200 ms en de tweede schrijfactie had gewonnen.","**3. Vergelijk de payloads.** Beide records hadden dezelfde API-sleutel en dezelfde clienttijdstempel, wat duidde op een nieuwe poging in plaats van op twee afzonderlijke klanten."]},{"p":"Totaal verstreken tijd: vier minuten. De eerdere poging tot dit onderzoek, waarbij werd gezocht naar dezelfde hoofdoorzaak in een houtkapplatform, duurde een middag en leverde een verkeerde conclusie op."},{"h":"Privacy: waarom lokaal draaien de eigenlijke functie is"},{"p":"Elke tool in deze bibliotheek verwerkt uw invoer in uw eigen browser. Er wordt niets geüpload, wat betekent dat er geen retentievraag is, geen verwerkersovereenkomst en geen ongemakkelijk gesprek over de productiepayload die je drie minuten geleden hebt geplakt.\\n\\nDit is de reden dat u deze tools verkiest boven een gehoste \\"pastebin API\\" of een online dienst die u vraagt ​​om u aan te melden. Het betekent ook dat ze blijven werken tijdens een vlucht, in een kelder of wanneer de zakelijke VPN heeft besloten weer een ander domein te blokkeren."},{"p":"Eén voorbehoud dat duidelijk moet worden vermeld: een pagina die offline kan worden gebruikt, is alleen privé als de pagina zelf de code bevat die u denkt dat deze is. Op een gedeelde machine gebruikt u een privévenster en sluit u dit wanneer u klaar bent, vooral als u tokens hebt gedecodeerd."},{"h":"Bouw een workflow om hen heen"},{"p":"De tools zijn individueel triviaal. De waarde ligt in de gewoonte om er onmiddellijk naar te grijpen in plaats van er \\"later op in te gaan\\", omdat je later een wegwerpscript schrijft, of een IDE opent, of besluit dat het helemaal niet de moeite waard is om te controleren."},{"l":["Maak een bladwijzer van de collectie, niet van individuele URL\'s, en plaats deze in de werkbalk van uw browser.","Als iets verkeerd lijkt, controleer het dan voordat je een theorie vormt. Kost vijftien seconden; doodt hele klassen van verkeerde conclusies.","Als je hetzelfde twee keer hebt gecontroleerd, is dat het signaal om het te automatiseren – maar automatiseer niet op verdenking.","Plak geen productiegeheimen. Draai alles waar u niet zeker van bent."]},{"h":"Veelgestelde vragen"},{"p":"**Zijn deze tools gratis?** Ja, volledig, zonder account en zonder gebruikslimiet. Er is geen betaald niveau dat iets fundamenteels tegenhoudt.\\n\\n**Werken ze offline?** Zodra een pagina is geladen, ja, alles draait in uw browser. Voor het herladen is een verbinding vereist.\\n\\n**Kan ik ze gebruiken voor commercieel werk?** Ja. De uitvoer is van jou, zonder attributievereiste.\\n\\n**Is er een API?** Nee, en dat is opzettelijk: de waarde is de interface. Exporteer de uitvoer en verwerk deze zoals u wilt.\\n\\n**Waarom installeert u niet gewoon een CLI-tool?** Installeer er een wanneer u deze drie keer nodig heeft. Gebruik een browsertabblad voor de eerste twee."}]},"text-tools-for-writers":{"title":"17 gratis teksthulpmiddelen voor schrijvers, studenten en marketeers","description":"Ruim de tekst op, tel de woorden nauwkeurig, maak lijsten op en verander ruwe concepten in iets dat publiceerbaar is - met gratis browsertools waarmee u nooit uw tekst hoeft te uploaden.","category":"Teksthulpmiddelen","blocks":[{"p":"Schrijven voor werk brengt verrassend veel mechanisch gezwoeg met zich mee dat niets met schrijven te maken heeft: het verwijderen van losse witruimte uit een geplakte alinea, het controleren van een woordlimiet, het dedupliceren van een lijst met namen, het omzetten van iets in een URL-slug.\\n\\nDeze zeventien gereedschappen zijn voor dat deel van de klus. Ze draaien allemaal lokaal in de browser, wat geen klein detail is: het concept dat je plakt is vaak niet gepubliceerd en de lijst die je aan het sorteren bent, bestaat vaak uit iemands persoonlijke gegevens."},{"h":"Meten van wat je hebt geschreven"},{"p":"Het aantal woorden lijkt opgelost totdat een klant precies 800 woorden vraagt en uw redacteur 820 zegt, of een formulier uw tekst afwijst op 1.995 tekens zonder uitleg over waar de nieuwe regel is gebleven."},{"l":["[[woordenteller|Woordenteller]] — de standaardmaat. Plakken, lezen, aanpassen.","[[letter-counter|Letter Counter]] — telt tekens en letterfrequentie. Handig als je wilt debuggen waarom een ​​alinea verkeerd aanvoelt: het is meestal een herhaald letterpatroon, geen droom."]},{"p":"Een opmerking over wat \\"een woord\\" betekent: verschillende tellers zijn het oneens over woordafbreking, cijfers en URL\'s. Als een exact aantal van belang is, gebruik dan hetzelfde loket dat de persoon die uw werk controleert gebruikt, en spreek dit van tevoren af. Dit is een werkelijk veel voorkomende bron van kleine, zinloze argumenten."},{"h":"Kopieën opruimen die u niet hebt geschreven"},{"p":"De meeste tekst die u ontvangt is licht beschadigd: dubbele spaties bij kopiëren en plakken, een verdwaalde tab, inconsistent hoofdlettergebruik als iemand haastig typt. Het handmatig repareren is traag en foutgevoelig."},{"l":["[[text-trimmer|Text Trimmer]] — verwijder voor- en achterliggende witruimte van elke regel in één keer. Hiermee worden meer rapporten met de melding \\"opmaak ziet er kapot\\" opgelost dan iets anders op deze lijst.","[[text-case-converter|Text Case Converter]] — schakel tussen hoofdletters, hoofdletters, hoofdletters en kleine letters binnen een blok. Ook de snelste manier om een ​​onbedoelde CAPS LOCK-paragraaf ongedaan te maken.","[[text-to-slug|Text to Slug]] — verander een kop in een schone URL-slug. Plak je titel, pak de slug, klaar."]},{"p":"De sluggenerator heeft nog één nut naast URL\'s: het is een snelle manier om een ​​leesbare bestandsnaam of anker te maken die een mens in één oogopslag kan ontleden, en dat is beter dan `final_final_v3`."},{"h":"Werken met lijsten"},{"p":"Lijstjes, inventarissen, samenvoegingen, het opschonen van tags, enquêtereacties, spreadsheetkolommen: op een gegeven moment wordt alles een lijst en moet elke lijst worden gesorteerd, ontdubbeld of gerandomiseerd."},{"l":["[[duplicate-line-remover|Duplicate Line Remover]] — vergelijk twee lijsten, of maak er één schoon. De uitvoer vertelt u hoeveel duplicaten zijn verwijderd, wat handig is wanneer u het resultaat rapporteert.","[[list-sorter|List Sorter]] — dezelfde taak voor gestructureerde lijstinvoer.","[[list-randomizer|List Randomizer]] — schud een trekkingsvolgorde, een quizreeks of een afgeschermde shortlist zodat niemand vriendjespolitiek vermoedt.","[[line-number-adder|Line Number Adder]] — nummerregels ter referentie in een ticket of commentaar op een codebeoordeling."]},{"b":"De klassieke valkuil hier is een lijst die er gededupliceerd uitziet, maar dat niet is: \'Apple\', \'apple\' en \'Apple.\' zijn drie verschillende regels voor een computer. Snijd de witruimte weg en verwijder de interpunctie voordat u dedupliceert, anders voegt u niets samen en komt u tot de conclusie dat de gegevens schoon zijn."},{"h":"Voorbeeld bekijken en opmaken"},{"p":"Markdown heeft gewonnen, maar niet op uniforme wijze. De helft van je gereedschap geeft het weer, de andere helft niet, en de helft die dat niet doet, is meestal degene waar iemand in moet plakken."},{"l":["[[markdown-preview|Markdown Preview]] — live weergave, zodat u kunt controleren of een tabel of een geneste lijst er daadwerkelijk uitziet voordat deze een client bereikt.","[[text-repeater|Text Repeater]] — herhaal een tekenreeks N keer. Handig voor het genereren van opvulling, testgegevens of, zo nu en dan, om een ​​punt in een document te maken."]},{"p":"Het Markdown-voorbeeld is het hulpmiddel dat stilletjes de meeste tijd bespaart in deze hele set, omdat een kapotte tabel in een gerenderd document veel zichtbaarder is (en veel gênanter) dan een kapotte tabel in onbewerkte tekst."},{"h":"De rest, en wanneer u ze kunt bereiken"},{"l":["[[random-string|Random String Generator]] — genereer leesbare nonces, tijdelijke ID\'s of korte codes. Beter dan iets met de hand verzinnen, want je hergebruikt het niet per ongeluk.","[[morse-code|Morse Code Translator]] — echt leuk, af en toe handig voor een themaproject of een puzzel."]},{"p":"Dit zijn tools met een lagere frequentie, maar het kost niets om een ​​bladwijzer bij te houden en ze lossen het specifieke probleem op van \\"Ik heb nu een willekeurig ogende waarde nodig en ik vertrouw mezelf niet om er een te verzinnen\\"."},{"h":"Een realistische bewerkingspas"},{"p":"Dit is de volgorde die werkt als er een concept van iemand anders binnenkomt en onder jouw naam moet worden verzonden."},{"l":["**1. Trimmen.** Haal eerst het hele document door de [[text-trimmer|Text Trimmer]]. Schade aan witruimte verbergt zich in paragrafen waar u deze nooit zult zien.","**2. Schone hoofdletters.** Gebruik de [[text-case-converter|Text Case Converter]] alleen voor de kop. Pas nooit hoofdletterconversie toe op een volledig concept; dit vernietigt eigennamen.","**3. Meten.** Controleer de lengte met de [[word-counter|Word Counter]] voordat je gaat schrijven, zodat je weet welke vorm het stuk moet hebben.","**4. Preview.** Als het Markdown bevat, geef het dan weer met [[markdown-preview|Markdown Preview]].","**5. Slug.** Genereer de URL-slug als laatste, vanaf de laatste kop, met [[text-to-slug|Text to Slug]] — als je de kop daarna wijzigt, wordt de slug verbroken."]},{"p":"De hele pas duurt een paar minuten en elimineert de categorie fouten waarbij een document technisch correct en zichtbaar fout is."},{"h":"Schrijversvragen over privacy"},{"p":"**Verlaat mijn ongepubliceerde tekst mijn computer?** Nee. Deze tools verwerken tekst in uw browser en er wordt niets opgeslagen of verzonden.\\n\\n**Is er een lengtelimiet?** Er is geen limiet aan de serverzijde omdat er geen serveroproep is. Extreem grote invoer wordt beperkt door het geheugen van uw eigen apparaat.\\n\\n**Kan ik de output commercieel gebruiken?** Ja, vrijelijk, zonder bronvermelding.\\n\\n**Werken ze op een telefoon?** Ja. De lay-out past zich aan en dezelfde code wordt uitgevoerd."},{"h":"Wat deze tools niet voor u zullen doen"},{"p":"Het is de moeite waard om bot te zijn over de grenzen, want een instrument dat het verkeerde mechaniseert, leidt alleen maar tot snellere fouten.\\n\\nGeen van deze hulpprogramma\'s kan u vertellen of een zin duidelijk is, of een bewering afkomstig is, of dat de toon goed is voor het publiek. Ze tellen karakters; zij oordelen niet over proza. Een tekst die mooi scoort op elke statistiek op deze pagina kan toch onleesbaar zijn.\\n\\nZe bewerken ook niet. Op het moment dat je merkt dat je individuele clausules op grote schaal met de hand herschrijft, ben je een teksttool ontgroeid en wil je óf een goede editor, een zoek-en-vervang met regex – waar de [[regex-tester|Regex Tester]] echt goed in is om te oefenen – of een script. Gebruik de browser voor de mechanische laag en behoud je eigen oordeel voor alles daarboven."},{"p":"Nog een ding dat ze niet zullen doen, is een slechte bron repareren. Als uw spreadsheet vol inconsistente namen staat: \'Dr.\', \'DR\', \'Dr.\' alles in één kolom: een tool sorteert en ontdubbelt wat je eraan hebt gegeven, en je hebt nog steeds drie vermeldingen waar er één zou moeten zijn. Het opschonen van de gegevens is een beslissing, geen mechanische stap. Bepaal eerst de canonieke vorm, pas deze toe en controleer vervolgens."},{"h":"Een werklijst bruikbaar houden"},{"p":"Als u een lijst met leads, links, referenties of termen bijhoudt, gaat deze langzaam achteruit. De foutmodus is altijd hetzelfde: vermeldingen die er identiek uitzien, zijn dat niet, en één samenvoeging verwijdert niets.\\n\\nEen onderhoudspas die werkt is saai: witruimte wegknippen, hoofdlettergebruik standaardiseren, navolgende interpunctie verwijderen en vervolgens ontdubbelen. In die volgorde gaat bij het bijsnijden na het dedupliceren invoer verloren. Als je dit één keer per maand op een actieve lijst doet, verandert een onherstelbare puinhoop van twee uur in een karwei van tien minuten.\\n\\nWanneer twee lijsten met elkaar in overeenstemming moeten worden gebracht, bijvoorbeeld een registratielijst en een presentielijst, sorteer beide dan eerst met de [[list-sorter|List Sorter]], zodat ze op één lijn komen te staan, en vergelijk ze vervolgens op het oog. Beide partijen sorteren voordat je gaat vergelijken, is het verschil tussen een controle van twee minuten en een jacht van twintig minuten."},{"h":"De afhaalmaaltijd"},{"p":"Geen van deze tools is slim. Dat is het punt: ze verwijderen de mechanische vijf procent van het schrift dat geen schrift is, dus de resterende vijfennegentig procent gaat eigenlijk over zinnen. Maak een bladwijzer van degene die u maandelijks gebruikt, negeer de rest en stop met het handmatig corrigeren van witruimte."}]},"calculators-and-converters-guide":{"title":"18 gratis rekenmachines en conversieprogramma\'s voor de getallen waarmee u daadwerkelijk te maken heeft","description":"Percentages, kortingen, fooien, leningen, datums, BMI en eenheidsconversies: gratis browsercalculators die hun redenering weergeven en uw invoer nooit opslaan.","category":"Rekenmachines","blocks":[{"p":"Iedereen moet een rekening splitsen, uitzoeken of een korting echt een korting is, en een temperatuur of een bestandsgrootte omzetten zonder erover na te denken. Iedereen heeft dit ook minstens één keer in het openbaar verkeerd begrepen.\\n\\nDit is een verzameling van achttien rekenmachines en converters die betrekking hebben op geld, datums, gezondheid en de eenheidconversies die voorkomen in werk en reizen. Ze draaien allemaal in de browser: er wordt niets opgeslagen, dus de cijfers die u typt zijn niemands zaken behalve die van u."},{"h":"Geldberekeningen"},{"p":"De meest voorkomende wiskunde in de echte wereld is een percentage van iets. Omzetbelasting, een fooi, een kortingsstapel, een commissie, een groeipercentage. De formule is eenvoudig, en toch is de reden dat mensen het bij het verkeerde eind hebben bijna altijd dezelfde: ze passen een percentage toe op de verkeerde grondslag."},{"l":["[[kortingscalculator|Kortingscalculator]] — bereken de uiteindelijke prijs en, nog belangrijker, hoeveel u heeft bespaard. Handig voor het spotten van een \\"50% korting\\" die in werkelijkheid 20% is na een verhoogde catalogusprijs.","[[fooicalculator|Fooicalculator]] — deel een rekening, kies een percentage, rond per persoon af als je wilt.","[[loan-calculator|Leningcalculator]] — maandelijkse betaling en totale rente, het getal dat feitelijk bepaalt of een lening betaalbaar is."]},{"b":"Over kortingen: een korting van 20% gevolgd door nog eens 20% korting is geen 40% korting, maar 36%. Opeenvolgende percentages worden samengesteld op de gereduceerde basis. Elke rekenmachine in deze lijst zal dit binnen ongeveer twee seconden bevestigen, en het is het meest bruikbare rekenkundige feit in dit artikel."},{"p":"De leningcalculator verdient een specifieke opmerking. Het getal dat ertoe doet is niet de maandelijkse betaling; het is de totale rente die wordt betaald over de looptijd van de lening, want dat zijn de werkelijke kosten van het lenen. Twee leningen met identieke maandelijkse betalingen en verschillende voorwaarden kunnen in totale rente tienduizenden verschillen."},{"h":"Datums en aftellingen"},{"p":"Bij het rekenen met datums hebben de meeste mensen het stilletjes mis, omdat menselijke maanden verschillende lengtes hebben en het antwoord verandert afhankelijk van of je \'kalendermaanden\' of \'30 dagen\' bedoelt."},{"l":["[[datumverschil|Datumverschilcalculator]] — dagen (en totaal aantal maanden, jaren) tussen twee datums.","[[days-until|Days Until Calculator]] — een aftelling naar een specifieke datum, waarbij het aantal werkdagen meestal is wat mensen eigenlijk willen.","[[age-calculator|Leeftijdcalculator]] — exacte leeftijd in jaren en dagen, plus de volgende verjaardag.","[[timestamp-converter|Timestamp Converter]] — een Unix-tijdstempel in een echte datum, wat er toe doet of je logs, databases of API-reacties aanraakt."]},{"p":"Het onderscheid waar mensen over struikelen: het aantal dagen tussen 1 maart en 1 april is 31, maar het aantal *maanden* is één. Als u een opzegtermijn of een abonnementstermijn berekent, geeft u dan schriftelijk aan welke eenheid u bedoelt."},{"h":"Gezondheidscijfers, eerlijk gezegd"},{"l":["[[bmi-calculator|BMI Calculator]] — body mass index met de standaardcategorieën en de onderstaande kanttekeningen."]},{"p":"BMI is een screeningsstatistiek op populatieniveau. Het zegt niets over de spiermassa, de lichaamssamenstelling of de gezondheid van een individu, en het is een slechte maatstaf voor de fitheid bij atleten, bij oudere volwassenen en bij verschillende etnische groepen. Gebruik het als één datapunt uit meerdere, of als een manier om een ​​verandering in de loop van de tijd bij te houden – niet als een oordeel. Als u beslissingen neemt die van invloed zijn op uw gezondheid, is het juiste hulpmiddel een arts, en geen browsertabblad."},{"h":"Eenheidsconversie: de alledaagse"},{"p":"Eenheidsconversie is onderverdeeld in twee soorten: conversies die u precies goed moet krijgen, en conversies die u grofweg nodig heeft. Deze tools kunnen beide aan, en het werk zit hem in het onthouden van welke welke is."},{"l":["[[lengte-omzetter|Lengteomzetter]] — metrisch naar imperiaal en terug: millimeters, centimeters, meters, kilometers, inches, voeten, yards, mijlen.","[[weight-converter|Gewichtconvertor]] — gram, kilogram, ounce, pond, ton. Degene die je moet controleren vóór een recept of een verzendlabel.","[[temperatuur-omzetter|Temperatuuromzetter]] — Celsius, Fahrenheit, Kelvin. Omdat -10°C niet 14°F is, en de formule geen vermenigvuldiging is.","[[snelheidsomzetter|Snelheidsomzetter]] — km/u, mph, m/s, knopen. Handig voor een buitenlandse snelheidslimiet of een technische specificatie.","[[area-converter|Area Converter]] — vierkante meter, vierkante voet, acres, hectare. Dit is degene die mensen slecht inschatten bij het kopen of huren van onroerend goed.","[[volume-converter|Volume Converter]] — liters, milliliters, gallons, kopjes, kubieke meters.","[[time-converter|Time Converter]] — seconden, minuten, uren, dagen, weken."]},{"b":"Twee conversievallen die de moeite waard zijn om te weten: de gegevensopslag hierboven (marketeers verkopen 10^3, besturingssystemen rapporteren 2^10) en het brandstofverbruik – een auto met een prijs van 40 mpg (imperiaal) ligt dichter bij 33 mpg (VS) dan 40, omdat de imperiale gallon groter is. Als je de tweede fout maakt, ziet een huurauto er onrealistisch efficiënt uit."},{"h":"De twee die je niet verwacht nodig te hebben"},{"l":["[[willekeurig getal|Random Number Generator]] — trekt binnen een bereik, voor een loterij, een beugel of een snelle A/B-splitsing. Handig juist omdat het de verdenking wegneemt dat je ermee hebt gemanipuleerd.","[[dice-roller|Dice Roller]] — elke dobbelsteen, van een muntstukje tot een twintigzijdige dobbelsteen, voor een bordspel of een tafelsessie waarbij de echte dobbelsteen voor de laatste keer van de tafel is gerold."]},{"h":"Een rekenmachine op de juiste manier gebruiken"},{"p":"Een rekenmachine helpt alleen als je weet over welk getal je het vraagt. Drie gewoonten maken het verschil."},{"l":["**Eerst rond, bereken het tweede.** Als het exacte getal uw beslissing niet verandert, gebruik dan een ronde. Percentages van ronde getallen zijn controleerbaar in uw hoofd, waardoor invoerfouten worden opgemerkt.","**Controleer de omvang van het gezond verstand.** Voordat u een resultaat gelooft, moet u zich afvragen of het groter of kleiner moet zijn dan de invoer, en hoeveel ongeveer. De meeste rekenfouten overleven elke controle, behalve deze.","**Fotografeer de input, niet de output.** Als je de berekening later opnieuw uitvoert, gaat het erom dat je weet wat je hebt aangenomen, niet wat je hebt geconcludeerd."]},{"h":"Vragen die mensen daadwerkelijk stellen"},{"p":"**Worden mijn nummers ergens opgeslagen?** Nee. De berekeningen gebeuren in uw browser en er wordt niets verzonden of bewaard.\\n\\n**Werken deze op een telefoon?** Ja, en de rekenmachines zijn gebouwd voor gebruik met één hand.\\n\\n**Welke conversiestandaard gebruik je voor dataopslag?** Standaard decimaal (1 KB = 1000 bytes), want zo wordt opslag verkocht. Besturingssystemen rapporteren binair, en daarom lijkt een schijf kleiner te worden; de tool legt het verschil uit in plaats van stilletjes een kant te kiezen.\\n\\n**Kan ik deze op mijn eigen site insluiten?** Nee. Maak er een bladwijzer van; de kosten daarvan zijn nul en het nauwkeurigheidsprobleem is uw eigen verantwoordelijkheid."},{"h":"Percentages: de vier fouten die er toe doen"},{"p":"Bijna elke procentuele fout die een persoon in het dagelijks leven maakt, is een van dezelfde vier fouten. Door ze een naam te geven, zijn ze vermijdbaar."},{"l":["**Verkeerde basis.** \\"Een stijging van 10% en een daling van 10% brengt je waar je begon\\" is niet waar, omdat beide op verschillende bases van toepassing zijn. Tien procent van 100 is 10; tien procent van 90 is 9.","**Percentage van een percentage.** Het stapelen van twee kortingen vermenigvuldigt ze (0,8 × 0,8 = 0,64, dus 36% korting), maar telt ze niet op.","**Procent versus procentpunt.** Een percentage van 4% naar 6% is met 2 procentpunt gestegen, maar relatief gezien met 50%. De politiek en de geneeskunde zijn vol van deze verwarring, en het is niet altijd toevallig.","**Te vroeg afgerond.** Het afronden van een tussenstap voordat een percentage wordt toegepast, vergroot de fout. Houd volledige precisie tot het laatste cijfer en voer de laatste stap op een rekenmachine uit in plaats van in uw hoofd."]},{"p":"Als je maar één gewoonte uit dit hele gedeelte overneemt, neem dan deze: voordat je iemand een percentage citeert, herhaal dan eerst welk percentage *van* het is. De helft van de argumenten die je ooit over een getal zult hebben, zijn feitelijk argumenten over de noemer."},{"h":"Weten wanneer je moet stoppen met rekenen"},{"p":"Er is een punt waarop precisie niet langer nuttig is. Een maandelijkse betaling tot twee decimalen is zinvol. Een geraamde totale kostprijs tot op acht decimalen is een manier om de daadwerkelijke beslissing te omzeilen, namelijk of de lening past binnen wat u zich zonder stress kunt veroorloven.\\n\\nDe bruikbare test is de gevoeligheidsvraag: verandert de beslissing als deze input met 10% beweegt? Als dat niet het geval is, stop dan met het verfijnen ervan en gebruik de extra tijd voor de variabele die het antwoord wel verplaatst – meestal de term in plaats van het tarief, of de catalogusprijs in plaats van de korting."},{"p":"En één grens die het duidelijk waard is om te vermelden: deze rekenmachines zijn rekenkundig, geen advies. Een spaardoel, een pensioendatum en een plan voor de afbetaling van schulden zijn allemaal beslissingen over risico, gedrag en tijd, en een browsertabblad kan deze allemaal niet wegen. Het kan u pas vertellen wat de cijfers impliceren als u eenmaal hebt besloten waar u van uitgaat. Dat onderscheid is het verschil tussen nuttig zijn en verantwoordelijk zijn voor een rekenmachine."},{"h":"De éénregelige versie"},{"p":"Maak een goede bladwijzer voor de geld- en datumcalculatoren, beschouw BMI als één signaal in plaats van als een oordeel, onthoud dat gestapelde percentages zich vermenigvuldigen en controleer de omrekening van eenheden wanneer een getal iets contractueels betreft. Dat omvat vrijwel alles."}]},"image-and-design-tools":{"title":"14 gratis beeld- en ontwerptools die in uw browser worden uitgevoerd","description":"Afbeeldingen comprimeren, vergroten of verkleinen en voorbereiden, en CSS-effecten, paletten, contrastcontroles en favicons genereren zonder Photoshop of een ontwerpsuite te installeren.","category":"Ontwerphulpmiddelen","blocks":[{"p":"Beeldwerk heeft een specifiek probleem: de klus is meestal klein en de aangeboden tools zijn enorm. Je moet 400 KB van een heldenafbeelding schrappen, of een hexadecimale waarde krijgen die je ontwerper noemde, of een favicon genereren die nog niemand heeft gemaakt. Daar is geen abonnement voor nodig.\\n\\nDe veertien onderstaande tools behandelen het voorbereiden van afbeeldingen, het werken met kleur, het genereren van CSS-effecten en de kleine productiemiddelen die door de kieren vallen. Ze draaien allemaal lokaal, wat voor afbeeldingen belangrijker is dan voor tekst: de foto die je zojuist hebt gecomprimeerd, is vaak een foto die je nog niet hebt gepubliceerd."},{"h":"Afbeeldingen voorbereiden voor internet"},{"p":"De meeste imagoproblemen zijn eigenlijk gewichtsproblemen. Een pagina die traag aanvoelt, bevat meestal afbeeldingen die groter zijn dan hun weergaveformaat, in het verkeerde formaat, met een kwaliteitsinstelling waar niemand ooit vraagtekens bij heeft gezet."},{"l":["[[image-compressor|Image Compressor]] — verklein de bestandsgrootte terwijl de afbeelding visueel intact blijft. Voer het uit voordat u iets uploadt naar een formulier met een maximale grootte.","[[image-resizer|Image Resizer]] — stel de werkelijke pixelafmetingen in die u nodig hebt. Dit is de grotere overwinning: een afbeelding van 4000 px, weergegeven op 800 px, bevat vijf keer zoveel gegevens die hij nodig heeft.","[[image-to-base64|Image to Base64]] — converteer een kleine afbeelding naar een gegevens-URI voor inlining in CSS, HTML of een e-mailsjabloon."]},{"b":"De volgorde is belangrijk. Eerst het formaat wijzigen, daarna comprimeren. Het comprimeren van een afbeelding van 4000 px levert een veel zwaarder bestand op dan het formaat wijzigen naar 800 px en vervolgens comprimeren met dezelfde kwaliteit, omdat compressoren hun inspanningen besteden aan pixels die toch zouden worden weggegooid."},{"p":"Hoeveel moet je comprimeren? Het eerlijke antwoord is: totdat het er verkeerd uitziet, en dan een stap teruggaan. Voor een fotografisch heldenbeeld is de kwaliteit van 70 tot 80 procent bij normaal kijkformaat meestal niet te onderscheiden van het origineel. Voor een logo, een screenshot of iets anders met een effen kleur en harde randen, gebruik PNG en comprimeer harder: deze winnen meer en verliezen minder."},{"p":"Een praktische vuistregel: alles onder de 200 KB is prima voor een hero-afbeelding, onder de 80 KB voor een thumbnail, en als je niet onder de 300 KB kunt komen, heb je waarschijnlijk eerder een dimensieprobleem dan een kwaliteitsprobleem."},{"h":"Base64: wanneer inlinen de juiste call is"},{"p":"Door een afbeelding naar een Base64-gegevens-URI te converteren, wordt een HTTP-verzoek verwijderd, wat klinkt als een pure overwinning. Meestal niet. De gecodeerde tekenreeks is ongeveer een derde groter dan het binaire bestand, kan niet afzonderlijk in de cache worden opgeslagen en vergroot uw CSS of HTML.\\n\\nAlleen inline als de afbeelding klein is (minder dan een paar kilobytes), één keer gebruikt en van cruciaal belang. Een klein pictogram in één e-mailsjabloon is het klassieke geval. Voor alles wat herhaald wordt over pagina\'s of groter is dan een paar kilobytes, dient u het als een bestand weer te geven en de browser het in de cache te laten opslaan."},{"h":"Watermerken: wat eerlijk verwijderbaar is"},{"l":[]},{"p":"Wees duidelijk over wat dit doet. Het verwijdert of verbergt het zichtbare merkteken. Het kan de onderliggende pixels niet reconstrueren; informatie die overschilderd is, is verdwenen en geen enkel filter vindt deze opnieuw uit. De resultaten variëren van onzichtbaar, wanneer de markering op een effen achtergrond zit, tot een duidelijke uitstrijkje wanneer de markering over details heen zit.\\n\\nNog één ding dat de moeite waard is om duidelijk te zeggen: het verwijderen van het watermerk van iemand anders en het publiceren van het resultaat is in de meeste rechtsgebieden een auteursrechtprobleem en een schending van de licentie, ongeacht of u gepakt wordt. Het verwijderen van markeringen uit uw eigen afbeeldingen of uit voorraad waarvoor u een licentie hebt, is het doel van deze tool."},{"h":"Kleur: omzetten, controleren, kiezen"},{"p":"Kleur is waar kleine fouten heel zichtbaar worden. Een contrastverhouding die niet toegankelijk is, een hex-waarde die eigenlijk een HSL-triple is, een palet dat er coherent uitziet op je monitor en modderig op een projector."},{"l":["[[color-converter|Color Converter]] — schakel tussen HEX, RGB en HSL. HSL is de moeite waard om te leren lezen, omdat tint 210, verzadiging 40 procent, lichtheid 50 procent veel gemakkelijker met de hand is aan te passen dan een hexadecimale waarde.","[[contrast-checker|Contrast Checker]] — test tekst tegen de achtergrond tegen WCAG-drempels. Dit is het nuttigste hulpmiddel in dit artikel, omdat het eerder een echt nalevingsprobleem dan een smaakprobleem aanpakt.","[[color-palette|Color Palette Generator]] — genereer een samenhangende set wanneer u begint met een merkkleur en de rest van de schaal nodig heeft."]},{"b":"Daarentegen vraagt ​​WCAG AA 4,5 op 1 voor normale hoofdtekst en 3 op 1 voor grote tekst. Als je voor een knop tussen twee merkkleuren moet kiezen, is de toegankelijke kleur meestal niet degene die de ontwerper leuk vindt. Controleer eerst en voer dan het argument met gegevens."},{"p":"Eén kanttekening bij kleurhulpmiddelen: ze gaan er allemaal van uit dat uw monitor is gekalibreerd en dat de persoon die uw pagina bekijkt, werkende ogen heeft. Geen van beide veronderstellingen is veilig. Dat is een reden om combinaties met contrastcontrole te verkiezen boven subjectieve combinaties."},{"h":"CSS-effecten zonder een ontwerptool te openen"},{"p":"Met de hand een verloop of een gelaagde schaduw schrijven is een echt onaangename taak. De syntaxis is onhandig, je kunt niet zien wat je produceert, en het verschil tussen een goede en een slechte schaduw is een paar pixels onscherpte."},{"l":["[[gradient-generator|CSS Gradient Generator]] — bouw lineaire en radiale gradiënten en kopieer de CSS rechtstreeks.","[[box-shadow-generator|Box Shadow Generator]] — breng meerdere schaduwen aan, wat een subtiele hoogte scheidt van een zware val.","[[border-radius-generator|Border Radius Generator]] — verkrijg de asymmetrische stralen die ervoor zorgen dat een vorm er opzettelijk uitziet.","[[text-shadow-generator|Text Shadow Generator]] — spaarzaam nuttig. De meeste tekstschaduwen zijn te sterk; Hiermee kunt u de offset aanpassen en vervagen totdat deze verdwijnt."]},{"p":"De truc voor alle vier is terughoudendheid. Twee schaduwen – een strakke donkere en een brede, zachte – lezen als fysieke verheffing. Eén schaduw leest als een website van vijftien jaar geleden. Genereer, kopieer en verwijder vervolgens totdat u niet meer weet dat het er is."},{"h":"De productiemiddelen die iedereen vergeet"},{"l":["[[favicon-generator|Favicon Generator]] — produceer de kleine pictogrammenset die een site daadwerkelijk nodig heeft. Dit staat op de lijst omdat favicons de activa zijn die het meest waarschijnlijk volledig zullen ontbreken, en een ontbrekende toont een algemeen browserpaginapictogram dat een voltooide site er onvoltooid uit laat zien.","[[emoji-picker|Emoji Picker]] — blader, zoek en kopieer emoji zonder door een besturingssysteemkiezer te hoeven zoeken. Echt handig als u teksten schrijft waarvoor één specifiek symbool nodig is."]},{"h":"Een uitgewerkt voorbeeld: het verzenden van een heldensectie"},{"p":"Hier is het hele cluster bezig met één echte taak. Een pagina heeft een held nodig met een achtergrondafbeelding, een kop en een knop, en die is nog niet gebouwd."},{"l":["**1. Reserveer de ruimte.** Geef de afbeeldingssleuf een vaste hoogte in de lay-out, zodat de pagina vanaf de eerste render de juiste vorm heeft in plaats van te springen wanneer de echte afbeelding landt.","**2. Formaat wijzigen en comprimeren.** Wanneer de echte foto arriveert, voert u deze door de [[image-resizer|Image Resizer]] op 1600px breed, en vervolgens door de [[image-compressor|Image Compressor]] op 75 procent. Dat is een bestand dat u kunt verzenden.","**3. Controleer het contrast van de tekst.** Een kop boven een foto is de klassieke contrastfout. Gebruik de [[contrast-checker|Contrast Checker]] om een ​​donkere overlaysterkte of een lichte tekstkleur te kiezen die AA passeert.","**4. Bouw de knop.** De [[box-shadow-generator|Box Shadow Generator]] geeft de hoogte, en de [[color-converter|Color Converter]] krijgt de merkkleur in het formaat dat de CSS nodig heeft.","**5. Ship.** Voeg een favicon toe van de [[favicon-generator|Favicon Generator]] zodat het tabblad er niet verlaten uitziet en de sectie klaar is."]},{"p":"Vijf tools, geen ontwerpsuite, en elke uitvoer is een waarde die u rechtstreeks in code kunt plakken."},{"h":"Veelgestelde vragen"},{"p":"**Worden mijn afbeeldingen ergens geüpload?** Nee. Compressie, formaatwijziging en Base64-conversie gebeuren allemaal in uw browser, wat de reden is dat er geen limiet voor de bestandsgrootte is en geen uploadwachtrij.\\n\\n**Zal bij het comprimeren van een afbeelding kwaliteit verloren gaan?** Altijd, per definitie. De vraag is of het zichtbaar is. Bij 70 tot 80 procent kwaliteit en correcte afmetingen is dat meestal niet het geval.\\n\\n**Waarom ziet mijn gewijzigde afbeelding er nog steeds groot uit?** Negen van de tien keer heb je gecomprimeerd voordat je de afbeelding hebt aangepast, of je slaat deze op als PNG terwijl een foto beter is als JPEG.\\n\\n**Kan ik deze gebruiken voor klantwerk?** Ja, zonder bronvermelding en zonder commerciële beperkingen.\\n\\n**Werken ze op een telefoon?** Ja, hoewel het wijzigen van de grootte en het comprimeren van grote foto\'s op een telefoon afhankelijk is van het geheugen van uw apparaat en niet van een server."},{"h":"De éénregelige versie"},{"p":"Pas het formaat aan voordat je comprimeert, controleer het contrast voordat je ruzie maakt over kleur, houd schaduwen subtiel en vergeet nooit de favicon. Dat is sowieso het meeste van wat een ontwerpsuite voor je deed."}]},"math-tools-for-real-numbers":{"title":"6 gratis wiskundige hulpmiddelen voor getallen die zich niet gedragen","description":"Wetenschappelijke notatie, decimalen naar breuken, controle van priemgetallen, faculteiten en GCF/LCM: gratis browsertools voor het getallenwerk dat gemakkelijk fout kan gaan.","category":"Wiskundige hulpmiddelen","blocks":[{"p":"De wiskunde die je eigenlijk nodig hebt op een computer, is niet de wiskunde waarop je bent geëxamineerd. Het is: heeft dit getal het formaat dat het systeem verwacht, is deze breuk vereenvoudigd, hoe snel groeit dit, en waarom zijn de rekenmachine en het spreadsheet het daar niet mee eens.\\n\\nDeze zes instrumenten bestrijken dat gebied. Ze draaien lokaal, wat voor rekenen één specifiek voordeel betekent dat het vermelden waard is: het getal dat je typt, wordt nergens heen gestuurd, zodat je zonder nadenken een berekening met een salaris, een saldo of een klantencijfer kunt controleren."},{"h":"Getallen in een vorm krijgen die een machine accepteert"},{"p":"Computers slaan decimale breuken op als binaire breuken. 0,1 is niet precies representatief in binair getal - de dichtstbijzijnde waarde met dubbele precisie is 0,100000000000000055511151231257827. Voeg 0,1 + 0,2 toe en je krijgt 0,30000000000000004, die standaard wordt afgedrukt als 0,3 en stilletjes een gelijkheidscontrole verbreekt."},{"l":["[[scientific-notation|Scientific Notation Converter]] — schakel tussen de standaard- en wetenschappelijke vorm, wat de manier is waarop de meeste logs, spreadsheets en API\'s feitelijk grote en kleine getallen opslaan.","[[decimale breuk|Decimaal naar breuk]] — converteer een decimaal getal naar een exacte breuk. Dit is de oplossing voor het bovenstaande probleem: 0,1 + 0,2 in de berekening van exacte breuken is 3/10, geen benadering."]},{"b":"Als je ooit een totaal hebt gezien dat 0,000000000000004 fout is, dan is dit de reden. In financiële code is het standaardantwoord om te werken in gehele centen, of in een decimale bibliotheek, en nooit in drijvende komma. Als je ooit hebt gezien dat een spreadsheet het met een fractie van een cent oneens was met een script, is het dezelfde bug met een andere hoed."},{"p":"Het is de moeite waard om de wetenschappelijke notatie vloeiend te beheersen, omdat dit het verschil is tussen het lezen van een logregel en het loensen ervan. 6.022e23, 1.6e-19 en 3e8 zijn het getal van Avogadro, de elementaire lading en de snelheid van het licht. Als deze op ruis lijken in plaats van cijfers, kunt u deze permanent oplossen door er een paar via de tool te converteren."},{"h":"Primes, en waarom het iemand iets kan schelen"},{"l":["[[prime-checker|Prime Number Checker]] — test of een getal een priemgetal is en bekijk de ontbinding ervan als dat niet het geval is.","[[gcf-calculator|GCF LCM Calculator]] — grootste gemene deler en kleinste gemene veelvoud."]},{"p":"Priemgetallen zijn geen schooloefening. De veiligheid van elke HTTPS-verbinding die u maakt, hangt af van het feit dat het vermenigvuldigen van twee grote priemgetallen eenvoudig is en het terugbetalen van het resultaat moeilijk is. Die asymmetrie is de hele basis van RSA.\\n\\nVoor alledaagse doeleinden gaat prime-controle meestal over breuken. Het vereenvoudigen van een breuk betekent dat je de boven- en onderkant deelt door hun grootste gemene deler, en dat kun je niet vinden zonder te ontbinden in factoren. Daarom horen deze twee tools bij elkaar: controleer de factoren en verkrijg vervolgens in één stap de GCF en LCM."},{"p":"De LCM-helft is degene die mensen vergeten, en het is degene die planningsproblemen oplost: twee evenementen die zich elke 18 dagen herhalen en elke 12 dagen vallen elke 36 dagen samen. Dezelfde rekenkunde, andere toepassing."},{"h":"Faculteiten, en de snelheid waarmee ze exploderen"},{"l":["[[factoriële rekenmachine|Factoriële rekenmachine]] — n! voor waarden waarbij het antwoord nog steeds betekenisvol is."]},{"p":"Factorials groeien sneller dan bijna alles wat je aan een bureau tegenkomt. 10! bedraagt ​​ongeveer 3,6 miljoen. 20! is ongeveer 2,4 quintiljoen – ruimschoots groter dan het aantal zandkorrels op aarde. 52!, het aantal manieren om een ​​pak kaarten te schudden, is grofweg 8 gevolgd door 67 cijfers.\\n\\nDe praktische consequentie is dat een programma dat alle permutaties opsomt, prima is op vijf items, aanvaardbaar is op acht, en permanent vastzit op twaalf. Als een taak het gevoel heeft dat hij nooit zal eindigen en je loopt over permutaties heen, dan is dit vrijwel zeker de reden. Het is ook het argument tegen de meeste brute-force-benaderingen, die eerder als rekenkundig dan als mening worden geformuleerd."},{"h":"Romeinse cijfers, en het vreemde eraan"},{"l":["[[Romeinse cijfers|Romeinse cijfers converter]] — converteren van en naar Romeinse cijfers."]},{"p":"Romeinse cijfers zijn de moeite waard om te begrijpen in plaats van alleen maar te converteren, omdat het systeem iets onthult over positionele notatie. Er is geen nul en geen plaatswaarde: XI betekent elf, of het nu elf stokjes of elfduizend vertegenwoordigt. Dat is de reden waarom het rekenen met Romeinse cijfers echt moeilijk is, en waarom het systeem eeuwenlang heeft bestaan, vooral vanwege tellen en dateren in plaats van rekenen.\\n\\nDe subtractieve regel is het deel dat mensen fout hebben. IV is vier, niet VI; IX is negen. Klokken vormen een bekende uitzondering: de Big Ben gebruikt IIII in plaats van IV, om redenen waar historici nog steeds over discussiëren. Converteren in plaats van afleiden is in elk geval de juiste keuze."},{"h":"Een uitgewerkt voorbeeld: een breuk met de hand controleren"},{"p":"Voor een recept zijn 0,375 kopjes nodig en een weegschaal die in grammen aangeeft, een rapport geeft een verhouding aan van 0,625, en beide zien eruit als cijfers die iemand haastig heeft getypt."},{"l":["**1. Zoek de exacte breuk.** Voer 0,375 uit met de tool [[decimale breuk|Decimaal naar breuk]]: 3/8. Run 0,625: 5/8. Geen van beiden had een rekenmachinegewoonte nodig die jij niet hebt.","**2. Vereenvoudig de verhouding.** Om 3/8 tegen 5/8 uit te drukken, heb je de GCF van 3 en 5 nodig. De [[gcf-calculator|GCF LCM Calculator]] geeft 1, dus de verhouding is 3:5 en al het eenvoudigst.","**3. Controleer de claim van de faculteiten.** Als iemand je vertelt dat een wachtrij van 9 bestellingen 362.880 arrangementen heeft, bevestigt de [[factorial-calculator|Factorial Calculator]] 9! is precies dat. Nu weet je of de schatting van de bouwtijd plausibel was.","**4. Normaliseer alles wat groot is.** Een server die 1,5-9 nanoseconden rapporteert, is 1,5 seconde, volgens de [[wetenschappelijke-notatie|Scientific Notation Converter]] – wat het verschil is tussen een latentieprobleem en een afrondingsartefact."]},{"h":"Wat deze tools bewust niet doen"},{"p":"Ze laten niet zien hoe ze werken, en ze geven geen les. Als je wilt begrijpen waarom een ​​formule waar is, is een rekenmachine het verkeerde instrument; hij geeft het antwoord zonder de reden, waardoor mensen uiteindelijk wel kunnen rekenen, maar niet kunnen redeneren.\\n\\nZe doen ook niet aan willekeurige precisie. Factoriële factoren en grote factorisaties zullen hun nauwkeurigheid verliezen voorbij het punt waarop het antwoord nog bruikbaar is, en een browsertabblad is geen computeralgebrasysteem. Voor alles waar correctheid er echt toe doet – techniek, financiën, cryptografie – gebruik een goede bibliotheek met exacte rekenkunde, geen webpagina."},{"h":"Je eigen rekenkunde controleren"},{"p":"De meest waardevolle wiskundige gewoonte is niet snelheid, maar schatting. Voordat u enig resultaat gelooft, moet u zich afvragen of het de juiste orde van grootte heeft: groter of kleiner dan de invoer, en ongeveer hoeveel. De meeste rekenfouten overleven elke andere controle, behalve deze.\\n\\nDoor eerst af te ronden, is de schatting gratis. Rond 0,375 tot 0,4, rond 5/8 tot 0,6, en de verhouding is duidelijk ongeveer 2:3 – dicht genoeg bij 3:5 om de breuk te bevestigen die u precies hebt berekend. Als het exacte antwoord en de schatting niet overeenkomen, heeft u een invoerfout gevonden in plaats van een afrondingsprobleem, en heeft u deze binnen enkele seconden gevonden.\\n\\nDit is ook de reden waarom een ​​rekenmachine geen vervanging is voor het nadenken over wat je hem vraagt. Een tool berekent perfect de verkeerde hoeveelheid, en de enige verdediging is weten hoe het antwoord zou moeten aanvoelen."},{"h":"Veelgestelde vragen"},{"p":"**Wordt mijn invoer ergens naartoe gestuurd?** Nee. Deze worden allemaal lokaal in uw browser uitgevoerd.\\n\\n**Waarom is 0,1 plus 0,2 niet gelijk aan 0,3?** Omdat noch 0,1, noch 0,2 exact representeerbaar is in binaire drijvende komma. De som is 0,30000000000000004, wat het dubbele is dat het dichtst bij 0,3 ligt.\\n\\n**Hoe groot kunnen deze faculteiten zijn?** Tot 170 voordat ze het bereik van een dubbel overschrijden. Voorbij wordt het antwoord weergegeven in wetenschappelijke notatie en heeft het dan geen betekenis meer.\\n\\n**Kan ik de uitvoer in code gebruiken?** Ja. Met name voor de resultaten van decimaal naar breuk moet u rekenen met gehele getallen op de teller en de noemer gebruiken in plaats van terug te rekenen naar een decimaal getal."},{"h":"De éénregelige versie"},{"p":"Gebruik exacte breuken als het om geld gaat. Bedenk dat faculteiten sneller ontploffen dan je verwacht, en priemfactorisatie is zowel een veiligheidsbasis als een truc om breuken te vereenvoudigen."}]},"everyday-utility-tools":{"title":"13 gratis dagelijkse hulpprogramma\'s: wachtwoorden, QR-codes, timers en tekstcodering","description":"Genereer wachtwoorden, bouw QR-codes, voer timers en klokken uit en decodeer binaire, hexadecimale en gecodeerde tekst - allemaal met gratis browsertools die niets uploaden.","category":"Hulpprogramma\'s","blocks":[{"p":"Deze laatste groep is de rommellade. Wachtwoorden, QR-codes, een stopwatch, een wereldklok, een muntstuk en vier tools die tekst omzetten in andere representaties van zichzelf. Individueel triviaal, gezamenlijk de spullen die je nodig hebt op lastige momenten.\\n\\nDe rode draad is dat ze alle dertien lokaal draaien. Voor een wachtwoordgenerator is dat geen aardigheidje; het is de hele reden dat de tool überhaupt te vertrouwen is."},{"h":"Wachtwoorden: het deel dat er echt toe doet"},{"l":["[[password-generator|Password Generator]] — genereer sterke willekeurige wachtwoorden van elke lengte en tekenset.","[[password-strength|Password Strength Checker]] — schat hoe resistent een wachtwoord is om lokaal te worden geraden."]},{"b":"Het allerbelangrijkste feit over de sterkte van wachtwoorden: **lengte wint het van complexiteit, en hergebruik is gevaarlijker.** Een wachtwoord van 16 tekens bestaande uit niet-gerelateerde woorden is sterker en veel beter typbaar dan een wirwar van symbolen van 10 tekens. Ondertussen wordt door één hergebruikt wachtwoord dat bij een inbreuk opduikt, in één keer elk account waarmee het in aanraking komt, uitgeschakeld. Het genereren van een duidelijk lang wachtwoord per site is de hele klus."},{"p":"Hoe de sterkte wordt geschat, is ook van belang. De meeste checkers benaderen de grootte van de zoekruimte, wat een redelijke indicatie is maar niet de waarheid: `CorrectHorseBatteryStaple` scoort goed op entropie, terwijl `P@ssw0rd1!` goed scoort op karaktervariatie en slecht in de praktijk omdat het in elke krakende woordenlijst ter wereld voorkomt.\\n\\nGebruik de generator voor alles wat u interesseert, en als u een wachtwoord moet onthouden, gebruik dan een wachtwoordzin van vier of vijf niet-gerelateerde woorden. Dat is het specifieke geval waarin memorabiliteit en kracht elkaar feitelijk overlappen."},{"h":"QR-codes: wat moet je erin zetten?"},{"l":["[[qr-code-generator|QR Code Generator]] — genereer een QR-code voor een URL, tekst, Wi-Fi-gegevens of contactgegevens."]},{"p":"QR-codes zijn een van die tools waarbij de uitvoerkwaliteit volledig wordt bepaald door één beslissing: hoeveel gegevens u invoert. Een korte URL wordt gecodeerd in een kleine, gemakkelijk scanbare code. Een alinea tekst met interpunctie wordt bij kleine formaten gecodeerd in iets compacts en onbetrouwbaars.\\n\\nTwee praktische regels. Maak eerst altijd een testscan van de code op het formaat waarin deze daadwerkelijk wordt afgedrukt, voordat u er tweehonderd afdrukt. Ten tweede gedragen Wi-Fi- en gewone URL-codes zich verschillend op verschillende telefoons. Als een code naar een gemengd publiek gaat, geef dan de voorkeur aan een gewone URL boven een landingspagina die vervolgens doorlinkt, omdat deze overal werkt en je kunt wijzigen waar deze naartoe verwijst."},{"h":"Tijd: timers, klokken en de val in tijdzones"},{"l":["[[stopwatch|Online Stopwatch]] — een gewone stopwatch, handig als je telefoon in de andere kamer ligt.","[[pomodoro-timer|Pomodoro Timer]] — Focusblokken van 25 minuten met pauzes, voor mensen die vinden dat die structuur werkt.","[[wereldklok|Wereldklok]] — huidige tijd in verschillende steden tegelijk."]},{"p":"De wereldklok verdient zijn plaats om één specifieke reden: zomertijd. De helft van de planningsfouten in de wereld zijn geen rekenfouten, maar een moment waarop twee steden vorige week vier uur uit elkaar lagen en deze week vijf uur, en niemand controleerde.\\n\\nVoordat u iets in een tijdzone plant, plaatst u beide steden in de wereldklok en kijkt u: bereken de offset niet uit het geheugen. Dit is ook de reden waarom uitnodigingen voor vergaderingen een tijdzone moeten bevatten in plaats van een enkel uur."},{"p":"Op de Pomodoro-timer: de techniek werkt voor een specifiek soort taak: begrensd, gefocust, ononderbroken. Het werkt niet bij het debuggen, waarbij de juiste zet bij het vastlopen is om weg te lopen, en niet om nog een blok van 25 minuten te starten. Gebruik het wanneer het helpt."},{"h":"Willekeurigheid, eerlijk gezegd"},{"p":"De [[random-number|Random Number Generator]] en de [[list-randomizer|List Randomizer]] behandelen de gevallen die zich daadwerkelijk voordoen: het kiezen van een getal in een bereik, en het in een goede volgorde plaatsen van een lijst. Een straf waard over eerlijkheid. Beiden maken gebruik van een pseudo-willekeurige generator, die voor het beslissen wie de lunch betaalt niet te onderscheiden is van een echte munt. Voor alles wat gevolgen heeft – een trekking met prijzen, een toewijzing waaraan geld is verbonden – wil je een bron die je kunt controleren, en een browsertabblad is dat niet. De waarde hier is het verwijderen van de mens, die slecht kiest als hij gemotiveerd is."},{"h":"De coderingsrommellade"},{"p":"Vier tools die tekst tussen representaties verplaatsen. Geen ervan is encryptie, en het onderscheid is de moeite waard om te vermelden omdat het voortdurend verward wordt: een codering is door iedereen omkeerbaar en heeft geen sleutel. Voor codering is een sleutel vereist."},{"l":["[[binary-text|Binary to Text]] — converteer tussen tekst en zijn binaire representatie.","[[hex-text|Hex naar tekst]] — converteer tussen tekst en hex, de representatie die je het vaakst ziet in netwerktools en debuggers.","[[caesar-cipher|Caesar Cipher]] - verschuif letters met een vast bedrag, het klassieke cijfer in het klaslokaal.","[[rot13-encoder|ROT13 Encoder]] — roteer letters met 13, een speciaal geval dat zijn eigen inverse is."]},{"p":"Deze zijn voor precies twee dingen nuttig. Ten eerste: begrijpen hoe tekst bytes wordt, het mentale model dat je nodig hebt als iets er onleesbaar uitziet. Ten tweede: het debuggen: wanneer een payload als hex verschijnt, kun je met de [[hex-text|Hex to Text]]-converter ontdekken wat er staat.\\n\\nZe zijn niet nuttig om iets te verbergen. ROT13 heeft geen sleutel – de dienst is openbaar – dus het verbergt niets voor iedereen die weet wat ROT13 is. Het Caesarcijfer heeft 25 mogelijke verschuivingen, die een mens in minuut één kan doorbreken."},{"h":"De twee die dingen formatteren"},{"l":["[[phone-formatter|Phone Number Formatter]] — normaliseer telefoonnummers in een consistent formaat.","[[file-size-converter|File Size Converter]] — converteer tussen KB, MB, GB en TB, waarbij het decimale en binaire onderscheid wordt uitgelegd."]},{"p":"De bestandsgrootteconverter heeft één echt waardevolle output: hij vertelt u waarom een ​​schijf een groter aantal adverteert dan uw computer meldt. Verkopers verkopen in machten van tien, besturingssystemen rapporteren machten van twee, en het verschil bedraagt ​​op elke schaal ongeveer 7 procent. Dat is geen fout, het zijn twee conventies."},{"h":"Een uitgewerkt voorbeeld: de verminkte API-reactie"},{"p":"De validatie van een webhook mislukt en de payload in het logboek ziet er als volgt uit: `\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f`. Dit is een tweeënnegentigste diagnose."},{"l":["**1. Convert.** Plak `48656c6c6f` in de [[hex-text|Hex to Text]] converter — het resultaat is `Hallo`. Het is nooit verminkt, alleen gecodeerd.","**2. Controleer de vorm.** Iets stroomopwaarts codeert de payload vóór ondertekening. De handtekening werd berekend over de originele tekst en gevalideerd tegen de hexadecimale tekst, dus de vergelijking mislukt.","**3. Sluit de andere richting uit.** Als het logboek leesbare tekst had getoond, zou het probleem het omgekeerde zijn geweest: het ondertekenen van het gecodeerde formulier.","**4. Bevestig de claim over de grootte.** Als hetzelfde logboek een payload van 1,2 MB rapporteert, bepaalt de [[file-size-converter|File Size Converter]] of dat decimaal of binair is voordat iemand ruzie maakt over een quotum."]},{"h":"Veelgestelde vragen"},{"p":"**Is de wachtwoordgenerator veilig als alles in de browser draait?** Ja, en meer nog dan een servergebaseerde generator: het wachtwoord wordt op uw machine gegenereerd en nooit verzonden, dus er valt niets te onderscheppen, te loggen of te kraken. Het nadeel is dat u een wachtwoord dat u niet hebt opgeslagen, niet kunt herstellen.\\n\\n**Kan ik de virtuele muntwissel vertrouwen?** Voor informele beslissingen, ja. Gebruik voor alles waar geld of prijzen aan verbonden zijn een bron die u kunt controleren.\\n\\n**Zijn de cijfers veilig?** Nee. Geen van allen. ROT13- en Caesar-cijfers hebben geen geheime sleutel en zijn bedoeld om codering aan te leren, niet om iets te beschermen.\\n\\n**Werken deze offline?** Zodra een pagina is geladen, ja – alles is lokaal.\\n\\n**Is er een limiet op de tekstlengte voor de converters?** Alleen het geheugen van uw apparaat, aangezien er niets ergens naartoe wordt verzonden."},{"h":"De éénregelige versie"},{"p":"Lange unieke wachtwoorden verslaan korte slimme wachtwoorden, een QR-code is slechts zo goed als de gegevens erin, controleer tijdzone-offsets in plaats van ze te berekenen, en codering is geen encryptie."}]}}')},64534,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"Geliştiricinin Araç Seti: Ücretli Uygulamaların Yerini Alan 24 Ücretsiz Tarayıcı Aracı","description":"Ücretsiz tarayıcı tabanlı geliştirici araçlarını kullanarak verileri biçimlendirmeye, dönüştürmeye, kodlamaya ve hata ayıklamaya yönelik pratik bir kılavuz - yükleme yok, hesap yok; çoğu araç girişi yerel olarak işler.","category":"Geliştirici Araçları","blocks":[{"p":"Haftada yüz kez yaptığınız küçük işlerin çoğu (bir API yanıtını yeniden biçimlendirmek, bir jetonun kodunu çözmek, bir hash\'i kontrol etmek, bir SQL bloğunu girintilemek) bir IDE\'ye, ücretli aboneliğe veya ekip lisansına ihtiyaç duymaz. Doksan saniye boyunca bir sekmenin açık olması gerekiyor.\\n\\nAşağıdaki koleksiyon, biçimlendirme, dönüştürme, kodlama, karma oluşturma ve hata ayıklamayı kapsayan yirmi dört tarayıcı tabanlı yardımcı programdan oluşmaktadır. Bunların her biri tamamen sayfanızda çalışır: verileriniz hiçbir zaman bir sunucuya gönderilmez; bu, geliştiricilerin genellikle kabul ettiğinden daha önemlidir, çünkü yapıştırdığınız veri yükü genellikle bir müşteriye aittir."},{"h":"Hangi tarayıcı tabanlı araçlar hangilerinin yerini alabilir ve alamaz?"},{"p":"Sınır konusunda gerçekçi olun. Bu araçlar bir defaya mahsus, düşük riskli, yüksek sıklıklı işlerin yerini alır. Dil sunucunuzun, hata ayıklayıcınızın, test paketinizin veya gerçek ortamda tekrar tekrar çalıştırmak için ihtiyaç duyduğunuz herhangi bir şeyin yerini almazlar."},{"l":["**İyi uyum:** yanıtı bir kez okumak, tek bir değerde hata ayıklamak, bir dosyayı tek bir içe aktarma işlemi için dönüştürmek, göndermeden önce biçimi kontrol etmek.","**Kötü uyum:** her dağıtımda aynı kontrolün çalıştırılması, yüzlerce dosyanın dönüştürülmesi, CI\'da yüksek sesle başarısız olması gereken her şey.","**Asla:** döndüremeyeceğiniz kimlik bilgilerini içeren herhangi bir şey. Canlı bir jeton değil, iptal edilmiş bir jeton yapıştırın."]},{"p":"Bununla birlikte, bu yer işaretlerini tutmanın nedeni verimdir. Bir tarayıcı sekmesinde kırk saniye süren bir görev asla planlanmaz, asla devredilmez ve asla akşam saat sekizde bir IDE açmak için bir neden haline gelmez."},{"h":"Verileri biçimlendirme ve dönüştürme"},{"p":"En yaygın günlük iş, verileri okunabilir hale getirmektir. Bir API, tek satırlık bir blob döndürür, bir iş arkadaşınız, sohbet penceresi tarafından yönetilen sekmelere sahip bir yapılandırma dosyası gönderir veya bir e-tabloyu JSON\'a aktardığınızda, devasa bir satır olarak geri gelir."},{"l":["[[json-formatter|JSON Formatter]] — bir veriyi girintileyin, doğrulayın ve okuyun. Hata ayıklamadan önce bunu kullanın: \\"API bozuk\\" biletlerinin yarısı aslında sonunda virgül bulunan hatalı biçimlendirilmiş JSON\'dur.","[[json-validator|JSON Validator]] — güzel bir baskı yerine katı bir geçti/kaldı cevabına ihtiyacınız olduğunda.","[[xml-formatter|XML Formatter]] — SOAP yanıtları, RSS beslemeleri ve Maven POM\'lar için 2014\'ten bu yana kimsenin dokunmadığı aynı iş.","[[json-to-yaml|JSON\'dan YAML\'a]] ve [[json-to-csv|JSON\'dan CSV\'ye]] — verileri gerçek sistemlerin gerçekte kullandığı formatlar arasında taşımak."]},{"p":"Belirli bir senaryo için son grubu aklınızda bulundurun: Bir müşteri size bir e-tablo verir ve bunu kendi API\'sinde bekler. CSV\'yi doğrudan JSON\'a aktarmak, öğleden sonraları komut dosyası yazmak yerine iki dakikalık bir iştir."},{"h":"Kodlama ve kaçış"},{"p":"Veriler iyi göründüğü için kodlama hataları orantısız derecede can sıkıcıdır. \\"San José & Sons\\" değeri \\"San Jos%C3%A9 %26 Sons\\" olarak geliyor ve veritabanıyla karşılaştırmanız, günlüklerde görünmeyen nedenlerden dolayı başarısız oluyor."},{"l":["[[url-encoder|URL Kodlayıcı / Kod Çözücü]] — bir sorgu dizesinin çift kodlu olup olmadığına hemen karar verin.","[[base64-encoder|Base64 Encoder / Decoder]] — bir sertifika parçasının kodunu çözün veya küçük bir varlığı CSS\'de satır içi olarak kodlayın.","[[html-entity-encoder|HTML Entity Encoder / Decoder]] — sayfanızdaki başıboş \\"&\\" işaretinin şablonunuzdan mı, yoksa verilerinizden mi geldiğini öğrenin.","[[unicode-converter|Unicode Converter]] — \\"bozuk\\" bir karakterin yanlış kodlamayla oluşturulmuş meşru bir karakter olduğu ortaya çıktığında kullanışlıdır.","[[number-base-converter|Number Base Converter]] — hesap makinesi uygulaması olmadan bir rengi, izin bit maskesini veya hafıza adresini kontrol edin."]},{"b":"Pratik bir alışkanlık: Bir değer bozuk geldiğinde, her seferinde bir katman olarak kodunu çözün ve her sonucu boş bir alana yapıştırın. İlk kod çözme okunabilir metin üretiyorsa sorun yukarı yönde bir yerde fazladan bir kodlamadır. Eğer mojibake üretiyorsa, kaçış probleminden ziyade kodlama probleminiz var demektir ve bu ikisinin farklı düzeltmelere ihtiyacı vardır."},{"h":"Tanımlayıcılar, karmalar ve belirteçler"},{"p":"Bu grup, geliştiricilerin bir kez yazdıkları ve kaybettikleri doğru yerel komut dosyasını ararken en çok zaman harcadıkları yerdir."},{"l":["[[uuid-generator|UUID Generator]] — tohum verileri, fikstürler veya hızlı bir veritabanı satırı için v4 tanımlayıcıları oluşturun.","[[md5-generator|MD5 / SHA Hash Generator]] — Bir indirmeyi doğrulayın veya aynı olması gereken iki dosyanın gerçekte olduğunu onaylayın.","[[timestamp-converter|Timestamp Converter]] — bu listenin tamamında en çok kullanılan araç. Bir günlük satırında 1761000000 yazıldığında, bu size olayın dağıtım sırasında mı yoksa dağıtımdan önce mi gerçekleştiğini söyler."]},{"p":"Zaman damgası dönüştürücüsü, belirli bir nedenden dolayı değerini kazanıyor: bir dönem numarası aynı zamanda hem kesin hem de işe yaramaz. Bir şeyin ne zaman olduğunu tam olarak bilirsiniz ve bunu bir meslektaşınıza söyleyemezsiniz. Bir kez dönüştürmek genellikle olması gerekenden daha yüksek sesli bir tartışmayı çözer."},{"h":"Karşılaştırma ve hata ayıklama"},{"l":["[[regex-tester|Regex Tester]] — buradaki en yüksek kaldıraca sahip öğe. Doğru görünen ve sessizce hiçbir şeyle eşleşmeyen bir düzenli ifade, geliştirmedeki en pahalı hatalardan biridir çünkü kimsenin okumadığı tek yerde sessizce başarısız olur.","[[html-preview|HTML Preview]] — gerçekte nasıl oluşturulduğunu kontrol etmek için işaretlemenin bir parçası üzerinde yineleme yapın."]},{"p":"Normal ifadelerinizi, boş dize, bir Unicode adı ve satırsonu içeren bir değer de dahil olmak üzere gerçekte beklediğiniz girdiye göre test edin. Çoğu model üçüncü durumda bozulur ve üretim verileri gelene kadar kimse bunu fark etmez."},{"h":"Çalışılmış bir örnek: üç araç, bir sıkıcı olay"},{"p":"İşte beni tüm bunlara yer işareti koymaya ikna eden dizi. Bir müşteri Salı günü gönderdikleri bir kaydın Perşembe günkü raporda eksik olduğunu bildirdi."},{"l":["**1. Zaman damgasını dönüştürün.** Rapor işi, kaydın oluşturulma süresini bir dönem değeri olarak günlüğe kaydetti. [[timestamp-converter|Timestamp Converter]], kaydın Salı günü yerel saat 23:00\'te oluşturulduğunu gösterdi — sorunun kayıt değil, işin saat dilimi varsayımı olduğu ortaya çıktı.","**2. Yükü biçimlendirin.** Saklanan JSON\'u [[json-formatter|JSON Formatter]] aracılığıyla aldığımızda, istemci aynı uç noktayı 200 ms aralıklarla iki kez çağırdığı ve ikinci yazma kazandığı için kaydın boş tarih alanıyla yazıldığı ortaya çıktı.","**3. Verileri karşılaştırın.** Her iki kayıt da aynı API anahtarını ve aynı istemci zaman damgasını taşıyordu; bu, iki ayrı müşteri yerine yeniden denemeyi işaret ediyordu."]},{"p":"Toplam geçen süre: dört dakika. Bir kayıt platformunda aynı temel nedeni arayan bu soruşturmanın önceki girişimi bir öğleden sonra sürdü ve yanlış bir sonuca vardı."},{"h":"Gizlilik: neden yerel olarak çalışmak asıl özelliktir?"},{"p":"Bu kitaplıktaki her araç, girişinizi kendi tarayıcınızda işler. Hiçbir şey yüklenmez; bu da, saklama sorusunun, işlemci anlaşmasının ve üç dakika önce yapıştırdığınız üretim verisi hakkında rahatsız edici konuşmaların olmayacağı anlamına gelir.\\n\\nBu araçları, barındırılan bir \\"pastebin API\'si\\" veya kaydolmanızı isteyen çevrimiçi bir hizmet yerine tercih etmenin nedeni budur. Bu aynı zamanda uçuş sırasında, bodrumda veya kurumsal VPN\'in başka bir alanı engellemeye karar vermesi durumunda çalışmaya devam edecekleri anlamına da gelir."},{"p":"Açıkça belirtmeye değer bir uyarı: Çevrimdışı özellikli bir sayfa, yalnızca sayfanın kendisi sizin düşündüğünüz kodsa özeldir. Paylaşılan bir makinede, özel bir pencere kullanın ve işiniz bittiğinde, özellikle de belirteçlerin kodunu çözüyorsanız kapatın."},{"h":"Çevrelerinde bir iş akışı oluşturmak"},{"p":"Araçlar tek tek önemsizdir. Değer, \\"daha sonra ulaşmak\\" yerine hemen bir tanesine ulaşma alışkanlığındadır, çünkü daha sonra, tek kullanımlık bir komut dosyası yazdığınızda, bir IDE açtığınızda veya kontrol etmeye değmediğine karar verdiğinizde olur."},{"l":["Tek tek URL\'leri değil, koleksiyonu yer imlerine ekleyin ve tarayıcınızın araç çubuğuna koyun.","Bir şeyler yanlış göründüğünde, bir teori oluşturmadan önce onu kontrol edin. On beş saniyeye mal olur; bütün sınıf yanlış çıkarımları yok eder.","Aynı şeyi iki kez kontrol ettiğinizde, bu onu otomatikleştirme sinyalidir; ancak şüphe üzerine otomatikleştirme yapmayın.","Üretim sırlarını yapıştırmayın. Emin olmadığınız her şeyi döndürün."]},{"h":"Sık sorulan sorular"},{"p":"**Bu araçlar ücretsiz mi?** Evet, tamamen, hesap yok ve kullanım sınırı yok. Temel herhangi bir şeyi geride tutan ücretli bir katman yoktur.\\n\\n**Çevrimdışı çalışıyorlar mı?** Bir sayfa yüklendikten sonra evet; her şey tarayıcınızda çalışır. Yeniden yükleme bir bağlantı gerektirir.\\n\\n**Bunları ticari amaçlarla kullanabilir miyim?** Evet. Çıktı, hiçbir atıfta bulunma zorunluluğu olmadan size aittir.\\n\\n**Bir API var mı?** Hayır ve bu kasıtlıdır; değer arayüzdür. Çıktıyı dışa aktarın ve istediğiniz gibi işleyin.\\n\\n**Neden bunun yerine bir CLI aracı yüklemiyorsunuz?** Üç kez ihtiyacınız olduğunda bir tane yükleyin. İlk ikisi için bir tarayıcı sekmesi kullanın."}]},"text-tools-for-writers":{"title":"Yazarlar, Öğrenciler ve Pazarlamacılar için 17 Ücretsiz Metin Aracı","description":"Tarayıcınızda yerel olarak çalışan ücretsiz tarayıcı araçlarıyla metni temizleyin, kelimeleri doğru şekilde sayın, listeleri biçimlendirin ve kaba taslakları yayınlanabilir bir şeye dönüştürün.","category":"Metin Araçları","blocks":[{"p":"İş için yazmak, yazmakla hiçbir ilgisi olmayan şaşırtıcı miktarda mekanik angarya içerir: yapıştırılan bir paragraftaki boşlukları çıkarmak, kelime sınırını kontrol etmek, ad listesinin tekilleştirilmesi, bir şeyi URL bilgisine dönüştürmek.\\n\\nBu on yedi araç işin bu kısmı içindir. Hepsi tarayıcıda yerel olarak çalışır ve bu da küçük bir ayrıntı değildir; yapıştırdığınız taslak genellikle yayınlanmaz ve sıraladığınız liste genellikle birisinin kişisel verileridir."},{"h":"Ne yazdığınızı ölçmek"},{"p":"Bir müşteri tam olarak 800 kelime isteyene ve editörünüz 820 diyene veya bir form, yeni satırın nereye gittiğine dair hiçbir açıklama olmadan 1.995 karakterlik metninizi reddedene kadar kelime sayımı çözülmüş gibi görünür."},{"l":["[[word-counter|Kelime Sayacı]] — standart ölçü. Yapıştırın, okuyun, ayarlayın.","[[letter-counter|Mektup Sayacı]] — karakterleri ve harf sıklığını sayar. Bir paragrafın neden yanlış geldiğinin hatalarını ayıklarken kullanışlıdır: bu genellikle tekrarlanan bir harf desenidir, bir rüya değil."]},{"p":"\\"Bir kelimenin\\" ne anlama geldiğine dair bir not: Farklı sayaçlar tireleme, sayılar ve URL\'ler konusunda anlaşamıyor. Kesin bir sayı önemliyse, çalışmanızı kontrol eden kişinin kullandığı sayacın aynısını kullanın ve üzerinde önceden anlaşın. Bu, küçük ve anlamsız tartışmaların gerçekten yaygın bir kaynağıdır."},{"h":"Yazmadığınız kopya temizleniyor"},{"p":"Aldığınız metnin çoğu hafif hasar görmüş: kopyala-yapıştır nedeniyle çift boşluk, başıboş bir sekme, aceleyle yazan birinin tutarsız büyük harf kullanımı. Elle düzeltmek yavaştır ve hataya açıktır."},{"l":["[[text-trimmer|Metin Kırpıcı]] — her satırın başındaki ve sonundaki boşlukları aynı anda kaldırın. Bu, bu listedeki diğer her şeyden daha fazla \\"biçimlendirme bozuk görünüyor\\" raporunu düzeltir.","[[text-case-converter|Metin Durumu Dönüştürücü]] — bir blok boyunca cümle büyüklüğü, başlık durumu, üst ve alt arasında geçiş yapın. Ayrıca yanlışlıkla CAPS LOCK paragrafını geri almanın en hızlı yolu.","[[text-to-slug|Text to Slug]] — bir başlığı temiz bir URL bilgisine dönüştürün. Başlığınızı yapıştırın, konuyu halledin, işiniz bitti."]},{"p":"Sümüklü böcek oluşturucunun URL\'lerin ötesinde bir kullanımı daha vardır: \\"final_final_v3\\"ü geride bırakan, bir insanın bir bakışta ayrıştırabileceği, okunabilir bir dosya adı veya bağlantı oluşturmanın hızlı bir yoludur."},{"h":"Listelerle çalışma"},{"p":"Listeler, envanterler, posta birleştirmeler, etiket temizlemeler, anket yanıtları, e-tablo sütunları; bir noktada her şey bir liste haline gelir ve her listenin sıralanması, tekilleştirilmesi veya rastgeleleştirilmesi gerekir."},{"l":["[[duplicate-line-remover|Duplicate Line Remover]] — iki listeyi karşılaştırın veya birini temizleyin. Çıktı size kaç kopyanın kaldırıldığını gösterir; bu, sonucu bildirirken faydalıdır.","[[list-sorter|Liste Sıralayıcısı]] — yapılandırılmış liste girişi için aynı iş.","[[list-randomizer|List Randomizer]] — kimsenin kayırmacılıktan şüphelenmemesi için bir çekiliş sırasını, bir sınav dizisini veya etrafı çevrili bir kısa listeyi karıştırın.","[[line-number-adder|Satır Numarası Toplayıcı]] — bir bildirimde veya kod inceleme yorumunda referans için sayı satırları."]},{"b":"Buradaki klasik tuzak, yinelenmemiş gibi görünen ancak öyle olmayan bir listedir: \'Apple\', \'apple\' ve \'Apple\' bir bilgisayar için üç farklı satırdır. Tekilleştirmeden önce boşlukları kesin ve sondaki noktalama işaretlerini kaldırın, aksi takdirde hiçbir şeyi birleştirmeyecek ve verilerin temiz olduğu sonucuna varacaksınız."},{"h":"Önizleme ve biçimlendirme"},{"p":"Markdown kazandı, ancak aynı şekilde değil. Araçlarınızın yarısı bunu oluşturuyor, yarısı yapmıyor ve yapmayan yarısı genellikle kıdemli birinin yapıştırması gereken şey."},{"l":["[[markdown-preview|Markdown Preview]] — canlı oluşturma, böylece bir tabloyu veya iç içe geçmiş bir listenin istemciye ulaşmadan hemen önce gerçekten göründüğünü kontrol edebilirsiniz.","[[text-repeater|Metin Tekrarlayıcı]] — bir dizeyi N kez tekrarlayın. Dolgu oluşturmak, test verileri oluşturmak veya ara sıra bir belgede bir noktaya değinmek için kullanışlıdır."]},{"p":"Markdown önizlemesi, tüm bu sette sessizce en çok zaman kazandıran araçtır, çünkü işlenmiş bir belgedeki bozuk bir tablo, ham metindeki bozuk bir tablodan çok daha görünür ve çok daha utanç vericidir."},{"h":"Gerisi ve onlara ne zaman ulaşacağınız"},{"l":["[[random-string|Random String Generator]] — okunabilir tekrarlar, yer tutucu kimlikleri veya kısa kodlar oluşturun. Bir şeyi elle icat etmekten daha iyidir çünkü onu yanlışlıkla yeniden kullanmayacaksınız.","[[Mors Kodu|Mors Kodu Çevirmeni]] — gerçekten eğlenceli, temalı bir proje veya bir bulmaca için ara sıra yararlı."]},{"p":"Bunlar daha düşük frekanslı araçlardır, ancak yer imlerine eklenmenin hiçbir maliyeti yoktur ve \\"Şu anda rastgele görünen bir değere ihtiyacım var ve bir tane oluşturma konusunda kendime güvenmiyorum\\" sorununu çözerler."},{"h":"Gerçekçi bir düzenleme geçişi"},{"p":"Başka birinden bir taslak geldiğinde ve sizin adınıza çıkması gerektiğinde işleyen düzen budur."},{"l":["**1. Kırp.** Önce tüm belgeyi [[text-trimmer|Metin Kırpıcı]] ile çalıştırın. Boşluk hasarı, asla göremeyeceğiniz paragrafların içinde gizlenir.","**2. Büyük/küçük harf temizleyin.** Yalnızca başlık için [[text-case-converter|Metin Durumu Dönüştürücüsü]]\'nü kullanın. Hiçbir zaman büyük/küçük harf dönüşümünü tam taslağa uygulamayın; bu, özel isimleri yok eder.","**3. Ölçün.** Yazmadan önce [[kelime sayacı|Kelime Sayacı]] ile uzunluğu kontrol edin, böylece parçanın nasıl bir şekil olması gerektiğini bilirsiniz.","**4. Önizleme.** Markdown içeriyorsa, onu [[markdown-preview|Markdown Preview]] ile oluşturun.","**5. Slug.** URL bilgisini en son, son başlıktan [[text-to-slug|Text to Slug]] ile oluşturun — daha sonra başlığı değiştirmek, bilgiyi bozar."]},{"p":"Geçişin tamamı birkaç dakika sürer ve bir belgenin teknik olarak doğru ve gözle görülür şekilde yanlış olduğu hata kategorisini ortadan kaldırır."},{"h":"Yazarların gizlilikle ilgili soruları"},{"p":"**Yayınlanmamış metnim bilgisayarımdan çıkıyor mu?** Hayır. Bu araçlar, metni tarayıcınızda işler ve hiçbir şey saklanmaz veya iletilmez.\\n\\n**Uzunluk sınırı var mı?** Sunucu çağrısı olmadığından sunucu tarafı sınırı yoktur. Son derece büyük girişler kendi cihazınızın belleğiyle sınırlıdır.\\n\\n**Çıktıyı ticari olarak kullanabilir miyim?** Evet, serbestçe, herhangi bir atıf yapılmadan.\\n\\n**Telefonda mı çalışıyorlar?** Evet. Düzen uyarlanır ve aynı kod çalışır."},{"h":"Bu araçlar sizin için ne yapmayacak?"},{"p":"Sınırlar konusunda açık sözlü olmaya değer çünkü yanlış şeyi makineleştiren bir araç, daha hızlı hata üretir.\\n\\nBu yardımcı programların hiçbiri size bir cümlenin açık olup olmadığını, bir iddianın kaynaklı olup olmadığını veya bir ses tonunun dinleyiciler için doğru olup olmadığını söyleyemez. Karakterleri sayarlar; düzyazıyı yargılamazlar. Bu sayfadaki her ölçümde güzel puan alan bir metin hâlâ okunamayabilir.\\n\\nDüzenleme de yapmıyorlar. Kendinizi tek tek tümceleri ölçekli olarak elle yeniden yazarken bulduğunuz anda, bir metin aracını aşmışsınız demektir ve ya uygun bir düzenleyici, regex ile bul ve değiştir — ki [[regex-tester|Regex Tester]] prova için gerçekten iyidir - ya da bir komut dosyası istersiniz. Tarayıcıyı mekanik katman için kullanın ve onun üzerindeki her şey için kendi kararınızı verin."},{"p":"Yapmayacakları bir şey daha kötü bir kaynağı düzeltmektir. E-tablonuz tutarsız adlandırmalarla doluysa - \\"Dr\\", \\"DR\\", \\"Dr.\\" hepsi tek bir sütunda - bir araç, ona verdiğiniz bilgileri aslına uygun bir şekilde sıralayacak ve tekilleştirecek ve bir tane olması gereken yerde hala üç girişe sahip olacaksınız. Verilerin temizlenmesi mekanik bir adım değil, bir karardır. Önce kanonik forma karar verin, ardından uygulayın ve ardından kontrol edin."},{"h":"Bir çalışma listesini kullanılabilir tutmak"},{"p":"Potansiyel müşterilerin, bağlantıların, referansların veya terimlerin bir listesini tutarsanız, bu liste sessizce bozulur. Başarısızlık modu her zaman aynıdır: aynı görünen girişler değildir ve bir birleştirme hiçbir şeyi ortadan kaldırmaz.\\n\\nİşe yarayan bir bakım geçişi sıkıcıdır: boşlukları kesin, büyük harfleri standartlaştırın, sondaki noktalama işaretlerini kaldırın ve ardından kopyaları kaldırın. Bu sırayla — tekilleştirmeden sonra yapılan kırpma, girişleri kaybeder. Bunu ayda bir kez aktif bir listede yapmak, iki saatlik telafisi olmayan bir karışıklığı on dakikalık bir angaryaya dönüştürür.\\n\\nİki listenin uzlaştırılması gerektiğinde - örneğin bir katılım listesine karşı bir kayıt listesi - her ikisini de önce [[list-sorter|Liste Sıralayıcısı]] ile sıralayın, böylece sıralanırlar, sonra gözle karşılaştırırlar. Karşılaştırmadan önce her iki tarafı da sıralamak, iki dakikalık bir kontrol ile yirmi dakikalık bir arama arasındaki farktır."},{"h":"Paket servis"},{"p":"Bu araçların hiçbiri akıllı değil. Önemli olan da bu: Yazının, yazı olmayan mekanik yüzde beşi kaldırılıyor, yani geri kalan yüzde doksan beş aslında cümlelerle ilgili. Aylık olarak kullandıklarınızı işaretleyin, gerisini görmezden gelin ve boşlukları elle düzeltmeyi bırakın."}]},"calculators-and-converters-guide":{"title":"Gerçekte İlgilendiğiniz Sayılar için 18 Ücretsiz Hesap Makinesi ve Dönüştürücü","description":"Yüzdeler, indirimler, ipuçları, krediler, tarihler, BMI ve birim dönüşümleri; hesap gerektirmeden bunların gerekçelerini gösteren ücretsiz tarayıcı hesaplayıcıları.","category":"Hesap makineleri","blocks":[{"p":"Herkesin faturayı bölmesi, indirimin gerçekten indirim olup olmadığına karar vermesi ve hiç düşünmeden sıcaklık veya dosya boyutunu dönüştürmesi gerekiyor. Ayrıca herkes, en az bir kez, kamuoyunda bunu yanlış anlar.\\n\\nBu, para, tarihler, sağlık ve iş ve seyahatte ortaya çıkan birim dönüşümlerini kapsayan on sekiz hesap makinesi ve dönüştürücüden oluşan bir koleksiyondur. Hepsi tarayıcıda çalışır: hiçbir şey kaydedilmez, dolayısıyla yazdığınız sayılar sizden başka kimseyi ilgilendirmez."},{"h":"Para hesaplamaları"},{"p":"En yaygın gerçek dünya matematiği bir şeyin yüzdesidir. Satış vergisi, bahşiş, indirim yığını, komisyon, büyüme oranı. Formül basit ama yine de insanların bunu yanlış anlamalarının nedeni neredeyse her zaman aynı: Yüzdeyi yanlış tabana uyguluyorlar."},{"l":["[[indirim hesaplayıcı|İndirim Hesaplayıcı]] — nihai fiyatı ve daha da önemlisi ne kadar tasarruf ettiğinizi hesaplayın. Yükseltilmiş liste fiyatından sonra gerçekte %20 olan \\"%50 indirimi\\" tespit etmek için kullanışlıdır.","[[bahşiş hesaplayıcı|İpucu Hesaplayıcı]] - bir faturayı bölün, bir yüzde seçin, isterseniz kişi başına yuvarlayın.","[[kredi-hesaplayıcı|Kredi Hesaplayıcı]] — aylık ödeme ve toplam faiz; bir kredinin uygun olup olmadığına aslında karar veren sayıdır."]},{"b":"İndirimlerde: %20 indirim ve ardından başka bir %20 indirim, %40 indirim değildir; %36\'dır. Ardışık yüzdeler indirgenmiş baz üzerinde bileşik oluşturur. Bu listedeki herhangi bir hesap makinesi bunu yaklaşık iki saniye içinde doğrulayacaktır ve bu, bu makaledeki en yararlı tek aritmetik olgudur."},{"p":"Kredi hesaplayıcısı özel bir notu hak ediyor. Önemli olan aylık ödeme değil, kredinin ömrü boyunca ödenen toplam faizdir çünkü bu, borçlanmanın gerçek maliyetidir. Aynı aylık ödemelere ve farklı vadelere sahip iki kredinin toplam faizi onbinlerce farklılık gösterebilir."},{"h":"Tarihler ve geri sayımlar"},{"p":"Tarih aritmetiği, çoğu insanın sessizce yanlış anladığı yerdir, çünkü insan aylarının farklı uzunlukları vardır ve cevap, \\"takvim ayları\\" mı yoksa \\"30 gün\\" mü kastettiğinize bağlı olarak değişir."},{"l":["[[date-difference|Tarih Farkı Hesaplayıcısı]] — iki tarih arasındaki gün (ve toplam aylar, yıllar).","[[days-until|Days Until Calculator]] — belirli bir tarihe geri sayım, çalışma günlerinin sayısı genellikle insanların gerçekte istedikleri kadardır.","[[age-calculator|Yaş Hesaplayıcı]] — yıl ve gün olarak tam yaş ve bir sonraki doğum günü.","[[timestamp-converter|Timestamp Converter]] — günlüklere, veritabanlarına veya API yanıtlarına dokunduğunuzda önemli olan, gerçek bir tarihe dönüştürülen bir Unix zaman damgası."]},{"p":"İnsanları şaşırtan ayrım: 1 Mart ile 1 Nisan arasındaki gün sayısı 31, ancak *ay* sayısı bir. İhbar süresi veya abonelik dönemi hesaplıyorsanız hangi birimi kastettiğinizi yazılı olarak belirtin."},{"h":"Dürüst olmak gerekirse sağlık rakamları"},{"l":["[[bmi-calculator|BMI Calculator]] — standart kategoriler ve aşağıdaki uyarılarla birlikte vücut kitle indeksi."]},{"p":"BMI, nüfus düzeyinde bir tarama istatistiğidir. Kas kütlesi, vücut kompozisyonu veya herhangi bir bireyin sağlığı hakkında hiçbir şey söylemez ve sporcularda, yaşlı yetişkinlerde ve farklı etnik gruplarda kondisyonun zayıf bir göstergesidir. Bunu, bir karar olarak değil, birkaç veri noktası arasında bir veri noktası olarak veya zaman içindeki değişimi izlemenin bir yolu olarak kullanın. Sağlığınızı etkileyecek kararlar veriyorsanız doğru araç bir tarayıcı sekmesi değil, bir klinisyendir."},{"h":"Birim dönüşümü: gündelik olanlar"},{"p":"Birim dönüşümü iki türe ayrılır: tam olarak doğru yapmanız gereken dönüşümler ve kabaca ihtiyacınız olan dönüşümler. Bu araçlar her ikisini de ele alır ve iş hangisinin hangisi olduğunu hatırlamaktır."},{"l":["[[length-converter|Uzunluk Dönüştürücü]] — metrikten İngiliz ölçü birimine ve geriye doğru: milimetre, santimetre, metre, kilometre, inç, fit, yarda, mil.","[[ağırlık dönüştürücü|Ağırlık Dönüştürücü]] — gram, kilogram, ons, pound, ton. Bir tariften veya nakliye etiketinden önce kontrol edilmesi gereken kişi.","[[temperature-converter|Sıcaklık Dönüştürücü]] — Celsius, Fahrenheit, Kelvin. Çünkü -10°C, 14°F değildir ve formül bir çarpma işlemi değildir.","[[speed-converter|Hız Dönüştürücü]] — km/sa, mil/sa, m/s, knot. Yabancı bir hız sınırı veya mühendislik spesifikasyonu için kullanışlıdır.","[[area-converter|Area Converter]] — metrekare, fit kare, dönüm, hektar. İnsanların mülk satın alırken veya kiralarken kötü tahmin ettiği şey budur.","[[hacim dönüştürücü|Hacim Dönüştürücü]] — litre, mililitre, galon, bardak, metreküp.","[[time-converter|Time Converter]] — saniye, dakika, saat, gün, hafta."]},{"b":"Bilmeye değer iki dönüşüm tuzağı: yukarıdaki veri depolama (pazarlamacılar 10^3 satıyor, işletim sistemleri 2^10 rapor ediyor) ve yakıt ekonomisi - 40 mpg (İngiliz) olarak fiyatlandırılan bir araba 40 mpg\'den (ABD) 33 mpg\'ye (ABD) daha yakın çünkü İngiliz galonu daha büyük. İkinciyi yanlış yapmak, kiralık arabanın gerçekçi olmayan derecede verimli görünmesine neden olur."},{"h":"İhtiyaç duymayı beklemeyeceğiniz ikisi"},{"l":["[[random-number|Random Number Generator]] — bir çekiliş, bir grup veya hızlı bir A/B bölünmesi için bir aralık dahilinde çekiliş yapar. Kesinlikle faydalıdır çünkü hile yaptığınız şüphesini ortadan kaldırır.","[[zar atma|Zar atma]] - yazı tura atmaktan yirmi yüzlü zara kadar herhangi bir zar, bir masa oyunu veya gerçek zarın masadan son kez yuvarlandığı masa üstü oturumu için."]},{"h":"Hesap makinesini doğru kullanmak"},{"p":"Hesap makinesi yalnızca hangi sayıyı sorduğunuzu biliyorsanız yardımcı olur. Üç alışkanlık fark yaratır."},{"l":["**Birinci turda ikinciyi hesaplayın.** Kesin sayı kararınızı değiştirmezse, bir tur kullanın. Giriş hatalarını yakalayan yuvarlak sayıların yüzdeleri kafanızda kontrol edilebilir.","**Büyüklüğü kontrol edin.** Bir sonuca inanmadan önce, bunun girdiden daha büyük mü yoksa daha küçük mü olması gerektiğini ve kabaca ne kadar olması gerektiğini sorun. Çoğu aritmetik hata, bunun dışında her kontrolde hayatta kalır.","**Çıktıyı değil, girdileri fotoğraflayın.** Daha sonra hesaplamayı yeniden çalıştırdığınızda önemli olan, ne sonuca vardığınız değil, ne varsaydığınızı bilmektir."]},{"h":"İnsanların aslında sorduğu sorular"},{"p":"**Numaralarım herhangi bir yerde saklanıyor mu?** Hayır. Hesaplamalar tarayıcınızda yapılır ve hiçbir şey iletilmez veya saklanmaz.\\n\\n**Bunlar telefonda çalışır mı?** Evet ve hesap makineleri tek elle kullanım için tasarlanmıştır.\\n\\n**Veri depolama için hangi dönüştürme standardını kullanıyorsunuz?** Varsayılan olarak ondalık sayı (1 KB = 1000 bayt), çünkü depolama bu şekilde satılır. İşletim sistemleri ikili rapor verir; bu nedenle sürücü küçülüyor gibi görünür; araç sessizce bir taraf seçmek yerine farkı açıklar.\\n\\n**Bunları kendi siteme yerleştirebilir miyim?** Hayır. Bunun yerine yer imlerine ekleyin; bunun maliyeti sıfırdır ve doğruluk sorunu size aittir."},{"h":"Yüzdeler: Önemli olan dört hata"},{"p":"Bir insanın günlük hayatta yaptığı neredeyse her yüzde hata aynı dört hatadan biridir. Onlara isim vermek onları kaçınılabilir kılar."},{"l":["**Yanlış taban.** \\"%10\'luk bir artış, ardından %10\'luk bir düşüş sizi başladığınız yerde bırakır\\" yanlıştır çünkü her ikisi de farklı tabanlar için geçerlidir. 100\'ün yüzde onu 10\'dur; 90\'ın yüzde onu 9\'dur.","**Yüzdelik yüzde.** İki indirimin üst üste gelmesi onları çarpar (0,8 × 0,8 = 0,64, yani %36 indirim), bunları eklemez.","**Yüzde puanlara karşı yüzde.** %4\'ten %6\'ya çıkan oran 2 yüzde puanı arttı, ancak göreceli olarak %50 arttı. Politika ve tıp bu kafa karışıklığıyla doludur ve bu her zaman tesadüfi değildir.","**Çok erken yuvarlama.** Yüzdeyi uygulamadan önce bir ara adımı yuvarlamak hatayı artırır. Son rakama kadar tam hassasiyeti koruyun ve son adımı kafanızdan ziyade hesap makinesinde yapın."]},{"p":"Eğer bu bölümün tamamından yalnızca bir alışkanlık edinirseniz, şunu alın: Herhangi birine bir yüzdeden bahsetmeden önce, bunun *yüzdesi* olduğunu yeniden belirtin. Bir sayı hakkında yapacağınız tartışmaların yarısı aslında paydayla ilgili tartışmalardır."},{"h":"Hesaplamayı ne zaman bırakacağını bilmek"},{"p":"Hassasiyetin artık kullanışlı olmadığı bir nokta vardır. İki ondalık basamağa kadar aylık ödeme anlamlıdır. Sekiz ondalık basamağa kadar öngörülen toplam maliyet, kredinin stres olmadan karşılayabileceğiniz tutara uyup uymadığı şeklindeki gerçek karardan kaçınmanın bir yoludur.\\n\\nYararlı test, duyarlılık sorusudur: Bu girdi %10 oranında hareket ederse karar değişir mi? Değilse, onu hassaslaştırmayı bırakın ve fazladan zamanı, cevabı harekete geçiren değişken üzerinde kullanın (genellikle oran yerine terim veya indirim yerine liste fiyatı)."},{"p":"Ve açıkça belirtmekte fayda olan bir sınır var: Bu hesap makineleri tavsiye değil, aritmetiktir. Tasarruf hedefi, emeklilik tarihi ve borç ödeme planının tümü risk, davranış ve zamanla ilgili kararlardır ve bir tarayıcı sekmesi bunların hiçbirini tartamaz. Yalnızca ne varsaydığınıza karar verdiğinizde size sayıların ne anlama geldiğini söyleyebilir. Bu ayrım, hesap makinesinin yararlı olması ile sorumlu olması arasındaki farktır."},{"h":"Tek satırlı versiyon"},{"p":"Para ve tarih hesaplayıcılarını doğru şekilde işaretleyin, BMI\'yi bir karar yerine tek bir sinyal olarak değerlendirin, yığılmış yüzdelerin çoğaldığını unutmayın ve bir sayı sözleşmeye bağlı herhangi bir şeye girdiğinde birim dönüşümünü kontrol edin. Bu neredeyse her şeyi kapsıyor."}]},"image-and-design-tools":{"title":"Tarayıcınızda Çalışan 14 Ücretsiz Resim ve Tasarım Aracı","description":"Photoshop\'u veya bir tasarım paketini yüklemeden görüntüleri sıkıştırın, yeniden boyutlandırın ve hazırlayın ve CSS efektleri, paletler, kontrast kontrolleri ve site simgeleri oluşturun.","category":"Tasarım Araçları","blocks":[{"p":"İmaj çalışmasının belirli bir sorunu vardır: iş genellikle küçüktür ve sunulan araçlar çok büyüktür. Bir kahraman görselinden 400 KB kesmeniz, tasarımcınızın bahsettiği onaltılık bir değer elde etmeniz veya henüz kimsenin yapmadığı bir favicon oluşturmanız gerekiyor. Bu bir abonelik gerektirmez.\\n\\nAşağıdaki on dört araç; görüntülerin hazırlanmasını, renklerle çalışmayı, CSS efektleri oluşturmayı ve gözden kaçan küçük prodüksiyon varlıklarını kapsar. Her biri yerel olarak çalışır ve bu, metinden çok görüntüler için önemlidir: Az önce sıkıştırdığınız fotoğraf genellikle henüz yayınlamadığınız bir fotoğraftır."},{"h":"Web için görsel hazırlama"},{"p":"Görüntü sorunlarının çoğu aslında kilo sorunudur. Yavaş gibi görünen bir sayfa genellikle ekran boyutlarından daha büyük, yanlış formatta, hiç kimsenin sorgulamadığı bir kalite ayarında görseller taşıyordur."},{"l":["[[image-compressor|Görüntü Sıkıştırıcı]] — görüntüyü görsel olarak sağlam tutarken dosya boyutunu küçültün. Boyut sınırı olan bir forma herhangi bir şey yüklemeden önce çalıştırın.","[[image-resizer|Image Resizer]] — ihtiyacınız olan gerçek piksel boyutlarını ayarlayın. Bu daha büyük bir kazanç: 800 pikselde görüntülenen 4000 piksellik bir görüntü, ihtiyaç duyduğu verinin beş katını taşıyor.","[[image-to-base64|Image to Base64]] — küçük bir resmi CSS, HTML veya bir e-posta şablonunda satır içi için bir veri URI\'sine dönüştürün."]},{"b":"Sıra önemlidir. Önce yeniden boyutlandırın, sonra sıkıştırın. 4000 piksellik bir görüntüyü sıkıştırmak, 800 piksele yeniden boyutlandırıp aynı kalitede sıkıştırmaktan çok daha ağır bir dosya üretir, çünkü kompresörler çabalarını zaten atılacak olan pikseller üzerinde harcarlar."},{"p":"Ne kadar sıkıştırmanız gerekir? Dürüst cevap şudur: Yanlış görünene kadar, sonra bir adım geri çekilin. Bir fotografik kahraman görüntüsü için, yüzde 70 ila 80\'lik kalite genellikle normal izleme boyutunda orijinalinden ayırt edilemez. Bir logo, ekran görüntüsü veya düz renkli ve sert kenarlı herhangi bir şey için PNG kullanın ve daha sert sıkıştırın; bunlar daha fazla kazanır ve daha az kaybeder."},{"p":"Pratik bir genel kural: Bir kahraman görseli için 200 KB\'ın altındaki her şey uygundur, küçük resim için 80 KB\'nin altındaki her şey uygundur ve 300 KB\'nin altına inemiyorsanız muhtemelen kalite sorunu yerine boyut sorununuz vardır."},{"h":"Base64: satır içi doğru çağrı olduğunda"},{"p":"Bir görüntüyü Base64 veri URI\'sine dönüştürmek, bir HTTP isteğini kaldırır ve bu da tamamen bir kazanç gibi görünür. Genellikle değildir. Kodlanmış dize, ikili dosyanın kabaca üçte biri kadar büyüktür, ayrı olarak önbelleğe alınamaz ve CSS\'nizi veya HTML\'nizi şişirir.\\n\\nSatır içi yalnızca görüntü küçük olduğunda (birkaç kilobaytın altında), bir kez kullanıldığında ve kritik olduğunda. Tek bir e-posta şablonundaki küçük bir simge klasik durumdur. Sayfalar arasında tekrarlanan veya birkaç kilobayttan büyük herhangi bir şeyi dosya olarak sunun ve tarayıcının önbelleğe almasına izin verin."},{"h":"Filigranlar: gerçekten kaldırılabilenler"},{"l":[]},{"p":"Bunun ne işe yaradığı konusunda açık olun. Görünür işareti kaldırır veya gizler. Altta yatan pikselleri yeniden oluşturamaz; üzeri boyanmış bilgiler kaybolur ve hiçbir filtre onu geri icat etmez. Sonuçlar, işaret düz bir arka plan üzerinde durduğunda görünmez olmaktan, detay üzerinde durduğunda belirgin bir lekeye kadar değişir.\\n\\nAçıkça söylemeye değer bir şey daha: Başka birinin filigranını kaldırmak ve sonucu yayınlamak, çoğu yargı alanında bir telif hakkı sorunudur ve yakalansanız da yakalansanız da bir lisans ihlalidir. Kendi görsellerinizden veya lisansladığınız stoktan işaretleri kaldırmak bu aracın amacıdır."},{"h":"Renk: dönüştürme, kontrol etme, seçme"},{"p":"Renk, küçük hataların çok görünür hale geldiği yerdir. Erişilebilirliği engelleyen bir kontrast oranı, aslında HSL üçlüsü olan altıgen bir değer, monitörünüzde tutarlı görünen ve projektörde çamurlu görünen bir palet."},{"l":["[[color-converter|Renk Dönüştürücü]] — HEX, RGB ve HSL arasında geçiş yapın. HSL okumayı öğrenmeye değer çünkü renk tonu 210, doygunluk yüzde 40, hafiflik yüzde 50\'yi elle ayarlamak, onaltılık bir değere göre çok daha kolaydır.","[[contrast-checker|Contrast Checker]] — metni WCAG eşiklerine göre arka planına göre test edin. Bu, bu makaledeki en kullanışlı araçtır çünkü bir zevk probleminden ziyade gerçek bir uyum problemini yakalar.","[[color-palette|Renk Paleti Oluşturucu]] — bir marka rengiyle başladığınızda ve ölçeğin geri kalanına ihtiyaç duyduğunuzda tutarlı bir set oluşturun."]},{"b":"Buna karşılık: WCAG AA normal gövde metni için 4,5\'e 1\'i ve büyük metin için 3\'e 1\'i ister. Bir düğme için iki marka rengi arasında seçim yapıyorsanız erişilebilir olan genellikle tasarımcının beğendiği renk olmaz. Önce kontrol edin, ardından verilerle tartışmaya girin."},{"p":"Renk araçlarıyla ilgili bir uyarı: Hepsi monitörünüzün kalibre edildiğini ve sayfanızı görüntüleyen kişinin gözlerinin çalıştığını varsayar. Her iki varsayım da güvenli değildir. Bu, kontrastı kontrol edilen kombinasyonları öznel olanlara tercih etmenin bir nedenidir."},{"h":"Bir tasarım aracı açmadan CSS efektleri"},{"p":"Elle bir degrade veya katmanlı bir gölge yazmak gerçekten hoş olmayan bir iştir. Sözdizimi karmaşıktır, ne ürettiğinizi göremezsiniz ve iyi bir gölge ile kötü bir gölge arasındaki fark birkaç piksellik bulanıklıktır."},{"l":["[[gradient-generator|CSS Gradient Generator]] — doğrusal ve radyal degradeler oluşturun ve CSS\'yi doğrudan kopyalayın.","[[box-shadow-generator|Box Shadow Generator]] — birden fazla gölgeyi katmanlayın; bu, hafif bir yükselişi ağır bir düşüşten ayıran şeydir.","[[border-radius-generator|Border Radius Generator]] — bir şeklin kasıtlı görünmesini sağlayan asimetrik yarıçapları elde edin.","[[text-shadow-generator|Metin Gölgesi Oluşturucu]] — idareli bir şekilde kullanışlıdır. Çoğu metin gölgesi çok güçlüdür; bu, ofseti ayarlamanıza ve kaybolana kadar bulanıklaştırmanıza olanak tanır."]},{"p":"Dördünün de hilesi kısıtlamadır. İki gölge (biri sıkı koyu diğeri geniş, yumuşak) fiziksel yükseklik olarak okunur. Bir gölge on beş yıl önceki bir web sitesi olarak okunuyor. Orada olduğunu anlayamayana kadar oluşturun, kopyalayın ve silin."},{"h":"Herkesin unuttuğu üretim varlıkları"},{"l":["[[favicon-generator|Favicon Generator]] — bir sitenin gerçekten ihtiyaç duyduğu küçük simge setini üretir. Bu listede yer alıyor çünkü favicon\'lar büyük olasılıkla tamamen eksik olan varlıklardır ve eksik olan, bitmiş bir siteyi yarım kalmış gibi gösteren genel bir tarayıcı sayfası simgesini gösterir.","[[emoji-picker|Emoji Picker]] — bir işletim sistemi seçiciyi aramadan emojilere göz atın, arayın ve kopyalayın. Belirli bir sembole ihtiyaç duyan bir metin yazarken gerçekten faydalıdır."]},{"h":"Çalışılmış bir örnek: bir kahraman bölümünün gönderilmesi"},{"p":"Burada tüm küme gerçek bir iş yapıyor. Bir sayfanın arka plan resmi, başlığı ve düğmesi olan bir kahramana ihtiyacı vardır ve bunların hiçbiri henüz oluşturulmamıştır."},{"l":["**1. Alanı ayırın.** Mizanpajda görüntü yuvasına sabit bir yükseklik verin, böylece sayfa, gerçek görüntü geldiğinde atlamak yerine ilk oluşturmadan itibaren doğru şekle sahip olur.","**2. Yeniden boyutlandırın ve sıkıştırın.** Gerçek fotoğraf geldiğinde, onu 1600 piksel genişliğinde [[image-resizer|Image Resizer]] ile, ardından yüzde 75\'te [[image-compressor|Image Compressor]] ile çalıştırın. Bu gönderebileceğiniz bir dosyadır.","**3. Metnin kontrastını kontrol edin.** Fotoğrafın üzerine başlık koymak klasik kontrast hatasıdır. Koyu bir kaplama gücü veya AA\'yı geçen açık bir metin rengi seçmek için [[contrast-checker|Contrast Checker]]\'ı kullanın.","**4. Düğmeyi oluşturun.** [[box-shadow-generator|Box Shadow Generator]] yüksekliği verir ve [[color-converter|Color Converter]] marka rengini CSS\'nin ihtiyaç duyduğu formata getirir.","**5. Gönder.** Sekmenin terkedilmiş gibi görünmemesi için [[favicon-generator|Favicon Generator]]\'dan bir favicon ekleyin ve bölüm tamamlandı."]},{"p":"Beş araç, tasarım paketi yok ve her çıktı, doğrudan koda yapıştırabileceğiniz bir değerdir."},{"h":"Sık sorulan sorular"},{"p":"**Resimlerim herhangi bir yere yüklendi mi?** Hayır. Sıkıştırma, yeniden boyutlandırma ve Base64 dönüştürme işlemlerinin tümü tarayıcınızda gerçekleşir; bu nedenle dosya boyutu sınırı ve yükleme sırası yoktur.\\n\\n**Görüntünün sıkıştırılması kaliteyi kaybeder mi?** Tanım gereği her zaman. Soru, görünür olup olmadığıdır. Yüzde 70 ila 80 kalite ve doğru boyutlarda genellikle değildir.\\n\\n**Yeniden boyutlandırılan resmim neden hala büyük görünüyor?** On fotoğraftan dokuzunu yeniden boyutlandırmadan önce sıkıştırdınız veya fotoğraf JPEG olarak daha iyiyken PNG olarak kaydediyorsunuz.\\n\\n**Bunları müşteri çalışmaları için kullanabilir miyim?** Evet, herhangi bir atıf veya ticari kısıtlama yoktur.\\n\\n**Telefonda çalışıyorlar mı?** Evet, ancak büyük fotoğrafların telefonda yeniden boyutlandırılması ve sıkıştırılması sunucudan ziyade cihazınızın belleğine bağlıdır."},{"h":"Tek satırlı versiyon"},{"p":"Sıkıştırmadan önce yeniden boyutlandırın, renk hakkında tartışmadan önce kontrastı kontrol edin, gölgeleri ince tutun ve site simgesini asla unutmayın. Zaten bir tasarım paketinin sizin için yaptığı şeylerin çoğu da buydu."}]},"math-tools-for-real-numbers":{"title":"Davranmayacak Sayılar İçin 6 Ücretsiz Matematik Aracı","description":"Bilimsel gösterim, ondalık sayılardan kesirlere geçiş, asal kontrol, faktöriyeller ve GCF/LCM — yanlış anlaşılması kolay sayı işleri için ücretsiz tarayıcı araçları.","category":"Matematik Araçları","blocks":[{"p":"Bir bilgisayarda aslında ihtiyacınız olan matematik, sınava girdiğiniz matematik değildir. Bu şu: Bu sayı sistemin beklediği formatta mı, bu kesir basitleştirilmiş mi, bu ne kadar hızlı büyüyor ve hesap makinesi ile elektronik tablo neden aynı fikirde değil?\\n\\nBu altı araç bu alanı kapsıyor. Yerel olarak çalışırlar, bu da aritmetik açısından adlandırılmaya değer belirli bir fayda anlamına gelir: Yazdığınız numara hiçbir yere gönderilmez, böylece maaş, bakiye veya müşteri rakamını içeren bir hesaplamayı ikinci kez düşünmeden kontrol edebilirsiniz."},{"h":"Sayıları makinenin kabul edeceği bir forma sokmak"},{"p":"Bilgisayarlar ondalık kesirleri ikili kesirler olarak saklar. 0,1, ikili olarak tam olarak temsil edilemez - en yakın çift duyarlıklı değer 0,10000000000000000055511151231257827\'dir. 0,1 + 0,2 eklediğinizde 0,300000000000000004 elde edersiniz; bu, varsayılan olarak 0,3 olarak yazdırılır ve eşitlik kontrolünü sessizce bozar."},{"l":["[[scientific-notation|Bilimsel Gösterim Dönüştürücü]] — standart ve bilimsel biçim arasında geçiş yapın; çoğu günlük, e-tablo ve API aslında büyük ve küçük sayıları bu şekilde depolar.","[[decimal-fraction|Ondalıktan Kesire]] — ondalık sayıyı tam kesire dönüştürür. Yukarıdaki problemin çözümü budur: Tam kesir aritmetiğinde 0,1 + 0,2, 3/10\'dur, bir yaklaşım değildir."]},{"b":"Eğer daha önce 0,000000000000000004 oranında yanlış olan bir toplam gördüyseniz, nedeni budur. Mali kodda standart cevap, tamsayı sentlerde veya ondalık kütüphanede çalışmaktır ve asla kayan noktada çalışmak değildir. Eğer bir e-tablonun bir senaryo ile bir kuruş kadar bile uyuşmadığını gördüyseniz, bu farklı bir şapka takan aynı böcektir."},{"p":"Bilimsel gösterimde akıcı olmaya değer çünkü bu, bir günlük satırını okumakla ona gözlerinizi kısarak bakmak arasındaki farktır. 6.022e23, 1.6e-19 ve 3e8 Avogadro sayısı, temel yük ve ışık hızıdır. Bunlar sayılardan ziyade gürültüye benziyorsa, araç aracılığıyla birkaçını dönüştürmek sorunu kalıcı olarak düzeltir."},{"h":"Asal sayılar ve neden kimsenin umrunda"},{"l":["[[prime-checker|Asal Sayı Denetleyicisi]] — bir sayının asal olup olmadığını test edin ve asal olmadığında çarpanlara ayrılmasını görün.","[[gcf-calculator|GCF LCM Calculator]] — en büyük ortak faktör ve en küçük ortak kat."]},{"p":"Asal sayılar bir okul alıştırması değildir. Yaptığınız her HTTPS bağlantısının güvenliği, iki büyük asal sayıyı çarpmanın kolay, sonucu geri çarpanlara ayırmanın zor olmasına bağlıdır. Bu asimetri RSA\'nın tüm temelini oluşturur.\\n\\nGünlük amaçlar için asal kontrol çoğunlukla kesirlerle ilgilidir. Bir kesri basitleştirmek, üst ve alt kısımları en büyük ortak çarpanlarına bölmek anlamına gelir ve bunu çarpanlara ayırmadan bulamazsınız. Bu iki aracın birbirine ait olmasının nedeni budur: Faktörleri kontrol edin, ardından tek adımda GCF ve LCM\'yi elde edin."},{"p":"LCM yarısı insanların unuttuğu kısımdır ve planlama sorunlarını çözen kısımdır: her 18 günde bir tekrarlanan ve her 12 günde bir tekrarlanan iki olay, her 36 günde bir çakışır. Aynı aritmetik, farklı uygulama."},{"h":"Faktöriyeller ve patlama hızları"},{"l":["[[faktöriyel-hesaplayıcı|Faktöriyel Hesaplayıcı]] — n! Cevabın hala anlamlı olduğu değerler için."]},{"p":"Faktöriyeller masa başında karşılaştığınız hemen hemen her şeyden daha hızlı büyür. 10! yaklaşık 3,6 milyondur. 20! yaklaşık 2,4 kentilyondur; bu, Dünya\'daki kum tanelerinin sayısından açık ara daha fazladır. 52!, bir kart destesini karıştırmanın yollarının sayısı, kabaca 8 ve ardından 67 rakam gelir.\\n\\nPratik sonuç, tüm permütasyonları sıralayan bir programın 5 öğede iyi, 8\'de tolere edilebilir ve kalıcı olarak 12\'de takılıp kalmasıdır. Bir görev asla bitmeyecekmiş gibi geliyorsa ve permütasyonlar üzerinde döngü yapıyorsanız, bunun nedeni neredeyse kesinlikle budur. Bu aynı zamanda fikirden ziyade aritmetik olarak ifade edilen kaba kuvvet yaklaşımlarının çoğuna karşı bir argümandır."},{"h":"Romen rakamları ve onlarla ilgili tuhaf şey"},{"l":["[[romen-rakamları|Romen Rakamı Dönüştürücü]] — Romen rakamlarına ve Romen rakamlarından dönüştürme."]},{"p":"Roma rakamları sadece dönüştürmekten ziyade anlaşılmaya değer çünkü sistem konumsal gösterimle ilgili bir şeyler ortaya koyuyor. Sıfır ve basamak değeri yoktur: XI, ister on bir çubuğu ister on bir bini temsil etsin, on bir anlamına gelir. Roma rakamlarıyla aritmetiğin gerçekten zor olmasının ve sistemin yüzyıllarca hesaplamak yerine çoğunlukla sayma ve tarihleme amacıyla ayakta kalmasının nedeni budur.\\n\\nÇıkarma kuralı insanların yanlış anladığı kısımdır. IV dörttür, VI değil; IX dokuzdur. Saatler ünlü bir istisnadır - tarihçilerin hala tartıştığı nedenlerden dolayı Big Ben IV yerine IIII\'ü kullanır. Türetmek yerine dönüştürmek her durumda doğru çağrıdır."},{"h":"Çalışılmış bir örnek: bir kesirin elle kontrol edilmesi"},{"p":"Bir tarif için 0,375 bardağa ve gram olarak okunan bir ölçeğe ihtiyaç vardır; bir raporda 0,625 olarak bir oran belirtilir ve her ikisi de birinin aceleyle yazdığı sayılara benzer."},{"l":["**1. Tam kesri bulun.** [[ondalık-kesir|Ondalıktan Kesire]] aracıyla 0,375\'i çalıştırın: 3/8. 0,625: 5/8\'i çalıştırın. Sizde olmayan bir hesap makinesi alışkanlığına da ihtiyacınız yoktu.","**2. Oranı basitleştirin.** 5/8\'e karşı 3/8\'i ifade etmek için 3 ve 5\'lik GCF\'ye ihtiyacınız vardır. [[gcf-calculator|GCF LCM Hesaplayıcı]] 1 verir, yani oran 3:5\'tir ve zaten en basittir.","**3. Faktöriyel iddiasını kontrol edin.** Birisi size 9 siparişten oluşan bir kuyrukta 362.880 düzenleme bulunduğunu söylerse, [[faktöriyel-hesaplayıcı|Faktöriyel Hesaplayıcı]] 9\'u doğrular! tam olarak budur. Artık yapım süresi tahmininin makul olup olmadığını biliyorsunuz.","**4. Büyük olan her şeyi normalleştirin.** 1,5e9 nanosaniye rapor eden bir sunucu, [[bilimsel-gösterim|Bilimsel Gösterim Dönüştürücüsü]]\'ne göre 1,5 saniyedir — bu, gecikme sorunu ile yuvarlama yapısı arasındaki farktır."]},{"h":"Bu araçların kasıtlı olarak yapmadığı şeyler"},{"p":"Çalıştıklarını göstermiyorlar ve öğretmiyorlar. Bir formülün neden doğru olduğunu anlamanız gerekiyorsa, hesap makinesi yanlış araçtır; nedeni olmadan yanıt verir; insanlar bu şekilde hesaplama yapabilir ve akıl yürütemez hale gelir.\\n\\nAyrıca keyfi kesinlik de yapmazlar. Faktöriyeller ve büyük çarpanlara ayırmalar, cevabın hala yararlı olduğu noktadan sonra doğruluğunu kaybedecektir ve tarayıcı sekmesi bir bilgisayar cebir sistemi değildir. Doğruluğun gerçekten önemli olduğu herhangi bir şey için (mühendislik, finans, kriptografi) bir web sayfası değil, tam aritmetik içeren uygun bir kütüphane kullanın."},{"h":"Kendi aritmetiğinizi kontrol etme"},{"p":"En değerli matematik alışkanlığı hız değil, tahmindir. Herhangi bir sonuca inanmadan önce, bunun büyüklük açısından doğru olup olmadığını sorun: girdiden daha büyük mü yoksa daha mı küçük ve kabaca ne kadar. Çoğu aritmetik hata, bunun dışındaki tüm kontrollerde geçerliliğini korur.\\n\\nÖnce yuvarlama, tahmini serbest bırakır. 0,375\'i 0,4\'e yuvarlayın, 5/8\'i 0,6\'ya yuvarlayın ve oran açıkça 2:3 civarındadır; tam olarak hesapladığınız kesri doğrulamak için 3:5\'e yeterince yakındır. Kesin cevap ve tahmin uyuşmuyorsa, yuvarlama sorunu yerine bir giriş hatası buldunuz ve bunu saniyeler içinde buldunuz.\\n\\nHesap makinesinin, ona ne sorduğunuz hakkında düşünmenin yerini tutmamasının nedeni de budur. Bir araç yanlış miktarı mükemmel bir şekilde hesaplayacaktır ve tek savunma, cevabın nasıl olması gerektiğini bilmektir."},{"h":"Sık sorulan sorular"},{"p":"**Girişim herhangi bir yere gönderiliyor mu?** Hayır. Bunların tümü tarayıcınızda yerel olarak çalışır.\\n\\n**0,1 artı 0,2 neden 0,3\'e eşit değil?** Çünkü ne 0,1 ne de 0,2 ikili kayan noktada tam olarak temsil edilebilir. Toplam 0,3000000000000000004 olup, 0,3\'e en yakın çifttir.\\n\\n**Bunlar ne kadar büyük bir faktöriyel ile başa çıkabilir?** Bir double aralığını aşmadan önce 170\'e kadar. Yanıt bilimsel gösterimle görüntülendikten sonra artık anlamlı olmuyor.\\n\\n**Çıktıyı kodda kullanabilir miyim?** Evet. Özellikle ondalıktan kesire dönüştürme sonuçları için, geri ondalık sayıya dönüştürmek yerine pay ve paydada tamsayı aritmetiği kullanın."},{"h":"Tek satırlı versiyon"},{"p":"Para söz konusu olduğunda tam kesirleri kullanın, faktöriyellerin beklediğinizden daha hızlı patladığını ve asal çarpanlara ayırmanın hem bir güvenlik temeli hem de kesirleri basitleştirmenin bir yolu olduğunu unutmayın."}]},"everyday-utility-tools":{"title":"13 Ücretsiz Günlük Yardımcı Program: Şifreler, QR Kodları, Zamanlayıcılar ve Metin Kodlama","description":"Hesap gerektirmeden, yerel olarak çalışan ücretsiz tarayıcı araçlarıyla parolalar oluşturun, QR kodları oluşturun, zamanlayıcıları ve saatleri çalıştırın ve ikili, onaltılı ve şifreli metinlerin kodunu çözün.","category":"Yardımcı Araçlar","blocks":[{"p":"Bu son grup hurda çekmecesidir. Parolalar, QR kodları, kronometre, dünya saati, yazı tura atma ve metni kendisinin başka temsillerine dönüştüren dört araç. Bireysel olarak önemsiz, toplu olarak ise tuhaf anlarda ihtiyaç duyduğunuz şeyler.\\n\\nKesin olan şu ki, on üçünün tamamı yerel olarak çalışıyor. Bir şifre oluşturucu için bu hoş bir özellik değil; araca güvenilebilmesinin tek nedeni budur."},{"h":"Şifreler: gerçekten önemli olan kısım"},{"l":["[[password-generator|Password Generator]] — herhangi bir uzunluk ve karakter kümesinde güçlü, rastgele şifreler oluşturun.","[[password-strength|Password Strength Checker]] — bir şifrenin yerel olarak tahmin edilmeye karşı ne kadar dirençli olduğunu tahmin edin."]},{"b":"Şifre gücüyle ilgili tek ve en önemli gerçek: **uzunluk karmaşıklığı yener ve yeniden kullanım her ikisini de tehlike olarak yener.** İlgisiz kelimelerden oluşan 16 karakterlik bir şifre, 10 karakterlik simgelerden oluşan bir karmaşadan daha güçlüdür ve çok daha kolay yazılabilir. Bu arada, yeniden kullanılan bir şifrenin ihlal nedeniyle ortaya çıkması, bu şifrenin dokunduğu tüm hesapları aynı anda devre dışı bırakıyor. İşin tamamı site başına ayrı, uzun bir şifre oluşturmaktır."},{"p":"Gücün nasıl tahmin edildiği de önemlidir. Çoğu dama, arama alanının boyutunu yaklaşık olarak tahmin eder; bu makul bir göstergedir ancak gerçek değildir: \'CorrectHorseBatteryStaple\' entropide iyi puan alırken, \'P@ssw0rd1!\' karakter çeşitliliğinde iyi puan alır ve pratikte kötü puan alır çünkü dünyadaki her harika kelime listesinde yer alır.\\n\\nİlgilendiğiniz herhangi bir şey için oluşturucuyu kullanın ve bir şifreyi hatırlamanız gerekiyorsa alakasız dört veya beş kelimeden oluşan bir şifre kullanın. Unutulmazlık ve gücün aslında örtüştüğü özel durum budur."},{"h":"QR kodları: bunlara ne konulmalı"},{"l":["[[qr-code-generator|QR Code Generator]] — bir URL, metin, Wi-Fi ayrıntıları veya iletişim bilgileri için bir QR kodu oluşturun."]},{"p":"QR kodları, çıktı kalitesinin tamamen tek bir kararla belirlendiği araçlardan biridir: ne kadar veri koyacağınız. Kısa bir URL, küçük, kolayca taranabilen bir koda kodlanır. Noktalama işaretli bir metin paragrafı, küçük boyutlarda yoğun ve güvenilmez bir şeye kodlanır.\\n\\nİki pratik kural. İlk olarak, iki yüz tanesini yazdırmadan önce her zaman kodu gerçekte yazdırılacağı boyutta test taramasıyla tarayın. İkincisi, Wi-Fi ve düz URL kodları farklı telefonlarda farklı davranır; eğer bir kod karışık bir hedef kitleye gidecekse, daha sonra bağlantı veren bir açılış sayfası yerine düz bir URL\'yi tercih edin, çünkü her yerde çalışır ve işaret ettiği yeri değiştirebilirsiniz."},{"h":"Zaman: zamanlayıcılar, saatler ve zaman dilimlerindeki tuzak"},{"l":["[[kronometre|Çevrimiçi Kronometre]] — telefonunuz diğer odadayken kullanışlı olan basit bir kronometre.","[[pomodoro-timer|Pomodoro Zamanlayıcı]] — Bu yapının işe yaradığını düşünen kişiler için aralarla birlikte 25 dakikalık odak blokları.","[[dünya saati|Dünya Saati]] — aynı anda birden fazla şehirde geçerli saat."]},{"p":"Dünya saati yerini belirli bir nedenden dolayı kazanıyor: yaz saati uygulaması. Dünyadaki planlama hatalarının yarısı aritmetik hatalar değil; bunlar, iki şehrin geçen hafta dört saat, bu hafta ise beş saat arayla olduğu ve kimsenin kontrol etmediği bir an.\\n\\nBir zaman diliminde herhangi bir şeyi planlamadan önce, her iki şehri de dünya saatine yerleştirin ve bakın; farkı bellekten hesaplamayın. Toplantı davetlerinin yalnızca bir saat yerine bir saat dilimi taşımasının nedeni de budur."},{"p":"Pomodoro zamanlayıcısında: teknik belirli bir tür görev için çalışır - sınırlı, odaklanmış, kesintisiz. Sıkıştığında doğru hareketin başka bir 25 dakikalık blok başlatmak değil, uzaklaşmak olduğu hata ayıklama için işe yaramaz. Faydası olduğunda kullanın."},{"h":"Rastgelelik, dürüst olmak gerekirse"},{"p":"[[random-number|Random Number Generator]] ve [[list-randomizer|List Randomizer]] gerçekte ortaya çıkan durumları kapsar: bir aralıktan bir sayı seçmek ve bir listeyi adil bir sıraya koymak. Adalet konusunda bir cümleye değer. Her ikisi de öğle yemeğini kimin ödeyeceğine karar vermek için gerçek bir madeni paradan ayırt edilemeyen sözde rastgele bir jeneratör kullanıyor. Önemli herhangi bir şey için (ödüllü bir çekiliş, para eklenmiş bir tahsis) denetleyebileceğiniz bir kaynak istersiniz ve bir tarayıcı sekmesi o değildir. Buradaki değer, motive edildiğinde kötü seçim yapan insanı ortadan kaldırmaktır."},{"h":"Kodlama önemsiz çekmecesi"},{"p":"Metni temsiller arasında hareket ettiren dört araç. Bunların hiçbiri şifreleme değildir ve sürekli karıştırıldığı için bu ayrım belirtilmeye değerdir: Bir kodlama herkes tarafından tersine çevrilebilir ve anahtarı yoktur. Şifreleme bir anahtar gerektirir."},{"l":["[[binary-text|İkili Metinden Metne]] — metin ve onun ikili gösterimi arasında dönüştürme.","[[hex-text|Hex\'ten Metne]] — ağ araçlarında ve hata ayıklayıcılarda en sık gördüğünüz temsil olan metin ve hex arasında dönüştürme.","[[caesar-cipher|Caesar Cipher]] — klasik sınıf şifresi olan harfleri sabit bir miktarda kaydırın.","[[rot13-encoder|ROT13 Encoder]] — harfleri 13 oranında döndürün; bu, kendisinin tersi olan özel bir durumdur."]},{"p":"Bunlar tam olarak iki şey için faydalıdır. İlk olarak, metnin nasıl bayt haline geldiğini anlamak; herhangi bir şey bozuk göründüğünde ihtiyacınız olan zihinsel model budur. İkincisi, aslında hata ayıklama: Bir veri onaltılı olarak göründüğünde, [[hex-text|Hex to Text]] dönüştürücü onun ne dediğini öğrenmenin yoludur.\\n\\nHerhangi bir şeyi saklamak açısından işe yaramazlar. ROT13\'ün anahtarı yoktur - vardiya halka açıktır - dolayısıyla ROT13\'ün ne olduğunu bilen kimseden hiçbir şeyi saklamaz. Sezar şifresinin 25 olası değişimi vardır ve bir insan bunu ilk dakikada kırar."},{"h":"Bir şeyleri biçimlendiren iki şey"},{"l":["[[phone-formatter|Phone Number Formatter]] — telefon numaralarını tutarlı bir formatta normalleştirin.","[[file-size-converter|Dosya Boyutu Dönüştürücü]] — ondalık ve ikili ayrım açıklanarak KB, MB, GB ve TB arasında dönüştürme."]},{"p":"Dosya boyutu dönüştürücünün gerçekten değerli bir çıktısı vardır: bir sürücünün neden bilgisayarınızın bildirdiğinden daha büyük bir sayının reklamını yaptığını size söyler. Satıcılar on katı olarak satış yapıyor, işletim sistemleri iki katı olarak rapor ediyor ve aradaki fark her ölçekte yaklaşık yüzde 7. Bu bir hata değil, iki sözleşmedir."},{"h":"Çalışılmış bir örnek: bozuk API yanıtı"},{"p":"Bir web kancası doğrulamada başarısız oluyor ve günlükteki yük `\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f` gibi görünüyor. Bu doksan ikinci bir teşhis."},{"l":["**1. Dönüştürün.** \'48656c6c6f\'yi [[hex-text|Hex to Text]] dönüştürücüye yapıştırın — sonuç \'Merhaba\' olur. Hiçbir zaman bozulmadı, sadece kodlandı.","**2. Şekli kontrol edin.** Yukarı akıştaki bir şey, imzalamadan önce yükü onaltılık kodluyor. İmza orijinal metin üzerinden hesaplandı ve onaltılık sayıya göre doğrulandı, dolayısıyla karşılaştırma başarısız oldu.","**3. Diğer yönü göz ardı edin.** Günlükte okunabilir metin gösterilseydi sorun tam tersi olurdu: kodlanmış formun imzalanması.","**4. Boyut iddiasını onaylayın.** Aynı günlük 1,2 MB\'lık bir yük rapor ediyorsa, [[file-size-converter|Dosya Boyutu Dönüştürücü]] kimse kota hakkında tartışmadan önce bunun ondalık sayı mı yoksa ikili sayı mı olduğuna karar verir."]},{"h":"Sık sorulan sorular"},{"p":"**Her şey tarayıcıda çalışıyorsa şifre oluşturucu güvenli midir?** Evet ve sunucu tabanlı olandan daha da fazlası: şifre makinenizde oluşturulur ve asla iletilmez; dolayısıyla müdahale edilecek, günlüğe kaydedilecek veya ihlal edilecek hiçbir şey yoktur. Bunun dezavantajı, kaydetmediğiniz bir şifreyi kurtaramayacağınızdır.\\n\\n**Sanal yazı tura atmaya güvenebilir miyim?** Sıradan kararlar için evet. Para veya ödüller içeren herhangi bir şey için denetleyebileceğiniz bir kaynak kullanın.\\n\\n**Şifreler güvenli mi?** Hayır. Hiçbiri. ROT13 ve Caesar şifrelerinin gizli anahtarı yoktur ve herhangi bir şeyi korumak için değil, kodlamayı öğretmek için vardırlar.\\n\\n**Bunlar çevrimdışı çalışıyor mu?** Bir sayfa yüklendikten sonra evet; her şey yereldir.\\n\\n**Dönüştürücüler için metin uzunluğu sınırı var mı?** Hiçbir yere hiçbir şey gönderilmediğinden yalnızca cihazınızın belleği."},{"h":"Tek satırlı versiyon"},{"p":"Uzun benzersiz şifreler kısa akıllı şifreleri yener, bir QR kodu yalnızca içindeki veriler kadar iyidir, bunları hesaplamak yerine saat dilimi farklarını kontrol edin ve kodlama şifreleme değildir."}]}}')},20485,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"Zestaw narzędzi programisty: 24 bezpłatne narzędzia przeglądarki, które zastępują płatne aplikacje","description":"Praktyczny przewodnik po formatowaniu, konwertowaniu, kodowaniu i debugowaniu danych przy użyciu bezpłatnych narzędzi programistycznych opartych na przeglądarce — bez instalacji, bez kont; większość narzędzi przetwarza dane wejściowe lokalnie.","category":"Narzędzia programistyczne","blocks":[{"p":"Większość drobnych zadań, które wykonujesz sto razy w tygodniu — przeformatowanie odpowiedzi API, dekodowanie tokena, sprawdzanie skrótu, wcięcie fragmentu kodu SQL — nie wymaga IDE, płatnej subskrypcji ani licencji zespołowej. Muszą jedną kartę otworzyć przez dziewięćdziesiąt sekund.\\n\\nPoniższa kolekcja zawiera dwadzieścia cztery narzędzia oparte na przeglądarce, obejmujące formatowanie, konwersję, kodowanie, mieszanie i debugowanie. Każdy z nich działa całkowicie na Twojej stronie: Twoje dane nigdy nie są wysyłane na serwer, co ma większe znaczenie, niż zwykle przyznają programiści, ponieważ wklejany ładunek należy zwykle do klienta."},{"h":"Jakie narzędzia oparte na przeglądarce mogą, a czego nie mogą zastąpić"},{"p":"Bądź realistą, jeśli chodzi o granicę. Narzędzia te zastępują jednorazowe prace o niskiej stawce i wymagające dużej częstotliwości. Nie zastępują one serwera językowego, debugera, zestawu testów ani niczego, czego potrzebujesz, aby wielokrotnie uruchamiać się w rzeczywistym środowisku."},{"l":["**Dobre dopasowanie:** jednokrotne przeczytanie odpowiedzi, debugowanie pojedynczej wartości, konwersja pliku na potrzeby jednego importu, sprawdzenie formatu przed wysyłką.","**Złe dopasowanie:** przeprowadzanie tej samej kontroli przy każdym wdrożeniu, przekształcanie setek plików, wszystko, co musi głośno kończyć się niepowodzeniem w CI.","**Nigdy:** niczego, co wiąże się z danymi uwierzytelniającymi, których nie można zmienić. Wklej unieważniony token, a nie aktywny."]},{"p":"W związku z tym powodem, dla którego warto zachować te zakładki, jest przepustowość. Zadanie, które na karcie przeglądarki zajmuje czterdzieści sekund, nigdy nie jest zaplanowane, nigdy nie jest delegowane i nigdy nie staje się powodem do otwarcia IDE o ósmej wieczorem."},{"h":"Formatowanie i konwertowanie danych"},{"p":"Najczęstszą codzienną pracą jest zapewnienie czytelności danych. Interfejs API zwraca jednoliniowy obiekt typu blob, kolega wysyła plik konfiguracyjny z zakładkami zniekształconymi przez okno czatu lub wyeksportowałeś arkusz kalkulacyjny do formatu JSON i wrócił on w postaci jednej ogromnej linii."},{"l":["[[json-formatter|JSON Formatter]] — wcina, sprawdza poprawność i odczytuje ładunek. Użyj go przed debugowaniem: połowa wszystkich biletów „interfejs API jest uszkodzony” to w rzeczywistości zniekształcone kody JSON z końcowym przecinkiem.","[[json-validator|JSON Validator]] — gdy potrzebujesz ścisłej odpowiedzi Pass/Fail, a nie ładnego wydruku.","[[xml-formatter|XML Formatter]] — to samo zadanie dla odpowiedzi SOAP, kanałów RSS i POM Maven, których nikt nie dotykał od 2014 roku.","[[json-to-yaml|JSON do YAML]] i [[json-to-csv|JSON do CSV]] — przenoszenie danych pomiędzy formatami faktycznie używanymi przez rzeczywiste systemy."]},{"p":"Pamiętaj o ostatniej grupie w przypadku jednego konkretnego scenariusza: klient wręcza Ci arkusz kalkulacyjny i oczekuje go w swoim API. Bezpośrednie przejście pliku CSV do JSON to dwie minuty pracy, a nie popołudnie pisania skryptów."},{"h":"Kodowanie i ucieczka"},{"p":"Błędy w kodowaniu są nieproporcjonalnie irytujące, ponieważ dane wyglądają dobrze. Wartość „San José & Sons” pojawia się jako „San Jos%C3%A9 %26 Sons”, a porównanie z bazą danych kończy się niepowodzeniem z powodów niewidocznych w logach."},{"l":["[[url-encoder|Koder / Dekoder URL]] — natychmiast ustal, czy ciąg zapytania jest podwójnie kodowany.","[[base64-encoder|Base64 Encoder/Decoder]] — zdekoduj fragment certyfikatu lub zakoduj mały zasób, aby umieścić go w CSS.","[[html-entity-encoder|Enkoder/dekoder encji HTML]] — dowiedz się, czy ten zbłąkany „&” na Twojej stronie pochodzi z Twojego szablonu czy z Twoich danych.","[[unicode-converter|Konwerter Unicode]] — przydatne, gdy „uszkodzony” znak okazuje się prawidłowy, renderowany w złym kodowaniu.","[[konwerter podstawy liczb|Konwerter podstawy liczb]] — sprawdź kolor, maskę bitową uprawnień lub adres pamięci bez aplikacji kalkulatora."]},{"b":"Praktyczny nawyk: gdy wartość przychodzi zniekształcona, dekoduj ją warstwa po warstwie i wklejaj każdy wynik w puste pole. Jeśli pierwsze dekodowanie daje czytelny tekst, problemem jest jedno dodatkowe kodowanie gdzieś w górę. Jeśli generuje mojibake, masz problem z kodowaniem, a nie z ucieczką, a te dwa wymagają różnych poprawek."},{"h":"Identyfikatory, skróty i tokeny"},{"p":"W tej grupie programiści marnują najwięcej czasu na poszukiwanie odpowiedniego lokalnego skryptu, który napisali raz i zgubili."},{"l":["[[uuid-generator|Generator UUID]] — wygeneruj identyfikatory v4 dla danych początkowych, urządzeń lub wiersza szybkiej bazy danych.","[[md5-generator|MD5 / SHA Hash Generator]] — zweryfikuj pobranie lub potwierdź, że w rzeczywistości są dwa pliki, które powinny być identyczne.","[[timestamp-converter|Timestamp Converter]] — najczęściej używane narzędzie na całej liście. Jeśli w dzienniku znajduje się liczba 1761000000, informacja ta informuje, czy zdarzenie miało miejsce podczas wdrażania, czy przed nim."]},{"p":"Konwerter znaczników czasu zasługuje na swoje utrzymanie z jednego konkretnego powodu: numer epoki jest jednoznaczny i jednocześnie bezużyteczny. Wiesz dokładnie, kiedy coś się wydarzyło i nie możesz powiedzieć o tym koledze. Jednorazowa konwersja zwykle rozstrzyga głośniejszy argument, niż powinna."},{"h":"Porównywanie i debugowanie"},{"l":["[[regex-tester|Regex Tester]] — pozycja o najwyższej dźwigni tutaj. Wyrażenie regularne, które wygląda poprawnie i po cichu nie pasuje do niczego, jest jednym z najkosztowniejszych błędów w rozwoju, ponieważ zawodzi po cichu w jednym miejscu, którego nikt nie czyta.","[[html-preview|Podgląd HTML]] — iteruj po fragmencie znaczników, aby sprawdzić, jak faktycznie jest on renderowany."]},{"p":"Przetestuj swoje wyrażenia regularne pod kątem danych wejściowych, których faktycznie oczekujesz, w tym pustego ciągu znaków, nazwy Unicode i wartości ze znakiem nowej linii. Większość wzorców załamuje się w trzecim przypadku i nikt tego nie zauważa, dopóki nie pojawią się dane produkcyjne."},{"h":"Sprawdzony przykład: trzy narzędzia, jeden nudny incydent"},{"p":"Oto sekwencja, która przekonała mnie do dodania tego wszystkiego do zakładek. Klient zgłosił, że w czwartkowym raporcie nie było wpisu, który przesłał we wtorek."},{"l":["**1. Konwertuj znacznik czasu.** Zadanie raportu rejestrowało czas utworzenia rekordu jako wartość epoki. [[timestamp-converter|Timestamp Converter]] pokazało, że rekord został utworzony o 23:00 lokalnie, czyli we wtorek — problemem było założenie strefy czasowej zadania, a nie rekord.","**2. Sformatuj ładunek.** Pobranie zapisanego pliku JSON przez [[json-formatter|JSON Formatter]] ujawniło, że rekord został zapisany z polem daty zerowej, ponieważ klient dwukrotnie wywołał ten sam punkt końcowy w odstępie 200 ms i wygrał drugi zapis.","**3. Porównaj ładunki.** Obydwa rekordy zawierały ten sam klucz API i tę samą sygnaturę czasową klienta, która wskazywała na ponowną próbę, a nie na dwóch oddzielnych klientów."]},{"p":"Całkowity czas, który upłynął: cztery minuty. Poprzednia próba tego dochodzenia, podczas której szukano tej samej pierwotnej przyczyny na platformie logowania, trwała całe popołudnie i doprowadziła do błędnych wniosków."},{"h":"Prywatność: dlaczego uruchamianie lokalne jest właściwą funkcją"},{"p":"Każde narzędzie w tej bibliotece przetwarza Twoje dane wejściowe w Twojej przeglądarce. Nic nie jest przesyłane, co oznacza brak pytań o przechowywanie, brak umowy dotyczącej procesora i brak niewygodnych rozmów na temat ładunku produkcyjnego wklejonego trzy minuty temu.\\n\\nTo jest powód, dla którego wolimy te narzędzia od hostowanego „API Pastebin” lub usługi online wymagającej rejestracji. Oznacza to również, że nadal pracują w samolocie, w piwnicy lub gdy korporacyjna sieć VPN zdecydowała się zablokować kolejną domenę."},{"p":"Jedno zastrzeżenie warto wyraźnie podkreślić: strona obsługująca tryb offline jest prywatna tylko wtedy, gdy sama strona jest kodem, o jakim myślisz. Na współdzielonej maszynie użyj prywatnego okna i zamknij je, gdy skończysz, szczególnie jeśli dekodowałeś tokeny."},{"h":"Budowanie wokół nich przepływu pracy"},{"p":"Narzędzia są indywidualnie trywialne. Wartość ma zwyczaj sięgania po nie natychmiast, zamiast „zajmować się tym później”, ponieważ później jest to, gdy piszesz jednorazowy skrypt, otwierasz IDE lub decydujesz, że w ogóle nie warto tego sprawdzać."},{"l":["Dodaj do zakładek kolekcję, a nie poszczególne adresy URL, i umieść ją na pasku narzędzi przeglądarki.","Jeśli coś wygląda nie tak, sprawdź to, zanim uformujesz teorię. Kosztuje piętnaście sekund; zabija całe klasy błędnych wniosków.","Kiedy dwukrotnie sprawdziłeś tę samą rzecz, jest to sygnał, aby to zautomatyzować – ale nie automatyzuj w oparciu o podejrzenia.","Nie wklejaj tajemnic produkcyjnych. Obróć wszystko, czego nie jesteś pewien."]},{"h":"Często zadawane pytania"},{"p":"**Czy te narzędzia są bezpłatne?** Tak, całkowicie, bez konta i bez limitu wykorzystania. Żaden płatny poziom nie powstrzymuje niczego podstawowego.\\n\\n**Czy działają w trybie offline?** Po załadowaniu strony tak – wszystko działa w Twojej przeglądarce. Ponowne załadowanie wymaga połączenia.\\n\\n**Czy mogę ich używać do pracy komercyjnej?** Tak. Wynik jest Twój i nie wymaga podania źródła.\\n\\n**Czy istnieje interfejs API?** Nie i jest to celowe — wartością jest interfejs. Wyeksportuj dane wyjściowe i przetwórz je w dowolny sposób.\\n\\n**Może zamiast tego po prostu zainstaluj narzędzie CLI?** Zainstaluj je, gdy będziesz go potrzebować trzy razy. W przypadku pierwszych dwóch użyj karty przeglądarki."}]},"text-tools-for-writers":{"title":"17 darmowych narzędzi tekstowych dla pisarzy, studentów i marketerów","description":"Oczyść kopię, dokładnie policz słowa, sformatuj listy i zamień wstępne wersje robocze w coś, co można opublikować — dzięki bezpłatnym narzędziom przeglądarkowym, które działają lokalnie w Twojej przeglądarce.","category":"Narzędzia tekstowe","blocks":[{"p":"Pisanie do pracy wiąże się z zaskakującą ilością mechanicznej harówki, która nie ma nic wspólnego z pisaniem: usuwaniem zbędnych białych znaków z wklejonego akapitu, sprawdzaniem limitu słów, usuwaniem duplikatów listy nazwisk, konwertowaniem czegoś na ślimak URL.\\n\\nTych siedemnaście narzędzi jest przeznaczonych do tej części pracy. Wszystkie działają lokalnie w przeglądarce, co nie jest małym szczegółem – wklejona wersja robocza często nie jest publikowana, a sortowana lista często zawiera czyjeś dane osobowe."},{"h":"Pomiar tego co napisałeś"},{"p":"Liczenie słów wydaje się rozwiązane, dopóki klient nie poprosi o dokładnie 800 słów, a redaktor powie 820, lub formularz odrzuci tekst zawierający 1995 znaków bez wyjaśnienia, gdzie poszedł znak nowej linii."},{"l":["[[licznik słów|Licznik słów]] — miara standardowa. Wklej, przeczytaj, dostosuj.","[[licznik-liter|Licznik liter]] — zlicza znaki i częstotliwość liter. Przydatne podczas debugowania, dlaczego jeden akapit wydaje się nieprawidłowy: zwykle jest to powtarzający się wzór literowy, a nie sen."]},{"p":"Uwaga na temat znaczenia „słowa”: różne liczniki nie zgadzają się co do dzielenia wyrazów, liczb i adresów URL. Jeżeli istotna jest dokładna liczba, skorzystaj z tego samego licznika, którego używa osoba sprawdzająca Twoją pracę i uzgodnij to wcześniej. Jest to naprawdę częste źródło drobnych, bezsensownych kłótni."},{"h":"Sprzątanie kopii, której nie napisałeś"},{"p":"Większość otrzymywanego tekstu jest lekko uszkodzona: podwójne spacje powstałe w wyniku kopiowania i wklejania, zabłąkana tabulator, niespójne pisanie wielkimi literami spowodowane pisaniem w pośpiechu. Ręczna naprawa jest powolna i podatna na błędy."},{"l":["[[text-trimmer|Text Trimmer]] — usuń początkowe i końcowe białe znaki z każdej linii jednocześnie. Naprawia to więcej raportów „formatowanie wygląda na uszkodzone” niż cokolwiek innego na tej liście.","[[text-case-converter|Konwerter wielkości liter]] — przełącza między wielkością zdań, wielkością liter w tytule, górną i dolną częścią bloku. Również najszybszy sposób na cofnięcie przypadkowego akapitu CAPS LOCK.","[[text-to-slug|Tekst do Slug]] — zamień nagłówek w czysty fragment adresu URL. Wklej tytuł, pobierz plik i gotowe."]},{"p":"Generator ślimaków ma jeszcze jedno zastosowanie poza adresami URL: jest szybkim sposobem na utworzenie czytelnej nazwy pliku lub kotwicy, którą człowiek może przeanalizować na pierwszy rzut oka, co przewyższa `final_final_v3`."},{"h":"Praca z listami"},{"p":"Listy, inwentarze, korespondencja seryjna, porządkowanie tagów, odpowiedzi na ankiety, kolumny arkusza kalkulacyjnego — w pewnym momencie wszystko staje się listą i każda lista wymaga sortowania, usuwania duplikatów lub losowania."},{"l":["[[usuwanie duplikatów linii|Usuwanie duplikatów linii]] — porównaj dwie listy lub wyczyść jedną. Dane wyjściowe informują, ile duplikatów zostało usuniętych, co jest przydatne podczas raportowania wyniku.","[[list-sorter|List Sorter]] — to samo zadanie dla wprowadzania danych z listy strukturalnej.","[[list-randomizer|List Randomizer]] — przetasuj kolejność losowania, sekwencję quizu lub wydzieloną krótką listę, aby nikt nie podejrzewał faworyzowania.","[[line-number-adder|Line Number Adder]] — numerowanie linii w celach informacyjnych w zgłoszeniu lub komentarzu do przeglądu kodu."]},{"b":"Klasyczną pułapką jest tutaj lista, która wygląda na pozbawioną duplikatu, ale nią nie jest: `Apple`, `apple ` i `Apple.` to trzy różne linie prowadzące do komputera. Przed deduplikacją przytnij białe znaki i usuń końcowe znaki interpunkcyjne, w przeciwnym razie niczego nie połączysz i uznasz, że dane są czyste."},{"h":"Podgląd i formatowanie"},{"p":"Markdown wygrał, ale nie równomiernie. Połowa narzędzi renderuje go, połowa nie, a połowa, która tego nie robi, jest zwykle tym, do którego musi wkleić ktoś starszy."},{"l":["[[markdown-preview|Markdown Preview]] — renderowanie na żywo, dzięki czemu możesz sprawdzić, czy tabela lub zagnieżdżona lista faktycznie wygląda tuż przed dotarciem do klienta.","[[text-repeater|Text Repeater]] — powtórz ciąg N razy. Przydatne do generowania uzupełnień, danych testowych lub okazjonalnie do wyrażania opinii w dokumencie."]},{"p":"Podgląd Markdown to narzędzie, które po cichu oszczędza najwięcej czasu z całego zestawu, ponieważ uszkodzona tabela w renderowanym dokumencie jest znacznie bardziej widoczna — i znacznie bardziej zawstydzająca — niż uszkodzona tabela w nieprzetworzonym tekście."},{"h":"Reszta i kiedy po nie sięgnąć"},{"l":["[[random-string|Generator ciągów losowych]] — generuj czytelne wartości jednorazowe, identyfikatory zastępcze lub krótkie kody. Lepsze to niż wymyślanie czegoś ręcznie, bo przypadkowo nie użyjesz tego ponownie.","[[kod Morse\'a|Tłumacz alfabetu Morse\'a]] — naprawdę zabawny, czasami przydatny do projektu tematycznego lub układanki."]},{"p":"Są to narzędzia o niższej częstotliwości, ale ich dodawanie do zakładek nic nie kosztuje i rozwiązują konkretny problem: „Potrzebuję teraz losowo wyglądającej wartości i nie ufam sobie, że ją wymyślę”."},{"h":"Realistyczna przepustka edycyjna"},{"p":"Oto kolejność, która obowiązuje, gdy wersja robocza przychodzi od kogoś innego i musi zostać wysłana pod Twoim nazwiskiem."},{"l":["**1. Przytnij.** Najpierw przeprowadź cały dokument przez [[text-trimmer|Text Trimmer]]. Uszkodzenia spowodowane białymi znakami ukrywają się w akapitach, gdzie nigdy ich nie zobaczysz.","**2. Wyczyść wielkość liter.** Użyj [[konwerter wielkości liter tekstu|Konwerter wielkości liter]] tylko w przypadku nagłówka. Nigdy nie stosuj konwersji wielkości liter do pełnej wersji roboczej — niszczy to rzeczowniki własne.","**3. Zmierz.** Przed zapisaniem sprawdź długość za pomocą [[licznik słów|Licznik słów]], aby wiedzieć, jaki kształt ma mieć dana rzecz.","**4. Podgląd.** Jeśli zawiera Markdown, wyrenderuj go za pomocą [[markdown-preview|Markdown Preview]].","**5. Slug.** Wygeneruj fragment adresu URL na końcu, począwszy od końcowego nagłówka, za pomocą [[text-to-slug|Text to Slug]] — późniejsza zmiana nagłówka powoduje przerwanie działania komunikatu."]},{"p":"Całość zajmuje kilka minut i eliminuje kategorię błędu, w którym dokument jest technicznie poprawny i widocznie błędny."},{"h":"Pytania pisarzy dotyczące prywatności"},{"p":"**Czy mój niepublikowany tekst opuszcza mój komputer?** Nie. Te narzędzia przetwarzają tekst w Twojej przeglądarce i nic nie jest zapisywane ani przesyłane.\\n\\n**Czy istnieje limit długości?** Nie ma limitu po stronie serwera, ponieważ nie ma wywołania serwera. Niezwykle duże dane wejściowe są ograniczone przez pamięć Twojego urządzenia.\\n\\n**Czy mogę wykorzystać wynik komercyjnie?** Tak, bezpłatnie, bez podawania źródła.\\n\\n**Czy działają na telefonie?** Tak. Układ dostosowuje się i działa ten sam kod."},{"h":"Czego te narzędzia nie zrobią za Ciebie"},{"p":"Warto być szczerym w kwestii ograniczeń, ponieważ narzędzie, które zmechanizuje niewłaściwą rzecz, powoduje po prostu szybszy błąd.\\n\\nŻadne z tych narzędzi nie może powiedzieć, czy zdanie jest jasne, czy twierdzenie ma źródło lub czy ton jest odpowiedni dla odbiorców. Liczą znaki; nie oceniają prozy. Tekst, który osiąga doskonałe wyniki w każdym metryce na tej stronie, może nadal być nieczytelny.\\n\\nAni nie edytują. W momencie, gdy zaczniesz ręcznie przepisywać poszczególne klauzule na dużą skalę, wyrosłeś z narzędzia tekstowego i potrzebujesz albo odpowiedniego edytora, funkcji znajdowania i zamieniania z wyrażeniem regularnym — które [[regex-tester|Tester Regex]] jest naprawdę dobry do ćwiczeń — albo skryptu. Użyj przeglądarki dla warstwy mechanicznej i zachowaj własną ocenę wszystkiego, co znajduje się nad nią."},{"p":"Jeszcze jedną rzeczą, której nie zrobią, jest naprawienie złego źródła. Jeśli Twój arkusz kalkulacyjny jest pełen niespójnych nazw — „Dr”, „DR”, „Dr.” wszystko w jednej kolumnie — narzędzie posortuje i usunie duplikaty tego, co wiernie przekazałeś, a nadal będziesz mieć trzy wpisy tam, gdzie powinien być jeden. Czyszczenie danych to decyzja, a nie mechaniczny krok. Najpierw określ formę kanoniczną, następnie zastosuj ją, a następnie sprawdź."},{"h":"Utrzymywanie użytecznej listy roboczej"},{"p":"Jeśli utrzymujesz listę potencjalnych klientów, linków, referencji lub terminów, ulega ona cichej degradacji. Tryb awarii jest zawsze taki sam: wpisy, które wyglądają identycznie, takie nie są, a jedno połączenie niczego nie usuwa.\\n\\nKarnet konserwacyjny, który działa, jest nudny: przytnij białe znaki, ujednolić wielkość liter, usuń końcowe znaki interpunkcyjne, a następnie usuń duplikaty. W tej kolejności — przycięcie po usunięciu duplikatów powoduje utratę wpisów. Robienie tego raz w miesiącu na aktywnej liście zamienia dwugodzinny niemożliwy do naprawienia bałagan w dziesięciominutową uciążliwość.\\n\\nKiedy dwie listy wymagają uzgodnienia — powiedzmy lista rejestracyjna z listą obecności — posortuj najpierw obie listy za pomocą [[list-sorter|List Sorter]], tak aby były wyrównane, a następnie porównaj wzrokowo. Sortowanie obu stron przed porównaniem to różnica między dwuminutową kontrolą a dwudziestominutowym polowaniem."},{"h":"Jedzenie na wynos"},{"p":"Żadne z tych narzędzi nie jest sprytne. O to właśnie chodzi: usuwają mechaniczne pięć procent pisma, które nie jest pismem, więc pozostałe dziewięćdziesiąt pięć procent dotyczy w rzeczywistości zdań. Dodaj do zakładek te, których używasz co miesiąc, zignoruj ​​resztę i przestań ręcznie naprawiać białe znaki."}]},"calculators-and-converters-guide":{"title":"18 bezpłatnych kalkulatorów i konwerterów liczb, z którymi faktycznie masz do czynienia","description":"Procenty, rabaty, napiwki, pożyczki, daty, BMI i konwersje jednostek — bezpłatne kalkulatory przeglądarkowe, które pokazują ich uzasadnienie, bez konieczności zakładania konta.","category":"Kalkulatory","blocks":[{"p":"Każdy musi podzielić rachunek, sprawdzić, czy zniżka jest rzeczywiście zniżką i bez zastanowienia przeliczyć temperaturę lub rozmiar pliku. Każdy też, przynajmniej raz, popełnił błąd w miejscu publicznym.\\n\\nJest to zbiór osiemnastu kalkulatorów i konwerterów obejmujących pieniądze, daty, zdrowie i przeliczanie jednostek, które pojawiają się w pracy i podróżach. Wszystkie działają w przeglądarce: nic nie jest zapisywane, więc wpisywane liczby nie są niczyją sprawą, tylko Twoją."},{"h":"Obliczenia pieniędzy"},{"p":"Najbardziej powszechną matematyką w świecie rzeczywistym jest procent czegoś. Podatek od sprzedaży, napiwek, stos rabatowy, prowizja, stopa wzrostu. Wzór jest prosty, a jednak powód, dla którego ludzie się mylą, jest prawie zawsze taki sam: stosują procent do niewłaściwej podstawy."},{"l":["[[discount-calculator|Kalkulator rabatów]] — oblicz ostateczną cenę i, co ważniejsze, ile zaoszczędziłeś. Przydatne do wykrycia „50% zniżki”, która w rzeczywistości wynosi 20% po podwyższonej cenie katalogowej.","[[kalkulator napiwków|Kalkulator napiwków]] — podziel rachunek, wybierz procent, zaokrąglij na osobę, jeśli chcesz.","[[kalkulator pożyczki|Kalkulator pożyczki]] — miesięczna rata i całkowite odsetki, czyli liczba, która faktycznie decyduje o tym, czy pożyczka jest dostępna."]},{"b":"O rabatach: 20% rabatu, a następnie kolejne 20% rabatu nie jest 40% rabatem — jest to 36%. Kolejne procenty składają się na zredukowaną zasadę. Każdy kalkulator na tej liście potwierdzi to w ciągu około dwóch sekund i jest to najbardziej przydatny fakt arytmetyczny w tym artykule."},{"p":"Na osobną uwagę zasługuje kalkulator kredytowy. Liczbą nie jest tu miesięczna rata, lecz suma odsetek płaconych przez cały okres trwania pożyczki, bo to jest realny koszt pożyczki. Dwie pożyczki z identycznymi miesięcznymi ratami i różnymi warunkami mogą różnić się łącznym oprocentowaniem o dziesiątki tysięcy."},{"h":"Daty i odliczanie"},{"p":"W arytmetyce dat większość ludzi po cichu się myli, ponieważ ludzkie miesiące mają różną długość i odpowiedź zmienia się w zależności od tego, czy masz na myśli „miesiące kalendarzowe”, czy „30 dni”."},{"l":["[[różnica-daty|Kalkulator różnicy dat]] — dni (oraz łączna liczba miesięcy i lat) pomiędzy dwiema datami.","[[days-until|Days Until Calculator]] — odliczanie do konkretnej daty, przy czym liczba dni roboczych zwykle odpowiada tym, czego ludzie faktycznie chcą.","[[age-calculator|Age Calculator]] — dokładny wiek w latach i dniach plus kolejne urodziny.","[[timestamp-converter|Timestamp Converter]] — uniksowy znacznik czasu na rzeczywistą datę, która ma znaczenie, jeśli dotkniesz logów, baz danych lub odpowiedzi API."]},{"p":"Różnica, która zadziwia ludzi: liczba dni między 1 marca a 1 kwietnia wynosi 31, ale liczba *miesięcy* to jeden. Jeżeli obliczasz okres wypowiedzenia lub okres subskrypcji, napisz na piśmie, które urządzenie masz na myśli."},{"h":"Liczby zdrowotne, szczerze"},{"l":["[[bmi-calculator|Kalkulator BMI]] — wskaźnik masy ciała ze standardowymi kategoriami i zastrzeżeniami poniżej."]},{"p":"BMI to statystyka przesiewowa na poziomie populacji. Nie mówi nic o masie mięśniowej, składzie ciała ani zdrowiu jakiejkolwiek jednostki i jest kiepskim wskaźnikiem sprawności sportowców, osób starszych i różnych grup etnicznych. Użyj go jako jednego punktu danych spośród kilku lub jako sposobu śledzenia zmian w czasie – a nie jako werdyktu. Jeśli podejmujesz decyzje mające wpływ na Twoje zdrowie, właściwym narzędziem jest lekarz, a nie zakładka przeglądarki."},{"h":"Konwersja jednostek: te codzienne"},{"p":"Konwersja jednostek dzieli się na dwa rodzaje: konwersje, które należy wykonać dokładnie prawidłowo, oraz konwersje, których potrzebujesz w przybliżeniu. Narzędzia te obsługują jedno i drugie, a praca polega na zapamiętaniu, który jest który."},{"l":["[[przelicznik długości|Przelicznik długości]] — jednostki metryczne na jednostki imperialne i odwrotnie: milimetry, centymetry, metry, kilometry, cale, stopy, jardy, mile.","[[przelicznik wagi|Przelicznik wagi]] — gramy, kilogramy, uncje, funty, tony. Ten, który należy sprawdzić przed przepisem lub etykietą wysyłkową.","[[przelicznik temperatury|Przelicznik temperatury]] — stopnie Celsjusza, Fahrenheita, Kelwina. Ponieważ -10°C to nie 14°F, a wzór nie jest mnożeniem.","[[przelicznik prędkości|Przelicznik prędkości]] — km/h, mph, m/s, węzły. Przydatne w przypadku zagranicznego ograniczenia prędkości lub specyfikacji technicznych.","[[przelicznik powierzchni|Przelicznik powierzchni]] — metry kwadratowe, stopy kwadratowe, akry, hektary. Jest to wartość, którą ludzie źle oceniają przy zakupie lub wynajmie nieruchomości.","[[przelicznik objętości|Przelicznik objętości]] — litry, mililitry, galony, filiżanki, metry sześcienne.","[[przelicznik czasu|Przelicznik czasu]] — sekundy, minuty, godziny, dni, tygodnie."]},{"b":"Warto znać dwie pułapki konwersji: powyższą dotyczącą przechowywania danych (marketerzy sprzedają 10^3, systemy operacyjne zgłaszają 2^10) i zużycie paliwa — samochód, którego zużycie paliwa wynosi 40 mpg (imperyjne), jest bliższe 33 mpg (w USA) niż 40, ponieważ galon imperialny jest większy. Błędne wykonanie drugiego sprawia, że ​​wypożyczony samochód wygląda na nierealistycznie wydajny."},{"h":"Dwóch, których nie będziesz potrzebować"},{"l":["[[liczba-losowa|Generator liczb losowych]] — losowanie w określonym zakresie, w przypadku loterii, nawiasu lub szybkiego podziału A/B. Przydatne właśnie dlatego, że usuwa podejrzenia, że ​​to ty sfałszowałeś.","[[dice-roller|Dice Roller]] — dowolna kość od rzutu monetą do kostki dwudziestościennej, przeznaczona do gry planszowej lub sesji stołowej, podczas której prawdziwa kość stoczyła się ze stołu po raz ostatni."]},{"h":"Prawidłowe korzystanie z kalkulatora"},{"p":"Kalkulator pomaga tylko wtedy, gdy wiesz, o jaką liczbę pytasz. Trzy nawyki robią różnicę."},{"l":["** Najpierw zaokrąglij, oblicz drugą.** Jeśli dokładna liczba nie zmienia Twojej decyzji, użyj zaokrąglonej liczby. Procenty okrągłych liczb można sprawdzić w głowie, co wychwytuje błędy przy wprowadzaniu.","**Sprawdź wielkość.** Zanim uwierzysz w wynik, zapytaj, czy powinien być większy czy mniejszy od danych wejściowych i mniej więcej o ile. Większość błędów arytmetycznych przetrwa każde sprawdzenie z wyjątkiem tego.","**Fotografuj dane wejściowe, a nie wyniki.** Kiedy później ponownie uruchomisz obliczenia, liczy się to, co założyłeś, a nie jakie wnioski."]},{"h":"Pytania, które ludzie rzeczywiście zadają"},{"p":"**Czy moje numery są gdzieś przechowywane?** Nie. Obliczenia odbywają się w Twojej przeglądarce i nic nie jest przesyłane ani zachowywane.\\n\\n**Czy działają one na telefonie?** Tak, a kalkulatory są przystosowane do obsługi jedną ręką.\\n\\n**Jakiego standardu konwersji używasz do przechowywania danych?** Domyślnie dziesiętny (1 KB = 1000 bajtów), ponieważ w ten sposób sprzedawana jest pamięć. Systemy operacyjne zgłaszają dane binarne, dlatego dysk wydaje się kurczyć — narzędzie wyjaśnia różnicę, zamiast po cichu wybierać stronę.\\n\\n**Czy mogę osadzić je na mojej własnej stronie?** Nie. Zamiast tego dodaj je do zakładek; koszt tego wynosi zero, a problem z dokładnością należy do Ciebie."},{"h":"Procenty: cztery błędy, które mają znaczenie"},{"p":"Prawie każdy błąd procentowy, jaki ktoś popełnia w życiu codziennym, jest jednym z tych samych czterech błędów. Nazywanie ich sprawia, że ​​można ich uniknąć."},{"l":["**Zła podstawa.** „Wzrost o 10%, a następnie spadek o 10% pozostawiają Cię tam, gdzie zacząłeś” jest fałszywe, ponieważ oba odnoszą się do różnych podstaw. Dziesięć procent ze 100 to 10; dziesięć procent z 90 to 9.","**Procent procentowy.** Kumulowanie dwóch rabatów mnoży je (0,8 × 0,8 = 0,64, a więc 36% rabatu), a nie sumuje.","**Procenty w porównaniu do punktów procentowych.** Stopa przechodząca z 4% do 6% wzrosła o 2 punkty procentowe, ale w ujęciu względnym o 50%. Polityka i medycyna są pełne tego zamieszania i nie zawsze jest ono przypadkowe.","**Zbyt wczesne zaokrąglenie.** Zaokrąglenie kroku pośredniego przed zastosowaniem wartości procentowej zwiększa błąd. Zachowaj pełną precyzję aż do ostatniej cyfry, a ostatni krok wykonaj na kalkulatorze, a nie w głowie."]},{"p":"Jeśli z całej tej sekcji weźmiesz tylko jeden nawyk, weź ten: zanim zacytujesz komukolwiek wartość procentową, powtórz, jaki to jest procent *z*. Połowa argumentów, jakie kiedykolwiek będziesz mieć na temat liczby, to w rzeczywistości argumenty dotyczące mianownika."},{"h":"Wiedza, kiedy przestać kalkulować"},{"p":"W pewnym momencie precyzja przestaje się przydać. Znacząca jest miesięczna wpłata z dokładnością do dwóch miejsc po przecinku. Prognozowany całkowity koszt z dokładnością do ośmiu miejsc po przecinku pozwala uniknąć faktycznej decyzji, czyli tego, czy pożyczka mieści się w zakresie, na który możesz sobie pozwolić bez stresu.\\n\\nPrzydatnym testem jest pytanie o wrażliwość: czy decyzja ulegnie zmianie, jeśli wartość wejściowa zmieni się o 10%? Jeśli nie, przestań go udoskonalać i wykorzystaj dodatkowy czas na zmienną, która faktycznie przesuwa odpowiedź — zwykle jest to termin, a nie stawka lub cena katalogowa, a nie rabat."},{"p":"I jedną granicę warto jasno określić: te kalkulatory służą do arytmetyki, a nie doradztwa. Cel oszczędzania, data przejścia na emeryturę i plan spłaty zadłużenia to decyzje dotyczące ryzyka, zachowania i czasu, a karta przeglądarki nie może ważyć żadnej z nich. Może ci powiedzieć tylko, co oznaczają liczby, gdy już zdecydujesz, co zakładasz. To rozróżnienie jest różnicą pomiędzy przydatnością kalkulatora a jego odpowiedzialnością."},{"h":"Wersja jednoliniowa"},{"p":"Dodaj odpowiednio kalkulatory pieniędzy i dat do zakładek, traktuj BMI jako jeden sygnał, a nie werdykt, pamiętaj, że nałożone wartości procentowe się mnożą i sprawdzaj konwersję jednostek za każdym razem, gdy liczba ma jakąkolwiek wartość umowną. To obejmuje prawie wszystko."}]},"image-and-design-tools":{"title":"14 bezpłatnych narzędzi do tworzenia obrazów i projektowania, które działają w Twojej przeglądarce","description":"Kompresuj, zmieniaj rozmiar i przygotowuj obrazy oraz generuj efekty CSS, palety, kontrole kontrastu i ikony ulubionych bez instalowania programu Photoshop lub pakietu projektowego.","category":"Narzędzia projektowe","blocks":[{"p":"Praca wizerunkowa ma specyficzny problem: praca jest zwykle niewielka, a narzędzia, które oferuje, są ogromne. Musisz obciąć 400 KB obrazu bohatera, uzyskać wartość szesnastkową, o której wspomniał projektant, lub wygenerować favikonę, której nikt jeszcze nie stworzył. To nie wymaga subskrypcji.\\n\\nPoniższe czternaście narzędzi obejmuje przygotowywanie obrazów, pracę z kolorami, generowanie efektów CSS i drobne zasoby produkcyjne, które wypadają z luk. Każdy działa lokalnie, co ma większe znaczenie w przypadku obrazów niż tekstu: zdjęcie, które właśnie skompresowałeś, często jest zdjęciem, którego jeszcze nie opublikowałeś."},{"h":"Przygotowanie zdjęć do Internetu"},{"p":"Większość problemów z wizerunkiem to tak naprawdę problemy z wagą. Strona, która wydaje się powolna, zwykle zawiera obrazy większe niż rozmiar wyświetlacza, w złym formacie i przy ustawieniu jakości, którego nikt nigdy nie kwestionował."},{"l":["[[image-compressor|Image Compressor]] — zmniejsz rozmiar pliku, zachowując wizualnie nienaruszony obraz. Uruchom go przed przesłaniem czegokolwiek do formularza z limitem rozmiaru.","[[image-resizer|Image Resizer]] — ustaw potrzebne wymiary w pikselach. To jest większa wygrana: obraz o rozdzielczości 4000 pikseli wyświetlany w rozdzielczości 800 pikseli zawiera pięciokrotnie więcej potrzebnych danych.","[[image-to-base64|Obraz do Base64]] — przekonwertuj mały obraz na identyfikator URI danych w celu wstawienia go w CSS, HTML lub szablonie wiadomości e-mail."]},{"b":"Kolejność ma znaczenie. Najpierw zmień rozmiar, a następnie skompresuj. Kompresja obrazu o rozdzielczości 4000 pikseli tworzy znacznie cięższy plik niż zmiana rozmiaru do 800 pikseli, a następnie kompresja z tą samą jakością, ponieważ kompresory poświęcają swój wysiłek na piksele, które i tak zostałyby wyrzucone."},{"p":"Jak bardzo należy kompresować? Szczera odpowiedź brzmi: dopóki nie będzie wyglądać źle, wtedy cofnij się o krok. W przypadku fotograficznego obrazu bohatera jakość od 70 do 80 procent jest zwykle nie do odróżnienia od oryginału przy normalnym rozmiarze oglądania. W przypadku logo, zrzutu ekranu lub czegokolwiek o płaskich kolorach i ostrych krawędziach użyj formatu PNG i skompresuj mocniej — zyskują one więcej i mniej tracą."},{"p":"Praktyczna zasada: wszystko poniżej 200 KB jest w porządku dla obrazu głównego, poniżej 80 KB dla miniatury, a jeśli nie możesz zejść poniżej 300 KB, prawdopodobnie masz problem z wymiarami, a nie z jakością."},{"h":"Base64: kiedy wstawianie jest właściwym rozwiązaniem"},{"p":"Konwersja obrazu na identyfikator URI danych Base64 usuwa żądanie HTTP, co brzmi jak czysta wygrana. Zwykle tak nie jest. Zakodowany ciąg jest mniej więcej o jedną trzecią większy niż plik binarny, nie można go oddzielnie buforować i powoduje to rozdęcie kodu CSS lub HTML.\\n\\nWstawiany tylko wtedy, gdy obraz jest mały — poniżej kilku kilobajtów — używany tylko raz i krytyczny. Klasycznym przypadkiem jest mała ikona w pojedynczym szablonie wiadomości e-mail. W przypadku czegokolwiek, co powtarza się na stronach lub jest większe niż kilka kilobajtów, podaj to jako plik i pozwól przeglądarce buforować."},{"h":"Znaki wodne: to, co naprawdę można usunąć"},{"l":[]},{"p":"Wyjaśnij jasno, do czego to służy. Usuwa lub zakrywa widoczny znak. Nie może zrekonstruować leżących pod spodem pikseli — zamalowana informacja zniknęła i żaden filtr nie odtwarza jej ponownie. Wyniki mogą być niewidoczne, gdy znak znajduje się na gładkim tle, lub widoczne rozmazanie, gdy znak znajduje się na szczegółach.\\n\\nJeszcze jedną rzecz warto powiedzieć wyraźnie: usunięcie cudzego znaku wodnego i opublikowanie wyniku jest problemem związanym z prawami autorskimi w większości jurysdykcji i naruszeniem licencji, niezależnie od tego, czy zostaniesz złapany. To narzędzie służy do usuwania śladów z własnych obrazów lub z zasobów, na które posiadasz licencję."},{"h":"Kolor: konwertowanie, sprawdzanie, wybieranie"},{"p":"Kolor to miejsce, w którym małe błędy stają się bardzo widoczne. Współczynnik kontrastu, który zawodzi przy dostępności, wartość szesnastkowa, która w rzeczywistości jest potrójną wartością HSL, paleta, która wygląda spójnie na monitorze i zabłocona na projektorze."},{"l":["[[color-converter|Color Converter]] — poruszaj się pomiędzy HEX, RGB i HSL. HSL warto nauczyć się czytać, ponieważ odcień 210, nasycenie 40 procent, jasność 50 procent jest znacznie łatwiejszy do dostosowania ręcznie niż wartość szesnastkowa.","[[contrast-checker|Contrast Checker]] — przetestuj tekst na tle pod kątem progów WCAG. Jest to najbardziej przydatne narzędzie opisane w tym artykule, ponieważ pozwala wykryć rzeczywisty problem związany z przestrzeganiem przepisów, a nie problem ze smakiem.","[[color-palette|Generator palet kolorów]] — wygeneruj spójny zestaw, gdy zaczynasz od koloru firmowego i potrzebujesz reszty skali."]},{"b":"Dla kontrastu: WCAG AA wymaga wartości 4,5 do 1 w przypadku normalnego tekstu podstawowego i 3 do 1 w przypadku dużego tekstu. Jeśli wybierasz pomiędzy dwoma markowymi kolorami przycisku, dostępny zazwyczaj nie jest tym, który podoba się projektantowi. Najpierw sprawdź, a potem dyskutuj z danymi."},{"p":"Jedno zastrzeżenie dotyczące narzędzi do kolorowania: wszystkie zakładają, że monitor jest skalibrowany i że osoba przeglądająca Twoją stronę ma sprawne oczy. Żadne założenie nie jest bezpieczne. To powód, dla którego wolimy kombinacje sprawdzone kontrastem od subiektywnych."},{"h":"Efekty CSS bez otwierania narzędzia do projektowania"},{"p":"Ręczne pisanie gradientu lub cienia warstwowego jest naprawdę nieprzyjemnym zadaniem. Składnia jest skomplikowana, nie widać, co tworzysz, a różnica między dobrym cieniem a złym to kilka pikseli rozmycia."},{"l":["[[gradient-generator|Generator gradientów CSS]] — twórz gradienty liniowe i radialne oraz bezpośrednio kopiuj CSS.","[[box-shadow-generator|Box Shadow Generator]] — nałóż wiele cieni na siebie, co odróżnia subtelne wzniesienie od ciężkiego upadku.","[[border-radius-generator|Border Radius Generator]] — uzyskaj asymetryczne promienie, które sprawiają, że kształt wygląda na zamierzony.","[[generator cienia tekstu|Generator cienia tekstu]] — przydatne oszczędnie. Większość cieni tekstowych jest zbyt mocna; pozwala to dostosować przesunięcie i rozmycie, aż zniknie."]},{"p":"Sztuką dla całej czwórki jest powściągliwość. Dwa cienie – ciasny, ciemny i szeroki, miękki – odczytywane są jako fizyczne uniesienie. Jeden cień brzmi jak strona internetowa sprzed piętnastu lat. Generuj, kopiuj, a następnie usuwaj, aż nie będziesz mógł stwierdzić, że tam jest."},{"h":"Aktywa produkcyjne, o których wszyscy zapominają"},{"l":["[[favicon-generator|Favicon Generator]] — utwórz mały zestaw ikon, którego witryna faktycznie potrzebuje. Znajduje się to na liście, ponieważ favicony to zasób, którego najprawdopodobniej całkowicie brakuje, a brakująca ikona wyświetla ogólną ikonę strony przeglądarki, która sprawia, że ​​ukończona witryna wygląda na niedokończoną.","[[emoji-picker|Emoji Picker]] — przeglądaj, wyszukuj i kopiuj emoji bez konieczności przechodzenia przez selektor systemu operacyjnego. Naprawdę przydatne, gdy piszesz kopię, która potrzebuje jednego określonego symbolu."]},{"h":"Sprawdzony przykład: wysyłka sekcji bohatera"},{"p":"Oto cała gromada wykonująca jedną prawdziwą pracę. Strona potrzebuje bohatera z obrazem tła, nagłówkiem i przyciskiem, a żaden z nich nie został jeszcze zbudowany."},{"l":["**1. Zarezerwuj miejsce.** Nadaj szczelinie obrazu stałą wysokość w układzie, aby strona miała odpowiedni kształt od pierwszego renderowania, zamiast skakać po wylądowaniu prawdziwego obrazu.","**2. Zmień rozmiar i skompresuj.** Kiedy pojawi się prawdziwe zdjęcie, przepuść je przez [[image-resizer|Image Resizer]] przy szerokości 1600 pikseli, a następnie [[image-compressor|Image Compressor]] przy 75 procentach. To jest plik, który możesz wysłać.","**3. Sprawdź kontrast tekstu.** Nagłówek nad zdjęciem to klasyczny błąd kontrastu. Użyj [[contrast-checker|Kontrast Checker]], aby wybrać moc ciemnej nakładki lub jasny kolor tekstu, który spełnia wymagania AA.","**4. Zbuduj przycisk.** [[box-shadow-generator|Box Shadow Generator]] podaje wysokość, a [[color-converter|Color Converter]] ustawia kolor marki w formacie wymaganym przez CSS.","**5. Ship.** Dodaj favikonę z [[favicon-generator|Favicon Generator]], aby zakładka nie wyglądała na opuszczoną, a sekcja jest gotowa."]},{"p":"Pięć narzędzi, brak pakietu projektowego, a każdy wynik to wartość, którą możesz wkleić bezpośrednio do kodu."},{"h":"Często zadawane pytania"},{"p":"**Czy moje obrazy są gdziekolwiek przesyłane?** Nie. Kompresja, zmiana rozmiaru i konwersja Base64 odbywają się w Twojej przeglądarce i dlatego nie ma limitu rozmiaru pliku ani kolejki przesyłania.\\n\\n**Czy kompresja obrazu spowoduje utratę jakości?** Z definicji zawsze. Pytanie czy to widać. Przy jakości wynoszącej 70–80 procent i prawidłowych wymiarach zwykle tak nie jest.\\n\\n**Dlaczego mój obraz o zmienionym rozmiarze nadal wygląda na duży?** W dziewięciu przypadkach na dziesięć kompresowałeś przed zmianą rozmiaru lub zapisałeś jako PNG, gdy zdjęcie jest lepsze w formacie JPEG.\\n\\n**Czy mogę ich używać do pracy z klientem?** Tak, bez podawania źródła i bez ograniczeń komercyjnych.\\n\\n**Czy działają na telefonie?** Tak, chociaż zmiana rozmiaru i kompresja dużych zdjęć na telefonie zależy od pamięci urządzenia, a nie serwera."},{"h":"Wersja jednoliniowa"},{"p":"Zmień rozmiar przed kompresją, sprawdź kontrast, zanim zaczniesz spierać się o kolor, staraj się zachować subtelne cienie i nigdy nie zapominaj o favikonie. W każdym razie to właśnie większość tego, co zrobił dla ciebie pakiet projektowy."}]},"math-tools-for-real-numbers":{"title":"6 bezpłatnych narzędzi matematycznych do obliczania liczb, które nie będą działać","description":"Notacja naukowa, ułamki dziesiętne, sprawdzanie liczb pierwszych, silnie i GCF/LCM — bezpłatne narzędzia przeglądarkowe do obliczania liczb, w których łatwo się pomylić.","category":"Narzędzia matematyczne","blocks":[{"p":"Matematyka, której faktycznie potrzebujesz na komputerze, nie jest matematyką, z której byłeś sprawdzany. Jest to: czy ta liczba ma format oczekiwany przez system, czy ten ułamek jest uproszczony, jak szybko rośnie i dlaczego kalkulator i arkusz kalkulacyjny się nie zgadzają.\\n\\nTe sześć narzędzi obejmuje ten obszar. Działają lokalnie, co dla arytmetyki oznacza jedną konkretną korzyść, którą warto wymienić: wpisany numer nie jest nigdzie wysyłany, dzięki czemu możesz bez namysłu sprawdzić wyliczenie dotyczące wynagrodzenia, salda czy liczby klientów."},{"h":"Przekazywanie liczb do postaci akceptowanej przez maszynę"},{"p":"Komputery przechowują ułamki dziesiętne jako ułamki binarne. Wartość 0,1 nie jest dokładnie przedstawiana w formacie binarnym — najbliższa wartość podwójnej precyzji to 0,1000000000000000055511151231257827. Dodaj 0,1 + 0,2, a otrzymasz 0,30000000000000004, które domyślnie wyświetla wartość 0,3 i po cichu przerywa sprawdzanie równości."},{"l":["[[scientific-notation|Konwerter notacji naukowej]] — przechodź między formą standardową a naukową, w ten sposób większość dzienników, arkuszy kalkulacyjnych i interfejsów API faktycznie przechowuje duże i małe liczby.","[[decimal-fraction|Decimal to Fraction]] — zamień ułamek dziesiętny na ułamek dokładny. Oto rozwiązanie powyższego problemu: 0,1 + 0,2 w arytmetyce ułamków dokładnych to 3/10, a nie przybliżenie."]},{"b":"Jeśli kiedykolwiek widziałeś sumę błędną o 0,000000000000004, oto dlaczego. W kodzie finansowym standardową odpowiedzią jest praca w centach całkowitych lub w bibliotece dziesiętnej, a nigdy w liczbach zmiennoprzecinkowych. Jeśli kiedykolwiek widziałeś, że arkusz kalkulacyjny nie zgadza się ze skryptem choćby o ułamek grosza, jest to ten sam błąd w innym kapeluszu."},{"p":"Warto biegle posługiwać się notacją naukową, bo to różnica pomiędzy czytaniem linii logarytmicznej a mrużeniem na nią oczu. 6,022e23, 1,6e-19 i 3e8 to liczba Avogadra, ładunek elementarny i prędkość światła. Jeśli wyglądają one jak szum, a nie liczby, konwersja kilku za pomocą narzędzia naprawi problem na stałe."},{"h":"Liczby pierwsze i dlaczego kogokolwiek to obchodzi"},{"l":["[[prime-checker|Sprawdzanie liczb pierwszych]] — sprawdza, czy liczba jest pierwsza i sprawdza jej rozkład na czynniki, jeśli nie jest.","[[gcf-calculator|GCF LCM Calculator]] — największy wspólny dzielnik i najmniejsza wspólna wielokrotność."]},{"p":"Liczby pierwsze nie są ćwiczeniem szkolnym. Bezpieczeństwo każdego połączenia HTTPS zależy od tego, że pomnożenie dwóch dużych liczb pierwszych jest łatwe, a rozłożenie wyniku na czynniki trudne. Ta asymetria jest podstawą RSA.\\n\\nNa co dzień sprawdzanie liczb pierwszych dotyczy głównie ułamków. Uproszczenie ułamka oznacza podzielenie góry i dołu przez ich największy wspólny dzielnik, a nie można tego znaleźć bez rozkładu na czynniki. Dlatego te dwa narzędzia są ze sobą powiązane: sprawdź czynniki, a następnie uzyskaj GCF i LCM w jednym kroku."},{"p":"O połowie LCM ludzie zapominają i to ona rozwiązuje problemy z harmonogramem: dwa wydarzenia powtarzające się co 18 dni i co 12 dni pokrywają się co 36 dni. Ta sama arytmetyka, inne zastosowanie."},{"h":"Silnie i prędkość, z jaką eksplodują"},{"l":["[[kalkulator silni|Kalkulator silni]] — n! dla wartości, w przypadku których odpowiedź jest nadal znacząca."]},{"p":"Silnie rosną szybciej niż prawie wszystko, co spotykasz przy biurku. 10! wynosi około 3,6 miliona. 20! wynosi około 2,4 kwintyliona – znacznie więcej niż liczba ziaren piasku na Ziemi. 52!, liczba sposobów przetasowania talii kart, wynosi w przybliżeniu 8, po których następuje 67 cyfr.\\n\\nPraktyczną konsekwencją jest to, że program wyliczający wszystkie permutacje jest w porządku przy 5 elementach, tolerowany przy 8 i trwale utknięty przy 12. Jeśli wydaje Ci się, że zadanie nigdy się nie zakończy, a Ty krążysz po permutacjach, prawie na pewno jest to powód. Jest to także argument przeciwko większości podejść opartych na brutalnej sile, określanych raczej jako arytmetyka niż opinia."},{"h":"Cyfry rzymskie i dziwna rzecz z nimi"},{"l":["[[roman-cymbers|Przelicznik cyfr rzymskich]] — konwertuj na i z cyfr rzymskich."]},{"p":"Cyfry rzymskie warto zrozumieć, a nie tylko przeliczać, ponieważ system ujawnia coś na temat notacji pozycyjnej. Nie ma zera ani wartości miejsca: XI oznacza jedenaście, niezależnie od tego, czy reprezentuje jedenaście drążków, czy jedenaście tysięcy. Właśnie dlatego arytmetyka cyfr rzymskich jest naprawdę trudna i dlatego system ten przetrwał stulecia, głównie do liczenia i datowania, a nie do obliczeń.\\n\\nZasada odejmowania to ta część, w której ludzie się mylą. IV to cztery, nie VI; IX to dziewięć. Zegary są słynnym wyjątkiem – Big Ben używa raczej IIII niż IV, z powodów, o których historycy wciąż się spierają. Konwersja zamiast wyprowadzania jest właściwym rozwiązaniem w każdym przypadku."},{"h":"Sprawdzony przykład: ręczne sprawdzanie ułamka"},{"p":"Przepis wymaga 0,375 filiżanki i skali w gramach, raport podaje stosunek 0,625, a oba wyglądają jak liczby wpisane przez kogoś w pośpiechu."},{"l":["**1. Znajdź dokładny ułamek.** Przeprowadź 0,375 za pomocą narzędzia [[decimal-fraction|Decimal to Fraction]]: 3/8. Uruchom 0,625: 5/8. Nie potrzebowałeś nawyku kalkulatora, którego nie masz.","**2. Uprość stosunek.** Aby wyrazić 3/8 w stosunku do 5/8, potrzebujesz GCF wynoszącego 3 i 5. [[gcf-calculator|GCF LCM Calculator]] daje 1, więc stosunek wynosi 3:5 i jest już najprostszy.","**3. Sprawdź twierdzenie silni.** Jeśli ktoś powie Ci, że kolejka złożona z 9 zamówień ma 362 880 ustaleń, [[kalkulator silni|Kalkulator silni]] potwierdzi 9! to jest dokładnie to. Teraz już wiesz, czy szacunkowy czas budowy był wiarygodny.","**4. Normalizuj wszystko, co jest duże.** Serwer zgłaszający 1,5e9 nanosekund to 1,5 sekundy według [[scientific-notation|Scientific Notation Converter]] — co stanowi różnicę między problemem opóźnienia a artefaktem zaokrąglania."]},{"h":"Czego te narzędzia celowo nie robią"},{"p":"Nie pokazują pracy i nie uczą. Jeśli chcesz zrozumieć, dlaczego formuła jest prawdziwa, kalkulator jest niewłaściwym narzędziem — podaje odpowiedź bez powodu, w związku z czym ludzie potrafią liczyć, ale nie potrafią rozumować.\\n\\nNie wykonują też dowolnej precyzji. Silnie i duże rozkłady na czynniki stracą dokładność po osiągnięciu punktu, w którym odpowiedź jest nadal użyteczna, a karta przeglądarki nie jest systemem algebry komputerowej. We wszystkim, gdzie naprawdę liczy się poprawność — w inżynierii, finansach, kryptografii — używaj odpowiedniej biblioteki z dokładną arytmetyką, a nie strony internetowej."},{"h":"Sprawdzanie własnej arytmetyki"},{"p":"Najcenniejszym nawykiem matematycznym nie jest szybkość, lecz szacowanie. Zanim uwierzysz w jakikolwiek wynik, zapytaj, czy jest to właściwy rząd wielkości: większy czy mniejszy od danych wejściowych i mniej więcej o ile. Większość błędów arytmetycznych przetrwa każde inne sprawdzenie z wyjątkiem tego.\\n\\nZaokrąglenie w pierwszej kolejności sprawia, że ​​oszacowanie jest bezpłatne. Zaokrąglij 0,375 do 0,4, zaokrąglij 5/8 do 0,6, a stosunek wynosi oczywiście około 2:3 — wystarczająco blisko 3:5, aby potwierdzić dokładnie obliczony ułamek. Jeśli dokładna odpowiedź i oszacowanie nie zgadzają się, zamiast problemu z zaokrągleniem znalazłeś błąd wejściowy, i znalazłeś go w ciągu kilku sekund.\\n\\nZ tego też powodu kalkulator nie zastępuje myślenia o tym, o co go zapytałeś. Narzędzie doskonale obliczy nieprawidłową wielkość, a jedyną obroną jest wiedza, jak powinna wyglądać odpowiedź."},{"h":"Często zadawane pytania"},{"p":"**Czy moje dane wejściowe są gdziekolwiek wysyłane?** Nie. Wszystkie działają lokalnie w Twojej przeglądarce.\\n\\n**Dlaczego 0,1 plus 0,2 nie równa się 0,3?** Ponieważ ani 0,1, ani 0,2 nie są dokładnie reprezentowalne w binarnej liczbie zmiennoprzecinkowej. Suma wynosi 0,30000000000000004, co jest wartością podwójną najbliższą 0,3.\\n\\n**Jak dużą silnię mogą one obsłużyć?** Do 170 przed przekroczeniem zakresu podwójnego. Po tym czasie odpowiedź jest wyświetlana w notacji naukowej i przestaje mieć znaczenie.\\n\\n**Czy mogę użyć wyniku w kodzie?** Tak. W szczególności w przypadku wyników z ułamka dziesiętnego na ułamek należy stosować arytmetykę liczb całkowitych w liczniku i mianowniku, zamiast konwertować z powrotem na liczbę dziesiętną."},{"h":"Wersja jednoliniowa"},{"p":"Używaj ułamków dokładnych, gdy w grę wchodzą pieniądze, pamiętaj, że silnie eksplodują szybciej, niż się spodziewasz, a rozkład na czynniki pierwsze jest zarówno podstawą bezpieczeństwa, jak i sztuczką upraszczającą ułamki."}]},"everyday-utility-tools":{"title":"13 bezpłatnych narzędzi codziennego użytku: hasła, kody QR, liczniki czasu i kodowanie tekstu","description":"Generuj hasła, twórz kody QR, uruchamiaj liczniki czasu i zegary oraz dekoduj tekst binarny, szesnastkowy i szyfrowany — a wszystko to za pomocą bezpłatnych narzędzi przeglądarkowych, które działają lokalnie i nie wymagają konta.","category":"Narzędzia użytkowe","blocks":[{"p":"Ta ostatnia grupa to szuflada na śmieci. Hasła, kody QR, stoper, zegar światowy, rzut monetą i cztery narzędzia, które przekształcają tekst w inne reprezentacje samego siebie. Pojedynczo drobnostki, razem rzeczy potrzebne w niezręcznych chwilach.\\n\\nLinia przelotowa jest taka, że ​​wszystkie trzynaście działa lokalnie. W przypadku generatora haseł nie jest to drobiazg — to jedyny powód, dla którego w ogóle można ufać temu narzędziu."},{"h":"Hasła: część, która faktycznie ma znaczenie"},{"l":["[[generator haseł|Generator haseł]] — generuj silne, losowe hasła o dowolnej długości i zestawie znaków.","[[password-strength|Kontrola siły hasła]] — lokalnie oszacuj, jak odporne jest hasło na odgadnięcie."]},{"b":"Najważniejszy fakt na temat siły hasła: **długość przewyższa złożoność, a ponowne użycie przewyższa jedno i drugie jako niebezpieczeństwo.** 16-znakowe hasło składające się z niepowiązanych ze sobą słów jest silniejsze i znacznie łatwiejsze do wpisania niż 10-znakowy bałagan symboli. Tymczasem jedno ponownie użyte hasło, które pojawia się w wyniku naruszenia, powoduje jednoczesne usunięcie wszystkich kont, których dotknie. Wygenerowanie odrębnego, długiego hasła dla każdej witryny to całe zadanie."},{"p":"Sposób szacowania siły również ma znaczenie. Większość warcabów przybliża rozmiar przestrzeni wyszukiwania, co jest rozsądnym przybliżeniem, ale nie jest prawdą: „CorrectHorseBatteryStaple” wypada dobrze pod względem entropii, podczas gdy „P@ssw0rd1!” wypada dobrze pod względem różnorodności znaków i źle w praktyce, ponieważ pojawia się na każdej pękającej liście słów na świecie.\\n\\nUżyj generatora do wszystkiego, na czym Ci zależy, a jeśli musisz zapamiętać hasło, użyj hasła składającego się z czterech lub pięciu niepowiązanych ze sobą słów. Jest to specyficzny przypadek, w którym zapamiętywalność i siła faktycznie się pokrywają."},{"h":"Kody QR: co w nich umieścić"},{"l":["[[qr-code-generator|Generator kodów QR]] — wygeneruj kod QR dla adresu URL, tekstu, szczegółów Wi-Fi lub danych kontaktowych."]},{"p":"Kody QR to jedno z tych narzędzi, w przypadku których o jakości wydruku decyduje wyłącznie jedna decyzja: ilość wprowadzonych danych. Krótki adres URL jest kodowany w mały, łatwy do zeskanowania kod. Akapit tekstu ze znakami interpunkcyjnymi koduje się w coś gęstego i zawodnego przy małych rozmiarach.\\n\\nDwie praktyczne zasady. Po pierwsze, przed wydrukowaniem dwustu kodów zawsze przetestuj kod w rozmiarze, w jakim faktycznie zostanie wydrukowany. Po drugie, Wi-Fi i zwykłe kody URL zachowują się inaczej na różnych telefonach — jeśli kod jest kierowany do mieszanej grupy odbiorców, lepiej wybrać zwykły adres URL niż stronę docelową zawierającą linki prowadzące dalej, ponieważ działa wszędzie i możesz zmienić miejsce, w którym wskazuje."},{"h":"Czas: timery, zegary i pułapka w strefach czasowych"},{"l":["[[stoper|Stoper online]] — zwykły stoper, przydatny, gdy telefon znajduje się w drugim pokoju.","[[pomodoro-timer|Pomodoro Timer]] — 25-minutowe bloki skupienia z przerwami, dla osób, które uważają, że ta struktura działa.","[[Zegar światowy|Zegar światowy]] — aktualny czas w kilku miastach jednocześnie."]},{"p":"Zegar światowy zasługuje na swoje miejsce z jednego konkretnego powodu: czasu letniego. Połowa światowych błędów w harmonogramie nie jest błędami arytmetycznymi, ale momentem, w którym dwa miasta dzieliły cztery godziny w zeszłym tygodniu i pięć godzin w tym tygodniu, a nikt tego nie sprawdził.\\n\\nZanim zaplanujesz cokolwiek w danej strefie czasowej, umieść oba miasta na zegarze światowym i spójrz – nie obliczaj przesunięcia z pamięci. Z tego też powodu zaproszenia na spotkania powinny zawierać strefę czasową, a nie godzinę."},{"p":"Na zegarze Pomodoro: technika ta sprawdza się w przypadku określonego rodzaju zadania — ograniczonego, skupionego i nieprzerwanego. Nie działa to w przypadku debugowania, gdzie prawidłowym ruchem w przypadku utknięcia jest odejście, a nie rozpoczynanie kolejnego 25-minutowego bloku. Używaj go, gdy pomaga."},{"h":"Losowość, szczerze"},{"p":"[[random-number|Generator liczb losowych]] i [[list-randomizer|List Randomizer]] obejmują przypadki, które faktycznie się pojawiają: wybranie liczby z zakresu i uporządkowanie listy. Warte wyroku za sprawiedliwość. Obydwa korzystają z generatora pseudolosowego, którego decydowanie o tym, kto zapłaci za lunch, jest nie do odróżnienia od prawdziwej monety. Do czegokolwiek istotnego – losowania z nagrodami, przydziału pieniędzy – potrzebujesz źródła, które możesz sprawdzić, a karta przeglądarki to nie to. Wartością jest tutaj usunięcie człowieka, który źle wybiera, gdy jest zmotywowany."},{"h":"Szuflada na śmieci kodujące"},{"p":"Cztery narzędzia przenoszące tekst pomiędzy reprezentacjami. Żadne z nich nie jest szyfrowane, a rozróżnienie jest warte podkreślenia, ponieważ jest stale mylone: ​​kodowanie jest odwracalne przez każdego i nie ma klucza. Szyfrowanie wymaga klucza."},{"l":["[[binary-text|Binarny na tekst]] — konwertuje pomiędzy tekstem a jego reprezentacją binarną.","[[hex-text|Hex to Text]] — konwertuj pomiędzy tekstem i szesnastkowo, reprezentację, którą widzisz najczęściej w narzędziach sieciowych i debugerach.","[[szyfr-cezara|szyfr Cezara]] — przesuwaj litery o ustaloną wartość, klasyczny szyfr szkolny.","[[rot13-encoder|ROT13 Encoder]] — obróć litery o 13, specjalny przypadek, który jest ich własną odwrotnością."]},{"p":"Przydają się one dokładnie do dwóch rzeczy. Po pierwsze, zrozumienie, w jaki sposób tekst staje się bajtami, czyli model mentalny, którego potrzebujesz, gdy cokolwiek wygląda na zniekształcone. Po drugie, właściwie debugowanie: kiedy ładunek pojawia się w postaci szesnastkowej, konwerter [[hex-text|Hex to Text]] pozwala dowiedzieć się, co jest w nim napisane.\\n\\nNie nadają się do ukrywania czegokolwiek. ROT13 nie ma klucza — zmiana jest publiczna — więc niczego nie ukrywa przed kimkolwiek, kto wie, czym jest ROT13. Szyfr Cezara ma 25 możliwych przesunięć, które człowiek łamie w ciągu pierwszej minuty."},{"h":"Dwie, które formatują rzeczy"},{"l":["[[phone-formatter|Phone Number Formatter]] — normalizuj numery telefonów do spójnego formatu.","[[file-size-converter|Konwerter rozmiaru pliku]] — konwertuje pomiędzy KB, MB, GB i TB, z wyjaśnieniem rozróżnienia na liczbę dziesiętną i binarną."]},{"p":"Konwerter rozmiaru pliku ma jeden naprawdę cenny wynik: informuje, dlaczego dysk ogłasza większą liczbę niż raportuje komputer. Sprzedawcy sprzedają w potęgach dziesięciu, systemy operacyjne podają potęgi dwójki, a różnica wynosi około 7 procent w każdej skali. To nie jest wina, to są dwie konwencje."},{"h":"Sprawdzony przykład: zniekształcona odpowiedź API"},{"p":"Element webhook nie przechodzi weryfikacji i ładunek w dzienniku wygląda jak `\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f`. To jest diagnoza dziewięćdziesiąta druga."},{"l":["**1. Konwertuj.** Wklej `48656c6c6f` do konwertera [[hex-text|Hex to Text]] — wynikiem będzie `Hello`. To nigdy nie było zniekształcone, tylko zakodowane.","**2. Sprawdź kształt.** Coś wcześniej koduje szesnastkowo ładunek przed podpisaniem. Podpis został obliczony na podstawie oryginalnego tekstu i zweryfikowany względem wartości szesnastkowej, więc porównanie kończy się niepowodzeniem.","**3. Wyklucz drugi kierunek.** Gdyby w logu był czytelny tekst, problem byłby odwrotny: podpisanie zakodowanego formularza.","**4. Potwierdź żądanie rozmiaru.** Jeśli ten sam dziennik zgłasza ładunek o wielkości 1,2 MB, [[konwerter rozmiaru pliku | Konwerter rozmiaru pliku]] sprawdza, czy jest to zapis dziesiętny czy binarny, zanim ktokolwiek zacznie spierać się o limit."]},{"h":"Często zadawane pytania"},{"p":"**Czy generator haseł jest bezpieczny, jeśli wszystko działa w przeglądarce?** Tak, i to bardziej niż ten oparty na serwerze: hasło jest generowane na Twoim komputerze i nigdy nie jest przesyłane, więc nie ma czego przechwytywać, rejestrować ani naruszać. Wadą jest to, że nie można odzyskać hasła, którego nie zapisano.\\n\\n**Czy mogę zaufać wirtualnemu rzutowi monetą?** W przypadku przypadkowych decyzji tak. W przypadku czegokolwiek, co wiąże się z pieniędzmi lub nagrodami, skorzystaj ze źródła, które możesz sprawdzić.\\n\\n**Czy szyfry są bezpieczne?** Nie. Żaden z nich. Szyfry ROT13 i Cezara nie mają tajnego klucza i istnieją po to, aby uczyć kodowania, a nie chronić cokolwiek.\\n\\n**Czy działają one w trybie offline?** Po załadowaniu strony tak – wszystko jest lokalne.\\n\\n**Czy istnieje ograniczenie długości tekstu dla konwerterów?** Tylko pamięć Twojego urządzenia, ponieważ nic nie jest nigdzie wysyłane."},{"h":"Wersja jednoliniowa"},{"p":"Długie, unikalne hasła są lepsze od krótkich, sprytnych, kod QR jest tak dobry, jak zawarte w nim dane, sprawdzaj przesunięcia stref czasowych, a nie je obliczaj, a kodowanie nie jest szyfrowaniem."}]}}')},62654,(e,a,n)=>{a.exports=JSON.parse('{"browser-tools-for-developers":{"title":"Bộ công cụ dành cho nhà phát triển: 24 công cụ trình duyệt miễn phí thay thế ứng dụng trả phí","description":"Hướng dẫn thực tế về định dạng, chuyển đổi, mã hóa và gỡ lỗi dữ liệu bằng cách sử dụng các công cụ dành cho nhà phát triển dựa trên trình duyệt miễn phí — không cần cài đặt, không cần tài khoản; hầu hết các công cụ xử lý đầu vào cục bộ.","category":"Công cụ dành cho nhà phát triển","blocks":[{"p":"Hầu hết các công việc nhỏ bạn thực hiện hàng trăm lần một tuần — định dạng lại phản hồi API, giải mã mã thông báo, kiểm tra hàm băm, thụt lề một đoạn SQL — không cần IDE, đăng ký trả phí hoặc giấy phép nhóm. Họ cần mở một tab trong 90 giây.\\n\\nBộ sưu tập bên dưới là 24 tiện ích dựa trên trình duyệt bao gồm định dạng, chuyển đổi, mã hóa, băm và gỡ lỗi. Mỗi một trong số chúng chạy hoàn toàn trên trang của bạn: dữ liệu của bạn không bao giờ được gửi đến máy chủ, điều này quan trọng hơn những gì các nhà phát triển thường thừa nhận, vì tải trọng bạn dán thường là của khách hàng."},{"h":"Những công cụ dựa trên trình duyệt nào có thể và không thể thay thế"},{"p":"Hãy thực tế về ranh giới. Những công cụ này thay thế các công việc làm một lần, ít rủi ro, tần suất cao. Chúng không thay thế máy chủ ngôn ngữ, trình gỡ lỗi, bộ thử nghiệm của bạn hay bất cứ thứ gì bạn cần để chạy nhiều lần trong môi trường thực."},{"l":["**Rất phù hợp:** đọc phản hồi một lần, gỡ lỗi một giá trị, chuyển đổi tệp cho một lần nhập, kiểm tra định dạng trước khi gửi.","**Không phù hợp:** chạy cùng một quy trình kiểm tra trên mỗi lần triển khai, chuyển đổi hàng trăm tệp, bất kỳ thứ gì chắc chắn bị lỗi trong CI.","**Không bao giờ:** bất cứ điều gì liên quan đến thông tin xác thực mà bạn không thể xoay vòng. Dán mã thông báo đã bị thu hồi chứ không phải mã thông báo đang hoạt động."]},{"p":"Như đã nói, lý do để giữ những dấu trang này là thông lượng. Một tác vụ mất 40 giây trên tab trình duyệt sẽ không bao giờ được lên lịch, không bao giờ được ủy quyền và không bao giờ trở thành lý do để mở IDE lúc 8 giờ tối."},{"h":"Định dạng và chuyển đổi dữ liệu"},{"p":"Công việc phổ biến nhất hàng ngày là làm cho dữ liệu có thể đọc được. API trả về một blob một dòng, một đồng nghiệp gửi tệp cấu hình với các tab được cửa sổ trò chuyện đọc sai hoặc bạn đã xuất bảng tính sang JSON và nó trở lại dưới dạng một dòng lớn."},{"l":["[[json-formatter|JSON Formatter]] — thụt lề, xác thực và đọc tải trọng. Sử dụng nó trước khi bạn gỡ lỗi: một nửa trong số tất cả các vé \\"API bị hỏng\\" thực sự là JSON không đúng định dạng với dấu phẩy ở cuối.","[[json-validator|JSON Validator]] — khi bạn cần một câu trả lời đạt/không đạt nghiêm ngặt thay vì một bản in đẹp.","[[xml-formatter|XML Formatter]] — công việc tương tự cho các phản hồi SOAP, nguồn cấp RSS và Maven POM mà chưa ai chạm tới kể từ năm 2014.","[[json-to-yaml|JSON to YAML]] và [[json-to-csv|JSON to CSV]] — di chuyển dữ liệu giữa các định dạng mà hệ thống thực sự sử dụng."]},{"p":"Hãy ghi nhớ nhóm cuối cùng trong một tình huống cụ thể: khách hàng đưa cho bạn một bảng tính và mong đợi nó có trong API của họ. Chuyển trực tiếp CSV sang JSON là một công việc kéo dài hai phút thay vì mất một buổi chiều viết kịch bản."},{"h":"Mã hóa và thoát"},{"p":"Các lỗi mã hóa gây khó chịu một cách không tương xứng vì dữ liệu trông ổn. Giá trị \\"San José & Sons\\" xuất hiện dưới dạng \\"San Jos%C3%A9 %26 Sons\\" và việc so sánh của bạn với cơ sở dữ liệu không thành công vì những lý do không thể thấy được trong nhật ký."},{"l":["[[url-encode|Bộ mã hóa / giải mã URL]] — giải quyết ngay lập tức xem chuỗi truy vấn có được mã hóa kép hay không.","[[base64-encoding|Bộ mã hóa / giải mã Base64]] — giải mã một đoạn chứng chỉ hoặc mã hóa một nội dung nhỏ thành nội tuyến trong CSS.","[[html-entity-encoding|Bộ mã hóa / giải mã thực thể HTML]] — tìm hiểu xem liệu dấu \\"&\\" lạc trong trang của bạn đến từ mẫu hay dữ liệu của bạn.","[[unicode-converter|Unicode Converter]] — hữu ích khi một ký tự \\"bị hỏng\\" hóa ra lại là ký tự hợp lệ được hiển thị sai mã hóa.","[[number-base-converter|Number Base Converter]] — kiểm tra màu sắc, mặt nạ bit cho phép hoặc địa chỉ bộ nhớ mà không cần ứng dụng máy tính."]},{"b":"Một thói quen thực tế: khi một giá trị bị cắt xén, hãy giải mã nó từng lớp một và dán từng kết quả vào một trường trống. Nếu bộ giải mã đầu tiên tạo ra văn bản có thể đọc được thì vấn đề nằm ở một bộ mã hóa bổ sung ở đâu đó ngược dòng. Nếu nó tạo ra mojibake, thì bạn gặp vấn đề về mã hóa chứ không phải vấn đề thoát và hai vấn đề đó cần các cách khắc phục khác nhau."},{"h":"Mã định danh, hàm băm và mã thông báo"},{"p":"Nhóm này là nơi các nhà phát triển lãng phí nhiều thời gian nhất để tìm kiếm tập lệnh cục bộ phù hợp mà họ đã viết một lần và bị mất."},{"l":["[[uuid-generator|UUID Generator]] — tạo mã định danh v4 cho dữ liệu gốc, đồ đạc hoặc hàng cơ sở dữ liệu nhanh.","[[md5-generator|MD5 / SHA Hash Generator]] — xác minh quá trình tải xuống hoặc xác nhận rằng hai tệp thực sự giống hệt nhau.","[[timestamp-converter|Timestamp Converter]] — công cụ được sử dụng nhiều nhất trong toàn bộ danh sách này. Khi dòng nhật ký ghi 1761000000, đây là thông tin cho bạn biết sự cố đã xảy ra trong quá trình triển khai hay trước đó."]},{"p":"Bộ chuyển đổi dấu thời gian kiếm được tiền vì một lý do cụ thể: số kỷ nguyên đồng thời rõ ràng và vô dụng. Bạn biết chính xác khi nào điều gì đó xảy ra và bạn không thể nói với đồng nghiệp. Chuyển đổi một lần thường giải quyết một cuộc tranh luận lớn hơn mức cần thiết."},{"h":"So sánh và gỡ lỗi"},{"l":["[[regex-tester|Regex Test]] — mục có đòn bẩy cao nhất ở đây. Một biểu thức chính quy trông có vẻ chính xác và lặng lẽ không khớp với gì là một trong những lỗi đắt giá nhất trong quá trình phát triển, bởi vì nó bị lỗi âm thầm ở một nơi không ai đọc.","[[html-preview|Xem trước HTML]] — lặp lại một đoạn đánh dấu để kiểm tra xem nó thực sự hiển thị như thế nào."]},{"p":"Kiểm tra các biểu thức chính quy của bạn với dữ liệu đầu vào mà bạn thực sự mong đợi, bao gồm chuỗi trống, tên Unicode và giá trị có dòng mới. Hầu hết các mẫu đều bị hỏng ở trường hợp thứ ba và không ai để ý cho đến khi có dữ liệu sản xuất."},{"h":"Một ví dụ điển hình: ba công cụ, một sự cố nhàm chán"},{"p":"Đây là trình tự đã thuyết phục tôi đánh dấu tất cả những điều này. Một khách hàng đã báo cáo rằng hồ sơ họ gửi vào thứ Ba đã bị thiếu trong báo cáo vào thứ Năm."},{"l":["**1. Chuyển đổi dấu thời gian.** Công việc báo cáo đã ghi lại thời gian tạo bản ghi dưới dạng giá trị kỷ nguyên. [[timestamp-converter|Timestamp Converter]] cho thấy bản ghi được tạo vào lúc 11 giờ tối theo giờ địa phương, tức là Thứ Ba — giả định múi giờ của công việc là vấn đề chứ không phải bản ghi.","**2. Định dạng tải trọng.** Lấy JSON được lưu trữ thông qua [[json-formatter|JSON Formatter]] cho thấy bản ghi được ghi với trường ngày rỗng, vì khách hàng đã gọi hai lần cùng một điểm cuối cách nhau 200 mili giây và lần ghi thứ hai đã thắng.","**3. So sánh các trọng tải.** Cả hai bản ghi đều có cùng một khóa API và cùng một dấu thời gian của khách hàng, cho thấy một lần thử lại chứ không phải hai khách hàng riêng biệt."]},{"p":"Tổng thời gian đã trôi qua: bốn phút. Nỗ lực trước đó trong cuộc điều tra này nhằm tìm kiếm nguyên nhân cốt lõi tương tự trong một nền tảng ghi nhật ký, đã mất một buổi chiều và đưa ra kết luận sai."},{"h":"Quyền riêng tư: tại sao chạy cục bộ lại là tính năng thực tế"},{"p":"Mọi công cụ trong thư viện này đều xử lý dữ liệu đầu vào của bạn bên trong trình duyệt của riêng bạn. Không có gì được tải lên, điều đó có nghĩa là không có câu hỏi về việc lưu giữ, không có thỏa thuận với bộ xử lý và không có cuộc trò chuyện khó chịu về trọng tải sản xuất mà bạn đã dán ba phút trước.\\n\\nĐây là lý do nên ưu tiên những công cụ này hơn \\"API Pastebin\\" được lưu trữ trên máy chủ hoặc dịch vụ trực tuyến yêu cầu bạn đăng ký. Điều đó cũng có nghĩa là họ tiếp tục làm việc trên chuyến bay, dưới tầng hầm hoặc khi VPN của công ty quyết định chặn một miền khác."},{"p":"Một điều cần lưu ý rõ ràng: một trang có khả năng ngoại tuyến chỉ ở chế độ riêng tư nếu bản thân trang đó có mã mà bạn cho là như vậy. Trên máy dùng chung, hãy sử dụng cửa sổ riêng tư và đóng nó khi bạn hoàn tất, đặc biệt nếu bạn đang giải mã mã thông báo."},{"h":"Xây dựng quy trình làm việc xung quanh họ"},{"p":"Các công cụ này là tầm thường. Giá trị nằm ở thói quen tiếp cận một cái ngay lập tức thay vì \\"làm sau\\", bởi vì muộn hơn là khi bạn viết một tập lệnh dùng một lần hoặc mở một IDE hoặc quyết định rằng nó không đáng để kiểm tra chút nào."},{"l":["Đánh dấu bộ sưu tập chứ không phải các URL riêng lẻ và đặt nó vào thanh công cụ của trình duyệt của bạn.","Khi có điều gì đó không ổn, hãy kiểm tra nó trước khi bạn hình thành giả thuyết. Tốn mười lăm giây; giết chết cả lớp kết luận sai lầm.","Khi bạn đã kiểm tra cùng một thứ hai lần, đó là tín hiệu để tự động hóa nó - nhưng đừng tự động hóa khi nghi ngờ.","Không dán bí mật sản xuất. Xoay bất cứ điều gì bạn không chắc chắn."]},{"h":"Câu hỏi thường gặp"},{"p":"**Những công cụ này có miễn phí không?** Có, hoàn toàn, không cần tài khoản và không giới hạn mức sử dụng. Không có cấp độ trả phí nào giữ lại bất cứ điều gì cơ bản.\\n\\n**Chúng có hoạt động ngoại tuyến không?** Khi một trang được tải xong, có — mọi thứ sẽ chạy trong trình duyệt của bạn. Tải lại yêu cầu kết nối.\\n\\n**Tôi có thể sử dụng chúng cho mục đích thương mại không?** Có. Đầu ra là của bạn mà không có yêu cầu ghi công.\\n\\n**Có API không?** Không, và đó là cố ý — giá trị là giao diện. Xuất kết quả đầu ra và xử lý nó theo cách bạn muốn.\\n\\n**Tại sao không cài đặt một công cụ CLI?** Cài đặt một công cụ khi bạn cần ba lần. Sử dụng tab trình duyệt cho hai tab đầu tiên."}]},"text-tools-for-writers":{"title":"17 công cụ văn bản miễn phí dành cho nhà văn, sinh viên và nhà tiếp thị","description":"Dọn dẹp bản sao, đếm từ chính xác, định dạng danh sách và biến bản nháp thô thành nội dung có thể xuất bản — bằng các công cụ trình duyệt miễn phí chạy cục bộ trong trình duyệt của bạn.","category":"Công cụ văn bản","blocks":[{"p":"Viết cho công việc bao gồm một lượng công việc cực nhọc máy móc đáng ngạc nhiên không liên quan gì đến việc viết: loại bỏ khoảng trắng thừa khỏi đoạn văn được dán, kiểm tra giới hạn từ, loại bỏ danh sách tên, chuyển đổi thứ gì đó thành một URL slug.\\n\\nMười bảy công cụ này dành cho phần công việc đó. Tất cả chúng đều chạy cục bộ trong trình duyệt, đây không phải là một chi tiết nhỏ - bản nháp bạn dán thường không được xuất bản và danh sách bạn đang sắp xếp thường là dữ liệu cá nhân của ai đó."},{"h":"Đo lường những gì bạn đã viết"},{"p":"Số từ có vẻ được giải quyết cho đến khi khách hàng yêu cầu chính xác 800 từ và người biên tập của bạn nói là 820 hoặc một biểu mẫu từ chối văn bản của bạn ở mức 1.995 ký tự mà không có lời giải thích về dòng mới đã đi đâu."},{"l":["[[bộ đếm từ|Bộ đếm từ]] — thước đo tiêu chuẩn. Dán, đọc, điều chỉnh.","[[bộ đếm chữ cái|Bộ đếm chữ cái]] — đếm ký tự và tần số chữ cái. Hữu ích khi bạn đang tìm hiểu lý do tại sao một đoạn văn có cảm giác sai: đó thường là mẫu chữ lặp đi lặp lại, không phải là một giấc mơ."]},{"p":"Lưu ý về ý nghĩa của \\"một từ\\": các bộ đếm khác nhau không đồng ý về dấu gạch nối, số và URL. Nếu con số chính xác quan trọng, hãy sử dụng cùng một bộ đếm mà người kiểm tra công việc của bạn sử dụng và đồng ý trước về con số đó. Đây thực sự là nguồn gốc phổ biến của những lý lẽ nhỏ nhặt, vô nghĩa."},{"h":"Dọn dẹp bản sao bạn không viết"},{"p":"Hầu hết văn bản bạn nhận được đều bị hư hỏng nhẹ: dấu cách đôi khi sao chép-dán, tab lạc, cách viết hoa không nhất quán do ai đó gõ vội. Sửa bằng tay thì chậm và dễ mắc lỗi."},{"l":["[[text-trimmer|Text Trimmer]] — xóa khoảng trắng đầu và cuối khỏi mỗi dòng cùng một lúc. Điều này sửa nhiều báo cáo \\"định dạng có vẻ bị hỏng\\" hơn bất kỳ báo cáo nào khác trong danh sách này.","[[text-case-converter|Trình chuyển đổi chữ hoa chữ thường]] — chuyển đổi giữa kiểu chữ trong câu, kiểu chữ tiêu đề, chữ hoa và chữ thường trong một khối. Đây cũng là cách nhanh nhất để hoàn tác một đoạn CAPS LOCK vô tình.","[[text-to-slug|Nhắn tin tới Slug]] — biến dòng tiêu đề thành một URL sạch. Dán tiêu đề của bạn, hoàn thành phần mở rộng."]},{"p":"Trình tạo slug còn có một công dụng ngoài URL: đó là một cách nhanh chóng để tạo tên tệp hoặc neo có thể đọc được mà con người có thể phân tích cú pháp trong nháy mắt, vượt trội hơn `final_final_v3`."},{"h":"Làm việc với danh sách"},{"p":"Danh sách, hàng tồn kho, trộn thư, dọn dẹp thẻ, phản hồi khảo sát, cột bảng tính - tại một thời điểm nào đó, mọi thứ sẽ trở thành một danh sách và mọi danh sách đều cần sắp xếp, loại bỏ trùng lặp hoặc ngẫu nhiên hóa."},{"l":["[[duplicate-line-remover|Xóa dòng trùng lặp]] — so sánh hai danh sách hoặc xóa một danh sách. Kết quả đầu ra cho bạn biết có bao nhiêu bản sao đã bị xóa, điều này rất hữu ích khi bạn báo cáo kết quả.","[[list-sorter|List Sorter]] — công việc tương tự đối với việc nhập danh sách có cấu trúc.","[[list-randomizer|List Randomizer]] — xáo trộn thứ tự bốc thăm, một chuỗi câu đố hoặc một danh sách rút gọn có rào chắn để không ai nghi ngờ sự thiên vị.","[[line-number-adder|Line Number Adder]] — các dòng số để tham khảo trong phiếu hoặc nhận xét đánh giá mã."]},{"b":"Cái bẫy cổ điển ở đây là một danh sách trông có vẻ không trùng lặp nhưng thực tế không phải vậy: `Apple`, `pple ` và `Apple.` là ba dòng khác nhau đối với một máy tính. Cắt bớt khoảng trắng và loại bỏ dấu câu ở cuối trước khi loại bỏ trùng lặp, nếu không bạn sẽ không hợp nhất gì và kết luận rằng dữ liệu là sạch."},{"h":"Xem trước và định dạng"},{"p":"Markdown đã thắng nhưng không đồng đều. Một nửa công cụ của bạn hiển thị nó, một nửa thì không, và một nửa không hiển thị nó thường là thứ mà cấp trên phải dán vào."},{"l":["[[markdown-preview|Markdown Preview]] — hiển thị trực tiếp, do đó bạn có thể kiểm tra bảng hoặc danh sách lồng nhau có thực sự trông ổn trước khi đến tay khách hàng hay không.","[[text-repeater|Text Repeater]] — lặp lại một chuỗi N lần. Hữu ích để tạo phần đệm, kiểm tra dữ liệu hoặc đôi khi tạo một điểm trong tài liệu."]},{"p":"Bản xem trước Markdown là công cụ giúp tiết kiệm nhiều thời gian nhất trong toàn bộ tập hợp này, vì bảng bị hỏng trong tài liệu được kết xuất sẽ hiển thị rõ ràng hơn — và gây bối rối hơn nhiều — so với bảng bị hỏng trong văn bản thô."},{"h":"Phần còn lại và thời điểm tiếp cận chúng"},{"l":["[[random-string|Random String Generator]] — tạo ra các nonces, ID giữ chỗ hoặc mã ngắn có thể đọc được. Tốt hơn là tự tay phát minh ra thứ gì đó vì bạn sẽ không vô tình tái sử dụng nó.","[[morse-code|Morse Code Translator]] — thực sự thú vị, đôi khi hữu ích cho một dự án theo chủ đề hoặc một câu đố."]},{"p":"Đây là những công cụ có tần suất thấp hơn, nhưng chúng không tốn kém gì khi đánh dấu trang và chúng giải quyết được vấn đề cụ thể là \\"Tôi cần một giá trị trông ngẫu nhiên ngay bây giờ và tôi không tin tưởng bản thân mình có thể tạo ra một giá trị đó\\"."},{"h":"Một lượt chỉnh sửa thực tế"},{"p":"Đây là thứ tự được áp dụng khi một bản nháp được gửi đến từ người khác và cần được gửi đi dưới tên của bạn."},{"l":["**1. Cắt.** Trước tiên hãy chạy toàn bộ tài liệu thông qua [[text-trimmer|Text Trimmer]]. Thiệt hại về khoảng trắng ẩn bên trong các đoạn văn mà bạn sẽ không bao giờ nhìn thấy nó.","**2. Viết hoa rõ ràng.** Chỉ sử dụng [[text-case-converter|Text Case Converter]] cho dòng tiêu đề. Không bao giờ áp dụng chuyển đổi kiểu chữ cho bản nháp đầy đủ — nó sẽ phá hủy danh từ riêng.","**3. Đo.** Kiểm tra độ dài bằng [[word-counter|Word Counter]] trước khi viết, để bạn biết tác phẩm có hình dạng như thế nào.","**4. Xem trước.** Nếu nó chứa Markdown, hãy hiển thị nó bằng [[markdown-preview|Markdown Preview]].","**5. Slug.** Tạo sên URL cuối cùng, từ dòng tiêu đề cuối cùng, với [[text-to-slug|Text to Slug]] — việc thay đổi dòng tiêu đề sau đó sẽ phá vỡ sên."]},{"p":"Toàn bộ quá trình này mất vài phút và loại bỏ loại lỗi trong đó tài liệu đúng về mặt kỹ thuật và sai rõ ràng."},{"h":"Câu hỏi của nhà văn về quyền riêng tư"},{"p":"**Văn bản chưa xuất bản của tôi có rời khỏi máy tính của tôi không?** Không. Những công cụ này xử lý văn bản trong trình duyệt của bạn và không có gì được lưu trữ hoặc truyền đi.\\n\\n**Có giới hạn độ dài không?** Không có giới hạn phía máy chủ vì không có lệnh gọi máy chủ. Đầu vào cực lớn bị giới hạn bởi bộ nhớ của thiết bị của bạn.\\n\\n**Tôi có thể sử dụng kết quả đầu ra cho mục đích thương mại không?** Có, miễn phí, không cần ghi công.\\n\\n**Họ có làm việc trên điện thoại không?** Có. Bố cục thích ứng và mã giống nhau sẽ chạy."},{"h":"Những công cụ này sẽ không làm được gì cho bạn"},{"p":"Đáng để nói thẳng về các giới hạn, bởi vì một công cụ cơ giới hóa sai lầm sẽ chỉ tạo ra sai lầm nhanh hơn.\\n\\nKhông tiện ích nào trong số này có thể cho bạn biết liệu một câu có rõ ràng hay không, liệu lời tuyên bố có nguồn gốc hay không hoặc liệu giọng điệu có phù hợp với khán giả hay không. Họ đếm các ký tự; họ không phán xét văn xuôi. Một văn bản đạt điểm cao trên mọi số liệu trên trang này vẫn có thể không đọc được.\\n\\nHọ cũng không chỉnh sửa. Thời điểm bạn nhận thấy mình đang viết lại các mệnh đề riêng lẻ bằng tay trên quy mô lớn, bạn đã phát triển vượt trội so với công cụ văn bản và bạn muốn có một trình soạn thảo phù hợp, một công cụ tìm và thay thế bằng biểu thức chính quy — mà [[regex-tester|Regex Test]] thực sự phù hợp để luyện tập — hoặc một tập lệnh. Sử dụng trình duyệt cho lớp cơ học và tự đánh giá mọi thứ ở trên nó."},{"p":"Một điều nữa họ sẽ không làm là sửa nguồn xấu. Nếu bảng tính của bạn có nhiều cách đặt tên không thống nhất — \\"Dr\\", \\"DR\\", \\"Dr.\\" tất cả trong một cột — một công cụ sẽ sắp xếp và loại bỏ trùng lặp một cách trung thực những gì bạn đã cung cấp và bạn vẫn sẽ có ba mục trong đó lẽ ra phải có một mục. Làm sạch dữ liệu là một quyết định chứ không phải một bước máy móc. Trước tiên, hãy quyết định hình thức chính tắc, sau đó áp dụng nó, sau đó kiểm tra."},{"h":"Giữ một danh sách làm việc có thể sử dụng được"},{"p":"Nếu bạn duy trì một danh sách các khách hàng tiềm năng, liên kết, tài liệu tham khảo hoặc thuật ngữ, nó sẽ xuống cấp một cách lặng lẽ. Chế độ lỗi luôn giống nhau: các mục trông giống hệt nhau thì không và một lần hợp nhất sẽ không loại bỏ được gì.\\n\\nQuá trình bảo trì hoạt động rất nhàm chán: cắt bớt khoảng trắng, chuẩn hóa cách viết hoa, loại bỏ dấu chấm câu ở cuối, sau đó loại bỏ trùng lặp. Theo thứ tự đó - việc cắt bớt các mục nhập sau khi loại bỏ trùng lặp sẽ bị mất. Thực hiện việc này mỗi tháng một lần trong danh sách đang hoạt động sẽ biến một mớ hỗn độn kéo dài hai giờ không thể phục hồi thành một công việc vặt kéo dài mười phút.\\n\\nKhi hai danh sách cần đối chiếu — chẳng hạn như danh sách đăng ký với danh sách tham dự — hãy sắp xếp cả hai bằng [[list-sorter|List Sorter]] trước, để chúng xếp hàng, sau đó so sánh bằng mắt. Sắp xếp cả hai bên trước khi so sánh là sự khác biệt giữa một cuộc kiểm tra kéo dài hai phút và một cuộc săn lùng kéo dài hai mươi phút."},{"h":"Đồ mang đi"},{"p":"Không có công cụ nào trong số này là thông minh. Đó chính là vấn đề: họ loại bỏ năm phần trăm văn bản máy móc không phải là văn bản, vì vậy chín mươi lăm phần trăm còn lại thực sự là về các câu. Đánh dấu những cái bạn sử dụng hàng tháng, bỏ qua phần còn lại và ngừng sửa khoảng trắng bằng tay."}]},"calculators-and-converters-guide":{"title":"18 công cụ tính toán và chuyển đổi miễn phí cho các con số mà bạn thực sự phải xử lý","description":"Tỷ lệ phần trăm, giảm giá, tiền boa, khoản vay, ngày tháng, chỉ số BMI và chuyển đổi đơn vị — các công cụ tính toán miễn phí trên trình duyệt hiển thị lý do của chúng mà không cần có tài khoản.","category":"Máy tính","blocks":[{"p":"Mọi người cần chia hóa đơn, tìm hiểu xem giảm giá có thực sự là giảm giá hay không và chuyển đổi nhiệt độ hoặc kích thước tệp mà không cần suy nghĩ về nó. Mọi người cũng vậy, ít nhất một lần, mắc lỗi này ở nơi công cộng.\\n\\nĐây là bộ sưu tập gồm mười tám máy tính và bộ chuyển đổi bao gồm tiền bạc, ngày tháng, sức khỏe và các chuyển đổi đơn vị hiển thị trong công việc và du lịch. Tất cả chúng đều chạy trong trình duyệt: không có gì được lưu, vì vậy những con số bạn nhập không phải là việc của ai khác ngoài việc của bạn."},{"h":"Tính toán tiền"},{"p":"Toán học thực tế phổ biến nhất là tỷ lệ phần trăm của một cái gì đó. Thuế bán hàng, tiền boa, khoản chiết khấu, hoa hồng, tốc độ tăng trưởng. Công thức rất đơn giản nhưng lý do khiến mọi người mắc sai lầm hầu như luôn giống nhau: họ áp dụng tỷ lệ phần trăm vào cơ số sai."},{"l":["[[máy tính chiết khấu|Máy tính chiết khấu]] — tính ra mức giá cuối cùng và quan trọng hơn là bạn đã tiết kiệm được bao nhiêu. Hữu ích khi phát hiện \\"giảm giá 50%\\" thực chất là 20% sau khi giá niêm yết tăng.","[[máy tính tiền boa|Máy tính tiền boa]] — chia hóa đơn, chọn tỷ lệ phần trăm, làm tròn cho mỗi người nếu bạn muốn.","[[loan-máy tính|Máy tính khoản vay]] — khoản thanh toán hàng tháng và tổng tiền lãi, đây là con số thực sự quyết định liệu khoản vay có phải chăng hay không."]},{"b":"Khi giảm giá: giảm giá 20%, sau đó giảm giá 20% nữa không phải là giảm 40% - mà là 36%. Tỷ lệ phần trăm tuần tự gộp trên cơ sở giảm. Bất kỳ máy tính nào trong danh sách này sẽ xác nhận nó trong khoảng hai giây và đó là dữ kiện số học hữu ích nhất trong bài viết này."},{"p":"Công cụ tính khoản vay xứng đáng được ghi chú cụ thể. Con số quan trọng không phải là khoản thanh toán hàng tháng - mà là tổng tiền lãi phải trả trong suốt thời hạn của khoản vay, vì đó là chi phí thực sự của việc đi vay. Hai khoản vay có khoản thanh toán hàng tháng giống nhau và các điều khoản khác nhau có thể khác nhau tới hàng chục nghìn về tổng tiền lãi."},{"h":"Ngày và đếm ngược"},{"p":"Số học về ngày tháng là nơi mà hầu hết mọi người đều âm thầm hiểu sai, bởi vì tháng của con người có độ dài khác nhau và câu trả lời thay đổi tùy thuộc vào việc bạn muốn nói là \\"tháng dương lịch\\" hay \\"30 ngày\\"."},{"l":["[[ngày-chênh lệch|Công cụ tính chênh lệch ngày]] — số ngày (và tổng số tháng, năm) giữa hai ngày.","[[days-until|Ngày cho đến Máy tính]] — đếm ngược đến một ngày cụ thể, với số ngày làm việc thường là số ngày mọi người thực sự mong muốn.","[[máy tính tuổi|Máy tính tuổi]] — tuổi chính xác tính theo năm và ngày, cộng với ngày sinh nhật tiếp theo.","[[timestamp-converter|Timestamp Converter]] — dấu thời gian Unix thành ngày thực, điều này quan trọng nếu bạn chạm vào nhật ký, cơ sở dữ liệu hoặc phản hồi API."]},{"p":"Sự khác biệt khiến mọi người cảm thấy khó chịu: số ngày từ ngày 1 tháng 3 đến ngày 1 tháng 4 là 31, nhưng số *tháng* là một. Nếu bạn đang tính toán thời hạn thông báo hoặc thời hạn đăng ký, hãy nêu rõ đơn vị bạn muốn nói bằng văn bản."},{"h":"Thành thật mà nói, con số sức khỏe"},{"l":["[[bmi-máy tính|Máy tính BMI]] — chỉ số khối cơ thể với các danh mục tiêu chuẩn và những lưu ý bên dưới."]},{"p":"BMI là một thống kê sàng lọc cấp độ dân số. Nó không nói gì về khối lượng cơ bắp, thành phần cơ thể hoặc sức khỏe của bất kỳ cá nhân nào và nó là một đại diện kém cho tình trạng thể lực ở các vận động viên, ở người lớn tuổi và giữa các nhóm dân tộc khác nhau. Sử dụng nó như một điểm dữ liệu trong số nhiều điểm dữ liệu hoặc như một cách để theo dõi sự thay đổi theo thời gian — không phải như một phán quyết. Nếu bạn đang đưa ra những quyết định ảnh hưởng đến sức khỏe của mình, công cụ phù hợp là bác sĩ lâm sàng chứ không phải tab trình duyệt."},{"h":"Chuyển đổi đơn vị: đơn vị hàng ngày"},{"p":"Chuyển đổi đơn vị được chia thành hai loại: chuyển đổi bạn phải thực hiện chính xác và chuyển đổi bạn cần đại khái. Những công cụ này xử lý cả hai và công việc nằm ở việc ghi nhớ cái nào."},{"l":["[[bộ chuyển đổi độ dài|Bộ chuyển đổi độ dài]] — hệ mét sang hệ đo lường Anh và ngược lại: milimét, cm, mét, km, inch, bàn chân, thước, dặm.","[[công cụ chuyển đổi trọng lượng|Công cụ chuyển đổi trọng lượng]] — gam, kilôgam, ounce, pound, tấn. Cái cần kiểm tra trước công thức hoặc nhãn vận chuyển.","[[bộ chuyển đổi nhiệt độ|Bộ chuyển đổi nhiệt độ]] — Độ C, Độ F, Kelvin. Bởi vì -10°C không phải là 14°F và công thức không phải là phép nhân.","[[bộ chuyển đổi tốc độ|Bộ chuyển đổi tốc độ]] — km/h, mph, m/s, hải lý. Hữu ích cho giới hạn tốc độ nước ngoài hoặc thông số kỹ thuật.","[[công cụ chuyển đổi diện tích|Công cụ chuyển đổi diện tích]] — mét vuông, feet vuông, mẫu Anh, ha. Đây là điều mọi người đánh giá không tốt khi mua hoặc thuê bất động sản.","[[bộ chuyển đổi âm lượng|Bộ chuyển đổi âm lượng]] — lít, mililit, gallon, cốc, mét khối.","[[bộ chuyển đổi thời gian|Bộ chuyển đổi thời gian]] — giây, phút, giờ, ngày, tuần."]},{"b":"Hai bẫy chuyển đổi đáng biết: bẫy lưu trữ dữ liệu ở trên (nhà tiếp thị bán 10^3, hệ điều hành báo cáo 2^10) và tiết kiệm nhiên liệu - một chiếc ô tô được báo giá ở mức 40 mpg (đế quốc) gần với 33 mpg (Mỹ) hơn là 40, bởi vì gallon Anh lớn hơn. Sai lầm thứ hai khiến chiếc xe thuê trông có vẻ kém hiệu quả một cách phi thực tế."},{"h":"Hai thứ bạn sẽ không mong đợi sẽ cần"},{"l":["[[random-number|Random Number Generator]] — rút thăm trong một phạm vi, dành cho xổ số, khung hoặc phân chia A/B nhanh chóng. Hữu ích chính xác vì nó loại bỏ sự nghi ngờ rằng bạn đã gian lận.","[[xúc xắc|Con lăn xúc xắc]] — bất kỳ xúc xắc nào từ việc lật đồng xu đến xúc xắc hai mươi mặt, dành cho trò chơi trên bàn hoặc phiên chơi trên bàn trong đó xúc xắc thật đã lăn khỏi bàn lần cuối."]},{"h":"Sử dụng máy tính đúng cách"},{"p":"Máy tính chỉ hữu ích nếu bạn biết bạn đang hỏi về số nào. Ba thói quen tạo nên sự khác biệt."},{"l":["**Vòng đầu tiên, tính thứ hai.** Nếu con số chính xác không làm thay đổi quyết định của bạn, hãy sử dụng vòng một. Bạn có thể kiểm tra phần trăm số tròn trong đầu và phát hiện lỗi đầu vào.","**Kiểm tra độ lớn một cách tỉnh táo.** Trước khi tin vào một kết quả, hãy hỏi xem kết quả đó nên lớn hơn hay nhỏ hơn đầu vào và khoảng bao nhiêu. Hầu hết các lỗi số học đều tồn tại sau mỗi lần kiểm tra ngoại trừ lần kiểm tra này.","**Chụp ảnh đầu vào chứ không phải đầu ra.** Khi bạn chạy lại phép tính sau này, điều quan trọng là biết những gì bạn đã giả định chứ không phải những gì bạn đã kết luận."]},{"h":"Những câu hỏi mà mọi người thực sự hỏi"},{"p":"**Số của tôi có được lưu ở đâu không?** Không. Việc tính toán diễn ra trong trình duyệt của bạn và không có gì được truyền đi hay giữ lại.\\n\\n**Những thứ này có hoạt động trên điện thoại không?** Có, và máy tính được thiết kế để sử dụng bằng một tay.\\n\\n**Bạn sử dụng tiêu chuẩn chuyển đổi nào để lưu trữ dữ liệu?** Thập phân (1 KB = 1000 byte) theo mặc định vì đó là cách bán dung lượng lưu trữ. Hệ điều hành báo cáo nhị phân, đó là lý do tại sao ổ đĩa có vẻ bị co lại — công cụ này giải thích sự khác biệt thay vì âm thầm chọn một bên.\\n\\n**Tôi có thể nhúng những thứ này vào trang web của riêng mình không?** Không. Thay vào đó hãy đánh dấu chúng; chi phí đó bằng 0 và vấn đề về độ chính xác là của bạn."},{"h":"Tỷ lệ phần trăm: bốn sai lầm quan trọng"},{"p":"Hầu hết mọi lỗi phần trăm mà một người mắc phải trong cuộc sống hàng ngày đều thuộc một trong bốn lỗi đó. Đặt tên cho chúng làm cho chúng có thể tránh được."},{"l":["**Cơ sở sai.** \\"Tăng 10% rồi giảm 10% sẽ đưa bạn về vị trí ban đầu\\" là sai vì cả hai đều áp dụng cho các cơ sở khác nhau. Mười phần trăm của 100 là 10; mười phần trăm của 90 là 9.","**Phần trăm của một tỷ lệ phần trăm.** Xếp chồng hai lần giảm giá sẽ nhân chúng lên (0,8 × 0,8 = 0,64, tức là giảm giá 36%), nó không cộng chúng lại.","**Phần trăm so với điểm phần trăm.** Tỷ lệ tăng từ 4% lên 6% đã tăng 2 điểm phần trăm, nhưng tính tương đối là 50%. Chính trị và y học chứa đầy sự nhầm lẫn này, và nó không phải lúc nào cũng là ngẫu nhiên.","**Làm tròn quá sớm.** Làm tròn một bước trung gian trước khi áp dụng tỷ lệ phần trăm sẽ tạo ra lỗi. Giữ độ chính xác tối đa cho đến con số cuối cùng và thực hiện bước cuối cùng trên máy tính thay vì trong đầu bạn."]},{"p":"Nếu bạn chỉ có một thói quen trong toàn bộ phần này, hãy làm theo thói quen này: trước khi trích dẫn tỷ lệ phần trăm cho bất kỳ ai, hãy trình bày lại tỷ lệ phần trăm *của*. Một nửa số lập luận bạn từng có về một số thực ra là những lập luận về mẫu số."},{"h":"Biết khi nào nên ngừng tính toán"},{"p":"Có một điểm mà độ chính xác không còn hữu ích nữa. Khoản thanh toán hàng tháng đến hai chữ số thập phân rất có ý nghĩa. Tổng chi phí dự kiến ​​đến tám chữ số thập phân là một cách để tránh đưa ra quyết định thực tế, đó là liệu khoản vay có phù hợp với những gì bạn có thể chi trả mà không bị căng thẳng hay không.\\n\\nBài kiểm tra hữu ích là câu hỏi về độ nhạy: quyết định có thay đổi không nếu đầu vào này thay đổi 10%? Nếu không, hãy ngừng tinh chỉnh nó và sử dụng thêm thời gian cho biến số có tác động đến câu trả lời - thường là thuật ngữ thay vì tỷ giá hoặc giá niêm yết thay vì chiết khấu."},{"p":"Và một ranh giới đáng nói rõ: những máy tính này là số học, không phải lời khuyên. Mục tiêu tiết kiệm, ngày nghỉ hưu và kế hoạch trả nợ đều là những quyết định về rủi ro, hành vi và thời gian và tab trình duyệt không thể cân nhắc bất kỳ điều nào trong số đó. Nó chỉ có thể cho bạn biết những con số ám chỉ điều gì khi bạn đã quyết định những gì bạn đang giả định. Sự khác biệt đó là sự khác biệt giữa một chiếc máy tính hữu ích và một chiếc máy tính có trách nhiệm."},{"h":"Phiên bản một dòng"},{"p":"Đánh dấu trang máy tính tiền và ngày tháng một cách chính xác, coi BMI là một tín hiệu thay vì phán đoán, hãy nhớ rằng tỷ lệ phần trăm xếp chồng lên nhau và kiểm tra chuyển đổi đơn vị bất cứ khi nào một số đi vào bất kỳ hợp đồng nào. Điều đó bao gồm hầu hết mọi thứ."}]},"image-and-design-tools":{"title":"14 công cụ thiết kế và hình ảnh miễn phí chạy trong trình duyệt của bạn","description":"Nén, thay đổi kích thước và chuẩn bị hình ảnh, đồng thời tạo các hiệu ứng CSS, bảng màu, kiểm tra độ tương phản và favicon mà không cần cài đặt Photoshop hoặc bộ thiết kế.","category":"Công cụ thiết kế","blocks":[{"p":"Công việc hình ảnh có một vấn đề cụ thể: công việc thường nhỏ và các công cụ được cung cấp rất lớn. Bạn cần loại bỏ 400 KB hình ảnh chính hoặc nhận giá trị hex mà nhà thiết kế của bạn đã đề cập hoặc tạo một biểu tượng yêu thích chưa ai tạo ra. Điều đó không yêu cầu đăng ký.\\n\\nMười bốn công cụ bên dưới bao gồm việc chuẩn bị hình ảnh, xử lý màu sắc, tạo hiệu ứng CSS và các nội dung sản xuất nhỏ cần thiết. Mọi thứ đều chạy cục bộ, điều này quan trọng đối với hình ảnh hơn là văn bản: ảnh bạn vừa nén thường là ảnh bạn chưa xuất bản."},{"h":"Chuẩn bị hình ảnh cho web"},{"p":"Hầu hết các vấn đề về hình ảnh đều thực sự là vấn đề về trọng lượng. Một trang có cảm giác chậm thường chứa những hình ảnh lớn hơn kích thước hiển thị, ở định dạng sai, ở cài đặt chất lượng mà không ai từng thắc mắc."},{"l":["[[image-compressor|Image Compressor]] — giảm kích thước tệp trong khi vẫn giữ nguyên hình ảnh. Chạy nó trước khi bạn tải bất cứ thứ gì lên một biểu mẫu có giới hạn kích thước.","[[image-resizer|Image Resizer]] — đặt kích thước pixel thực tế mà bạn cần. Đây là chiến thắng lớn hơn: hình ảnh 4000px được hiển thị ở 800px mang theo dữ liệu gấp năm lần nó cần.","[[image-to-base64|Image to Base64]] — chuyển đổi một hình ảnh nhỏ thành URI dữ liệu để nội tuyến trong CSS, HTML hoặc mẫu email."]},{"b":"Thứ tự quan trọng. Thay đổi kích thước đầu tiên, nén thứ hai. Việc nén hình ảnh 4000px sẽ tạo ra một tệp nặng hơn nhiều so với việc thay đổi kích thước thành 800px và sau đó nén ở cùng chất lượng, bởi vì máy nén sẽ dành nhiều công sức cho các pixel mà dù sao cũng sẽ bị loại bỏ."},{"p":"Bạn nên nén bao nhiêu? Câu trả lời trung thực là: cho đến khi thấy sai thì hãy lùi lại một bước. Đối với một bức ảnh anh hùng, chất lượng từ 70 đến 80 phần trăm thường không thể phân biệt được với ảnh gốc ở kích thước xem bình thường. Đối với logo, ảnh chụp màn hình hoặc bất kỳ thứ gì có màu phẳng và các cạnh cứng, hãy sử dụng PNG và nén mạnh hơn — những thứ này thu được nhiều hơn và mất ít hơn."},{"p":"Một nguyên tắc nhỏ thực tế: mọi thứ dưới 200 KB đều phù hợp cho hình ảnh chính, dưới 80 KB cho hình thu nhỏ và nếu bạn không thể đạt dưới 300 KB thì có thể bạn đang gặp vấn đề về kích thước hơn là vấn đề về chất lượng."},{"h":"Base64: khi nội tuyến là cuộc gọi phù hợp"},{"p":"Việc chuyển đổi hình ảnh thành URI dữ liệu Base64 sẽ loại bỏ yêu cầu HTTP, điều này nghe giống như một chiến thắng thuần túy. Thông thường thì không. Chuỗi được mã hóa lớn hơn khoảng một phần ba so với tệp nhị phân, nó không thể được lưu vào bộ nhớ đệm riêng biệt và nó làm cồng kềnh CSS hoặc HTML của bạn.\\n\\nChỉ nội tuyến khi hình ảnh nhỏ — dưới vài kilobyte — được sử dụng một lần và rất quan trọng. Một biểu tượng nhỏ trong một mẫu email là trường hợp điển hình. Đối với bất kỳ nội dung nào được lặp lại trên các trang hoặc lớn hơn vài kilobyte, hãy phân phát nó dưới dạng tệp và để trình duyệt lưu vào bộ nhớ đệm."},{"h":"Hình mờ: những gì có thể tháo rời một cách trung thực"},{"l":[]},{"p":"Hãy rõ ràng về những gì điều này làm. Nó loại bỏ hoặc che khuất dấu hiệu có thể nhìn thấy. Nó không thể tái tạo lại các pixel cơ bản - thông tin được tô lên đã biến mất và không có bộ lọc nào tái tạo lại thông tin đó. Các kết quả có thể từ vô hình khi dấu nằm trên nền trơn cho đến vết ố rõ ràng khi dấu nằm trên chi tiết.\\n\\nMột điều đáng nói rõ ràng hơn: xóa hình mờ của người khác và xuất bản kết quả là vấn đề bản quyền ở hầu hết các khu vực pháp lý và vi phạm cấp phép bất kể bạn có bị bắt hay không. Công cụ này dành cho trường hợp này."},{"h":"Màu sắc: chuyển đổi, kiểm tra, lựa chọn"},{"p":"Màu sắc là nơi những lỗi nhỏ trở nên rất dễ thấy. Tỷ lệ tương phản không hỗ trợ khả năng truy cập, giá trị hex thực sự là bộ ba HSL, bảng màu trông mạch lạc trên màn hình của bạn và mờ trên máy chiếu."},{"l":["[[color-converter|Color Converter]] — di chuyển giữa HEX, RGB và HSL. HSL đáng để học đọc, vì màu sắc 210, độ bão hòa 40 phần trăm, độ sáng 50 phần trăm dễ điều chỉnh bằng tay hơn nhiều so với giá trị hex.","[[contrast-checker|Contrast Checker]] — kiểm tra văn bản trên nền của nó theo ngưỡng WCAG. Đây là công cụ hữu ích nhất trong bài viết này vì nó nắm bắt được vấn đề tuân thủ thực sự hơn là vấn đề về mùi vị.","[[color-palette|Color Palette Generator]] — tạo một bộ mạch lạc khi bạn bắt đầu từ một màu thương hiệu và cần phần còn lại của thang màu."]},{"b":"Ngược lại: WCAG AA yêu cầu 4,5 trên 1 đối với văn bản nội dung thông thường và 3 trên 1 đối với văn bản lớn. Nếu bạn đang chọn giữa hai màu thương hiệu cho một nút, thì màu có thể truy cập thường không phải là màu mà nhà thiết kế thích. Kiểm tra trước, sau đó tranh luận với dữ liệu."},{"p":"Một lưu ý đối với các công cụ màu sắc: tất cả đều cho rằng màn hình của bạn đã được hiệu chỉnh và người xem trang của bạn có đôi mắt hoạt động tốt. Không có giả định nào là an toàn. Đó là lý do người ta thích những sự kết hợp có kiểm tra độ tương phản hơn là những sự kết hợp chủ quan."},{"h":"Hiệu ứng CSS mà không cần mở công cụ thiết kế"},{"p":"Viết một gradient hoặc một lớp bóng bằng tay là một công việc thực sự khó chịu. Cú pháp khó hiểu, bạn không thể thấy những gì bạn đang tạo ra và sự khác biệt giữa bóng tốt và bóng xấu là một vài pixel mờ."},{"l":["[[gradient-generator|CSS gradient Generator]] — xây dựng các gradient tuyến tính và xuyên tâm, đồng thời sao chép CSS trực tiếp.","[[box-shadow-generator|Box Shadow Generator]] — tạo nhiều lớp bóng, đây là yếu tố phân biệt độ cao tinh tế với hình ảnh đổ nặng.","[[border-radius-generator|Trình tạo bán kính đường viền]] — lấy bán kính bất đối xứng giúp hình dạng trông có chủ ý.","[[text-shadow-generator|Text Shadow Generator]] — hữu ích một cách tiết kiệm. Hầu hết bóng văn bản đều quá mạnh; điều này cho phép bạn điều chỉnh phần bù và làm mờ cho đến khi nó biến mất."]},{"p":"Bí quyết cho cả bốn người là sự kiềm chế. Hai cái bóng - một cái tối đậm và một cái rộng mềm mại - được coi là độ cao vật lý. Một cái bóng đọc như một trang web từ mười lăm năm trước. Tạo, sao chép, sau đó xóa cho đến khi bạn không thể biết nó ở đó."},{"h":"Tài sản sản xuất mọi người đều quên"},{"l":["[[favicon-generator|Favicon Generator]] — tạo bộ biểu tượng nhỏ mà trang web thực sự cần. Điều này nằm trong danh sách vì biểu tượng yêu thích là nội dung có nhiều khả năng bị thiếu hoàn toàn nhất và biểu tượng bị thiếu sẽ hiển thị biểu tượng trang trình duyệt chung khiến trang web đã hoàn thiện trông có vẻ chưa hoàn thiện.","[[emoji-picker|Bộ chọn biểu tượng cảm xúc]] — duyệt, tìm kiếm và sao chép biểu tượng cảm xúc mà không cần tìm kiếm thông qua bộ chọn hệ điều hành. Thực sự hữu ích khi bạn viết bản sao cần một ký hiệu cụ thể."]},{"h":"Một ví dụ hoạt động: vận chuyển một phần anh hùng"},{"p":"Đây là toàn bộ cụm làm một công việc thực sự. Một trang cần một anh hùng có hình nền, tiêu đề và nút, nhưng chưa có anh hùng nào trong số đó được xây dựng."},{"l":["**1. Dành không gian.** Cung cấp cho vùng hình ảnh một chiều cao cố định trong bố cục để trang có hình dạng phù hợp ngay từ lần hiển thị đầu tiên thay vì nhảy khi hình ảnh thật xuất hiện.","**2. Thay đổi kích thước và nén.** Khi có ảnh thật, hãy chạy ảnh đó qua [[image-resizer|Image Resizer]] ở độ rộng 1600px, sau đó là [[image-compressor|Image Compressor]] ở mức 75 phần trăm. Đó là một tập tin bạn có thể gửi.","**3. Kiểm tra độ tương phản của văn bản.** Tiêu đề trên ảnh là lỗi tương phản cổ điển. Sử dụng [[contrast-checker|Contrast Checker]] để chọn cường độ lớp phủ tối hoặc màu văn bản sáng vượt qua AA.","**4. Tạo nút.** [[box-shadow-generator|Box Shadow Generator]] cung cấp độ cao và [[color-converter|Color Converter]] chuyển màu thương hiệu thành định dạng mà CSS cần.","**5. Gửi.** Thêm một favicon từ [[favicon-generator|Favicon Generator]] để tab trông không bị bỏ rơi và phần này đã hoàn tất."]},{"p":"Năm công cụ, không có bộ thiết kế và mỗi đầu ra là một giá trị mà bạn có thể dán thẳng vào mã."},{"h":"Câu hỏi thường gặp"},{"p":"**Hình ảnh của tôi có được tải lên bất kỳ đâu không?** Không. Quá trình nén, thay đổi kích thước và chuyển đổi Base64 đều diễn ra trong trình duyệt của bạn, đó là lý do không có giới hạn kích thước tệp và không có hàng đợi tải lên.\\n\\n**Việc nén hình ảnh có làm giảm chất lượng không?** Theo định nghĩa, luôn luôn như vậy. Câu hỏi là liệu nó có thể nhìn thấy được hay không. Ở mức 70 đến 80 phần trăm chất lượng và kích thước chính xác thì thường là không.\\n\\n**Tại sao hình ảnh đã thay đổi kích thước của tôi trông vẫn lớn?** Chín trong số mười lần bạn đã nén trước khi thay đổi kích thước hoặc bạn đang lưu dưới dạng PNG trong khi ảnh tốt hơn ở định dạng JPEG.\\n\\n**Tôi có thể sử dụng những thứ này cho công việc của khách hàng không?** Có, không có ghi công và không có hạn chế thương mại.\\n\\n**Chúng có hoạt động trên điện thoại không?** Có, mặc dù việc thay đổi kích thước và nén ảnh lớn trên điện thoại phụ thuộc vào bộ nhớ thiết bị của bạn chứ không phải máy chủ."},{"h":"Phiên bản một dòng"},{"p":"Thay đổi kích thước trước khi nén, kiểm tra độ tương phản trước khi tranh luận về màu sắc, giữ bóng tinh tế và không bao giờ quên favicon. Dù sao thì đó cũng là hầu hết những gì một bộ thiết kế đã làm cho bạn."}]},"math-tools-for-real-numbers":{"title":"6 công cụ toán học miễn phí dành cho những con số không hoạt động","description":"Ký hiệu khoa học, từ số thập phân đến phân số, kiểm tra số nguyên tố, giai thừa và GCF/LCM — các công cụ trình duyệt miễn phí dành cho công việc tính toán dễ mắc sai sót.","category":"Công cụ toán học","blocks":[{"p":"Môn toán bạn thực sự cần trên máy tính không phải là môn toán bạn đã làm bài kiểm tra. Đó là: con số này có ở định dạng mà hệ thống mong đợi không, phân số này có được đơn giản hóa không, nó tăng nhanh như thế nào và tại sao máy tính và bảng tính không đồng nhất.\\n\\nSáu công cụ này bao trùm lãnh thổ đó. Chúng chạy cục bộ, đối với số học có nghĩa là một lợi ích cụ thể đáng được đặt tên: số bạn nhập không được gửi đi bất cứ đâu, vì vậy bạn có thể kiểm tra phép tính liên quan đến tiền lương, số dư hoặc số liệu khách hàng mà không cần suy nghĩ kỹ."},{"h":"Đưa số vào dạng mà máy chấp nhận"},{"p":"Máy tính lưu trữ phân số thập phân dưới dạng phân số nhị phân. 0,1 không thể biểu thị chính xác trong hệ nhị phân — giá trị có độ chính xác kép gần nhất là 0,1000000000000000055511151231257827. Thêm 0,1 + 0,2 và bạn nhận được 0,3000000000000000004, được in là 0,3 theo mặc định và lặng lẽ phá vỡ kiểm tra đẳng thức."},{"l":["[[scientific-notation|Scientific Notation Converter]] — di chuyển giữa dạng tiêu chuẩn và dạng khoa học, đó là cách hầu hết nhật ký, bảng tính và API thực sự lưu trữ số lượng lớn và nhỏ.","[[phân số thập phân|Phân số thập phân thành phân số]] — chuyển đổi một số thập phân thành một phân số chính xác. Đây là cách khắc phục sự cố trên: 0,1 + 0,2 trong số học phân số chính xác là 3/10, không phải là xấp xỉ."]},{"b":"Nếu bạn đã từng thấy tổng sai 0,0000000000000004 thì đây là lý do. Trong mã tài chính, câu trả lời tiêu chuẩn là tính bằng xu nguyên hoặc trong thư viện thập phân và không bao giờ tính bằng dấu phẩy động. Nếu bạn đã từng thấy một bảng tính không đồng ý với một kịch bản dù chỉ một phần nhỏ, thì đó chính là lỗi tương tự đang đội một chiếc mũ khác."},{"p":"Cần phải thông thạo các ký hiệu khoa học vì đó là sự khác biệt giữa việc đọc một dòng nhật ký và nheo mắt nhìn nó. 6.022e23, 1.6e-19 và 3e8 là số Avogadro, điện tích cơ bản và tốc độ ánh sáng. Nếu những thứ đó trông giống như tiếng ồn hơn là số, việc chuyển đổi một số thông qua công cụ sẽ khắc phục vấn đề đó vĩnh viễn."},{"h":"Số nguyên tố và tại sao mọi người quan tâm"},{"l":["[[prime-checker|Prime Number Checker]] — kiểm tra xem một số có phải là số nguyên tố hay không và xem hệ số hóa của nó khi số đó không phải là số nguyên tố.","[[gcf-máy tính|Máy tính GCF LCM]] — ước chung lớn nhất và bội chung nhỏ nhất."]},{"p":"Số nguyên tố không phải là bài tập ở trường. Tính bảo mật của mọi kết nối HTTPS mà bạn thực hiện phụ thuộc vào thực tế là việc nhân hai số nguyên tố lớn rất dễ dàng và việc tính ra kết quả là khó. Sự bất đối xứng đó là toàn bộ cơ sở của RSA.\\n\\nĐối với mục đích hàng ngày, việc kiểm tra số nguyên tố chủ yếu là về phân số. Rút gọn một phân số có nghĩa là chia trên và dưới cho ước chung lớn nhất của chúng và bạn không thể tìm được phân số đó nếu không phân tích thành nhân tử. Đó là lý do tại sao hai công cụ này phối hợp với nhau: kiểm tra các yếu tố, sau đó lấy GCF và LCM trong một bước."},{"p":"Nửa LCM là thứ mà mọi người hay quên, và nó là thứ giải quyết các vấn đề về lịch trình: hai sự kiện lặp lại sau mỗi 18 ngày và cứ sau 12 ngày lại trùng khớp với nhau sau mỗi 36 ngày. Số học giống nhau, ứng dụng khác nhau."},{"h":"Giai thừa và tốc độ chúng bùng nổ"},{"l":["[[máy tính giai thừa|Máy tính giai thừa]] — n! đối với các giá trị mà câu trả lời vẫn có ý nghĩa."]},{"p":"Giai thừa phát triển nhanh hơn hầu hết mọi thứ bạn gặp ở bàn làm việc. 10! là khoảng 3,6 triệu. 20! là khoảng 2,4 triệu tỷ - lớn hơn số lượng hạt cát trên Trái đất rất nhiều. 52!, số cách xáo trộn một bộ bài, là khoảng 8, theo sau là 67 chữ số.\\n\\nHậu quả thực tế là một chương trình liệt kê tất cả các hoán vị chỉ ổn ở 5 mục, có thể chấp nhận được ở 8 mục và vĩnh viễn bị kẹt ở 12. Nếu một nhiệm vụ có vẻ như sẽ không bao giờ hoàn thành và bạn đang lặp lại các hoán vị, thì đây gần như chắc chắn là lý do. Nó cũng là lập luận chống lại hầu hết các cách tiếp cận bạo lực, được nêu dưới dạng số học hơn là quan điểm."},{"h":"Chữ số La Mã và điều kỳ lạ về chúng"},{"l":["[[chữ số La Mã|Bộ chuyển đổi số La Mã]] — chuyển đổi sang và từ các chữ số La Mã."]},{"p":"Các chữ số La Mã đáng để hiểu hơn là chỉ chuyển đổi, bởi vì hệ thống tiết lộ điều gì đó về ký hiệu vị trí. Không có số 0 và không có giá trị vị trí: XI có nghĩa là mười một dù nó đại diện cho mười một cây gậy hay mười một nghìn. Đó là lý do tại sao số học bằng chữ số La Mã thực sự khó khăn và tại sao hệ thống này tồn tại qua nhiều thế kỷ chủ yếu để đếm và xác định niên đại hơn là tính toán.\\n\\nQuy tắc trừ là phần mà mọi người mắc sai lầm. IV là bốn, không phải VI; IX là chín. Đồng hồ là một ngoại lệ nổi tiếng - Big Ben sử dụng IIII thay vì IV, vì lý do mà các nhà sử học vẫn tranh cãi. Chuyển đổi thay vì rút ra là quyết định đúng đắn trong mọi trường hợp."},{"h":"Một ví dụ hoạt động: kiểm tra một phân số bằng tay"},{"p":"Một công thức nấu ăn cần 0,375 cốc và một cái cân đọc bằng gam, một báo cáo trích dẫn tỷ lệ là 0,625 và cả hai đều trông giống như những con số ai đó gõ vội."},{"l":["**1. Tìm phân số chính xác.** Chạy 0,375 thông qua công cụ [[phân số thập phân|Phân số thập phân]]: 3/8. Chạy 0,625: 5/8. Bạn cũng không cần có thói quen tính toán.","**2. Đơn giản hóa tỷ lệ.** Để biểu thị 3/8 so với 5/8, bạn cần GCF là 3 và 5. [[gcf-máy tính|Máy tính GCF LCM]] cho kết quả 1, do đó tỷ lệ là 3:5 và đã đơn giản nhất.","**3. Kiểm tra xác nhận giai thừa.** Nếu ai đó cho bạn biết một hàng gồm 9 đơn hàng có 362.880 cách sắp xếp, thì [[máy tính giai thừa|Máy tính giai thừa]] sẽ xác nhận 9! chính xác là vậy. Bây giờ bạn biết liệu ước tính thời gian xây dựng có hợp lý hay không.","**4. Bình thường hóa mọi nội dung lớn.** Một máy chủ báo cáo 1,5e9 nano giây là 1,5 giây, theo [[ký hiệu khoa học|Bộ chuyển đổi ký hiệu khoa học]] — đây là sự khác biệt giữa vấn đề về độ trễ và thành phần làm tròn."]},{"h":"Những công cụ này cố tình không làm gì"},{"p":"Họ không thể hiện công việc và họ không dạy. Nếu bạn cần hiểu tại sao một công thức lại đúng thì máy tính là một công cụ sai lầm - nó đưa ra câu trả lời mà không có lý do, đó là lý do tại sao mọi người cuối cùng có thể tính toán và không thể suy luận.\\n\\nHọ cũng không làm độ chính xác tùy ý. Các giai thừa và hệ số hóa lớn sẽ mất độ chính xác khi câu trả lời vẫn còn hữu ích và tab trình duyệt không phải là hệ thống đại số máy tính. Đối với bất cứ điều gì mà tính chính xác thực sự quan trọng - kỹ thuật, tài chính, mật mã - hãy sử dụng thư viện thích hợp với số học chính xác chứ không phải trang web."},{"h":"Kiểm tra số học của riêng bạn"},{"p":"Thói quen toán học có giá trị nhất không phải là tốc độ mà là sự ước lượng. Trước khi tin vào bất kỳ kết quả nào, hãy hỏi xem nó có đúng thứ tự độ lớn hay không: lớn hơn hay nhỏ hơn đầu vào và khoảng bao nhiêu. Hầu hết các lỗi số học đều tồn tại sau mỗi lần kiểm tra khác ngoại trừ lần kiểm tra này.\\n\\nLàm tròn đầu tiên giúp ước tính miễn phí. Làm tròn 0,375 thành 0,4, làm tròn 5/8 thành 0,6 và tỷ lệ rõ ràng là khoảng 2:3 - đủ gần với 3:5 để xác nhận phân số bạn đã tính chính xác. Nếu câu trả lời chính xác và ước tính không giống nhau, thì bạn đã tìm thấy lỗi đầu vào chứ không phải vấn đề làm tròn và bạn đã tìm ra lỗi đó sau vài giây.\\n\\nĐây cũng là lý do tại sao máy tính không thể thay thế cho việc suy nghĩ về những gì bạn đã hỏi. Một công cụ sẽ tính toán sai số lượng một cách hoàn hảo và cách bảo vệ duy nhất là biết câu trả lời sẽ như thế nào."},{"h":"Câu hỏi thường gặp"},{"p":"**Thông tin đầu vào của tôi có được gửi đi đâu không?** Không. Tất cả những thông tin này đều chạy cục bộ trong trình duyệt của bạn.\\n\\n**Tại sao 0,1 cộng 0,2 không bằng 0,3?** Vì cả 0,1 và 0,2 đều không thể biểu thị chính xác trong dấu phẩy động nhị phân. Tổng là 0,300000000000000004, gấp đôi gần nhất với 0,3.\\n\\n**Những giai thừa này có thể xử lý được lớn đến mức nào?** Lên tới 170 trước khi vượt quá phạm vi của một nhân đôi. Trước đó, câu trả lời được hiển thị dưới dạng ký hiệu khoa học và sau đó không còn ý nghĩa nữa.\\n\\n**Tôi có thể sử dụng kết quả đầu ra bằng mã không?** Có. Cụ thể, đối với các kết quả thập phân thành phân số, hãy sử dụng số học số nguyên trên tử số và mẫu số thay vì chuyển đổi về số thập phân."},{"h":"Phiên bản một dòng"},{"p":"Sử dụng phân số chính xác khi liên quan đến tiền, hãy nhớ rằng giai thừa phát triển nhanh hơn bạn mong đợi và việc phân tích thành thừa số nguyên tố vừa là nền tảng bảo mật vừa là thủ thuật đơn giản hóa phân số."}]},"everyday-utility-tools":{"title":"13 tiện ích miễn phí hàng ngày: Mật khẩu, mã QR, bộ hẹn giờ và mã hóa văn bản","description":"Tạo mật khẩu, xây dựng mã QR, chạy bộ hẹn giờ và đồng hồ cũng như giải mã văn bản nhị phân, hex và mật mã - tất cả đều có các công cụ trình duyệt miễn phí chạy cục bộ mà không cần có tài khoản.","category":"Công cụ tiện ích","blocks":[{"p":"Nhóm cuối cùng này là ngăn kéo rác. Mật khẩu, mã QR, đồng hồ bấm giờ, đồng hồ thế giới, lật đồng xu và bốn công cụ chuyển đổi văn bản thành các cách thể hiện khác của chính nó. Những thứ tầm thường riêng lẻ, gọi chung là những thứ bạn cần vào những thời điểm khó xử.\\n\\nĐiểm mấu chốt là tất cả 13 đều chạy cục bộ. Đối với một trình tạo mật khẩu không phải là một tính năng hay - đó là toàn bộ lý do khiến công cụ này có thể đáng tin cậy."},{"h":"Mật khẩu: phần thực sự quan trọng"},{"l":["[[password-generator|Trình tạo mật khẩu]] — tạo mật khẩu mạnh ngẫu nhiên có độ dài và bộ ký tự bất kỳ.","[[độ mạnh mật khẩu|Trình kiểm tra độ mạnh mật khẩu]] — ước tính mức độ chống đoán mật khẩu cục bộ."]},{"b":"Thực tế quan trọng nhất về độ mạnh của mật khẩu: **độ dài đánh bại độ phức tạp và việc sử dụng lại đánh bại cả hai yếu tố nguy hiểm.** Mật khẩu 16 ký tự được tạo từ các từ không liên quan sẽ mạnh hơn và dễ đánh máy hơn nhiều so với một mớ ký hiệu 10 ký tự. Trong khi đó, một mật khẩu được sử dụng lại bị vi phạm sẽ xóa mọi tài khoản mà nó chạm vào cùng một lúc. Tạo một mật khẩu dài riêng biệt cho mỗi trang web là toàn bộ công việc."},{"p":"Sức mạnh được ước tính như thế nào cũng là vấn đề. Hầu hết các trình kiểm tra đều gần đúng kích thước của không gian tìm kiếm, đây là một proxy hợp lý nhưng không phải sự thật: `CorregHorseBatteryStaple` đạt điểm cao về entropy, trong khi `P@ssw0rd1!` đạt điểm cao về sự đa dạng ký tự và tệ trong thực tế vì nó xuất hiện trong mọi danh sách từ bẻ khóa trên trái đất.\\n\\nSử dụng trình tạo cho bất kỳ điều gì bạn quan tâm và nếu bạn phải nhớ mật khẩu, hãy sử dụng cụm mật khẩu gồm bốn hoặc năm từ không liên quan. Đó là trường hợp cụ thể mà khả năng ghi nhớ và sức mạnh thực sự trùng lặp."},{"h":"Mã QR: nên đặt gì vào chúng"},{"l":["[[qr-code-generator|Trình tạo mã QR]] — tạo mã QR cho URL, văn bản, chi tiết Wi-Fi hoặc thông tin liên hệ."]},{"p":"Mã QR là một trong những công cụ mà chất lượng đầu ra hoàn toàn được xác định bởi một quyết định: lượng dữ liệu bạn đưa vào. Một URL ngắn mã hóa thành một mã nhỏ, dễ quét. Một đoạn văn bản có dấu câu sẽ mã hóa thành thứ gì đó dày đặc và không đáng tin cậy ở kích thước nhỏ.\\n\\nHai quy tắc thực tế. Trước tiên, hãy luôn quét thử mã ở kích thước thực sự sẽ được in trước khi bạn in hai trăm mã. Thứ hai, mã Wi-Fi và mã URL đơn giản hoạt động khác nhau trên các điện thoại khác nhau — nếu mã hướng tới đối tượng hỗn hợp, hãy ưu tiên URL đơn giản hơn trang đích sau đó liên kết trở đi vì mã này hoạt động ở mọi nơi và bạn có thể thay đổi vị trí trỏ đến."},{"h":"Thời gian: bộ tính giờ, đồng hồ và bẫy theo múi giờ"},{"l":["[[đồng hồ bấm giờ|Đồng hồ bấm giờ trực tuyến]] — một loại đồng hồ bấm giờ đơn giản, hữu ích khi điện thoại của bạn ở phòng khác.","[[pomodoro-timer|Bộ đếm thời gian Pomodoro]] — các khối tập trung 25 phút có thời gian nghỉ giải lao, dành cho những người thấy cấu trúc đó hoạt động.","[[world-clock|World Clock]] — thời gian hiện tại ở một số thành phố cùng một lúc."]},{"p":"Đồng hồ thế giới giành được vị trí của nó vì một lý do cụ thể: tiết kiệm ánh sáng ban ngày. Một nửa sai lầm về lịch trình của thế giới không phải là lỗi số học, đó là thời điểm hai thành phố cách nhau bốn giờ vào tuần trước và năm giờ trong tuần này và không ai kiểm tra.\\n\\nTrước khi lên lịch cho bất kỳ điều gì theo múi giờ, hãy đặt cả hai thành phố vào đồng hồ thế giới và xem xét - không tính toán phần bù từ bộ nhớ. Đây cũng là lý do tại sao lời mời họp nên ghi rõ múi giờ thay vì ghi rõ giờ."},{"p":"Trên bộ đếm thời gian Pomodoro: kỹ thuật này hoạt động cho một loại nhiệm vụ cụ thể - có giới hạn, tập trung, không bị gián đoạn. Nó không hoạt động để gỡ lỗi, trong đó động thái đúng khi bị mắc kẹt là bỏ đi, không bắt đầu một khối 25 phút khác. Hãy sử dụng nó khi nó giúp ích."},{"h":"Sự ngẫu nhiên, một cách trung thực"},{"p":"[[random-number|Random Number Generator]] và [[list-randomizer|List Randomizer]] bao gồm các trường hợp thực sự xảy ra: chọn một số trong một phạm vi và sắp xếp danh sách theo thứ tự hợp lý. Đáng một câu về sự công bằng. Cả hai đều sử dụng một trình tạo giả ngẫu nhiên, để quyết định ai trả tiền cho bữa trưa thì không thể phân biệt được với một đồng tiền thật. Đối với bất kỳ điều gì mang tính hệ quả - rút thăm có giải thưởng, phân bổ kèm theo tiền - bạn muốn có một nguồn mà bạn có thể kiểm tra và tab trình duyệt thì không như vậy. Giá trị ở đây là loại bỏ con người, những người sẽ chọn sai khi có động cơ."},{"h":"Ngăn kéo rác mã hóa"},{"p":"Bốn công cụ di chuyển văn bản giữa các cách trình bày. Không có cái nào trong số chúng là mã hóa, và cần phải nêu rõ sự khác biệt vì nó thường bị nhầm lẫn: bất kỳ ai cũng có thể đảo ngược mã hóa và không có khóa. Mã hóa yêu cầu một khóa."},{"l":["[[binary-text|Binary to Text]] — chuyển đổi giữa văn bản và biểu diễn nhị phân của nó.","[[hex-text|Hex to Text]] — chuyển đổi giữa văn bản và hex, cách thể hiện mà bạn thấy thường xuyên nhất trong các công cụ mạng và trình gỡ lỗi.","[[caesar-cipher|Caesar Cipher]] — dịch chuyển các chữ cái theo một lượng cố định, mật mã cổ điển trong lớp học.","[[rot13-encoding|Bộ mã hóa ROT13]] — xoay các chữ cái đi 13, một trường hợp đặc biệt là nghịch đảo của chính nó."]},{"p":"Đây là hữu ích cho chính xác hai điều. Đầu tiên, hiểu cách văn bản trở thành byte, đây là mô hình tinh thần mà bạn cần bất cứ khi nào mọi thứ trông có vẻ bị cắt xén. Thứ hai, thực sự gỡ lỗi: khi một tải trọng hiển thị dưới dạng hex, trình chuyển đổi [[hex-text|Hex to Text]] là cách bạn tìm hiểu nội dung của nó.\\n\\nChúng không hữu ích để che giấu bất cứ điều gì. ROT13 không có khóa - ca làm việc được công khai - vì vậy nó không giấu bất kỳ ai biết ROT13 là gì. Mật mã Caesar có 25 lần dịch chuyển có thể xảy ra mà con người có thể giải quyết trong phút đầu tiên."},{"h":"Hai cái định dạng mọi thứ"},{"l":["[[phone-formatter|Phone Number Formatter]] — chuẩn hóa số điện thoại thành một định dạng nhất quán.","[[file-size-converter|Bộ chuyển đổi kích thước tệp]] — chuyển đổi giữa KB, MB, GB và TB, với giải thích về sự phân biệt thập phân và nhị phân."]},{"p":"Trình chuyển đổi kích thước tệp có một đầu ra thực sự có giá trị: nó cho bạn biết lý do tại sao ổ đĩa quảng cáo số lượng lớn hơn báo cáo mà máy tính của bạn báo cáo. Các nhà cung cấp bán sức mạnh của mười, hệ điều hành báo cáo sức mạnh của hai, và khoảng cách là khoảng 7 phần trăm ở mọi quy mô. Đó không phải là lỗi, đó là hai quy ước."},{"h":"Một ví dụ hoạt động: phản hồi API bị cắt xén"},{"p":"Một webhook không xác thực được và tải trọng trong nhật ký trông giống như `\\\\x48\\\\x65\\\\x6c\\\\x6c\\\\x6f`. Đây là chẩn đoán thứ chín mươi giây."},{"l":["**1. Chuyển đổi.** Dán `48656c6c6f` vào trình chuyển đổi [[hex-text|Hex to Text]] — kết quả là `Hello`. Nó không bao giờ bị cắt xén, chỉ được mã hóa.","**2. Kiểm tra hình dạng.** Có gì đó ngược dòng đang mã hóa hex tải trọng trước khi ký. Chữ ký đã được tính toán trên văn bản gốc và được xác thực theo hệ thập lục phân, do đó việc so sánh không thành công.","**3. Loại trừ hướng khác.** Nếu nhật ký hiển thị văn bản có thể đọc được thì vấn đề sẽ ngược lại: ký vào biểu mẫu được mã hóa.","**4. Xác nhận xác nhận kích thước.** Nếu cùng một nhật ký báo cáo tải trọng 1,2 MB, [[file-size-converter|File Size Converter]] sẽ quyết định xem đó là số thập phân hay nhị phân trước khi bất kỳ ai tranh luận về hạn ngạch."]},{"h":"Câu hỏi thường gặp"},{"p":"**Trình tạo mật khẩu có an toàn không nếu mọi thứ chạy trong trình duyệt?** Có, và còn hơn thế nữa so với trình tạo mật khẩu dựa trên máy chủ: mật khẩu được tạo trên máy của bạn và không bao giờ được truyền đi, do đó không có gì có thể chặn, ghi nhật ký hoặc vi phạm. Sự đánh đổi là bạn không thể khôi phục mật khẩu mà bạn không lưu.\\n\\n**Tôi có thể tin tưởng vào việc lật đồng xu ảo không?** Đối với các quyết định thông thường, có. Đối với bất kỳ thứ gì có tiền hoặc giải thưởng kèm theo, hãy sử dụng nguồn mà bạn có thể kiểm tra.\\n\\n**Mật mã có an toàn không?** Không. Không có mật mã nào cả. Mật mã ROT13 và Caesar không có khóa bí mật và tồn tại để dạy mã hóa chứ không phải để bảo vệ bất cứ thứ gì.\\n\\n**Những thứ này có hoạt động ngoại tuyến không?** Sau khi tải xong một trang, có — mọi thứ đều cục bộ.\\n\\n**Có giới hạn về độ dài văn bản đối với bộ chuyển đổi không?** Chỉ có bộ nhớ thiết bị của bạn vì không có gì được gửi đi bất cứ đâu."},{"h":"Phiên bản một dòng"},{"p":"Mật khẩu dài duy nhất đánh bại mật khẩu ngắn thông minh, mã QR chỉ tốt khi dữ liệu bên trong nó, kiểm tra chênh lệch múi giờ thay vì tính toán chúng và mã hóa không phải là mã hóa."}]}}')},73519,93379,e=>{"use strict";let a=[{slug:"browser-tools-for-developers",metaTitle:"24 Free Browser Tools Every Developer Should Bookmark (2026)",title:"The Developer's Toolkit: 24 Free Browser Tools That Replace Paid Apps",description:"A practical guide to formatting, converting, encoding and debugging data using free browser-based developer tools — no installs, no accounts; most tools process input locally.",date:"2026-10-20",updated:"2026-10-20",readingTime:"12 min read",category:"Developer Tools",blocks:[{p:"Most of the small jobs you do a hundred times a week — reformatting an API response, decoding a token, checking a hash, indenting a slug of SQL — do not need an IDE, a paid subscription or a team licence. They need one tab open for ninety seconds.\n\nThe collection below is twenty-four browser-based utilities covering formatting, conversion, encoding, hashing and debugging. Every one of them runs entirely in your page: your data is never sent to a server, which matters more than developers usually admit, because the payload you paste is usually a customer's."},{h:"What browser-based tools can and cannot replace"},{p:"Be realistic about the boundary. These tools replace one-off, low-stakes, high-frequency chores. They do not replace your language server, your debugger, your test suite or anything you need to run against a real environment repeatedly."},{l:["**Good fit:** reading a response once, debugging a single value, converting a file for one import, checking a format before shipping.","**Bad fit:** running the same check on every deploy, transforming hundreds of files, anything that must fail loudly in CI.","**Never:** anything involving credentials you cannot rotate. Paste a revoked token, not a live one."]},{p:"With that said, the reason to keep these bookmarked is throughput. A task that takes forty seconds in a browser tab never gets scheduled, never gets delegated, and never becomes a reason to open an IDE at eight in the evening."},{h:"Formatting and converting data"},{p:"The most common daily job is making data readable. An API returns a single-line blob, a colleague sends a config file with tabs mangled by a chat window, or you exported a spreadsheet to JSON and it came back as one enormous line."},{l:['[[json-formatter|JSON Formatter]] — indent, validate and read a payload. Use it before you debug: half of all "the API is broken" tickets are actually malformed JSON with a trailing comma.',"[[json-validator|JSON Validator]] — when you need a strict pass/fail answer rather than a pretty print.","[[xml-formatter|XML Formatter]] — the same job for SOAP responses, RSS feeds and Maven POMs that nobody has touched since 2014.","[[json-to-yaml|JSON to YAML]] and [[json-to-csv|JSON to CSV]] — moving data between the formats real systems actually use."]},{p:"Keep the last group in mind for one specific scenario: a client hands you a spreadsheet and expects it in their API. Going CSV to JSON directly is a two-minute job rather than an afternoon of scripting."},{h:"Encoding and escaping"},{p:'Encoding bugs are disproportionately annoying because the data looks fine. The value "San José & Sons" arrives as "San Jos%C3%A9 %26 Sons" and your comparison against the database fails for reasons that are invisible in the logs.'},{l:["[[url-encoder|URL Encoder / Decoder]] — settle immediately whether a query string is double-encoded.","[[base64-encoder|Base64 Encoder / Decoder]] — decode a certificate fragment, or encode a small asset to inline in CSS.",'[[html-entity-encoder|HTML Entity Encoder / Decoder]] — find out whether that stray "&amp;" in your page came from your template or your data.','[[unicode-converter|Unicode Converter]] — useful when a "broken" character turns out to be a legitimate one rendered in the wrong encoding.',"[[number-base-converter|Number Base Converter]] — check a colour, a permission bitmask or a memory address without a calculator app."]},{b:"A practical habit: when a value arrives garbled, decode it one layer at a time and paste each result into a blank field. If the first decode produces readable text, the problem is one extra encode somewhere upstream. If it produces mojibake, you have an encoding problem rather than an escaping problem, and those two need different fixes."},{h:"Identifiers, hashes and tokens"},{p:"This group is where developers waste the most time hunting for the right local script that they wrote once and lost."},{l:["[[uuid-generator|UUID Generator]] — generate v4 identifiers for seed data, fixtures or a quick database row.","[[md5-generator|MD5 / SHA Hash Generator]] — verify a download or confirm that two files that should be identical actually are.","[[timestamp-converter|Timestamp Converter]] — the single most-used tool in this whole list. When a log line says 1761000000, this is what tells you whether the incident happened during the deploy or before it."]},{p:"The timestamp converter earns its keep for one specific reason: an epoch number is unambiguous and useless at the same time. You know exactly when something happened and you cannot tell a colleague. Converting once usually settles a louder argument than it should."},{h:"Comparing and debugging"},{l:["[[regex-tester|Regex Tester]] — the highest-leverage item here. A regular expression that looks correct and quietly matches nothing is one of the most expensive bugs in development, because it fails silently in the one place nobody reads.","[[html-preview|HTML Preview]] — iterate on a fragment of markup to check how it actually renders."]},{p:"Test your regular expressions against the input you actually expect, including the empty string, a Unicode name and a value with a newline. Most patterns break on the third case and nobody notices until production data arrives."},{h:"A worked example: three tools, one boring incident"},{p:"Here is the sequence that convinced me to bookmark all of this. A customer reported that a record they submitted on Tuesday was missing from a report on Thursday."},{l:["**1. Convert the timestamp.** The report job logged the record's creation time as an epoch value. The [[timestamp-converter|Timestamp Converter]] showed the record was created at 11pm local, which is Tuesday — the job's timezone assumption was the problem, not the record.","**2. Format the payload.** Taking the stored JSON through the [[json-formatter|JSON Formatter]] revealed the record was written with a null date field, because the client twice-called the same endpoint 200ms apart and the second write won.","**3. Compare the payloads.** Both records carried the same API key and the same client timestamp, which pointed at a retry rather than two separate customers."]},{p:"Total elapsed time: four minutes. The prior attempt at this investigation, which looked for the same root cause in a logging platform, took an afternoon and produced a wrong conclusion."},{h:"Privacy: why running locally is the actual feature"},{p:'Every tool in this library processes your input inside your own browser. Nothing is uploaded, which means no retention question, no processor agreement, and no uncomfortable conversation about the production payload you pasted three minutes ago.\n\nThis is the reason to prefer these tools over a hosted "pastebin API" or an online service that asks you to sign up. It also means they keep working on a flight, in a basement, or when the corporate VPN has decided to block yet another domain.'},{p:"One caveat worth stating plainly: an offline-capable page is only private if the page itself is the code you think it is. On a shared machine, use a private window and close it when you are done, especially if you have been decoding tokens."},{h:"Building a workflow around them"},{p:'The tools are individually trivial. The value is in the habit of reaching for one immediately instead of "getting to it later", because later is when you write a throwaway script, or open an IDE, or decide it is not worth checking at all.'},{l:["Bookmark the collection, not individual URLs, and put it in your browser's toolbar.","When something looks wrong, check it before you form a theory. Costs fifteen seconds; kills whole classes of wrong conclusions.","When you have checked the same thing twice, that is the signal to automate it — but do not automate on suspicion.","Do not paste production secrets. Rotate anything you are unsure about."]},{h:"Frequently asked questions"},{p:"**Are these tools free?** Yes, entirely, with no account and no usage limit. There is no paid tier holding back anything basic.\n\n**Do they work offline?** Once a page has loaded, yes — everything runs in your browser. Reloading requires a connection.\n\n**Can I use them for commercial work?** Yes. The output is yours with no attribution requirement.\n\n**Is there an API?** No, and that is deliberate — the value is the interface. Export the output and process it however you like.\n\n**Why not just install a CLI tool instead?** Install one when you need it three times. Use a browser tab for the first two."}]},{slug:"text-tools-for-writers",metaTitle:"17 Free Text Tools for Writers, Students and Marketers",title:"17 Free Text Tools for Writers, Students and Marketers",description:"Clean up copy, count words accurately, format lists and turn rough drafts into something publishable — with free browser tools that run locally in your browser.",date:"2026-10-20",updated:"2026-10-20",readingTime:"10 min read",category:"Text Tools",blocks:[{p:"Writing for work involves a surprising amount of mechanical drudgery that has nothing to do with writing: stripping stray whitespace from a pasted paragraph, checking a word limit, de-duplicating a list of names, converting something into a URL slug.\n\nThese seventeen tools are for that part of the job. They all run locally in the browser, which is not a small detail — the draft you paste is often unpublished, and the list you are sorting is often somebody's personal data."},{h:"Measuring what you have written"},{p:"Word count sounds solved until a client asks for exactly 800 words and your editor says 820, or a form rejects your text at 1,995 characters with no explanation of where the newline went."},{l:["[[word-counter|Word Counter]] — the standard measure. Paste, read, adjust.","[[letter-counter|Letter Counter]] — counts characters and letter frequency. Useful when you are debugging why one paragraph feels wrong: it is usually a repeated letter pattern, not a dream."]},{p:'A note on what "a word" means: different counters disagree on hyphenation, numbers and URLs. If an exact number matters, use the same counter the person checking your work uses, and agree on it in advance. This is a genuinely common source of small, pointless arguments.'},{h:"Cleaning up copy you did not write"},{p:"Most text you receive is slightly damaged: double spaces from a copy-paste, a stray tab, inconsistent capitalisation from someone typing in a hurry. Fixing it by hand is slow and error-prone."},{l:['[[text-trimmer|Text Trimmer]] — remove leading and trailing whitespace from every line at once. This fixes more "formatting looks broken" reports than anything else on this list.',"[[text-case-converter|Text Case Converter]] — switch between sentence case, title case, upper and lower across a block. Also the fastest way to undo an accidental CAPS LOCK paragraph.","[[text-to-slug|Text to Slug]] — turn a headline into a clean URL slug. Paste your title, get the slug, done."]},{p:"The slug generator has one use beyond URLs: it is a fast way to make a readable filename or anchor that a human can parse at a glance, which beats `final_final_v3`."},{h:"Working with lists"},{p:"Listicles, inventories, mail merges, tag cleanups, survey responses, spreadsheet columns — at some point everything becomes a list and every list needs sorting, de-duplicating or randomising."},{l:["[[duplicate-line-remover|Duplicate Line Remover]] — compare two lists, or clean one. The output tells you how many duplicates were removed, which is useful when you are reporting the result.","[[list-sorter|List Sorter]] — the same job for structured list input.","[[list-randomizer|List Randomizer]] — shuffle a draw order, a quiz sequence or a ring-fenced shortlist so nobody suspects favouritism.","[[line-number-adder|Line Number Adder]] — number lines for reference in a ticket or a code review comment."]},{b:"The classic trap here is a list that looks de-duplicated but is not: `Apple`, `apple ` and `Apple.` are three different lines to a computer. Trim whitespace and strip trailing punctuation before you dedupe, or you will merge nothing and conclude the data is clean."},{h:"Previewing and formatting"},{p:"Markdown has won, but not uniformly. Half your tools render it, half do not, and the half that does not is usually the one someone senior has to paste into."},{l:["[[markdown-preview|Markdown Preview]] — live rendering, so you can check a table or a nested list actually looks right before it reaches a client.","[[text-repeater|Text Repeater]] — repeat a string N times. Useful for generating padding, test data or, occasionally, making a point in a document."]},{p:"The Markdown preview is the tool that quietly saves the most time in this whole set, because a broken table in a rendered document is far more visible — and far more embarrassing — than a broken table in raw text."},{h:"The rest, and when to reach for them"},{l:["[[random-string|Random String Generator]] — generate readable nonces, placeholder IDs or short codes. Better than inventing something by hand, because you will not accidentally reuse it.","[[morse-code|Morse Code Translator]] — genuinely fun, occasionally useful for a themed project or a puzzle."]},{p:'These are lower-frequency tools, but they cost nothing to keep bookmarked and they solve the specific problem of "I need a random-looking value right now and I do not trust myself to make one up".'},{h:"A realistic editing pass"},{p:"Here is the order that works when a draft arrives from someone else and needs to go out under your name."},{l:["**1. Trim.** Run the whole document through the [[text-trimmer|Text Trimmer]] first. Whitespace damage hides inside paragraphs where you will never see it.","**2. Clean case.** Use the [[text-case-converter|Text Case Converter]] for the headline only. Never apply case conversion to a full draft — it destroys proper nouns.","**3. Measure.** Check length with the [[word-counter|Word Counter]] before writing, so you know what shape the piece is meant to be.","**4. Preview.** If it contains Markdown, render it with the [[markdown-preview|Markdown Preview]].","**5. Slug.** Generate the URL slug last, from the final headline, with [[text-to-slug|Text to Slug]] — changing the headline afterwards breaks the slug."]},{p:"The whole pass takes a few minutes and eliminates the category of mistake where a document is technically correct and visibly wrong."},{h:"Writers' questions about privacy"},{p:"**Does my unpublished text leave my computer?** No. These tools process text in your browser and nothing is stored or transmitted.\n\n**Is there a length limit?** There is no server-side limit because there is no server call. Extremely large inputs are limited by your own device's memory.\n\n**Can I use the output commercially?** Yes, freely, with no attribution.\n\n**Do they work on a phone?** Yes. The layout adapts, and the same code runs."},{h:"What these tools will not do for you"},{p:"Worth being blunt about the limits, because a tool that mechanises the wrong thing just produces a faster mistake.\n\nNone of these utilities can tell you whether a sentence is clear, whether a claim is sourced, or whether a tone is right for the audience. They count characters; they do not judge prose. A text that scores beautifully on every metric on this page can still be unreadable.\n\nNor do they edit. The moment you find yourself rewriting individual clauses by hand at scale, you have outgrown a text tool and you want either a proper editor, a find-and-replace with regex — which the [[regex-tester|Regex Tester]] is genuinely good for rehearsing — or a script. Use the browser for the mechanical layer, and keep your own judgement for everything above it."},{p:'One more thing they will not do is fix a bad source. If your spreadsheet is full of inconsistent naming — "Dr", "DR", "Dr." all in one column — a tool will sort and de-duplicate what you gave it faithfully, and you will still have three entries where there should be one. Cleaning the data is a decision, not a mechanical step. Decide the canonical form first, then apply it, then check.'},{h:"Keeping a working list usable"},{p:"If you maintain a list of leads, links, references or terms, it degrades quietly. The failure mode is always the same: entries that look identical are not, and one merge removes nothing.\n\nA maintenance pass that works is boring: trim whitespace, standardise capitalisation, strip trailing punctuation, then de-duplicate. In that order — trimming after de-duplicating loses entries. Doing this once a month on an active list turns a two-hour unrecoverable mess into a ten-minute chore.\n\nWhen two lists need reconciling — say, a registration list against an attendance list — sort both with the [[list-sorter|List Sorter]] first, so they line up, then compare by eye. Sorting both sides before comparing is the difference between a two-minute check and a twenty-minute hunt."},{h:"The takeaway"},{p:"None of these tools is clever. That is the point: they remove the mechanical five percent of writing that is not writing, so the remaining ninety-five percent is actually about sentences. Bookmark the ones you use monthly, ignore the rest, and stop fixing whitespace by hand."}]},{slug:"calculators-and-converters-guide",metaTitle:"18 Free Calculators and Converters for Everyday Numbers",title:"18 Free Calculators and Converters for the Numbers You Actually Deal With",description:"Percentages, discounts, tips, loans, dates, BMI and unit conversions — free browser calculators that show their reasoning, with no account required.",date:"2026-10-20",updated:"2026-10-20",readingTime:"11 min read",category:"Calculators",blocks:[{p:"Everybody needs to split a bill, work out whether a discount is genuinely a discount, and convert a temperature or a file size without thinking about it. Everybody also, at least once, gets this wrong in public.\n\nThis is a collection of eighteen calculators and converters covering money, dates, health, and the unit conversions that show up in work and travel. All of them run in the browser: nothing is saved, so the numbers you type are nobody's business but yours."},{h:"Money calculations"},{p:"The most common real-world math is a percentage of something. Sales tax, a tip, a discount stack, a commission, a growth rate. The formula is simple, and yet the reason people get it wrong is almost always the same: they apply a percentage to the wrong base."},{l:['[[discount-calculator|Discount Calculator]] — work out the final price and, more importantly, how much you saved. Useful for spotting a "50% off" that is really 20% after a raised list price.',"[[tip-calculator|Tip Calculator]] — split a bill, pick a percentage, round per person if you want to.","[[loan-calculator|Loan Calculator]] — monthly payment and total interest, which is the number that actually decides whether a loan is affordable."]},{b:"On discounts: a 20% discount followed by another 20% discount is not 40% off — it is 36%. Sequential percentages compound on the reduced base. Any calculator in this list will confirm it in about two seconds, and it is the single most useful arithmetic fact in this article."},{p:"The loan calculator deserves a specific note. The number that matters is not the monthly payment — it is the total interest paid over the life of the loan, because that is the real cost of borrowing. Two loans with identical monthly payments and different terms can differ by tens of thousands in total interest."},{h:"Dates and countdowns"},{p:'Date arithmetic is where most people silently get it wrong, because human months have different lengths and the answer changes depending on whether you mean "calendar months" or "30 days".'},{l:["[[date-difference|Date Difference Calculator]] — days (and total months, years) between two dates.","[[days-until|Days Until Calculator]] — a countdown to a specific date, with the number of working days usually being what people actually want.","[[age-calculator|Age Calculator]] — exact age in years and days, plus the next birthday.","[[timestamp-converter|Timestamp Converter]] — a Unix timestamp into a real date, which matters if you touch logs, databases or API responses."]},{p:"The distinction that trips people up: the number of days between March 1 and April 1 is 31, but the number of *months* is one. If you are calculating a notice period or a subscription term, state which unit you mean, in writing."},{h:"Health numbers, honestly"},{l:["[[bmi-calculator|BMI Calculator]] — body mass index with the standard categories, and the caveats below."]},{p:"BMI is a population-level screening statistic. It says nothing about muscle mass, body composition, or any individual's health, and it is a poor proxy for fitness in athletes, in older adults, and across different ethnic groups. Use it as one data point among several, or as a way to track a change over time — not as a verdict. If you are making decisions that affect your health, the right tool is a clinician, not a browser tab."},{h:"Unit conversion: the everyday ones"},{p:"Unit conversion is divided into two kinds: conversions you must get exactly right, and conversions you need roughly. These tools handle both, and the work is in remembering which is which."},{l:["[[length-converter|Length Converter]] — metric to imperial and back: millimetres, centimetres, metres, kilometres, inches, feet, yards, miles.","[[weight-converter|Weight Converter]] — grams, kilograms, ounces, pounds, tonnes. The one to check before a recipe or a shipping label.","[[temperature-converter|Temperature Converter]] — Celsius, Fahrenheit, Kelvin. Because -10°C is not 14°F, and the formula is not a multiplication.","[[speed-converter|Speed Converter]] — km/h, mph, m/s, knots. Useful for a foreign speed limit or an engineering spec.","[[area-converter|Area Converter]] — square metres, square feet, acres, hectares. This is the one people estimate badly when buying or renting property.","[[volume-converter|Volume Converter]] — litres, millilitres, gallons, cups, cubic metres.","[[time-converter|Time Converter]] — seconds, minutes, hours, days, weeks."]},{b:"Two conversion traps worth knowing: the data-storage one above (marketers sell 10^3, operating systems report 2^10), and fuel economy — a car quoted at 40 mpg (imperial) is closer to 33 mpg (US) than 40, because the imperial gallon is larger. Getting the second one wrong makes a rental car look unrealistically efficient."},{h:"The two you will not expect to need"},{l:["[[random-number|Random Number Generator]] — draws within a range, for a raffle, a bracket, or a quick A/B split. Useful precisely because it removes the suspicion that you rigged it.","[[dice-roller|Dice Roller]] — any die from a coin flip to a twenty-sided die, for a board game or a tabletop session where the real die has rolled off the table for the last time."]},{h:"Using a calculator properly"},{p:"A calculator only helps if you know which number you are asking it about. Three habits make the difference."},{l:["**Round first, compute second.** If the precise number does not change your decision, use a round one. Percentages of round numbers are checkable in your head, which catches input errors.","**Sanity-check the magnitude.** Before believing a result, ask whether it should be bigger or smaller than the input, and by roughly how much. Most arithmetic mistakes survive every check except this one.","**Photograph the inputs, not the output.** When you re-run the calculation later, what matters is knowing what you assumed, not what you concluded."]},{h:"Questions people actually ask"},{p:"**Are my numbers stored anywhere?** No. The calculations happen in your browser and nothing is transmitted or retained.\n\n**Do these work on a phone?** Yes, and the calculators are built for one-handed use.\n\n**Which conversion standard do you use for data storage?** Decimal (1 KB = 1000 bytes) by default, because that is how storage is sold. Operating systems report binary, which is why a drive appears to shrink — the tool explains the difference rather than silently picking a side.\n\n**Can I embed these on my own site?** No. Bookmark them instead; the cost of that is zero and the accuracy problem is yours to own."},{h:"Percentages: the four mistakes that matter"},{p:"Almost every percentage error a person makes in daily life is one of the same four mistakes. Naming them makes them avoidable."},{l:['**Wrong base.** "A 10% rise then a 10% fall leaves you where you started" is false, because both apply to different bases. Ten per cent of 100 is 10; ten per cent of 90 is 9.',"**Percentage of a percentage.** Stacking two discounts multiplies them (0.8 × 0.8 = 0.64, so 36% off), it does not add them.","**Percent versus percentage points.** A rate going from 4% to 6% has risen by 2 percentage points, but by 50% in relative terms. Politics and medicine are full of this confusion, and it is not always accidental.","**Rounding too early.** Rounding an intermediate step before applying a percentage compounds the error. Keep full precision until the final figure, and do the last step on a calculator rather than in your head."]},{p:"If you only take one habit from this whole section, take this one: before quoting a percentage to anyone, restate what it is a percentage *of*. Half the arguments you will ever have about a number are actually arguments about the denominator."},{h:"Knowing when to stop calculating"},{p:"There is a point where precision stops being useful. A monthly payment to two decimal places is meaningful. A projected total cost to eight decimal places is a way of avoiding the actual decision, which is whether the loan fits inside what you can afford without stress.\n\nThe useful test is the sensitivity question: does the decision change if this input moves by 10%? If not, stop refining it and use the extra time on the variable that does move the answer — usually the term rather than the rate, or the list price rather than the discount."},{p:"And one boundary worth stating plainly: these calculators are arithmetic, not advice. A savings target, a retirement date and a debt payoff plan are all decisions about risk, behaviour and time, and a browser tab cannot weigh any of those. It can only tell you what the numbers imply once you have decided what you are assuming. That distinction is the difference between a calculator being useful and being responsible."},{h:"The one-line version"},{p:"Bookmark the money and date calculators properly, treat BMI as one signal rather than a verdict, remember that stacked percentages multiply, and check a unit conversion whenever a number is going into anything contractual. That covers almost everything."}]},{slug:"image-and-design-tools",metaTitle:"14 Free Image and Design Tools That Run in Your Browser",title:"14 Free Image and Design Tools That Run in Your Browser",description:"Compress, resize and prepare images, and generate CSS effects, palettes, contrast checks and favicons without installing Photoshop or a design suite.",date:"2026-10-20",updated:"2026-10-20",readingTime:"11 min read",category:"Design Tools",blocks:[{p:"Image work has a specific problem: the job is usually small, and the tools on offer are enormous. You need to shave 400 KB off a hero image, or get a hex value your designer mentioned, or generate a favicon nobody has made yet. That does not require a subscription.\n\nThe fourteen tools below cover preparing images, working with colour, generating CSS effects, and the small production assets that fall through the cracks. Every one runs locally, which matters more for images than for text: the photo you just compressed is often a photo you have not published yet."},{h:"Preparing images for the web"},{p:"Most image problems are really weight problems. A page that feels slow is usually carrying images that are larger than their display size, in the wrong format, at a quality setting nobody ever questioned."},{l:["[[image-compressor|Image Compressor]] — reduce file size while keeping the image visually intact. Run it before you upload anything to a form with a size limit.","[[image-resizer|Image Resizer]] — set the actual pixel dimensions you need. This is the bigger win: a 4000px image displayed at 800px is carrying five times the data it needs.","[[image-to-base64|Image to Base64]] — convert a small image into a data URI for inlining in CSS, HTML or an email template."]},{b:"The order matters. Resize first, compress second. Compressing a 4000px image produces a much heavier file than resizing to 800px and then compressing at the same quality, because compressors spend their effort on pixels that were going to be thrown away anyway."},{p:"How much should you compress? The honest answer is: until it looks wrong, then back off one step. For a photographic hero image, 70 to 80 percent quality is usually indistinguishable from the original at normal viewing size. For a logo, a screenshot or anything with flat colour and hard edges, use PNG and compress harder — these gain more and lose less."},{p:"A practical rule of thumb: anything under 200 KB is fine for a hero image, under 80 KB for a thumbnail, and if you cannot get under 300 KB you probably have a dimension problem rather than a quality problem."},{h:"Base64: when inlining is the right call"},{p:"Converting an image to a Base64 data URI removes an HTTP request, which sounds like a pure win. It usually is not. The encoded string is roughly a third larger than the binary file, it cannot be cached separately, and it bloats your CSS or HTML.\n\nInline only when the image is small — under a few kilobytes — used once, and critical. A tiny icon in a single email template is the classic case. For anything repeated across pages or larger than a few kilobytes, serve it as a file and let the browser cache it."},{h:"Watermarks: what is honestly removable"},{l:[]},{p:"Be clear about what this does. It removes or obscures the visible mark. It cannot reconstruct the underlying pixels — information that was painted over is gone, and no filter invents it back. Results range from invisible, when the mark sits over a plain background, to an obvious smear when it sits over detail.\n\nOne more thing worth saying plainly: removing somebody else's watermark and publishing the result is a copyright problem in most jurisdictions, and a licensing violation regardless of whether you would get caught. Removing marks from your own images, or from stock you have licensed, is the case this tool is for."},{h:"Colour: converting, checking, choosing"},{p:"Colour is where small mistakes become very visible. A contrast ratio that fails accessibility, a hex value that is actually an HSL triple, a palette that looks coherent on your monitor and muddy on a projector."},{l:["[[color-converter|Color Converter]] — move between HEX, RGB and HSL. HSL is worth learning to read, because hue 210, saturation 40 percent, lightness 50 percent is far easier to adjust by hand than a hex value.","[[contrast-checker|Contrast Checker]] — test text against its background against WCAG thresholds. This is the single most useful tool in this article, because it catches a real compliance problem rather than a taste problem.","[[color-palette|Color Palette Generator]] — generate a coherent set when you are starting from a brand colour and need the rest of the scale."]},{b:"On contrast: WCAG AA asks for 4.5 to 1 for normal body text and 3 to 1 for large text. If you are choosing between two brand colours for a button, the accessible one is usually not the one the designer likes. Check first, then have the argument with data."},{p:"One caveat on colour tools: they all assume your monitor is calibrated and that the person viewing your page has working eyes. Neither assumption is safe. That is a reason to prefer contrast-checked combinations over subjective ones."},{h:"CSS effects without opening a design tool"},{p:"Writing a gradient or a layered shadow by hand is a genuinely unpleasant task. The syntax is fiddly, you cannot see what you are producing, and the difference between a good shadow and a bad one is a few pixels of blur."},{l:["[[gradient-generator|CSS Gradient Generator]] — build linear and radial gradients and copy the CSS directly.","[[box-shadow-generator|Box Shadow Generator]] — layer multiple shadows, which is what separates a subtle elevation from a heavy drop.","[[border-radius-generator|Border Radius Generator]] — get the asymmetric radii that make a shape look intentional.","[[text-shadow-generator|Text Shadow Generator]] — useful sparingly. Most text shadows are too strong; this lets you tune the offset and blur until it disappears."]},{p:"The trick to all four is restraint. Two shadows — a tight dark one and a wide soft one — read as physical elevation. One shadow reads as a website from fifteen years ago. Generate, copy, then delete until you cannot tell it is there."},{h:"The production assets everyone forgets"},{l:["[[favicon-generator|Favicon Generator]] — produce the small icon set a site actually needs. This is on the list because favicons are the asset most likely to be missing entirely, and a missing one shows a generic browser page icon that makes a finished site look unfinished.","[[emoji-picker|Emoji Picker]] — browse, search and copy emoji without hunting through an operating system picker. Genuinely useful when you are writing copy that needs one specific symbol."]},{h:"A worked example: shipping a hero section"},{p:"Here is the whole cluster doing one real job. A page needs a hero with a background image, a heading and a button, and none of it has been built yet."},{l:["**1. Reserve the space.** Give the image slot a fixed height in the layout, so the page has the right shape from the first render instead of jumping when the real image lands.","**2. Resize and compress.** When the real photo arrives, run it through the [[image-resizer|Image Resizer]] at 1600px wide, then the [[image-compressor|Image Compressor]] at 75 percent. That is a file you can ship.","**3. Contrast-check the text.** A heading over a photo is the classic contrast failure. Use the [[contrast-checker|Contrast Checker]] to pick either a dark overlay strength or a light text colour that passes AA.","**4. Build the button.** The [[box-shadow-generator|Box Shadow Generator]] gives the elevation, and the [[color-converter|Color Converter]] gets the brand colour into the format the CSS needs.","**5. Ship.** Add a favicon from the [[favicon-generator|Favicon Generator]] so the tab does not look abandoned, and the section is done."]},{p:"Five tools, no design suite, and every output is a value you can paste straight into code."},{h:"Frequently asked questions"},{p:"**Are my images uploaded anywhere?** No. Compression, resizing and Base64 conversion all happen in your browser, which is the reason there is no file-size limit and no upload queue.\n\n**Will compressing an image lose quality?** Always, by definition. The question is whether it is visible. At 70 to 80 percent quality and correct dimensions, it usually is not.\n\n**Why does my resized image still look large?** Nine times out of ten you compressed before resizing, or you are saving as PNG when a photo is better as JPEG.\n\n**Can I use these for client work?** Yes, with no attribution and no commercial restriction.\n\n**Do they work on a phone?** Yes, though resizing and compressing large photos on a phone depends on your device's memory rather than a server."},{h:"The one-line version"},{p:"Resize before you compress, check contrast before you argue about colour, keep shadows subtle, and never forget the favicon. That is most of what a design suite was doing for you anyway."}]},{slug:"math-tools-for-real-numbers",metaTitle:"6 Free Math Tools for Numbers That Will Not Behave",title:"6 Free Math Tools for Numbers That Will Not Behave",description:"Scientific notation, decimals to fractions, prime checking, factorials and GCF/LCM — free browser tools for the number work that is easy to get wrong.",date:"2026-10-20",updated:"2026-10-20",readingTime:"10 min read",category:"Math Tools",blocks:[{p:"The maths you actually need at a computer is not the maths you were examined on. It is: is this number in the format the system expects, is this fraction simplified, how fast does this grow, and why does the calculator and the spreadsheet disagree.\n\nThese six tools cover that territory. They run locally, which for arithmetic means one specific benefit worth naming: the number you typed is not sent anywhere, so you can check a calculation involving a salary, a balance or a customer figure without a second thought."},{h:"Getting numbers into a form a machine accepts"},{p:"Computers store decimal fractions as binary fractions. 0.1 is not exactly representable in binary — the closest double-precision value is 0.1000000000000000055511151231257827. Add 0.1 + 0.2 and you get 0.30000000000000004, which prints as 0.3 by default and quietly breaks an equality check."},{l:["[[scientific-notation|Scientific Notation Converter]] — move between standard and scientific form, which is how most logs, spreadsheets and APIs actually store large and small numbers.","[[decimal-fraction|Decimal to Fraction]] — convert a decimal into an exact fraction. This is the fix for the problem above: 0.1 + 0.2 in exact fraction arithmetic is 3/10, not an approximation."]},{b:"If you have ever seen a total that is wrong by 0.0000000000000004, this is why. In financial code the standard answer is to work in integer cents, or in a decimal library, and never in floating point. If you have ever seen a spreadsheet disagree with a script by a fraction of a penny, it is the same bug wearing a different hat."},{p:"Scientific notation is worth being fluent in, because it is the difference between reading a log line and squinting at it. 6.022e23, 1.6e-19 and 3e8 are Avogadro's number, the elementary charge and the speed of light. If those look like noise rather than numbers, converting a few through the tool fixes it permanently."},{h:"Primes, and why anyone cares"},{l:["[[prime-checker|Prime Number Checker]] — test whether a number is prime, and see its factorisation when it is not.","[[gcf-calculator|GCF LCM Calculator]] — greatest common factor and least common multiple."]},{p:"Prime numbers are not a school exercise. The security of every HTTPS connection you make depends on the fact that multiplying two large primes is easy and factoring the result back is hard. That asymmetry is the entire basis of RSA.\n\nFor everyday purposes, prime checking is mostly about fractions. Simplifying a fraction means dividing top and bottom by their greatest common factor, and you cannot find that without factoring. Which is why these two tools belong together: check the factors, then get the GCF and LCM in one step."},{p:"The LCM half is the one people forget, and it is the one that solves scheduling problems: two events that repeat every 18 days and every 12 days coincide every 36 days. Same arithmetic, different application."},{h:"Factorials, and the speed at which they explode"},{l:["[[factorial-calculator|Factorial Calculator]] — n! for values where the answer is still meaningful."]},{p:"Factorials grow faster than almost anything you meet at a desk. 10! is about 3.6 million. 20! is about 2.4 quintillion — larger than the number of grains of sand on Earth by a wide margin. 52!, the number of ways to shuffle a deck of cards, is roughly 8 followed by 67 digits.\n\nThe practical consequence is that a program that enumerates all permutations is fine at 5 items, tolerable at 8, and permanently stuck at 12. If a task feels like it will never finish and you are looping over permutations, this is almost certainly why. It is also the argument against most brute-force approaches, stated as arithmetic rather than opinion."},{h:"Roman numerals, and the odd thing about them"},{l:["[[roman-numerals|Roman Numeral Converter]] — convert to and from Roman numerals."]},{p:"Roman numerals are worth understanding rather than just converting, because the system reveals something about positional notation. There is no zero, and no place value: XI means eleven whether it represents eleven sticks or eleven thousand. That is why arithmetic in Roman numerals is genuinely difficult, and why the system survived for centuries mostly for counting and dating rather than calculation.\n\nThe subtractive rule is the part people get wrong. IV is four, not VI; IX is nine. Clocks are a famous exception — Big Ben uses IIII rather than IV, for reasons historians still argue about. Converting rather than deriving is the right call in every case."},{h:"A worked example: checking a fraction by hand"},{p:"A recipe needs 0.375 cups and a scale that reads in grams, a report quotes a ratio as 0.625, and both look like numbers somebody typed in a hurry."},{l:["**1. Find the exact fraction.** Run 0.375 through the [[decimal-fraction|Decimal to Fraction]] tool: 3/8. Run 0.625: 5/8. Neither needed a calculator habit you do not have.","**2. Simplify the ratio.** To express 3/8 against 5/8, you need the GCF of 3 and 5. The [[gcf-calculator|GCF LCM Calculator]] gives 1, so the ratio is 3:5 and already simplest.","**3. Check the factorials claim.** If someone tells you a queue of 9 orders has 362,880 arrangements, the [[factorial-calculator|Factorial Calculator]] confirms 9! is exactly that. Now you know whether the build-time estimate was plausible.","**4. Normalise anything large.** A server reporting 1.5e9 nanoseconds is 1.5 seconds, per the [[scientific-notation|Scientific Notation Converter]] — which is the difference between a latency problem and a rounding artefact."]},{h:"What these tools deliberately do not do"},{p:"They do not show working, and they do not teach. If you need to understand why a formula is true, a calculator is the wrong instrument — it gives the answer without the reason, which is how people end up able to compute and unable to reason.\n\nThey also do not do arbitrary precision. Factorials and large factorisations will lose accuracy past the point where the answer is still useful, and a browser tab is not a computer algebra system. For anything where correctness genuinely matters — engineering, finance, cryptography — use a proper library with exact arithmetic, not a web page."},{h:"Checking your own arithmetic"},{p:"The most valuable mathematical habit is not speed, it is estimation. Before believing any result, ask whether it is the right order of magnitude: bigger or smaller than the input, and by roughly how much. Most arithmetic mistakes survive every other check except this one.\n\nRounding first makes estimation free. Round 0.375 to 0.4, round 5/8 to 0.6, and the ratio is obviously about 2:3 — close enough to 3:5 to confirm the fraction you computed exactly. If the exact answer and the estimate disagree, you have found an input error rather than a rounding problem, and you found it in seconds.\n\nThis is also why a calculator is not a substitute for thinking about what you asked it. A tool will compute the wrong quantity perfectly, and the only defence is knowing what the answer should feel like."},{h:"Frequently asked questions"},{p:"**Is my input sent anywhere?** No. All of these run locally in your browser.\n\n**Why does 0.1 plus 0.2 not equal 0.3?** Because neither 0.1 nor 0.2 is exactly representable in binary floating point. The sum is 0.30000000000000004, which is the closest double to 0.3.\n\n**How large a factorial can these handle?** Up to 170 before exceeding the range of a double. Past that the answer is displayed in scientific notation and then stops being meaningful.\n\n**Can I use the output in code?** Yes. For the decimal-to-fraction results in particular, use integer arithmetic on the numerator and denominator rather than converting back to a decimal."},{h:"The one-line version"},{p:"Use exact fractions when money is involved, remember that factorials explode faster than you expect, and prime factorisation is both a security foundation and a fraction-simplifying trick."}]},{slug:"everyday-utility-tools",metaTitle:"13 Free Everyday Utilities: Passwords, QR Codes, Timers, Encoding",title:"13 Free Everyday Utilities: Passwords, QR Codes, Timers and Text Encoding",description:"Generate passwords, build QR codes, run timers and clocks, and decode binary, hex and cipher text — all with free browser tools that run locally, with no account required.",date:"2026-10-20",updated:"2026-10-20",readingTime:"11 min read",category:"Utility Tools",blocks:[{p:"This last group is the junk drawer. Passwords, QR codes, a stopwatch, a world clock, a coin flip, and four tools that convert text into other representations of itself. Individually trivial, collectively the stuff you need at awkward moments.\n\nThe through-line is that all thirteen run locally. For a password generator that is not a nicety — it is the entire reason the tool can be trusted at all."},{h:"Passwords: the part that actually matters"},{l:["[[password-generator|Password Generator]] — generate strong random passwords of any length and character set.","[[password-strength|Password Strength Checker]] — estimate how resistant a password is to being guessed, locally."]},{b:"The single most important fact about password strength: **length beats complexity, and reuse beats both as a danger.** A 16-character password made of unrelated words is stronger and far more typeable than a 10-character mess of symbols. Meanwhile one reused password turning up in a breach takes out every account it touches at once. Generating a distinct long password per site is the entire job."},{p:"How strength is estimated matters too. Most checkers approximate the size of the search space, which is a reasonable proxy but not the truth: `CorrectHorseBatteryStaple` scores well on entropy, while `P@ssw0rd1!` scores well on character variety and badly in practice because it appears in every cracking wordlist on earth.\n\nUse the generator for anything you care about, and if you have to remember a password, use a passphrase of four or five unrelated words. That is the specific case where memorability and strength actually overlap."},{h:"QR codes: what to put in them"},{l:["[[qr-code-generator|QR Code Generator]] — generate a QR code for a URL, text, Wi-Fi details or contact information."]},{p:"QR codes are one of those tools where the output quality is entirely determined by one decision: how much data you put in. A short URL encodes into a small, easily-scannable code. A paragraph of text with punctuation encodes into something dense and unreliable at small sizes.\n\nTwo practical rules. First, always test-scan the code at the size it will actually be printed before you print two hundred of them. Second, Wi-Fi and plain URL codes behave differently on different phones — if a code is going to a mixed audience, prefer a plain URL to a landing page that then links onward, because it works everywhere and you can change where it points."},{h:"Time: timers, clocks and the trap in timezones"},{l:["[[stopwatch|Online Stopwatch]] — a plain stopwatch, useful when your phone is in the other room.","[[pomodoro-timer|Pomodoro Timer]] — 25-minute focus blocks with breaks, for people who find that structure works.","[[world-clock|World Clock]] — current time in several cities at once."]},{p:"The world clock earns its place for one specific reason: daylight saving. Half the world's scheduling mistakes are not arithmetic errors, they are a moment where two cities were four hours apart last week and five hours apart this week, and nobody checked.\n\nBefore scheduling anything across a timezone, put both cities in the world clock and look — do not compute the offset from memory. This is also why meeting invitations should carry a timezone rather than a bare hour."},{p:"On the Pomodoro timer: the technique works for a specific kind of task — bounded, focused, uninterrupted. It does not work for debugging, where the correct move when stuck is to walk away, not to start another 25-minute block. Use it when it helps."},{h:"Randomness, honestly"},{p:"The [[random-number|Random Number Generator]] and the [[list-randomizer|List Randomizer]] cover the cases that actually come up: picking a number in a range, and putting a list into a fair order. Worth a sentence on fairness. Both use a pseudo-random generator, which for deciding who pays for lunch is indistinguishable from a real coin. For anything consequential — a draw with prizes, an allocation with money attached — you want a source you can audit, and a browser tab is not that. The value here is removing the human, who picks badly when motivated."},{h:"The encoding junk drawer"},{p:"Four tools that move text between representations. None of them are encryption, and the distinction is worth stating because it is constantly confused: an encoding is reversible by anyone and has no key. Encryption requires a key."},{l:["[[binary-text|Binary to Text]] — convert between text and its binary representation.","[[hex-text|Hex to Text]] — convert between text and hex, the representation you see most often in network tools and debuggers.","[[caesar-cipher|Caesar Cipher]] — shift letters by a fixed amount, the classic classroom cipher.","[[rot13-encoder|ROT13 Encoder]] — rotate letters by 13, a special case that is its own inverse."]},{p:"These are useful for exactly two things. First, understanding how text becomes bytes, which is the mental model you need whenever anything looks garbled. Second, actually debugging: when a payload shows up as hex, the [[hex-text|Hex to Text]] converter is how you find out what it says.\n\nThey are not useful for hiding anything. ROT13 has no key — the shift is public — so it hides nothing from anyone who knows what ROT13 is. The Caesar cipher has 25 possible shifts, which a human breaks in minute one."},{h:"The two that format things"},{l:["[[phone-formatter|Phone Number Formatter]] — normalise phone numbers into a consistent format.","[[file-size-converter|File Size Converter]] — convert between KB, MB, GB and TB, with the decimal and binary distinction explained."]},{p:"The file size converter has one genuinely valuable output: it tells you why a drive advertises a bigger number than your computer reports. Vendors sell in powers of ten, operating systems report powers of two, and the gap is about 7 percent at every scale. That is not a fault, it is two conventions."},{h:"A worked example: the garbled API response"},{p:"A webhook is failing validation and the payload in the log looks like `\\x48\\x65\\x6c\\x6c\\x6f`. This is a ninety-second diagnosis."},{l:["**1. Convert.** Paste `48656c6c6f` into the [[hex-text|Hex to Text]] converter — the result is `Hello`. It was never garbled, just encoded.","**2. Check the shape.** Something upstream is hex-encoding the payload before signing. The signature was computed over the original text and validated against the hex, so the comparison fails.","**3. Rule out the other direction.** If the log had shown readable text, the problem would have been the reverse: signing the encoded form.","**4. Confirm the size claim.** If the same log reports a 1.2 MB payload, the [[file-size-converter|File Size Converter]] settles whether that is decimal or binary before anyone argues about a quota."]},{h:"Frequently asked questions"},{p:"**Is the password generator safe if everything runs in the browser?** Yes, and more so than a server-based one: the password is generated on your machine and never transmitted, so there is nothing to intercept, log or breach. The trade-off is that you cannot recover a password you did not save.\n\n**Can I trust the virtual coin flip?** For casual decisions, yes. For anything with money or prizes attached, use a source you can audit.\n\n**Are the ciphers secure?** No. None of them. ROT13 and Caesar ciphers have no secret key and exist to teach encoding, not to protect anything.\n\n**Do these work offline?** Once a page has loaded, yes — everything is local.\n\n**Is there a limit on text length for the converters?** Only your device's memory, since nothing is sent anywhere."},{h:"The one-line version"},{p:"Long unique passwords beat short clever ones, a QR code is only as good as the data inside it, check timezone offsets rather than computing them, and encoding is not encryption."}]}];e.s(["posts",0,a],93379);var n=e.i(54575),i=e.i(89642),r=e.i(17622),t=e.i(94541),o=e.i(64591),s=e.i(31823),l=e.i(78831),d=e.i(8280),c=e.i(5852),u=e.i(31884),m=e.i(76442),h=e.i(52903),p=e.i(64534),g=e.i(20485),k=e.i(62654);let b={zh:n.default,"zh-TW":i.default,ja:r.default,ko:t.default,es:o.default,fr:s.default,de:l.default,pt:d.default,ru:c.default,ar:u.default,it:m.default,nl:h.default,tr:p.default,pl:g.default,vi:k.default},v=new Map(a.map(e=>[e.slug,e]));e.s(["getPostI18n",0,function(e,a){let n=v.get(a);if(!n)return;if("en"===e||!b[e])return n;let i=b[e]?.[a];if(!i)return n;let r=(i.blocks??n.blocks).map((e,a)=>{let i=n.blocks[a]??{};return{...e.h?{h:e.h}:i.h?{h:i.h}:{},...e.p?{p:e.p}:i.p?{p:i.p}:{},...e.b?{b:e.b}:i.b?{b:i.b}:{},...e.s?{s:e.s}:i.s?{s:i.s}:{},...e.l||i.l?{l:e.l??i.l}:{}}});return{...n,title:i.title??n.title,description:i.description??n.description,category:i.category??n.category,blocks:r}}],73519)}]);